    /**
     * The accessory chrome — glass, blur, frost and backdrops for the dock, the in-app keyboard,
     * the under-pill nav strip, the top pane, the palette and the drawer plane. The Activity keeps
     * only the view slots and the lifecycle forwarding; everything the module needs from here goes
     * through {@link ChromeRenderer.Surfaces} below. Its commit is a step of {@link #mFrames}.
     */
    private final ChromeRenderer mChrome = new ChromeRenderer(new ChromeRenderer.Surfaces() {
        @NonNull @Override public Context context() {
            return TermuxActivity.this;
        }

        @Nullable @Override public View findChromeView(int viewId) {
            return findViewById(viewId);
        }

        @Nullable @Override public TermuxAppSharedPreferences preferences() {
            return mPreferences;
        }

        @Override public int stackLookPage() {
            return TermuxActivity.this.stackLookPage();
        }

        @Override public int statusLookPage() {
            return mStatusBar.statusLookPage();
        }

        @Override public int orientation() {
            return getResources().getConfiguration().orientation;
        }

        @Override public float dpToPx(float dp) {
            return TermuxActivity.this.dpToPx(dp);
        }

        @Override public int glassBaseColor() {
            return resolveAccessoryGlassBaseColor();
        }

        @Override public int accentColor() {
            return resolveDockAccentColor();
        }

        @Override public int outlineColor() {
            return resolveAccessoryOutlineColor();
        }

        @Override public int wallpaperDimColor() {
            return resolveWallpaperBackdropDimColor();
        }

        @Override public int groundUnder(@NonNull Rect screenRect) {
            return groundUnderRect(screenRect);
        }

        @Override public int homeGround() {
            return groundOfWallPage(com.termux.app.page.PageKind.HOME);
        }

        @Override public boolean paneGlassSlabs() {
            return isTerminalPaneGlassActive();
        }

        @Override public int wallpaperHintColor() {
            return resolveWallpaperHintColor();
        }

        @Override public boolean roundedDockStyle() {
            return isRoundedStyle(com.termux.app.place.SeamDress.Surface.STATUS);
        }

        @Override public void onWindowBarFrostEdge(boolean drawsEdge) {
            if (drawsEdge == mWindowBarFrostDrawsEdge) return;
            mWindowBarFrostDrawsEdge = drawsEdge;
            // The bar's glass is dressed from this, so it is re-dressed now, not on the next pass.
            refreshTerminalWindowBar();
        }

        @Override public boolean statusBarOnDockPlank() {
            // Under a joined Docked frame the bar is on the frame's glass, which is as good as
            // the plank's: it wears no frost of its own.
            return mStatusBarOnDockPlank || frameStandsDown();
        }

        @NonNull @Override public com.termux.app.chrome.ChromeEdgeRule.TopLead topStackLead() {
            // The strip behind the system status bar is the frame's glass there; no frost of its own.
            return frameStandsDown() ? com.termux.app.chrome.ChromeEdgeRule.TopLead.NONE
                : topEdgeStackLead();
        }

        @NonNull @Override public PlaceLayout.Edge statusBarEdge() {
            return mStatusBar.statusBarEdge();
        }

        @Override public int statusBarSeamEdges() {
            return com.termux.app.chrome.LiveChromeShape.seamEdges(chromeShape(com.termux.app.place.SeamDress.Surface.STATUS),
                Collections.singletonList(com.termux.app.place.ChromeShape.PieceId.STATUS));
        }

        @Override public float statusBarRimCornerRadiusPx() {
            return mStatusBar.resolveStatusBarCapsuleCornerRadiusPx(mStatusBar.targetStatusBarHeightPx(true,
                mStatusBar.isStatusBarCompact()));
        }

        @NonNull @Override public Rect wallpaperFrameRect() {
            return getWallpaperCaptureFrameRect();
        }

        @NonNull @Override public com.termux.app.chrome.WallpaperParallax wallpaperParallax() {
            return mWallpaperParallax;
        }

        @Nullable @Override public com.termux.app.chrome.GlassRefraction.Look fancierGlassLook() {
            return mFancierGlassLook;
        }

        @Override public float planeGlassCornerRadiusPx() {
            // The planes are clipped to the terminal's own edge shape, capsule or knob.
            return terminalEdgeCornerRadiusPx();
        }

        @Override public boolean useManagedWallpaperSource() {
            return shouldUseManagedWallpaperBlurSource();
        }

        /** Fancier Glass draws the backdrop: its look carries the colour, the frames stay raw. */
        @Override public boolean glassColourOnDraw() {
            return mFancierGlassLook != null;
        }

        @Override public int systemWallpaperId() {
            return wallpaperSourceFacts().systemWallpaperId;
        }

        @NonNull @Override public java.io.File managedWallpaperExactFile() {
            return getManagedWallpaperExactFile();
        }

        @Override public long managedWallpaperLastModified() {
            return wallpaperSourceFacts().managedLastModified;
        }

        @Override public long managedWallpaperLength() {
            return wallpaperSourceFacts().managedLength;
        }

        @Nullable @Override public com.termux.app.chrome.WallpaperBlurCache.FrameCapture beginCapture(
                @NonNull Rect frameRect, @NonNull View wallpaperFrame) {
            return beginWallpaperFrameCapture(frameRect, wallpaperFrame);
        }

        @Override public boolean publishesHardwareFrames() {
            // The glass draws the frames as textures uploaded once (HardwareFrame); the switch
            // (setprop debug.tl.hw_frames 0) puts the software frames back for a comparison,
            // from the next frame the cache bakes.
            return HARDWARE_FRAMES.isOn(android.os.SystemClock.uptimeMillis());
        }

        @Override public boolean isFrameInUse(@Nullable Bitmap frame) {
            // The keyboard's own backdrop may be the shared frame itself; recycling it under the
            // keyboard crashes its next draw exactly like recycling it under a frost would.
            return frame != null
                && (frame == mInAppKeyboardBackdropBitmap || frame == mUnderKeyboardBackdropBitmap
                    || frame == mFrameGutterBackdropBitmap || frame == mControlBarFrame
                    || (mLookGlass != null && mLookGlass.holds(frame))
                    || (mDrawerCardGlass != null && mDrawerCardGlass.holds(frame))
                    || (mRaisedGlass != null && mRaisedGlass.holds(frame))
                    || isSharedWallpaperBlurFrameInUse(frame));
        }

        @Override public void onCacheCleared() {
            mPaneGlassFrame = null;
            mPaneGlassClearFrame = null;
            mWallBehindFrame = null;
            if (mLookGlass != null) mLookGlass.onCacheCleared();
            if (mDrawerCardGlass != null) mDrawerCardGlass.onCacheCleared();
            if (mRaisedGlass != null) mRaisedGlass.onCacheCleared();
            // The bar's glass is cut again from the next frame the cache bakes.
            mControlBarFrame = null;
            if (mControlBar != null) mArrangementAutosaveHandler.post(mControlBar::restyle);
        }

        @Override public boolean isActivityVisible() {
            return mIsVisible;
        }

        @Override public boolean wallpaperPassthroughEnabled() {
            return shouldUseWallpaperPassthroughMode();
        }

        @Override public int effectiveDockBlurRadiusDp() {
            return getEffectiveExtraKeysBlurRadius();
        }

        @Override public int effectiveStatusBarBlurRadiusDp() {
            return mStatusBar.getEffectiveStatusBarBlurRadius();
        }

        @NonNull @Override public ChromeSpec buildChromeSpec() {
            return TermuxActivity.this.buildChromeSpec();
        }

        @Override public void applyChromeSpec(@NonNull ChromeSpec spec) {
            TermuxActivity.this.applyChromeSpec(spec);
        }

        @Override public void enforceAccessoryFxInvariants() {
            TermuxActivity.this.enforceAccessoryFxInvariants();
        }

        @Override public void updateTerminalGlassFrost() {
            TermuxActivity.this.updateTerminalGlassFrost();
        }

        @Override public void rejudgeBandInks(
                @NonNull java.util.Set<com.termux.app.chrome.GlassBackdropCache.Band> bands) {
            if (bands.contains(com.termux.app.chrome.GlassBackdropCache.Band.KEYBOARD))
                rejudgeKeyboardGlassFaces();
        }

        @Override public boolean isBlurHealthy(@NonNull ChromeSpec spec) {
            return isAccessoryBlurHealthy(spec);
        }
    }, ChromeRenderer.newBlurWorker(), mFrames);

    /** The accessory chrome module — the one way in to glass, blur, frost and backdrop work. */
    @VisibleForTesting
    @NonNull
    ChromeRenderer getChromeRenderer() {
        return mChrome;
    }

    /** The rotation geometry pass waiting for the new layout, or null when none is pending. */
    @Nullable private OneShotPreDrawListener mPendingOrientationGeometryPass;

    /**
     * Set when accessory geometry was suppressed because the app drawer plane owns the stack's
     * transforms. Flushed by {@link #flushPendingAccessoryGeometry()} on drawer close and on every
     * {@link #onStart()} — a suppression that is never flushed freezes the dock until recreate.
     */
    private boolean mAppDrawerGeometryFreezePending;
    @Nullable private WallpaperManager.OnColorsChangedListener mWallpaperColorsChangedListener;
    private final Handler mAccessoryRenderHandler = new Handler(Looper.getMainLooper());
    /** A pause that a resume ends inside the same message: see {@link SameMessageMark}. */
    private final SameMessageMark mPausedThisMessage =
        new SameMessageMark(runnable -> mAccessoryRenderHandler.postAtFrontOfQueue(runnable));
    /** An onCreate whose launch transaction is still running; its onResume follows in it. */
    private final SameMessageMark mCreatedThisMessage =
        new SameMessageMark(runnable -> mAccessoryRenderHandler.postAtFrontOfQueue(runnable));

    @Override
    public void onCreate(Bundle savedInstanceState) {
        LifecycleTrail.activity("create", "saved=" + (savedInstanceState != null)
            + " intent=" + (getIntent() == null ? null : getIntent().getAction())
            + " home=" + (getIntent() != null && getIntent().hasCategory(Intent.CATEGORY_HOME)));
        Logger.logDebug(LOG_TAG, "onCreate");
        // The wall's pages, one store for this activity. A removal still pending from a process
        // that was killed becomes final before any owner attaches.
        wallPagesStore().flushPending();
        MotionLog.syncFromPreferences(this);
        com.termux.terminal.LatencyProbe.setDebugBuild(com.termux.BuildConfig.DEBUG);
        mIsOnResumeAfterOnCreate = true;
        mCreatedThisMessage.mark();
        if (savedInstanceState != null) {
            mIsActivityRecreated = savedInstanceState.getBoolean(ARG_ACTIVITY_RECREATED, false);
            mSetupCardsWereShowing = savedInstanceState.getBoolean(ARG_SETUP_CARDS_SHOWING, false);
            mPendingPaneLayoutState = savedInstanceState.getBundle(ARG_PANE_LAYOUT);
            mPendingWallState = savedInstanceState;
            mAppearanceHandover.take(savedInstanceState);
        } else {
            // No instance state while the process lives on: the layout the last activity left.
            mPendingPaneLayoutState = sProcessPaneLayout;
        }
        // Delete ReportInfo serialized object files from cache older than 14 days
        ReportActivity.deleteReportInfoFilesOlderThanXDays(this, 14, false);
        // Load Termux app SharedProperties from disk
        mProperties = TermuxAppSharedProperties.getProperties();
        reloadProperties();

        // Load preferences BEFORE setting theme (needed to check wallpaper preference)
        mPreferences = buildPlaceScopedPreferences(false);
        // A draft an Appearance editor session left open is dropped before anything reads the
        // look, unless a relaunch carries that session on.
        com.termux.app.surfaces.AppearanceDraft.dropUnowned(mPreferences,
            mAppearanceHandover.pending() != null);
        // Before any chrome is built: every label reads the shared Text size as it is made.
        com.termux.app.theme.TextScale.sync(mPreferences);

        // Apply wallpaper or normal theme based on preference
        setActivityThemeAndWindow();
        super.onCreate(savedInstanceState);
        sLiveActivity = new java.lang.ref.WeakReference<>(this);
        registerRotationListener();
        setContentView(R.layout.activity_termux);
        mFrames.attach(findViewById(R.id.activity_termux_root_view));
        mFrames.bind(com.termux.app.window.FrameStep.PAGE_SETTLE, this::flushLandedFrameSettle);
        mFrames.bind(com.termux.app.window.FrameStep.PAGE_FRONT, mPages::applyFront);
        mFrames.bind(com.termux.app.window.FrameStep.GEOMETRY, mGeometryHost::runBookedFrame);
        mPages.setHomeDefault(() -> mPaneWallController != null
            && mPaneWallController.goToHomePageOne(isVisible()));
        // The pages' glass lives in the glass service as long as the pages are registered, and
        // its Live pictures come from the recorder, made on the first ask.
        mPages.setGlass(mGlass);
        mGlass.setLiveSource(new com.termux.app.glass.GlassService.LiveSource() {
            @Nullable @Override
            public Object attach(@NonNull View surface, float radiusPx, int priority) {
                com.termux.app.chrome.LiveBackdrop recorder = liveBackdrop();
                if (recorder == null) return null;
                int rank = com.termux.app.chrome.LiveBackdrop.rankOf(priority);
                return recorder.attach(surface, radiusPx, rank);
            }

            @Override
            public void detach(@NonNull View surface) {
                if (mLiveBackdrop != null) mLiveBackdrop.detach(surface);
            }
        });
        // The bottom stack's writer is a step of the frame table, on the pipeline's guards.
        mStackRenderer.attach(mFrames);
        // The top stack's writer joins it: the bar's ride, the strip and the chips' slide.
        mTopStackRenderer.attach(mFrames);
        mStatusBar.bindTopStackInks();
        mRowsGuard.attach(mFrames.guards());
        mFrames.setLog((event, detail) -> {
            if (com.termux.app.chrome.MotionLog.enabled) com.termux.app.chrome.MotionLog.log(event, detail);
        });
        // Battery saver is a Live policy input: the next apply reads it and the kinds move at once.
        mGlass.watchPowerSave(this, () -> mChrome.requestSync(ChromeRenderer.SCOPE_APPLY_THIS_FRAME));
        // The tint sampler is the glass service's store of legibility corrections (ADR 0029 section 9).
        mChrome.ink().attachLegibility(mGlass.legibility());
        mChrome.ink().setMeasureFreeze(mCrossing::crossing);
        mChrome.ink().setFrontHome(() -> mPages.isCommitted(com.termux.app.page.PageKind.HOME));
        mChrome.ink().setOnWidgetPolarityChanged(() -> {
            com.termux.app.wall.WidgetPaneFrame page = mPaneWallController == null ? null
                : mPaneWallController.widgetsPage();
            if (page != null) page.post(page::redressWidgets);
        });
        View panelDecor = getWindow().getDecorView();
        com.termux.app.chrome.PanelBackdrop.install(panelDecor, mPanelBackdropSource);
        com.termux.app.glass.GlassService.install(panelDecor, mGlass);
        // The window's content root holds the shell and every overlay placed over it by absolute
        // geometry (the layout editor's frame, the hide zone, the dictation pill), so it stays left
        // to right in every locale. Reading-order overlays added here (help, tour, notices, the
        // first-run card, the Appearance editor's panel) set the locale's direction on themselves.
        View contentRoot = findViewById(android.R.id.content);
        if (contentRoot != null) contentRoot.setLayoutDirection(View.LAYOUT_DIRECTION_LTR);
        // Load termux shared preferences
        // This will also fail if TermuxConstants.TERMUX_PACKAGE_NAME does not equal applicationId
        if (mPreferences == null) {
            mPreferences = buildPlaceScopedPreferences(true);
            com.termux.app.surfaces.AppearanceDraft.dropUnowned(mPreferences,
                mAppearanceHandover.pending() != null);
            com.termux.app.theme.TextScale.sync(mPreferences);
        }
        if (mPreferences == null) {
            // An AlertDialog should have shown to kill the app, so we don't continue running activity code
            mIsInvalidState = true;
            return;
        }
        com.termux.app.wall.pageswitch.PageGlyphSource.install(mPageGlyphProvider);
        attachPageBar();
        // Before this activity builds anything that reads the catalogue: a snapshot already held
        // by the process singleton may predate an install made while no activity was listening.
        com.termux.app.launcher.data.LauncherAppDataProvider heldProvider =
            com.termux.app.launcher.data.LauncherAppDataProvider.peekInstance();
        mCatalogueHeldBeforeFirstRead = heldProvider != null && heldProvider.hasLoadedApps();
        // The chrome is dressed for the page the wall opens on from the first frame: every read of
        // Home's Style, Corners and Margin and of the layout variant follows mLastWallPage, which
        // otherwise said the Terminal until the first settle.
        mLastWallPage = com.termux.app.wall.WallRow.openingKind(
            mPendingWallState == null ? null
                : mPendingWallState.getString(com.termux.app.wall.PaneWallController.ARG_HALF),
            useAs().startIn(effectiveStartIn()));
        if (!useAs().showsHomePage())
            mLastWallPage = com.termux.app.page.PageKind.TERMINAL;
        watchStartIn();
        // Built after the preferences, and only while the Widgets place is on the wall, so a
        // terminal-only install never registers an app widget host at all — no binding, no
        // listening, no widget providers reconciled — and neither does a pane switched on under
        // a mode that keeps its place off the wall, which used to leave a host listening for a
        // page that was GONE.
        if (isWidgetsPageWanted()) {
            mWidgetHostController = new com.termux.app.launcher.widget.LauncherWidgetHostController(
                this, com.termux.app.launcher.widget.LauncherWidgetRepository.create(this,
                    widgetPageOwner()), null);
            applyWidgetGridPreference();
        }
        mPreferences.migrateTerminalMarginAdjustmentDefaultIfNeeded();
        // Every blur frame this activity captures is aligned with this value; remembering it here
        // is what lets a later styling reload tell a moved slider from any other restyle.
        mAppliedWallpaperRenderZoomPercent = effectiveWallpaperRenderZoomPercent();
        mLauncherTransitionController = new LauncherTransitionController(this, mPreferences);
        setMargins();
        setSuggestionBarView();
        mTermuxActivityRootView = findViewById(R.id.activity_termux_root_view);
        mTermuxActivityRootView.setActivity(this);
        mTermuxActivityRootView.setBottomMarginWriter(this::requestRootBottomMargin);
        // The Home pill is rechecked after each layout pass: compare-guarded, never per frame.
        mHomePillLayoutListener = mHomePill::refresh;
        mTermuxActivityRootView.getViewTreeObserver().addOnGlobalLayoutListener(mHomePillLayoutListener);
        mHomePillCoverListener = () -> {
            mHomePill.refreshIfCoversChanged();
            return true;
        };
        mTermuxActivityRootView.getViewTreeObserver().addOnPreDrawListener(mHomePillCoverListener);
        mWallpaperBackdropView = findViewById(R.id.wallpaper_backdrop);
        if (mWallpaperBackdropView != null) mWallpaperBackdropView.setParallax(mWallpaperParallax);
        View sceneContainer = findViewById(R.id.terminal_root_container);
        if (sceneContainer instanceof android.widget.FrameLayout) {
            mScene = new com.termux.app.chrome.scene.SceneController(this,
                (android.widget.FrameLayout) sceneContainer, mWallpaperBackdropView,
                new com.termux.app.chrome.scene.SceneController.Host() {
                    @NonNull @Override public java.util.List<TerminalView> paneViews() {
                        return getTerminalPaneViews();
                    }
                    @Nullable @Override public TerminalView focusedPane() {
                        return getTerminalView();
                    }
                    @Override public boolean lazyMode() {
                        return isLazyModeEnabled();
                    }
                    @Nullable @Override public com.termux.shared.termux.settings.preferences.TermuxAppSharedPreferences preferences() {
                        return mPreferences;
                    }
                });
        }
        mTermuxActivityBottomSpaceView = findViewById(R.id.activity_termux_bottom_space_view);
        mTermuxActivityRootView.setOnApplyWindowInsetsListener(new TermuxActivityRootView.WindowInsetsListener());
        View content = findViewById(android.R.id.content);
        com.termux.app.place.SystemImeAnimation.install(content, mImeRide,
            new com.termux.app.place.SystemImeAnimation.Host() {
                @Override public int laidForImePx() { return mLastDispatchedImeBottomPx; }
                @Override public void writeRide(int offsetPx) { applyDockImeOffset(offsetPx); }
                @Override public boolean suppressed() { return isSystemImeSuppressedByInAppKeyboard(); }
            });
        content.setOnApplyWindowInsetsListener((v, insets) -> {
            WindowInsetsCompat insetsCompat = WindowInsetsCompat.toWindowInsetsCompat(insets, v);
            mNavBarHeight = insetsCompat.getInsets(Type.systemBars()).bottom;
            noteRootFitBottom(insetsCompat);
            applyBottomKept(insetsCompat);
            applyAppDrawerEdgeBleed(insetsCompat);
            mImeRide.onInsets(insetsCompat.isVisible(Type.ime()));
            mMaximise.noteBars(insetsCompat.isVisible(Type.statusBars()));
            androidx.core.graphics.Insets gestures = insetsCompat.getInsets(Type.systemGestures());
            // The full-screen handle stands above Android's bottom gesture, which no app can claim.
            int mandatory = insetsCompat.getInsets(Type.mandatorySystemGestures()).bottom;
            if (mandatory != mGestureBottomPx) {
                mGestureBottomPx = mandatory;
                syncControlBarPlacement();
            }
            mMaximise.noteGestureBands(gestures.top, gestures.bottom,
                Math.round(24f * getResources().getDisplayMetrics().density));
            mImeLiftPx = computeDockImeLiftPx(insetsCompat);
            mDisplayKeys.applyDisplayImeRoom(mDisplayKeys.displayImeRoomPx(insetsCompat));
            applyTerminalOverlayInsets(insetsCompat);
            // The root consumes the insets, so the overlays after it in this frame are handed them.
            if (mSheets.homeActionsSheetIfBuilt() != null) mSheets.homeActionsSheetIfBuilt().applyInsets(insetsCompat);
            if (mSheets.terminalActionsSheetIfBuilt() != null) mSheets.terminalActionsSheetIfBuilt().applyInsets(insetsCompat);
            // The drawer plane pins itself above a system keyboard; guarded on the field so a
            // keyboard rising over the terminal never builds a drawer that was never opened.
            if (mSheets.appDrawerControllerIfBuilt() != null) {
                mSheets.appDrawerControllerIfBuilt().onImeInsetChanged(insetsCompat.isVisible(Type.ime())
                    ? insetsCompat.getInsets(Type.ime()).bottom : 0);
            }
            // Every relayout re-dispatches the insets, a wall page arrival included, and an
            // apply requested from inside that traversal lands as a second full commit before
            // the frame draws. Only an inset that moved earns one.
            long insetsSignature = insetsSignature(insetsCompat);
            if (insetsSignature != mLastAppliedInsetsSignature) {
                mLastAppliedInsetsSignature = insetsSignature;
                mChrome.requestSync(ChromeRenderer.SCOPE_APPLY_THIS_FRAME);
            }
            int imeBottomPx = insetsCompat.isVisible(Type.ime())
                ? insetsCompat.getInsets(Type.ime()).bottom : 0;
            if (imeBottomPx != mLastDispatchedImeBottomPx) {
                mLastDispatchedImeBottomPx = imeBottomPx;
                // Dispatched ahead of this traversal's measure: the grid is held from here, so
                // the window resizing for a system keyboard reflows nothing until the geometry
                // pass this books has laid the chrome out around it — one resize, not two.
                mGeometry.request(GeometryScheduler.Reason.INSETS,
                    GeometryScheduler.ResizePolicy.NOW);
            }
            return insetsCompat.toWindowInsets();
        });
        applySeamlessStatusBackgroundModeIfNeeded();
        ViewCompat.requestApplyInsets(content);
        applyFullscreenMode();
        // Must be done every time activity is created in order to registerForActivityResult,
        // Even if the logic of launching is based on user input.
        registerWallpaperActivityResultLaunchers();
        registerHelpScreenLauncher();
        mLastLaunchWasLauncherEntry = isLauncherHomeIntent(getIntent());
        setTermuxTerminalViewAndClients();
        createWidgetPaneController();
        attachHomeFloatLayer();
        landWall();
        setTerminalWindowBar();
        setTerminalToolbarView(savedInstanceState);
        syncPinnedAppsHost();
        initializeInAppKeyboard(savedInstanceState);
        // Only a fresh launch may enter adjust mode: after process death the system re-delivers
        // the original launch intent with the extra still set, which must not re-enter it.
        if (savedInstanceState == null) {
            handleInAppKeyboardHeightAdjustIntent(getIntent());
            handleSurfaceEditorIntent(getIntent());
            handleHomePagesEditorIntent(getIntent());
            handleEditModeIntent(getIntent());
            handleOpenAssistantIntent(getIntent());
            handleWallpaperStyleIntent(getIntent());
            handleEditExtraKeysIntent(getIntent());
            handleShowHelpIntent(getIntent());
            handleHelpScreenActionIntent(getIntent());
            handleShellNotificationIntent(getIntent());
        } else {
            // A rebuilt window (a theme change) takes edit mode back where the last one left it.
            reopenEditModeIfCarried();
        }
        FileReceiverActivity.updateFileReceiverActivityComponentsState(this);
        try {
            // Start the {@link TermuxService} and make it run regardless of who is bound to it
            Intent serviceIntent = new Intent(this, TermuxService.class);
            if (Build.VERSION.SDK_INT >= 26) {
                startForegroundService(serviceIntent);
            } else {
                startService(serviceIntent);
            };

            // Attempt to bind to the service, this will call the {@link #onServiceConnected(ComponentName, IBinder)}
            // callback if it succeeds.
            if (!bindService(serviceIntent, this, 0))
                throw new RuntimeException("bindService() failed");
        } catch (Exception e) {
            Logger.logStackTraceWithMessage(LOG_TAG, "TermuxActivity failed to start TermuxService", e);
            com.termux.app.notice.AppNotice.show(this, getString(e.getMessage() != null && e.getMessage().contains("app is in background") ? R.string.error_termux_service_start_failed_bg : R.string.error_termux_service_start_failed_general), true);
            mIsInvalidState = true;
            return;
        }
        // Send the {@link TermuxConstants#BROADCAST_TERMUX_OPENED} broadcast to notify apps that Termux
        // app has been opened.
        TermuxUtils.sendTermuxOpenedBroadcast(this);
        registerPreferredHomeChangeReceiver();
        // Only something that lists apps hears about packages: the catalogue behind the dock and
        // the index, the drawer, or the widget host reconciling its providers. A terminal-only
        // install registers neither listener. Kept until onDestroy, not onStop.
        if (consumesPackageChanges()) {
            registerPackageChangeReceiver();
            registerLauncherAppsCallback();
        }
        mSheets.ensureAppNoticeHost();
        if (savedInstanceState == null) {
            View contentView = findViewById(android.R.id.content);
            boolean rerunSetup = getIntent().getBooleanExtra(EXTRA_RERUN_SETUP, false);
            boolean showSetupCards = getIntent().getBooleanExtra(EXTRA_SHOW_SETUP_CARDS, false);
            String setupCardId = getIntent().getStringExtra(EXTRA_SETUP_CARD_ID);
            // The intent the post sees can be gone by then (a relaunch after a crash cleared it).
            final Intent launchIntent = getIntent();
            // Due cards hold the other first-run cards back until the post below has looked.
            setupWizard().expectCardsOffer();
            contentView.post(() -> {
                if (isFinishing() || isDestroyed()) return;
                if (showSetupCards) {
                    if (launchIntent != null) {
                        launchIntent.removeExtra(EXTRA_SHOW_SETUP_CARDS);
                        launchIntent.removeExtra(EXTRA_SETUP_CARD_ID);
                    }
                    if (!openSetupWizardIfDue()) setupWizard().openCards(setupCardId);
                    return;
                }
                if (rerunSetup) {
                    if (launchIntent != null) launchIntent.removeExtra(EXTRA_RERUN_SETUP);
                    setupWizard().open(true);
                    return;
                }
                if (openSetupWizardIfDue()) return;
                setupWizard().openCardsIfDue();
                showGlassResetNudgeIfDue();
            });
        } else {
            resumeFirstRunAfterRestart();
        }
    }

    /**
     * The setup wizard, picked back up by an activity rebuilt from a saved state.
     *
     * <p>The process can die while the wizard is up, and the activity that comes back would
     * otherwise have nothing on screen. The wizard is not stored, so it is simply offered again.
     * The card sheet after it comes back only if it was up when the state was saved: it is
     * offered on a launcher start, not on every rebuild, and a recreate the launcher asks for
     * itself (a wallpaper applied with wallpaper mode off switches the window theme) is not a
     * start. A rotation does not come through here: this activity keeps itself across one.
     */
    private void resumeFirstRunAfterRestart() {
        View contentView = findViewById(android.R.id.content);
        if (contentView == null) return;
        boolean cardsWereShowing = mSetupCardsWereShowing;
        mSetupCardsWereShowing = false;
        contentView.post(() -> {
            if (isFinishing() || isDestroyed() || mPreferences == null) return;
            if (openSetupWizardIfDue()) return;
            if (cardsWereShowing) setupWizard().openCards();
        });
    }

    /** A place is picked in Settings, so the weather needs no location permission. */
    private boolean weatherFollowsPickedPlace() {
        return mPreferences != null && !mPreferences.getStatusWidgetWeatherLocation().isEmpty();
    }

    /**
     * Gives the terminal focus back after a text field had it. Quietly: the terminal's own focus
     * listener would re-show the system keyboard 500ms later for a terminal nobody is typing into.
     */
    private void returnFocusToTerminalQuietly() {
        // Over the display window the focus is the display's: a terminal that is hidden behind
        // it must not be handed the keys the launcher keyboard types.
        if (returnFocusToDisplayWindow()) return;
        if (mTerminalView == null || mTerminalView.hasFocus()) return;
        View.OnFocusChangeListener listener = mTerminalView.getOnFocusChangeListener();
        mTerminalView.setOnFocusChangeListener(null);
        try {
            mTerminalView.requestFocus();
        } finally {
            mTerminalView.setOnFocusChangeListener(listener);
        }
    }

    /** This app's page in the system settings, where a permission refused twice is turned back on. */
    private void openAppSettingsPage() {
        try {
            startActivity(new Intent(
                android.provider.Settings.ACTION_APPLICATION_DETAILS_SETTINGS,
                android.net.Uri.fromParts("package", getPackageName(), null))
                .addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));
        } catch (android.content.ActivityNotFoundException notFound) {
            Logger.logStackTraceWithMessage(LOG_TAG, "no settings page for this package", notFound);
        }
    }

    /**
     * What the terminal is wearing, for everything the launcher draws on top of it: the notice pill
     * and the sessions drawer read the same numbers, so the two can never disagree about the radius
     * or the fill.
     */
    @NonNull
    private TerminalDress.Source terminalDressSource() {
        if (mTerminalDressSource == null) {
            mTerminalDressSource = new TerminalDress.Source() {
                @Override public float terminalCornerRadiusPx() {
                    return terminalEdgeCornerRadiusPx();
                }

                @Override public int terminalFillColor() {
                    return shouldShowTerminalOverlaySurface()
                        ? resolveTerminalSurfaceColor() : Color.TRANSPARENT;
                }
            };
        }
        return mTerminalDressSource;
    }

    @Override
    protected void onNewIntent(Intent intent) {
        super.onNewIntent(intent);
        LifecycleTrail.activity("new-intent", String.valueOf(intent == null ? null : intent.getAction()));
        setIntent(intent);
        handleInAppKeyboardHeightAdjustIntent(intent);
        handleSurfaceEditorIntent(intent);
        handleHomePagesEditorIntent(intent);
        handleEditModeIntent(intent);
        handleOpenAssistantIntent(intent);
        handleWallpaperStyleIntent(intent);
        handleEditExtraKeysIntent(intent);
        handleShowHelpIntent(intent);
        handleHelpScreenActionIntent(intent);
        handleRerunSetupIntent(intent);
        handleShowSetupCardsIntent(intent);
        handleShellNotificationIntent(intent);
        // A warm New session shortcut under Terl: a terminal window of the stack (v1 ignores it).
        if (mTilingDesktop != null && intent != null && asksForSession(intent)) openTerlTerminal();
        if (isLauncherHomeIntent(intent)) {
            mLastLaunchWasLauncherEntry = true;
        }
        if (mLauncherTransitionController != null) {
            mLauncherTransitionController.maybeHandleGestureContract(intent, mSuggestionBarView,
                getWindow().getDecorView(), isAppDrawerOpen());
        }
        if (isLauncherHomeIntent(intent)) {
            handleHomePress();
        }
    }

    /**
     * HOME means the home screen, not the home screen with something still up (ADR 0034). HOME
     * while already home never stops the activity, so this is the one exit these get that is not
     * a Back press. {@link com.termux.app.chrome.HomeExitPolicy} picks the step.
     */
    private void handleHomePress() {
        mHomeExitController.onHomePress();
    }

    /** The home press, carried out through the activity's registry and page ({@code HomeExitController}). */
    private final com.termux.app.chrome.HomeExitController mHomeExitController =
        new com.termux.app.chrome.HomeExitController(
            new com.termux.app.chrome.HomeExitController.Host() {
                @Override public boolean anyOpen() { return mOverlays.anyOpen(); }
                @Override public boolean anyHoldsUnsavedChanges() {
                    return mOverlays.anyHoldsUnsavedChanges();
                }
                @Override public boolean goesHome() { return mHomePress.goesHome(); }
                @Override public boolean reducedMotion() {
                    return ReducedMotion.isEnabled(TermuxActivity.this);
                }
                @Override public boolean launcherVisible() { return isVisible(); }
                @Override public boolean gestureNavigation() {
                    return com.termux.app.chrome.GestureNavigation.isActive(
                        TermuxActivity.this, mTermuxActivityRootView);
                }
                @Override public boolean turnsToHomePage() {
                    return mPaneWallController != null && mPaneWallController.goHomeTurnsToHomePage();
                }
                @Override @Nullable public ViewGroup landingRoot() {
                    return com.termux.app.window.WindowLayers.windowRoot(TermuxActivity.this);
                }
                @Override public void askBeforeLeaving(@NonNull Runnable leave, @NonNull Runnable stay) {
                    mOverlays.askBeforeLeaving(leave, stay);
                }
                @Override public int beginExit(@NonNull java.util.List<View> out) {
                    return mOverlays.beginExit(out);
                }
                @Override public void endExit() { mOverlays.endExit(); }
                @Override public void closeAllForHome() {
                    // Before settle(): resetTransientVisualState() stomps every dock child's
                    // alpha, scale and translation, so a drawer left open across HOME would
                    // strand faded pinned icons.
                    mOverlays.closeAll(com.termux.app.chrome.OverlayRegistry.CloseReason.HOME);
                }
                @Override public void settle(@NonNull com.termux.app.chrome.HomeExitPolicy.Step step) {
                    settleHomePress(step);
                }
            },
            new com.termux.app.chrome.HomeExit(com.termux.app.chrome.HomeExit.pipelineFrames(mFrames)));

    private void settleHomePress(@NonNull HomeExitPolicy.Step step) {
        restoreInAppKeyboardTypingClaim();
        // The tiling desktop's home press goes to Home, which is the wall's Home below.
        if (step == HomeExitPolicy.Step.GO_HOME && mTilingDesktop != null) mTilingDesktop.home();
        // A home press while the launcher is in front and nothing was open lands on the page Start
        // in names as Home, from a window or from another Home page; with something open it stays
        // on the page underneath; a return from another app finds the page it left.
        if (step == HomeExitPolicy.Step.GO_HOME && mPaneWallController != null) {
            mPaneWallController.goHome(HomeExitPolicy.animatesWall(isVisible(),
                com.termux.app.chrome.GestureNavigation.isActive(this, mTermuxActivityRootView)));
            // Home floats stay on their pages; a focused one gives the keyboard back.
            if (mPaneController != null) mPaneController.releaseHomeFloatFocus();
        }
        if (mSuggestionBarView != null) {
            mSuggestionBarView.resetTransientVisualState();
        }
        mGeometry.request(GeometryScheduler.Reason.HOME, GeometryScheduler.ResizePolicy.NONE);
        mChrome.requestSync(ChromeRenderer.SCOPE_ACCESSORY_RENDER);
    }

    @Override
    public void onStart() {
        super.onStart();
        com.termux.app.terminal.TouchDownHint.attach(this);
        if (mScene != null) mScene.attach();
        Logger.logDebug(LOG_TAG, "onStart");
    
        if (mIsInvalidState) return;
        // Clears what the removed live wallpaper left behind: a stored choice, a black lock screen.
        com.termux.app.chrome.wallpaper.WallpaperSlots.dropRetiredLiveWallpapers(this);

        // The wallpaper can have been swapped while we were stopped.
        refreshWallpaperPictureOnArrival();

        if (mWidgetHostController != null) mWidgetHostController.onStart();
        applyHomeSettings();
        if (mWidgetPaneController != null) mWidgetPaneController.onStart();
        // Pin requests (Add to home screen, Add widget) are placed on Home while it is started.
        if (mWidgetPaneController != null) {
            com.termux.app.launcher.pin.HomePinHandoff.attach(mWidgetPaneController.pinTarget());
        }

        mTerminalFrameMetricsMonitor.start(getWindow());

        mIsVisible = true;
        reclaimTerminalSessionClient();
        resetInheritedImeLayoutState();
        if (mSuggestionBarView != null) {
            mSuggestionBarView.setHostVisible(true);
            scheduleLauncherCatalogWarmup();
        }
        // The toolbar's text input page, built while the launcher is idle rather than inside the
        // first page change that shows the toolbar.
        View toolbarWarmRoot = getWindow().getDecorView();
        toolbarWarmRoot.removeCallbacks(mToolbarTextInputWarmRunnable);
        toolbarWarmRoot.postDelayed(mToolbarTextInputWarmRunnable, TOOLBAR_TEXT_INPUT_WARM_DELAY_MS);
        if (mPendingBootstrapOnStart && mTermuxService != null && mTermuxService.isTermuxSessionsEmpty()) {
            mPendingBootstrapOnStart = false;
            Intent pendingIntent = mPendingLaunchIntent;
            mPendingLaunchIntent = null;
            startBootstrapAndSession(pendingIntent);
        }

        if (mTermuxTerminalSessionActivityClient != null)
            mTermuxTerminalSessionActivityClient.onStart();
        if (mTermuxTerminalViewClient != null)
            mTermuxTerminalViewClient.onStart();
        if (mInAppKeyboard != null) {
            mInAppKeyboard.onStart();
        }
        updateWindowBackgroundForCurrentSession();
    
        if (mPreferences.isTerminalMarginAdjustmentEnabled()) {
            addTermuxActivityRootViewGlobalLayoutListener();
        }
        addAccessoryKeyboardLayoutListener();
        addAccessoryLayoutChangeListeners();
        // Unconditional: if a close threw, or the process was stopped mid-drag, the accessory
        // geometry is still frozen and the dock would stay deaf to style changes until recreate.
        flushPendingAccessoryGeometry();

        syncTerminalWallpaperRenderingMode();
        applySeamlessStatusBackgroundModeIfNeeded();
        applyTerminalSurfaceAppearance();
        // onStop() stops the stats sampler, and the only thing that starts it is
        // updateStatusWidgets(), reached solely from refreshTerminalWindowBar()'s tail — which
        // neither onStart nor onResume calls. Without this the CPU and memory readings never
        // resumed after leaving the app and coming back.
        PrivilegedBackendManager.getInstance().addAvailabilityListener(mPrivilegedAvailabilityListener);
        mStatusBar.setBatteryWindowStarted(true);
        mStatusBar.updateStatusWidgets();
        if (mControlBar != null) mControlBar.setInFront(true);
        // onStop let go of the display's surface; nothing else re-attaches it when the wall
        // already rests on the Display place, and a display whose surface is not attached takes
        // no touch and misses every setting changed while we were away.
        if (mDisplayServer.controller() != null && isDisplayWindowInFront() && !mPaneWallController.wall().isMoving()) {
            mDisplayPages.attach();
        }
        // The default home can have been changed while we were stopped.
        mDefaultHomeApp = null;
        syncRecentsVisibilityPolicy();
        mRecentsPolicySyncedSinceStart = true;
        mChrome.requestSync(ChromeRenderer.SCOPE_BLUR_HEALTH);
        registerTermuxActivityBroadcastReceiver();
        registerWallpaperColorsChangedListener();
        refreshCalendarIconsIfDayChanged();
        // What a package event heard while stopped left for the visible half of the refresh.
        if (mCatalogueUiRefreshOwed) {
            mCatalogueUiRefreshOwed = false;
            // The letters follow the catalogue; the forced pass that syncs them ran data-only.
            syncAzScrubLettersAndTint();
            scheduleSuggestionBarPackageRefresh(false, false);
        }
        refreshSuggestionBarIfLauncherCatalogChanged();
        getWindow().getDecorView().post(() -> LauncherCtlApiServer.getInstance().ensureStartedAsync(getApplicationContext()));
        // An editor left open under another activity (the Keyboard theme page it opened) is the
        // same session on the way back: restated, never closed or reverted.
        mSurfaceEditor.onActivityStarted();
    }

    /**
     * Traced as {@code Touch.dispatch}: with the frame timeline this is the touch-to-frame latency
     * of every gesture, which nothing else in a trace attributes to this app.
     */
    @Override
    public boolean dispatchTouchEvent(MotionEvent ev) {
        Trace.beginSection("Touch.dispatch");
        try {
            // A display that comes up after the user has started doing something does not pull
            // them over to it (Start in = Display).
            if (ev.getActionMasked() == MotionEvent.ACTION_DOWN) {
                mStartOnDisplayPending = false;
                // A raised control bar (full screen, #426) drops back on a touch outside it.
                if (mControlBar != null) mControlBar.onWindowTouchDown(ev.getRawX(), ev.getRawY());
            }
            // Maximised, a swipe from the top or the bottom edge is the system's (and brings the
            // row back from the top): none of it reaches the window under the edge.
            if (mTermuxActivityRootView != null && mMaximise.onWindowTouch(ev.getActionMasked(),
                ev.getY(), mTermuxActivityRootView.getRootView().getHeight())) return true;
            // A Linux window lifted with Move owns every finger until it is set down (#386).
            if (mLinuxWindows != null && mLinuxWindows.carryTouch(ev)) return true;
            // A stream that starts on the notice pill is the pill's whole: it can rest over the
            // thin status row, which would otherwise take the tap before any view sees it.
            int noticeAction = ev.getActionMasked();
            if (noticeAction == MotionEvent.ACTION_DOWN)
                mNoticePillStream = com.termux.app.notice.AppNotice.pillClaimsWindowDown(
                    this, ev.getX(), ev.getY());
            if (mNoticePillStream) {
                if (noticeAction == MotionEvent.ACTION_UP || noticeAction == MotionEvent.ACTION_CANCEL)
                    mNoticePillStream = false;
                return super.dispatchTouchEvent(ev);
            }
            // A hold on the Home pill picks it up: the surface long-press never sees that stream.
            int pillAction = ev.getActionMasked();
            if (pillAction == MotionEvent.ACTION_DOWN) mHomePillStream = homePillClaimsDown(ev);
            boolean pillStream = mHomePillStream;
            if (pillAction == MotionEvent.ACTION_UP || pillAction == MotionEvent.ACTION_CANCEL)
                mHomePillStream = false;
            // The page bar (Home's, the key's and its open popup) takes its stream whole, ahead of
            // the seam's swipe and the surface long-press.
            if (mPageBar != null && mPageBar.claimsTouch(ev)) return super.dispatchTouchEvent(ev);
            // The thin status row lies over the top pane, where the views would give its presses
            // to the pane: it takes a stream that starts on it whole, its hold included.
            com.termux.app.statusbar.StatusBarSwipeLayout statusHost = statusRowHost();
            if (statusHost != null && statusHost.dispatchWindowRowTouch(ev)) return true;
            // A stream that starts on full screen's handle is the handle's whole: the page's keyboard
            // swipe off its bottom border never takes the slide that brings the bar (round 4).
            if (pillAction == MotionEvent.ACTION_DOWN)
                mHandleStream = mControlBar != null && mControlBar.handleClaims(ev.getRawX(), ev.getRawY());
            boolean handleStream = mHandleStream;
            if (pillAction == MotionEvent.ACTION_UP || pillAction == MotionEvent.ACTION_CANCEL)
                mHandleStream = false;
            if (handleStream) return super.dispatchTouchEvent(ev);
            if (!pillStream && mSurfaceLongPress.onWindowTouch(ev)) return true;
            if (routeDockSeamTouch(ev)) return true;
            return dispatchTouchToViews(ev);
        } finally {
            Trace.endSection();
        }
    }

    /** True from a down on full screen's handle to its lift: the stream goes to the views alone. */
    private boolean mHandleStream;

    /** True from a down on the notice pill to its lift: the stream goes to the views alone. */
    private boolean mNoticePillStream;

    /** The status host, found once: every window touch asks it whether the thin row owns it. */
    @Nullable private com.termux.app.statusbar.StatusBarSwipeLayout mStatusRowHost;

    @Nullable
    private com.termux.app.statusbar.StatusBarSwipeLayout statusRowHost() {
        if (mStatusRowHost == null) {
            View host = findViewById(R.id.terminal_window_bar_host);
            if (host instanceof com.termux.app.statusbar.StatusBarSwipeLayout)
                mStatusRowHost = (com.termux.app.statusbar.StatusBarSwipeLayout) host;
        }
        return mStatusRowHost;
    }

    /**
     * True from the move where the window's border drag took a finger that landed on the dock's
     * top (the seam band, {@link com.termux.app.wall.SeamSwipe}) to its lift: the stream is the
     * wall's, and nothing of it reaches the views.
     */
    private boolean mDockSeamOwned;

    /**
     * The seam band between the window and the dock reaches into the dock's top, which the dock
     * otherwise has: every event is shown to the wall first
     * ({@link com.termux.app.wall.PaneWallLayout#dispatchDockSeamTouch}), and goes on to the views
     * as usual until the wall takes the finger by a clearly sideways start. At that move the views
     * are sent a cancel, so the dock ends its own gesture and the reactions fed from here let go,
     * and the rest of the stream is the wall's alone.
     *
     * @return whether the wall owns this event and the views are to see nothing of it
     */
    private boolean routeDockSeamTouch(@NonNull MotionEvent ev) {
        int action = ev.getActionMasked();
        if (action == MotionEvent.ACTION_DOWN) mDockSeamOwned = false;
        com.termux.app.wall.PaneWallLayout wall = mPaneWallController == null ? null
            : mPaneWallController.wall();
        boolean taken = wall != null && wall.dispatchDockSeamTouch(ev);
        if (taken && !mDockSeamOwned) {
            mDockSeamOwned = true;
            MotionEvent cancel = MotionEvent.obtain(ev);
            cancel.setAction(MotionEvent.ACTION_CANCEL);
            try {
                dispatchTouchToViews(cancel);
            } finally {
                cancel.recycle();
            }
        }
        boolean owned = mDockSeamOwned;
        if (action == MotionEvent.ACTION_UP || action == MotionEvent.ACTION_CANCEL) {
            mDockSeamOwned = false;
        }
        return owned;
    }

    /** Every touch the wall's seam has not taken, to the window's views and the feeds beside them. */
    private boolean dispatchTouchToViews(@NonNull MotionEvent ev) {
        // A finger on the A-Z pull tab is the letters' and nothing else's: the pane under the
        // tab neither tilts for it nor reads it as a tap on the terminal.
        if (ev.getActionMasked() == MotionEvent.ACTION_DOWN) {
            mAzTabTouch = mAzTabLayer != null
                && mAzTabLayer.isOnTab(ev.getRawX(), ev.getRawY());
            // The Home folder popup lives in the Home pane: a press outside the pane closes it.
            if (mWidgetPaneController != null)
                mWidgetPaneController.onWindowTouchDown(ev.getRawX(), ev.getRawY());
        }
        // Seen before any view acts on it: a tap off the dictation card's text ends its edit.
        if (mVoiceCardEdit != null)
            mVoiceCardEdit.onWindowTouch(ev.getActionMasked(), ev.getRawX(), ev.getRawY());
        if (mScene != null) mScene.onWindowTouch(ev);
        mDock.feedDockPlank(ev);
        mDock.feedDockTouchLight(ev);
        if (!mAzTabTouch) feedTerminalPlank(ev);
        if (!mAzTabTouch && touchBeganOverTerminal(ev))
            mKeybindHintPresenter.onTerminalTouch(ev);
        notifyKeybindHintPanelTouch(ev);
        return super.dispatchTouchEvent(ev);
    }

    /**
     * Whether this touch is a tap on the terminal itself. The hint presenter reads such a tap
     * while its strip is up as "the user has moved on from the chord", so a tap anywhere else must
     * never reach it: every touch used to, and the in-app keyboard's Shift cap joining a latched
     * Ctrl+Alt took the strip down and marked the chord spent, so letting Shift go again brought
     * nothing back. The keyboard is ruled out on its own as well, since the floating keyboard sits
     * over the terminal's bounds.
     */
    private boolean touchBeganOverTerminal(@NonNull MotionEvent ev) {
        if (ev.getActionMasked() != MotionEvent.ACTION_DOWN) return false;
        if (!viewContainsScreenPoint(findViewById(R.id.terminal_surface_host), ev)) return false;
        return !viewContainsScreenPoint(findViewById(R.id.inapp_keyboard_container), ev);
    }

    private static boolean viewContainsScreenPoint(@Nullable View view, @NonNull MotionEvent ev) {
        return viewContainsScreenPoint(view, ev.getRawX(), ev.getRawY());
    }

    private static boolean viewContainsScreenPoint(@Nullable View view, float x, float y) {
        if (view == null || !view.isShown()) return false;
        int[] location = new int[2];
        view.getLocationOnScreen(location);
        return x >= location[0] && x < location[0] + view.getWidth()
            && y >= location[1] && y < location[1] + view.getHeight();
    }

    @Override
    public void onResume() {
        super.onResume();
        // Back after a trim: a policy event, so the Live kinds return at once.
        mGlass.setMemoryShort(false);
        mHomePress.onResume();
        if (mFirstRunTips != null && mControlBar != null) {
            mControlBar.view().post(() -> { if (mFirstRunTips != null) mFirstRunTips.refresh(); });
        }
        Logger.logVerbose(LOG_TAG, "onResume");
        mHomePill.refresh();
        refreshPageGlyphs();
        // A flip while stopped found the overlays closed already; this records the new look.
        closeOverlaysIfThemeMoved();
        // Text left waiting in the pill holds the screen again, its idle release started over.
        mVoiceScreenMayHold = true;
        holdVoiceScreen();
        if (mIsInvalidState)
            return;
        // A setting saved while away (launcherctl config) refreshes now; a field write otherwise.
        LauncherSettings.onLauncherResumed(mSettingsScreen);
        // The frost under a keyboard over the display was let go at pause; a pass makes it again.
        if (isInAppKeyboardShown() && inAppKeyboardSeesThroughToDisplay())
            mChrome.requestSync(ChromeRenderer.SCOPE_APPLY_THIS_FRAME);
        reopenAppearanceAfterRelaunch();
        View nudgeContent = findViewById(android.R.id.content);
        if (nudgeContent != null && com.termux.app.setup.GlassResetNudgeCard.isDue(mPreferences))
            nudgeContent.post(this::showGlassResetNudgeIfDue);
        if (nudgeContent != null && com.termux.app.setup.AppearanceResetCard.isDue(mPreferences))
            nudgeContent.post(this::showAppearanceResetCardIfDue);
        // A permission page the setup cards sent the person to may have been answered.
        if (mSetupWizard != null) mSetupWizard.onActivityResumed();
        // A distro installed in a shell while we were away still needs its sound drop-in.
        if (com.termux.BuildConfig.X11_SERVER) {
            com.termux.app.sound.LauncherSound.get(this).onContainersMaybeChanged();
        }
        // A return hold opened by the stop starts waiting for a settled frame (focus held, no
        // layout pending); window focus arriving later keeps this wait and asks for that frame.
        armReturnWait();
        // A new intent to the resumed launcher (HOME while home; a second start racing a cold
        // start) pauses and resumes it inside one message. Nothing can have changed in between,
        // so the passes below that re-read preferences and re-dress the chrome "in case they
        // changed while we were away" are skipped for it; everything that pairs with onPause,
        // and the prefix checks a shell can change without a broadcast, still run. A Settings
        // reload waiting for this resume always takes the full path.
        boolean transientPause = mPausedThisMessage.isMarked()
            && !sPendingStyleReloadOnNextResume && !sPendingAppDrawerReloadOnNextResume;
        // The launch's own resume: the keyboard was built from the preferences moments ago in
        // this same message, tap model and layout ring included, so re-reading them all (17 ms
        // on a cold start, the tap model file a second time) has nothing to find.
        boolean keyboardJustBuilt = mCreatedThisMessage.isMarked();
        // Also here, not only in onStart: a wallpaper picker shown over this activity never stops
        // it, so the arrival back from one is an onResume on its own.
        refreshWallpaperPictureOnArrival();
        com.termux.app.chrome.wallpaper.WallpaperSlots.dropRetiredLiveWallpapers(this);
        redressChromeAfterFirstLayout();
        // The DISPLAY opt-in can have been flipped in Settings while we were away.
        syncDisplayEnvironment();
        // `pkg install xkeyboard-config` in a shell leaves no broadcast behind either, so the
        // display window's empty state re-reads the prefix itself rather than staying stuck on
        // whatever it last said.
        refreshDisplayEmptyStateReadiness();
        // `pkg install` leaves no broadcast behind: the drawer's Linux apps are re-read when the
        // prefix's desktop files have changed since they were last listed.
        refreshLinuxApps(false);
        // Terminal hierarchy actions from launcherctl/agent/MCP need a foreground
        // Activity; they answer 409 activity_not_running while nothing is attached.
        com.termux.app.terminal.TerminalActionDispatcher.getInstance().attach(terminalHost());
        // The last insets snapshot can be from mid-transition out of the previous app (IME still
        // up, nav bars reported hidden) and there is no later dispatch to correct it — a stale
        // lift here renders the dock and keyboard in the top third of the screen. Drop it and
        // ask for a fresh pass.
        resetInheritedImeLayoutState();
        View contentView = findViewById(android.R.id.content);
        if (contentView != null)
            androidx.core.view.ViewCompat.requestApplyInsets(contentView);
        // Preferences may have changed while the settings activity covered this one.
        if (!transientPause) initializeInAppKeyboard(null);
        mDisplayKeys.syncDisplayKeyboardRoute();
        if (mInAppKeyboard != null) {
            if (!transientPause && !keyboardJustBuilt) mInAppKeyboard.onPreferencesReloaded();
            mInAppKeyboard.onResume();
            if (mInAppKeyboard.isExternalTextInputActive())
                onSystemImeRequested();
        }
        if (sPendingStyleReloadOnNextResume) {
            boolean recreateActivity = consumePendingStyleReloadRecreateActivity();
            reloadActivityStyling(recreateActivity);
            return;
        }
        // A display started from a shell while we were away announced itself to nobody.
        claimKeptDisplay();
        if (sPendingAppDrawerReloadOnNextResume) {
            sPendingAppDrawerReloadOnNextResume = false;
            if (mSheets.appDrawerControllerIfBuilt() != null) mSheets.appDrawerControllerIfBuilt().onPreferencesReloaded();
        }
        if (mTermuxTerminalSessionActivityClient != null)
            mTermuxTerminalSessionActivityClient.onResume();
        if (mTermuxTerminalSessionActivityClient != null)
            mTermuxTerminalSessionActivityClient.refreshMaterialTerminalColorsIfNeeded();
        if (mTermuxTerminalSessionActivityClient != null)
            mTermuxTerminalSessionActivityClient.applyClipboardCleanupPreference();
        if (mTermuxTerminalViewClient != null)
            mTermuxTerminalViewClient.onResume();
        refreshLauncherIconsIfPreferencesChanged();
        if (!transientPause) {
            // If compatibility mode was just enabled, drop any active split back to a single pane.
            if (!isSplitPanesEnabled())
                collapseAllSplits();
            else if (mPaneController != null) {
                refreshPaneSizesOnReturn();
                // Settings may have flipped the pane behaviour toggles while we were away.
                applyPaneBehaviourPreferences();
            }
            refreshTerminalWindowBar();

            updateWindowBackgroundForCurrentSession();
            syncTerminalWallpaperRenderingMode();
            applySeamlessStatusBackgroundModeIfNeeded();
            applyTerminalSurfaceAppearance();
            // Once per visible pass: onStart has just done it on an arrival. A resume with no
            // start before it (a dialog such as the home-role request shown over us) re-reads.
            if (mRecentsPolicySyncedSinceStart) {
                mRecentsPolicySyncedSinceStart = false;
            } else {
                mDefaultHomeApp = null;
                syncRecentsVisibilityPolicy();
            }
            applyWallpaperOffsetFixIfNeeded();
            mChrome.requestSync(ChromeRenderer.SCOPE_BACKDROPS
                | ChromeRenderer.SCOPE_ACCESSORY_RENDER | ChromeRenderer.SCOPE_BLUR_HEALTH);
        }
        refreshPrivilegedBackendIfNeeded();
        if (mSuggestionBarView != null) {
            mSuggestionBarView.post(this::updateAzOverflowAffordance);
        }

        // The row card, for the update that has no first-run chain to hang it off.
        maybeOfferExtraKeysDefaultRow();

        // Check if a crash happened on last run of the app or if a plugin crashed and show a
        // notification with the crash details if it did
        TermuxCrashUtils.notifyAppCrashFromCrashLogFile(this, LOG_TAG);
        mIsOnResumeAfterOnCreate = false;
    }

    @Nullable private com.termux.app.setup.SetupWizardController mSetupWizard;

    private com.termux.app.setup.SetupWizardController setupWizard() {
        if (mSetupWizard == null) {
            mSetupWizard = new com.termux.app.setup.SetupWizardController(
                new com.termux.app.setup.SetupWizardController.Host() {
                    @Override public android.content.Context context() {
                        return TermuxActivity.this;
                    }
                    @Override public <T extends View> T findView(int id) {
                        return TermuxActivity.this.findViewById(id);
                    }
                    @Override public void holdPaneWall(boolean held) {
                        if (mPaneWallController != null)
                            mPaneWallController.setGesturesEnabled(!held);
                    }
                    @Override public int statusBarInsetTop() {
                        return mLastStatusBarInsetTop;
                    }
                    @Override public com.termux.shared.termux.settings.preferences
                        .TermuxAppSharedPreferences preferences() {
                        return mPreferences;
                    }
                    @Override public void openWallpaperPicker() {
                        openWallpaperPickerForSetup();
                    }
                    @Override public void requestNotificationPermission() {
                        androidx.core.app.ActivityCompat.requestPermissions(TermuxActivity.this,
                            new String[] {android.Manifest.permission.POST_NOTIFICATIONS},
                            REQUEST_CODE_SETUP_NOTIFICATIONS);
                    }
                    @Override public void requestWallpaperRead() {
                        // The same request the first-run wallpaper card makes.
                        if (mPreferences != null)
                            mPreferences.setWallpaperReadPermissionPrompted(true);
                        androidx.core.app.ActivityCompat.requestPermissions(TermuxActivity.this,
                            new String[] {android.Manifest.permission.READ_EXTERNAL_STORAGE},
                            REQUEST_CODE_WALLPAPER_READ_PERMISSION);
                    }
                    @Override public boolean isAppearanceEditorOpen() {
                        return mAppearance.isOpen();
                    }
                });
        }
        return mSetupWizard;
    }

    /** The wizard's wallpaper picker, or a photo pick it started, is on screen. */
    private boolean mSetupPickerPhotoTrip;

    /**
     * The wizard's Set an in-app wallpaper: the Appearance surface opens on the wallpaper picker.
     * When the surface closes (and no photo pick is under way) the wizard comes back.
     */
    private void openWallpaperPickerForSetup() {
        mAppearanceFromSettings = false;
        mOverviewRestore = null;
        resumeWallpaper(null);
    }

    /** Brings the wizard back from the picker once nothing of the picker trip is still running. */
    private void resumeSetupWizardAfterPicker() {
        if (mSetupWizard == null || !mSetupWizard.isSuspended() || mSetupPickerPhotoTrip) return;
        View root = findViewById(R.id.activity_termux_root_view);
        Runnable resume = () -> {
            if (mSetupWizard != null && !mAppearance.isOpen()) mSetupWizard.resumeFromPicker();
        };
        if (root != null) root.post(resume);
        else resume.run();
    }

    /**
     * The upgrade nudge (appearance overhaul §6), once it is due: only on a Home page, after the
     * setup wizard and its cards, never over a terminal; else it waits for the next resume.
     */
    private void showGlassResetNudgeIfDue() {
        if (isFinishing() || isDestroyed() || mPreferences == null) return;
        if (!com.termux.app.setup.GlassResetNudgeCard.isDue(mPreferences)) return;
        if (setupWizardComesFirst()) return;
        if (mSetupWizard != null && mSetupWizard.isCardSheetShowing()) return;
        if (currentWallPage() != com.termux.app.page.PageKind.HOME) return;
        com.termux.app.setup.GlassResetNudgeCard.showIfDue(this, mPreferences, () -> {
            // Mode back to System, then the window restyled for the new glass and colours.
            String mode = com.termux.app.surfaces.GlassReset.NIGHT_MODE_DEFAULT;
            if (mProperties == null || !mode.equals(mProperties.getNightMode()))
                com.termux.app.settings.TermuxPropertiesFile.write(
                    com.termux.shared.termux.settings.properties.TermuxPropertyConstants
                        .KEY_NIGHT_MODE, mode);
            recreate();
        });
    }

    /**
     * The card after an appearance reset on upgrade, once it is due: on a Home page, after the
     * setup wizard and its cards, never over a terminal; else it waits for the next resume.
     */
    private void showAppearanceResetCardIfDue() {
        if (isFinishing() || isDestroyed() || mPreferences == null) return;
        if (!com.termux.app.setup.AppearanceResetCard.isDue(mPreferences)) return;
        if (setupWizardComesFirst()) return;
        if (mSetupWizard != null && mSetupWizard.isCardSheetShowing()) return;
        if (currentWallPage() != com.termux.app.page.PageKind.HOME) return;
        com.termux.app.setup.AppearanceResetCard.showIfDue(this, mPreferences,
            this::openAppearanceSurface);
    }

    /**
     * The wizard is due or up, or its cards are up or will open in this session: the other
     * first-run cards wait until they are done. Cards that will only open on a later start hold
     * nothing back.
     */
    private boolean setupWizardComesFirst() {
        boolean wizardDue = mPreferences != null && com.termux.app.setup.SetupWizardGate.decide(
            mPreferences.getSetupWizardVersion(), false, false).show;
        com.termux.app.setup.SetupWizardController wizard = mSetupWizard;
        boolean offerPending = wizard != null && wizard.isCardsOfferPending();
        // The due check reads the phone, so it runs only while an offer is still to come.
        return com.termux.app.setup.SetupWizardGate.comesFirst(wizardDue,
            wizard != null && wizard.isOpen(), offerPending && wizard.isCardSheetDue(),
            offerPending);
    }

    /**
     * Opens the setup wizard when its version has not been finished; true when it is up, or due
     * and waiting for the bootstrap install to end (it then opens by itself).
     */
    private boolean openSetupWizardIfDue() {
        if (mPreferences == null) return false;
        com.termux.app.setup.SetupWizardGate.Decision decision =
            com.termux.app.setup.SetupWizardGate.decide(mPreferences.getSetupWizardVersion(),
                mPreferences.getFirstBootTourCompletedVersion() >= 1,
                mPreferences.isUseAsStored(),
                mPreferences.isWallpaperReadPermissionPrompted());
        if (!decision.show) return false;
        View content = findViewById(android.R.id.content);
        if (content != null && com.termux.app.setup.SetupWizardGate.waitsForBootstrap(
                TermuxInstaller.isBootstrapInstalled(), mBootstrapSettled)) {
            if (!mSetupWizardAwaitsBootstrap) {
                mSetupWizardAwaitsBootstrap = true;
                content.postDelayed(mSetupWizardBootstrapBackstop,
                    SETUP_WIZARD_BOOTSTRAP_BACKSTOP_MS);
            }
            return true;
        }
        setupWizard().migrateFromOldTourIfDue(decision);
        setupWizard().open(decision.updater);
        return true;
    }

    /** A bootstrap install this activity started is running. */
    private boolean mBootstrapInstalling;
    /** The wizard no longer waits for the bootstrap: an install ended, or none was needed or came. */
    private boolean mBootstrapSettled;
    /** The wizard is due and opens once the bootstrap install has ended. */
    private boolean mSetupWizardAwaitsBootstrap;
    /**
     * How long a waiting wizard gives the bootstrap install to start. A running install always
     * ends in {@link #onBootstrapSettled}; with none running by then, the wizard opens anyway.
     */
    private static final long SETUP_WIZARD_BOOTSTRAP_BACKSTOP_MS = 10_000L;
    private final Runnable mSetupWizardBootstrapBackstop = () -> {
        if (mSetupWizardAwaitsBootstrap && !mBootstrapInstalling) onBootstrapSettled();
    };

    /** The bootstrap install ended (installed or failed) or none ran: a waiting wizard opens. */
    private void onBootstrapSettled() {
        mBootstrapInstalling = false;
        mBootstrapSettled = true;
        if (!mSetupWizardAwaitsBootstrap) return;
        mSetupWizardAwaitsBootstrap = false;
        View content = findViewById(android.R.id.content);
        if (content != null) content.removeCallbacks(mSetupWizardBootstrapBackstop);
        if (isFinishing() || isDestroyed()) return;
        openSetupWizardIfDue();
    }

    /** Settings asking for the setup cards, on the launcher that is already up. */
    private void handleShowSetupCardsIntent(@Nullable Intent intent) {
        if (intent == null || !intent.getBooleanExtra(EXTRA_SHOW_SETUP_CARDS, false)) return;
        intent.removeExtra(EXTRA_SHOW_SETUP_CARDS);
        String setupCardId = intent.getStringExtra(EXTRA_SETUP_CARD_ID);
        intent.removeExtra(EXTRA_SETUP_CARD_ID);
        View contentView = findViewById(android.R.id.content);
        if (contentView == null) return;
        contentView.post(() -> {
            if (!openSetupWizardIfDue()) setupWizard().openCards(setupCardId);
        });
    }

    /** Settings asking for the setup wizard again, on the launcher that is already up. */
    private void handleRerunSetupIntent(@Nullable Intent intent) {
        if (intent == null || !intent.getBooleanExtra(EXTRA_RERUN_SETUP, false)) return;
        intent.removeExtra(EXTRA_RERUN_SETUP);
        View contentView = findViewById(android.R.id.content);
        if (contentView == null) return;
        contentView.post(() -> setupWizard().open(true));
    }

    /**
     * The one-time card asking someone who has a key row of their own whether to take this
     * release's row.
     *
     * <p>A value for {@code extra-keys} in the user's properties file replaces the shipped row for
     * good, so an update's new keys would never reach anyone who had ever edited theirs. They are
     * asked once, and only if the row they have is not already the shipped one; a fresh install
     * sets no such value and is never asked. The answer is remembered either way, back button
     * included. The card waits while the first-launch run is going or still to be offered, and is
     * looked at again on the way back in, so the two are never up together.
     */
    private void maybeOfferExtraKeysDefaultRow() {
        if (mExtraKeysDefaultOfferShowing || mPreferences == null) return;
        if (setupWizardComesFirst()) return;
        if (isFinishing() || isDestroyed()) return;
        // Cheapest check first: once answered, nothing else is read on any later resume.
        if (mPreferences.isExtraKeysDefaultOffered()) return;
        java.util.Properties properties = com.termux.app.settings.TermuxPropertiesFile.load(this);
        String pageOne = properties.getProperty(
            com.termux.shared.termux.settings.properties.TermuxPropertyConstants.KEY_EXTRA_KEYS);
        if (!ExtraKeysDefaultOffer.isCustomRow(pageOne)) {
            // Nothing to offer: they already have the shipped row. Remember that, so a fresh
            // install never reads the properties file for this again.
            mPreferences.setExtraKeysDefaultOffered(true);
            return;
        }
        if (!ExtraKeysDefaultOffer.shouldOffer(pageOne, false, false)) return;
        String pageTwo = properties.getProperty(
            com.termux.shared.termux.settings.properties.TermuxPropertyConstants.KEY_EXTRA_KEYS2);
        mExtraKeysDefaultOfferShowing = true;
        AlertDialog dialog = new MaterialAlertDialogBuilder(this)
            .setCustomTitle(extraKeysDefaultOfferTitle())
            .setMessage(R.string.extra_keys_default_offer_message)
            .setNegativeButton(R.string.extra_keys_default_offer_keep, null)
            .setPositiveButton(R.string.extra_keys_default_offer_switch,
                (d, which) -> takeDefaultExtraKeysRow(pageOne, pageTwo))
            .create();
        dialog.setOnDismissListener(d -> {
            mExtraKeysDefaultOfferShowing = false;
            // Answered is answered, back button and a tap outside included — but a card taken off
            // the screen by a rotation or by the user leaving was never answered, and comes back.
            if (isFinishing() || isDestroyed() || isChangingConfigurations()) return;
            if (mPreferences != null) mPreferences.setExtraKeysDefaultOffered(true);
        });
        dialog.show();
    }

    /** The card's heading: the launcher's name over one short title, the way its cards read. */
    @NonNull
    private View extraKeysDefaultOfferTitle() {
        float density = getResources().getDisplayMetrics().density;
        LinearLayout title = new LinearLayout(this);
        title.setOrientation(LinearLayout.VERTICAL);
        title.setPadding((int) (24 * density), (int) (20 * density), (int) (24 * density), 0);
        TextView kicker = new TextView(this);
        kicker.setText(R.string.extra_keys_default_offer_kicker);
        kicker.setTextSize(android.util.TypedValue.COMPLEX_UNIT_SP, 12f);
        kicker.setAllCaps(true);
        kicker.setLetterSpacing(0.08f);
        kicker.setTextColor(MaterialColors.getColor(this,
            androidx.appcompat.R.attr.colorPrimary, Color.WHITE));
        TextView heading = new TextView(this);
        heading.setText(R.string.extra_keys_default_offer_title);
        heading.setTextSize(android.util.TypedValue.COMPLEX_UNIT_SP, 20f);
        heading.setPadding(0, (int) (4 * density), 0, 0);
        heading.setTextColor(MaterialColors.getColor(this,
            com.google.android.material.R.attr.colorOnSurface, Color.WHITE));
        title.addView(kicker);
        title.addView(heading);
        return title;
    }

    /**
     * Takes the shipped row, keeping what the user had so the editor can offer it back under
     * Presets. The write and the restyle are the editor's own Save path, so the row on screen
     * changes at once while the launcher is in front.
     */
    private void takeDefaultExtraKeysRow(@Nullable String previousPageOne,
                                         @Nullable String previousPageTwo) {
        if (mPreferences != null) {
            mPreferences.setExtraKeysDefaultOffered(true);
            // Only a row of their own is worth keeping: once the shipped row is on file,
            // saving it as "Before the update" would lose the row the first tap kept.
            if (ExtraKeysDefaultOffer.isCustomRow(previousPageOne)) {
                mPreferences.setPreviousExtraKeys(0,
                    previousPageOne == null ? "" : previousPageOne.trim());
                mPreferences.setPreviousExtraKeys(1,
                    previousPageTwo == null ? "" : previousPageTwo.trim());
            }
        }
        for (int page = 0; page < TermuxTerminalExtraKeys.PAGE_PROPERTY_KEYS.length
            && page < TermuxTerminalExtraKeys.PAGE_DEFAULT_VALUES.length; page++) {
            com.termux.app.settings.TermuxPropertiesFile.write(
                TermuxTerminalExtraKeys.PAGE_PROPERTY_KEYS[page],
                TermuxTerminalExtraKeys.PAGE_DEFAULT_VALUES[page]);
        }
        requestTermuxActivityStylingOnNextResume(this, false);
        AppNotice.show(this, R.string.extra_keys_default_offer_switched);
    }

    @Override
    protected void onPause() {
        LauncherSettings.onLauncherPaused();
        if (mTilingDesktop != null) mTilingDesktop.onPause();
        if (mLinuxWindows != null) mLinuxWindows.cancelCarry();
        mStatusRow.endMarksTouch();
        if (mPageBar != null) mPageBar.close();
        cancelReturnWait();
        endHomePillFlight();
        // A home press's landing held behind a frame with no pages settles and shows now.
        mHomeExitController.onPause();
        // A landing still waiting for its post lands before the screen goes.
        flushLandedFrameSettle();
        // The frost under a keyboard over the display goes with the screen; onResume's pass
        // makes it again.
        releaseKeyboardFrost();
        if (mTermuxTerminalSessionActivityClient != null)
            mTermuxTerminalSessionActivityClient.onPause();
        dismissHelpOverlay();
        // An edit of the dictation card's text is kept and its typing handed back, before the
        // microphone closes below and the text settles with it.
        endVoiceEdit();
        // The microphone is only ever open while this activity is the one on screen; what was
        // said stays in the panel, waiting for the user to come back to it.
        endVoiceInput(VoiceInputSession.EndReason.PAUSED);
        // Nobody is looking at the pill now; the screen may sleep. onResume takes the hold back.
        mVoiceScreenMayHold = false;
        mVoiceScreenHold.release();
        // Nothing is typed into a display nobody is looking at.
        mDisplayKeys.hideDisplaySystemKeyboard();
        // Rename owns the in-app-keyboard interceptor only while this activity is visible.
        mSheets.folderRenameController().onActivityPaused();
        if (mRenameCoordinator != null) mRenameCoordinator.onActivityPaused();
        // Same rule for the find strip: it holds the interceptor and paints over a pane, and both
        // must be handed back before this activity stops being the one on screen.
        if (mFindCoordinator != null) mFindCoordinator.cancel();
        mPausedThisMessage.mark();
        super.onPause();
    }

    /**
     * Dresses the whole chrome from the current state, the way the first pass after a launch does.
     * Everything a pass decides and remembers is dropped first — the ink's polarity and samples,
     * the panes' applied style (the veil is not part of its key) and the crops — so a change that
     * moves every surface at once, the Style, cannot leave an answer from before it standing.
     */
    /**
     * The first dress runs before the chrome has been laid out, so glass recorded then is aimed at
     * where nothing stands yet and keeps that aim until something re-records it. Dress once more
     * after the first layout, the same way leaving an editor does, so a cold start and a session
     * that has been through an editor wear the same chrome.
     */
    private void redressChromeAfterFirstLayout() {
        if (mFirstLayoutRedressed) return;
        View root = findViewById(R.id.activity_termux_root_view);
        if (root == null) return;
        mFirstLayoutRedressed = true;
        root.getViewTreeObserver().addOnGlobalLayoutListener(
            new android.view.ViewTreeObserver.OnGlobalLayoutListener() {
                @Override public void onGlobalLayout() {
                    root.getViewTreeObserver().removeOnGlobalLayoutListener(this);
                    root.post(TermuxActivity.this::redressChromeFromState);
                }
            });
    }

    private boolean mFirstLayoutRedressed;

    /**
     * Mist's opacity depends on whether its glass is light (SurfacePresets.followGlassTheme): on
     * the pass a theme, scheme or wallpaper-mode change runs through, a store on the shipped Mist
     * takes this glass's value. A write is re-dressed whole after this pass, as a Look is.
     */
    private void followLooksGlassTheme() {
        if (mPreferences == null) return;
        boolean light = com.termux.app.chrome.GlassLook.isLightGlass(resolveAccessoryGlassBaseColor());
        if (com.termux.app.surfaces.SurfacePresets.followGlassTheme(mPreferences, light))
            getWindow().getDecorView().post(this::redressChromeFromState);
    }

    private void redressChromeFromState() {
        redressChromeFromState(true);
    }

    /**
     * @param redressPanes whether the panes and pages are dressed again whatever their style key
     *                     says (the editor's Undo, a Look, a Style). A landing's half re-dress
     *                     passes false: the panes are dressed again only where their own style
     *                     moved, so a landing between halves that differ only in the dock's look
     *                     or the bar's Margin does not rebuild the terminal pane's glass, which
     *                     drew its text blurred for a few frames after the landing.
     */
    private void redressChromeFromState(boolean redressPanes) {
        if (mPreferences == null || mChrome == null) return;
        if (redressPanes) mAppliedPaneStyleKey = null;
        // A redress after the editor (Undo, a Look, a Style) or at a settle between halves
        // (restyleChromeForHalfIfChanged): the grid's rim is Home's Margin as it stands now.
        pushHomeMarginToWidgetGrid(true);
        mChrome.redressFromState();
        applyTerminalSurfaceAppearance();
        updateTerminalGlassFrost();
    }

    private void applyTerminalSurfaceAppearance() {
        if (mPreferences == null) {
            return;
        }
        View terminalSurfaceHost = findViewById(R.id.terminal_surface_host);
        View terminalBodySurface = findViewById(R.id.terminal_background);
        View terminalStatusSurface = findViewById(R.id.terminal_status_bar_background);
        View terminalView = findViewById(R.id.terminal_view);
        if (terminalSurfaceHost == null || terminalBodySurface == null || terminalStatusSurface == null) {
            return;
        }
        boolean wallpaperMode = shouldUseWallpaperPassthroughMode();
        int accessoryBaseColor = resolveAccessoryGlassBaseColor();
        // The dock plank's tint is deliberately NOT painted here. This pass used to flat-colour it
        // opaque and leave the re-glazing to the chrome apply every caller made straight
        // afterwards — until the content view's insets listener stopped asking for one when the
        // insets had not moved. Every relayout re-dispatches the same insets, so any of them now
        // reaches this pass with no apply behind it: the plank is painted one solid colour over its
        // own blurred backdrop and stays that way, while the keyboard below it — painted by
        // applyInAppKeyboardSurfaceState — stays glass. doApplyChromeSpec owns extrakeys_background
        // and builds it from the glass model; nothing else may write it.
        applyGlassSurfaceColor(R.id.activity_termux_bottom_space_background, accessoryBaseColor);

        if (wallpaperMode) {
            boolean showSurface = shouldShowTerminalOverlaySurface();
            int terminalSurfaceColor = showSurface ? resolveTerminalSurfaceColor() : Color.TRANSPARENT;
            int wallpaperDim = resolveWallpaperBackdropDimColor();
            boolean glassPane = isTerminalPaneGlassActive();
            // With glass on, the terminal tint lives on each pane's own slab (a Floating card's, or
            // the Docked insert's), so the root carries only the wallpaper dim and the gaps between
            // and around the panes show the wallpaper, or under Docked the frame glass, at whatever
            // opacity the Wallpaper control asks for. Without it the tint is folded into the dim.
            // Settled before the panes are dressed: they read this colour for their corner arcs.
            // Page-chrome C: each page paints its own ground on the ground strip (Home its dim
            // alone, the Terminal page this fold), so the root carries none and the backdrop
            // frame wears none of its own. mWallGroundColor stays the Terminal page's ground.
            mWallGroundColor = com.termux.app.terminal.TerminalSurfacePolicy.wallGround(glassPane,
                terminalSurfaceColor, wallpaperDim);
            mWallGroundPainted = true;
            mGroundGlassPane = glassPane;
            mGroundCanvasTint = terminalSurfaceColor;
            applyUnifiedBackgroundDim(Color.TRANSPARENT);
            refreshGroundStrip();
            applyTerminalBorderAppearance();
            terminalSurfaceHost.setBackgroundColor(Color.TRANSPARENT);
            applyTerminalBodySurface(terminalBodySurface, Color.TRANSPARENT, false);
            applyFrameGutterGlass(frameGlassHost(), glassPane && hasDockedFrameCard());
            terminalStatusSurface.setBackgroundColor(Color.TRANSPARENT);
            terminalStatusSurface.setVisibility(View.GONE);
            if (terminalView != null) {
                terminalView.setBackgroundColor(Color.TRANSPARENT);
                if (terminalView instanceof TerminalView) {
                    ((TerminalView) terminalView).setTransparentFrameOverlayColor(Color.TRANSPARENT);
                }
            }
            applyTerminalStatusBarSurfaceColor(showSurface, terminalSurfaceColor);
            applyTerminalWindowBarBackdropInsets();
            redressKeyboardForStyle();
            return;
        }

        // Opaque (non-wallpaper) mode keeps the bounded terminal surface; no full-screen dim needed.
        applyFrameGutterGlass(frameGlassHost(), false);
        applyUnifiedBackgroundDim(Color.TRANSPARENT);
        refreshGroundStrip();   // hides the strip: opaque mode keeps the terminal's own surface
        boolean showSurface = true;
        int terminalSurfaceColor = resolveTerminalSurfaceColor();
        // Behind the wall here is the terminal surface over the window's base colour.
        mWallGroundColor = androidx.core.graphics.ColorUtils.compositeColors(terminalSurfaceColor,
            getTermuxThemeColor(com.termux.shared.R.attr.termuxColorSurfaceBase,
                R.color.termux_surface_base));
        mWallGroundPainted = true;
        applyTerminalBorderAppearance();
        terminalSurfaceHost.setBackgroundColor(Color.TRANSPARENT);
        applyTerminalBodySurface(terminalBodySurface, terminalSurfaceColor,
            showSurface && Color.alpha(terminalSurfaceColor) > 0);
        terminalStatusSurface.setBackgroundColor(terminalSurfaceColor);
        terminalStatusSurface.setVisibility(shouldShowTerminalStatusBarSurface(showSurface, terminalSurfaceColor) ? View.VISIBLE : View.GONE);
        if (terminalView != null) {
            terminalView.setBackgroundColor(Color.TRANSPARENT);
            if (terminalView instanceof TerminalView) {
                ((TerminalView) terminalView).setTransparentFrameOverlayColor(Color.TRANSPARENT);
            }
        }
        applyTerminalStatusBarSurfaceColor(showSurface, terminalSurfaceColor);
        applyTerminalWindowBarBackdropInsets();
        redressKeyboardForStyle();
    }

    /**
     * A live Style change: the keyboard host is redressed in the pass that changes everything else,
     * as a card or as a slice of the frame, rather than waiting for a chrome render that may not
     * come.
     */
    private void redressKeyboardForStyle() {
        if (isInAppKeyboardShown() && isInAppKeyboardCapsule() != mKeyboardSurfaceDressedAsCard)
            applyInAppKeyboardSurfaceState(buildChromeSpec());
    }

    /**
     * Optional thin outline framing the terminal area. Rounded to the same radius as other capsule
     * surfaces and inset from the dock/keyboard edges by the same 10dp when the Rounded surface
     * style is active; square and edge-to-edge otherwise. The pane host is inset by the stroke
     * width plus a small gap so terminal content never renders under the line, and is clipped to
     * the same rounded outline so its corners don't poke past a rounded border.
     */
    /**
     * Ceiling on the radius Floating lends the terminal's edge. The dock capsule is a pill; the
     * terminal it floats above is a tall slab, and a pill's radius on a slab reads as a lozenge, so
     * the edge takes the capsule's radius only up to here.
     */
    private static final int TERMINAL_PANE_MAX_CAPSULE_RADIUS_DP = 14;

    /**
     * Tiled panes in the active window. A maximized pane counts as one, which is the point:
     * temporarily maximizing is visually a lone pane and should get the terminal border back.
     *
     * <p>Floats are deliberately excluded. This count decides whether the terminal border or the
     * per-pane borders own the frame line, and that flips paneInsetPx — which resizes the tiled
     * TerminalView and so reflows its PTY and resets its scroll position. A float is drawn over the
     * terminal and owns its own border; it must not make the pane underneath it reflow.
     */
    private int visiblePaneCount() {
        return mPaneController == null ? 1 : mPaneController.tiledPaneCount();
    }

    /**
     * The radius the terminal's own top corners actually draw with, which is what any surface
     * hanging off them has to match: Corners, whether the pane is a Floating card or the Docked
     * rounded insert.
     */
    private float terminalEdgeCornerRadiusPx() {
        return layoutCornersPx(com.termux.app.place.SeamDress.Surface.FRAME);
    }

    /**
     * The pane host's clip when it is there to contain, not to shape: a rect inflated by the room a
     * pressed pane travels into.
     *
     * <p>The host clips so a dragged float cannot paint over the dock. Its bounds are the pane area,
     * which is also exactly where a pressed pane's tilt and slide take it — so the clip cut the
     * press off along the margin, taking the slab's lit rim with it, and the border stopped reading
     * as part of the terminal. Slack of a few dp contains the float and lets the press happen. The
     * shaping clips (a Docked radius, the frame's inner radius) are left exact: they are the
     * terminal's own corners, nothing tilts under them, and inflating those would let the corner
     * cells poke past the arc.
     */
    @NonNull
    private ViewOutlineProvider paneHostContainmentOutlineProvider() {
        final int slackPx = Math.round(dpToPx(
            com.termux.app.terminal.TerminalPaneController.PANE_PRESS_SLACK_DP));
        ViewOutlineProvider held = mPaneHostContainmentOutline;
        if (held != null && slackPx == mPaneHostContainmentSlackPx) return held;
        mPaneHostContainmentSlackPx = slackPx;
        mPaneHostContainmentOutline = new ViewOutlineProvider() {
            @Override
            public void getOutline(View view, android.graphics.Outline outline) {
                outline.setRect(-slackPx, -slackPx,
                    view.getWidth() + slackPx, view.getHeight() + slackPx);
            }
        };
        return mPaneHostContainmentOutline;
    }

    /** The containment outline and the slack it was made for; one per slack, not per pass. */
    @Nullable private ViewOutlineProvider mPaneHostContainmentOutline;
    private int mPaneHostContainmentSlackPx = -1;
    /** The pane host's rounded outline and the radius it was made for; see {@link #setOutlineIfChanged}. */
    @Nullable private ViewOutlineProvider mPaneHostRoundedOutline;
    private float mPaneHostRoundedRadiusPx = Float.NaN;

    /** {@link #roundedOutlineProvider} for the pane host, kept while the radius holds. */
    @NonNull
    private ViewOutlineProvider paneHostRoundedOutlineProvider(float radiusPx) {
        ViewOutlineProvider held = mPaneHostRoundedOutline;
        if (held != null && Float.compare(radiusPx, mPaneHostRoundedRadiusPx) == 0) return held;
        held = roundedOutlineProvider(radiusPx);
        mPaneHostRoundedOutline = held;
        mPaneHostRoundedRadiusPx = radiusPx;
        return held;
    }

    @NonNull
    private static ViewOutlineProvider roundedOutlineProvider(float radiusPx) {
        return new ViewOutlineProvider() {
            @Override
            public void getOutline(View view, android.graphics.Outline outline) {
                outline.setRoundRect(0, 0, view.getWidth(), view.getHeight(), radiusPx);
            }
        };
    }

    /**
     * Where the terminal's frame sits inside its host, on one axis.
     *
     * <p>Sideways, Floating tucks under the dock's own capsule inset, which gives it visible air.
     * Vertically it had none, so its edges butted against the status bar and the dock and read as
     * one merged frame; it is held off both by the gap the capsule surfaces leave. Docked spends
     * the user's own Margin knob evenly on all four sides instead.
     *
     * <p>Shared with whatever else has to sit on that edge — the mode hint card hangs off the
     * top-trailing corner and must land on the terminal's edge, not near it.
     *
     * @param framed whether a frame line (the border preference, or the glass rim) is being drawn,
     *     which is what buys the Floating frame its vertical air.
     */
    private int terminalFrameInsetPx(boolean vertical, boolean framed) {
        // The model's opening keeps Margin from every bar and screen edge under both Styles: the
        // Floating pane card stands at exactly that, the Docked insert a gutter of frame glass in.
        return terminalFrameInsetPx(vertical);
    }

    /**
     * The air a side stack keeps at each end: the terminal frame's own vertical inset, so a rail
     * and a standing alphabets index begin and end level with the edge of the frame beside them
     * instead of running the raw height of the canvas band.
     *
     * <p>Padding on the stack rather than on each bar inside it: one answer, applied once, and
     * every band the user puts on that edge inherits it without knowing the number. Derived from
     * {@link #terminalFrameInsetPx(boolean)} — the same call the frame and the pane host are laid
     * out with — so there is nothing to keep in step.
     */
    void applySideStackFrameInset(int verticalInsetPx) {
        mSideStackFrameInsetPx = Math.max(0, verticalInsetPx);
        padSideStack(0, findViewById(R.id.place_edge_stack_left));
        padSideStack(1, findViewById(R.id.place_edge_stack_right));
    }

    /**
     * A side stack's padding: the frame inset at both ends, plus the status bar's band on top on a
     * page it overlays (EdgeStackPolicy.sideStackTopInsetPx), so a side column starts at the bar's
     * edge, and the dock's reach at the bottom on a page it overlays
     * (EdgeStackPolicy.sideStackBottomInsetPx), so it ends above the dock. Whether it changed.
     */
    private boolean padSideStack(int side, @Nullable View stack) {
        if (stack == null) return false;
        int top = mSideStackFrameInsetPx + mSideStackBarInsetPx[side];
        int bottom = mSideStackFrameInsetPx + mSideStackDockInsetPx[side];
        if (stack.getPaddingTop() == top && stack.getPaddingBottom() == bottom) return false;
        stack.setPadding(stack.getPaddingLeft(), top, stack.getPaddingRight(), bottom);
        return true;
    }

    /** The frame inset both side stacks keep at each end (applySideStackFrameInset). */
    private int mSideStackFrameInsetPx;

    /** Per side stack (left, right), the status bar's band it starts below; 0 off Home. */
    @NonNull private final int[] mSideStackBarInsetPx = new int[2];

    /** Per side stack (left, right), the dock's reach it ends above; 0 off Home. */
    @NonNull private final int[] mSideStackDockInsetPx = new int[2];

    /**
     * Ends each side stack above the dock on a page the dock overlays: the canvas reaches
     * {@code bottomReachPx} under the bottom stack there, and a side column standing the canvas's
     * whole height ran on under the dock's last icons. Whether either stack moved.
     */
    private boolean applySideStackDockInsets(boolean dockOverlays, int bottomReachPx) {
        PlaceLayout layout = arrangement().layout();
        boolean moved = false;
        PlaceLayout.Edge[] edges = {PlaceLayout.Edge.LEFT, PlaceLayout.Edge.RIGHT};
        int[] ids = {R.id.place_edge_stack_left, R.id.place_edge_stack_right};
        for (int side = 0; side < ids.length; side++) {
            int inset = EdgeStackPolicy.sideStackBottomInsetPx(layout, edges[side], dockOverlays,
                bottomReachPx);
            if (mSideStackDockInsetPx[side] == inset) continue;
            mSideStackDockInsetPx[side] = inset;
            moved |= padSideStack(side, findViewById(ids[side]));
        }
        return moved;
    }

    /** The same two numbers the frame is laid out with, for a surface that has to meet its edge. */
    private int terminalFrameInsetPx(boolean vertical) {
        return terminalFrameInsetPx(chromeShape(com.termux.app.place.SeamDress.Surface.FRAME), vertical);
    }

    /**
     * Both of {@link #terminalFrameInsetPx(boolean)}'s numbers off one chrome shape, for the
     * callers that need the pair: {@code out[0]} the horizontal inset, {@code out[1]} the
     * vertical. The shape is the same answer both calls built, built once.
     */
    private void terminalFrameInsetsPx(@NonNull int[] out) {
        com.termux.app.place.ChromeShape shape = chromeShape(com.termux.app.place.SeamDress.Surface.FRAME);
        out[0] = terminalFrameInsetPx(shape, false);
        out[1] = terminalFrameInsetPx(shape, true);
    }

    /** Scratch for {@link #terminalFrameInsetsPx}; main thread only. */
    @NonNull private final int[] mTmpFrameInsets = new int[2];

    private int terminalFrameInsetPx(@NonNull com.termux.app.place.ChromeShape shape,
                                     boolean vertical) {
        View root = hotView(R.id.activity_termux_root_view);
        android.util.DisplayMetrics metrics = getResources().getDisplayMetrics();
        float width = root != null && root.getWidth() > 0 ? root.getWidth() : metrics.widthPixels;
        float height = root != null && root.getHeight() > 0 ? root.getHeight() : metrics.heightPixels;
        return Math.round(com.termux.app.chrome.LiveChromeShape.terminalOpeningInsetPx(shape,
            vertical ? PlaceLayout.Edge.TOP : PlaceLayout.Edge.LEFT, width, height,
            metrics.density));
    }

    private void applyTerminalBorderAppearance() {
        if (mPreferences == null) {
            return;
        }
        View borderView = findViewById(R.id.terminal_border_overlay);
        View paneHost = findViewById(R.id.terminal_pane_host);
        if (borderView == null || paneHost == null) {
            return;
        }
        // One frame line, one owner. A lone pane gets the terminal border; the moment a window
        // splits, the pane borders are the frame and the terminal border stands down — two
        // concentric strokes only ever cost the terminal a row and clipped the prompt's own glyph
        // against the outer one.
        boolean preferBorder = mPreferences.isTerminalBorderEnabled();
        boolean singlePane = visiblePaneCount() <= 1;
        // With glass on, each pane carries its own lit rim, and a second frame drawn around the
        // whole terminal would box the floating slabs inside a sheet — the exact reading the glass
        // is there to break. So the outer line is the plain-border case only.
        boolean glass = isTerminalPaneGlassActive();
        boolean enabled = preferBorder && singlePane && !glass;
        borderView.setVisibility(enabled ? View.VISIBLE : View.GONE);
        // The pane is a shape of its own under both Styles: a card over the wallpaper or the
        // rounded insert over the frame glass, at Corners either way.
        boolean capsule = true;
        int capsuleMarginPx = mDock.appliedDockLayout().horizontalInsetPx;

        // Where a frame line sits, whichever view draws it. Sideways it tucks under the dock's own
        // capsule inset, which gives it visible air. Vertically it had none, so its top edge butted
        // against the status bar's lower edge and its bottom against the dock's upper edge, reading
        // as one merged frame; hold it off both by the gap the capsule surfaces leave.
        //
        // Keyed off the preference rather than off `enabled`, so splitting a window does not shift
        // the terminal: the pane borders land exactly where the terminal border was.
        terminalFrameInsetsPx(mTmpFrameInsets);
        int borderVerticalInsetPx = mTmpFrameInsets[1];
        int borderHorizontalInsetPx = mTmpFrameInsets[0];
        // The side stacks flank the canvas, so their bars start and end where the terminal's own
        // frame does rather than at the raw edges of the band it sits in. Under a joined Docked
        // frame the model stands the side bars flush between the top and bottom stacks, and the
        // insert's gutter is frame glass, not air: padding them by it left a wallpaper gap at each
        // end of the A-Z bar and the extra-keys column.
        applySideStackFrameInset(hasDockedFrameCard() ? 0 : borderVerticalInsetPx);

        ViewGroup.LayoutParams borderParams = borderView.getLayoutParams();
        if (borderParams instanceof ViewGroup.MarginLayoutParams) {
            ViewGroup.MarginLayoutParams marginParams = (ViewGroup.MarginLayoutParams) borderParams;
            // It frames the terminal page from outside the wall, so it starts where that page
            // does: the Terminal's top inset below the frame's own (applyTerminalTopInset).
            mTerminalBorderFrameTopPx = borderVerticalInsetPx;
            int borderTopPx = borderVerticalInsetPx + mTerminalTopInsetPx;
            // The Terminal's frame line ends above the canvas's bottom by the Terminal's own room.
            int borderBottomPx = borderVerticalInsetPx + (mPaneWallController == null ? 0
                : mPaneWallController.wall().pageBottomInsetPx(
                    com.termux.app.page.PageKind.TERMINAL));
            if (marginParams.leftMargin != borderHorizontalInsetPx || marginParams.rightMargin != borderHorizontalInsetPx
                || marginParams.topMargin != borderTopPx
                || marginParams.bottomMargin != borderBottomPx) {
                marginParams.leftMargin = borderHorizontalInsetPx;
                marginParams.rightMargin = borderHorizontalInsetPx;
                marginParams.topMargin = borderTopPx;
                marginParams.bottomMargin = borderBottomPx;
                borderView.setLayoutParams(marginParams);
            }
        }
        int strokePx = Math.max(1, Math.round(dpToPx(1)));
        // The pane's shape is Corners, a card under Floating and the insert under Docked.
        float cornerRadiusPx = mDock.resolveDockCapsuleCornerRadiusPx(Integer.MAX_VALUE);

        // Clearance inside the frame line, so a glyph never touches the stroke. Only the terminal
        // border needs it: pane borders draw their own stroke on the frame line itself, and adding
        // this on top of them is what pushed the split panes inside the outer border and clipped
        // their top corners.
        //
        // Arc clearance is not part of this margin. A margin moves the clipped box; it does not
        // move the box's own corners away from the arc it is clipped to, so at any radius the
        // corner cells were still being nibbled — worse the larger the radius. That clearance is
        // padding inside the clip instead (see cornerArcPaddingPx below).
        int paneInsetPx = enabled ? strokePx + Math.round(dpToPx(2)) : 0;
        // The other pages' cards stand at the frame itself, the model's opening, so the wall is
        // told how much of the terminal's margin is its own border's air.
        if (paneHost.getParent() instanceof com.termux.app.wall.PaneWallLayout)
            ((com.termux.app.wall.PaneWallLayout) paneHost.getParent())
                .setTerminalFrameAirPx(paneInsetPx);
        int paneHorizontalInsetPx = borderHorizontalInsetPx + paneInsetPx;
        int paneVerticalInsetPx = borderVerticalInsetPx + paneInsetPx;
        ViewGroup.LayoutParams paneParams = paneHost.getLayoutParams();
        if (paneParams instanceof ViewGroup.MarginLayoutParams) {
            ViewGroup.MarginLayoutParams marginParams = (ViewGroup.MarginLayoutParams) paneParams;
            if (marginParams.leftMargin != paneHorizontalInsetPx || marginParams.rightMargin != paneHorizontalInsetPx
                || marginParams.topMargin != paneVerticalInsetPx
                || marginParams.bottomMargin != paneVerticalInsetPx) {
                marginParams.leftMargin = paneHorizontalInsetPx;
                marginParams.rightMargin = paneHorizontalInsetPx;
                marginParams.topMargin = paneVerticalInsetPx;
                marginParams.bottomMargin = paneVerticalInsetPx;
                paneHost.setLayoutParams(marginParams);
            }
        }

        if (!enabled) {
            borderView.setBackground(null);
            if (borderView instanceof TerminalGlassFrameView) {
                ((TerminalGlassFrameView) borderView).setRim(false, 0f);
            }
            // The host rounds nothing itself: each pane's slab clips its own corners, a card
            // under Floating and the insert under Docked.
            applyPaneHostCornerPadding(paneHost, 0);
            refreshAzTabTextInsets();
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.LOLLIPOP) {
                setOutlineIfChanged(paneHost, paneHostContainmentOutlineProvider(), glass);
            }
            setupTerminalPlankFx(glass);
            updateTerminalGlassFrost();
            return;
        }

        // The lone pane's frame is the shared rim under Floating, the same border the status bar,
        // dock and keyboard wear (the dock's gradient, under every look), and the opening's line
        // under Docked, as the panes' own frames are (PaneRim). The Material active colour belongs
        // to the focused pane of a split only (PaneBorderStyle).
        borderView.setBackground(terminalBorderRim(borderView, cornerRadiusPx));
        if (borderView instanceof TerminalGlassFrameView) {
            ((TerminalGlassFrameView) borderView).setRim(false, 0f);
        }

        setupTerminalPlankFx(false);
        updateTerminalGlassFrost();

        float innerRadiusPx = Math.max(0f, cornerRadiusPx - paneInsetPx);
        // Padding the host by the arc's own depth (PaneShape.contentInsetPx) is what keeps the
        // corner glyphs whole, and because it is derived from the radius it holds at 20dp and at
        // 40dp alike — the same trade tmux and zellij make when they spend a whole cell on the
        // frame: the frame owns space the content never enters. This is the lone pane's only arc
        // clearance: its frame draws no arc of its own and is told it is square
        // (TerminalPaneController.updateActiveBorders), so the terminal does not pay for the
        // same corner twice. Split panes round their own corners and pay their own clearance.
        applyPaneHostCornerPadding(paneHost, PaneShape.contentInsetPx(innerRadiusPx));
        refreshAzTabTextInsets();

        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.LOLLIPOP) {
            applyPaneHostOutline(paneHost, innerRadiusPx);
        }
    }

    /** The pane host's inner radius the frame last asked for; negative until it has. */
    private float mPaneHostInnerRadiusPx = -1f;
    /** The pane host's outline while Full screen raises its top corners to the screen's. */
    private final com.termux.app.chrome.ChromeShapeOutlineProvider mPaneHostScreenTopOutline =
        new com.termux.app.chrome.ChromeShapeOutlineProvider();

    /**
     * The pane host's outline: its own rounded rect, or, when Full screen leaves its top inside
     * the screen's top corners' band ({@link #fullScreenPaneTopRadiusPx}), the same card with its
     * top corners curving with the screen's, as the keyboard's bottom does. Only the outline;
     * a per-corner clip needs a path outline, so Android 13 and later.
     */
    private void applyPaneHostOutline(@NonNull View paneHost, float innerRadiusPx) {
        mPaneHostInnerRadiusPx = innerRadiusPx;
        float top = fullScreenPaneTopRadiusPx(paneHost);
        if (Build.VERSION.SDK_INT < 33 || top <= innerRadiusPx) {
            setOutlineIfChanged(paneHost, innerRadiusPx > 0f
                ? paneHostRoundedOutlineProvider(innerRadiusPx) : ViewOutlineProvider.BOUNDS, true);
            return;
        }
        boolean changed = mPaneHostScreenTopOutline.setClip(
            com.termux.app.chrome.LiveChromeShape.atLeast(
                com.termux.app.chrome.LiveChromeShape.cardClip(innerRadiusPx), top, 0f));
        if (paneHost.getOutlineProvider() != mPaneHostScreenTopOutline)
            paneHost.setOutlineProvider(mPaneHostScreenTopOutline);
        else if (changed)
            paneHost.invalidateOutline();
        mPaneHostScreenTopOutline.follow(paneHost);
        if (!paneHost.getClipToOutline()) paneHost.setClipToOutline(true);
    }

    /**
     * The screen's top radius the pane host's top corners take, or 0: only in Full screen with
     * the status row hidden, when the host's top stands inside the top corners' band.
     */
    private float fullScreenPaneTopRadiusPx(@NonNull View paneHost) {
        if (!panesReachScreenTop() || paneHost.getHeight() <= 0) return 0f;
        float screen = Math.max(mDisplayCornerRadiiPx[0], mDisplayCornerRadiiPx[1]);
        int[] origin = new int[2];
        com.termux.app.chrome.GlassAnchor.layoutOriginOnScreen(paneHost, origin, new int[2]);
        return com.termux.app.chrome.FullScreenCornerPolicy.topCornerRadiusPx(true, 0f,
            origin[1], screen);
    }

    /** Whether Full screen may lift the panes to the screen's top: the status row hidden. */
    private boolean panesReachScreenTop() {
        if (mProperties == null || !mProperties.isUsingFullScreen()) return false;
        View row = findViewById(R.id.terminal_status_row);
        return row == null || !row.isShown();
    }

    /** How deep the pane rim's top line is cut where the camera stands over it, in dp. */
    private static final float PANE_TOP_GAP_DEPTH_DP = 3f;
    private final int[] mPaneTopOrigin = new int[2];
    private final int[] mPaneTopScratch = new int[2];
    private final int[] mPaneTopGap = new int[2];
    /** Whether {@link #syncPanesForScreenTop} follows every window layout yet; installed once. */
    private boolean mPanesScreenTopFollowed;

    /**
     * Keeps each visible pane's text clear of the camera ({@link
     * com.termux.app.chrome.FullScreenCornerPolicy#paneTextTopInsetPx}) and the pane host's top
     * corners with the screen's, after every window layout, so a pane Full screen lifts to the
     * top reads the band on the pass that moved it. Outside Full screen every inset is 0 and the
     * outline is the host's own. Compares first: a pane at rest costs a walk up its parents.
     */
    private void syncPanesForScreenTop() {
        syncBarSplit();
        // The thin row follows the top pane's laid-out place (a split, a keyboard, a rotation).
        mStatusRow.syncStatusRowPlace();
        int[] box = panesReachScreenTop() ? mCameraBox : null;
        java.util.List<TerminalView> panes = mPaneController != null
            ? mPaneController.getVisiblePaneViews()
            : (mTerminalView == null ? java.util.Collections.emptyList()
                : java.util.Collections.singletonList(mTerminalView));
        int[] origin = mPaneTopOrigin;
        int[] scratch = mPaneTopScratch;
        int[] gap = mPaneTopGap;
        int gapDepthPx = Math.round(dpToPx(PANE_TOP_GAP_DEPTH_DP));
        for (TerminalView pane : panes) {
            if (pane == null) continue;
            int inset = 0;
            int gapStart = 0;
            int gapEnd = 0;
            if (box != null && pane.getWidth() > 0) {
                com.termux.app.chrome.GlassAnchor.layoutOriginOnScreen(pane, origin, scratch);
                inset = com.termux.app.chrome.FullScreenCornerPolicy.paneTextTopInsetPx(true,
                    origin[0], origin[1], origin[0] + pane.getWidth(), box[0], box[2], box[3]);
                // The rim is the pane frame's: its own x, from the frame's left edge.
                View frame = pane.getParent() instanceof View ? (View) pane.getParent() : null;
                if (frame instanceof com.termux.app.terminal.PaneContentFrame && frame.getWidth() > 0) {
                    com.termux.app.chrome.GlassAnchor.layoutOriginOnScreen(frame, origin, scratch);
                    if (com.termux.app.chrome.CameraHoleGeometry.paneTopGap(box, origin[0],
                        origin[1], origin[0] + frame.getWidth(), gap)) {
                        gapStart = gap[0];
                        gapEnd = gap[1];
                    }
                }
            }
            pane.setTextTopInsetPx(inset);
            if (pane.getParent() instanceof com.termux.app.terminal.PaneContentFrame) {
                ((com.termux.app.terminal.PaneContentFrame) pane.getParent())
                    .setTopGap(gapStart, gapEnd, gapDepthPx);
            }
        }
        // The plain border round a lone pane (no glass) breaks over the camera too.
        View border = findViewById(R.id.terminal_border_overlay);
        if (border instanceof TerminalGlassFrameView) {
            int start = 0;
            int end = 0;
            if (box != null && border.getVisibility() == View.VISIBLE && border.getWidth() > 0) {
                com.termux.app.chrome.GlassAnchor.layoutOriginOnScreen(border, origin, scratch);
                if (com.termux.app.chrome.CameraHoleGeometry.paneTopGap(box, origin[0], origin[1],
                    origin[0] + border.getWidth(), gap)) {
                    start = gap[0];
                    end = gap[1];
                }
            }
            ((TerminalGlassFrameView) border).setTopGap(start, end, gapDepthPx);
        }
        if (mPaneHostInnerRadiusPx >= 0f && Build.VERSION.SDK_INT >= Build.VERSION_CODES.LOLLIPOP) {
            View paneHost = findViewById(R.id.terminal_pane_host);
            if (paneHost != null) applyPaneHostOutline(paneHost, mPaneHostInnerRadiusPx);
        }
    }

    /**
     * Puts {@code provider} on {@code view} unless it is already there. A provider's outline is a
     * function of its own key and the view's size, and the view rebuilds it itself on a resize,
     * so handing it the same provider again (as every inset dispatch did, with a new one each
     * time) only re-ran the outline and damaged the parent for nothing.
     */
    private static void setOutlineIfChanged(@NonNull View view, @NonNull ViewOutlineProvider provider,
                                            boolean clip) {
        if (view.getOutlineProvider() != provider) view.setOutlineProvider(provider);
        if (view.getClipToOutline() != clip) view.setClipToOutline(clip);
    }

    /** The lone pane's frame line, kept while its radius and stroke hold; see {@link #terminalBorderRim}. */
    @Nullable private Drawable mTerminalBorderRim;
    private float mTerminalBorderRimRadiusPx = Float.NaN;
    private int mTerminalBorderRimStrokePx = -1;
    /** Whether {@link #mTerminalBorderRim} is the Docked opening's line rather than the glass rim. */
    private boolean mTerminalBorderRimIsLine;

    /**
     * The rim the lone pane's frame line wears: the drawable it already has while the radius, the
     * stroke and the Style it was made for still hold — it is drawn from those alone — else a new
     * one: the opening's line under Docked, the glass's gradient rim under Floating.
     */
    @NonNull
    private Drawable terminalBorderRim(@NonNull View borderView, float cornerRadiusPx) {
        int strokePx = Math.max(1, Math.round(dpToPx(1)));
        boolean line = !isRoundedStyle(com.termux.app.place.SeamDress.Surface.FRAME);
        Drawable rim = mTerminalBorderRim;
        if (rim != null && borderView.getBackground() == rim
            && Float.compare(cornerRadiusPx, mTerminalBorderRimRadiusPx) == 0
            && strokePx == mTerminalBorderRimStrokePx && line == mTerminalBorderRimIsLine) {
            return rim;
        }
        rim = line ? com.termux.app.terminal.PaneRim.openingLine(this, cornerRadiusPx)
            : mChrome.glass().rimDrawable(cornerRadiusPx);
        mTerminalBorderRim = rim;
        mTerminalBorderRimRadiusPx = cornerRadiusPx;
        mTerminalBorderRimStrokePx = strokePx;
        mTerminalBorderRimIsLine = line;
        return rim;
    }

    /**
     * Whether the model has a joined Docked frame, and so a gutter of glass round the insert: with
     * a bar at a side, or with every bar put away. With none at a side the top and bottom stacks
     * are edge cards and the gutter is the wallpaper, as it is under Floating.
     */
    private boolean hasDockedFrameCard() {
        // Under Terl the frame with every bar put away is the wall's ground, keyboard or not
        // (FrameGlassPolicy.frameCard, round 5).
        if (com.termux.app.chrome.FrameGlassPolicy.frameCard(mControlBar != null,
                !isFloatingStyle(), false)) return true;
        com.termux.app.place.ChromeShape shape =
            chromeShape(com.termux.app.place.SeamDress.Surface.FRAME);
        for (com.termux.app.place.ChromeShape.Card card : shape.cards())
            if (card.frame) return true;
        return false;
    }

    /**
     * Whether the joined Docked frame's glass is the one sheet behind the whole screen, so that
     * every sheet inside it (status bar, dock rows, off-dock planks, the keyboard's slab) stands
     * down. The same gate {@link #applyFrameGutterGlass} paints under. Read live: the shape model
     * is a handful of rects and the cheap tests come first, so no answer is held across a layout
     * or Style change that could leave a sheet stale.
     */
    private boolean frameStandsDown() {
        if (mPreferences == null || !shouldUseWallpaperPassthroughMode()
            || !isTerminalPaneGlassActive()) return false;
        return com.termux.app.chrome.FrameGlassPolicy.sheetsStandDown(true, true,
            hasDockedFrameCard());
    }

    /**
     * {@link #frameStandsDown} for the stack's own sheets (the dock's, the keyboard's): they stand
     * down on the frame's glass only while they wear the frame's dress. Mid-slide across the seam,
     * dressed for the other half (SeamDress), they keep sheets of their own.
     */
    private boolean stackStandsDownOnFrame() {
        return !stackDressedApart() && frameStandsDown();
    }

    /**
     * Whether the apps row wears Lens beads on the joined frame, which then leaves the row's band
     * out of its glass ({@link #syncFrameBeadCut}): the beads resolved
     * ({@link #resolveDockBeads}, from the row's geometry and the frame's answer alone, no glass
     * read) while the stack stands down on the frame.
     */
    private boolean dockBeadsCutFrame() {
        return mDock.beads() != null && stackStandsDownOnFrame();
    }

    /**
     * {@link #stackStandsDownOnFrame} for the dock's own sheet: it stands down on the frame, but
     * returns for the apps row's beads where they cut the frame ({@link #dockBeadsCutFrame}); the
     * host clips that sheet to the beads, so every other band keeps the frame's glass. The
     * keyboard's sheet and the gesture strip keep asking {@link #stackStandsDownOnFrame}.
     */
    private boolean dockSheetStandsDownOnFrame() {
        return mDock.beads() == null && stackStandsDownOnFrame();
    }

    /** Whether the sheets were last dressed standing down; see {@link #syncFrameStandDown}. */
    private boolean mFrameSheetsStoodDown;

    /**
     * Notes a flip of {@link #frameStandsDown} and, when it flips, asks every sheet it touches to
     * dress again: a Style round trip must bring each one back (or take it away) without waiting
     * for something else to move it.
     */
    private void syncFrameStandDown() {
        boolean now = frameStandsDown();
        if (now == mFrameSheetsStoodDown) return;
        mFrameSheetsStoodDown = now;
        View root = findViewById(R.id.activity_termux_root_view);
        if (root == null) return;
        root.post(() -> {
            refreshTerminalWindowBar();
            refreshOffDockGlass();
            applyTerminalWindowBarBackdropInsets();
            if (mChrome != null) mChrome.requestSync(ChromeRenderer.SCOPE_BACKDROPS
                | ChromeRenderer.SCOPE_KEYBOARD_BACKDROP | ChromeRenderer.SCOPE_ACCESSORY_RENDER
                | ChromeRenderer.SCOPE_TOP_PANE_FROST);
        });
    }

    /**
     * The Docked frame's glass behind the gutter: the dock's material (frost of the wallpaper, the
     * tint at the dock's opacity, its grain) filling the terminal's host, which the pane slabs then
     * sit on, inset by Margin. Under Floating and in opaque mode the view carries none, and
     * whatever a Docked pass left on it is cleared, so a Style round trip cannot leave a layer
     * behind.
     */
    /**
     * The view the Docked frame's glass is painted on: a full-screen view just above the wallpaper
     * backdrop and under every chrome sheet. Painted on the canvas band it stopped at the status
     * bar and the dock, each of which wore its own glass and showed a seam where the tones met.
     */
    @Nullable
    private View frameGlassHost() {
        // The whole-screen view behind the status bar, the canvas band, the dock rows and the
        // keyboard (the band alone stops at the status bar and the dock), so the frame is one sheet.
        return findViewById(R.id.docked_frame_glass);
    }

    private void applyFrameGutterGlass(@Nullable View body, boolean on) {
        if (body == null) return;
        if (!on) {
            mFrameGutterBackdropBitmap = null;
            mFrameGutterKey = null;
            mFrameGutterDrawable = null;
            if (mFrameGutterShown) body.setBackground(null);
            body.setVisibility(View.GONE);
            mFrameGutterShown = false;
            syncFrameStandDown();
            return;
        }
        if (mPreferences == null) return;
        float density = getResources().getDisplayMetrics().density;
        int blurRadiusDp = getEffectiveExtraKeysBlurRadius();
        Bitmap frame = null;
        View wallpaperFrame = findViewById(R.id.activity_termux_root_view);
        if (ChromePolicy.dockBlurEnabled(blurRadiusDp) && wallpaperFrame != null
                && wallpaperSampleable()) {
            frame = mChrome.blurCache().obtain(blurRadiusDp, wallpaperFrame);
            if (frame != null && frame.isRecycled()) frame = null;
        }
        // Rebuilt only when what it is dressed with has moved: this runs behind every chrome pass.
        // The test is for the glass this method built, not for any background: the body-surface
        // reset that runs just before leaves a transparent colour drawable and hides the view, and
        // taking that for the glass left the gutter bare from the second pass on.
        // The dock's material, with the dock's own Depth and Edge where it holds them (ADR 0017).
        com.termux.app.chrome.GlassRefraction.Look gutterLook = com.termux.app.chrome.ElementGlass.refraction(mPreferences,
            com.termux.shared.termux.settings.preferences.LookGrid.Element.DOCK, restingPage(), mFancierGlassLook);
        List<Object> key = Arrays.asList(frame, blurRadiusDp, mPreferences.getAppBarOpacity(restingPage()),
            mPreferences.getDockGlassGrain(restingPage()), gutterLook, mPreferences.getDockTintStrength(restingPage()));
        if (mFrameGutterShown && mFrameGutterDrawable != null
                && body.getBackground() == mFrameGutterDrawable && key.equals(mFrameGutterKey)) {
            body.setVisibility(View.VISIBLE);
            syncFrameStandDown();
            syncFrameBeadCut();
            return;
        }
        mFrameGutterKey = key;
        mFrameGutterBackdropBitmap = frame;
        com.termux.app.chrome.SharedFrameDrawable backdrop = frame == null ? null
            : new com.termux.app.chrome.SharedFrameDrawable(frame,
                new Rect(mChrome.blurCache().frameRectRef()), mWallpaperParallax,
                com.termux.app.chrome.GlassAnchor.layout(body, () -> 0f));
        com.termux.app.chrome.GlassStack.Spec spec = com.termux.app.chrome.GlassStack.Spec.of(
            blurRadiusDp, mPreferences.getAppBarOpacity(restingPage()) / 100f,
            mPreferences.getDockGlassGrain(restingPage()), 0f, gutterLook).withRim(false)
            .withTintStrength(mPreferences.getDockTintStrength(restingPage()))
            // Every edge of this sheet is the screen's own. The gathered light, which every side
            // takes a share of, would run a glow round the screen, so all four are seams.
            .withSeams(com.termux.app.chrome.ChromeEdgeRule.ALL)
            // The page's ground over the frame, as the bars and the dock draw it (#283).
            .withGround(true);
        // Wrapped so the apps row's band can be left out where it wears Lens beads; with no band
        // it draws the sheet whole (FrameBandCutDrawable).
        Drawable frameStack = com.termux.app.chrome.GlassStack.build(mChrome.glass(), spec, density,
            backdrop);
        com.termux.app.chrome.GroundUnderGlass.bind(frameStack, body);
        mFrameGutterDrawable = new com.termux.app.dock.FrameBandCutDrawable(frameStack);
        body.setBackground(mFrameGutterDrawable);
        growFrameGlassUnderSystemBars(body);
        body.setVisibility(View.VISIBLE);
        mFrameGutterShown = true;
        syncFrameStandDown();
        syncFrameBeadCut();
    }

    /**
     * Leaves the apps row's band out of the joined frame's glass while the row wears Lens beads
     * on it ({@link #dockBeadsCutFrame}), and puts it back otherwise: the band spans the frame's
     * width and reaches over the row and its beads (the Search field's capsule under them, and
     * the A–Z row under the icons with its letter beads), so the frame continues above and under
     * it (the gesture strip's foot) and the beads stand on the wallpaper as under Floating.
     */
    private void syncFrameBeadCut() {
        if (!(mFrameGutterDrawable instanceof com.termux.app.dock.FrameBandCutDrawable)) return;
        com.termux.app.dock.FrameBandCutDrawable frame =
            (com.termux.app.dock.FrameBandCutDrawable) mFrameGutterDrawable;
        com.termux.app.dock.LensBeadGeometry.Beads beads = mDock.beads();
        View body = findViewById(R.id.docked_frame_glass);
        View host = findViewById(R.id.accessory_surface_host);
        SuggestionBarView row = mSuggestionBarView;
        if (beads == null || body == null || host == null || row == null || !mFrameGutterShown
            || body.getWidth() <= 0 || !dockBeadsCutFrame()) {
            frame.setCut(null);
            return;
        }
        int[] at = new int[2];
        body.getLocationOnScreen(at);
        float bodyY = at[1];
        host.getLocationOnScreen(at);
        float hostY = at[1];
        row.getLocationOnScreen(at);
        float top = Math.min(at[1], hostY + beads.centerY - beads.radiusPx);
        float bottom = Math.max(at[1] + row.getHeight(), hostY + beads.centerY + beads.radiusPx);
        if (beads.hasCapsule()) {
            top = Math.min(top, hostY + beads.capsuleTop);
            bottom = Math.max(bottom, hostY + beads.capsuleBottom);
        }
        // The A–Z row under the icons wears letter beads too: its band leaves the frame as well,
        // with the room its beads rise into.
        com.termux.app.dock.AzBeadRow az = mDock.azBeads();
        View azRow = az != null ? findViewById(R.id.apps_bar_az_row) : null;
        if (az != null && azRow != null) {
            azRow.getLocationOnScreen(at);
            float liftRoom = com.termux.app.dock.AzBeadRow.LIFT_PEAK_DP
                * getResources().getDisplayMetrics().density;
            top = Math.min(top, Math.min(at[1], hostY + az.centerY - az.radiusPx - liftRoom));
            bottom = Math.max(bottom, Math.max(at[1] + azRow.getHeight(),
                hostY + az.centerY + az.radiusPx));
        }
        frame.setCut(new RectF(0f, top - bodyY, body.getWidth(), bottom - bodyY));
    }

    /**
     * The frame glass reaches under the transparent system bars. The root fits the system windows,
     * so its children stop at the status bar's inset and the gesture strip's; the status sheet used
     * to continue up by translating itself, and now that it stands down the frame has to, or the
     * strip under the system status bar shows bare wallpaper above the glass.
     */
    private void growFrameGlassUnderSystemBars(@NonNull View body) {
        ViewGroup.LayoutParams params = body.getLayoutParams();
        if (!(params instanceof ViewGroup.MarginLayoutParams)) return;
        View root = findViewById(R.id.activity_termux_root_view);
        int top = Math.max(mLastStatusBarInsetTop, root == null ? 0 : root.getPaddingTop());
        int bottom = (root == null ? 0 : root.getPaddingBottom()) + mBottomKeptPx;
        ViewGroup.MarginLayoutParams margins = (ViewGroup.MarginLayoutParams) params;
        if (margins.topMargin == -top && margins.bottomMargin == -bottom) return;
        margins.topMargin = -top;
        margins.bottomMargin = -bottom;
        body.setLayoutParams(margins);
    }

    /** The shared frame the Docked gutter glass is drawing, for the blur cache's in-use scan. */
    @Nullable private Bitmap mFrameGutterBackdropBitmap;
    /** What the gutter glass was last dressed with; null while it is not shown. */
    @Nullable private List<Object> mFrameGutterKey;
    /** Whether the terminal's backdrop view currently carries the Docked gutter glass. */
    private boolean mFrameGutterShown;
    /**
     * Whether the appearance editor holds the window opaque behind its scaled frame; the window
     * background reset leaves the decor alone while it does.
     */
    /** The glass drawable the gutter was last given, so a reset to a plain colour is told apart. */
    @Nullable private android.graphics.drawable.Drawable mFrameGutterDrawable;

    /**
     * Paints the terminal's own field. Square and full-bleed by default, which is what makes the
     * terminal, the strip under the dock and the gesture-pill area read as one surface; with a
     * Docked corner radius set it becomes a bounded rounded slab inset by the Margin knob, sharing
     * both numbers with the frame line and the pane clip so the three never disagree on an edge.
     */
    private void applyTerminalBodySurface(@NonNull View bodySurface, int color, boolean visible) {
        ViewGroup.LayoutParams params = bodySurface.getLayoutParams();
        if (params instanceof ViewGroup.MarginLayoutParams) {
            ViewGroup.MarginLayoutParams marginParams = (ViewGroup.MarginLayoutParams) params;
            // Below the bar the canvas reaches up behind, where the canvas used to start
            // (PageTopInsets.bodySurfaceTopPx).
            int top = mBodySurfaceTopPx;
            // And ends where the front page's room does (applyBodySurfaceBottom).
            int bottom = mBodySurfaceBottomPx;
            if (marginParams.leftMargin != 0 || marginParams.topMargin != top
                || marginParams.rightMargin != 0 || marginParams.bottomMargin != bottom) {
                marginParams.setMargins(0, top, 0, bottom);
                bodySurface.setLayoutParams(marginParams);
            }
        }
        bodySurface.setBackground(null);
        bodySurface.setBackgroundColor(color);
        bodySurface.setVisibility(visible ? View.VISIBLE : View.GONE);
    }

    /**
     * Arc clearance the pane tree lays out inside, so no glyph sits under the rounded clip. Applied
     * as padding rather than as a margin on purpose: the clip follows the host's bounds, so only
     * padding puts distance between the content's corners and the arc.
     */
    private static void applyPaneHostCornerPadding(@NonNull View paneHost, int paddingPx) {
        if (paneHost.getPaddingLeft() == paddingPx && paneHost.getPaddingTop() == paddingPx
            && paneHost.getPaddingRight() == paddingPx
            && paneHost.getPaddingBottom() == paddingPx)
            return;
        paneHost.setPadding(paddingPx, paddingPx, paddingPx, paddingPx);
    }

    /**
     * Whether the terminal's glass pane is configured on: border enabled with a blur radius or a
     * grain amount behind it, in wallpaper mode. The pane-count gate lives with the border's own
     * ({@code applyTerminalBorderAppearance} folds both in), since glass and border share a frame.
     */
    private boolean isTerminalGlassConfigured() {
        return mPreferences != null
            && shouldUseWallpaperPassthroughMode()
            && (mPreferences.getTerminalGlassBlurRadius() > 0
                || mPreferences.getTerminalGlassGrain() > 0);
    }

    /**
     * Whether every terminal pane is currently a glass slab of its own.
     *
     * <p>Gated on the border switch because the border is conceptually the pane's edge: with glass
     * on, each pane's lit rim <em>is</em> that border, drawn per pane instead of once around the
     * whole terminal. Deliberately not gated on the pane count — one pane is simply one slab, which
     * is what makes a split read as several floating terminals rather than a sheet with lines on it.
     */
    private boolean isTerminalPaneGlassActive() {
        // Under both Styles: a Floating card's slab, or the Docked insert's, which keeps its
        // frost, tint, grain and Legibility veil.
        return isTerminalGlassConfigured() && mPreferences.isTerminalBorderEnabled();
    }

    /**
     * The glass supplier the pane controller paints from. Every value it reads is the same one the
     * dock and status surfaces use, so "Match all surfaces" moves the panes with everything else.
     */
    @NonNull
    private com.termux.app.terminal.PaneSurfaceStyle paneSurfaceStyle() {
        return new com.termux.app.terminal.PaneSurfaceStyle() {
            @Override public boolean isPaneGlassActive() {
                return isTerminalPaneGlassActive();
            }

            @Override public boolean paneBorderEnabled() {
                return mPreferences != null && mPreferences.isTerminalBorderEnabled();
            }

            @Override @Nullable public Bitmap paneGlassBlurFrame() {
                return obtainTerminalPaneGlassFrame();
            }

            @Override public boolean paneGlassCrossfade() {
                int radiusDp = mPreferences != null ? mPreferences.getTerminalGlassBlurRadius() : 0;
                return mChrome.blurCache().isCrossfadedRadius(radiusDp)
                    && !ReducedMotion.isEnabled(TermuxActivity.this);
            }

            @Override @NonNull public Rect paneGlassBlurFrameRect() {
                return mChrome.blurCache().frameRectRef();
            }

            @Override @NonNull public com.termux.app.chrome.WallpaperParallax wallpaperParallax() {
                return mWallpaperParallax;
            }

            @Override @Nullable public com.termux.app.chrome.GlassRefraction.Look paneGlassRefraction() {
                // Inside a joined Docked frame the insert is a hole in one sheet, not a lens over
                // the wallpaper: a bend at its rim pulls the blurred wallpaper inward where the
                // frame glass a pixel outside shows it unbent, which read as colour smeared along
                // the inner border. The rim's light stays; only the pull goes.
                if (mFancierGlassLook != null && frameStandsDown())
                    return new com.termux.app.chrome.GlassRefraction.Look(0,
                        mFancierGlassLook.edgeWidthDp, mFancierGlassLook.edgeLightPercent)
                        .withColour(mFancierGlassLook.vibrancyPercent, mFancierGlassLook.frameTint);
                // Depth and Edge are Global's alone (ADR 0031 §2): the terminal holds none.
                return mFancierGlassLook;
            }

            @Override @Nullable public Bitmap paneGlassClearFrame() {
                // Asked of the look the slabs actually draw: the joined frame's insert keeps no
                // bend and so no clarity, and holds no clear frame for it.
                return obtainTerminalPaneGlassClearFrame(paneGlassRefraction());
            }

            @Override @Nullable public ColorFilter paneGlassFrostFilter() {
                return com.termux.app.chrome.GlassFilters.frost(mPreferences != null ? mPreferences.getTerminalBackgroundOpacity() : 100);
            }

            @Override @Nullable public Bitmap wallBehindFrame() {
                View wallpaperFrame = findViewById(R.id.activity_termux_root_view);
                if (!shouldUseWallpaperPassthroughMode() || wallpaperFrame == null) return null;
                // Radius 0 is the capture itself: the wallpaper as the wall shows it.
                Bitmap frame = mChrome.blurCache().obtain(0, wallpaperFrame);
                mWallBehindFrame = frame != null && !frame.isRecycled() ? frame : null;
                return mWallBehindFrame;
            }

            @Override public int wallBehindColor() {
                // Exactly what the wall's ground was last painted with, not a re-derivation of
                // it: the root's dim in wallpaper mode (which folds the terminal tint in when the
                // panes have no slab of their own), the terminal surface over the base colour
                // otherwise. Every time the two were computed separately they drifted apart, and
                // the arcs showed as four faint squares a shade off the wall beside them.
                return wallGroundColor();
            }

            @Override public int paneGlassTintColor() {
                // Under both Styles the pane is the frame's glass until Darkness is raised: the
                // Docked insert reads as a window by the hairline round its opening, not by tone.
                if (!shouldShowTerminalOverlaySurface()) return Color.TRANSPARENT;
                return mChrome.glass().look(mPreferences != null
                        ? mPreferences.getTerminalTintStrength()
                        : TermuxPreferenceConstants.TERMUX_APP.DEFAULT_SURFACE_GLOBAL_TINT)
                    .flatTint(resolveTerminalSurfaceColor());
            }

            @Override public int paneGlassVeil(@NonNull Rect rootRect) {
                return paneGlassVeil(rootRect, new Rect(rootRect));
            }

            @Override public int paneGlassVeil(@NonNull Rect rootRect, @NonNull Object key) {
                // The terminal pane band (appearance-layout-editor SPEC §2): the scheme's default
                // foreground and its dim, veiled toward the terminal's own background. Off the
                // wallpaper the text stands on the palette's own background (terminalTextGround)
                // and nothing is measured; a pane with no slab is asked too (PaneGlass), so the
                // ground follows its tint under every Look.
                if (mChrome == null || !shouldUseWallpaperPassthroughMode()) return Color.TRANSPARENT;
                updateEvenOutPolicy();
                int foreground = com.termux.terminal.TerminalColors.COLOR_SCHEME
                    .mDefaultColors[com.termux.terminal.TextStyle.COLOR_INDEX_FOREGROUND];
                return mChrome.ink().terminalPane(rootRect, key, paneGlassTintColor(),
                    com.termux.app.chrome.OnGlass.opaque(resolveTerminalSurfaceColor()),
                    com.termux.app.chrome.OnGlass.opaque(foreground),
                    com.termux.app.terminal.PaneGlass.dimTerminalInk(foreground)).veil;
            }

            @Override @Nullable
            public android.graphics.ColorMatrix paneGlassEvenOut(@NonNull Rect rootRect) {
                return paneGlassEvenOut(rootRect, new Rect(rootRect));
            }

            @Override @Nullable
            public android.graphics.ColorMatrix paneGlassEvenOut(@NonNull Rect rootRect,
                                                                 @NonNull Object key) {
                if (mChrome == null) return null;
                return mChrome.ink().evenOutMatrix(rootRect, key);
            }

            @Override public void paneGlassPark(@NonNull Object key, boolean parked) {
                if (mChrome != null) mChrome.ink().parkPane(key, parked);
            }

            @Override public void paneGlassForget(@NonNull Object key) {
                if (mChrome != null) mChrome.ink().forgetPane(key);
            }

            @Override public int paneGlassGeneration() {
                if (mChrome == null) return 0;
                // The level and the Opacity are what move the policy while no pane is re-dressed;
                // a theme change re-dresses the panes itself. Two cached preference reads, and the
                // policy is rebuilt only when one of them moved.
                com.termux.shared.termux.settings.preferences.TerminalContrastLevel level =
                    mPreferences != null
                        ? com.termux.app.chrome.LegibilityLevel.terminalContrast(mPreferences) : null;
                int strength = evenOutStrengthNow();
                if (level != mEvenOutLevelSeen
                        || strength != mEvenOutStrengthSeen) {
                    mEvenOutStrengthSeen = strength;
                    mEvenOutLevelSeen = level;
                    updateEvenOutPolicy();
                }
                return mChrome.ink().evenOutGeneration();
            }

            @Override public boolean paneGlassRimWanted() {
                // Every look wears the dock's gradient rim; over a slab whose program draws its
                // own edge, the pane's border yields to that edge (PaneRim.SlabEdge).
                return true;
            }

            @Override public boolean paneOpeningLine() {
                // Docked: the insert is a window in the frame, read by its line, not by its tone.
                return !isRoundedStyle(com.termux.app.place.SeamDress.Surface.FRAME);
            }

            @Override @Nullable public Drawable paneGlassRim(float radiusPx) {
                return paneGlassRimWanted() ? mChrome.glass().rimDrawable(radiusPx) : null;
            }

            @Override @Nullable public Drawable paneRimDrawable(float radiusPx) {
                return mChrome.glass().rimDrawable(radiusPx);
            }

            @Override public boolean paneAttentionPulses() {
                return !isLazyModeEnabled() && !ReducedMotion.isEnabled(TermuxActivity.this);
            }

            @Override @Nullable public Drawable paneGlassGrainLayer() {
                int grain = paneGlassGrainStrength();
                return grain > 0 ? mChrome.glass().grainLayer(grain) : null;
            }

            @Override public int paneGlassGrainStrength() {
                return mPreferences != null ? mPreferences.getTerminalGlassGrain() : 0;
            }

            @Override public float paneGlassCornerRadiusPx() {
                // What a pane follows while its own radius is on the sentinel: the shape the style
                // gives the terminal's edge, which is the dock capsule's while Floating.
                return terminalEdgeCornerRadiusPx();
            }

            @Override public int paneCornerRadiusDp() {
                // The pane wears Corners under both Styles, a stored 0 being square corners.
                return Math.round(layoutCornersPx(com.termux.app.place.SeamDress.Surface.FRAME) / getResources().getDisplayMetrics().density);
            }

            @Override public int paneGapDp() {
                return terminalPaneGapDp();
            }

            @Override @NonNull public com.termux.app.chrome.LookGlassStyle lookGlass() {
                return lookGlassStyle();
            }
        };
    }

    /** The Look's glass Home's widgets wear; see {@link #lookGlassStyle}. */
    @Nullable private com.termux.app.chrome.LookGlassStyle mLookGlass;

    /**
     * The Look's own glass (Global's values) as a pane style, which Home's widgets wear whatever a
     * detached surface does. It samples the same blur cache, wallpaper frame and Fancier Glass
     * look as the panes, in the chrome's glass base colour.
     */
    @NonNull
    private com.termux.app.chrome.LookGlassStyle lookGlassStyle() {
        if (mLookGlass == null) {
            mLookGlass = new com.termux.app.chrome.LookGlassStyle(this, mChrome,
                new com.termux.app.chrome.LookGlassStyle.Host() {
                    @Override public TermuxAppSharedPreferences preferences() { return mPreferences; }
                    @Override public View wallpaperFrame() {
                        return findViewById(R.id.activity_termux_root_view);
                    }
                    @Override public boolean wallpaperBlurs() { return wallpaperSampleable(); }
                    @Override public int glassBaseColor() { return resolveAccessoryGlassBaseColor(); }
                    @Override public com.termux.app.chrome.GlassRefraction.Look refraction() {
                        // The Widgets element's own Depth and Edge where it holds them (ADR 0017).
                        return com.termux.app.chrome.ElementGlass.refraction(mPreferences, com.termux.shared.termux.settings.preferences.LookGrid.Element.WIDGETS,
                            pageId(), mFancierGlassLook);
                    }
                    // The Home page the widgets stand on, whatever is in front: a surface only
                    // Home has keeps Home's look across a crossing and never blends (ADR 0029
                    // section 8). Read through the resting page it took the Terminal's look on
                    // the Terminal and through a crossing back, and changed at the landing.
                    @Override public int pageId() {
                        return com.termux.app.place.SeamDress.lookPageId(
                            com.termux.app.page.PageKind.HOME, mHomeSeam.pageInFront(), -1,
                            terminalLookPageId());
                    }
                    @Override public com.termux.app.chrome.WallpaperParallax parallax() {
                        return mWallpaperParallax;
                    }
                });
        }
        return mLookGlass;
    }

    /** The open drawer card's own glass the section switch wears; see {@link #drawerCardGlassStyle}. */
    @Nullable private com.termux.app.chrome.DrawerCardGlassStyle mDrawerCardGlass;

    /**
     * The drawer card's surface as a pane style: the dock's blur radius (the card's frost holds
     * that entry), the sheets' refraction and the sheets' tint, none of Global's Look.
     */
    @NonNull
    private com.termux.app.chrome.DrawerCardGlassStyle drawerCardGlassStyle() {
        if (mDrawerCardGlass == null) {
            mDrawerCardGlass = new com.termux.app.chrome.DrawerCardGlassStyle(this, mChrome,
                new com.termux.app.chrome.DrawerCardGlassStyle.Host() {
                    @Override public TermuxAppSharedPreferences preferences() { return mPreferences; }
                    @Override public View wallpaperFrame() {
                        return findViewById(R.id.activity_termux_root_view);
                    }
                    @Override public boolean wallpaperPassthrough() {
                        return shouldUseWallpaperPassthroughMode();
                    }
                    @Override public int cardBlurDp() { return getEffectiveExtraKeysBlurRadius(); }
                    @Override public int glassBaseColor() {
                        return com.termux.app.terminal.inappkeyboard.InAppKeyboardPaletteFactory
                            .resolveDockGlassBaseColor(TermuxActivity.this);
                    }
                    // The sheets element, as WallpaperFrostPainter.sheets() answers it.
                    @Override public com.termux.app.chrome.GlassRefraction.Look refraction() {
                        return com.termux.app.chrome.ElementGlass.refraction(mPreferences, null,
                            stackLookPage(), mFancierGlassLook);
                    }
                    @Override public com.termux.app.chrome.WallpaperParallax parallax() {
                        return mWallpaperParallax;
                    }
                });
        }
        return mDrawerCardGlass;
    }

    /**
     * The shared pre-blurred wallpaper frame the panes draw, remembered so the blur cache never
     * recycles a bitmap a pane is still painting from (the panes hold it in a custom view rather
     * than an ImageView, so the frost-in-use scan cannot find it by drawable).
     *
     * <p>Null while the readable picture is one nobody chose ({@link WallpaperPicture#NO_STILL}):
     * the pane then wears its tint and grain alone, which {@code PaneGlassBackdropView} draws for a
     * null frame, and keeps the rim and insets a glass pane has. Same gate as the bands', so the
     * whole app either blurs a picture or none of it does.
     */
    @Nullable
    private Bitmap obtainTerminalPaneGlassFrame() {
        int radiusDp = mPreferences != null ? mPreferences.getTerminalGlassBlurRadius() : 0;
        View wallpaperFrame = findViewById(R.id.activity_termux_root_view);
        if (radiusDp <= 0 || wallpaperFrame == null || !isTerminalPaneGlassActive()
                || !wallpaperSampleable()) {
            mPaneGlassFrame = null;
            return null;
        }
        Bitmap frame = mChrome.blurCache().obtain(radiusDp, wallpaperFrame);
        mPaneGlassFrame = frame != null && !frame.isRecycled() ? frame : null;
        return mPaneGlassFrame;
    }

    /**
     * The clearer frame the panes' bent edges show (Fancier Glass's edge clarity), at
     * {@link com.termux.app.chrome.GlassRefraction#CLARITY_RADIUS_DP} from the same cache and the
     * same wallpaper frame as {@link #obtainTerminalPaneGlassFrame}, under the same gate, or null
     * when the look asks for none or that blur is still in flight. Remembered for the cache's
     * in-use scan as the frame is; its landing changes the panes' style key, so the pass the
     * cache's ready callback runs re-dresses them.
     */
    @Nullable
    private Bitmap obtainTerminalPaneGlassClearFrame(
            @Nullable com.termux.app.chrome.GlassRefraction.Look look) {
        int radiusDp = mPreferences != null ? mPreferences.getTerminalGlassBlurRadius() : 0;
        View wallpaperFrame = findViewById(R.id.activity_termux_root_view);
        if (wallpaperFrame == null || !isTerminalPaneGlassActive() || !wallpaperSampleable()) {
            mPaneGlassClearFrame = null;
            return null;
        }
        Bitmap clear = com.termux.app.chrome.WallpaperFrostPainter.sharpFrame(mChrome.blurCache(),
            look, radiusDp, wallpaperFrame);
        mPaneGlassClearFrame = clear != null && !clear.isRecycled() ? clear : null;
        return mPaneGlassClearFrame;
    }

    /**
     * Dresses the terminal glass backdrop: the shared pre-blurred wallpaper frame shown through the
     * bordered rect (matrix-positioned, so a resize never allocates a terminal-sized bitmap the way
     * a crop would — this surface resizes on every keyboard toggle), with the terminal tint and the
     * film grain layered as its foreground. Localises what used to be the full-screen dim.
     */
    /**
     * Re-dress the panes' glass. Every pane draws the shared pre-blurred wallpaper frame through
     * its own rect, so a wallpaper change, a blur-radius change or a layout move all resolve here
     * rather than in a per-surface bitmap.
     */
    private void updateTerminalGlassFrost() {
        // Whether the slabs refract is decided before the style is read: a knob the editor just
        // turned, or the switch flipped in Settings, has to land on this very pass.
        Trace.beginSection("Frost.terminal.backdrop");
        syncFancierGlassLook();
        // The backdrop shows the very frame the crops below are cut from, so it is dressed in this
        // same pass: a backdrop and a glass that disagreed for even one frame would show as the
        // misalignment this whole mode exists to remove.
        updateWallpaperBackdrop();
        // The frame just asked for may be a different width from the last one (the switch, a
        // rotation, a new wallpaper), and a different width puts the resting place at a different
        // offset into it — whether or not the panes' own dress changed below.
        syncWallpaperParallax();
        Trace.endSection();
        // The Docked gutter's glass samples the same frame, so it follows it as it lands.
        Trace.beginSection("Frost.terminal.gutter");
        View gutterBody = frameGlassHost();
        if (gutterBody != null && shouldUseWallpaperPassthroughMode())
            applyFrameGutterGlass(gutterBody, isTerminalPaneGlassActive() && hasDockedFrameCard());
        Trace.endSection();
        // The open drawer's section switch wears the card's own glass and frame.
        if (mSheets.appDrawerControllerIfBuilt() != null)
            mSheets.appDrawerControllerIfBuilt().onGlassChanged();
        // The key's page bar, opened while its raised blur was baking, wears the frame that landed.
        if (mPageBar != null) mPageBar.onGlassFramesMoved();
        if (mPaneController == null) return;
        com.termux.app.terminal.PaneSurfaceStyle style = paneSurfaceStyle();
        // This runs behind every chrome apply, several times a page change, and the style is a
        // live view that looks new each time: re-dress the panes and pages only when what it
        // answers has moved.
        com.termux.app.terminal.PaneStyleKey key = com.termux.app.terminal.PaneStyleKey.of(style);
        com.termux.app.terminal.PaneStyleKey previousKey = mAppliedPaneStyleKey;
        if (key.equals(previousKey)) return;
        mAppliedPaneStyleKey = key;
        if (key.sameButWallGround(previousKey)) {
            // The ground colour changes on every Home <-> Terminal crossing and only the Display
            // page's corner mask reads it.
            Trace.beginSection("Frost.terminal.wallGround");
            try {
                if (mPaneWallController != null) mPaneWallController.applyWallGround(style);
            } finally {
                Trace.endSection();
            }
            return;
        }
        Trace.beginSection("Frost.terminal.paneStyle");
        try {
            mPaneController.setSurfaceStyle(style);
            mStatusRow.dressBand(style);
            if (mPaneWallController != null) mPaneWallController.applyStyle(style);
        } finally {
            Trace.endSection();
        }
    }

    /** What {@link #updateTerminalGlassFrost} last dressed the panes with; null forces a pass. */
    @Nullable private com.termux.app.terminal.PaneStyleKey mAppliedPaneStyleKey;

    /**
     * Fancier Glass as it stands this instant: the switch, the three knobs, Android 13, and a
     * wallpaper the launcher set — see {@link com.termux.app.chrome.FancierGlassPolicy}. Null is
     * the default mode.
     */
    @Nullable
    private com.termux.app.chrome.GlassRefraction.Look currentFancierGlassLook() {
        if (mPreferences == null) return null;
        // Lazy mode turns the refraction look off with the other effects.
        if (isLazyModeEnabled()) return null;
        if (!com.termux.app.chrome.FancierGlassPolicy.active(Build.VERSION.SDK_INT,
                mPreferences.isFancierGlassEnabled(), shouldUseManagedWallpaperBlurSource())) {
            return null;
        }
        // The glass's colour rides on the look: the program applies it to the backdrop, so the
        // stored frames and the live pictures carry none (#321).
        com.termux.app.chrome.WallpaperBlurCache cache = mChrome.blurCache();
        return com.termux.app.chrome.GlassRefraction.Look.of(mPreferences)
            .withColour(cache.glassVibrancyPercent(), cache.glassFrameTint());
    }

    /**
     * Re-reads {@link #mFancierGlassLook} and, when it moved — the switch, a knob, a wallpaper the
     * launcher did or did not set — makes this pass re-dress every glass surface: the dock, the
     * strip and the keyboard through their backdrop entries, the panes through a style key that no
     * longer matches; the frosts restate the look on every pass of their own. At the head of the
     * apply and of the panes' pass, so no surface in a pass reads a different answer.
     */
    private void syncFancierGlassLook() {
        com.termux.app.chrome.GlassRefraction.Look look = currentFancierGlassLook();
        boolean live = currentLiveBlur(look != null);
        // A policy event for the glass service when it moved: every Live kind follows at once.
        mGlass.setLiveOn(live);
        // Light to dark makes every legibility correction stale; the same report again does not.
        mGlass.legibility().onSchemeChanged((getResources().getConfiguration().uiMode
            & android.content.res.Configuration.UI_MODE_NIGHT_MASK)
            == android.content.res.Configuration.UI_MODE_NIGHT_YES);
        if (java.util.Objects.equals(look, mFancierGlassLook) && live == mLiveBlur) return;
        mFancierGlassLook = look;
        if (live != mLiveBlur) {
            mLiveBlur = live;
            // Off: every live layer goes now; the pass below puts the stored frames back up.
            if (!live && mLiveBackdrop != null) mLiveBackdrop.releaseAll();
        }
        mChrome.ledger().markAllBackdropsDirty();
        mAppliedPaneStyleKey = null;
    }

    /** {@link com.termux.app.chrome.LiveBlurPolicy} as it stands this instant; the switch first, so off costs nothing. */
    private boolean currentLiveBlur(boolean fancierGlassActive) {
        if (mPreferences == null || !mPreferences.isLiveBlurEnabled() || !fancierGlassActive)
            return false;
        android.os.PowerManager power = getSystemService(android.os.PowerManager.class);
        return com.termux.app.chrome.LiveBlurPolicy.live(Build.VERSION.SDK_INT, true, true,
            wallpaperBackdropMode() == WallpaperBackdropPolicy.Mode.SELF_DRAWN,
            power != null && power.isPowerSaveMode(), mPreferences.isLowMemoryPresetEnabled(),
            isLazyModeEnabled());
    }

    /**
     * The dock backdrop's live picture, attached at the stored frame's blur radius; null when Live
     * is off or the recorder is full, and the stored frame stands.
     */
    @Nullable
    private android.graphics.drawable.Drawable liveDockPicture(@NonNull ImageView backdrop,
                                                               int blurRadiusDp) {
        com.termux.app.chrome.LivePicture picture = attachLivePicture(backdrop, blurRadiusDp,
            com.termux.app.chrome.LiveBackdrop.RANK_CHROME, DOCK_GLASS, mDockGlassRedress);
        return picture == null ? null : picture.drawable();
    }

    /**
     * {@code surface}'s live picture at {@code blurRadiusDp} and {@code rank} in the budget's
     * order, the recorder made on first use. The surface registers as {@code element} with the
     * glass service the first time; null, and any picture it had dropped, while its granted kind
     * is not Live.
     */
    @Nullable
    private com.termux.app.chrome.LivePicture attachLivePicture(@NonNull View surface,
            int blurRadiusDp, int rank, @NonNull String element,
            @Nullable com.termux.app.glass.GlassService.Redress redress) {
        return attachLivePicture(surface, blurRadiusDp, rank, element, redress, null);
    }

    /** As above; {@code layer} is the window layer the surface stands in, null for the rank's own. */
    @Nullable
    private com.termux.app.chrome.LivePicture attachLivePicture(@NonNull View surface,
            int blurRadiusDp, int rank, @NonNull String element,
            @Nullable com.termux.app.glass.GlassService.Redress redress,
            @Nullable com.termux.app.window.WindowLayer layer) {
        com.termux.app.glass.GlassKind kind = mGlass.grantedTo(element, surface);
        if (kind == null) {
            int priority = rank == com.termux.app.chrome.LiveBackdrop.RANK_FLOAT
                ? com.termux.app.glass.GlassEntry.PRIORITY_FLOAT
                : com.termux.app.glass.GlassEntry.PRIORITY_DOCK;
            // The dock stands in the chrome layer; floats and widgets on the pages.
            kind = mGlass.register(new com.termux.app.glass.GlassEntry(element, surface,
                com.termux.app.glass.GlassKind.LIVE, priority,
                layer != null ? layer
                : priority == com.termux.app.glass.GlassEntry.PRIORITY_DOCK
                    ? com.termux.app.window.WindowLayer.CHROME
                    : com.termux.app.window.WindowLayer.PAGES, null), redress);
        }
        if (kind != com.termux.app.glass.GlassKind.LIVE) {
            if (mLiveBackdrop != null) mLiveBackdrop.detach(surface);
            return null;
        }
        com.termux.app.chrome.LiveBackdrop recorder = liveBackdrop();
        if (recorder == null) return null;
        return recorder.attach(surface,
            blurRadiusDp * getResources().getDisplayMetrics().density, rank);
    }

    /** The drawer search capsule's name in the glass registry: one surface, whatever its shape. */
    private static final String DRAWER_SEARCH_GLASS = "drawer-search";

    /**
     * The search capsule's Live picture: the slab registers while the drawer is open, wanting
     * Live in the sheets layer at a float's place in the budget, and takes its picture from the
     * recorder, which draws the list beneath it in its local layer. Null while the service grants
     * Wallpaper (the slab then draws the stored frame).
     */
    @Nullable
    private com.termux.app.chrome.LivePicture wearDrawerSearchGlass(@NonNull View slab,
            int blurDp, @Nullable Runnable redress) {
        return attachLivePicture(slab, blurDp, com.termux.app.chrome.LiveBackdrop.RANK_FLOAT,
            DRAWER_SEARCH_GLASS, redress == null ? null : k -> redress.run(),
            com.termux.app.window.WindowLayer.SHEETS);
    }

    /** The capsule's slab gave its glass back: its Live slot and picture go. */
    private void dropDrawerSearchGlass(@NonNull View slab) {
        if (mLiveBackdrop != null) mLiveBackdrop.detach(slab);
        if (mGlass.grantedTo(DRAWER_SEARCH_GLASS, slab) != null) {
            mGlass.unregister(DRAWER_SEARCH_GLASS);
        }
    }

    /** The window's recorder, made on first use; null before the content root exists. */
    @Nullable
    private com.termux.app.chrome.LiveBackdrop liveBackdrop() {
        if (mLiveBackdrop == null) {
            View root = findViewById(R.id.terminal_root_container);
            if (!(root instanceof ViewGroup)) return null;
            mLiveBackdrop = new com.termux.app.chrome.LiveBackdrop((ViewGroup) root);
            // Recorded by the glass commit, the frame table's last step.
            mLiveBackdrop.setService(mGlass);
            mGlass.setLiveCore(mLiveBackdrop);
            // A swipe holds the wall's pages in a page layer of their own under live glass.
            View wall = findViewById(R.id.terminal_pane_wall);
            if (wall instanceof com.termux.app.chrome.LiveBackdrop.Wall) {
                mLiveBackdrop.setWall((com.termux.app.chrome.LiveBackdrop.Wall) wall);
            }
            // While the wall moves, live glass samples the stored frame as its ground layer.
            mLiveBackdrop.setGroundSource(new com.termux.app.chrome.LiveBackdrop.GroundSource() {
                @Nullable @Override
                public Bitmap storedFrame(float blurRadiusPx, @NonNull Rect outScreenRect) {
                    com.termux.app.chrome.WallpaperBlurCache cache = mChrome.blurCache();
                    Bitmap frame = cache.peek(Math.round(
                        blurRadiusPx / getResources().getDisplayMetrics().density));
                    if (frame != null) cache.copyFrameRect(outScreenRect);
                    return frame;
                }

                @Override
                public float parallaxOffsetPx() {
                    return mWallpaperParallax.offsetPx();
                }
            });
        }
        return mLiveBackdrop;
    }

    /** The panels' recorder and Live switch ({@link com.termux.app.chrome.PanelBackdrop}). */
    private final com.termux.app.chrome.PanelBackdrop.Source mPanelBackdropSource =
        new com.termux.app.chrome.PanelBackdrop.Source() {
            @Nullable @Override public com.termux.app.chrome.LiveBackdrop recorder() {
                return liveBackdrop();
            }

            @Nullable @Override public com.termux.app.glass.GlassService glass() {
                return mGlass;
            }
        };

    /** Whether the dock's backdrop shows a picture now, stored or live. */
    private boolean accessoryPictureUp(@NonNull ImageView backdrop) {
        return com.termux.app.chrome.SharedFrameDrawable.of(backdrop.getDrawable()) != null
            || (mLiveBackdrop != null && mLiveBackdrop.shows(backdrop.getDrawable()));
    }

    /**
     * Whether a managed wallpaper can pan here and now: the switch is on, the phone animates,
     * the screen is portrait, and the launcher is drawing the wallpaper itself from a managed
     * copy. Every other wallpaper stays still, and so does this one in landscape: the picture is
     * cropped for the portrait screen and a landscape frame already shows it cover-cropped.
     * Parallax needs the self-drawn backdrop because the ROM composites the system wallpaper at
     * one fixed offset — only a picture the launcher paints can move.
     */
    private boolean isWallpaperParallaxAvailable() {
        return mPreferences != null && mPreferences.isWallpaperParallaxEnabled()
            && !isReducedMotionEnabled()
            && getResources().getConfiguration().orientation == Configuration.ORIENTATION_PORTRAIT
            && wallpaperBackdropMode() == WallpaperBackdropPolicy.Mode.SELF_DRAWN
            && shouldUseManagedWallpaperBlurSource();
    }

    /**
     * The rect the wallpaper frame is captured for, in screen coordinates: the decor's rect, and
     * with a managed wallpaper that can pan, as wide as the stored picture is at the screen's
     * height — one and a half screens from the picker, anchored at the screen's left edge, which
     * is where the Home place rests. Every surface samples the frame at its own screen position
     * plus the live offset, so the frame's extra width is exactly the offset's travel. A picture
     * cropped before the wide picker is one screen wide and answers the decor rect: it does not
     * pan, and nothing is zoomed to pretend it can.
     *
     * <p>Also where {@link #mWallpaperParallaxSparePx} is kept current, since every path that
     * cuts or aims at the frame asks for this rect first.</p>
     */
    @NonNull
    private Rect getWallpaperCaptureFrameRect() {
        Rect frame = getManagedWallpaperFrameRect();
        int spanPx = frame.width();
        if (isWallpaperParallaxAvailable()) {
            com.termux.app.chrome.WallpaperSourceFacts facts = wallpaperSourceFacts();
            if (facts.hasManagedSize()) {
                spanPx = com.termux.app.wall.WallParallax.spanPx(facts.managedWidth,
                    facts.managedHeight, frame.width(), frame.height());
            }
        }
        mWallpaperParallaxSparePx = Math.max(0, spanPx - frame.width());
        frame.right = frame.left + spanPx;
        return frame;
    }

    /**
     * Puts the wallpaper where the row is: the offset is a function of the row's live position
     * ({@link com.termux.app.wall.PaneWallController#rowPosition}, spread over the picture by
     * {@link com.termux.app.wall.WallParallax#offsetPx}), so Home's swipe, the seam, a border drag
     * between windows, a window's arrival and a step onto the display window all move the picture on
     * their own curve, and every surface that samples the frame is told to draw again when it
     * moved. Per frame of a slide, so nothing here allocates: one number written, and
     * invalidates. A Home page or a window coming or going re-spreads the picture over the new
     * count, and the picture settles there on a page's spring ({@link #settleWallpaperParallax}):
     * a window opened behind the one in view used to jump the wallpaper under it.
     */
    private void syncWallpaperParallax() {
        syncWallpaperParallax(false);
    }

    /**
     * @param pagesReaimed true from the wall's own offset tick, which re-aims the panes' slabs and
     *                     the Widgets page and the display window itself on every frame: they are not aimed
     *                     a second time here
     */
    private void syncWallpaperParallax(boolean pagesReaimed) {
        int rowCount = mPaneWallController == null ? 0 : mPaneWallController.rowCount();
        boolean recounted = mWallpaperParallaxRowCount > 0 && rowCount != mWallpaperParallaxRowCount;
        mWallpaperParallaxRowCount = rowCount;
        // Held by Edit pages: every surface keeps sampling the one offset until it lets go.
        if (mWallpaperParallaxHeld) return;
        if (mScene != null && mPaneWallController != null) {
            mScene.setPageOffset(com.termux.app.wall.WallParallax.pageFraction(
                mPaneWallController.rowPosition(), rowCount));
        }
        if (recounted) {
            settleWallpaperParallax();
            return;
        }
        int sparePx = mWallpaperParallaxSparePx;
        float offsetPx = liveWallpaperParallaxPx(sparePx);
        if (mWallpaperParallaxSettle != null) {
            offsetPx = com.termux.app.wall.WallParallax.settlingOffsetPx(offsetPx,
                mWallpaperParallaxSettleGapPx, mWallpaperParallaxSettleRemaining, sparePx);
        }
        if (!mWallpaperParallax.setOffsetPx(offsetPx)) return;
        if (mWallpaperBackdropView != null) mWallpaperBackdropView.invalidate();
        // The pane slabs and the tab are re-aimed by the glass service on every frame that draws
        // (SlabAim), so only the pages' own widgets are told here.
        if (!pagesReaimed && mPaneWallController != null) {
            if (mPaneWallController.widgetsPage() != null) mPaneWallController.widgetsPage().onWallMoved();
        }
        if (mParallaxFrostViews == null) {
            mParallaxFrostViews = new View[] {
                findViewById(R.id.accessory_blur_backdrop),
                findViewById(R.id.inapp_keyboard_view_host),
                findViewById(R.id.accessory_under_keyboard_stack),
                findViewById(R.id.command_palette_wallpaper_backdrop),
                findViewById(R.id.terminal_sheet_wallpaper_backdrop),
                findViewById(R.id.app_drawer_wallpaper_backdrop),
                findViewById(R.id.place_off_dock_plank_frost),
                findViewById(R.id.place_az_bar_host_frost),
            };
        }
        for (View frost : mParallaxFrostViews) {
            if (frost != null && frost.getVisibility() == View.VISIBLE) frost.invalidate();
        }
    }

    /** The offset the wall's live position asks for; 0 while nothing pans. */
    private float liveWallpaperParallaxPx(int sparePx) {
        if (sparePx <= 0 || mPaneWallController == null) return 0f;
        return com.termux.app.wall.WallParallax.offsetPx(
            mPaneWallController.rowPosition(), mPaneWallController.rowCount(), sparePx);
    }

    /**
     * Holds the wallpaper where it stands: a settle still running stops where it is, so its
     * animator lets this activity go.
     */
    private void holdWallpaperParallax() {
        android.animation.ValueAnimator settle = mWallpaperParallaxSettle;
        mWallpaperParallaxSettle = null;
        if (settle != null) settle.cancel();
        mWallpaperParallaxHeld = true;
    }

    /**
     * Settles the wallpaper from where it stands now to where the wall's live position puts it,
     * on a page's spring over the distance the wall would have slid for the gap
     * ({@link com.termux.app.wall.WallParallax#settleTravelPx}). A settle already running is
     * replaced, starting from where it had got to. Reduce motion, or nothing to travel, lands it
     * at once.
     */
    private void settleWallpaperParallax() {
        android.animation.ValueAnimator running = mWallpaperParallaxSettle;
        mWallpaperParallaxSettle = null;
        if (running != null) running.cancel();
        int sparePx = mWallpaperParallaxSparePx;
        float gapPx = mWallpaperParallax.offsetPx() - liveWallpaperParallaxPx(sparePx);
        View decor = getWindow() == null ? null : getWindow().getDecorView();
        float travelPx = com.termux.app.wall.WallParallax.settleTravelPx(gapPx,
            mPaneWallController == null ? 0 : mPaneWallController.rowCount(), sparePx,
            decor == null ? 0 : decor.getWidth());
        if (isReducedMotionEnabled()
            || Math.abs(travelPx) <= com.termux.app.wall.SettleSpring.PAGE_REST_PX) {
            syncWallpaperParallax();
            return;
        }
        com.termux.app.wall.SettleSpring spring = com.termux.app.wall.SettleSpring.page(travelPx,
            0f, com.termux.app.AnimationSpeed.springTime(this));
        long durationMs = spring.durationMs(com.termux.app.wall.SettleSpring.PAGE_REST_PX);
        android.animation.ValueAnimator settle = android.animation.ValueAnimator.ofFloat(0f, 1f);
        settle.setDuration(durationMs);
        settle.setInterpolator(new android.view.animation.LinearInterpolator());
        settle.addUpdateListener(animation -> {
            if (mWallpaperParallaxSettle != animation) return;
            float seconds = animation.getAnimatedFraction() * durationMs / 1000f;
            mWallpaperParallaxSettleRemaining = spring.displacementAt(seconds) / travelPx;
            syncWallpaperParallax();
        });
        settle.addListener(new android.animation.AnimatorListenerAdapter() {
            @Override public void onAnimationEnd(android.animation.Animator animation) {
                if (mWallpaperParallaxSettle != animation) return;
                mWallpaperParallaxSettle = null;
                syncWallpaperParallax();
            }
        });
        mWallpaperParallaxSettleGapPx = gapPx;
        mWallpaperParallaxSettleRemaining = 1f;
        mWallpaperParallaxSettle = settle;
        settle.start();
    }

    /**
     * Whether the launcher paints the wallpaper itself or leaves it to the ROM.
     *
     * @see WallpaperBackdropPolicy
     */
    @NonNull
    private WallpaperBackdropPolicy.Mode wallpaperBackdropMode() {
        return WallpaperBackdropPolicy.mode(shouldUseWallpaperPassthroughMode(),
            wallpaperPicture(), !mWallpaperReadPermissionDenied, appOnlyWallpaperOnScreen());
    }

    /**
     * Keeps the window from asking Android to composite the phone's wallpaper behind it while the
     * launcher draws an app-only picture of its own: that is a different picture, and it would
     * show through for the frames before the capture lands (a cold start, a rotation). Any other
     * wallpaper keeps the flag the wallpaper theme gave the window. Only in wallpaper mode, whose
     * theme is the one that carries the flag; a flag compare otherwise.
     */
    private void syncSystemWallpaperBehindWindow(@NonNull WallpaperBackdropPolicy.Mode mode) {
        if (!shouldUseWallpaperPassthroughMode() || getWindow() == null) return;
        boolean show = WallpaperBackdropPolicy.showsSystemWallpaper(mode, appOnlyWallpaperOnScreen());
        boolean showing = (getWindow().getAttributes().flags
            & WindowManager.LayoutParams.FLAG_SHOW_WALLPAPER) != 0;
        if (show == showing) return;
        if (show) getWindow().addFlags(WindowManager.LayoutParams.FLAG_SHOW_WALLPAPER);
        else getWindow().clearFlags(WindowManager.LayoutParams.FLAG_SHOW_WALLPAPER);
    }

    /**
     * Dresses the self-drawn wallpaper behind everything with the shared radius-0 frame.
     *
     * <p>Radius 0 is the capture itself, and the pane wall's corner arcs already ask for it, so the
     * backdrop costs no extra frame and no extra copy. A miss returns null while the blur worker
     * decodes, and the view decides for itself whether the frame it still holds is safe to keep;
     * {@code onBlurFrameReady} brings this pass round again when the new one lands.</p>
     */
    private void updateWallpaperBackdrop() {
        WallpaperBackdropView backdrop = mWallpaperBackdropView;
        if (backdrop == null) return;
        View wallpaperFrame = findViewById(R.id.activity_termux_root_view);
        WallpaperBackdropPolicy.Mode mode = wallpaperBackdropMode();
        syncSystemWallpaperBehindWindow(mode);
        if (wallpaperFrame == null || mode != WallpaperBackdropPolicy.Mode.SELF_DRAWN) {
            backdrop.hide();
            return;
        }
        Bitmap frame = mChrome.blurCache().obtain(0, wallpaperFrame);
        boolean crossfade = mChrome.blurCache().isCrossfadedRadius(0) && !ReducedMotion.isEnabled(this);
        Rect captureRect = getWallpaperCaptureFrameRect();
        // In wallpaper mode the ground strip, above this view, carries every page's dim, so a
        // crossfade's two frames are both dimmed by the same layer and never by one that lags;
        // opaque mode never gets here (SELF_DRAWN is a wallpaper mode).
        backdrop.showFrame(frame, captureRect, Color.TRANSPARENT, crossfade);
    }

    /**
     * The colour the wall's ground is painted with — the wallpaper dim, with the terminal tint
     * folded in when the panes carry no slab of their own. Read by the pane wall's corner arcs and
     * by the self-drawn backdrop, which paints it over its frame the way the root's background
     * paints it over the system wallpaper.
     */
    private int wallGroundColor() {
        if (mWallGroundPainted) {
            if (!shouldUseWallpaperPassthroughMode()) return mWallGroundColor;
            // The page in front wears its own ground (corner arcs, the editor's label ink).
            com.termux.app.wall.PaneWallLayout wall = groundWall();
            return groundOfWallPage(wall == null
                ? com.termux.app.page.PageKind.TERMINAL : wall.currentPage());
        }
        return shouldUseWallpaperPassthroughMode() ? resolveWallpaperBackdropDimColor()
            : getTermuxThemeColor(com.termux.shared.R.attr.termuxColorSurfaceBase,
                R.color.termux_surface_base);
    }

    /**
     * Arms or disarms the panes' glass physics. The rigs themselves live per pane in
     * {@link com.termux.app.terminal.TerminalPaneController}, since with glass on each pane is its
     * own slab and must tip alone.
     */
    private void setupTerminalPlankFx(boolean active) {
        mTerminalGlassActive = active;
    }

    /**
     * Observes (never consumes) touches over the terminal and hands them to the pane under the
     * finger, so scrolling, selecting text or just pressing a pane tips that one physical slab.
     * Overlays that own the screen (drawer, palette, surface editor) mute it, so their gestures
     * never tilt the surface underneath.
     */
    private void feedTerminalPlank(MotionEvent ev) {
        if (!mTerminalGlassActive || mPaneController == null) return;
        if (mSheets.isAppDrawerEngaged() || mSurfaceEditor.isActive() || mSheets.isCommandPaletteOpen()) {
            mPaneController.cancelPaneGlassTouch();
            return;
        }
        mPaneController.dispatchPaneGlassTouch(ev, isReducedMotionEnabled());
    }

    // ---- the ground strip (page-chrome spec C)

    @Nullable private com.termux.app.chrome.GroundStripView mGroundStrip;
    @Nullable private com.termux.app.wall.PaneWallLayout mGroundWall;
    @Nullable private com.termux.app.look.PageLook mGroundLook;
    private final int[] mGroundScratch = new int[8];
    /** The Terminal page's canvas tint and whether its panes are glass, as last dressed. */
    private boolean mGroundGlassPane;
    private int mGroundCanvasTint = Color.TRANSPARENT;
    private int mGroundInkKey;

    /**
     * The page kinds the ground strip reads, one per cell in cell order, through the wall's
     * controller (ADR 0016); the page in view alone before it is built.
     */
    @NonNull
    private java.util.List<com.termux.app.page.PageKind> groundKinds(
            @NonNull com.termux.app.wall.PaneWallLayout wall) {
        return mPaneWallController != null ? mPaneWallController.cellKinds()
            : java.util.Collections.singletonList(wall.currentPage());
    }

    /** The ground strip's stop for the page in view: its cell's index, within the strip. */
    private int groundStop() {
        int at = mPaneWallController != null ? mPaneWallController.currentCellIndex() : 0;
        return Math.max(0, Math.min(mGroundScratch.length - 1, at));
    }

    @Nullable
    private com.termux.app.wall.PaneWallLayout groundWall() {
        if (mGroundWall == null) {
            View wall = findViewById(R.id.terminal_pane_wall);
            if (wall instanceof com.termux.app.wall.PaneWallLayout)
                mGroundWall = (com.termux.app.wall.PaneWallLayout) wall;
        }
        return mGroundWall;
    }

    @Nullable
    private com.termux.app.look.PageLook groundLook() {
        if (mGroundLook == null && mPreferences != null) {
            mGroundLook = new com.termux.app.look.PageLook(
                new com.termux.app.look.PrefsLookStore(mPreferences.getSharedPreferences()));
            mGroundLook.addListener(ids -> runOnUiThread(this::refreshGroundStrip));
        }
        return mGroundLook;
    }

    /**
     * One wall page's ground in wallpaper mode: Home's is the wallpaper as it is (Home's pages
     * have no dim, ADR 0031 §4); every page of the Terminal wears the Terminal's one Wallpaper
     * dim, and the Terminal page's (and a display window's) folds the canvas tint in when the
     * panes are not glass. Opaque mode has the one ground it always had.
     */
    private int groundOfWallPage(@NonNull com.termux.app.page.PageKind wallPage) {
        if (!shouldUseWallpaperPassthroughMode()) return mWallGroundColor;
        // The Assistant page is of the Terminal (ADR 0025) but its pane is its own glass, never
        // the terminal's tint (ADR 0022): its ground is its dim alone.
        boolean terminal = com.termux.app.wall.PaneWallPolicy.isTerminalPlace(wallPage)
            && wallPage != com.termux.app.page.PageKind.ASSISTANT;
        int dim = com.termux.app.terminal.TerminalSurfacePolicy.dimColor(
            com.termux.app.terminal.TerminalSurfacePolicy.pageDimPercent(wallPage,
                terminalWallpaperDimPercent()));
        return com.termux.app.terminal.TerminalSurfacePolicy.pageGround(terminal, mGroundGlassPane,
            mGroundCanvasTint, dim);
    }

    /** Dresses the strip's grounds, position and visibility; hides it in opaque mode. */
    private void refreshGroundStrip() {
        if (mGroundStrip == null) mGroundStrip = findViewById(R.id.ground_strip);
        com.termux.app.chrome.GroundStripView strip = mGroundStrip;
        com.termux.app.wall.PaneWallLayout wall = groundWall();
        if (strip == null) return;
        if (wall == null || !shouldUseWallpaperPassthroughMode()) {
            strip.setVisibility(View.GONE);
            return;
        }
        java.util.List<com.termux.app.page.PageKind> pages = groundKinds(wall);
        int count = Math.min(pages.size(), mGroundScratch.length);
        for (int i = 0; i < count; i++) mGroundScratch[i] = groundOfWallPage(pages.get(i));
        if (count == 0) {
            mGroundScratch[0] = groundOfWallPage(wall.currentPage());
            count = 1;
        }
        int current = Math.min(count - 1, groundStop());
        strip.setWall(wall);
        strip.setCover(getManagedWallpaperFrameRect());
        strip.setGrounds(mGroundScratch, count, current);
        strip.setPosition(current, wall.getWidth(), wall.offsetPx());
        strip.setVisibility(View.VISIBLE);
        // What the ink stands on changed with the page in front: the memoised answers go.
        int key = mGroundScratch[current];
        if (key != mGroundInkKey) {
            mGroundInkKey = key;
            if (mChrome != null) mChrome.ink().invalidate();
        }
    }

    /** Per frame of a slide: only the wall's position moves, nothing is allocated. */
    private void syncGroundStrip(float offsetPx) {
        com.termux.app.chrome.GroundStripView strip = mGroundStrip;
        com.termux.app.wall.PaneWallLayout wall = mGroundWall;
        if (strip == null || wall == null || strip.getVisibility() != View.VISIBLE) return;
        strip.setPosition(groundStop(), wall.getWidth(), offsetPx);
    }

    /** The ground under a screen rect, for the ink: the strip's, else the wall-wide dim. */
    private int groundUnderRect(@NonNull Rect screenRect) {
        com.termux.app.chrome.GroundStripView strip = mGroundStrip;
        if (strip != null && strip.getVisibility() == View.VISIBLE)
            return strip.groundUnder(screenRect);
        return resolveWallpaperBackdropDimColor();
    }

    /**
     * The Terminal's Wallpaper dim, black over the wallpaper behind everything else on its pages
     * (Display and Assistant pages included): 0% shows the wallpaper untouched. Home's pages have
     * none ({@link #groundOfWallPage}).
     */
    private int resolveWallpaperBackdropDimColor() {
        return com.termux.app.terminal.TerminalSurfacePolicy.dimColor(terminalWallpaperDimPercent());
    }

    /** The Terminal card's Wallpaper dim, percent; read at rest, never per frame. */
    private int terminalWallpaperDimPercent() {
        return mPreferences != null ? mPreferences.getTerminalWallpaperDim()
            : TermuxPreferenceConstants.TERMUX_APP.DEFAULT_TERMINAL_WALLPAPER_DIM;
    }

    /**
     * Paints the full-screen root with the terminal-opacity dim so the whole window background is a
     * single uniform surface (terminal, the gap under the floating dock, and the gesture-pill strip
     * all match), with the dock floating on top. Pass {@link Color#TRANSPARENT} to clear it.
     */
    private void applyUnifiedBackgroundDim(int color) {
        View root = mTermuxActivityRootView != null
            ? mTermuxActivityRootView
            : findViewById(R.id.activity_termux_root_view);
        if (root != null) {
            root.setBackgroundColor(color);
        }
        // The self-drawn backdrop covers that background, so it carries the same dim over its own
        // frame — set here, with the root's, so the two can never read differently.
        if (mWallpaperBackdropView != null) mWallpaperBackdropView.setDimColor(color);
        // Soft wallpaper's blur half rides on the same view (SPEC §3.4); its dim is in color.
        com.termux.app.surfaces.SoftWallpaper.apply(mWallpaperBackdropView, mPreferences);
    }

    private void applyTerminalStatusBarSurfaceColor(boolean showSurface, int terminalSurfaceColor) {
        int targetColor;
        if (shouldUseWallpaperPassthroughMode()) {
            // The full-screen root dim already covers the status-bar region uniformly. A seamless
            // status scrim here would dim it a second time, making the notification area read darker
            // than the terminal — so keep the system status bar transparent in wallpaper mode.
            targetColor = Color.TRANSPARENT;
        } else if (shouldEnableSeamlessStatusBackground()) {
            targetColor = terminalSurfaceColor;
        } else {
            targetColor = getTermuxThemeColor(com.termux.shared.R.attr.termuxColorSurfaceBase, R.color.termux_surface_base);
        }
        if (getWindow() != null) {
            getWindow().setStatusBarColor(targetColor);
            if (shouldUseWallpaperPassthroughMode()) {
                // Keep the gesture-pill strip showing only the unified root dim. Re-assert a fully
                // transparent navigation bar with contrast enforcement off so the OS doesn't paint a
                // darker contrast scrim behind the pill that would make the nav area read darker than
                // the terminal. (This removes a scrim; it never adds a layer over the content.)
                getWindow().setNavigationBarColor(Color.TRANSPARENT);
                if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) {
                    getWindow().setNavigationBarContrastEnforced(false);
                }
            }
        }
    }

    private void applyWallpaperOffsetFixIfNeeded() {
        if (!shouldUseWallpaperPassthroughMode()) {
            return;
        }
        if (getWindow() == null || getWindow().getDecorView() == null) {
            return;
        }
        IBinder windowToken = getWindow().getDecorView().getWindowToken();
        if (windowToken == null) {
            return;
        }
        try {
            WallpaperManager wallpaperManager = WallpaperManager.getInstance(this);
            Rect frameRect = getSystemWallpaperFrameRect();
            // suggestDesiredDimensions needs SET_WALLPAPER_HINTS; guard it on its own so a missing
            // permission (or OEM restriction) can't skip the actual offset-centering below it.
            try {
                wallpaperManager.suggestDesiredDimensions(frameRect.width(), frameRect.height());
            } catch (Exception ignored) {
            }
            wallpaperManager.setWallpaperOffsetSteps(1f, 1f);
            wallpaperManager.setWallpaperOffsets(windowToken, 0.5f, 0.5f);
            // Ask the system to render the wallpaper at true size. WindowManager scales the
            // wallpaper by lerp(config_wallpaperMinScale, config_wallpaperMaxScale, 1 - zoomOut)
            // (WallpaperController.zoomOutToScale), so zoomOut 0 is the MAXIMUM scale — 1.10x
            // about the screen centre on stock — and 1 is the minimum, 1.0. The value here used
            // to be 0, which asked for the very zoom the frost math does not model. Measured on
            // Nothing OS (2026-09-09): the ROM renders ~1.08x either way, so there the
            // measured per-ROM zoom (defaultWallpaperRenderZoom) carries the difference. setWallpaperZoomOut is
            // hidden API; launchers reach it by reflection, and when a ROM blocks the call
            // nothing changes from today's behavior.
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.R) {
                try {
                    WallpaperManager.class
                        .getMethod("setWallpaperZoomOut", IBinder.class, float.class)
                        .invoke(wallpaperManager, windowToken, 1f);
                } catch (Throwable t) {
                    Logger.logVerbose(LOG_TAG, "setWallpaperZoomOut unavailable: " + t);
                }
            }
        } catch (Exception e) {
            Logger.logStackTraceWithMessage(LOG_TAG, "Failed to apply wallpaper offset fix", e);
        }
    }

    /**
     * The system's description of its wallpaper as one colour ({@code WallpaperInk#hintColor}),
     * read when the listener registers and whenever the system reports new colours; transparent
     * before then, below API 27, and when the system said nothing.
     */
    @androidx.annotation.ColorInt private int mSystemWallpaperHint = Color.TRANSPARENT;

    /**
     * What the chrome's ink assumes the wallpaper is until it has read one (editor-redesign §8):
     * the system's description while the launcher shows the system wallpaper, which is the case
     * where the launcher may not be able to read it; transparent otherwise, so the launcher's own
     * picture is never described by someone else's colours.
     */
    @androidx.annotation.ColorInt
    private int resolveWallpaperHintColor() {
        return shouldUseWallpaperPassthroughMode() ? mSystemWallpaperHint : Color.TRANSPARENT;
    }

    private void readSystemWallpaperHint(@Nullable WallpaperColors colors) {
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.O_MR1 || colors == null) {
            mSystemWallpaperHint = Color.TRANSPARENT;
            return;
        }
        boolean darkText = Build.VERSION.SDK_INT >= Build.VERSION_CODES.S
            && (colors.getColorHints() & WallpaperColors.HINT_SUPPORTS_DARK_TEXT) != 0;
        int primary = colors.getPrimaryColor().toArgb();
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.S) {
            // No public hint before S: the primary colour's own side is the best there is.
            darkText = androidx.core.graphics.ColorUtils.calculateLuminance(primary) > 0.5d;
        }
        mSystemWallpaperHint = com.termux.app.chrome.WallpaperInk.hintColor(primary, darkText);
    }

    private void registerWallpaperColorsChangedListener() {
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.O_MR1 || mWallpaperColorsChangedListener != null) {
            return;
        }
        try {
            WallpaperManager wallpaperManager = WallpaperManager.getInstance(this);
            readSystemWallpaperHint(wallpaperManager.getWallpaperColors(WallpaperManager.FLAG_SYSTEM));
            mWallpaperColorsChangedListener = (WallpaperColors colors, int which) -> {
                if ((which & WallpaperManager.FLAG_SYSTEM) != 0) {
                    LifecycleTrail.activity("wallpaper-colours", "system wallpaper colours changed");
                    readSystemWallpaperHint(colors);
                    runOnUiThread(this::refreshTerlWallpaperLooks);
                    // A relaunch for the new theme may follow: the wallpaper page's Done waits for it.
                    mAppearance.onWallpaperColoursChanged();
                }
                // The new id first, so nothing that runs from here on cuts a frame for the old one.
                com.termux.app.chrome.WallpaperSourceFacts facts = refreshWallpaperSourceFacts();
                // A wallpaper set outside the launcher is still a wallpaper change: tagged so the
                // surface that refills each radius crossfades into it instead of swapping outright.
                mChrome.blurCache().clearForWallpaperChange();
                // How a wallpaper set outside the launcher reaches us: the picture can have gone
                // from a still to a live wallpaper, or back, and every glass turns on that.
                refreshWallpaperPicture(facts);
                if (!mIsVisible) {
                    return;
                }
                if (mTermuxTerminalSessionActivityClient != null) {
                    mTermuxTerminalSessionActivityClient.refreshMaterialTerminalColorsIfNeeded();
                }
                applyTerminalSurfaceAppearance();
                // Dynamic keyboard swatches follow the Material roles; pinned or imported ones
                // are left exactly as stored. Gated internally on the palette signature moving.
                if (mInAppKeyboard != null) {
                    mInAppKeyboard.refreshMaterialPalette();
                }
                mChrome.requestSync(ChromeRenderer.SCOPE_BACKDROPS | ChromeRenderer.SCOPE_ACCESSORY_RENDER);
            };
            wallpaperManager.addOnColorsChangedListener(mWallpaperColorsChangedListener, mAccessoryRenderHandler);
        } catch (Exception e) {
            Logger.logStackTraceWithMessage(LOG_TAG, "Failed to register wallpaper color listener", e);
            mWallpaperColorsChangedListener = null;
        }
    }

    private void unregisterWallpaperColorsChangedListener() {
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.O_MR1 || mWallpaperColorsChangedListener == null) {
            return;
        }
        try {
            WallpaperManager.getInstance(this).removeOnColorsChangedListener(mWallpaperColorsChangedListener);
        } catch (Exception e) {
            Logger.logStackTraceWithMessage(LOG_TAG, "Failed to unregister wallpaper color listener", e);
        } finally {
            mWallpaperColorsChangedListener = null;
        }
    }

    // -------------------------------------------------------------- "what did that key just do"
    //
    // Tool keys draw a glyph and nothing else, so the row and the keyboard's space-bar swipes are
    // only as discoverable as the guesses people make about them. Every action the dispatcher runs
    // names itself for a beat, on the same pill as every other notice.

    /**
     * Names a dispatched tool in the notice pill; a no-op for tools with no UI title and for
     * self-evident tools — an action whose result is already on screen (a split, a pan, a closed
     * pane) narrates itself, and naming it too was pure clutter. The hint is for what the screen
     * cannot say: invisible results, refusals, off-screen events.
     */
    void showTerminalActionHint(@NonNull String toolName) {
        LauncherToolRegistry.ToolMetadata tool = LauncherToolRegistry.getInstance().getTool(toolName);
        if (tool == null || tool.titleRes == 0 || tool.selfEvident) return;
        // A toggle's name says nothing about where it left things; the hint runs after the
        // action, so the state it reads is the one the tap produced.
        if (LauncherToolRegistry.TOOL_MOUSE_TOGGLE.equals(toolName)) {
            com.termux.app.notice.AppNotice.readout(this, R.drawable.ic_rl_mouse,
                getString(isMouseMode()
                    ? R.string.extra_key_readout_mouse_mode_on
                    : R.string.extra_key_readout_mouse_mode_off));
            return;
        }
        // A place change names its destination for as long as the page is on its way there: the
        // read-out comes up as the wall commits and is taken down by the settle
        // (onWallPageSettled), so it reads as one motion with the page rather than a clock of its
        // own. A second wall tool mid-slide swaps the label in place, and the same settle clears it.
        if (LauncherToolRegistry.CATEGORY_WALL.equals(tool.category) && mPaneWallController != null
                && mPaneWallController.wall().isMoving()) {
            mWallReadoutShowing = true;
            com.termux.app.notice.AppNotice.readout(this, getString(LauncherToolRegistry.titleRes(tool)),
                WALL_READOUT_CEILING_MS, com.termux.app.terminal.io.ExtraKeyActionLabels.iconDrawable(toolName));
            return;
        }
        com.termux.app.notice.AppNotice.readout(this,
            com.termux.app.terminal.io.ExtraKeyActionLabels.iconDrawable(toolName),
            getString(LauncherToolRegistry.titleRes(tool)));
    }

    /** A wall tool's read-out is up, naming the place the slide is heading for, until the settle. */
    private boolean mWallReadoutShowing;
    /** How long that read-out may stand without a settle to take it down. */
    private static final long WALL_READOUT_CEILING_MS = 3000L;

    private int resolveAccessoryGlassBaseColor() {
        // In dark wallpaper mode the glass base deliberately reads the framework's Material You
        // neutral so the dock matches the system exactly; when the chrome belongs to the terminal
        // scheme that bypass would keep every glass surface on the wallpaper palette.
        if (isNightThemeActive() && !LauncherSchemeTheme.isSchemeChromeActive(this)) {
            return resolveMaterialDarkBackgroundColor();
        }
        return getTermuxThemeColor(com.termux.shared.R.attr.termuxColorSurfacePanelHigh, R.color.termux_surface_panel_high);
    }

    private int resolveMaterialDarkBackgroundColor() {
        // The theme's own surface role: with dynamic colour it is the system neutral, without it
        // the M3 baseline, so no framework resource lookup or literal fallback is needed.
        return com.termux.app.material.M3.color(this,
            com.google.android.material.R.attr.colorSurface,
            com.google.android.material.R.color.m3_sys_color_dark_surface);
    }

    private int resolveAccessoryOutlineColor() {
        return getTermuxThemeColor(com.termux.shared.R.attr.termuxColorOutlineVariant, R.color.termux_outline_variant);
    }

    /** Wallpaper-derived accent (Material You primary) used across the dock's reactive glass treatment. */
    private int resolveDockAccentColor() {
        return MaterialColors.getColor(this, androidx.appcompat.R.attr.colorPrimary,
            ContextCompat.getColor(this, R.color.termux_primary));
    }












    /** Cached light-scatter filter applied to the blurred wallpaper backdrop. */


    /**
     * The dock's and the under-pill strip's refraction (API 33+), applied as a {@code RenderEffect}
     * over their backdrops. The program itself is the one every glass surface shares — see
     * {@link com.termux.app.chrome.GlassRefraction}; these two keep the effect route because the
     * key-press lens rides it.
     */
    private final com.termux.app.chrome.GlassEffects mGlassEffects =
        new com.termux.app.chrome.GlassEffects(new com.termux.app.chrome.GlassEffects.Host() {
            @Override public float density() {
                return getResources().getDisplayMetrics().density;
            }
            @Nullable @Override public View dockBackdrop() {
                return findViewById(R.id.accessory_blur_backdrop);
            }
            @Nullable @Override public float[] peekGlassRect() {
                return TermuxActivity.this.peekGlassRect();
            }
            @Nullable @Override public com.termux.app.chrome.GlassRefraction.Look fancierLook() {
                return mFancierGlassLook;
            }
            @Override public float dockCover() {
                return mDockGlassCover;
            }
            @Override public void applyDockSurfaceGlass(
                @NonNull com.termux.app.chrome.GlassRefraction.Program program) {
                mDock.applyDockSurfaceGlass(program);
            }
            @Override public boolean keyLensActive() {
                return mKeyLensActive;
            }
            @Override public float keyLensIntensity() {
                return mKeyLensIntensity;
            }
            @Override public void keyLens(@NonNull float[] out) {
                out[0] = mKeyLensCx;
                out[1] = mKeyLensCy;
                out[2] = mKeyLensHx;
                out[3] = mKeyLensHy;
                out[4] = mKeyLensRadius;
            }
        });

    /** Where the dock host's origin sits in its backdrop's pixels, for mapping a pressed key into it. */
    private float mGlassOriginLeft, mGlassOriginTop;

    /**
     * What Fancier Glass draws right now, or null in the default mode — see
     * {@link com.termux.app.chrome.FancierGlassPolicy}. Re-read at the head of every apply
     * ({@link #syncFancierGlassLook}) rather than per surface: the answer asks Android for the
     * wallpaper id, and every glass surface in a pass reads it.
     */
    @Nullable private com.termux.app.chrome.GlassRefraction.Look mFancierGlassLook;

    /** Whether glass takes the live picture this pass ({@link com.termux.app.chrome.LiveBlurPolicy}). */
    private boolean mLiveBlur;

    /** Live blur's recorder, made the first time a surface goes live. */
    @Nullable private com.termux.app.chrome.LiveBackdrop mLiveBackdrop;

    // --- Active extra-key lens state (drives the per-key refraction in the backdrop shader). ---
    private boolean mKeyLensActive = false;
    private float mKeyLensIntensity = 0f;            // 0..1 fade
    private float mKeyLensCx, mKeyLensCy;            // centre in backdrop fragCoord space
    private float mKeyLensHx, mKeyLensHy;            // half extents
    private float mKeyLensRadius;                    // corner radius
    /**
     * What the dock's and the strip's tint cover of their backdrops, as their last dress passes
     * worked it out ({@link #dockGlassCover}); -1 before the first. A change re-dresses the
     * backdrop, so its edge follows an opacity change.
     */
    private float mDockGlassCover = -1f;

    /**
     * The row's icons moved off or back onto their places (a page swipe, a page switch): the
     * Peek glass reflection, then the beads ({@link com.termux.app.dock.DockController#onDockIconsMoved}).
     */
    private void onDockIconsMoved() {
        // The Peek glass reflection rides with the icons (live) or steps away (still).
        if (mPeekReflection != null) mPeekReflection.onIconsMoved();
        mTerminalHostDress.onIconsMoved();
        mDock.onDockIconsMoved();
    }

    /**
     * The translation {@code view} and its ancestors below {@code ancestor} are drawn with, down
     * the screen: what {@link #layoutOffsetIn} leaves out.
     */
    private static float drawnShiftYIn(@NonNull View view, @NonNull View ancestor) {
        float shift = 0f;
        for (View v = view; v != null && v != ancestor; ) {
            shift += v.getTranslationY();
            android.view.ViewParent parent = v.getParent();
            v = parent instanceof View ? (View) parent : null;
        }
        return shift;
    }


    // ------------------------------------------------------------------ Peek glass
    //
    // Peek glass (DockSurfaceSpec.PEEK_GLASS), on whichever half's dock wears the design: the
    // dock's glass host is cut to a card whose top edge runs through the icons' centres and whose
    // lower corners stand past the screen's edge (PeekGlassGeometry), the host's outline clips
    // everything in it to the card, the glass program's rim follows the card, and the strip under
    // the gesture pill is the card's foot, inset as the card is. The icons' reflections fade down
    // the card (PeekGlassReflection). The card rises from the screen's edge under either Style:
    // while it stands, the dock is placed as it is Docked (DockPlacement, dockFloats) — flush with
    // the bottom, no Floating gap or capsule, the strip under the pill shown as its foot — while
    // its rows keep the Style's measurements and every other surface keeps the Style. The card is
    // worked out again only when the row or the host lays out, before the frame that shows the new
    // layout draws; at rest nothing runs. Where the card cannot stand (another band or the
    // keyboard on the dock's glass, the Search field under the row, the dock lifted over the
    // system keyboard) the dock is the tray's slab, placed as its Style places it.

    /** The Peek card as last cut and where the rows stood then; the scene's cards own the aim. */
    private final com.termux.app.dock.PeekCardAim mPeekAim = new com.termux.app.dock.PeekCardAim(
        new com.termux.app.dock.PeekCardAim.Host() {
            @Nullable @Override public com.termux.app.place.RestCards.HostLook hostLook() {
                return mSideCards.hostLook();
            }
            @Override public boolean peekCardWanted() { return TermuxActivity.this.peekCardWanted(); }
            @Override public boolean homeAtRest() { return isHomeAtRest(); }
            @Nullable @Override public View row() { return mSuggestionBarView; }
            @Override public int drawnIconBoxes(@NonNull float[] out) {
                SuggestionBarView row = mSuggestionBarView;
                return row == null ? 0 : row.drawnIconBoxes(out);
            }
            @Nullable @Override public <T extends View> T findViewById(int id) {
                return TermuxActivity.this.findViewById(id);
            }
            @Nullable @Override public View decorView() {
                return getWindow() != null ? getWindow().getDecorView() : null;
            }
            @Override public float density() { return getResources().getDisplayMetrics().density; }
            @Override public float drawnShiftYIn(@NonNull View view, @NonNull View ancestor) {
                return TermuxActivity.drawnShiftYIn(view, ancestor);
            }
        });
    /** The icons' reflections on the card; made the first time a card shows them. */
    @Nullable private com.termux.app.dock.PeekGlassReflection mPeekReflection;
    /** The views whose layout moves the card, while the dock wears Peek glass. */
    @Nullable private View mPeekWatchedHost;
    @Nullable private View mPeekWatchedRow;
    /** The strip under the pill, watched while the reflection runs on down it. */
    @Nullable private View mPeekWatchedStrip;
    private boolean mPeekRefreshPending;
    private final View.OnLayoutChangeListener mPeekLayoutListener =
        (v, l, t, r, b, ol, ot, or, ob) -> schedulePeekRefresh();
    /** The one wait for the host's next draw that a layout asked for ({@link #schedulePeekRefresh}). */
    @Nullable private com.termux.app.window.FirstLayout.Handle mPeekWait;
    /** The Reflection knob moved: the reflection is drawn at its new strength. */
    private final android.content.SharedPreferences.OnSharedPreferenceChangeListener mPeekReflectionKnob =
        (preferences, key) -> {
            if (com.termux.app.dock.PeekGlassPreferences.KEY_REFLECTION.equals(key))
                syncPeekReflection();
        };
    @Nullable private android.content.SharedPreferences mPeekReflectionKnobStore;

    /** The host clipped to the card: its top corners rounded, its lower ones off screen. */
    private final ViewOutlineProvider mPeekOutline = new ViewOutlineProvider() {
        @Override
        public void getOutline(View view, android.graphics.Outline outline) {
            com.termux.app.dock.PeekGlassGeometry.Card card = mPeekAim.card();
            if (card == null) {
                outline.setRect(0, 0, view.getWidth(), view.getHeight());
                return;
            }
            float[] cut = mPeekAim.cutBuffer();
            com.termux.app.dock.PeekCardAim.cut(card, cut);
            outline.setRoundRect(Math.round(cut[com.termux.app.chrome.RoundCut.LEFT]),
                Math.round(cut[com.termux.app.chrome.RoundCut.TOP]),
                Math.round(cut[com.termux.app.chrome.RoundCut.RIGHT]),
                Math.round(cut[com.termux.app.chrome.RoundCut.BOTTOM]),
                cut[com.termux.app.chrome.RoundCut.RADIUS]);
        }
    };

    /** The row as the reflection reads it. */
    private final com.termux.app.dock.PeekGlassReflection.Row mPeekRow =
        new com.termux.app.dock.PeekGlassReflection.Row() {
            @NonNull
            @Override
            public View view() {
                SuggestionBarView row = mSuggestionBarView;
                return row != null ? row : getWindow().getDecorView();
            }

            @Override
            public int iconBoxes(@NonNull float[] out) {
                SuggestionBarView row = mSuggestionBarView;
                return row == null ? 0 : row.drawnIconBoxes(out);
            }

            @Override
            public boolean iconsMoving() {
                SuggestionBarView row = mSuggestionBarView;
                return row != null && row.iconsOffTheirPlaces();
            }

            @Override
            public float hostTx() {
                return mStackRenderer.cardDrawnX(com.termux.app.place.RestCards.StackView.HOST);
            }

            @Override
            public float laneTx() {
                SuggestionBarView row = mSuggestionBarView;
                View stack = findViewById(R.id.accessory_row_stack);
                if (row == null || stack == null) return 0f;
                float sum = 0f;
                for (android.view.ViewParent p = row.getParent(); p instanceof View && p != stack;
                     p = p.getParent()) {
                    sum += ((View) p).getTranslationX();
                }
                return sum;
            }
        };

    /**
     * Whether the dock can stand as the Peek glass card now, under either Style
     * ({@link com.termux.app.dock.DockPlacement#peekCardStands}): the design is Peek glass, the
     * dock shown with the apps row alone on its glass along the bottom, no keyboard up under it,
     * the dock not lifted over the system keyboard, and no Search field under the row. Read from
     * none of what the dock's placement moves, so the placement can read it
     * ({@link #dockFloats}).
     */
    private boolean peekCardWanted() {
        return peekCardStandsWith(mDockRows.surfaceShown(), isInAppKeyboardShown());
    }

    /**
     * {@link #peekCardWanted} for the dock shown or not and the keyboard up or down as given, the
     * rest as they are now: for a margin worked out ahead of the keyboard's settle. The joined
     * frame's answer is the dear one (a shape model built per ask), so it is asked last, and only
     * Docked: Floating has no joined frame to stand down on (ChromeShapeModel), and the dock asks
     * this many times a pass under Floating ({@link #dockFloats}).
     */
    private boolean peekCardStandsWith(boolean dockShown, boolean keyboardShown) {
        if (mPreferences == null) return false;
        // For the page whose rows the stack stands (stackDressPage), as Stack layout places it:
        // mid-crossing the rows a dip or a pictured dip brings in wear their page's answer from
        // the frame they stand, out of sight, and the settle commits that same answer.
        return com.termux.app.dock.DockPlacement.peekCardStandsOn(stackDressPage(),
                isHomeKeyboardAlwaysOn(), mDock.shownDockSurfaceSpec().peek, dockShown, arrangement().layout(), false,
                keyboardShown, mImeLiftPx > 0, mAppliedPromptFieldBandPx > 0)
            && (arrangement().floating() || !stackStandsDownOnFrame());
    }

    /**
     * The glass program's rect for the card, in the backdrop's coordinates, and its radius
     * (left, top, right, bottom, radius); null while the dock is a slab. Its bottom is a seam
     * (the card runs on off the screen), its top and sides keep the rim.
     */
    @Nullable
    private float[] peekGlassRect() {
        com.termux.app.dock.PeekGlassGeometry.Card card = mPeekAim.card();
        // A card cut before the keyboard came up must not shape the glass program a moment longer.
        if (card == null || (!peekChromeTravelling() && !mPeekAim.hostWanted())) return null;
        float[] cut = new float[com.termux.app.chrome.RoundCut.SIZE];
        com.termux.app.dock.PeekCardAim.cut(card, cut);
        float radius = cut[com.termux.app.chrome.RoundCut.RADIUS];
        float reach = com.termux.app.chrome.GlassRefraction.seamReachPx(
            com.termux.app.chrome.GlassStack.lookFor(mFancierGlassLook),
            getResources().getDisplayMetrics().density, radius);
        float[] rect = new float[4];
        com.termux.app.chrome.GlassRefraction.rimRect(rect,
            mGlassOriginLeft + cut[com.termux.app.chrome.RoundCut.LEFT],
            mGlassOriginTop + cut[com.termux.app.chrome.RoundCut.TOP],
            mGlassOriginLeft + cut[com.termux.app.chrome.RoundCut.RIGHT],
            mGlassOriginTop + cut[com.termux.app.chrome.RoundCut.BOTTOM], reach,
            com.termux.app.chrome.ChromeEdgeRule.BOTTOM);
        return new float[] {rect[0], rect[1], rect[2], rect[3], radius};
    }

    /**
     * The rim under the glass along the card's top and sides, where the program does not draw
     * the glass's edge (below Android 13): the rim moved onto the card, its bottom edge left
     * open (the card runs on under the pill), drawn inside the host.
     */
    @Nullable
    private Drawable peekRimDrawable(@NonNull float[] cut, int hostWidth, int hostHeight) {
        if (hostWidth <= 0 || hostHeight <= 0) return null;
        Drawable rim = mChrome.glass().rimUnderGlass(cut[com.termux.app.chrome.RoundCut.RADIUS],
            com.termux.app.chrome.ChromeEdgeRule.LEFT | com.termux.app.chrome.ChromeEdgeRule.TOP
                | com.termux.app.chrome.ChromeEdgeRule.RIGHT);
        if (rim == null) return null;
        // Never a plain InsetDrawable: its insets would become the host's padding and lay every
        // layer in the host out inside the card's box, long after the card is gone.
        return com.termux.app.dock.PeekRimDrawable.forCut(rim, cut, hostWidth);
    }



    /**
     * Watches the host and the row for layout while the dock wears Peek glass, and lets go of
     * them otherwise, so every other design carries no listener of this.
     */
    private void syncPeekListeners() {
        boolean peek = mPreferences != null && mDock.hostDressSpec().peek;
        View host = peek ? findViewById(R.id.accessory_surface_host) : null;
        View row = peek ? mSuggestionBarView : null;
        if (mPeekWatchedHost != host) {
            if (mPeekWatchedHost != null) {
                mPeekWatchedHost.removeOnLayoutChangeListener(mPeekLayoutListener);
                if (mPeekWait != null) mPeekWait.cancel();
                mPeekWait = null;
                mPeekRefreshPending = false;
            }
            mPeekWatchedHost = host;
            if (host != null) host.addOnLayoutChangeListener(mPeekLayoutListener);
        }
        if (mPeekWatchedRow != row) {
            if (mPeekWatchedRow != null)
                mPeekWatchedRow.removeOnLayoutChangeListener(mPeekLayoutListener);
            mPeekWatchedRow = row;
            if (row != null) row.addOnLayoutChangeListener(mPeekLayoutListener);
        }
        if (!peek && mPeekWatchedStrip != null) {
            mPeekWatchedStrip.removeOnLayoutChangeListener(mPeekLayoutListener);
            mPeekWatchedStrip = null;
        }
    }

    /** A layout moved the host or the row: the card is read again before the next draw. */
    private void schedulePeekRefresh() {
        View host = mPeekWatchedHost;
        if (mPeekRefreshPending || host == null) return;
        mPeekRefreshPending = true;
        mPeekWait = com.termux.app.window.FirstLayout.beforeNextDraw(host, () -> {
            mPeekWait = null;
            mPeekRefreshPending = false;
            onPeekLayoutSettled();
        });
    }

    /**
     * After a layout: a card that moved re-cuts the host, re-aims the glass program (one rebuild
     * of the dock's effect) and dresses the strip under the pill again; the same card only
     * re-aims the reflection.
     */
    private void onPeekLayoutSettled() {
        com.termux.app.dock.PeekGlassGeometry.Card card = mPeekAim.resolve();
        if (java.util.Objects.equals(card, mPeekAim.card())) {
            syncPeekReflection();
            // The same card over a row laid out again: the row's slots may be other views now (a
            // crossing stands the other half's rows on its first frame and builds their slots on
            // the frames after), and the live reflection holds the ones it recorded, which go
            // blank once let go. It is recorded again from the row as it now stands.
            onDockRowContentChanged();
            return;
        }
        View host = findViewById(R.id.accessory_surface_host);
        // While the chrome travels, a card whose floor alone moved with the stack is re-cut on
        // its own; the landing's pass dresses the rest (PeekGlassGeometry#travelRecutsOnly).
        boolean recutOnly = com.termux.app.dock.PeekGlassGeometry.travelRecutsOnly(mPeekAim.card(),
            card, peekChromeTravelling());
        if (host != null && mDock.dockShapeCut()) {
            // Cuts the card afresh, re-aims the glass program and the reflection, or puts the
            // slab back, in the shape the dock is placed in now: a card that gave way under
            // Floating hands the host back its capsule (dockFloats).
            mDock.applyDockSurfaceShape(host, mDock.hostFloats(), mDock.dockShapeHeightPx(), true, true);
            if (recutOnly) {
                return;
            }
        } else {
            mPeekAim.set(card);
            syncPeekReflection();
            rebuildBackdropGlassEffectForLens();
        }
        if (mChrome != null)
            mChrome.requestSync(ChromeRenderer.SCOPE_APPLY_THIS_FRAME
                | ChromeRenderer.SCOPE_ACCESSORY_RENDER);
    }

    /** Whether the chrome is travelling with the wall: a crossing, a slide, or its transforms. */
    private boolean peekChromeTravelling() {
        if (mCrossing.crossing() || mChromeTravelMoved) return true;
        com.termux.app.wall.PaneWallLayout wall =
            mPaneWallController != null ? mPaneWallController.wall() : null;
        return wall != null && wall.isMoving();
    }

    /** One of the row's icons asked to be drawn again: the reflection shows it as the icon does. */
    private void onDockRowContentChanged() {
        if (mPeekReflection != null) mPeekReflection.onRowContentChanged();
        mTerminalHostDress.onRowContentChanged();
    }

    /**
     * The reflection set to the card, the row and the Reflection knob as they are now: drawn on
     * the host and on the strip under the pill while a card stands and the knob is above 0, put
     * away otherwise. Live (the row's render node through an AGSL fade) while Fancier glass is
     * active, still bitmaps otherwise. Nothing is redrawn for the same values.
     */
    private void syncPeekReflection() {
        com.termux.app.dock.PeekGlassGeometry.Card card = mPeekAim.card();
        int strength = mPreferences == null ? 0 : com.termux.app.dock.PeekGlassPreferences
            .reflection(mPreferences.getSharedPreferences());
        SuggestionBarView row = mSuggestionBarView;
        View host = findViewById(R.id.accessory_surface_host);
        View container = findViewById(R.id.accessory_stack_container);
        // Apart, the reflection is part of Home's card: while Home's row does not stand (the
        // Terminal's rows up) it is kept as Home's rest drew it, parked with the card, so it is
        // there for the whole slide back and the landing finds it right (PeekGlassReflection#syncFor).
        com.termux.app.dock.PeekGlassReflection.Sync sync =
            com.termux.app.dock.PeekGlassReflection.syncFor(card != null, strength > 0,
                row != null && host instanceof ViewGroup && container != null,
                mSideCards.hostLook() != null, peekHomeRowStands());
        if (sync == com.termux.app.dock.PeekGlassReflection.Sync.CLEAR) {
            if (mPeekReflection != null) mPeekReflection.clear();
            return;
        }
        if (sync == com.termux.app.dock.PeekGlassReflection.Sync.KEEP) {
            if (mPeekReflection != null) mPeekReflection.setHeld(true);
            return;
        }
        float[] rowAt = com.termux.app.dock.DockController.layoutOffsetIn(row, container);
        float[] hostAt = com.termux.app.dock.DockController.layoutOffsetIn(host, container);
        if (rowAt == null || hostAt == null) {
            if (mPeekReflection != null) mPeekReflection.clear();
            return;
        }
        if (mPeekReflection == null) {
            mPeekReflection = new com.termux.app.dock.PeekGlassReflection(
                getResources().getDisplayMetrics().density);
        }
        // The knob is heard while a reflection exists.
        android.content.SharedPreferences store = mPreferences.getSharedPreferences();
        if (store != null && mPeekReflectionKnobStore != store) {
            if (mPeekReflectionKnobStore != null)
                com.termux.shared.settings.preferences.PreferenceDraft.unlisten(mPeekReflectionKnobStore, mPeekReflectionKnob);
            com.termux.shared.settings.preferences.PreferenceDraft.listen(store, mPeekReflectionKnob);
            mPeekReflectionKnobStore = store;
        }
        com.termux.app.dock.PeekGlassReflection reflection = mPeekReflection;
        reflection.attachHost((ViewGroup) host, findViewById(R.id.extrakeys_background));
        // The card's foot under the pill is the host's own glass now (DockSpec): nothing to attach.
        if (mPeekWatchedStrip != null) {
            mPeekWatchedStrip.removeOnLayoutChangeListener(mPeekLayoutListener);
            mPeekWatchedStrip = null;
        }
        reflection.attachStrip(null, 0f, 0f);
        boolean live = Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU
            && mFancierGlassLook != null;
        // Aimed as the card was cut: the row where it stood over the host then. Apart the card is
        // Home's rest's whichever page is in front (PeekCardAim#set), so the same aim compares equal
        // and the Terminal's rest re-aims nothing.
        reflection.update(card, mPeekRow, rowAt[0] - hostAt[0], mPeekAim.rowsPx(),
            com.termux.app.dock.PeekGlassGeometry.reflectionAlpha(strength), live);
        reflection.setHeld(false);
    }

    /** Whether Home's apps row stands (shown), which the reflection is drawn from. */
    private boolean peekHomeRowStands() {
        SuggestionBarView row = mSuggestionBarView;
        return row != null && row.isShown();
    }

    /** The reflection and its views let go, and the knob no longer heard; for the activity's end. */
    private void releasePeekReflection() {
        if (mPeekReflection != null) mPeekReflection.release();
        mPeekReflection = null;
        if (mPeekReflectionKnobStore != null) {
            com.termux.shared.settings.preferences.PreferenceDraft.unlisten(mPeekReflectionKnobStore, mPeekReflectionKnob);
            mPeekReflectionKnobStore = null;
        }
    }

    private void rebuildBackdropGlassEffectForLens() {
        mGlassEffects.rebuildForLens();
    }

    private boolean isReducedMotionEnabled() {
        Boolean held = mReducedMotion;
        if (held != null) return held;
        boolean enabled = com.termux.app.ReducedMotion.isEnabled(this);
        // Held only while an observer will say when it moves; without one, every ask reads.
        if (ensureReducedMotionObserver()) mReducedMotion = enabled;
        return enabled;
    }

    /**
     * The animator scale's answer, held between changes: it was a Settings.Global read on every
     * MOVE of a pane touch and every frame of a slide. Null until read, and again whenever the
     * observer says the setting moved.
     */
    @Nullable private volatile Boolean mReducedMotion;
    @Nullable private android.database.ContentObserver mReducedMotionObserver;

    private boolean ensureReducedMotionObserver() {
        if (mReducedMotionObserver != null) return true;
        if (isDestroyed()) return false;
        android.database.ContentObserver observer = new android.database.ContentObserver(
                new Handler(Looper.getMainLooper())) {
            @Override public void onChange(boolean selfChange) {
                mReducedMotion = null;
            }
        };
        try {
            getContentResolver().registerContentObserver(
                Settings.Global.getUriFor(Settings.Global.ANIMATOR_DURATION_SCALE), false, observer);
        } catch (Throwable t) {
            return false;
        }
        mReducedMotionObserver = observer;
        return true;
    }

    private void unregisterReducedMotionObserver() {
        android.database.ContentObserver observer = mReducedMotionObserver;
        mReducedMotionObserver = null;
        mReducedMotion = null;
        if (observer == null) return;
        try {
            getContentResolver().unregisterContentObserver(observer);
        } catch (Throwable ignored) {
            // Already gone with the resolver.
        }
    }

    private void playAppLaunchRipple(@NonNull String packageName, @Nullable Drawable icon,
                                     @Nullable View sourceView) {
        if (isReducedMotionEnabled()) return;
        View accessorySurface = findViewById(R.id.accessory_surface_host);
        DockLaunchRippleView ripple = accessorySurface == null ? null
            : (DockLaunchRippleView) accessorySurface.findViewWithTag("dock_launch_ripple");
        if (ripple == null || ripple.getWidth() <= 0 || ripple.getHeight() <= 0) return;

        int color = launchRippleColor(resolveLaunchIconDominantColor(packageName, icon),
            resolveDockAccentColor());
        int[] rippleLocation = new int[2];
        ripple.getLocationOnScreen(rippleLocation);
        float originX;
        float originY;
        if (sourceView != null && sourceView.isAttachedToWindow()) {
            int[] sourceLocation = new int[2];
            sourceView.getLocationOnScreen(sourceLocation);
            originX = sourceLocation[0] + sourceView.getWidth() * 0.5f - rippleLocation[0];
            originY = sourceLocation[1] + sourceView.getHeight() * 0.5f - rippleLocation[1];
        } else {
            originX = ripple.getWidth() * 0.5f;
            originY = ripple.getHeight() * 0.5f;
        }

        boolean capsule = mDock.dockFloats();
        RectF bounds = new RectF(0f, 0f, ripple.getWidth(), ripple.getHeight());
        float cornerRadius = capsule ? mDock.resolveDockCapsuleCornerRadiusPx(ripple.getHeight()) : 0f;
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S) {
            // The glass shader is stateful and belongs to the backdrop. Reusing it here mutates the
            // same rounded-surface uniforms while a radial source is being drawn, which produced the
            // audit's repeated oversized masks. Keep the launch wave a single Canvas composition.
            ripple.setRenderEffect(null);
        }
        DockEdgeGlowView edgeGlow = findViewById(R.id.accessory_edge_glow_fx);
        if (capsule && edgeGlow != null) edgeGlow.setVisibility(View.VISIBLE);
        final boolean keyboardShownAtLaunch = isInAppKeyboardShown();
        ripple.startRipple(color, originX, originY, capsule, bounds, cornerRadius,
            edgeGlow == null ? null : (collisionColor, level) ->
                edgeGlow.setLaunchCollisionState(collisionColor, level),
            () -> capsule == mDock.dockFloats()
                && keyboardShownAtLaunch == isInAppKeyboardShown(),
            () -> {
                if (mInAppKeyboard != null) mInAppKeyboard.fadeOutLaunchWave();
            });

        if (!capsule && keyboardShownAtLaunch && mInAppKeyboard != null) {
            mInAppKeyboard.animateLaunchWave(color, originX + rippleLocation[0],
                originY + rippleLocation[1]);
        }
    }

    /**
     * Keeps an icon's hue legible after the low-alpha wave is composited through tinted glass.
     *
     * <p>An icon with no hue of its own still borrows the dock's accent — that part was never about
     * brightness. What is gone is the pair of floors under it, saturation to 0.72 and value to
     * 0.78, which made every launch wave a bright one whatever it was breaking over. The wave is
     * decoration, so it is resolved at {@link OnGlass#TARGET_DECORATION} against the glass the dock
     * is standing on, and on a pale band it now comes out darker rather than brighter.</p>
     */
    private int launchRippleColor(int color, int fallbackAccent) {
        float[] hsv = new float[3];
        Color.colorToHSV(color, hsv);
        int seed = hsv[1] < 0.08f ? fallbackAccent : color;
        OnGlass.Resolution glass = resolveAzGlass();
        return glass == null ? seed
            : glassInk(glass, seed, OnGlass.TARGET_DECORATION, 255);
    }

    private int resolveLaunchIconDominantColor(@NonNull String packageName,
                                               @Nullable Drawable sourceIcon) {
        Integer cached = mLaunchIconColorCache.get(packageName);
        if (cached != null) return cached;
        Drawable drawable = sourceIcon;
        if (drawable == null) {
            try {
                drawable = getPackageManager().getApplicationIcon(packageName);
            } catch (Throwable ignored) {
            }
        }
        int fallback = resolveDockAccentColor();
        int color = com.termux.app.chrome.IconColor.dominant(drawable, fallback);
        mLaunchIconColorCache.put(packageName, color);
        return color;
    }

    private void applyGlassSurfaceColor(int viewId, int surfaceColor) {
        View surface = findViewById(viewId);
        if (surface != null) {
            surface.setBackgroundColor(surfaceColor);
        }
    }

    private float resolveOpacityAlpha(int opacityPercent) {
        int clamped = Math.max(0, Math.min(100, opacityPercent));
        return clamped / 100f;
    }

    private int resolveTerminalOverlayBaseColor() {
        if (mPreferences != null && mPreferences.isTerminalDynamicColorsEnabled()) {
            // Level-independent: Terminal contrast moves the text, never the pane's glass.
            return com.termux.app.terminal.MaterialTerminalColorScheme.overlayBaseColor(this);
        }
        if (isNightThemeActive() || LauncherSchemeTheme.isSchemeChromeActive(this)) {
            return getTermuxThemeColor(com.termux.shared.R.attr.termuxColorSurfaceBase, R.color.termux_surface_base);
        }
        return com.termux.app.material.M3.color(this,
            com.google.android.material.R.attr.colorSurfaceContainerLowest,
            com.google.android.material.R.color.m3_sys_color_dark_surface_container_lowest);
    }

    private int resolveTerminalSurfaceColor() {
        int baseColor = shouldUseWallpaperPassthroughMode()
            ? resolveTerminalOverlayBaseColor()
            : getTermuxThemeColor(com.termux.shared.R.attr.termuxColorSurfaceBase, R.color.termux_surface_base);
        // The opacity slider is the user's contract: in wallpaper mode this colour is painted on the
        // full-screen root, so raising it for glyph contrast hides the wallpaper everywhere at once.
        // Generated palettes always contain mid-tone greys (color0/color8), which cannot meet a
        // contrast target over both a dark and a light wallpaper at any alpha below 255 — so any
        // "raise until every glyph is legible over any wallpaper" floor is pinned at fully opaque.
        int opacity = mPreferences != null ? mPreferences.getTerminalBackgroundOpacity() : 100;
        int alpha = Math.round(resolveOpacityAlpha(opacity) * 255f);
        return (alpha << 24) | (baseColor & 0x00FFFFFF);
    }

    private int resolveAccessorySurfaceColor(float surfaceAlpha) {
        int baseColor = shouldUseWallpaperPassthroughMode()
            ? resolveAccessoryGlassBaseColor()
            : getTermuxThemeColor(com.termux.shared.R.attr.termuxColorSurfaceBase, R.color.termux_surface_base);
        int alpha = Math.round(Math.max(0f, Math.min(1f, surfaceAlpha)) * 255f);
        return (alpha << 24) | (baseColor & 0x00FFFFFF);
    }

    @NonNull
    private Drawable buildRoundedAmbientVeil(float surfaceAlpha, boolean decorLayer) {
        int surfaceColor = resolveAccessorySurfaceColor(surfaceAlpha);
        int baseAlpha = Color.alpha(surfaceColor);
        int midAlpha = Math.round(baseAlpha * (decorLayer ? 0.22f : 0.14f));
        int highAlpha = Math.round(baseAlpha * (decorLayer ? 0.40f : 0.24f));
        // Soft veil that fades back to transparent at the BOTTOM as well as the top, so the floating
        // dock blends smoothly into the same terminal/background dim above and below — no hard
        // darker-band seam at the dock's bottom edge against the under-dock gap and gesture strip.
        GradientDrawable veil = new GradientDrawable(
            GradientDrawable.Orientation.TOP_BOTTOM,
            new int[] {
                Color.TRANSPARENT,
                withAlphaComponent(surfaceColor, midAlpha),
                withAlphaComponent(surfaceColor, highAlpha),
                Color.TRANSPARENT
            }
        );
        veil.setDither(true);
        return veil;
    }

    private void applyAccessoryAmbientVeil(@Nullable View accessoryContainer, @NonNull ChromeSpec state) {
        if (accessoryContainer == null) {
            return;
        }
        if (!state.toolbarShown || !mDock.dockFloats()) {
            accessoryContainer.setBackground(null);
            return;
        }
        accessoryContainer.setBackground(buildRoundedAmbientVeil(state.barAlpha, false));
    }

    private int getTermuxThemeColor(int attr, int fallbackRes) {
        return ThemeUtils.getSystemAttrColor(this, attr, ContextCompat.getColor(this, fallbackRes));
    }

    private boolean isNightThemeActive() {
        return (getResources().getConfiguration().uiMode & Configuration.UI_MODE_NIGHT_MASK)
            == Configuration.UI_MODE_NIGHT_YES;
    }

    private static int withAlphaComponent(int color, int alpha) {
        return (Math.max(0, Math.min(255, alpha)) << 24) | (color & 0x00FFFFFF);
    }

    /**
     * Whether the terminal paints its own surface. Fullscreen is deliberately not consulted: see
     * {@link com.termux.app.terminal.TerminalSurfacePolicy}.
     */
    private boolean shouldShowTerminalOverlaySurface() {
        if (mPreferences == null) {
            return false;
        }
        return com.termux.app.terminal.TerminalSurfacePolicy.showsTerminalSurface(
            shouldUseWallpaperPassthroughMode(), mPreferences.getTerminalBackgroundOpacity());
    }

    private void applyAccessoryLayerBounds(int viewId, @Nullable Rect bounds) {
        View view = findViewById(viewId);
        if (view == null) {
            return;
        }
        ViewGroup.LayoutParams layoutParams = view.getLayoutParams();
        if (!(layoutParams instanceof RelativeLayout.LayoutParams)) {
            return;
        }
        RelativeLayout.LayoutParams params = (RelativeLayout.LayoutParams) layoutParams;
        int targetTop = 0;
        int targetWidth = ViewGroup.LayoutParams.MATCH_PARENT;
        int targetHeight = ViewGroup.LayoutParams.MATCH_PARENT;
        int targetLeftMargin = 0;
        int targetRightMargin = 0;
        boolean capsuleSurface = viewId == R.id.accessory_surface_host && mDock.hostFloats();
        ViewParent parent = view.getParent();
        if (parent instanceof View) {
            View parentView = (View) parent;
            if (parentView.getHeight() > 0) {
                targetHeight = parentView.getHeight();
            }
        }
        if (bounds != null) {
            targetTop = Math.max(0, bounds.top);
            targetHeight = Math.max(0, bounds.height());
        }
        if (viewId == R.id.accessory_surface_host) {
            // The margins, and MATCH_PARENT for what is left — never the parent's width frozen
            // into pixels. The dock gets its width back in the same frame a bar leaves a side
            // edge, and this pass runs before that re-layout: a pixel width read here left the
            // glass short by the rail's whole band, all of it on the right. A standing Peek card
            // spans the screen as it does Docked and cuts its own sides (dockFloatsIn).
            DockLayout dock = mDock.appliedDockLayout();
            int horizontalMargin = com.termux.app.dock.DockHostBounds.sideMarginPx(
                mDock.dockFloatsIn(dock.capsule), dock.horizontalInsetPx);
            targetLeftMargin = horizontalMargin;
            targetRightMargin = horizontalMargin;
        }
        if (viewId == R.id.accessory_surface_host && mSideCards.hostPinned()) {
            // Home's card while it stands apart from the Terminal's: laid out at Home's rest from
            // the answer, whatever page is in front.
            mDock.applyDockSurfaceShape(view, capsuleSurface, mSideCards.hostHeightPx(), true, true);
            View container = findViewById(R.id.accessory_stack_container);
            if (mSideCards.layOutHost(params, container == null ? 0 : container.getPaddingBottom()))
                view.setLayoutParams(params);
            return;
        }
        mDock.applyDockSurfaceShape(view, capsuleSurface, targetHeight,
            viewId == R.id.accessory_surface_host, viewId == R.id.accessory_surface_host);
        if (params.leftMargin != targetLeftMargin || params.topMargin != targetTop ||
            params.rightMargin != targetRightMargin || params.bottomMargin != 0 ||
            params.width != targetWidth || params.height != targetHeight) {
            params.leftMargin = targetLeftMargin;
            params.topMargin = targetTop;
            params.rightMargin = targetRightMargin;
            params.bottomMargin = 0;
            params.width = targetWidth;
            params.height = targetHeight;
            view.setLayoutParams(params);
        }
    }

    /** Takes the bottom pin the host wore while the cards stood apart off; whether there was one. */
    private static boolean dropHostBottomPin(@NonNull RelativeLayout.LayoutParams params) {
        if (params.getRule(RelativeLayout.ALIGN_PARENT_BOTTOM) == 0) return false;
        params.removeRule(RelativeLayout.ALIGN_PARENT_BOTTOM);
        return true;
    }

    /** Positions the dock glass behind either the dock rows alone or the unified default stack. */
    private void applyAccessorySurfaceBounds(@NonNull ChromeSpec state) {
        View surface = findViewById(R.id.accessory_surface_host);
        if (surface == null)
            return;
        ViewGroup.LayoutParams layoutParams = surface.getLayoutParams();
        if (layoutParams instanceof RelativeLayout.LayoutParams) {
            RelativeLayout.LayoutParams params = (RelativeLayout.LayoutParams) layoutParams;
            boolean unified = shouldUseUnifiedDefaultKeyboardGlassSurface(state);
            boolean rulesChanged = false;
            if (mSideCards.hostPinned()) {
                // The pin is applied with the bounds below.
            } else if (unified) {
                rulesChanged = params.getRule(RelativeLayout.ABOVE) != 0
                    || params.getRule(RelativeLayout.ALIGN_PARENT_TOP) != RelativeLayout.TRUE;
                params.removeRule(RelativeLayout.ABOVE);
                params.addRule(RelativeLayout.ALIGN_PARENT_TOP, RelativeLayout.TRUE);
                rulesChanged |= dropHostBottomPin(params);
            } else {
                // The dock's sheet alone is pinned at both ends, the stack's top and the top of the
                // keyboard's column, exactly where the rows stand. Anchoring only the bottom and
                // sizing it by the keyboard's measured height let the sheet and the rows part
                // whenever that measure and the laid-out column disagreed (#49, split keyboard),
                // and counted bands under the keyboard a second time, over the rows. With the
                // keyboard gone the column is empty and the sheet runs to the stack's bottom.
                rulesChanged = params.getRule(RelativeLayout.ALIGN_PARENT_TOP) != RelativeLayout.TRUE
                    || params.getRule(RelativeLayout.ABOVE) != R.id.accessory_keyboard_column;
                params.addRule(RelativeLayout.ALIGN_PARENT_TOP, RelativeLayout.TRUE);
                params.addRule(RelativeLayout.ABOVE, R.id.accessory_keyboard_column);
                params.alignWithParent = true;
                rulesChanged |= dropHostBottomPin(params);
            }
            if (rulesChanged)
                surface.setLayoutParams(params);
        }
        // Pinned at both ends, the sheet's height comes from its anchors; these bounds only carry
        // its top inset and the rows' height the capsule's corner is clamped against.
        boolean underBands = underKeyboardBandsShown();
        Rect bounds = state.keyboardShown && !underBands
            && !shouldUseUnifiedDefaultKeyboardGlassSurface(state)
            ? buildToolbarOnlyAccessoryBounds(state) : null;
        applyAccessoryLayerBounds(R.id.accessory_surface_host,
            withDockGlassTopInset(bounds, dockGlassTopInsetPx()));
        applyUnderKeyboardStackGlass(state);
    }

    /**
     * Whether bands stand under the keyboard now: the stack below it holds one. Every arrangement
     * without the slot answers false, and every path this gates is then exactly what it was.
     */
    private boolean underKeyboardBandsShown() {
        return mDockRows.underKeyboardBandsShown();
    }

    /**
     * The bands under the keyboard wear the dock's own material on a card of their own
     * ({@link com.termux.app.dock.UnderKeyboardBand}): the dock's frost where the dock blurs, its
     * tint at the dock's opacity and grain, its faint containing rim, its side inset and its corner
     * radius, clipped to that card. The same card with the keyboard up, down or switched off, so a
     * keyboard swipe only opens or closes the gap between the dock's rows and it, and the settle
     * swaps nothing. The frame is sampled where the scene draws the card: the stack's travel,
     * plus the keyboard column's lift and the share the card is held back by while the keyboard
     * rises out from over it ({@link StackRenderer#underDrawnY}).
     */
    private void applyUnderKeyboardStackGlass(@NonNull ChromeSpec state) {
        View under = findViewById(R.id.accessory_under_keyboard_stack);
        if (under == null) return;
        // The Peek card is the dock's only glass: the bands under the keyboard then ride on it.
        if (!com.termux.app.dock.UnderKeyboardBand.wearsSheet(
                mDockRows.underKeyboardBandsShown(), state.toolbarShown, peekCardWanted())) {
            if (under.getBackground() != null) under.setBackground(null);
            mUnderKeyboardBackdropBitmap = null;
            releaseUnderKeyboardBackdrop();
            return;
        }
        DockLayout dock = mDock.appliedDockLayout();
        float radiusPx = com.termux.app.dock.UnderKeyboardBand.cornerRadiusPx(dock,
            under.getHeight() > 0 ? under.getHeight() : Integer.MAX_VALUE);
        com.termux.app.chrome.SharedFrameDrawable backdrop = null;
        mUnderKeyboardBackdropBitmap = null;
        View wallpaperFrame = findViewById(R.id.activity_termux_root_view);
        if (state.blurEnabled && wallpaperFrame != null) {
            Bitmap frame = mChrome.blurCache().obtain(state.blurRadiusDp, wallpaperFrame);
            if (frame != null) {
                mUnderKeyboardBackdropBitmap = frame;
                // Kept for the same card, as the keyboard host's is (SharedFrameReuse): a new one
                // compiles its own refraction program on the main thread.
                com.termux.app.chrome.SharedFrameDrawable held = mUnderKeyboardBackdrop;
                if (com.termux.app.chrome.SharedFrameReuse.reuses(held, mUnderKeyboardBackdropHost,
                        under, mUnderKeyboardBackdropParallax, mWallpaperParallax)) {
                    backdrop = held;
                    backdrop.setFrame(frame, mChrome.blurCache().frameRectRef(), false);
                } else {
                    backdrop = new com.termux.app.chrome.SharedFrameDrawable(frame,
                        new Rect(mChrome.blurCache().frameRectRef()), mWallpaperParallax,
                        com.termux.app.chrome.GlassAnchor.layout(under,
                            () -> mAccessoryStackLift.px() + mStackRenderer.underDrawnY()));
                    mUnderKeyboardBackdrop = backdrop;
                    mUnderKeyboardBackdropHost = under;
                    mUnderKeyboardBackdropParallax = mWallpaperParallax;
                }
                backdrop.setClearFrame(glassClearFrame(state.blurRadiusDp));
            }
        }
        // No frame to draw this pass: the card wears no backdrop, so none is kept for it.
        if (backdrop == null) releaseUnderKeyboardBackdrop();
        com.termux.app.chrome.GlassStack.Spec spec = com.termux.app.chrome.GlassStack.Spec.of(
                state.blurRadiusDp, state.barAlpha, mPreferences != null
                    ? mPreferences.getDockGlassGrain(stackLookPage())
                    : TermuxPreferenceConstants.TERMUX_APP.DEFAULT_VALUE_DOCK_GLASS_GRAIN,
                radiusPx, com.termux.app.chrome.ElementGlass.refraction(mPreferences, com.termux.shared.termux.settings.preferences.LookGrid.Element.DOCK, stackLookPage(), mFancierGlassLook))
            .withTintStrength(mPreferences != null ? mPreferences.getDockTintStrength(stackLookPage())
                : TermuxPreferenceConstants.TERMUX_APP.DEFAULT_SURFACE_GLOBAL_TINT)
            // A card under Floating, with its whole rim. Docked it joins the frame below the
            // keyboard: its top is a join and the rest is the screen's edge, so it draws none.
            .withRim(arrangement().floating())
            .withSlice(1f, true)
            // The page's ground over the frame, as the bars and the dock draw it (#283).
            .withGround(true);
        Drawable underStack = com.termux.app.chrome.GlassStack.build(mChrome.glass(), spec,
            getResources().getDisplayMetrics().density, backdrop);
        // Its ground is drawn on the card: the rounded sheet passes no callbacks on.
        com.termux.app.chrome.GroundUnderGlass.bind(underStack, under);
        under.setBackground(new com.termux.app.chrome.RoundedSheetDrawable(underStack,
            com.termux.app.dock.UnderKeyboardBand.sideInsetPx(dock), radiusPx));
    }

    /** The shared frame the under-keyboard card is drawing, for the blur cache's in-use scan. */
    @Nullable private Bitmap mUnderKeyboardBackdropBitmap;
    /** The card's backdrop as last built, its view and parallax; see {@link #applyUnderKeyboardStackGlass}. */
    @Nullable private com.termux.app.chrome.SharedFrameDrawable mUnderKeyboardBackdrop;
    @Nullable private View mUnderKeyboardBackdropHost;
    @Nullable private Object mUnderKeyboardBackdropParallax;

    private void releaseUnderKeyboardBackdrop() {
        mUnderKeyboardBackdrop = null;
        mUnderKeyboardBackdropHost = null;
        mUnderKeyboardBackdropParallax = null;
    }

    /**
     * Fancier Glass's edge clarity for a surface frosted at {@code blurRadiusDp}: the blur cache's
     * clear frame ({@link com.termux.app.chrome.GlassRefraction#CLARITY_RADIUS_DP}, the same rect
     * as the frost's), or null while the look asks for none or that blur is still in flight. The
     * frame lands through the cache's ready pass, which rebuilds these surfaces. Read on every
     * build, so a radius, look or wallpaper change and a cache clear restate it with the frame.
     * The in-use scan finds it through the drawable ({@code SharedFrameDrawable.shows}).
     */
    @Nullable
    private Bitmap glassClearFrame(int blurRadiusDp) {
        View wallpaperFrame = findViewById(R.id.activity_termux_root_view);
        if (wallpaperFrame == null) return null;
        Bitmap clear = com.termux.app.chrome.WallpaperFrostPainter.sharpFrame(mChrome.blurCache(),
            mFancierGlassLook, blurRadiusDp, wallpaperFrame);
        return clear != null && !clear.isRecycled() ? clear : null;
    }

    /**
     * The dock's glass, started below a bottom status bar that kept a sheet of its own. Without
     * this the dock's sheet would run up behind that bar and the two washes would stack — the bar
     * stands in the same container as the dock's rows now, not on the terminal's height above it.
     *
     * <p>Zero inset gives back exactly what was passed, so every arrangement that has ever shipped
     * takes the same path it always did.
     */
    @Nullable
    private Rect withDockGlassTopInset(@Nullable Rect bounds, int topInsetPx) {
        if (topInsetPx <= 0) return bounds;
        if (bounds != null)
            return new Rect(bounds.left, bounds.top + topInsetPx, bounds.right, bounds.bottom);
        View container = findViewById(R.id.accessory_stack_container);
        if (container == null) return null;
        ViewGroup.LayoutParams params = container.getLayoutParams();
        int heightPx = params != null && params.height > 0 ? params.height : container.getHeight();
        if (heightPx <= topInsetPx) return null;
        int widthPx = container.getWidth() > 0
            ? container.getWidth() : getResources().getDisplayMetrics().widthPixels;
        return new Rect(0, topInsetPx, widthPx, heightPx);
    }

    private void applyAccessoryLayerVerticalBounds(int viewId, @Nullable Rect bounds) {
        View view = findViewById(viewId);
        if (view == null || !(view.getLayoutParams() instanceof RelativeLayout.LayoutParams))
            return;
        RelativeLayout.LayoutParams params = (RelativeLayout.LayoutParams) view.getLayoutParams();
        int targetTop = bounds == null ? 0 : Math.max(0, bounds.top);
        int targetHeight = bounds == null
            ? ViewGroup.LayoutParams.MATCH_PARENT : Math.max(0, bounds.height());
        if (params.topMargin != targetTop || params.height != targetHeight) {
            params.topMargin = targetTop;
            params.height = targetHeight;
            view.setLayoutParams(params);
        }
    }

    // ---- The one shape model, read live (ADR 0007) ----

    /**
     * Whether the chrome on screen wears Home's own Style, Corners and Margin rather than the
     * Terminal's (the page's Dress). Each surface wears the half it belongs to (SeamDress): at
     * rest that is the page the chrome is committed to, so it switches at settle with the layout
     * variant, and a settle that crosses between halves that differ dresses the chrome again
     * ({@link #restyleChromeForHalfIfChanged}). Mid-slide across the seam the stack wears the half
     * whose rows it stands, the status bar the Terminal's, and the frame the committed half's.
     * The reads without a surface are the stack's, which is most of the chrome.
     */
    private boolean chromeWearsHomeShape() {
        return chromeWearsHomeShape(com.termux.app.place.SeamDress.Surface.STACK);
    }

    private boolean chromeWearsHomeShape(@NonNull com.termux.app.place.SeamDress.Surface surface) {
        // On the one shared layout Home wears the Terminal's shape: there is no other to wear.
        return homeHoldsOwnLayout()
            && com.termux.app.place.SeamDress.wearsHome(surface, mLastWallPage, stackDressPage(),
                mCrossing.seam().barDressedAcross());
    }

    /**
     * While the top band's arriving end is built as a crossing begins: the arriving page's look id,
     * which the status and stack reads answer so the builders dress it as the landing's re-dress
     * will. {@link com.termux.app.place.TopBandFadePlan#NONE} otherwise.
     */
    private int mLookIdOverride = com.termux.app.place.TopBandFadePlan.NONE;

    /**
     * The half of the wall whose look values {@code surface} wears now (ADR 0013). Unlike the
     * shape, which Home wears only with a Home layout of its own, look values are always held per
     * half; until a half is edited both answer the same numbers.
     */
    private int lookPageId(@NonNull com.termux.app.place.SeamDress.Surface surface) {
        if (mLookIdOverride != com.termux.app.place.TopBandFadePlan.NONE
            && (surface == com.termux.app.place.SeamDress.Surface.STATUS
                || surface == com.termux.app.place.SeamDress.Surface.STACK))
            return mLookIdOverride;
        // Between two Home pages the bar is Home's on both ends (SeamCrossing#barDressedAcross).
        // Each surface reads the page it stands on (ADR 0015 §6): the Home page in front, the
        // bound Display page, or the Terminal's; mid-crossing the end the surface wears.
        com.termux.app.page.PageKind stackPage = stackDressPage();
        com.termux.app.page.PageKind kind = com.termux.app.place.SeamDress.lookPage(surface,
            mLastWallPage, stackPage, mCrossing.seam().barDressedAcross());
        com.termux.app.page.PageKind window =
            surface == com.termux.app.place.SeamDress.Surface.STACK ? stackPage : mLastWallPage;
        // The Assistant page reads its own page's look cells (@kind:assistant, ADR 0022).
        int displayId = window == com.termux.app.page.PageKind.DISPLAY ? mDisplayPageBinding.boundPage()
            : window == com.termux.app.page.PageKind.ASSISTANT ? assistantPageId() : -1;
        return com.termux.app.place.SeamDress.lookPageId(kind,
            kind == com.termux.app.page.PageKind.HOME ? mHomeSeam.pageInFront() : -1, displayId,
            terminalLookPageId());
    }

    /** The id {@code page}'s look values are read under, for a crossing's end. */
    private int lookIdOf(@NonNull com.termux.app.wall.PageRef page) {
        if (page.isHome())
            return com.termux.app.place.SeamDress.lookPageId(
                com.termux.app.page.PageKind.HOME, page.id >= 0 ? page.id : mHomeSeam.pageInFront(),
                -1, terminalLookPageId());
        return com.termux.app.place.SeamDress.lookPageId(page.kind, -1,
            page.kind == com.termux.app.page.PageKind.DISPLAY ? mDisplayPageBinding.boundPage()
                : page.kind == com.termux.app.page.PageKind.ASSISTANT ? assistantPageId() : -1,
            terminalLookPageId());
    }

    /**
     * Puts the Assistant page on the wall after page {@code afterId} (the end when there is no
     * such page), unless it has one. It wears the Terminal's layout and look (ADR 0025), so
     * nothing is seeded. Returns the page's id, or -1 when none was added.
     */
    private int addAssistantPage(int afterId) {
        if (wallPages().assistant() != null) return -1;
        com.termux.app.wall.WallPages.Result added = wallPagesStore().edit(pages ->
            pages.add(com.termux.app.page.PageKind.ASSISTANT,
                pages.page(afterId) != null ? afterId : com.termux.app.wall.WallPages.END, null));
        if (mPaneWallController != null) mPaneWallController.refreshPages();
        return added.ok() && added.page != null ? added.page.id : -1;
    }

    /** The chats are kept (ADR 0022): only the page leaves, and with no confirm. */
    private void removeAssistantPageFromWall(int id) {
        com.termux.app.wall.WallPages.Result removed =
            wallPagesStore().edit(pages -> pages.remove(id, 0, true));
        if (removed.ok()) wallPagesStore().edit(pages -> pages.commitRemoval(id));
        if (mPaneWallController != null) mPaneWallController.refreshPages();
    }

    /**
     * Opens the Assistant page, adding it after Home 1 first when the wall has none (ADR 0022
     * section 1). The drawer's entry, a pinned dock icon and {@link
     * com.termux.app.assistant.AssistantEntry#ACTION_OPEN_ASSISTANT} come here.
     */
    private void openAssistant() {
        if (mTilingDesktop != null) {
            // Every kind is a tile (#419): the Assistant opens as a window, not a page.
            closeAppDrawerForLinuxLaunch();
            mTilingDesktop.openAssistant();
            return;
        }
        if (mPaneWallController == null) return;
        closeAppDrawerForLinuxLaunch();
        com.termux.app.assistant.AssistantEntry.open(new com.termux.app.assistant.AssistantEntry.Host() {
            @Override public boolean hasAssistantPage() { return wallPages().assistant() != null; }
            @Override public int firstHomePageId() {
                java.util.List<com.termux.app.wall.WallPages.Page> homes = wallPages().homePages();
                return homes.isEmpty() ? -1 : homes.get(0).id;
            }
            @Override public int currentPageId() { return mPaneWallController.currentPageId(); }
            @Override public boolean goToAssistantPage(boolean animate) {
                return mPaneWallController.goToAssistantPage(animate && isVisible());
            }
            @Override public int addAssistantPage(int afterId) {
                return TermuxActivity.this.addAssistantPage(afterId);
            }
            @Override public void removeAssistantPage(int id) { removeAssistantPageFromWall(id); }
            @Override public void goToPage(int id, boolean animate) {
                mPaneWallController.goToPageId(id, animate && isVisible());
            }
            @Override public void showAdded(@NonNull Runnable undo) {
                // Made from the activity's content, not from the sliding page: the parent walk from
                // the fresh page view settles inside the wall, clipped or under the chrome.
                View root = findViewById(android.R.id.content);
                if (root == null) return;
                com.google.android.material.snackbar.Snackbar bar =
                    com.google.android.material.snackbar.Snackbar.make(root,
                        R.string.assistant_page_added, 4000);
                // Kept just above whichever bottom chrome stands highest, every frame: the chrome
                // grows and moves as the page lands and the keyboard comes up, and the bar's own
                // anchor keeps the first position. Fade, so the bar's translation is ours.
                bar.setAnimationMode(
                    com.google.android.material.snackbar.BaseTransientBottomBar.ANIMATION_MODE_FADE);
                final View barView = bar.getView();
                final View[] chrome = { getVisibleExtraKeys(),
                    findViewById(R.id.accessory_stack_container) };
                final int gap = Math.round(8 * getResources().getDisplayMetrics().density);
                final int[] at = new int[2];
                final android.view.ViewTreeObserver.OnPreDrawListener follow = () -> {
                    if (!barView.isLaidOut()) return true;
                    int top = Integer.MAX_VALUE;
                    for (View c : chrome) {
                        if (c == null || !c.isShown() || c.getHeight() <= 0) continue;
                        c.getLocationOnScreen(at);
                        top = Math.min(top, at[1]);
                    }
                    barView.getLocationOnScreen(at);
                    float natural = at[1] - barView.getTranslationY() + barView.getHeight();
                    float want = top == Integer.MAX_VALUE ? 0f
                        : Math.min(0f, top - gap - natural);
                    if (barView.getTranslationY() != want) barView.setTranslationY(want);
                    return true;
                };
                root.getViewTreeObserver().addOnPreDrawListener(follow);
                bar.addCallback(new com.google.android.material.snackbar.BaseTransientBottomBar
                        .BaseCallback<com.google.android.material.snackbar.Snackbar>() {
                    @Override public void onDismissed(
                            com.google.android.material.snackbar.Snackbar sb, int event) {
                        root.getViewTreeObserver().removeOnPreDrawListener(follow);
                    }
                });
                bar.setAction(R.string.page_overview_undo, v -> undo.run()).show();
            }
        });
    }

    /** Opens the Assistant page for an {@code ACTION_OPEN_ASSISTANT} intent (once). */
    private void handleOpenAssistantIntent(@Nullable Intent intent) {
        if (intent == null || !com.termux.app.assistant.AssistantEntry.ACTION_OPEN_ASSISTANT
            .equals(intent.getAction())) return;
        intent.setAction(null);
        // A cold start delivers the intent before the wall is laid out.
        View root = findViewById(R.id.activity_termux_root_view);
        if (root != null) root.post(this::openAssistant);
        else openAssistant();
    }

    /** The id of the Assistant page, or -1 while the wall has none. */
    private int assistantPageId() {
        com.termux.app.wall.WallPages.Page page = wallPages().assistant();
        return page == null ? -1 : page.id;
    }

    /**
     * The id the Terminal page's look values are read under (ADR 0015 section 6): the Terminal
     * page of the wall, or the wall itself while it has none.
     */
    private int terminalLookPageId() {
        refreshShownPageIds();
        return mShownTerminalPageId < 0 ? TermuxAppSharedPreferences.PAGE_WALL : mShownTerminalPageId;
    }

    /** The wall value {@link #mShownHomePageIds} and {@link #mShownTerminalPageId} were read from. */
    @Nullable private com.termux.app.wall.WallPages mShownPagesValue;
    /** The wall's Home page ids, read once per wall value: read on every dress and look pass. */
    @NonNull private java.util.List<Integer> mShownHomePageIds = java.util.Collections.emptyList();
    /** The Terminal page's id, read once per wall value; -1 for none. */
    private int mShownTerminalPageId = -1;

    /**
     * Reads the Home and Terminal page ids again only when the store holds another wall value
     * (it replaces the value on every change), so the hot paths allocate nothing.
     */
    private void refreshShownPageIds() {
        com.termux.app.wall.WallPages pages = wallPages();
        if (pages == mShownPagesValue) return;
        mShownPagesValue = pages;
        mShownHomePageIds = java.util.Collections.unmodifiableList(
            new java.util.ArrayList<>(pages.homePageIdsForRepository()));
        com.termux.app.wall.WallPages.Page terminal = pages.terminal();
        mShownTerminalPageId = terminal == null ? -1 : terminal.id;
    }

    /** The half whose look the stack (dock, extra keys, keyboard) wears now. */
    private int stackLookPage() {
        return lookPageId(com.termux.app.place.SeamDress.Surface.STACK);
    }

    /**
     * The half the wall rests on, or the one a crossing is arriving at: what a layer that opens
     * over whatever is in front (drawer, sheets, the suggestion bar) wears.
     */
    private int restingPage() {
        return stackLookPage();
    }

    /** The page whose half the stack wears: the committed one, except across the seam. */
    @NonNull
    private com.termux.app.page.PageKind stackDressPage() {
        com.termux.app.page.PageKind page = mCrossing.seam().stackDressPage();
        return page != null ? page : mLastWallPage;
    }

    /**
     * Whether the stack wears a dress apart from the frame's: mid-slide, once it stands the rows of
     * a half that dresses it differently. It then draws its own sheets rather than standing down
     * on a joined Docked frame that belongs to the other half.
     */
    private boolean stackDressedApart() {
        return mCrossing.seam().stackDressedApart(mLastWallPage);
    }

    /** The Floating Style for one surface's dress: the arrangement of the half it wears. */
    /** Whether chrome is in the Floating style (rounded cards) rather than Docked. */
    public boolean isFloatingStyle() {
        return isRoundedStyle(com.termux.app.place.SeamDress.Surface.STATUS);
    }

    private boolean isRoundedStyle(@NonNull com.termux.app.place.SeamDress.Surface surface) {
        return arrangementOf(chromeWearsHomeShape(surface) ? com.termux.app.wall.PageRef.HOME
            : com.termux.app.wall.PageRef.TERMINAL).floating();
    }

    /** Corners in dp as stored for the chrome on screen (-1 is the auto token). */
    private int chromeCornersDp() {
        return chromeCornersDp(com.termux.app.place.SeamDress.Surface.STACK);
    }

    private int chromeCornersDp(@NonNull com.termux.app.place.SeamDress.Surface surface) {
        return mPreferences == null
            ? TermuxPreferenceConstants.TERMUX_APP.DEFAULT_SURFACE_GLOBAL_CORNER_RADIUS
            : mPreferences.getLayoutCornersDp(chromeWearsHomeShape(surface));
    }

    /** Margin in dp as stored for the chrome on screen. */
    private int chromeMarginDp() {
        return chromeMarginDp(com.termux.app.place.SeamDress.Surface.STACK);
    }

    private int chromeMarginDp(@NonNull com.termux.app.place.SeamDress.Surface surface) {
        return mPreferences == null
            ? TermuxPreferenceConstants.TERMUX_APP.DEFAULT_SURFACE_GLOBAL_SIDE_GAP
            : mPreferences.getLayoutMarginDp(chromeWearsHomeShape(surface));
    }


    /**
     * A settle from {@code from} onto {@code to} that crosses between the halves of the wall while
     * Home's Style, Corners or Margin differ from the Terminal's: the chrome is dressed again as
     * the Appearance editor dresses it for a Style change (a launch's dress, the dock and terminal
     * heights, the status bar, the keyboard and the dock's styling), now that every read above
     * answers for the arriving half. Nothing happens while the halves agree, which is every
     * install until the user sets Home apart.
     */
    private void restyleChromeForHalfIfChanged(@NonNull com.termux.app.page.PageKind from,
                                               @NonNull com.termux.app.page.PageKind to) {
        if (mPreferences == null || mChrome == null) return;
        if (dressOf(from).shape().equals(dressOf(to).shape()) && !looksDifferAcross(from, to))
            return;
        // Traced: 58-88 ms on pong, so it must never run inside a landing's frame.
        Trace.beginSection("Wall.halfRedress");
        // A dock dress a landing's commit made before this one is no longer what it wears.
        mHalfRedressCount++;
        try {
            redressChromeFromState(false);
            updateAppLauncherBarHeight();
            setTerminalToolbarHeight(true);
            refreshTerminalWindowBar();
            if (mInAppKeyboard != null) mInAppKeyboard.onPreferencesReloaded();
            applySuggestionBarSurfaceStyling();
            mChrome.requestSync(ChromeRenderer.SCOPE_APPLY_THIS_FRAME
                | ChromeRenderer.SCOPE_ACCESSORY_RENDER);
        } finally {
            Trace.endSection();
        }
    }

    /** Set through a landing's commit while the stack already wears the half it landed on. */
    private boolean mLandingStackDressed;
    /** A half re-dress a landing left for after its frame: from where, to where; null when none. */
    @Nullable private com.termux.app.page.PageKind mHalfRestyleFrom;
    @Nullable private com.termux.app.page.PageKind mHalfRestyleTo;
    private final Runnable mLandingSettleRunnable = this::runLandingSettle;

    /** {@link #restyleChromeForHalfIfChanged} for {@code from} onto {@code to}, after this frame. */
    private void deferHalfRestyle(@NonNull com.termux.app.page.PageKind from,
                                  @NonNull com.termux.app.page.PageKind to) {
        if (mHalfRestyleFrom == null) mHalfRestyleFrom = from;
        mHalfRestyleTo = to;
    }

    /** Runs a deferred half re-dress now, if one waits. */
    private void flushLandingRestyle() {
        com.termux.app.page.PageKind from = mHalfRestyleFrom;
        com.termux.app.page.PageKind to = mHalfRestyleTo;
        mHalfRestyleFrom = null;
        mHalfRestyleTo = null;
        if (from != null && to != null) restyleChromeForHalfIfChanged(from, to);
    }

    /**
     * Books {@link #runLandingSettle} for just after the frame a landing is drawn in: a plain post
     * from the frame's own callbacks runs once that frame's traversal has been handed off.
     */
    private void postLandingSettle() {
        if (mHalfRestyleFrom == null && (mChrome == null || !mChrome.isEvenOutHeld())
            && mDockFilterPlan.phase() != com.termux.app.chrome.DockFilterPlan.Phase.LANDED) return;
        View root = getWindow().getDecorView();
        root.removeCallbacks(mLandingSettleRunnable);
        root.post(mLandingSettleRunnable);
    }

    /**
     * After a landing's frame: the half's re-dress it deferred, then the even-out held through
     * the travel is let go and measured where the chrome rests. A crossing already under way again
     * keeps the hold; its own landing settles it.
     */
    private void runLandingSettle() {
        if (isDestroyed()) return;
        flushLandingRestyle();
        // The re-dress has laid the bar out at the Margin it eased to; whatever it found to do,
        // no ease outlives the crossing.
        if (!mCrossing.crossing()) mStatusBar.resetStatusMarginEase();
        if (mChrome != null && !mCrossing.crossing()) mChrome.settleEvenOut();
        // The dock's frost stood on the landed end through the landing's frame; from here a pass
        // measures it where it rests, and one is booked so the measure does not wait for one.
        if (mDockFilterPlan.phase() == com.termux.app.chrome.DockFilterPlan.Phase.LANDED) {
            mDockFilterPlan.settle(mCrossing.crossing());
            if (mChrome != null
                && mDockFilterPlan.phase() == com.termux.app.chrome.DockFilterPlan.Phase.REST)
                mChrome.requestSync(com.termux.app.chrome.ChromeRenderer.SCOPE_ACCESSORY_RENDER);
        }
    }

    /**
     * Whether a settle from {@code from} onto {@code to} crosses between halves of the wall whose
     * look values differ (ADR 0013), which the chrome must be dressed again for.
     */
    private boolean looksDifferAcross(@NonNull com.termux.app.page.PageKind from,
                                      @NonNull com.termux.app.page.PageKind to) {
        if (com.termux.app.place.SeamDress.screenOf(from)
                == com.termux.app.place.SeamDress.screenOf(to))
            return false;
        return !com.termux.app.place.HalfLook.read(mPreferences, TermuxAppSharedPreferences.PAGE_WALL)
            .equals(com.termux.app.place.HalfLook.read(mPreferences, terminalLookPageId()));
    }

    /** Corners, the one Floating radius, in px: the half's corner radius, or the auto token. */
    private float layoutCornersPx() {
        return layoutCornersPx(com.termux.app.place.SeamDress.Surface.STACK);
    }

    private float layoutCornersPx(@NonNull com.termux.app.place.SeamDress.Surface surface) {
        int dp = chromeCornersDp(surface);
        if (dp < 0) dp = TermuxAppSharedPreferences.resolveAutoCornerRadiusDp(null, true);
        return dpToPx(dp);
    }

    /** Margin, the air between and around Floating cards, in px. */
    private float layoutMarginPx() {
        return layoutMarginPx(com.termux.app.place.SeamDress.Surface.STACK);
    }

    private float layoutMarginPx(@NonNull com.termux.app.place.SeamDress.Surface surface) {
        return dpToPx(Math.max(0, chromeMarginDp(surface)));
    }

    /**
     * The gap between split panes, in dp: the stored Inner gap — air between Floating cards, the
     * gutter of frame glass between Docked inserts. The divider's touch strip has its own minimum.
     */
    private int terminalPaneGapDp() {
        return com.termux.app.chrome.LiveChromeShape.paneGapDp(mPreferences != null
            ? mPreferences.getTerminalPaneGap()
            : TermuxPreferenceConstants.TERMUX_APP.DEFAULT_TERMINAL_PANE_GAP);
    }

    /** The device's screen radius, which a Docked frame's outer corners take; 28dp when unknown. */
    private float screenRadiusPx() {
        float reported = 0f;
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S) {
            android.view.WindowInsets insets = getWindow().getDecorView().getRootWindowInsets();
            if (insets != null) {
                for (int position : new int[] {android.view.RoundedCorner.POSITION_TOP_LEFT,
                    android.view.RoundedCorner.POSITION_TOP_RIGHT,
                    android.view.RoundedCorner.POSITION_BOTTOM_LEFT,
                    android.view.RoundedCorner.POSITION_BOTTOM_RIGHT}) {
                    android.view.RoundedCorner corner = insets.getRoundedCorner(position);
                    if (corner != null) reported = Math.max(reported, corner.getRadius());
                }
            }
        }
        return com.termux.app.chrome.LiveChromeShape.screenRadiusPx(reported,
            getResources().getDisplayMetrics().density);
    }

    /** How thick one element's band stands now, along its own axis: measured, else the target. */
    private float chromeThicknessPx(@NonNull Element element, @NonNull PlaceLayout layout) {
        PlaceLayout.Edge edge = layout.slot(element).edge;
        View host = edgeStackHost(element, edge);
        if (host != null && host.getVisibility() != View.GONE) {
            int measured = edge.isOnSide() ? host.getWidth() : host.getHeight();
            if (measured > 0) return measured;
        }
        if (element == Element.STATUS)
            return mStatusBar.targetStatusBarHeightPx(
                isRoundedStyle(com.termux.app.place.SeamDress.Surface.STATUS),
                mStatusBar.isStatusBarCompact());
        // Not laid out yet: a side column's band is the shared frame width, the same the host
        // is given, so the insert's gutter lines up with the glass from the first frame.
        if (edge.isOnSide()) {
            int shared = dockedFrameSharedBandPx();
            if (shared > 0 && (element == Element.EXTRA_KEYS && extraKeysColumnOnSide(layout)
                || element == Element.AZ && azHostOnSide(layout))) return shared;
        }
        return 0f;
    }

    /**
     * Every chrome shape for the frame as it stands: the layout, the Style and the live band
     * thicknesses through the shape model. The one answer every outline, rim and pane reads; it
     * is cheap (a handful of rects), so it is asked for rather than cached.
     */
    @NonNull
    private com.termux.app.place.ChromeShape chromeShape() {
        return chromeShape(com.termux.app.place.SeamDress.Surface.STACK);
    }

    /**
     * The same, in one surface's dress (SeamDress): the status bar's and the frame's pieces are
     * read off the model in their own half's Style, Corners and Margin while a slide across the
     * seam dresses the stack in the other half's.
     */
    @NonNull
    private com.termux.app.place.ChromeShape chromeShape(
            @NonNull com.termux.app.place.SeamDress.Surface surface) {
        return chromeShape(surface, arrangement().layout());
    }

    /** The same, for a layout in hand: it may not be the stored one during a slide or a pre-roll. */
    @NonNull
    private com.termux.app.place.ChromeShape chromeShape(@NonNull PlaceLayout stored) {
        return chromeShape(com.termux.app.place.SeamDress.Surface.STACK, stored);
    }

    @NonNull
    private com.termux.app.place.ChromeShape chromeShape(
            @NonNull com.termux.app.place.SeamDress.Surface surface, @NonNull PlaceLayout stored) {
        View root = hotView(R.id.activity_termux_root_view);
        android.util.DisplayMetrics metrics = getResources().getDisplayMetrics();
        int width = root != null && root.getWidth() > 0 ? root.getWidth() : metrics.widthPixels;
        int height = root != null && root.getHeight() > 0 ? root.getHeight() : metrics.heightPixels;
        // The keyboard the chrome stands around is the in-app one. The system IME never raises
        // it, so asking that left the keyboard out of the shape: no piece, so no card, rim or
        // radius of its own for the host to read.
        boolean keyboardUp = isInAppKeyboardShown();
        PlaceLayout layout = stored.withKeyboardShown(keyboardUp);
        float status = chromeThicknessPx(Element.STATUS, layout);
        float apps = chromeThicknessPx(Element.APPS, layout);
        float az = chromeThicknessPx(Element.AZ, layout);
        float keys = chromeThicknessPx(Element.EXTRA_KEYS, layout);
        View keyboardHost = hotView(R.id.inapp_keyboard_view_host);
        // Before its first layout the host has no height yet: the last measure stands in, so the
        // piece is not a zero-height one whose radius clamps to nothing.
        float keyboard = keyboardUp && keyboardHost != null
            ? BottomInsets.keyboardKeysPx(keyboardHost.getHeight() > 0 ? keyboardHost.getHeight()
                : mKeyboardGeometry.desiredHeightPx(), mDressedKeyboardFootPx) : 0f;
        return com.termux.app.chrome.LiveChromeShape.of(layout,
            arrangementOf(chromeWearsHomeShape(surface) ? com.termux.app.wall.PageRef.HOME
                : com.termux.app.wall.PageRef.TERMINAL).layoutStyle(), width, height,
            com.termux.app.place.ChromeShapeModel.Thickness.of(status, status, apps, apps, az, az,
                keys, keys, keyboard),
            layoutCornersPx(surface), layoutMarginPx(surface), screenRadiusPx(),
            metrics.density, Math.max(1, visiblePaneCount()),
            width >= height ? com.termux.app.place.ChromeShapeModel.SplitAxis.SIDE_BY_SIDE
                : com.termux.app.place.ChromeShapeModel.SplitAxis.STACKED, 0f, null,
            // The insert stands as close to the bars as the terminal does, on the Terminal only.
            !chromeWearsHomeShape(surface)
                && com.termux.app.wall.PaneWallPolicy.isTerminalPlace(mLastWallPage),
            dpToPx(terminalPaneGapDp()));
    }

    /**
     * Where the keyboard's host stands in the model: the keyboard, or a split keyboard's two
     * halves. The host is one surface across both halves and the parting between them, so its
     * clip and rim are those of the pieces' union, as the docked keyboard's are of its one piece.
     */
    private static final com.termux.app.place.ChromeShape.PieceId[] KEYBOARD_PIECES = {
        com.termux.app.place.ChromeShape.PieceId.KEYBOARD,
        com.termux.app.place.ChromeShape.PieceId.KEYBOARD_LEFT,
        com.termux.app.place.ChromeShape.PieceId.KEYBOARD_RIGHT};

    /** The clip of the view that stands where {@code ids} stand in the model; null if none shown. */
    @Nullable
    private com.termux.app.chrome.LiveChromeShape.Clip chromeClipOf(
        @NonNull com.termux.app.place.ChromeShape.PieceId... ids) {
        return com.termux.app.chrome.LiveChromeShape.outlineOf(chromeShape(surfaceOf(ids)),
            Arrays.asList(ids));
    }

    /** What the views standing where {@code ids} stand draw rim light on, as edge bits. */
    private int chromeRimEdges(@NonNull com.termux.app.place.ChromeShape.PieceId... ids) {
        return com.termux.app.chrome.LiveChromeShape.rimEdges(chromeShape(surfaceOf(ids)),
            Arrays.asList(ids));
    }

    /** The surface whose dress the model's {@code ids} are read in: the status bar's, or the stack's. */
    @NonNull
    private static com.termux.app.place.SeamDress.Surface surfaceOf(
            @NonNull com.termux.app.place.ChromeShape.PieceId... ids) {
        for (com.termux.app.place.ChromeShape.PieceId id : ids)
            if (id == com.termux.app.place.ChromeShape.PieceId.STATUS)
                return com.termux.app.place.SeamDress.Surface.STATUS;
        return com.termux.app.place.SeamDress.Surface.STACK;
    }

    /**
     * Symmetric outer screen inset for one editable surface. The floating capsule sits at the
     * configured dp (10dp by default · design redline · Outer margin 10); the edge-to-edge default
     * shape stays flush until the user pushes the inset past that baseline.
     */
    private int resolveSurfaceHorizontalInsetPx(int configuredDp, boolean capsule) {
        return DockLayoutPolicy.surfaceHorizontalInsetPx(configuredDp, capsule,
            getResources().getDisplayMetrics().density);
    }

    /** The dock's outer screen margin, shared with the app drawer plane's seed rect. */
    public int getDockHorizontalInsetPx() {
        return mDock.appliedDockLayout().horizontalInsetPx;
    }

    /** The side gap the keyboard's host is inset by, in dp, before the Style says whether it applies. */
    private int inAppKeyboardMarginDp() {
        return mPreferences == null
            ? TermuxPreferenceConstants.TERMUX_APP.DEFAULT_IN_APP_KEYBOARD_HORIZONTAL_INSET
            : TermuxAppSharedPreferences.clampSurfaceHorizontalInset(chromeMarginDp());
    }

    /**
     * The top pane's COMPACT height in the current style. Read by the app drawer's top-band
     * choreography, which fakes the expanded→compact collapse with a clip while the plane grows:
     * the real two-state animator writes the pane's height, and the drawer transition freezes
     * exactly that.
     */
    public int getCompactTopStatusBarHeightPx() {
        return mDock.appliedDockLayout().compactStatusBarHeightPx;
    }

    /**
     * The Floating card's radius for a surface this tall, Corners capped at half of it. Under
     * Docked no surface carries a radius of its own: the frame's outer corners are the model's.
     */
    public float resolveDockCapsuleCornerRadiusPx(int surfaceHeightPx) {
        return mDock.resolveDockCapsuleCornerRadiusPx(surfaceHeightPx);
    }

    /**
     * The model's pieces of the dock's own rows, the ones standing over the keyboard. Where the
     * dock and the keyboard share one glass ({@code withKeyboard}) the keyboard's piece is part
     * of the same sheet, so its clip, rim and seams are the model's for the whole of it.
     */
    @NonNull
    private List<com.termux.app.place.ChromeShape.PieceId> dockPieceIds(boolean withKeyboard) {
        List<Element> rows = new ArrayList<>(
            EdgeStackPolicy.overKeyboard(arrangement().layout()));
        List<com.termux.app.place.ChromeShape.PieceId> ids = chromePieceIds(rows);
        if (withKeyboard) ids.addAll(Arrays.asList(KEYBOARD_PIECES));
        return ids;
    }

    /** The dock's shape on {@code surface} (DockController); kept for DockBeadsLeaveTest. */
    private void applyDockSurfaceShape(@NonNull View surface, boolean capsule, int surfaceHeightPx,
                                       boolean ownsInnerEdge, boolean innerRim) {
        mDock.applyDockSurfaceShape(surface, capsule, surfaceHeightPx, ownsInnerEdge, innerRim);
    }

    /** Whether a Home page stands at rest with the stack dressed as it: no crossing, no travel. */
    private boolean isHomeAtRest() {
        return !peekChromeTravelling()
            && com.termux.app.wall.PaneWallPolicy.isHomePlace(stackDressPage());
    }

    /**
     * Peek glass on the dock's host, for the dock's shape (DockController.Host#dressPeekCard):
     * the card is worked out from the row and the host as laid out now; a layout that moves
     * either reads it again (onPeekLayoutSettled). Whether a card stands, the host dressed as it.
     */
    private boolean dressPeekCard(@NonNull View surface) {
        syncPeekListeners();
        com.termux.app.dock.PeekGlassGeometry.Card wasPeek = mPeekAim.card();
        mPeekAim.set(mPeekAim.resolve());
        com.termux.app.dock.PeekGlassGeometry.Card shown = mPeekAim.card();
        // The glass program's rect is the card's (or the slab's again): re-aimed once here,
        // since the pass's backdrop may find nothing else changed and keep its effect.
        if (!java.util.Objects.equals(wasPeek, shown)) rebuildBackdropGlassEffectForLens();
        if (shown != null) {
            // Its top edge through the icons' centres, its lower corners past the screen's
            // edge: the host is clipped to it, and where the program does not draw the
            // glass's edge the rim follows the card's outline.
            if (!mDock.dockGlassDrawsEdge())
                com.termux.app.dock.PeekCardAim.cut(shown, mPeekAim.cutBuffer());
            surface.setBackground(mDock.dockGlassDrawsEdge() ? null
                : peekRimDrawable(mPeekAim.cutBuffer(), surface.getWidth(), surface.getHeight()));
            if (surface.getOutlineProvider() != mPeekOutline)
                surface.setOutlineProvider(mPeekOutline);
            else
                surface.invalidateOutline();
            surface.setClipToOutline(true);
            syncPeekReflection();
            return true;
        }
        syncPeekReflection();
        return false;
    }

    private void configureAccessoryTopEdgeFx(boolean visible, float barAlpha) {
        View edgeFx = findViewById(R.id.accessory_top_edge_fx);
        if (edgeFx == null) {
            return;
        }
        com.termux.app.dock.CapsuleGlass.dressTopEdge(edgeFx, visible, barAlpha,
            resolveAccessoryOutlineColor());
    }

    @NonNull
    private ChromeSpec buildChromeSpec() {
        boolean keyboardShown = isInAppKeyboardShown();
        int keyboardHeight = keyboardShown ? mKeyboardGeometry.measureHeightPx() : 0;
        if (mPreferences == null) {
            return new ChromeSpec(false, keyboardShown, keyboardHeight,
                false, false, false, false, 1.0f, 0);
        }
        // Mirror the metrics-side collapse: zero-height dock rows still paint at full size through
        // the stack's clipChildren=false chain, so the render state must hide them outright. A row
        // the place stands on a screen edge — the apps rail, an extra keys column — is a column
        // laid out beside the content root, and its row collapses like a switched-off one.
        ResolvedArrangement arranged = arrangement();
        PlaceLayout layout = arranged.layout();
        boolean appsRowEnabled = arranged.appsRowShown();
        // The dock's own row. A place that stands the bar on another edge gives the dock nothing:
        // the row goes, and with it the whole stack when it was the only thing on it.
        boolean azRowEnabled = arranged.azRowOnDock();
        boolean extraKeysRowEnabled = arranged.extraKeysRowShown();
        boolean dockShown = arranged.dockShown();
        int blurRadiusDp = getEffectiveExtraKeysBlurRadius();
        float barAlpha = mPreferences.getAppBarOpacity(stackLookPage()) / 100f;
        return new ChromeSpec(
            dockShown,
            keyboardShown,
            keyboardHeight,
            ChromePolicy.dockBlurEnabled(blurRadiusDp),
            appsRowEnabled,
            azRowEnabled,
            extraKeysRowEnabled,
            barAlpha,
            blurRadiusDp
        );
    }

    private boolean isInAppKeyboardShown() {
        if (mInAppKeyboard != null) {
            return mInAppKeyboard.isVisible();
        }
        // Read per arrangement while maximised: the view is looked up only before the keyboard is.
        View keyboardContainer = findViewById(R.id.inapp_keyboard_container);
        return keyboardContainer != null && keyboardContainer.getVisibility() != View.GONE;
    }

    /**
     * Whether the accessory stack is on screen. Since the whole bottom edge stands in it, a status
     * bar the place put along the bottom keeps it up on its own — the dock's rows can all be
     * hidden or standing on other edges and the bar still has to be drawn.
     */
    static boolean shouldShowAccessoryStack(boolean toolbarShown, boolean keyboardShown,
                                            boolean bottomStatusBar) {
        return com.termux.app.dock.DockRows.stackShown(toolbarShown, keyboardShown, bottomStatusBar);
    }

    static int computeAccessoryStackHeight(int dockContentHeight, int terminalFlushPadding,
                                           int keyboardHeight) {
        return Math.max(0, dockContentHeight)
            + Math.max(0, terminalFlushPadding)
            + Math.max(0, keyboardHeight);
    }

    /**
     * The dock's and keyboard's blur radius as the glass draws it.
     *
     * <p>This used to drop to 0 whenever a wallpaper <em>service</em> was running — but some ROMs
     * (One UI, issue #37) serve a plain static picture through one, so the bands lost their blur on
     * a still image while the terminal pane, which never had the gate, blurred the very same frame.
     * The gate is now the same for every glass in the app: the readable picture is blurred wherever
     * there is one, and only the ROM default nobody chose ({@link WallpaperPicture#NO_STILL}) sends
     * every band to its plain tint. Downstream, a radius of 0 already means "no blur".
     */
    private int getEffectiveExtraKeysBlurRadius() {
        if (mPreferences == null || !wallpaperSampleable()) {
            return 0;
        }
        return Math.max(0, mPreferences.getExtraKeysBlurRadius(stackLookPage()));
    }

    /**
     * The keyboard's own blur radius as its own glass draws it — the KEYBOARD slot's blur, which
     * follows Global until detached, so an untouched keyboard resolves to the same number
     * {@link #getEffectiveExtraKeysBlurRadius()} does. See that method for the wallpaper-does-not-
     * blur gate this mirrors.
     */
    private int getEffectiveInAppKeyboardBlurRadius() {
        if (mPreferences == null || !wallpaperSampleable()) return 0;
        return Math.max(0, terlKeyboardLook().blurDp(
            mPreferences.getInAppKeyboardBlurRadius(stackLookPage())));
    }

    /**
     * Which picture the glass can blur, and how sure we are it is the one on screen — see
     * {@link WallpaperPicture}. Read from the cached value, because resolving it opens a file
     * descriptor and every surface in a render pass asks: {@link #refreshWallpaperPicture()} is
     * what actually goes to Android, on arrival and whenever the wallpaper changes.
     */
    @NonNull
    WallpaperPicture wallpaperPicture() {
        return mWallpaperPicture;
    }

    /**
     * The one answer to "is there a wallpaper image any surface may sample": Show wallpaper is on
     * and the readable picture is one worth blurring. Every glass gate asks this, so with the
     * switch off no chrome surface holds a wallpaper frame, blurred or sharp.
     */
    boolean wallpaperSampleable() {
        return com.termux.app.chrome.WallpaperPicturePolicy.sampleable(
            mPreferences == null || mPreferences.isUseSystemWallpaperEnabled(), mWallpaperPicture);
    }

    /**
     * Ask Android which picture is on screen now, and re-dress everything if the answer moved.
     *
     * <p>The three facts behind it are only readable from the system, so this runs where a change
     * can have happened: on arrival, after the in-app picker sets a wallpaper, when the wallpaper
     * colors listener fires (which is how a wallpaper swap made outside the app reaches us), and
     * after the wallpaper-read permission is granted.
     *
     * @return true when the picture changed, so the caller can skip a redraw nothing needs
     */
    private boolean refreshWallpaperPicture() {
        return refreshWallpaperPicture(refreshWallpaperSourceFacts());
    }

    /** {@link #refreshWallpaperPicture()} with source facts the caller has just read. */
    private boolean refreshWallpaperPicture(@NonNull com.termux.app.chrome.WallpaperSourceFacts facts) {
        WallpaperPicture picture = WallpaperPictureReader.read(this, mPreferences,
            facts.systemWallpaperId, facts.appOnlyOnScreen());
        if (picture == mWallpaperPicture) return false;
        mWallpaperPicture = picture;
        return true;
    }

    /** {@link #refreshWallpaperPicture()} on an arrival, re-dressing the glass only if it moved. */
    private void refreshWallpaperPictureOnArrival() {
        refreshTerlWallpaperLooks();
        if (refreshWallpaperPicture()) mChrome.onWallpaperChanged();
    }

    /**
     * The dock's rectangle on screen, for a surface that wants to sit exactly where the dock is.
     *
     * @return false when there is no dock laid out — a terminal-only install, or before first layout.
     */
    /**
     * The terminal's own frame on screen: the pane region less the insets its border is drawn at, so
     * a surface that has to meet that edge — the keybind hints, a foot panel on the sheet plane —
     * lands on the same line the border does.
     */
    private boolean terminalFrameOnScreen(@NonNull Rect out) {
        View host = findViewById(R.id.terminal_surface_host);
        if (host == null || host.getWidth() <= 0 || host.getHeight() <= 0
            || host.getVisibility() != View.VISIBLE) {
            return false;
        }
        int[] location = new int[2];
        host.getLocationOnScreen(location);
        terminalFrameInsetsPx(mTmpFrameInsets);
        int sideInset = mTmpFrameInsets[0];
        int verticalInset = mTmpFrameInsets[1];
        out.set(location[0] + sideInset, location[1] + verticalInset,
            location[0] + host.getWidth() - sideInset,
            location[1] + host.getHeight() - frontPageRoomPx() - verticalInset);
        return out.width() > 0 && out.height() > 0;
    }



    private boolean shouldUseAccessoryRenderEffectBlur(@NonNull ChromeSpec state) {
        return state.toolbarShown
            && state.blurEnabled
            && !dockSheetStandsDownOnFrame();
    }

    private void clearAccessoryRenderEffectBackdrop() {
        ImageView backdrop = findViewById(R.id.accessory_blur_backdrop);
        if (backdrop == null) {
            return;
        }
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S) {
            backdrop.setRenderEffect(null);
        }
        if (mLiveBackdrop != null) mLiveBackdrop.detach(backdrop);
        mGlass.unregister(DOCK_GLASS);
        backdrop.setImageDrawable(null);
        backdrop.setVisibility(View.GONE);
        // No frame: the dock's content stands on the page's dim again.
        mChrome.ink().noteBandFrame(com.termux.app.chrome.GlassBackdropCache.Band.DOCK, false);
        mGlassEffects.invalidateParams(); // no live backdrop shader -> key lens falls back to the bubble border
        mChrome.ledger().reset(SurfaceDirtyLedger.Backdrop.ACCESSORY);
        mDock.setDockProgramEdge(false);
        mDock.syncDockShelf(null);
    }

    /**
     * Lets the app drawer's plane reach the physical screen edges.
     *
     * <p>{@code fitsSystemWindows} pads the root by the status bar at the top and the navigation
     * bar at the bottom, so every child of it — the drawer host included — begins and ends inside
     * them. The open drawer is a page, not a card: it gives those two paddings straight back as
     * negative margins, which makes its glass, its backdrop blur and its wallpaper frost one sheet
     * from the top bezel to the bottom one, instead of a band with the status-bar inset strip
     * standing above it and the under-pill strip showing below. Nothing inside the drawer moves:
     * the controller reads these same two margins back and lays the grid out in the safe area.
     *
     * <p>Written from the insets rather than from the root's measured padding, because this runs on
     * the content view's own insets listener — one dispatch ahead of the root's — and because these
     * are the very numbers the two strips are sized by, so the sheet meets them exactly.
     *
     * <p>The camera cutout counts as a bar here. With the status bar hidden the bars report no top
     * inset, but the root still keeps clear of the cutout, and a drawer bled by the bars alone left
     * its dim a square-cornered band starting under the cutout, with the wallpaper bright above it
     * (#69).
     */
    private void applyAppDrawerEdgeBleed(@NonNull WindowInsetsCompat insetsCompat) {
        mSheets.applyAppDrawerEdgeBleed(insetsCompat);
    }

    /**
     * The default edge-to-edge dock and a glass-matched keyboard are one rectangular material.
     * Render one backdrop through both instead of placing two independently cropped glass layers
     * next to each other. Floating/capsule styling deliberately remains on its separate path.
     */
    private boolean shouldUseUnifiedDefaultKeyboardGlassSurface(@NonNull ChromeSpec state) {
        // A scheme background color or a non-default background opacity must repaint only the
        // keyboard, not the material it would share with the dock, so either drops the keyboard
        // to its own local surface path. Every arrangement that is not the glass drops out of it
        // too, and for one reason: it shares no material with the dock. A floating card and an
        // overlaying keyboard lie over the content, and the dock underneath keeps the glass it
        // has. A split keyboard is the docked one with its keys parted, so it shares the sheet
        // like the docked one does. Bands under the keyboard wear a card of their own below it,
        // and one material spanning the dock and the keyboard would run on down behind that card.
        if (underKeyboardBandsShown()) return false;
        // Apart under Docked (#304) the keyboard is one surface with the Terminal's own host
        // exactly where the Terminal's rest's answer puts it on that host, and never with Home's
        // pinned host: the two agree while the cards stand apart.
        if (mSideCards.terminalHostOn()) {
            com.termux.app.place.RestCards.Card card = mSideCards.terminalHostCard();
            if (card == null || stackDressPage() != com.termux.app.page.PageKind.TERMINAL
                || !card.pieces.contains(com.termux.app.place.ChromeShape.PieceId.KEYBOARD))
                return false;
        }
        // The page whose rows the stack stands (stackDressPage: the committed page at rest, the
        // seam's stack page mid-crossing): on Home the keyboard covers the dock and is never one
        // surface with it, unless Home's keyboard is always on and the dock rides it.
        return ChromePolicy.shouldUseUnifiedDefaultKeyboardGlassSurface(state.toolbarShown,
            state.keyboardShown, arrangement().floating(), isInAppKeyboardGlassSurface(),
            com.termux.app.place.HomeKeyboardCover.liftsRows(stackDressPage(),
                isHomeKeyboardAlwaysOn()))
            && !hasInAppKeyboardBackgroundOverride()
            && inAppKeyboardMaterial() == KeyboardMaterialPolicy.Material.GLASS
            // Over a Display page the unified glass would lay the wallpaper over the display.
            && !inAppKeyboardSeesThroughToDisplay();
    }

    /** The form the keyboard on screen is actually in, floating included. */
    @NonNull
    private PlaceLayout.KeyboardForm inAppKeyboardForm() {
        if (isKeyboardFloating()) return PlaceLayout.KeyboardForm.FLOATING;
        if (isInAppKeyboardSplit()) return PlaceLayout.KeyboardForm.SPLIT;
        return PlaceLayout.KeyboardForm.DOCKED;
    }

    /**
     * Whether the keyboard lies over this place's content instead of shrinking it, which is what
     * decides its material. Asked of the place the chrome is committed to rather than the page the
     * wall has committed to at release, so the material changes at settle with the rest of the
     * place's state — and of the place a pre-rolled keyboard is travelling toward while it slides,
     * so it rises in the material it will keep.
     */
    private boolean inAppKeyboardOverlays() {
        return KeyboardOverlayPolicy.overlays(inAppKeyboardPlace(), isDisplayWindowInFront(),
            arrangement().layout());
    }

    /** Whether that same place is Home, whose overlaying keyboard still wears the glass. */
    private boolean inAppKeyboardOnHome() {
        return inAppKeyboardPlace() == com.termux.app.page.PageKind.HOME;
    }

    /** Whether that same place is a Display page, where the keyboard sees through to the display. */
    private boolean inAppKeyboardOnDisplay() {
        return inAppKeyboardPlace() == com.termux.app.page.PageKind.DISPLAY;
    }

    /**
     * Whether the keyboard's glass is the Display page's: no wallpaper frame of its own, the live
     * display showing through, frosted by {@link com.termux.app.chrome.DisplayKeyboardBlur}.
     */
    private boolean inAppKeyboardSeesThroughToDisplay() {
        return KeyboardMaterialPolicy.seesThroughToDisplay(inAppKeyboardForm(),
            inAppKeyboardOverlays(), inAppKeyboardOnDisplay(),
            KeyboardOverlayPolicy.contentUnderWholeBed(arrangement().layout()));
    }

    @NonNull
    private com.termux.app.page.PageKind inAppKeyboardPlace() {
        com.termux.app.page.PageKind travelling = mCrossing.keyboardPlace();
        return travelling != null ? travelling : mLastWallPage;
    }

    /** Glass, one opaque panel, or nothing at all — see {@link KeyboardMaterialPolicy}. */
    @NonNull
    private KeyboardMaterialPolicy.Material inAppKeyboardMaterial() {
        return KeyboardMaterialPolicy.hostMaterial(inAppKeyboardForm(), inAppKeyboardOverlays(),
            inAppKeyboardOnHome(), inAppKeyboardOnDisplay());
    }

    // ---- The band behind the system bar and the bar across the seam ---------------------------
    //
    // On pong (TopBandDiag) the strip's glass behind the system status bar was re-dressed into the
    // Terminal's look in place, full width, on a crossing's second frame, while the bar's own
    // glass under it kept Home's until the landing: a dark band, then the bar a moment later. Now
    // the first re-dress of either mid-crossing builds both in the arriving dress, once, beside
    // the dresses they wore, and both cross by the one share of the way (SeamFade). Later
    // re-dresses in the crossing change nothing; the landing leaves each on the dress it reached.

    /**
     * A crossing begins, or reads its ends again for another page of the other half: the top
     * stack's two ends, each with what its layout says of the bar, its look, and the chips and
     * strip as they stand. The two ends draw the bar in one outline exactly when the seam says
     * the bar stands still ({@link com.termux.app.place.SeamCrossing#barStill}), which the scene's
     * {@code shared} must agree with. Each end's inks are measured here, once (a crossing
     * measures nothing, ADR 0029 section 9): the committed end as the bar stands, the other under
     * its page's look; an end that cannot be measured wears the other's, so nothing flips.
     */
    private void beginTopStack(@NonNull com.termux.app.wall.PageRef here,
                               @NonNull com.termux.app.wall.PageRef there,
                               @NonNull PlaceLayout hereLayout, @NonNull PlaceLayout thereLayout) {
        boolean still = mCrossing.seam().barStill();
        fillTopEnd(mTopEndHere, here, hereLayout, 0);
        fillTopEnd(mTopEndThere, there, thereLayout, still ? 0 : 1);
        View strip = findViewById(R.id.terminal_status_bar_glass_surface);
        boolean stripHereShown = mTopFadeActive ? mTopFadeStripHere != null
            : strip != null && strip.isShown();
        fillTopInks(here, there);
        mTopStackRenderer.begin(mTopEndHere, mTopEndThere, stripHereShown);
    }

    /**
     * Both top ends' inks: the chrome wears one look on every page (ADR 0031), so both ends are
     * inked from the glass drawn now; the sessions chip, which slides with the chips and does not
     * blend, is inked on the Terminal end's band.
     */
    private void fillTopInks(@NonNull com.termux.app.wall.PageRef here,
                             @NonNull com.termux.app.wall.PageRef there) {
        boolean ok = mStatusBar.resolveStatusInks(mTopEndHere.inks);
        com.termux.app.chrome.OnGlass.Resolution band = ok ? mStatusBar.resolvedStatusBand() : null;
        if (ok) System.arraycopy(mTopEndHere.inks, 0, mTopEndThere.inks, 0,
            mTopEndHere.inks.length);
        // The bar's glass shows the ground beneath it (#283): toward a page whose ground differs,
        // the arriving end is inked over that ground, read now and recording nothing, so the
        // inks cross with the wall to what the landing measures.
        if (ok && com.termux.app.chrome.GlassGround.ON) {
            int thereGround = groundOfWallPage(there.kind);
            if (thereGround != groundOfWallPage(here.kind))
                mStatusBar.probeStatusInks(mTopEndThere.inks, thereGround);
        }
        mTopEndHere.inksResolved = ok;
        mTopEndThere.inksResolved = ok;
        mStatusBar.applySessionsBand(band);
    }

    private void fillTopEnd(@NonNull com.termux.app.statusbar.TopStackScene.End end,
                            @NonNull com.termux.app.wall.PageRef page, @NonNull PlaceLayout layout,
                            int outlineKey) {
        com.termux.app.place.Slot status = layout.slot(Element.STATUS);
        end.barShown = !status.hidden;
        end.edge = status.edge;
        end.side = com.termux.app.page.Side.of(page.isHome());
        end.lookId = lookIdOf(page);
        end.outlineKey = outlineKey;
        fillTopStripState(end);
    }

    /** The chips and the strip behind the system bar as they stand; one view of each for both ends. */
    private void fillTopStripState(@NonNull com.termux.app.statusbar.TopStackScene.End end) {
        View chips = findViewById(R.id.terminal_status_place_content);
        end.chipsShown = chips != null && chips.getVisibility() == View.VISIBLE;
        View strip = findViewById(R.id.terminal_status_bar_background);
        end.stripShown = strip != null && strip.getVisibility() == View.VISIBLE;
        end.stripDressedForBar =
            mStatusStripLead == com.termux.app.chrome.ChromeEdgeRule.TopLead.WINDOW_BAR;
    }

    /**
     * The top stack at rest on {@code front}'s side: the chips a wall to the right on Home, in
     * place on the Terminal. Where the rest may have moved: the wall moved or was laid out, the
     * place bar was synced, a crossing landed. Does not end a crossing.
     */
    private void restTopStack(@NonNull com.termux.app.page.PageKind front) {
        if (mCrossing.crossing()) return;
        com.termux.app.statusbar.TopStackScene.End end = mTopEndRest;
        end.side = com.termux.app.page.Side.of(front == com.termux.app.page.PageKind.HOME);
        end.edge = mStatusBar.statusBarEdge();
        fillTopStripState(end);
        mTopStackRenderer.setWidth(
            mPaneWallController == null ? 0 : mPaneWallController.wall().getWidth());
        mTopStackRenderer.rest(end);
    }

    private boolean mTopFadeActive;
    @Nullable private com.termux.app.wall.PageRef mTopFadeHerePage;
    @Nullable private Drawable mTopFadeStripHere;
    @Nullable private Drawable mTopFadeBarHere;
    private boolean mTopFadeBuilt;

    /** A crossing between Home and the Terminal begins: the band and the bar keep their glass. */
    private void beginTopBandFade(@NonNull com.termux.app.wall.PageRef here,
                                  @NonNull com.termux.app.wall.PageRef there) {
        endTopBandFade();
        if (here.isHome() == there.isHome()) return;
        mTopFadeActive = true;
        mTopFadeHerePage = here;
        View strip = findViewById(R.id.terminal_status_bar_glass_surface);
        mTopFadeStripHere = strip != null && strip.isShown() ? strip.getBackground() : null;
        View bar = findViewById(R.id.terminal_window_bar_background);
        mTopFadeBarHere = bar != null ? bar.getBackground() : null;
        // One look on every page (ADR 0031): no arriving end is built here; the first re-dress
        // on the way builds it (topFadeTakesRedress).
    }

    /** Builds both crossfades, the arriving end as the band is dressed now, once per crossing. */
    private void buildTopBandFadeEnds(@NonNull View host) {
        mTopFadeBuilt = true;
        View strip = findViewById(R.id.terminal_status_bar_glass_surface);
        if (strip != null) {
            strip.setBackground(new com.termux.app.chrome.CrossfadeDrawable(mTopFadeStripHere,
                buildStatusInsetStripSurface(host), mTopStackRenderer.glassShare()));
        }
        View bar = findViewById(R.id.terminal_window_bar_background);
        if (bar != null) {
            bar.setBackground(new com.termux.app.chrome.CrossfadeDrawable(mTopFadeBarHere,
                buildTerminalWindowBarBackground(host), mTopStackRenderer.glassShare()));
        }
        // The top stack's writer puts the blend's share (and the band's presence) on them.
        mTopStackRenderer.requestApply();
    }

    /**
     * Whether a re-dress of the band or the bar is the fade's to answer: mid-crossing it is. The
     * first one builds both in the dress worn now beside the ones they began with; every later one
     * changes nothing.
     */
    private boolean topFadeTakesRedress() {
        if (!mTopFadeActive) return false;
        if (!mCrossing.crossing()) {
            endTopBandFade();
            return false;
        }
        if (mTopFadeBuilt) return true;
        View host = findViewById(R.id.terminal_window_bar_host);
        if (host == null || mChrome == null) return false;
        buildTopBandFadeEnds(host);
        return true;
    }

    /** The crossing is over: each blend gives way to the dress it reached, nothing rebuilt. */
    private void endTopBandFade() {
        if (mTopFadeBuilt) {
            View strip = findViewById(R.id.terminal_status_bar_glass_surface);
            settleCrossfade(strip);
            if (strip != null && strip.getAlpha() != 1f) {
                // Faded out on a cancel toward a half that shows no band: it goes as it was; the
                // landing's pass hides it, as that half wears it.
                if (strip.getAlpha() == 0f && mTopFadeStripHere == null)
                    strip.setVisibility(View.GONE);
                strip.setAlpha(1f);
            }
            settleCrossfade(findViewById(R.id.terminal_window_bar_background));
        }
        mTopFadeActive = false;
        mTopFadeHerePage = null;
        mTopFadeStripHere = null;
        mTopFadeBarHere = null;
        mTopFadeBuilt = false;
    }

    private static void settleCrossfade(@Nullable View view) {
        Drawable background = view == null ? null : view.getBackground();
        if (background instanceof com.termux.app.chrome.CrossfadeDrawable)
            view.setBackground(((com.termux.app.chrome.CrossfadeDrawable) background).endpoint());
    }

    /**
     * The docked keyboard's glass as {@link #buildInAppKeyboardSurfaceBackground} builds it, with
     * the band it is drawn as given by the caller (the keyboard notes its own, the strip only
     * repeats it). One place, so the strip under the pill cannot disagree with the keyboard about
     * a single value of its material.
     */
    @NonNull
    private com.termux.app.chrome.GlassStack.Spec inAppKeyboardGlassSpec(@NonNull ChromeSpec state,
            boolean capsule, float cornerRadiusPx,
            @Nullable com.termux.app.chrome.GlassBackdropCache.Band band) {
        // While the keyboard's opacity still follows Global it renders the shared material, so its
        // own background colour and opacity are ignored here exactly as in the unified path. An
        // overlaying keyboard ignores them for the other reason (D3): it is opaque, and both say
        // how much of the wallpaper shows through.
        boolean normalized = isInAppKeyboardOpacityLinked()
            || !KeyboardMaterialPolicy.opacityApplies(inAppKeyboardForm(), inAppKeyboardOverlays(),
                inAppKeyboardOnHome(), inAppKeyboardOnDisplay());
        Integer schemeBackground = normalized ? null : resolveInAppKeyboardSchemeBackgroundColor();
        int blurRadiusDp = getEffectiveInAppKeyboardBlurRadius();
        // Docked, the keyboard is a slice of the frame: only the edge the model says faces the
        // opening wears a rim, and the rest (its joins, the screen's edges and the strip under
        // the pill it continues into) are seams. A card keeps its rim all round.
        boolean floating = isKeyboardFloating();
        int modelRim = capsule ? com.termux.app.chrome.ChromeEdgeRule.ALL
            : chromeRimEdges(KEYBOARD_PIECES);
        return com.termux.app.chrome.GlassStack.keyboard(
                mPreferences, stackLookPage(), state.barAlpha, capsule ? cornerRadiusPx : 0f, mFancierGlassLook)
            .withBlur(blurRadiusDp)
            // The same tint GlassStack read from v1's slot, unless Terl's Keyboard look is worn.
            .withTintAlpha(inAppKeyboardGlassAlpha(state))
            // A card is a card: its fill and rim are never faded out by the stack alpha a
            // detached Keyboard Opacity may hold. That alpha belongs to a slice of the frame.
            .withStackAlpha(capsule && !floating ? 100
                : getInAppKeyboardBackdropOpacityPercent())
            .withRim(capsule ? !floating : modelRim != com.termux.app.chrome.ChromeEdgeRule.NONE)
            .withSeams(capsule ? com.termux.app.chrome.ChromeEdgeRule.NONE
                : com.termux.app.chrome.ChromeEdgeRule.ALL & ~modelRim)
            .withTintColor(schemeBackground == null ? null : withAlphaComponent(schemeBackground,
                Math.round(255f * getInAppKeyboardBackgroundOpacityPercent() / 100f)))
            .withBand(band)
            // The page's ground over the frame, as the bars and the dock draw it (#283).
            .withGround(true);
    }

    /**
     * The opacity the keyboard's glass is built at.
     *
     * <p>Its own once it has one, the dock's while it still follows Global. Built at, not scaled to:
     * fading the finished drawable fades every layer of the light model including the grain, so
     * raising the keyboard's opacity brightened the speckle instead of thickening the background.
     */
    private float inAppKeyboardGlassAlpha(@NonNull ChromeSpec state) {
        if (isInAppKeyboardOpacityLinked())
            return state.barAlpha;
        return getInAppKeyboardBackgroundOpacityPercent() / 100f;
    }

    private int resolveInAppKeyboardBackgroundColor() {
        if (mAttachedInAppKeyboardView instanceof Keyboard2View)
            return ((Keyboard2View) mAttachedInAppKeyboardView).getKeyboardBackgroundColor();
        return MaterialColors.getColor(this,
            com.google.android.material.R.attr.colorSurface,
            ContextCompat.getColor(this, R.color.termux_surface_base));
    }

    /**
     * Keyboard-background color assigned in the color scheme editor, or null for the theme's own
     * surface. Memoized on the raw pref JSON — dynamic slots re-resolve against Material roles,
     * which only move with a configuration change that recreates this activity anyway.
     */
    @Nullable
    private Integer resolveInAppKeyboardSchemeBackgroundColor() {
        if (mPreferences == null)
            return null;
        String json = mPreferences.getInAppKeyboardColorScheme();
        if (!json.equals(mInAppKeyboardSchemeBackgroundJson)) {
            mInAppKeyboardSchemeBackgroundJson = json;
            mInAppKeyboardSchemeBackgroundColor =
                com.termux.app.terminal.inappkeyboard.InAppKeyboardColorScheme
                    .fromJson(this, json).resolvedKeyboardBackground();
        }
        return mInAppKeyboardSchemeBackgroundColor;
    }

    /** The Settings knob for the air under the last key row, in pixels. */
    private int resolveInAppKeyboardBottomPaddingPx() {
        if (mPreferences == null)
            return 0;
        return Math.round(dpToPx(mPreferences.getInAppKeyboardBottomPadding()));
    }

    private int getInAppKeyboardBackgroundOpacityPercent() {
        return mPreferences != null
            ? terlKeyboardLook().opacityPercent(
                mPreferences.getInAppKeyboardBackgroundOpacity(stackLookPage()))
            : TermuxPreferenceConstants.TERMUX_APP.DEFAULT_IN_APP_KEYBOARD_BACKGROUND_OPACITY;
    }

    /**
     * The keyboard's own film-grain strength — the KEYBOARD slot's grain, which follows Global until
     * detached, so an untouched keyboard grains like the dock.
     */
    private int getInAppKeyboardTintStrengthPercent() {
        return mPreferences != null
            ? mPreferences.getInAppKeyboardTintStrength(stackLookPage())
            : TermuxPreferenceConstants.TERMUX_APP.DEFAULT_SURFACE_GLOBAL_TINT;
    }

    private int getInAppKeyboardGrainPercent() {
        return mPreferences != null
            ? mPreferences.getInAppKeyboardGrain(stackLookPage())
            : TermuxPreferenceConstants.TERMUX_APP.DEFAULT_VALUE_DOCK_GLASS_GRAIN;
    }

    /**
     * The alpha (percent) of the keyboard's whole backdrop stack — the blurred wallpaper crop and
     * the tint together, applied as one alpha over the finished drawable so lowering it reveals the
     * plain wallpaper rather than cross-fading any one layer. 100 (the effective default) renders
     * exactly as every keyboard has until now; distinct from
     * {@link #getInAppKeyboardBackgroundOpacityPercent()}, which is the tint's own colour intensity.
     */
    private int getInAppKeyboardBackdropOpacityPercent() {
        return mPreferences != null
            ? terlKeyboardLook().stackAlphaPercent(
                com.termux.app.chrome.GlassStack.keyboardStackAlphaPercent(mPreferences, stackLookPage()))
            : TermuxPreferenceConstants.TERMUX_APP.MAX_IN_APP_KEYBOARD_BACKDROP_OPACITY;
    }

    /** Whether the keyboard on screen is the split one: the docked keyboard with its keys parted. */
    private boolean isInAppKeyboardSplit() {
        return mInAppKeyboard != null
            && mInAppKeyboard.getForm() == PlaceLayout.KeyboardForm.SPLIT;
    }

    /**
     * True when the scheme's background color or the opacity slider repaints the surface.
     *
     * <p>"Match all surfaces" outranks both. An edited keyboard scheme sets a background swatch,
     * which used to drop the keyboard onto its own local surface painted in that colour — a
     * surface no dock/status opacity write reaches, so the keyboard sat visibly lighter than
     * every other surface until the keyboard section was reset. While surfaces are normalized the
     * keyboard renders the shared material and the scheme keeps only its key colours.</p>
     */
    private boolean hasInAppKeyboardBackgroundOverride() {
        return ChromePolicy.hasInAppKeyboardBackgroundOverride(isInAppKeyboardOpacityLinked(),
            resolveInAppKeyboardSchemeBackgroundColor(),
            getInAppKeyboardBackgroundOpacityPercent(),
            mPreferences != null ? mPreferences.getAppBarOpacity(stackLookPage())
                : TermuxPreferenceConstants.TERMUX_APP.DEFAULT_VALUE_APP_BAR_OPACITY);
    }


    /** The keyboard always renders on the same glass material path as the dock. */
    private boolean isInAppKeyboardGlassSurface() {
        return true;
    }

    /** True when the keyboard renders as the floating Rounded surface. */
    private boolean isInAppKeyboardCapsule() {
        // The shape model says what the keyboard is: a card of its own with its own corners
        // (Floating, or a floating keyboard under either Style, or a split half), or a slice of
        // the Docked frame whose only round corners are the screen's. A floating keyboard is a
        // card wherever it is parked: a square slab in the middle of the place reads as a
        // rendering fault. With no keyboard piece in the shape yet, the Style and the form say it.
        com.termux.app.place.ChromeShape shape = chromeShape();
        com.termux.app.place.ChromeShape.Piece piece =
            shape.piece(com.termux.app.place.ChromeShape.PieceId.KEYBOARD);
        if (piece == null) piece = shape.piece(com.termux.app.place.ChromeShape.PieceId.KEYBOARD_LEFT);
        com.termux.app.place.ChromeShape.Card card = piece == null ? null : shape.cardOf(piece);
        if (card == null) return arrangement().floating() || isKeyboardFloating();
        return !card.docked();
    }

    /** True while the keyboard is hosted in its floating frame rather than in the dock. */
    private boolean isKeyboardFloating() {
        return mFloatingKeyboard != null && mFloatingKeyboard.isFloating();
    }

    /**
     * Whether the keyboard wears the kept navigation band as its own foot: it is laid out in the
     * stack's column as a Docked slice (shown, or down and still laid out), no bands stand under
     * it and the system keyboard is away. It does not flip when the keyboard toggles up or down at
     * rest, so the toggle resizes nothing new. The one question the dress phase and the stack
     * pass both ask ({@link BottomInsets#keyboardFootPx(int, boolean)}).
     */
    private boolean inAppKeyboardFootApplies(boolean capsule) {
        View keyboardContainer = findViewById(R.id.inapp_keyboard_container);
        boolean laidOut = keyboardContainer != null
            && keyboardContainer.getVisibility() != View.GONE
            && (isInAppKeyboardShown() || keyboardStaysLaidOut());
        return BottomInsets.keyboardWearsFoot(capsule, isKeyboardFloating(), isImeVisible(),
            underKeyboardBandsShown(), laidOut);
    }

    /** The foot the keyboard's host was last dressed with; what the shape model reads. */
    private int mDressedKeyboardFootPx;

    /** The keyboard's foot now: the kept band while it wears it, else 0. */
    private int inAppKeyboardFootPx() {
        return BottomInsets.keyboardFootPx(mBottomKeptPx,
            inAppKeyboardFootApplies(isInAppKeyboardCapsule()));
    }

    /** The keys of a laid-out keyboard height: the foot is the keyboard's own, not the stack's. */
    private int inAppKeyboardKeysPx(int laidOutPx) {
        return BottomInsets.keyboardKeysPx(laidOutPx, inAppKeyboardFootPx());
    }

    /**
     * Dresses the keyboard's host in the margins and padding of the shape it wears: a docked
     * card's side gap, top gap and inner rim, a floating card's thin side rim, and the user's chin.
     * They are part of the keyboard's height, so the geometry choreographer runs this before every
     * measure ({@link KeyboardGeometryChoreographer.Surface#dressKeyboardHost}); a form or Style
     * that changed since the last render is therefore measured as it will be laid out. Compares
     * before setting, so a host already dressed costs nothing and asks for no layout.
     *
     * @return whether anything changed
     */
    private boolean dressInAppKeyboardHost() {
        View surfaceHost = findViewById(R.id.inapp_keyboard_view_host);
        if (surfaceHost == null) {
            return false;
        }
        boolean capsule = isInAppKeyboardCapsule();
        boolean floating = isKeyboardFloating();
        // The side gap keeps a docked capsule off the screen's edges; inside a floating card it was
        // only more rim round the keys.
        float density = getResources().getDisplayMetrics().density;
        int horizontalMargin = ChromePolicy.keyboardHostSideMarginPx(floating,
            inAppKeyboardMarginDp(), capsule, density);
        // A floating keyboard already sits under its card's grab handle, so the capsule's top gap
        // would only push the keys further from it: the host runs straight up to the handle row
        // and keeps a thin inner rim of the one surface the card and the host share.
        int topMargin = ChromePolicy.keyboardHostTopMarginPx(capsule, floating, density);
        // A floating card keeps a thin 3dp rim at the sides and none above and below: its handle row
        // and the keyboard's own margins are rim enough.
        int innerPadding = floating ? Math.round(dpToPx(3)) : capsule ? Math.round(dpToPx(6)) : 0;
        int innerTopPadding = floating ? 0 : innerPadding;
        // The user's own chin allowance, from Settings, and it lands in a different place per shape:
        // padding inside the docked slab, a taller gap under the floating capsule. In the stack the
        // capsule's gap is not this host's to carry: the stack's own bottom margin is the one edge
        // gap the dock and the keyboard share (ChromePolicy.bottomEdgeGapPx), so the keyboard
        // coming or going never moves the dock's landing. A keyboard floating in its own frame
        // still keeps the card's gap under its keys.
        int chinPaddingPx = resolveInAppKeyboardBottomPaddingPx();
        int bottomMargin = ChromePolicy.keyboardChinBottomMarginPx(
            capsule, 0, chinPaddingPx);
        // The kept navigation band under a Docked keyboard is its own: its material reaches the
        // screen's bottom, and the keys stand where they did (BottomInsets#keyboardFootPx, the
        // same band the stack pass counts).
        int keyboardFootPx = BottomInsets.keyboardFootPx(mBottomKeptPx,
            inAppKeyboardFootApplies(capsule));
        // The shape model (which this pass must not ask) reads the foot the host wears.
        mDressedKeyboardFootPx = floating ? 0 : keyboardFootPx;
        int innerBottomPadding = floating ? 0 : ChromePolicy.keyboardChinBottomPaddingPx(
            capsule, innerPadding, chinPaddingPx) + keyboardFootPx;
        boolean changed = false;
        ViewGroup.LayoutParams layoutParams = surfaceHost.getLayoutParams();
        if (layoutParams instanceof ViewGroup.MarginLayoutParams) {
            ViewGroup.MarginLayoutParams params = (ViewGroup.MarginLayoutParams) layoutParams;
            if (params.leftMargin != horizontalMargin || params.rightMargin != horizontalMargin
                || params.topMargin != topMargin || params.bottomMargin != bottomMargin) {
                params.leftMargin = horizontalMargin;
                params.rightMargin = horizontalMargin;
                params.topMargin = topMargin;
                params.bottomMargin = bottomMargin;
                surfaceHost.setLayoutParams(params);
                changed = true;
            }
        }
        if (surfaceHost.getPaddingLeft() != innerPadding
            || surfaceHost.getPaddingTop() != innerTopPadding
            || surfaceHost.getPaddingRight() != innerPadding
            || surfaceHost.getPaddingBottom() != innerBottomPadding) {
            surfaceHost.setPadding(innerPadding, innerTopPadding, innerPadding, innerBottomPadding);
            changed = true;
        }
        if (changed) {
            mKeyboardGeometry.markHeightDirty();
            // The host moved inside the stack, so its wallpaper crop is cut again.
            mChrome.requestSync(ChromeRenderer.SCOPE_KEYBOARD_BACKDROP);
        }
        return changed;
    }

    /**
     * Applies the in-app keyboard's material and clip: the rounded clip when the host is a card,
     * and the dock's blurred-wallpaper + tinted-glass stack (or the overlay panel) behind the keys.
     * The host's margins and padding are not this pass's: the spec this paints was built by a
     * measure that already dressed the host ({@link #dressInAppKeyboardHost}). The glass stack is
     * rendered as the host's background drawable (a pre-blurred wallpaper crop under the same
     * tint, built by {@link com.termux.app.chrome.GlassStack}) so the wrap-content keyboard
     * measurement is never affected by extra sibling views.
     */
    /** Whether this surface pass asked the keyboard band about its glass. */
    private boolean mKeyboardBandAskedThisPass;

    /**
     * True while the Look editor's Frost, Opacity or Tint thumb is down and its ticks are in
     * flight ({@code SurfaceEditorController.Host#setGlassDragPreview}). Each tick then dresses
     * the layers already up (their tint, opacity and grain) and nothing a tick cannot afford: no
     * backdrop re-cut or refraction rebuild, no keyboard face sampling or palette, no full window
     * bar refresh. The release clears it and asks for the full pass, which settles all of that once.
     */
    private boolean mGlassDragPreview;

    /**
     * Whether the crossing under way has judged the keyboard's legends (KeyboardFaceJudging): on
     * its first frame that measured the keyboard's band, and again when a layout moves the band.
     * Cleared by any apply at rest, the landing's included.
     */
    private boolean mKeyboardFacesJudgedThisCrossing;

    /** This crossing pushed the arriving page's stored legends ({@link #pushStoredKeyboardGlassFaces}). */
    private boolean mKeyboardFacesStoredThisCrossing;

    /** The keyboard band's laid-out rect as this pass measured it ({@link #measureInAppKeyboardBand}). */
    private final Rect mKeyboardBandRect = new Rect();

    /** {@link #mKeyboardBandRect} when the keyboard's legends were last judged. */
    private final Rect mKeyboardFacesJudgedRect = new Rect();

    /**
     * The keyboard host's material for {@code state}, then the keys' legends re-chosen against the
     * faces that material draws, row by row (ChromeInk#bandFaces): measured where the host wears
     * the keyboard band's glass this pass, the theme's glass base where it does not (Solid, the
     * joined frame, a floating card, the keyboard down).
     */
    // DIAG(stack-look): the stack's look as each pass applies it, logged on change; revert before merge.
    @Nullable private String mDiagStackLook;

    private void diagStackLook(@NonNull ChromeSpec state) {
        if (!MotionLog.enabled || mPreferences == null) return;
        int page = stackLookPage();
        String look = "page=" + page + " barAlpha=" + state.barAlpha + " dockBlur="
            + getEffectiveExtraKeysBlurRadius() + " kbOpacity=" + getInAppKeyboardBackgroundOpacityPercent()
            + " kbTint=" + getInAppKeyboardTintStrengthPercent() + " kbGrain=" + getInAppKeyboardGrainPercent()
            + " kbBlur=" + mPreferences.getInAppKeyboardBlurRadius(page)
            + " kbBackdrop=" + getInAppKeyboardBackdropOpacityPercent()
            + " unified=" + shouldUseUnifiedDefaultKeyboardGlassSurface(state)
            + " travel=" + mKeyboardTravelSolidness + " kbShown=" + state.keyboardShown
            + " crossing=" + mCrossing.crossing();
        if (look.equals(mDiagStackLook)) return;
        mDiagStackLook = look;
        MotionLog.log("stack-look", look);
    }

    private void applyInAppKeyboardSurfaceState(@NonNull ChromeSpec state) {
        diagStackLook(state);
        mKeyboardBandAskedThisPass = false;
        Trace.beginSection("Chrome.kb.host");
        applyInAppKeyboardHostMaterial(state);
        Trace.endSection();
        TermuxInAppKeyboard keyboard = mInAppKeyboard;
        if (keyboard == null || mChrome == null) return;
        // Mid-drag the legends keep the inks they have: re-chosen per tick, every one re-sampled
        // the band's rows and rebuilt the palette. The release's full pass chooses them once.
        // A crossing judges them once, on its first frame that measured the band, and again only
        // when a layout moves the band (its first frame can stand on the page it left), so a
        // keyboard it brings up rises in the inks it lands in; the landing's apply re-judges at
        // rest (KeyboardFaceJudging).
        boolean crossing = mCrossing.crossing();
        if (!crossing) {
            mKeyboardFacesJudgedThisCrossing = false;
            mKeyboardFacesStoredThisCrossing = false;
        }
        // A crossing measures nothing (ADR 0029 section 9): the legends of the page it arrives on
        // are the ones rest kept for it. A page with none yet is judged as before, counted by the
        // store's guard, until the landing keeps its own.
        if (crossing) {
            // No judging here: a look-only crossing drifts the legends between the two kept
            // palettes (beginLegendBlend); any other crossing takes the arriving page's once.
            if (!mGlassDragPreview && !mKeyboardBlendOn) pushStoredKeyboardGlassFaces(keyboard);
            return;
        }
        boolean bandMoved = mKeyboardBandAskedThisPass
            && !mKeyboardBandRect.equals(mKeyboardFacesJudgedRect);
        if (!com.termux.app.terminal.inappkeyboard.KeyboardFaceJudging.due(mGlassDragPreview,
            crossing, mKeyboardFacesJudgedThisCrossing, bandMoved)) return;
        if (!mKeyboardBandAskedThisPass) {
            if (com.termux.app.terminal.inappkeyboard.KeyboardFaceJudging.clearsWithoutBand(crossing))
                keyboard.setGlassFaces(new int[0]);
            return;
        }
        pushKeyboardGlassFaces(keyboard);
        if (crossing) mKeyboardFacesJudgedThisCrossing = true;
    }

    /** The keyboard band's faces and the legend tone chosen on its bare face, to the keyboard. */
    private void pushKeyboardGlassFaces(@NonNull TermuxInAppKeyboard keyboard) {
        Trace.beginSection("Chrome.kb.faces");
        try {
            com.termux.app.chrome.ChromeInk ink = mChrome.ink();
            int[] faces = ink.bandFaces(com.termux.app.chrome.GlassBackdropCache.Band.KEYBOARD);
            int tone = ink.bandTone(com.termux.app.chrome.GlassBackdropCache.Band.KEYBOARD);
            keyboard.setGlassFaces(faces, tone);
            mKeyboardFacesJudgedRect.set(mKeyboardBandRect);
            recordKeyboardLegibility(faces, tone);
        } finally {
            Trace.endSection();
        }
    }

    /**
     * Keeps the keyboard's faces and legend tone as judged at this page's rest, for a crossing that
     * arrives here. Nothing is built when they are what the store already holds; never in a crossing.
     */
    private void recordKeyboardLegibility(@NonNull int[] faces, int tone) {
        syncLegibilityCrossing();
        com.termux.app.glass.LegibilityStore store = mGlass.legibility();
        if (store.crossing() || faces.length == 0) return;
        Rect rest = mKeyboardBandRect;
        com.termux.app.wall.PageRef page = endpointPageOf(mLastWallPage);
        long key = legibilityKey(page);
        int look = dockLegibilityLook(page);
        com.termux.app.glass.LegibilityCorrection held = store.get(key,
            com.termux.app.glass.LegibilityBand.KEYBOARD, rest.left, rest.top, rest.right,
            rest.bottom, look);
        if (held == null || !held.matches(faces, tone)) {
            store.record(key, com.termux.app.glass.LegibilityBand.KEYBOARD, rest.left, rest.top,
                rest.right, rest.bottom, look,
                com.termux.app.glass.LegibilityCorrection.ofRows(faces, tone));
        }
        if (mPreferences == null) return;
        // The legends every other page would settle on, worked out here at rest from that page's
        // glass, so a crossing blends two kept palettes and judges nothing.
        for (com.termux.app.page.PageKind kind : LEGIBILITY_KINDS) {
            if (kind == page.kind) continue;
            com.termux.app.wall.PageRef other = endpointPageOf(kind);
            int otherLook = dockLegibilityLook(other);
            if (!store.needsMeasure(legibilityKey(other),
                    com.termux.app.glass.LegibilityBand.KEYBOARD, rest.left, rest.top, rest.right,
                    rest.bottom, otherLook)) continue;
            int lookId = lookIdOf(other);
            int[] rows = new int[com.termux.app.chrome.ChromeInk.FACE_ROWS];
            float otherOpacity = mPreferences.getAppBarOpacity(lookId) / 100f;
            int otherTint = mChrome.glass().tintBase(mPreferences.getDockTintStrength(lookId));
            // The keyboard's glass shows the page's ground (#283): the arriving page's faces are
            // measured over its own, so the legends blend to what the landing measures there.
            int otherTone = com.termux.app.chrome.GlassGround.ON
                ? mChrome.ink().probeEitherToneUnderGlass(
                    com.termux.app.chrome.GlassBackdropCache.Band.KEYBOARD, otherOpacity, otherTint,
                    rows, groundOfWallPage(kind))
                : mChrome.ink().probeEitherToneUnderGlass(
                    com.termux.app.chrome.GlassBackdropCache.Band.KEYBOARD, otherOpacity, otherTint,
                    rows);
            if (otherTone == 0) continue;
            store.record(legibilityKey(other), com.termux.app.glass.LegibilityBand.KEYBOARD,
                rest.left, rest.top, rest.right, rest.bottom, otherLook,
                com.termux.app.glass.LegibilityCorrection.ofRows(rows, otherTone));
        }
    }

    /**
     * The keyboard's faces and legend tone for the page a crossing arrives on, as rest kept them,
     * pushed once per crossing; false (and nothing pushed) when no correction is kept for it or the
     * crossing already pushed one.
     */
    private boolean pushStoredKeyboardGlassFaces(@NonNull TermuxInAppKeyboard keyboard) {
        if (mKeyboardFacesStoredThisCrossing) return true;
        com.termux.app.page.PageKind other = mCrossing.seam().other();
        if (other == null) return false;
        com.termux.app.glass.LegibilityCorrection kept = mGlass.legibility().peek(
            legibilityKey(endpointPageOf(other)), com.termux.app.glass.LegibilityBand.KEYBOARD);
        if (kept == null) return false;
        int[] faces = new int[kept.rows()];
        for (int row = 0; row < faces.length; row++) faces[row] = kept.face(row);
        keyboard.setGlassFaces(faces, kept.tone());
        mKeyboardFacesJudgedThisCrossing = true;
        mKeyboardFacesStoredThisCrossing = true;
        return true;
    }

    /**
     * The keyboard's own blurred frame has landed after its rows were read off a stand-in (a Glass
     * edit, a held drag's release): the faces are measured again on it and the legends re-chosen,
     * the keyboard repainting only if an ink moved ({@link TermuxInAppKeyboard#setGlassFaces}).
     * Only where the last pass measured the keyboard's band; the editor's live preview is this
     * same keyboard. The veil, if it moves with them, asks for its own apply.
     */
    private void rejudgeKeyboardGlassFaces() {
        TermuxInAppKeyboard keyboard = mInAppKeyboard;
        if (keyboard == null || mChrome == null || !mKeyboardBandAskedThisPass) return;
        boolean crossing = mCrossing.crossing();
        if (!crossing) mKeyboardFacesJudgedThisCrossing = false;
        // Mid-crossing too: the ink names each stand-in reading once, so this is one judgment.
        if (!com.termux.app.terminal.inappkeyboard.KeyboardFaceJudging.rejudgeDue(
            mGlassDragPreview)) return;
        pushKeyboardGlassFaces(keyboard);
        if (crossing) mKeyboardFacesJudgedThisCrossing = true;
    }

    private void applyInAppKeyboardHostMaterial(@NonNull ChromeSpec state) {
        // The frost under the bed is up only while this pass dresses the host as the Display
        // page's glass; every other pass (keyboard down, another page, floating, mid-blend) takes
        // it away, so it can never outlive the material it belongs to.
        com.termux.app.wall.PageRef arriving = keyboardArrivalOf(state.keyboardShown);
        boolean frosts = arriving != null ? dressArrivingKeyboardHost(arriving)
            : dressInAppKeyboardHost(state);
        if (!frosts) releaseKeyboardFrost();
    }

    /**
     * The page a crossing arrives at when, under Floating, the keyboard host is dressed as that
     * page's rest shows it (KeyboardMaterialPolicy#dressedShown), so the keyboard rises in the
     * arriving rest's own card rather than bare until the landing makes it visible. Null on every
     * other pass, which dresses the host from its own state.
     */
    @Nullable
    private com.termux.app.wall.PageRef keyboardArrivalOf(boolean liveShown) {
        if (liveShown || !mCrossing.crossing()) return null;
        com.termux.app.page.PageKind other = mCrossing.seam().other();
        if (other == null) return null;
        boolean arrives = chromeRestOf(other).keyboardReveal() > 0f;
        if (!KeyboardMaterialPolicy.dressedShown(false, arrives,
            arrangementOf(com.termux.app.wall.PageRef.TERMINAL).floating())) return null;
        return endpointPageOf(other);
    }

    /**
     * The keyboard host dressed as {@code arriving}'s rest shows it: the one dress ladder
     * ({@link #dressInAppKeyboardHost}) run with the keyboard shown under that page's look
     * ({@link #mLookIdOverride}), so it builds what the rest's own pass builds, held under the
     * same key, and that pass finds it and changes nothing. Built once as the crossing begins
     * ({@link #beginKeyboardLookBlend}); a pass on the way finds the same held glass, and the look
     * blend crossing to it is put back up. True when the bed frosts the display.
     */
    private boolean dressArrivingKeyboardHost(@NonNull com.termux.app.wall.PageRef arriving) {
        boolean frosts;
        mLookIdOverride = lookIdOf(arriving);
        try {
            ChromeSpec state = buildChromeSpec();
            frosts = dressInAppKeyboardHost(new ChromeSpec(state.toolbarShown, true,
                mKeyboardGeometry.measureHeightPx(), state.blurEnabled, state.appsRowEnabled,
                state.azRowEnabled, state.extraKeysRowEnabled, state.barAlpha,
                state.blurRadiusDp));
        } finally {
            mLookIdOverride = com.termux.app.place.TopBandFadePlan.NONE;
        }
        com.termux.app.chrome.CrossfadeDrawable blend = mKeyboardLookBlend;
        View surfaceHost = findViewById(R.id.inapp_keyboard_view_host);
        if (blend != null && mKeyboardLookBlendArrives && surfaceHost != null
            && mKeyboardHostInner != null && mKeyboardHostInner == blend.there())
            setKeyboardHostBackground(surfaceHost, blend);
        return frosts;
    }

    /** {@link #applyInAppKeyboardHostMaterial}'s dressing; true when the bed frosts the display. */
    private boolean dressInAppKeyboardHost(@NonNull ChromeSpec state) {
        View surfaceHost = findViewById(R.id.inapp_keyboard_view_host);
        if (surfaceHost == null) {
            return false;
        }
        if (!state.keyboardShown) {
            setKeyboardHostBackground(surfaceHost, null);
            clearInAppKeyboardBackdrop();
            return false;
        }

        boolean capsule = isInAppKeyboardCapsule();
        // Remembered, so a Style change that reaches the surfaces without a chrome render redresses
        // the host at once instead of leaving the other Style's material on it.
        mKeyboardSurfaceDressedAsCard = capsule;
        // A card's radius is the model's for the keyboard's piece (Corners, held to its size).
        com.termux.app.chrome.LiveChromeShape.Clip keyboardClip = capsule ? chromeClipOf(
            KEYBOARD_PIECES) : null;
        float cornerRadiusPx = !capsule ? 0f : keyboardClip != null ? keyboardClip.radius
            : mDock.resolveDockCapsuleCornerRadiusPx(Integer.MAX_VALUE);
        applyInAppKeyboardSurfaceClip(surfaceHost, capsule, cornerRadiusPx);
        // A floating keyboard paints nothing here: its card is already one solid panel in the
        // same surface role, and a glass slice inside it would draw a second material over the
        // first. A split keyboard is painted as the docked one is; only its keys part.
        PlaceLayout.KeyboardForm form = inAppKeyboardForm();
        boolean overlays = inAppKeyboardOverlays();
        boolean home = inAppKeyboardOnHome();
        boolean display = inAppKeyboardOnDisplay();
        KeyboardMaterialPolicy.Material material =
            KeyboardMaterialPolicy.hostMaterial(form, overlays, home, display);
        if (material == KeyboardMaterialPolicy.Material.NONE) {
            setKeyboardHostBackground(surfaceHost, null);
            clearInAppKeyboardBackdrop();
            return false;
        }
        // Mid-slide between a place that paints the keyboard as glass and one that paints it as
        // the panel, the host wears both and the panel's alpha follows the wall; at rest the two
        // ends of that blend are exactly the materials painted below, so the settle repaints
        // nothing the eye can see. See syncKeyboardMaterialTravel.
        if (mKeyboardTravelSolidness != KeyboardMaterialPolicy.NO_TRAVEL) {
            applyInAppKeyboardMaterialTravel(state, surfaceHost, capsule, cornerRadiusPx);
            return false;
        }
        mKeyboardTravelSolidFill = null;
        // Over a Display page in overlay mode the bed lies over the display and wears its
        // Display-pages look see-through, with no wallpaper frame: its Opacity and Tint over the
        // live display, and the Frost drawn by the compositor in a blur layer under the bed.
        // Neither the unified dock glass nor the joined frame's sheet stands in for it here: both
        // would lay the wallpaper over the display. Only while the display lies behind the whole
        // bed: with rows over the keyboard, whose room at rest is below the display, the bed's
        // lower strip lies over the wallpaper, and the bed wears the wallpaper glass below from
        // top to bottom, one material with the dock's rows (KeyboardMaterialPolicy).
        if (inAppKeyboardSeesThroughToDisplay()) {
            setKeyboardHostBackground(surfaceHost, buildInAppKeyboardSurfaceBackground(
                state, surfaceHost, capsule, cornerRadiusPx));
            clearInAppKeyboardBackdrop();
            com.termux.app.chrome.LiveChromeShape.Clip clip = mKeyboardBaseClip;
            frostKeyboardOverDisplay(surfaceHost, capsule ? cornerRadiusPx : clip == null ? 0f
                : com.termux.app.chrome.DisplayKeyboardBlurPolicy.cornerPx(clip.topLeft,
                    clip.topRight, clip.bottomRight, clip.bottomLeft));
            return true;
        }
        // A keyboard that overlays its place is one opaque panel in the overlay surface role: no
        // wallpaper frost, no glass slice, no rim, and the Keyboard surface's opacity and scheme
        // background colour are ignored, because both say how much of the wallpaper shows through
        // a material that is no longer there. The dock underneath keeps its glass. Home is the
        // exception: its keyboard lies over the wallpaper, not over text, and wears the glass below.
        if (material == KeyboardMaterialPolicy.Material.SOLID) {
            setKeyboardHostBackground(surfaceHost, buildInAppKeyboardSolidSurface(
                KeyboardMaterialPolicy.solidFillIsRounded(form, overlays, home, capsule)
                    ? cornerRadiusPx : 0f));
            clearInAppKeyboardBackdrop();
            return false;
        }
        // Under a joined Docked frame the frame's glass is the sheet behind the keys; the keys keep
        // their own glass.
        if (stackStandsDownOnFrame()) {
            setKeyboardHostBackground(surfaceHost, null);
            clearInAppKeyboardBackdrop();
            return false;
        }
        // Under the deck look the host is the slab, not glass (wave 8): the keys draw their own
        // opaque bed over it, and what they leave uncovered at the card's edge is the same
        // plastic rather than a glass rim showing through. No band is measured: the legends take
        // the deck's inks, not a tone judged on glass.
        Drawable slab = deckSlabOr(null);
        if (slab != null) {
            setKeyboardHostBackground(surfaceHost, slab);
            clearInAppKeyboardBackdrop();
            return false;
        }
        if (shouldUseUnifiedDefaultKeyboardGlassSurface(state)) {
            // Once accessory_surface_host has actually laid out at the expanded height — and, when
            // there is a frame to blur, its backdrop shows it — the transparent keyboard exposes
            // that one unified material. Until then, keep a keyboard-local glass background in
            // place: changing the RelativeLayout rules above only requests layout, so clearing
            // this background here would expose sharp wallpaper for a frame (or the whole IME
            // transition). It must come off the moment the shared surface is there, though: the
            // expanded surface already paints this glass under the keyboard, and a local coat left
            // on top is the same translucent material twice — a keyboard visibly darker than the
            // band above it. Both sample the one shared frame at the host's own position, so the
            // wallpaper under the keys is the same picture on either side of the handoff.
            if (isUnifiedAccessoryBackdropReady(state)) {
                // No glass of its own, but the keyboard band's veil: over the unified glass,
                // under the keys, on the host's bounds only, so the dock rows are never veiled.
                // The veil holds no frame, so the backdrop goes without letting the veil go.
                clearInAppKeyboardBackdropFrame();
                setKeyboardHostBackground(surfaceHost, buildInAppKeyboardVeilOnly(state, surfaceHost));
            } else {
                setKeyboardHostBackground(surfaceHost, buildInAppKeyboardSurfaceBackground(
                    state, surfaceHost, false, 0f, true));
            }
            return false;
        }
        setKeyboardHostBackground(surfaceHost, buildInAppKeyboardSurfaceBackground(
            state, surfaceHost, capsule, cornerRadiusPx, true));
        return false;
    }

    /** The frost under the keyboard on a Display page (the glass service's Compositor kind); made on first use. */
    @Nullable private com.termux.app.chrome.KeyboardFrost mKeyboardFrost;

    /**
     * Says where the keyboard's bed is over the display and what its Frost is; the glass service
     * grants the compositor's blur under it, or leaves the bed see-through
     * ({@link com.termux.app.chrome.KeyboardFrost}).
     */
    private void frostKeyboardOverDisplay(@NonNull View surfaceHost, float cornerPx) {
        if (mPreferences == null) return;
        if (mKeyboardFrost == null) {
            mKeyboardFrost = new com.termux.app.chrome.KeyboardFrost(this, mGlass);
        }
        mKeyboardFrost.show(surfaceHost, mDisplayKeys.displayView(),
            terlKeyboardLook().blurDp(mPreferences.getInAppKeyboardBlurRadius(stackLookPage())),
            getResources().getDisplayMetrics().density, cornerPx);
    }

    /** Takes the frost under the keyboard away and frees it; safe when there is none. */
    private void releaseKeyboardFrost() {
        if (mKeyboardFrost != null) mKeyboardFrost.release();
    }

    /**
     * The docked keyboard's host while the wall travels between glass and panel: the panel at the
     * travel's alpha over the glass. The glass is the unified dock surface where that is already
     * the material under the keys (leaving the terminal), and a keyboard-local coat of the same
     * glass otherwise (arriving at it), so the blend never stacks two coats. The fill is kept so
     * the frames that follow set its alpha and rebuild nothing.
     */
    private void applyInAppKeyboardMaterialTravel(@NonNull ChromeSpec state,
                                                  @NonNull View surfaceHost, boolean capsule,
                                                  float cornerRadiusPx) {
        GradientDrawable fill = buildInAppKeyboardSolidSurface(capsule ? cornerRadiusPx : 0f);
        fill.setAlpha(Math.round(255f * mKeyboardTravelSolidness));
        mKeyboardTravelSolidFill = fill;
        Drawable glass = isUnifiedAccessoryBackdropReady(state) || stackStandsDownOnFrame() ? null
            : buildInAppKeyboardSurfaceBackground(state, surfaceHost, capsule, cornerRadiusPx);
        Drawable material = glass == null ? fill
            : new LayerDrawable(new Drawable[] {glass, fill});
        setKeyboardHostBackground(surfaceHost, new LayoutNeutralDrawable(material));
    }

    /**
     * One frame of the keyboard's material travel (PlaceChromeTravel): with the keyboard up on
     * both places of a slide and the two painting it differently, the panel's alpha follows the
     * wall rather than swapping whole at settle. The first frame of a blend builds the host's
     * layers; every later frame writes one alpha. {@link #settlePlaceChrome} ends it, and the
     * place's own repaint then finds the material the blend already landed on.
     */
    private void syncKeyboardMaterialTravel(@NonNull com.termux.app.place.PlaceChromeTravel.Frame frame) {
        PlaceLayout layout = arrangement().layout();
        PlaceLayout.KeyboardForm form = inAppKeyboardForm();
        float solidness = KeyboardMaterialPolicy.travelSolidness(
            KeyboardMaterialPolicy.hostMaterial(form, KeyboardOverlayPolicy.overlays(frame.from,
                layout), frame.from == com.termux.app.page.PageKind.HOME,
                frame.from == com.termux.app.page.PageKind.DISPLAY),
            KeyboardMaterialPolicy.hostMaterial(form, KeyboardOverlayPolicy.overlays(frame.toward,
                layout), frame.toward == com.termux.app.page.PageKind.HOME,
                frame.toward == com.termux.app.page.PageKind.DISPLAY),
            chromeRestOf(frame.from).keyboardReveal() > 0f,
            chromeRestOf(frame.toward).keyboardReveal() > 0f, frame.chromeFraction);
        if (solidness == mKeyboardTravelSolidness) return;
        boolean wasTravelling = mKeyboardTravelSolidness != KeyboardMaterialPolicy.NO_TRAVEL;
        mKeyboardTravelSolidness = solidness;
        // The settle has a repaint owed either way: to take the blend's layers off, or to leave
        // the host in the material the blend landed on.
        mChromeTravelMoved = true;
        if (solidness == KeyboardMaterialPolicy.NO_TRAVEL) {
            // The frame moved on to a pair of places that paint alike (past an outer page): the
            // host goes back to the committed material now rather than at settle.
            if (wasTravelling) mChrome.requestSync(ChromeRenderer.SCOPE_APPLY_THIS_FRAME);
            return;
        }
        GradientDrawable fill = mKeyboardTravelSolidFill;
        if (wasTravelling && fill != null) {
            fill.setAlpha(Math.round(255f * solidness));
            return;
        }
        applyInAppKeyboardSurfaceState(buildChromeSpec());
    }

    /** Whether the keyboard host was last dressed as a card (Floating) rather than a frame slice. */
    private boolean mKeyboardSurfaceDressedAsCard;

    /** The in-app keyboard host's clip, the model's: see {@link #chromeClipOf}. */
    private final com.termux.app.chrome.ChromeShapeOutlineProvider mKeyboardOutline =
        new com.termux.app.chrome.ChromeShapeOutlineProvider();

    /**
     * Clips the keyboard host to its shape. A card (Floating, or a floating keyboard under either
     * Style) is its own bounds rounded to Corners; a Docked keyboard is its slice of the frame.
     */
    /**
     * The keyboard's clip with its bottom corners curving with the screen's when Full screen puts
     * the frame's bottom inside the bottom corners' band (FullScreenCornerPolicy); the clip as
     * given otherwise. Only the outline: keys, chin and height stay where they are. Needs a path
     * outline to clip, so Android 13 and later.
     */
    @Nullable
    private com.termux.app.chrome.LiveChromeShape.Clip fullScreenKeyboardClip(
            @NonNull View surfaceHost, @Nullable com.termux.app.chrome.LiveChromeShape.Clip clip) {
        if (Build.VERSION.SDK_INT < 33 || mProperties == null || !mProperties.isUsingFullScreen()
            || surfaceHost.getHeight() <= 0) return clip;
        int windowHeight = getWindow().getDecorView().getHeight();
        int[] origin = new int[2];
        com.termux.app.chrome.GlassAnchor.layoutOriginOnScreen(surfaceHost, origin, new int[2]);
        int bottom = origin[1] + surfaceHost.getHeight() + (clip == null ? 0 : clip.reachBottom);
        float screen = Math.max(mDisplayCornerRadiiPx[2], mDisplayCornerRadiiPx[3]);
        float own = clip == null ? 0f : Math.min(clip.bottomLeft, clip.bottomRight);
        float raised = com.termux.app.chrome.FullScreenCornerPolicy.bottomCornerRadiusPx(true,
            own, bottom, windowHeight, screen);
        if (raised <= own) return clip;
        return com.termux.app.chrome.LiveChromeShape.atLeast(clip == null
            ? com.termux.app.chrome.LiveChromeShape.cardClip(0f) : clip, 0f, raised);
    }

    /** The keyboard's clip before Full screen raised its bottom corners. */
    @Nullable private com.termux.app.chrome.LiveChromeShape.Clip mKeyboardBaseClip;
    /** The window-layout listener that re-reads the raise as the keyboard moves; once per host. */
    @Nullable private View mKeyboardCornerFollowed;

    /**
     * Re-reads the Full screen raise after every window layout, so a keyboard that moved (its
     * stack, the chin, a rise) curves with the screen on that pass rather than the next material
     * pass. Compares before it touches the outline, so a keyboard at rest costs one walk up.
     */
    private void followKeyboardForScreenCorners(@NonNull View surfaceHost) {
        if (mKeyboardCornerFollowed == surfaceHost) return;
        mKeyboardCornerFollowed = surfaceHost;
        surfaceHost.getViewTreeObserver().addOnGlobalLayoutListener(() -> {
            if (surfaceHost.getOutlineProvider() != mKeyboardOutline) return;
            if (mKeyboardOutline.setClip(keyboardOutlineClip(surfaceHost)))
                surfaceHost.invalidateOutline();
        });
    }

    /**
     * The clip the keyboard host's outline takes: {@link #fullScreenKeyboardClip}.
     */
    @Nullable
    private com.termux.app.chrome.LiveChromeShape.Clip keyboardOutlineClip(@NonNull View surfaceHost) {
        return fullScreenKeyboardClip(surfaceHost, com.termux.app.chrome.KeyboardSheetLook.outline(
            mKeyboardBaseClip, mKeyboardSheet.engaged()));
    }

    /** What the keyboard host wears over its own material while the drawer is open. */
    private final com.termux.app.chrome.KeyboardSheetSkin mKeyboardSheet =
        new com.termux.app.chrome.KeyboardSheetSkin();
    /** The host's own background, under the sheet; what {@link #setKeyboardHostBackground} was given. */
    @Nullable private Drawable mKeyboardHostInner;

    /**
     * One frame of the drawer's motion, as the keyboard sees it ({@link KeyboardSheetLook}): the
     * drawer's dim and glass over its own at the drawer's fraction. A compare per frame at rest;
     * the glass is built when the drawer first reaches the keyboard and let go when it leaves. The
     * card's shape is its own throughout, except that a Docked slice stands as a card of its own
     * (its top rounded at its own top) while it wears the sheet: {@link
     * com.termux.app.chrome.KeyboardSheetLook#outline}.
     */
    private void onKeyboardSheetFraction(float drawerFraction, float progress) {
        View host = findViewById(R.id.inapp_keyboard_view_host);
        float f = host == null ? 0f : com.termux.app.chrome.KeyboardSheetLook.glassFraction(
            isInAppKeyboardShown(), drawerFraction);
        if (f <= 0f && !mKeyboardSheet.engaged() && mKeyboardSheet.sheet() == null) return;
        boolean wasEngaged = mKeyboardSheet.engaged();
        if (f > 0f && mKeyboardSheet.sheet() == null) {
            float top = keyboardTopRadiusPx();
            mKeyboardSheet.setSheet(buildKeyboardSheetGlass(host, top), (int) Math.ceil(top));
        }
        mKeyboardSheet.setFraction(f);
        mKeyboardSheet.setDim(com.termux.app.chrome.KeyboardSheetLook.dimAlpha(f, progress));
        if (mKeyboardSheet.engaged() != wasEngaged && host != null) {
            host.setBackground(mKeyboardSheet.dress(mKeyboardHostInner));
            // The card's top moves to the keyboard's own while it wears the sheet, and back.
            if (host.getOutlineProvider() == mKeyboardOutline
                && mKeyboardOutline.setClip(keyboardOutlineClip(host)))
                host.invalidateOutline();
        }
        if (f <= 0f && mKeyboardSheet.sheet() != null) mKeyboardSheet.setSheet(null, 0);
    }

    /**
     * The radius of the keyboard card's top corners, px: a Floating card's, or the top of Docked's
     * slice of the frame. Read off the clip the host's outline was given, so it is the shape
     * already on screen.
     */
    private float keyboardTopRadiusPx() {
        com.termux.app.chrome.LiveChromeShape.Clip clip = mKeyboardBaseClip;
        return clip == null ? 0f : Math.max(0f, Math.max(clip.topLeft, clip.topRight));
    }

    /** The sheet's glass at the keyboard's place: Global's, at the sheets' opacity floor. */
    @Nullable
    private Drawable buildKeyboardSheetGlass(@Nullable View host, float radiusPx) {
        if (host == null || mPreferences == null) return null;
        com.termux.app.chrome.ElementGlass sheets =
            com.termux.app.chrome.SheetGlass.of(mPreferences);
        return buildInAppKeyboardGlass(sheets.spec(radiusPx, mFancierGlassLook)
            .withRim(!sheets.rimOff()), buildChromeSpec(), host, false);
    }

    private void applyInAppKeyboardSurfaceClip(@NonNull View surfaceHost, boolean capsule,
                                               float cornerRadiusPx) {
        mKeyboardBaseClip = capsule
            ? com.termux.app.chrome.LiveChromeShape.cardClip(cornerRadiusPx)
            : chromeClipOf(KEYBOARD_PIECES);
        boolean changed = mKeyboardOutline.setClip(keyboardOutlineClip(surfaceHost));
        followKeyboardForScreenCorners(surfaceHost);
        if (surfaceHost.getOutlineProvider() != mKeyboardOutline)
            surfaceHost.setOutlineProvider(mKeyboardOutline);
        else if (changed)
            surfaceHost.invalidateOutline();
        mKeyboardOutline.follow(surfaceHost);
        surfaceHost.setClipToOutline(true);
    }

    /**
     * The overlay keyboard's panel: one opaque fill in {@code colorSurfacePanelHigh}, the role
     * the drawer and the popups use, so it resolves per theme and per scheme. Rounded to the
     * capsule's cap or square, whichever the surface shape already clipped the host to.
     */
    @NonNull
    private GradientDrawable buildInAppKeyboardSolidSurface(float cornerRadiusPx) {
        GradientDrawable fill = new GradientDrawable();
        fill.setColor(getTermuxThemeColor(com.termux.shared.R.attr.termuxColorSurfacePanelHigh,
            R.color.termux_surface_panel_high));
        fill.setCornerRadius(cornerRadiusPx);
        return fill;
    }

    /**
     * The keyboard's glass, on the same {@link com.termux.app.chrome.GlassStack} the dock's cards
     * are built on: its own blur, tint and grain from its slot, the dock's refraction and rim.
     */
    @NonNull
    private Drawable buildInAppKeyboardSurfaceBackground(@NonNull ChromeSpec state,
                                                         @NonNull View surfaceHost,
                                                         boolean capsule, float cornerRadiusPx) {
        return buildInAppKeyboardSurfaceBackground(state, surfaceHost, capsule, cornerRadiusPx,
            false);
    }

    /**
     * {@code keep}: the host's own background, which is kept while the spec, the backdrop and the
     * values the stack bakes at build time are the same ({@link HeldBackground}), so the host does
     * not swap in a new drawable on every apply.
     */
    @NonNull
    private Drawable buildInAppKeyboardSurfaceBackground(@NonNull ChromeSpec state,
                                                         @NonNull View surfaceHost,
                                                         boolean capsule, float cornerRadiusPx,
                                                         boolean keep) {
        return buildInAppKeyboardGlass(inAppKeyboardGlassSpec(state, capsule, cornerRadiusPx,
            noteInAppKeyboardBand(surfaceHost)), state, surfaceHost, keep);
    }

    /**
     * The material the keyboard's glass is built in: the chrome's, and under the Terl switch in
     * Terl's Tint colour (the keyboard wears Terl's look), its ink and rim still the chrome's.
     */
    @NonNull
    private com.termux.app.chrome.GlassSurfaceFactory inAppKeyboardGlassFactory() {
        com.termux.app.chrome.GlassSurfaceFactory glass = mChrome.glass();
        if (mPreferences == null || !terlKeyboardLook().worn()) return glass;
        return glass.withLook(com.termux.app.chrome.GlassLook.of(mPreferences.getSurfaceGlassTint(),
            mPreferences.getSurfaceGlassRim(),
            terlKeyboardLook().tintHue(mPreferences.getSurfaceGlassTintHue())));
    }

    /** The glass {@code spec} says, over the keyboard's backdrop frame; {@code keep} as above. */
    @NonNull
    private Drawable buildInAppKeyboardGlass(@NonNull com.termux.app.chrome.GlassStack.Spec spec,
                                             @NonNull ChromeSpec state, @NonNull View surfaceHost,
                                             boolean keep) {
        int blurRadiusDp = spec.blurRadiusDp;
        com.termux.app.chrome.SharedFrameDrawable backdrop = null;
        // Over a Display page the bed is see-through: what is behind it is the live display, which
        // the frost layer under it blurs, so no wallpaper frame is drawn into it.
        Trace.beginSection("Chrome.kb.glass");
        try {
            if (ChromePolicy.dockBlurEnabled(blurRadiusDp) && !inAppKeyboardSeesThroughToDisplay()) {
                Bitmap frame = obtainInAppKeyboardBackdropFrame(state, surfaceHost);
                if (frame != null) {
                    // The shared frame, sampled at the host's own position on every draw — through
                    // the stack's travel, so a rising keyboard shows the wallpaper it is over. The
                    // one built last time is kept for the same host: a new one compiles its own
                    // refraction program, which was most of every chrome apply on pong.
                    com.termux.app.chrome.SharedFrameDrawable held = mInAppKeyboardBackdropDrawable;
                    if (com.termux.app.chrome.SharedFrameReuse.reuses(held,
                            mInAppKeyboardBackdropHost, surfaceHost,
                            mInAppKeyboardBackdropParallax, mWallpaperParallax)) {
                        backdrop = held;
                        backdrop.setFrame(frame, mInAppKeyboardBackdropFrameRect, false);
                    } else {
                        backdrop = new com.termux.app.chrome.SharedFrameDrawable(frame,
                            mInAppKeyboardBackdropFrameRect, mWallpaperParallax,
                            com.termux.app.chrome.GlassAnchor.layout(surfaceHost,
                                mAccessoryStackLift));
                        mInAppKeyboardBackdropDrawable = backdrop;
                        mInAppKeyboardBackdropHost = surfaceHost;
                        mInAppKeyboardBackdropParallax = mWallpaperParallax;
                    }
                    backdrop.setClearFrame(glassClearFrame(blurRadiusDp));
                }
            }
            // The drawable reports no intrinsic size. This background is installed on a
            // wrap-content host, and an intrinsic size would feed itself back into layout as a
            // blank band below a subsequently shorter keyboard. Decoration must follow content
            // geometry, never define it.
            float density = getResources().getDisplayMetrics().density;
            java.util.List<Object> key = null;
            if (keep) {
                // Everything GlassStack.build reads that is not the spec: the backdrop instance,
                // the band's baked veil and even-out, and the colours and look the factory
                // resolves for the glass layers.
                // The band's even-out as the build bakes it: measured first, and keyed by the
                // band's own token, so another band measured again (the dock, at a landing)
                // does not read as a new keyboard glass.
                if (spec.band != null) mChrome.ink().bandEvenOutMatrix(spec.band, null);
                key = com.termux.app.chrome.HeldBackground.key("glass", spec, backdrop, density,
                    mChrome.glass().bandVeil(spec.band), spec.band == null ? -1
                        : mChrome.ink().bandEvenOutChanges(spec.band),
                    resolveAccessoryGlassBaseColor(), resolveDockAccentColor(),
                    inAppKeyboardGlassFactory().look(spec.tintStrengthPercent));
                Drawable held = mKeyboardHostBackground.reuse(key);
                if (held != null) return held;
            }
            Drawable stack = com.termux.app.chrome.GlassStack.build(inAppKeyboardGlassFactory(),
                spec, density, backdrop);
            // Its ground is drawn on the host: the layout-neutral wrapper passes no callbacks on.
            com.termux.app.chrome.GroundUnderGlass.bind(stack, surfaceHost);
            Drawable built = new LayoutNeutralDrawable(stack);
            if (keep) mKeyboardHostBackground.hold(key, built);
            return built;
        } finally {
            Trace.endSection();
        }
    }

    /**
     * The keyboard host's backdrop as last built, the view it was anchored to and the parallax it
     * samples through; reused while those hold ({@link com.termux.app.chrome.SharedFrameReuse}),
     * let go with the frame in {@link #clearInAppKeyboardBackdrop}.
     */
    @Nullable private com.termux.app.chrome.SharedFrameDrawable mInAppKeyboardBackdropDrawable;
    @Nullable private View mInAppKeyboardBackdropHost;
    @Nullable private Object mInAppKeyboardBackdropParallax;

    /**
     * The glass or veil the keyboard host wears, kept while what it was built from is unchanged so
     * the host keeps one background instance for its life ({@link HeldBackground}). Released
     * whenever the host is given anything else, and with the backdrop.
     */
    private final com.termux.app.chrome.HeldBackground<Drawable> mKeyboardHostBackground =
        new com.termux.app.chrome.HeldBackground<>();

    /** Sets the host's background; one that is not the held glass lets the held glass go. */
    private void setKeyboardHostBackground(@NonNull View surfaceHost, @Nullable Drawable background) {
        // DIAG(kb-host): the keyboard host's material as it changes, with its caller; revert before merge.
        if (MotionLog.enabled && surfaceHost.getBackground() != background) {
            StackTraceElement[] st = new Throwable().getStackTrace();
            StringBuilder by = new StringBuilder();
            for (int k = 1; k < Math.min(st.length, 4); k++)
                by.append(st[k].getMethodName()).append(':').append(st[k].getLineNumber()).append(' ');
            Drawable d = background instanceof LayoutNeutralDrawable
                ? ((LayoutNeutralDrawable) background).source() : background;
            MotionLog.log("kb-host", "now=" + (d == null ? "null" : d.getClass().getSimpleName())
                + " crossing=" + mCrossing.crossing() + " look=" + stackLookPage() + " by=" + by);
        }
        if (!mKeyboardHostBackground.holds(background) && !keyboardBlendHoldsArrival(background))
            mKeyboardHostBackground.release();
        mKeyboardHostInner = background;
        // Under an open drawer the host wears the sheet's glass over this (KeyboardSheetSkin).
        surfaceHost.setBackground(mKeyboardSheet.dress(background));
    }

    /**
     * Whether {@code background} is the Floating look blend whose arriving end is the held glass:
     * that end stays held while the blend shows it, so the landing puts it up and the rest's own
     * pass reuses it rather than building the same glass again.
     */
    private boolean keyboardBlendHoldsArrival(@Nullable Drawable background) {
        com.termux.app.chrome.CrossfadeDrawable blend = mKeyboardLookBlend;
        return mKeyboardLookBlendDressed && blend != null && background == blend
            && mKeyboardHostBackground.holds(blend.there());
    }

    /**
     * The docked keyboard's host while the unified dock glass is its material: the keyboard band's
     * veil alone, measured on the keyboard's slice of that glass, or null when none is needed.
     */
    @Nullable
    private Drawable buildInAppKeyboardVeilOnly(@NonNull ChromeSpec state, @NonNull View surfaceHost) {
        com.termux.app.chrome.GlassBackdropCache.Band band = noteInAppKeyboardBand(surfaceHost);
        if (band == null) return null;
        Drawable veil = mChrome.glass().veilOnlyLayer(band, inAppKeyboardGlassAlpha(state), 0f,
            1f, false);
        if (veil == null) return null;
        // The layer is one flat colour, the band's veil as the call above just resolved it.
        java.util.List<Object> key = com.termux.app.chrome.HeldBackground.key("veil",
            mChrome.glass().bandVeil(band));
        Drawable held = mKeyboardHostBackground.reuse(key);
        if (held != null) return held;
        Drawable built = new LayoutNeutralDrawable(veil);
        mKeyboardHostBackground.hold(key, built);
        return built;
    }

    /**
     * Asks the keyboard band (appearance-layout-editor SPEC §2) what the host's glass has to become
     * for a letter key's and a function key's label to read on their caps, and names the band for
     * the surface to draw that veil. Measured at the host's laid-out rect, which ignores the
     * stack's travel and the editor's scale alike; null, and no veil, before the host is laid out
     * or the keyboard view exists. The veil lands on the next build when this one changes it.
     */
    @Nullable
    private com.termux.app.chrome.GlassBackdropCache.Band noteInAppKeyboardBand(
            @NonNull View surfaceHost) {
        Trace.beginSection("Chrome.kb.legendInks");
        int[] inks = mInAppKeyboard != null ? mInAppKeyboard.letterKeyLegibilityInks() : null;
        Trace.endSection();
        if (inks == null || surfaceHost.getWidth() <= 0 || surfaceHost.getHeight() <= 0)
            return null;
        Trace.beginSection("Chrome.kb.bandInk");
        try {
            return measureInAppKeyboardBand(surfaceHost, inks);
        } finally {
            Trace.endSection();
        }
    }

    /** {@link #noteInAppKeyboardBand}'s measurement, on a host that is laid out. */
    @NonNull
    private com.termux.app.chrome.GlassBackdropCache.Band measureInAppKeyboardBand(
            @NonNull View surfaceHost, @NonNull int[] inks) {
        Rect host = new Rect();
        com.termux.app.chrome.GlassAnchor.layoutRectOnScreen(surfaceHost, host, new int[2],
            new int[2]);
        // The letter legend on its cap and the function legend (Ctrl, Alt, Fn) on its thinner
        // chip, each over the row of the host where it reads worst. Asked as either tone (each
        // side's extreme, the function legend as drawn secondary), never as the legends drawn
        // now: the tone is chosen on the bare face and a veil bought only for that tone, so a
        // dark legend left from a brighter face cannot buy a milky veil that keeps it dark.
        int pale = android.graphics.Color.WHITE;
        int dark = android.graphics.Color.BLACK;
        // The keyboard band's even-out (ADR 0014) is current before its legends are judged on it.
        updateEvenOutPolicy();
        mChrome.ink().onFixedInkEitherTone(com.termux.app.chrome.GlassBackdropCache.Band.KEYBOARD,
            host, dark, pale, inks[1],
            com.termux.app.terminal.inappkeyboard.InAppKeyboardPaletteFactory.secondaryOf(dark),
            com.termux.app.terminal.inappkeyboard.InAppKeyboardPaletteFactory.secondaryOf(pale),
            inks[3], com.termux.app.chrome.OnGlass.TARGET_BODY_TEXT);
        mKeyboardBandRect.set(host);
        mKeyboardBandAskedThisPass = true;
        return com.termux.app.chrome.GlassBackdropCache.Band.KEYBOARD;
    }

    /**
     * Lets go of the frame the keyboard host was drawing. The frame is the blur cache's own and is
     * never recycled here: several surfaces may still be showing it, and the cache's in-use scan
     * decides what may go.
     */
    private void clearInAppKeyboardBackdrop() {
        mKeyboardHostBackground.release();
        clearInAppKeyboardBackdropFrame();
    }

    /** {@link #clearInAppKeyboardBackdrop} for a host whose held background holds no frame. */
    private void clearInAppKeyboardBackdropFrame() {
        mInAppKeyboardBackdropBitmap = null;
        // The drawable is kept for the host's next glass (SharedFrameReuse): a new one compiles
        // its own refraction program, 10-35 ms of the main thread on pong, and every keyboard
        // hide came through here. The cache's in-use scan reads the bitmap above, not this.
        mInAppKeyboardBackdropFrameRect.setEmpty();
        mChrome.ledger().reset(SurfaceDirtyLedger.Backdrop.IN_APP_KEYBOARD);
    }

    /**
     * The shared pre-blurred frame the keyboard host draws, at the keyboard's own radius. The host
     * samples it at its live position, so no geometry is cut here; the ledger only notes the
     * radius and source a rebuild was asked for. While a blur is in flight the frame already held
     * stays, as long as it still describes the screen it was captured for.
     */
    @Nullable
    private Bitmap obtainInAppKeyboardBackdropFrame(@NonNull ChromeSpec state,
                                                    @NonNull View surfaceHost) {
        View wallpaperFrame = findViewById(R.id.activity_termux_root_view);
        Rect targetRect = wallpaperFrame == null ? null
            : buildInAppKeyboardBackdropTargetRect(state, surfaceHost);
        if (targetRect == null) {
            return mChrome.ledger().isDirty(SurfaceDirtyLedger.Backdrop.IN_APP_KEYBOARD) ? null : mInAppKeyboardBackdropBitmap;
        }
        // The keyboard's own radius, not the dock's state.blurRadiusDp it used to share outright —
        // falls back to it while the keyboard's is still the -1 "follow" sentinel.
        int keyboardBlurRadiusDp = getEffectiveInAppKeyboardBlurRadius();
        boolean usingManagedWallpaperSource = shouldUseManagedWallpaperBlurSource();
        Bitmap frame = mChrome.blurCache().obtain(keyboardBlurRadiusDp, wallpaperFrame);
        Rect frameRect = mChrome.blurCache().frameRectRef();
        if (frame == null) {
            return mInAppKeyboardBackdropFrameRect.equals(frameRect) ? mInAppKeyboardBackdropBitmap : null;
        }
        mInAppKeyboardBackdropBitmap = frame;
        mInAppKeyboardBackdropFrameRect.set(frameRect);
        mChrome.ledger().recordApplied(SurfaceDirtyLedger.Backdrop.IN_APP_KEYBOARD, keyboardBlurRadiusDp,
            usingManagedWallpaperSource, targetRect);
        return frame;
    }

    /**
     * Returns the keyboard crop even during its first pre-layout render. The accessory stack is
     * bottom-anchored, so its already-laid-out bottom remains a stable reference while the new
     * keyboard height is waiting for layout.
     */
    @Nullable
    private Rect buildInAppKeyboardBackdropTargetRect(@NonNull ChromeSpec state,
                                                       @NonNull View surfaceHost) {
        if (surfaceHost.getWidth() > 0 && surfaceHost.getHeight() > 0) {
            surfaceHost.getLocationOnScreen(mTmpViewLocation);
            return new Rect(
                mTmpViewLocation[0],
                mTmpViewLocation[1],
                mTmpViewLocation[0] + surfaceHost.getWidth(),
                mTmpViewLocation[1] + surfaceHost.getHeight()
            );
        }

        View accessoryContainer = findViewById(R.id.accessory_stack_container);
        if (accessoryContainer == null || state.keyboardHeight <= 0) {
            return null;
        }
        accessoryContainer.getLocationOnScreen(mTmpViewLocation);
        int width = accessoryContainer.getWidth();
        if (width <= 0) {
            width = getResources().getDisplayMetrics().widthPixels;
        }
        int bottom = mTmpViewLocation[1] + accessoryContainer.getHeight();
        if (bottom <= 0) {
            Rect frameRect = getManagedWallpaperFrameRect();
            bottom = frameRect.bottom;
        }
        return new Rect(
            mTmpViewLocation[0],
            Math.max(0, bottom - state.keyboardHeight),
            mTmpViewLocation[0] + Math.max(1, width),
            Math.max(1, bottom)
        );
    }

    /**
     * True once the one expanded dock+keyboard surface is the material on screen: its geometry is
     * laid out over both, and — only when there is a frame to blur — its crop is installed and
     * current. See {@link ChromePolicy#unifiedKeyboardSurfaceIsTheMaterial} for why the crop is not
     * asked for when there is none.
     */
    private boolean isUnifiedAccessoryBackdropReady(@NonNull ChromeSpec state) {
        if (!shouldUseUnifiedDefaultKeyboardGlassSurface(state)) {
            return false;
        }
        return ChromePolicy.unifiedKeyboardSurfaceIsTheMaterial(
            isUnifiedAccessorySurfaceLaidOut(state), state.blurEnabled,
            isUnifiedAccessoryCropInstalled(state));
    }

    /** The expanded surface's own geometry: laid out over the dock and the keyboard together. */
    private boolean isUnifiedAccessorySurfaceLaidOut(@NonNull ChromeSpec state) {
        // Apart under Docked the unified surface is the Terminal's own host (#304).
        View surfaceHost = findViewById(mSideCards.terminalHostOn() ? R.id.terminal_dock_host
            : R.id.accessory_surface_host);
        View accessoryContainer = findViewById(R.id.accessory_stack_container);
        View keyboardContainer = findViewById(R.id.inapp_keyboard_container);
        if (surfaceHost == null || accessoryContainer == null || keyboardContainer == null
            || keyboardContainer.getVisibility() == View.GONE) {
            return false;
        }
        ViewGroup.LayoutParams containerParams = accessoryContainer.getLayoutParams();
        int expectedHeight = containerParams != null && containerParams.height > 0
            ? containerParams.height : accessoryContainer.getHeight();
        // Its bottom reaching the stack's, not its height matching it: asked that way the
        // keyboard kept a coat of its own over the shared glass for good, a keyboard more opaque
        // than the extra keys above it.
        return ChromePolicy.unifiedHostLaidOut(surfaceHost.getBottom(), surfaceHost.getHeight(),
            expectedHeight, state.keyboardHeight);
    }

    /**
     * The expanded surface's backdrop: showing the shared frame, laid out at the surface's size,
     * and aimed for this geometry. Both this and the pass that records the geometry build the
     * same, unwidened rect; when the pass recorded a rect widened for the parallax the two never
     * matched while the wallpaper could pan, so the keyboard-local coat never came off and the
     * keyboard's reveal fell to its backstop on every open.
     */
    private boolean isUnifiedAccessoryCropInstalled(@NonNull ChromeSpec state) {
        if (mSideCards.terminalHostOn()) {
            // Apart under Docked the unified surface is the Terminal's own host (#304): its
            // dress keeps its own record, clean once its crop is installed for this geometry.
            ImageView terminal = findViewById(R.id.terminal_dock_blur_backdrop);
            return mTerminalHostDress.shown() && terminal != null
                && terminal.getDrawable() != null && terminal.getVisibility() == View.VISIBLE
                && !mChrome.ledger().isDirty(SurfaceDirtyLedger.Backdrop.TERMINAL_HOST);
        }
        ImageView backdrop = findViewById(R.id.accessory_blur_backdrop);
        View surfaceHost = findViewById(R.id.accessory_surface_host);
        if (backdrop == null || surfaceHost == null || backdrop.getDrawable() == null
            || backdrop.getVisibility() != View.VISIBLE) {
            return false;
        }
        int horizontalOverscanPx = computeAccessoryBackdropHorizontalOverscanPx(state.blurRadiusDp);
        int seamOverscanPx = com.termux.app.dock.CapsuleGlass.seamOverscanPx(hostFootPx(),
            horizontalOverscanPx);
        Rect currentTarget = buildAccessoryBackdropTargetRect(
            surfaceHost, horizontalOverscanPx, seamOverscanPx);
        // setLayoutParams() during pre-draw does not resize the ImageView until another layout.
        // Treat that pass as unready so it is skipped instead of drawing the expanded surface with
        // a dock-height blur child for one frame.
        if (backdrop.getWidth() < currentTarget.width()
            || backdrop.getHeight() < currentTarget.height()) {
            return false;
        }
        return mChrome.ledger().lastRadiusDp(SurfaceDirtyLedger.Backdrop.ACCESSORY) == state.blurRadiusDp
            && mChrome.ledger().lastManagedSource(SurfaceDirtyLedger.Backdrop.ACCESSORY) == shouldUseManagedWallpaperBlurSource()
            && mChrome.ledger().matchesLastRect(SurfaceDirtyLedger.Backdrop.ACCESSORY, currentTarget);
    }



    private boolean isAccessoryBlurHealthy(@NonNull ChromeSpec state) {
        View accessoryContainer = findViewById(R.id.accessory_stack_container);
        if (accessoryContainer == null || !mDockRows.stackShown()) {
            return !state.toolbarShown;
        }
        // Under a joined Docked frame the dock has no blur of its own to keep alive, unless its
        // sheet returns for the beads.
        if (dockSheetStandsDownOnFrame()) return true;
        boolean useRenderEffectBlur = shouldUseAccessoryRenderEffectBlur(state);
        if (useRenderEffectBlur) {
            ImageView backdrop = findViewById(R.id.accessory_blur_backdrop);
            boolean accessoryHealthy = backdrop != null
                && backdrop.getVisibility() == View.VISIBLE
                && backdrop.getDrawable() != null;
            return accessoryHealthy;
        }
        // Without RenderEffect the dock has no live blur of its own to be healthy; the renderer
        // only asks while blur is on and the toolbar is shown, which is the RenderEffect case.
        return false;
    }

    private boolean shouldUseManagedWallpaperBlurSource() {
        if (mPreferences == null) {
            return false;
        }
        return wallpaperSourceFacts().managedOnScreen();
    }

    /**
     * The wallpaper source facts every glass surface reads in a pass, read once and held: the
     * system id is a binder call and the file's facts are stats, and the blur cache alone asked
     * for them once per surface per obtain.
     */
    @NonNull
    private com.termux.app.chrome.WallpaperSourceFacts wallpaperSourceFacts() {
        com.termux.app.chrome.WallpaperSourceFacts facts = mWallpaperSourceFacts;
        // The stored id and the app-only mark are preferences held in memory, so they are checked
        // on every ask: the picker (or a command) writes them once the picture is on disk, and a
        // moved one reads again.
        if (facts == null || facts.isStaleFor(storedManagedWallpaperSystemId(), storedWallpaperAppOnly())) {
            facts = refreshWallpaperSourceFacts();
        }
        return facts;
    }

    private int storedManagedWallpaperSystemId() {
        return mPreferences == null ? 0 : mPreferences.getManagedWallpaperSystemId();
    }

    private boolean storedWallpaperAppOnly() {
        return mPreferences != null && mPreferences.isWallpaperAppOnly();
    }

    /**
     * Whether the launcher wears its app-only picture (one Android's home and lock screens never
     * got), with the copy on disk; see {@link com.termux.app.chrome.WallpaperSourceFacts#appOnlyOnScreen}.
     */
    private boolean appOnlyWallpaperOnScreen() {
        return mPreferences != null && wallpaperSourceFacts().appOnlyOnScreen();
    }

    /**
     * Reads the wallpaper source facts afresh. Called wherever the wallpaper can have changed —
     * {@link #refreshWallpaperPicture()} (every arrival and the picker's apply), the colours
     * listener and the managed picture landing — and always before the capture that follows, so
     * the blur cache's identity check sees the same id the capture is cut for.
     */
    @NonNull
    private com.termux.app.chrome.WallpaperSourceFacts refreshWallpaperSourceFacts() {
        File exact = getManagedWallpaperExactFile();
        boolean present = exact.isFile();
        int width = 0, height = 0;
        if (present && mManagedWallpaperSource.readSize(exact, mManagedWallpaperSize)) {
            width = mManagedWallpaperSize[0];
            height = mManagedWallpaperSize[1];
        }
        com.termux.app.chrome.WallpaperSourceFacts facts = com.termux.app.chrome.WallpaperSourceFacts.of(
            storedManagedWallpaperSystemId(), getCurrentSystemWallpaperId(), present,
            exact.lastModified(), exact.length(), width, height, storedWallpaperAppOnly());
        mWallpaperSourceFacts = facts;
        // An app-only picture set, replaced, ended or gone moves the theme's colours too (ADR
        // 0011), and Android sends no configuration change for a picture it never got: the theme
        // is checked wherever these are read again, after the pass that asked.
        mAccessoryRenderHandler.removeCallbacks(mWallpaperColorsCheck);
        mAccessoryRenderHandler.post(mWallpaperColorsCheck);
        return facts;
    }

    /** Re-themes the activity when the app-only colours it wears no longer apply. */
    private final Runnable mWallpaperColorsCheck =
        () -> TermuxThemeManager.recreateIfWallpaperColorsMoved(this);

    private int computeAccessoryBackdropHorizontalOverscanPx(int blurRadiusDp) {
        float blurRadiusPx = ViewUtils.dpToPx(this, Math.max(0, blurRadiusDp));
        float density = getResources().getDisplayMetrics().density;
        return com.termux.app.dock.CapsuleGlass.horizontalOverscanPx(blurRadiusPx, density);
    }

    private void applyAccessoryBackdropOverscan(@NonNull ImageView backdrop, @NonNull View surfaceHost,
                                                int horizontalOverscanPx, int bottomOverscanPx) {
        com.termux.app.dock.CapsuleGlass.applyOverscan(backdrop, surfaceHost.getWidth(),
            surfaceHost.getHeight(), horizontalOverscanPx, bottomOverscanPx);
    }

    @NonNull
    private Rect buildAccessoryBackdropTargetRect(@NonNull View surfaceHost, int horizontalOverscanPx,
                                                  int bottomOverscanPx) {
        surfaceHost.getLocationOnScreen(mTmpViewLocation);
        return com.termux.app.dock.CapsuleGlass.targetRect(mTmpViewLocation, surfaceHost.getWidth(),
            surfaceHost.getHeight(), horizontalOverscanPx, bottomOverscanPx);
    }

    /**
     * The managed wallpaper file decoded once, off the main thread, at the frame's size. Reading
     * it in place on every blur-cache miss was the launcher's "not responding" after a large
     * wallpaper was set.
     */
    private final com.termux.app.chrome.ManagedWallpaperSource mManagedWallpaperSource =
        new com.termux.app.chrome.ManagedWallpaperSource(
            java.util.concurrent.Executors.newSingleThreadExecutor(runnable -> {
                Thread thread = new Thread(runnable, "managed-wallpaper-decode");
                thread.setPriority(Thread.NORM_PRIORITY - 1);
                return thread;
            }),
            runnable -> new Handler(Looper.getMainLooper()).post(runnable));
    /** Set by the managed path when its read is in flight: draw nothing, a sync follows. */
    private boolean mManagedWallpaperPending;

    /**
     * The managed wallpaper's capture for {@code targetRect}: the geometry and the decoded file
     * are read here, on the main thread, and the full-size draw is handed to the blur worker. It
     * used to allocate and draw the full-size frame right here on every miss, a software draw of
     * the whole frame per radius on the main thread.
     */
    @Nullable
    private com.termux.app.chrome.WallpaperBlurCache.FrameCapture beginManagedWallpaperCapture(
            @NonNull Rect targetRect) {
        File sourceFile = getManagedWallpaperExactFile();
        // The capture rect, not the decor's: with parallax the frame is as wide as the picture,
        // so the cover draw below is the whole picture at 1:1; without it, the picture's centre.
        Rect frameRect = getWallpaperCaptureFrameRect();
        Bitmap sourceBitmap = mManagedWallpaperSource.obtain(sourceFile, frameRect.width(),
            frameRect.height(), () -> {
                if (isFinishing() || isDestroyed()) return;
                // The file that just landed is the one the facts must describe from here on.
                refreshWallpaperSourceFacts();
                // The managed file landing is a new wallpaper picture; tagged the same way, so the
                // surface that refills each radius crossfades into it instead of swapping outright.
                mChrome.blurCache().clearForWallpaperChange();
                // The panes and the wall's pages hold the frame they were dressed with; they
                // need the one that now exists, not only the accessory backdrops.
                updateTerminalGlassFrost();
                mChrome.requestSync(ChromeRenderer.SCOPE_BACKDROPS | ChromeRenderer.SCOPE_ACCESSORY_RENDER);
            });
        mManagedWallpaperPending = sourceBitmap == null && mManagedWallpaperSource.isReading();
        if (sourceBitmap == null) {
            return null;
        }
        final Rect target = new Rect(targetRect);
        final Rect frame = new Rect(frameRect);
        final float zoom = systemWallpaperRenderZoom();
        // Lent to the worker: a new file landing (or onDestroy) clears the source on this thread,
        // and must not recycle the picture while the worker is still drawing from it. The cache
        // gives the loan back exactly once: after the draw, or when no job will ever draw it (the
        // capture dropped first, its job rejected, or the worker shut down with it queued).
        mManagedWallpaperSource.lend(sourceBitmap);
        return com.termux.app.chrome.WallpaperBlurCache.FrameCapture.deferred(
            () -> drawManagedWallpaperBackdrop(sourceBitmap, target, frame, zoom),
            () -> runOnUiThread(() -> mManagedWallpaperSource.release(sourceBitmap)));
    }

    /**
     * Any thread: the managed picture drawn into {@code targetRect} at full size, from geometry
     * the caller read on the main thread. Null when the picture was recycled before the draw.
     */
    @Nullable
    private static Bitmap drawManagedWallpaperBackdrop(@NonNull Bitmap sourceBitmap,
                                                       @NonNull Rect targetRect,
                                                       @NonNull Rect frameRect, float zoom) {
        if (sourceBitmap.isRecycled()) return null;
        int targetWidth = Math.max(1, targetRect.width());
        int targetHeight = Math.max(1, targetRect.height());

        Bitmap bitmap = Bitmap.createBitmap(targetWidth, targetHeight, Bitmap.Config.ARGB_8888);
        Canvas canvas = new Canvas(bitmap);
        int frameWidth = Math.max(1, frameRect.width());
        int frameHeight = Math.max(1, frameRect.height());
        int sourceWidth = Math.max(1, sourceBitmap.getWidth());
        int sourceHeight = Math.max(1, sourceBitmap.getHeight());
        float scale = Math.max((float) frameWidth / sourceWidth, (float) frameHeight / sourceHeight);
        float drawWidth = sourceWidth * scale;
        float drawHeight = sourceHeight * scale;
        float translateX = frameRect.left + ((frameWidth - drawWidth) / 2f) - targetRect.left;
        float translateY = frameRect.top + ((frameHeight - drawHeight) / 2f) - targetRect.top;

        Matrix shaderMatrix = new Matrix();
        shaderMatrix.setScale(scale, scale);
        shaderMatrix.postTranslate(translateX, translateY);
        if (zoom != 1f) {
            // Same render-zoom compensation as the system-drawable path, in this bitmap's
            // local coordinates (the target rect's origin is already subtracted above).
            shaderMatrix.postScale(zoom, zoom,
                frameRect.exactCenterX() - targetRect.left,
                frameRect.exactCenterY() - targetRect.top);
        }

        BitmapShader shader = new BitmapShader(sourceBitmap, Shader.TileMode.CLAMP, Shader.TileMode.CLAMP);
        shader.setLocalMatrix(shaderMatrix);
        Paint paint = new Paint(Paint.ANTI_ALIAS_FLAG | Paint.FILTER_BITMAP_FLAG);
        paint.setShader(shader);
        canvas.drawRect(0f, 0f, targetWidth, targetHeight, paint);
        return bitmap;
    }

    /**
     * Extra magnification the system applies when it renders the static wallpaper, about the
     * display center, as a factor. ROMs that honor {@code setWallpaperZoomOut(0)} render at 1.0 and
     * need no compensation; Nothing OS applies its own regardless of what the launcher asks for —
     * and by an amount that depends on the wallpaper, which is why this is the user's Wallpaper
     * measured per ROM and not a constant. A stored 1328x2654 wallpaper measured 1.03, a
     * 1400x3100 one about 1.084, on the same panel and the same ROM.
     *
     * <p>Only the composite zoom belongs here. Whatever scaling is baked into the stored bitmap is
     * already in the pixels: the frost samples {@code WallpaperManager.getDrawable()}, which
     * returns the wallpaper <em>as the system stored it</em>, so re-applying the store-scale
     * double-counts it — that was the original bug.
     *
     * <p>How to measure one: set the wallpaper through the in-app picker, which keeps a byte-exact
     * copy of the source, then fit {@code source = ((screen - centre) / zoom + centre) / fillScale}
     * against the sharp wallpaper still visible in a screenshot's margins. For the 1328x2654 case
     * 1.03 fit to a mean squared error of 4 with no pan term, against 355 for 1.00 and 564 for
     * 1.10. Over-compensating displaces every frost by that error times its distance from the
     * centre — around 75px at the status bar for seven percent — which is what "the blur is offset"
     * looks like. Fit the number; do not nudge it by eye.
     */
    private float systemWallpaperRenderZoom() {
        return effectiveWallpaperRenderZoomPercent() / 100f;
    }

    /**
     * The zoom the captures are actually taken at: the slider in passthrough mode, and 1.0 while
     * the launcher draws the wallpaper itself, where backdrop and glass share one frame and a zoom
     * would only slide the glass off our own backdrop.
     */
    private int effectiveWallpaperRenderZoomPercent() {
        // No control any more: the ROM's measured composite zoom is the only number there is.
        return WallpaperBackdropPolicy.renderZoomPercent(wallpaperBackdropMode(),
            TermuxAppSharedPreferences.defaultWallpaperRenderZoom(Build.MANUFACTURER));
    }

    /**
     * Drops the pre-blurred frames when the wallpaper alignment moved.
     *
     * <p>Every resident frame was captured at the old zoom and the cache's identity does not
     * include it (frame rect, source and wallpaper id only), so a styling reload alone would keep
     * serving the misaligned crops. The value the frames were captured at is recorded in
     * {@code onCreate}, so the comparison holds for a change made in Settings before this process
     * had ever reloaded its styling.
     *
     * <p>It is the <em>effective</em> zoom that is compared, so switching to or from a live
     * wallpaper — which moves the mode, and with it the zoom, without anyone touching the slider —
     * drops the frames the same way a slider drag does.
     */
    private void applyWallpaperRenderZoomIfChanged() {
        if (mPreferences == null)
            return;
        int percent = effectiveWallpaperRenderZoomPercent();
        if (percent == mAppliedWallpaperRenderZoomPercent)
            return;
        mAppliedWallpaperRenderZoomPercent = percent;
        mChrome.blurCache().clear();
        updateTerminalGlassFrost();
        mChrome.requestSync(ChromeRenderer.SCOPE_BACKDROPS | ChromeRenderer.SCOPE_ACCESSORY_RENDER);
    }

    /**
     * The glass bands blur a crop of the system wallpaper read through {@link WallpaperManager}.
     * Where the platform still gates that read behind the legacy storage permission, an install
     * that never ran {@code termux-setup-storage} and never set its wallpaper through the in-app
     * picker (which keeps a managed copy and needs no permission) gets a {@link SecurityException}
     * instead, and every band renders flat with nothing but a log line to say why. Ask at the
     * point the read actually fails rather than up front, so devices that can read the wallpaper
     * are never prompted at all.
     */
    private void onSystemWallpaperReadDenied() {
        if (mWallpaperReadPermissionDenied) {
            return;
        }
        mWallpaperReadPermissionDenied = true;
        // Called from inside a render pass; do not put up a dialog mid-draw.
        View root = findViewById(R.id.activity_termux_root_view);
        if (root != null) {
            root.post(this::maybeRequestWallpaperReadPermission);
        }
    }


    private void maybeRequestWallpaperReadPermission() {
        if (!mIsVisible || mPreferences == null || isFinishing() || isDestroyed()) {
            return;
        }
        if (setupWizardComesFirst()) {
            // Asked again by the next failed read once the wizard is done.
            mWallpaperReadPermissionDenied = false;
            return;
        }
        boolean permissionGranted = androidx.core.content.ContextCompat.checkSelfPermission(this,
            android.Manifest.permission.READ_EXTERNAL_STORAGE)
            == android.content.pm.PackageManager.PERMISSION_GRANTED;
        if (permissionGranted) {
            // Already granted and the read still failed: the refusal is not about this permission,
            // so a prompt would only nag.
            mWallpaperReadPermissionDenied = false;
            return;
        }
        if (mWallpaperReadPermissionPromptShowing
            || !ChromePolicy.shouldPromptForWallpaperRead(mWallpaperReadPermissionDenied,
                shouldUseWallpaperPassthroughMode(), false,
                mPreferences.isWallpaperReadPermissionPrompted())) {
            return;
        }
        mWallpaperReadPermissionPromptShowing = true;
        new MaterialAlertDialogBuilder(this)
            .setTitle(R.string.title_wallpaper_read_permission)
            .setMessage(R.string.msg_wallpaper_read_permission)
            .setPositiveButton(R.string.action_wallpaper_read_permission_allow, (dialog, which) -> {
                mPreferences.setWallpaperReadPermissionPrompted(true);
                androidx.core.app.ActivityCompat.requestPermissions(this,
                    new String[] {android.Manifest.permission.READ_EXTERNAL_STORAGE},
                    REQUEST_CODE_WALLPAPER_READ_PERMISSION);
            })
            .setNegativeButton(R.string.action_wallpaper_read_permission_dismiss, (dialog, which) ->
                mPreferences.setWallpaperReadPermissionPrompted(true))
            .setOnDismissListener(dialog -> mWallpaperReadPermissionPromptShowing = false)
            .show();
    }

    /**
     * The blur cache's capture, split across threads: for both sources only the geometry is read
     * here, on the main thread — the managed source answers from its own decode (or says it is
     * reading), and the full-size draw from it, like the system wallpaper's decode, is handed back
     * as a job for the blur worker. Reading the system wallpaper was a ~46 ms decode per miss on
     * the main thread (Pong, 2026-09-09).
     */
    @Nullable
    private com.termux.app.chrome.WallpaperBlurCache.FrameCapture beginWallpaperFrameCapture(
            @NonNull Rect targetRect, @NonNull View wallpaperFrame) {
        if (shouldUseManagedWallpaperBlurSource()) {
            com.termux.app.chrome.WallpaperBlurCache.FrameCapture managed =
                beginManagedWallpaperCapture(targetRect);
            if (managed != null) {
                return managed;
            }
            // While the file is being read there is nothing to draw yet; the system drawable
            // would be the same picture decoded again, on this thread, for a frame about to be
            // replaced by the managed one.
            if (mManagedWallpaperPending) return null;
        }
        final Rect target = new Rect(targetRect);
        // The system wallpaper never pans, so this is the decor's rect whenever it is reached.
        final Rect frameRect = getWallpaperCaptureFrameRect();
        final float zoom = systemWallpaperRenderZoom();
        final WallpaperManager wallpaperManager = WallpaperManager.getInstance(this);
        return com.termux.app.chrome.WallpaperBlurCache.FrameCapture.deferred(
            () -> decodeSystemWallpaperBackdrop(wallpaperManager, target, frameRect, zoom));
    }

    /** Worker thread. The system wallpaper drawn into {@code targetRect}, or null. */
    @Nullable
    private Bitmap decodeSystemWallpaperBackdrop(@NonNull WallpaperManager wallpaperManager,
                                                 @NonNull Rect targetRect, @NonNull Rect frameRect,
                                                 float zoom) {
        Drawable wallpaper;
        try {
            wallpaper = wallpaperManager.getDrawable();
        } catch (SecurityException e) {
            Logger.logStackTraceWithMessage(LOG_TAG, "Cannot read system wallpaper for accessory backdrop", e);
            runOnUiThread(this::onSystemWallpaperReadDenied);
            return null;
        }
        runOnUiThread(() -> mWallpaperReadPermissionDenied = false);
        if (wallpaper == null) {
            return null;
        }
        try {
            return drawWallpaperBackdrop(wallpaper, targetRect, frameRect, zoom);
        } finally {
            // getDrawable() leaves the framework holding the decoded wallpaper in
            // WallpaperManager's globals; it is copied into our frame now, so let it go.
            try {
                wallpaperManager.forgetLoadedWallpaper();
            } catch (Exception ignored) {
            }
        }
    }

    /** Any thread: pure drawing from geometry the caller read on the main thread. */
    private static Bitmap drawWallpaperBackdrop(@NonNull Drawable wallpaper, @NonNull Rect targetRect,
                                                @NonNull Rect frameRect, float zoom) {
        int targetWidth = Math.max(1, targetRect.width());
        int targetHeight = Math.max(1, targetRect.height());
        int frameWidth = Math.max(1, frameRect.width());
        int frameHeight = Math.max(1, frameRect.height());

        int intrinsicWidth = wallpaper.getIntrinsicWidth() > 0 ? wallpaper.getIntrinsicWidth() : frameWidth;
        int intrinsicHeight = wallpaper.getIntrinsicHeight() > 0 ? wallpaper.getIntrinsicHeight() : frameHeight;
        float scale = Math.max((float) frameWidth / intrinsicWidth, (float) frameHeight / intrinsicHeight);
        int drawWidth = Math.max(frameWidth, Math.round(intrinsicWidth * scale));
        int drawHeight = Math.max(frameHeight, Math.round(intrinsicHeight * scale));

        int frameScreenX = frameRect.left;
        int frameScreenY = frameRect.top;
        int offsetLeft = frameScreenX + Math.round((frameWidth - drawWidth) / 2f);
        int offsetTop = frameScreenY + Math.round((frameHeight - drawHeight) / 2f);

        if (zoom != 1f) {
            float centerX = frameRect.exactCenterX();
            float centerY = frameRect.exactCenterY();
            offsetLeft = Math.round(zoom * (offsetLeft - centerX) + centerX);
            offsetTop = Math.round(zoom * (offsetTop - centerY) + centerY);
            drawWidth = Math.round(drawWidth * zoom);
            drawHeight = Math.round(drawHeight * zoom);
        }

        Bitmap bitmap = Bitmap.createBitmap(targetWidth, targetHeight, Bitmap.Config.ARGB_8888);
        Canvas canvas = new Canvas(bitmap);
        Drawable drawable = wallpaper.getConstantState() != null
            ? wallpaper.getConstantState().newDrawable().mutate()
            : wallpaper.mutate();
        drawable.setBounds(
            offsetLeft - targetRect.left,
            offsetTop - targetRect.top,
            offsetLeft - targetRect.left + drawWidth,
            offsetTop - targetRect.top + drawHeight
        );
        drawable.draw(canvas);
        return bitmap;
    }




    /**
     * True while a full-screen glass frost is displaying this exact frame through the identity fast
     * path in {@link #createCachedAccessoryWallpaperBlurCrop}. Recycling a bitmap an ImageView still
     * holds crashes on its next draw, so such a frame is dropped from the cache without recycling
     * and left to the collector.
     */
    private boolean isSharedWallpaperBlurFrameInUse(@Nullable Bitmap frame) {
        if (frame == null) {
            return false;
        }
        if (frame == mPaneGlassFrame || frame == mPaneGlassClearFrame || frame == mWallBehindFrame) {
            return true;   // a pane is drawing it right now; recycling it would crash its next draw
        }
        if (mWallpaperBackdropView != null && (mWallpaperBackdropView.heldFrame() == frame
                || mWallpaperBackdropView.fadingFrame() == frame)) {
            // The self-drawn backdrop keeps the frame it is showing across a clear, so the wall
            // does not flash the system wallpaper while the replacement is on the blur worker —
            // and keeps the one it is fading out of for as long as that crossfade is still on screen.
            return true;
        }
        // Every surface that samples the shared frame directly, the frame a crossfade is still
        // fading out of included: the frosts, the dock's backdrop and the
        // keyboard host's background.
        int[] frostIds = {R.id.command_palette_wallpaper_backdrop, R.id.terminal_sheet_wallpaper_backdrop,
            R.id.app_drawer_wallpaper_backdrop, R.id.accessory_blur_backdrop,
            R.id.place_off_dock_plank_frost, R.id.place_az_bar_host_frost};
        for (int frostId : frostIds) {
            ImageView frost = findViewById(frostId);
            if (frost != null && drawableShowsFrame(frost.getDrawable(), frame)) return true;
        }
        // The bars' glass views hold their own frost.
        int[] barIds = {R.id.terminal_status_bar_glass_surface, R.id.terminal_window_bar_background,
            R.id.terminal_window_bar_background_side};
        for (int barId : barIds) {
            View bar = findViewById(barId);
            if (bar instanceof com.termux.app.chrome.BarGlassView
                && drawableShowsFrame(((com.termux.app.chrome.BarGlassView) bar).getFrost(), frame))
                return true;
        }
        View keyboardHost = findViewById(R.id.inapp_keyboard_view_host);
        if (keyboardHost != null && drawableShowsFrame(keyboardHost.getBackground(), frame))
            return true;
        View underKeyboard = findViewById(R.id.accessory_under_keyboard_stack);
        return underKeyboard != null && drawableShowsFrame(underKeyboard.getBackground(), frame);
    }

    /** True while {@code drawable} — a shared-frame drawable, or a stack holding one — shows {@code frame}. */
    private static boolean drawableShowsFrame(@Nullable Drawable drawable, @NonNull Bitmap frame) {
        if (drawable instanceof LayoutNeutralDrawable) drawable = ((LayoutNeutralDrawable) drawable).source();
        if (drawable instanceof com.termux.app.chrome.RoundedSheetDrawable)
            drawable = ((com.termux.app.chrome.RoundedSheetDrawable) drawable).source();
        com.termux.app.chrome.SharedFrameDrawable shared = com.termux.app.chrome.SharedFrameDrawable.of(drawable);
        return shared != null && shared.shows(frame);
    }


    private void updateAccessoryRenderEffectBackdrop(@NonNull ChromeSpec state) {
        ImageView backdrop = findViewById(R.id.accessory_blur_backdrop);
        View surfaceHost = findViewById(R.id.accessory_surface_host);
        View accessoryContainer = findViewById(R.id.accessory_stack_container);
        boolean usingManagedWallpaperSource = shouldUseManagedWallpaperBlurSource();
        View wallpaperFrame = findViewById(R.id.activity_termux_root_view);
        if (backdrop != null) {
            backdrop.setAlpha(1f);
        }
        applyAccessorySurfaceBounds(state);
        // The Lens beads follow the row as it is laid out now; a pass that moved them and
        // re-installs nothing rebuilds the effect once below.
        boolean beadsMoved = mDock.refreshDockBeads();
        if (backdrop == null || surfaceHost == null || accessoryContainer == null || wallpaperFrame == null ||
            accessoryContainer.getWidth() <= 0 || accessoryContainer.getHeight() <= 0) {
            if (backdrop != null && shouldUseAccessoryRenderEffectBlur(state)
                && accessoryPictureUp(backdrop)) {
                backdrop.setVisibility(View.VISIBLE);
            } else {
                clearAccessoryRenderEffectBackdrop();
            }
            return;
        }
        if (!shouldUseAccessoryRenderEffectBlur(state)) {
            clearAccessoryRenderEffectBackdrop();
            return;
        }
        int horizontalOverscanPx = computeAccessoryBackdropHorizontalOverscanPx(state.blurRadiusDp);
        // When the under-pill decor strip abuts the dock/keyboard bottom (default dock only), overscan
        // the view downward past that seam so the refraction edge band lands below it — the strip
        // overscans upward by the same amount, so the two surfaces' blurred wallpaper meets seamlessly.
        int seamOverscanPx = com.termux.app.dock.CapsuleGlass.seamOverscanPx(hostFootPx(),
            horizontalOverscanPx);
        applyAccessoryBackdropOverscan(backdrop, surfaceHost, horizontalOverscanPx, seamOverscanPx);
        // The dock's own overscan is what the ImageView is sized to. The drawable inside samples
        // the shared frame at the view's live position, so the rect only says where the shader's
        // capsule sits and whether the surface has moved since the last pass.
        Rect backdropTargetRect = buildAccessoryBackdropTargetRect(surfaceHost, horizontalOverscanPx,
            seamOverscanPx);
        com.termux.app.chrome.SharedFrameDrawable installed =
            com.termux.app.chrome.SharedFrameDrawable.of(backdrop.getDrawable());
        float dockCover = mDock.dockGlassCover();
        // A Frost drag moves the radius every tick; the bakes are held, so a re-install would put
        // up a stand-in and rebuild the refraction effect for nothing the eye gains. The frame
        // up stays until the release's pass, which re-cuts at the radius the drag settled on.
        if (!mChrome.ledger().isDirty(SurfaceDirtyLedger.Backdrop.ACCESSORY) &&
            dockCover == mDockGlassCover &&
            (mGlassDragPreview
                || mChrome.ledger().lastRadiusDp(SurfaceDirtyLedger.Backdrop.ACCESSORY) == state.blurRadiusDp) &&
            mChrome.ledger().lastManagedSource(SurfaceDirtyLedger.Backdrop.ACCESSORY) == usingManagedWallpaperSource &&
            mChrome.ledger().matchesLastRect(SurfaceDirtyLedger.Backdrop.ACCESSORY, backdropTargetRect) &&
            accessoryPictureUp(backdrop)) {
            // The frost filter follows Opacity live, and the even-out the wallpaper under the dock
            // now asks for (mid-drag the one last measured, re-measured on the release's pass);
            // the same filter instance when neither moved, which re-dresses nothing.
            backdrop.setColorFilter(hostFrostFilter(surfaceHost, true));
            // DIAG(dock-filter): the frost a pass at rest puts up, on change; revert before merge.
            if (MotionLog.enabled && !mCrossing.crossing()) {
                String d = matrixDiag(com.termux.app.chrome.GlassFilters.matrixOf(
                    backdrop.getColorFilter())) + " look=" + stackLookPage();
                if (!d.equals(mDiagDockFilter)) {
                    mDiagDockFilter = d;
                    MotionLog.log("dock-filter", "rest " + d);
                }
            }
            backdrop.setVisibility(View.VISIBLE);
            if (beadsMoved) rebuildBackdropGlassEffectForLens();
            mDock.syncDockShelf(state);
            return;
        }
        Bitmap frame = mChrome.blurCache().obtain(state.blurRadiusDp, wallpaperFrame);
        Rect frameRect = mChrome.blurCache().frameRectRef();
        if (frame == null) {
            if ((installed != null && installed.frameRect().equals(frameRect))
                || (mLiveBlur && accessoryPictureUp(backdrop))) {
                // A blur in flight: the frame already up still describes this screen, and it is
                // sampled where the view is now, so a moved dock shows the right wallpaper. A live
                // picture needs no frame at all.
                backdrop.invalidate();
                backdrop.setVisibility(View.VISIBLE);
            } else {
                // Nothing that describes this screen. A subsequent recovery pass can restore blur;
                // this frame keeps the tint layer without stale wallpaper brightness.
                backdrop.setImageDrawable(null);
                backdrop.setVisibility(View.GONE);
                mChrome.ink().noteBandFrame(com.termux.app.chrome.GlassBackdropCache.Band.DOCK,
                    false);
                mChrome.ledger().markDirty(SurfaceDirtyLedger.Backdrop.ACCESSORY);
                mDock.setDockProgramEdge(false);
            }
            return;
        }

        installAccessoryBackdropFrame(backdrop, installed, frame, frameRect, state.blurRadiusDp);
        mDockGlassCover = dockCover;
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S) {
            // The capsule sits inside the (horizontally overscanned) backdrop bitmap: left/right are
            // inset by the overscan, top/bottom span the full height. Hand that rect to the shader so
            // refraction happens at the real dock edge.
            float capLeft = horizontalOverscanPx;
            boolean capsuleDock = mDock.hostFloats();
            float radiusPx = capsuleDock
                ? mDock.resolveDockCapsuleCornerRadiusPx(surfaceHost.getHeight())
                : 0f;
            // The edge rule is the model's: Docked, the dock's sides, its bottom and its joins
            // are seams and the rim rect is pushed past them; only the edge facing the opening
            // keeps the rim and the bend. The capsule is unchanged.
            // Apart under Docked (#304) the host is Home's card: its seams are Home's cut's.
            com.termux.app.place.RestCards.Card homeDock = mSideCards.homeDockCard();
            int dockSeams = capsuleDock ? 0 : homeDock != null
                ? com.termux.app.chrome.ChromeEdgeRule.ALL
                    & ~com.termux.app.dock.TerminalHostDress.rimEdges(homeDock)
                : com.termux.app.chrome.LiveChromeShape.seamEdges(
                chromeShape(), dockPieceIds(shouldUseUnifiedDefaultKeyboardGlassSurface(state)));
            float[] capRect = new float[4];
            com.termux.app.dock.CapsuleGlass.capRect(capRect, horizontalOverscanPx,
                surfaceHost.getWidth(), surfaceHost.getHeight(), seamOverscanPx,
                com.termux.app.chrome.GlassRefraction.seamReachPx(
                    com.termux.app.chrome.GlassStack.lookFor(mFancierGlassLook),
                    getResources().getDisplayMetrics().density, radiusPx),
                dockSeams);
            // Where the host's origin sits in the backdrop, before the build: the icon reflection
            // is aimed by it.
            mGlassOriginLeft = capLeft;
            mGlassOriginTop = 0f;
            // Remembers the dock params so a key-press lens can rebuild this effect cheaply (no recapture).
            RenderEffect glass = mGlassEffects.buildDockAndRemember(0f, capRect[0], capRect[1],
                capRect[2], capRect[3], radiusPx);
            backdrop.setRenderEffect(glass);
        }
        // Content-aware light scatter — the frost that makes the blur read as glass, not plastic —
        // with the dock band's even-out ahead of it (ADR 0014).
        backdrop.setColorFilter(hostFrostFilter(surfaceHost, false));
        backdrop.setVisibility(View.VISIBLE);
        // Below Android 13 there is no effect to install, and the dock keeps its rim.
        mDock.setDockProgramEdge(mGlassEffects.paramsValid());
        mDock.syncDockShelf(state);
        mChrome.ledger().recordApplied(SurfaceDirtyLedger.Backdrop.ACCESSORY, state.blurRadiusDp,
            usingManagedWallpaperSource, backdropTargetRect);
        // The keyboard-local cover is deliberately retained until this expanded surface is ready.
        // Remove it now so dock and keyboard switch atomically to the unified material — unless
        // the keyboard is mid-way between materials, when its own pass owns what it wears.
        if (mKeyboardTravelSolidness == KeyboardMaterialPolicy.NO_TRAVEL
            && isUnifiedAccessoryBackdropReady(state)) {
            View keyboardSurfaceHost = findViewById(R.id.inapp_keyboard_view_host);
            if (keyboardSurfaceHost != null) {
                setKeyboardHostBackground(keyboardSurfaceHost, null);
            }
            clearInAppKeyboardBackdrop();
        }
    }

    /**
     * Points the dock's backdrop at {@code frame}, on the settle curve rather than outright when
     * the cache says this radius's frame arrived to replace one a wallpaper change displaced — see
     * {@link com.termux.app.chrome.WallpaperBlurCache#isCrossfadedRadius}. A rotation or a radius
     * change never sets that flag, so those keep landing the way they always have. The drawable
     * samples the frame at the view's laid-out position plus the stack's own travel, so the dock
     * shows the wallpaper it is over while it slides between two places' states and rides the
     * plank's press exactly as it always has.
     */
    private void installAccessoryBackdropFrame(@NonNull ImageView backdrop,
                                               @Nullable com.termux.app.chrome.SharedFrameDrawable installed,
                                               @NonNull Bitmap frame, @NonNull Rect frameRect,
                                               int blurRadiusDp) {
        android.graphics.drawable.Drawable live = liveDockPicture(backdrop, blurRadiusDp);
        // The page's ground over the dock's picture, stored or Live (#283). A Live picture does
        // not carry the strip's dim: on pong (round 2) the dock and the keyboard rows it holds
        // kept Home's luma over a Terminal dimmed 50 while their ground was left to it.
        syncDockGround(backdrop, false);
        installBackdropPicture(backdrop, installed, frame, frameRect, blurRadiusDp, live);
    }

    /**
     * Where a capsule's glass samples the wallpaper: where the stack's scene draws the card it
     * dresses (ADR 0032 section 5), its laid-out place moved by the stack's travel and the card's
     * pose ({@link StackRenderer#cardDrawnX}), never a layout the crossing will change. The
     * plank's press stays out, as it always has.
     */
    @NonNull
    private com.termux.app.chrome.GlassAnchor.Origin stackCardAnchor(@NonNull View backdrop) {
        int id = backdrop.getId();
        com.termux.app.place.RestCards.StackView own =
            com.termux.app.dock.KeysCardDress.stackViewOf(id);
        if (own == null) own = com.termux.app.dock.TerminalHostDress.stackViewOf(id);
        final com.termux.app.place.RestCards.StackView card =
            own != null ? own : com.termux.app.place.RestCards.StackView.HOST;
        return com.termux.app.chrome.GlassAnchor.layout(backdrop,
            () -> mAccessoryStackLift.px() + mStackRenderer.cardDrawnY(card),
            () -> mStackRenderer.cardDrawnX(card));
    }

    /**
     * Points a capsule's {@code backdrop} at its live picture, or at the stored frame when it has
     * none; the dock's, the extra-keys card's and the Terminal's host's backdrops are installed
     * here.
     */
    private void installBackdropPicture(@NonNull ImageView backdrop,
                                        @Nullable com.termux.app.chrome.SharedFrameDrawable installed,
                                        @NonNull Bitmap frame, @NonNull Rect frameRect,
                                        int blurRadiusDp,
                                        @Nullable android.graphics.drawable.Drawable live) {
        if (live != null) {
            // Live blur: the picture records what is beneath the dock; it is aimed by the recording.
            if (backdrop.getDrawable() != live) backdrop.setImageDrawable(live);
        } else if (installed != null) {
            boolean crossfade = installed.frame() != frame
                && mChrome.blurCache().isCrossfadedRadius(blurRadiusDp)
                && !ReducedMotion.isEnabled(this);
            installed.setFrame(frame, frameRect, crossfade);
        } else {
            backdrop.setImageDrawable(new com.termux.app.chrome.StoredPicture(frame, frameRect,
                mWallpaperParallax, stackCardAnchor(backdrop)).drawable());
        }
        // The surface moved or the geometry changed, or this would not have run: re-aim now, since
        // a view whose ancestor moved is not redrawn on its own.
        backdrop.invalidate();
    }

    /**
     * The host's frost for this pass. Apart, the host is Home's card at every rest and across
     * every crossing, so its even-out is Home's rest's own, measured under Home's rest rect over
     * Home's ground ({@link #restFrostFilter}), whether the host is parked left of the screen or
     * not; the dock band's one live memo follows the card in front (the host while Home is in
     * front, so the row's inks read it; the Terminal's card otherwise). A Frost drag keeps the
     * live path. Together, not apart: the host measures under itself as it always has.
     */
    @Nullable
    private android.graphics.ColorFilter hostFrostFilter(@NonNull View surfaceHost,
                                                         boolean dragAware) {
        com.termux.app.place.RestCards.HostLook look = mSideCards.hostLook();
        boolean liveFront = !mStackRenderer.terminalCardStands() && !mCrossing.crossing();
        boolean drag = dragAware && mGlassDragPreview;
        if (look == null || drag) {
            return dockFrostFilter(drag || mStackRenderer.terminalCardStands() ? null
                : surfaceHost);
        }
        // Home in front at rest: the live memo is measured (the row's inks stand on it); the
        // frost put up is Home's rest's, the same one the parked host wore.
        android.graphics.ColorFilter live = liveFront ? dockFrostFilter(surfaceHost) : null;
        android.graphics.ColorFilter rest = restFrostFilter(mHostRestFrost,
            com.termux.app.wall.PageRef.HOME, mSideCards.hostRestRect());
        if (rest != null) return rest;
        return liveFront ? live : dockFrostFilter(null);
    }

    /** One card's frost at its own rest, with what it was measured from. */
    private static final class RestFrost {
        @Nullable android.graphics.ColorFilter filter;
        final Rect rect = new Rect();
        int look = com.termux.app.place.TopBandFadePlan.NONE;
        int ground;
        int frames;
        int dress;
    }

    @NonNull private final RestFrost mHostRestFrost = new RestFrost();
    @NonNull private final RestFrost mCardRestFrost = new RestFrost();

    /**
     * The dock band's frost as {@code page}'s card wears it at its own rest ({@code rest}, screen
     * px, from the rest answer): the even-out measured under that rect over {@code page}'s
     * ground, never under a view's position on screen, so a card parked off screen is measured
     * where it will stand. Kept per card by its inputs, so a pass that moved none of them
     * measures nothing; it touches no memo the live band keeps. Null when nothing can be read.
     */
    @Nullable
    private android.graphics.ColorFilter restFrostFilter(@NonNull RestFrost slot,
            @NonNull com.termux.app.wall.PageRef page,
            @Nullable com.termux.app.place.ChromeShape.Box rest) {
        if (mChrome == null || rest == null) return null;
        int lookId = lookIdOf(page);
        updateEvenOutPolicy();
        int ground = groundOfWallPage(page.kind);
        int frames = mChrome.ink().framesGeneration();
        int dress = dockFilterDress(lookId);
        mDockEvenOutRect.set(Math.round(rest.left), Math.round(rest.top), Math.round(rest.right),
            Math.round(rest.bottom));
        if (slot.filter != null && slot.look == lookId && slot.ground == ground
            && slot.frames == frames && slot.dress == dress && slot.rect.equals(mDockEvenOutRect))
            return slot.filter;
        android.graphics.ColorFilter frost = com.termux.app.chrome.GlassFilters.frost(
            mPreferences != null ? mPreferences.getAppBarOpacity(lookId) : 100);
        android.graphics.ColorMatrix evenOut = mChrome.ink().bandEvenOutMatrixOver(
            com.termux.app.chrome.GlassBackdropCache.Band.DOCK, mDockEvenOutRect, ground);
        // A band that evens out and read nothing: the frost alone would be a wrong one.
        if (evenOut == null && mChrome.ink().hasBandEvenOut(
                com.termux.app.chrome.GlassBackdropCache.Band.DOCK)) return null;
        slot.filter = com.termux.app.chrome.GlassFilters.withEvenOut(evenOut, frost);
        slot.rect.set(mDockEvenOutRect);
        slot.look = lookId;
        slot.ground = ground;
        slot.frames = frames;
        slot.dress = dress;
        return slot.filter;
    }

    /** Prototype #283: the ground drawn in the dock backdrop's overlay; null until first needed. */
    @Nullable private com.termux.app.chrome.GroundUnderGlass mDockGround;

    /**
     * Prototype #283 ({@link com.termux.app.chrome.GlassGround}): the dock's backdrop wears the
     * page's ground in its overlay, over its frost filter's output and under its refraction, and
     * rides the strip so a seam crossing beneath redraws it. {@code carried}: its picture is Live
     * and holds the strip already.
     */
    private void syncDockGround(@NonNull ImageView backdrop, boolean carried) {
        mDockGround = syncGround(mDockGround, backdrop, "dock-keyboard", carried);
    }

    /** {@link #syncDockGround} for any capsule backdrop: its overlay made once, held by the caller. */
    @Nullable
    private com.termux.app.chrome.GroundUnderGlass syncGround(
            @Nullable com.termux.app.chrome.GroundUnderGlass held, @NonNull ImageView backdrop,
            @NonNull String name, boolean carried) {
        if (!com.termux.app.chrome.GlassGround.ON) return held;
        if (held == null) {
            com.termux.app.chrome.GroundUnderGlass ground =
                new com.termux.app.chrome.GroundUnderGlass(backdrop, name);
            held = ground;
            backdrop.getOverlay().add(ground);
            ground.setBounds(0, 0, backdrop.getWidth(), backdrop.getHeight());
            backdrop.addOnLayoutChangeListener((v, l, t, r, b, ol, ot, or, ob) ->
                ground.setBounds(0, 0, r - l, b - t));
            ground.attach();
        }
        held.setCarried(carried);
        return held;
    }

    @Nullable
    private Rect buildToolbarOnlyAccessoryBounds(@NonNull ChromeSpec state) {
        if (!state.toolbarShown)
            return null;
        View accessoryContainer = findViewById(R.id.accessory_stack_container);
        if (accessoryContainer == null)
            return null;
        ViewGroup.LayoutParams params = accessoryContainer.getLayoutParams();
        int totalHeight = params != null && params.height > 0
            ? params.height : accessoryContainer.getHeight();
        int toolbarHeight = Math.max(0, totalHeight - inAppKeyboardKeysPx(state.keyboardHeight));
        if (toolbarHeight <= 0)
            return null;
        int width = accessoryContainer.getWidth();
        if (width <= 0)
            width = getResources().getDisplayMetrics().widthPixels;
        return new Rect(0, 0, Math.max(0, width), toolbarHeight);
    }

    private void applyChromeSpec(@NonNull ChromeSpec state) {
        Trace.beginSection("Chrome.applyChromeSpec");
        try {
            // Each block of the pass is its own trace section (Chrome.<block>), so a trace says
            // which of them a slow apply spent its time in.
            Trace.beginSection("Chrome.looks");
            followLooksGlassTheme();
            syncFancierGlassLook();
            syncFrameStandDown();
            Trace.endSection();
            doApplyChromeSpec(state);
            mRowsGuard.afterCommit();
            // The bar's ink is measured from the wallpaper under it, so it is re-asked on the same
            // pass that re-cuts the glass — a wallpaper, palette, mode or geometry change reaches
            // both through one request.
            Trace.beginSection("Chrome.statusBarInk");
            mStatusBar.syncStatusBarInk();
            Trace.endSection();
            if (mHomePill.isShown()) applyHomePillDress();
        } finally {
            Trace.endSection();
        }
    }

    private void doApplyChromeSpec(@NonNull ChromeSpec state) {
        View accessoryContainer = findViewById(R.id.accessory_stack_container);
        View extraKeysBackground = findViewById(R.id.extrakeys_background);
        Trace.beginSection("Chrome.bounds");
        // With bands under the keyboard the column the layers stand above is the keyboard and those
        // bands, so the layers' MATCH_PARENT above it is already exactly the dock's rows.
        Rect toolbarOnlyBounds = state.keyboardShown && !underKeyboardBandsShown()
            ? buildToolbarOnlyAccessoryBounds(state) : null;
        applyAccessorySurfaceBounds(state);
        applyAccessoryLayerVerticalBounds(R.id.apps_bar_az_fx_underlay, toolbarOnlyBounds);
        applyAccessoryLayerVerticalBounds(R.id.apps_bar_az_fx_overlay, toolbarOnlyBounds);
        boolean useRenderEffectBlur = shouldUseAccessoryRenderEffectBlur(state);
        applyAccessoryAmbientVeil(accessoryContainer, state);
        Trace.endSection();

        // Which of the dock's views show is Dock rows' answer, one for every chrome spec, the dock
        // up or not. Its subscribers (onDockRowsChanged: a drag on the pinned apps, their page
        // ticks, the icon reflection) hear a change before the views move, so a drag is cancelled
        // while its source is still on screen.
        Trace.beginSection("Chrome.dockRows");
        View laidOutKeyboard = findViewById(R.id.inapp_keyboard_container);
        mDockRows.setKeyboardLaidOut(keyboardStaysLaidOut() && laidOutKeyboard != null
            && laidOutKeyboard.getVisibility() != View.GONE);
        mDockRows.apply(state, mStatusBar.statusBarEdge() == PlaceLayout.Edge.BOTTOM,
            dockRowsUnion());
        Trace.endSection();
        if (state.toolbarShown && !state.appsRowEnabled) {
            mSuggestionBarExplicitSearchActive = false;
            // The letters keep their scrub without the apps row — it just shows its matches on the
            // floating strip instead — so only drop the gesture when the letters are gone too.
            // Standing on another edge is not gone: the row here is empty, the bar is elsewhere.
            if (!isAzIndexEnabled()) {
                resetAzGestureState(true);
            }
        }
        if (!state.toolbarShown) {
            clearAccessoryRenderEffectBackdrop();
            // Nothing lands on the dock, but the letters may still be standing on another edge.
            Trace.beginSection("Chrome.offDock");
            syncAzBarHosts();
            syncOffDockPlank(arrangement().layout());
            refreshOffDockGlass();
            Trace.endSection();
            // The extra keys or the letters standing on another edge, with nothing left on the
            // dock, still take their ink from the face under them (the plank wears the dock's
            // glass), not from the theme they were built in.
            Trace.beginSection("Chrome.dockInks");
            syncDockGlassInks(state.barAlpha);
            Trace.endSection();
            Trace.beginSection("Chrome.keyboardSurface");
            applyInAppKeyboardSurfaceState(state);
            Trace.endSection();
            configureAccessoryTopEdgeFx(false, state.barAlpha);
            mKeysCardDress.release();
            mTerminalHostDress.release();
            mFootDress.release();
            resetAzOverflowAffordanceState();
            if (mDock.dockPlankController() != null) {
                mDock.dockPlankController().setEnabled(false);
            }
            mChrome.requestSync(ChromeRenderer.SCOPE_TOP_PANE_FROST);
            return;
        }

        Trace.beginSection("Chrome.dockSheet");
        if (extraKeysBackground != null) {
            // The dock renders the full light model, foot included.
            // Under a joined Docked frame the frame's glass is this sheet, but where the row's
            // beads cut the frame (the host clips this sheet to them).
            extraKeysBackground.setBackground(dockSheetStandsDownOnFrame() ? null
                : deckSlabOr(mChrome.glass().dockSurface(state.barAlpha,
                    0f, 1f, false)));
            // Opacity is baked into the drawable (translucent base) so the glass light model survives.
            extraKeysBackground.setAlpha(1f);
        }
        mDock.refreshDockPlankFx(state.barAlpha);
        Trace.endSection();
        // A bar off the dock is not in this stack and never rides its plank; it wears the same
        // glass, so it is re-glazed on the same pass that re-glazes the dock.
        Trace.beginSection("Chrome.offDock");
        syncAzBarHosts();
        syncOffDockPlank(arrangement().layout());
        refreshOffDockGlass();
        Trace.endSection();
        Trace.beginSection("Chrome.dockInks");
        syncDockGlassInks(state.barAlpha);
        Trace.endSection();

        Trace.beginSection("Chrome.topEdgeFx");
        configureAccessoryTopEdgeFx(true, state.barAlpha);
        Trace.endSection();
        Trace.beginSection("Chrome.keyboardSurface");
        applyInAppKeyboardSurfaceState(state);
        Trace.endSection();
        // Wallpaper passthrough feeds every glass surface from the shared pre-blurred wallpaper, so
        // the live blur views have nothing left to contribute — and each one that keeps capturing
        // redraws the whole window, terminal text included, on the UI thread.
        Trace.beginSection("Chrome.renderEffectBackdrop");
        updateAccessoryRenderEffectBackdrop(state);
        mKeysCardDress.update(state);
        mTerminalHostDress.update(state);
        // After both hosts: the foot wears the frost of the one that stands.
        mFootDress.update(state);
        // Apart under Docked the unified surface is the Terminal's own host (#304): the keyboard's
        // own coat comes off once that host's crop is up, as it does for the one host.
        if (mSideCards.terminalHostOn()
            && mKeyboardTravelSolidness == KeyboardMaterialPolicy.NO_TRAVEL
            && isUnifiedAccessoryBackdropReady(state)) {
            View keyboardSurfaceHost = findViewById(R.id.inapp_keyboard_view_host);
            if (keyboardSurfaceHost != null) setKeyboardHostBackground(keyboardSurfaceHost, null);
            clearInAppKeyboardBackdrop();
        }
        Trace.endSection();
        mChrome.requestSync(ChromeRenderer.SCOPE_TOP_PANE_FROST);
        updateAzOverflowAffordance();
        // The keyboard going up or down, or the dock lifting, does not always lay the dock host out
        // again, yet it decides whether the Peek card may stand: read it again before the next draw.
        if (mPeekWatchedHost != null) schedulePeekRefresh();
        // The stack's transforms for this rest: written only where they differ from the last.
        mStackRenderer.applyAtRest();
    }

    /**
     * The one owner of when the chrome geometry pass runs and of the panes' grid pause around it.
     * Keyboard, insets, layout echoes, font metrics, slides, divider drags and the status fold all
     * ask here; see {@link GeometryScheduler}. Disposed in {@link #onDestroy}.
     */
    private final GeometryHost mGeometryHost = new GeometryHost(this);
    private final GeometryScheduler mGeometry = new GeometryScheduler(mGeometryHost);

    /**
     * The scheduler's window side. Static, and weak to the activity and to what it holds paused:
     * the scheduler's callbacks sit on the process-wide main looper (the hold's fail-safe is 500 ms
     * out), and a message still queued there must not keep a destroyed activity — its whole view
     * tree with it — reachable. {@link #onDestroy} withdraws them as well.
     */
    private static final class GeometryHost implements GeometryScheduler.Host {

        @NonNull private final java.lang.ref.WeakReference<TermuxActivity> mActivity;
        /** Where the scheduler posts: the main looper, frame work ahead of booked traversals. */
        private final Handler mHandler = new Handler(Looper.getMainLooper());
        /** The pane controller whose grid this scheduler paused, so the resume reaches it. */
        @Nullable private java.lang.ref.WeakReference<
            com.termux.app.terminal.TerminalPaneController> mHeldPanes;
        @Nullable private java.lang.ref.WeakReference<com.termux.app.x11.X11PaneFrame> mHeldDisplay;

        GeometryHost(@NonNull TermuxActivity activity) {
            mActivity = new java.lang.ref.WeakReference<>(activity);
        }

        /** The pass the scheduler booked, waiting for the frame table's GEOMETRY step. */
        @Nullable private Runnable mBookedFrame;

        @Override public void postFrame(@NonNull Runnable frame) {
            // A step of the frame table, before the frame's layout: the pass's writes reach the
            // traversal that frame books instead of booking the next one.
            TermuxActivity activity = mActivity.get();
            if (activity == null) return;
            mBookedFrame = frame;
            activity.mFrames.requestFrame(com.termux.app.window.FrameStep.GEOMETRY);
        }

        /** The GEOMETRY step: runs the booked pass, once. */
        void runBookedFrame() {
            Runnable frame = mBookedFrame;
            mBookedFrame = null;
            if (frame != null) frame.run();
        }

        @Override public void postAfterLayout(@NonNull Runnable afterLayout) {
            // Ordinary: a booked traversal's barrier holds it until that layout has run.
            mHandler.post(afterLayout);
        }

        @Override public void postDelayed(@NonNull Runnable runnable, long delayMs) {
            mHandler.postDelayed(runnable, delayMs);
        }

        @Override public void removeCallbacks(@NonNull Runnable runnable) {
            if (mBookedFrame == runnable) mBookedFrame = null;
            mHandler.removeCallbacks(runnable);
        }

        @Override public void runPass(@NonNull GeometryScheduler.Reason reason) {
            TermuxActivity activity = mActivity.get();
            if (activity != null) activity.runAccessoryGeometryPass(reason);
        }

        @Override public void beginGridHold() {
            TermuxActivity activity = mActivity.get();
            com.termux.app.terminal.TerminalPaneController panes =
                activity == null ? null : activity.mPaneController;
            mHeldPanes = panes == null ? null : new java.lang.ref.WeakReference<>(panes);
            if (panes != null) panes.beginHostSurfaceResize();
        }

        @Override public void finishGridHold() {
            com.termux.app.terminal.TerminalPaneController panes =
                mHeldPanes == null ? null : mHeldPanes.get();
            mHeldPanes = null;
            if (panes != null) panes.finishHostSurfaceResizeKeepingBottom();
        }

        @Override public void beginDisplayHold() {
            // The display window shares the wall's height: without this every frame of a fold would
            // resize the X screen, and the bar's motion would judder along with it.
            TermuxActivity activity = mActivity.get();
            com.termux.app.x11.X11PaneFrame display = activity == null
                || activity.mPaneWallController == null
                ? null : activity.mPaneWallController.displayWindow();
            mHeldDisplay = display == null ? null : new java.lang.ref.WeakReference<>(display);
            if (display != null) display.beginHostResize();
        }

        @Override public void finishDisplayHold() {
            com.termux.app.x11.X11PaneFrame display =
                mHeldDisplay == null ? null : mHeldDisplay.get();
            mHeldDisplay = null;
            if (display != null) display.finishHostResize();
        }

        @Override public long layoutInputsKey() {
            TermuxActivity activity = mActivity.get();
            return activity == null ? 0L : activity.geometryInputsKey();
        }

        @Override public boolean isAlive() {
            TermuxActivity activity = mActivity.get();
            return activity != null && !activity.isFinishing() && !activity.isDestroyed();
        }
    }

    /**
     * The in-app keyboard's geometry and its flash-free reveal choreography: the measurement memo,
     * the pending-reveal/pending-close protocol, the two pre-draw gates and the system-IME inset
     * gate. The Activity keeps the chrome <em>painters</em> — they are welded to the glass factory,
     * the backdrop bitmaps and the dock layout — and hands them to the module below.
     */
    private final KeyboardGeometryChoreographer mKeyboardGeometry =
        new KeyboardGeometryChoreographer(new KeyboardGeometryChoreographer.Surface() {

            @Nullable @Override public View findView(int viewId) {
                return findViewById(viewId);
            }

            @NonNull @Override public DisplayMetrics displayMetrics() {
                return getResources().getDisplayMetrics();
            }

            @Override public boolean dressKeyboardHost() {
                return dressInAppKeyboardHost();
            }

            @Nullable @Override public View attachedKeyboardView() {
                return mAttachedInAppKeyboardView;
            }

            @Nullable @Override
            public KeyboardGeometryChoreographer.HostReference floatingKeyboardReference() {
                return mFloatingKeyboard == null ? null : mFloatingKeyboard.reference();
            }

            @NonNull @Override public ChromeSpec buildChromeSpec() {
                return TermuxActivity.this.buildChromeSpec();
            }

            @Override public void applyKeyboardSurfaceState(@NonNull ChromeSpec spec) {
                applyInAppKeyboardSurfaceState(spec);
            }

            @Override public void requestAccessoryRenderSync() {
                mChrome.requestSync(ChromeRenderer.SCOPE_ACCESSORY_RENDER);
            }

            @Override public void requestApplyThisFrame() {
                mChrome.requestSync(ChromeRenderer.SCOPE_APPLY_THIS_FRAME);
            }

            @Override public void applyAccessoryGeometry(@NonNull String reason) {
                // Now, not at the end of the dispatch: the reveal gate armed by this show applies
                // against the very next traversal, which must already have the stack's new height.
                mGeometry.requestNow(GeometryScheduler.Reason.KEYBOARD,
                    GeometryScheduler.ResizePolicy.NOW);
            }

            @Override public boolean keyboardStaysLaidOut() {
                return TermuxActivity.this.keyboardStaysLaidOut();
            }

            @Override public void requestStackRest() {
                mStackRenderer.applyAtRest();
            }

            @Override public void invalidateTransitionCrops() {
                // Geometry-dependent crops only; the shared full-frame blur is preserved.
                mChrome.ledger().markDirty(SurfaceDirtyLedger.Backdrop.IN_APP_KEYBOARD);
                mChrome.ledger().invalidateRect(SurfaceDirtyLedger.Backdrop.IN_APP_KEYBOARD);
                mChrome.ledger().markDirty(SurfaceDirtyLedger.Backdrop.ACCESSORY);
                mChrome.ledger().invalidateRect(SurfaceDirtyLedger.Backdrop.ACCESSORY);
            }

            @Override public void onKeyboardClosed() {
                mKeybindHintPresenter.hideAfterLinger();
            }

            @Override public void requestApplyInsets() {
                View content = findViewById(android.R.id.content);
                if (content != null)
                    ViewCompat.requestApplyInsets(content);
            }

            @Override public void postDelayed(@NonNull Runnable runnable, long delayMs) {
                mAccessoryRenderHandler.postDelayed(runnable, delayMs);
            }

            @Override public void removeCallbacks(@NonNull Runnable runnable) {
                mAccessoryRenderHandler.removeCallbacks(runnable);
            }

            @Override public boolean isActivityAlive() {
                return !isFinishing() && !isDestroyed();
            }
        });

    private boolean shouldUseWallpaperPassthroughMode() {
        return mPreferences != null
            && mPreferences.isUseSystemWallpaperEnabled();
    }

    private void syncTerminalWallpaperRenderingMode() {
        if (mTerminalView == null) {
            return;
        }
        mTerminalView.setUseTransparentFrameClear(false);
    }

    private boolean shouldEnableSeamlessStatusBackground() {
        return mProperties != null
            && !mProperties.isUsingFullScreen();
    }

    private boolean shouldShowTerminalStatusBarSurface(boolean showSurface, int terminalSurfaceColor) {
        return shouldEnableSeamlessStatusBackground()
            && showSurface
            && Color.alpha(terminalSurfaceColor) > 0
            && mLastStatusBarInsetTop > 0;
    }

    private void applyTerminalOverlayInsets(@NonNull WindowInsetsCompat insetsCompat) {
        int statusBarInsetTop = insetsCompat.getInsets(Type.statusBars()).top;
        mLastStatusBarInsetTop = statusBarInsetTop;
        // The frame glass follows the inset it reaches under, on the pass that changes it.
        View frameGlass = findViewById(R.id.docked_frame_glass);
        if (frameGlass != null && mFrameGutterShown) growFrameGlassUnderSystemBars(frameGlass);

        View statusBarSurface = findViewById(R.id.terminal_status_bar_background);
        if (statusBarSurface != null) {
            ViewGroup.LayoutParams layoutParams = statusBarSurface.getLayoutParams();
            if (layoutParams != null && layoutParams.height != statusBarInsetTop) {
                layoutParams.height = statusBarInsetTop;
                statusBarSurface.setLayoutParams(layoutParams);
            }
        }
        applyDeckBands();

        // Keep content out of the camera hole now that the window draws under the cutout. Only the
        // horizontal insets reach the content root: the top cutout is already covered by the
        // status-bar inset, and what stands along the top and the bottom takes its slice of the
        // content column's height structurally rather than as padding.
        androidx.core.graphics.Insets cutoutInsets = insetsCompat.getInsets(Type.displayCutout());
        mLastDisplayCutoutInsetLeft = cutoutInsets.left;
        mLastDisplayCutoutInsetRight = cutoutInsets.right;
        syncStatusRowKeepOut(insetsCompat);
        syncExtraKeysHost();
        syncPinnedAppsHost();
        syncAzBarHosts();
        syncOffDockPlank(arrangement().layout());
        // The arithmetic below counts the bands on each edge, so the bars stand in their stacks
        // first: the answer and the screen can never disagree, not even on the frame before the
        // first arrangement pass.
        applyEdgeStacksAndInvalidate(arrangement().layout());
        // One answer for all four edges: what stands on each of them, summed, rather than a chain
        // of max() in which every column carried the reach of every column outside it.
        PlaceLayout placeLayout = arrangement().layout();
        EdgeStackPolicy.Metrics metrics = buildEdgeStackMetrics();
        EdgeStackPolicy.Insets content = EdgeStackPolicy.contentInsets(placeLayout, metrics);
        // The side stacks stand inside the canvas band now, so the bands they hold are an inset on
        // the canvas structurally and nobody pads for them. What is left of the horizontal answer
        // is the display cutout, and that the root keeps: the camera hole is the window's, not the
        // place's, so every bar on every edge clears it in one place rather than four.
        int cutoutLeft = content.left
            - EdgeStackPolicy.stackThicknessPx(placeLayout, PlaceLayout.Edge.LEFT, metrics);
        int cutoutRight = content.right
            - EdgeStackPolicy.stackThicknessPx(placeLayout, PlaceLayout.Edge.RIGHT, metrics);
        View rootRelativeLayout = findViewById(R.id.activity_termux_root_relative_layout);
        if (rootRelativeLayout != null
            && (rootRelativeLayout.getPaddingLeft() != cutoutLeft
                || rootRelativeLayout.getPaddingRight() != cutoutRight)) {
            rootRelativeLayout.setPadding(cutoutLeft, rootRelativeLayout.getPaddingTop(),
                cutoutRight, rootRelativeLayout.getPaddingBottom());
            // The dock's rows span the root between these, so a slot's share of them moved.
            updateAppLauncherBarHeight();
        }

        applyTerminalSurfaceAppearance();
    }

    /**
     * Hands the status row what the screen takes from it (#163): the camera's box on the top edge,
     * the screen's corner radii and the user's cutout choice. The row works out from where it
     * stands whether the camera shares its band and how far its ends step in
     * ({@link com.termux.app.statusbar.StatusRowKeepOut}); these insets are the window's, since
     * the content view they arrive on starts at the window's origin.
     */
    /** The screen's corner radii, top-left, top-right, bottom-left, bottom-right; 0 unknown. */
    @NonNull private float[] mDisplayCornerRadiiPx = new float[4];

    /** The cutout {@link #mTopCutoutShape} was read from, and what it was; see {@link #topCutoutShape}. */
    @Nullable private androidx.core.view.DisplayCutoutCompat mTopCutoutShapeSource;
    @Nullable private Rect mTopCutoutShape;
    private boolean mTopCutoutShapeRead;

    /**
     * The camera's shape on the top edge in window pixels, or null with none: Android's bounding
     * rects that touch the edge, joined (a side cutout in landscape stands off the top edge, so
     * it is never one); on API 31+ narrowed to the bounds of the cutout's own path, which traces
     * a punch hole's circle inside its rect. Read once per cutout and kept: never per inset
     * dispatch. The returned rect is the cache's own; callers copy what they keep.
     */
    @Nullable
    private Rect topCutoutShape(@Nullable androidx.core.view.DisplayCutoutCompat cutout,
                                @NonNull WindowInsetsCompat insetsCompat) {
        if (mTopCutoutShapeRead && java.util.Objects.equals(cutout, mTopCutoutShapeSource)) {
            return mTopCutoutShape;
        }
        Rect hole = com.termux.app.chrome.CutoutShape.top(cutout, insetsCompat);
        mTopCutoutShapeSource = cutout;
        mTopCutoutShape = hole;
        mTopCutoutShapeRead = true;
        return hole;
    }

    /** The camera's keep-out box in window px while Full screen has one; null otherwise. */
    @Nullable private int[] mCameraBox;
    /** {@link #syncBarSplit}'s scratch: the margins it wants (main left/right, second left/right), and the host's origin. */
    private final int[] mBarSplitWant = new int[4];
    private final int[] mBarSplitOrigin = new int[2];
    private final int[] mBarSplitScratch = new int[2];

    /**
     * Splits the Floating status bar round the camera: the host's glass becomes two convex cards
     * with the hole between them ({@link com.termux.app.chrome.CameraHoleGeometry}). The main card
     * keeps the host's own glass views and takes the wider side; the second card is the side
     * views'; with one side too narrow the main card is trimmed to the hole's far edge. The split
     * is a function of the bar's rest rect and the box, so it needs one answer per layout and is
     * laid only when it changed (margins and visibility compared before they are set). Docked
     * bars, bars below the camera's band and bars on a side or bottom edge answer NONE.
     */
    private void syncBarSplit() {
        View host = findViewById(R.id.terminal_window_bar_host);
        View main = findViewById(R.id.terminal_window_bar_background);
        View side = findViewById(R.id.terminal_window_bar_background_side);
        if (host == null || main == null || side == null) return;
        int[] want = mBarSplitWant;
        java.util.Arrays.fill(want, 0);
        boolean sideWanted = false;
        com.termux.app.chrome.CameraHoleGeometry.Split split =
            com.termux.app.chrome.CameraHoleGeometry.Split.NONE;
        int[] box = mCameraBox;
        if (box != null && host.getVisibility() == View.VISIBLE && host.getWidth() > 0
            && host.getHeight() > 0 && !mStatusBar.isStatusBarVertical() && mChrome != null
            && isRoundedStyle(com.termux.app.place.SeamDress.Surface.STATUS)
            && !frameStandsDown()) {
            int[] origin = mBarSplitOrigin;
            com.termux.app.chrome.GlassAnchor.layoutOriginOnScreen(host, origin, mBarSplitScratch);
            int left = origin[0];
            int top = origin[1];
            int right = left + host.getWidth();
            float radius = mStatusBar.resolveStatusBarCapsuleCornerRadiusPx(host.getHeight());
            split = com.termux.app.chrome.CameraHoleGeometry.split(box, left, top, right,
                top + host.getHeight(), com.termux.app.chrome.CameraHoleGeometry.minSidePx(radius,
                    getResources().getDisplayMetrics().density));
            sideWanted = com.termux.app.chrome.CameraHoleGeometry.barCardMargins(split, left,
                right, want);
        }
        int mainLeft = want[com.termux.app.chrome.CameraHoleGeometry.MAIN_LEFT];
        int mainRight = want[com.termux.app.chrome.CameraHoleGeometry.MAIN_RIGHT];
        int sideLeft = want[com.termux.app.chrome.CameraHoleGeometry.SIDE_LEFT];
        int sideRight = want[com.termux.app.chrome.CameraHoleGeometry.SIDE_RIGHT];
        // Each card's view draws its wallpaper frost under its tint and rim, so one set of
        // margins places both.
        boolean changed = false;
        changed |= setBarCardMargins(main, mainLeft, mainRight);
        changed |= setBarCardMargins(side, sideLeft, sideRight);
        if (side.getVisibility() == View.VISIBLE != sideWanted) {
            side.setVisibility(sideWanted ? View.VISIBLE : View.GONE);
            changed = true;
        }
        // A split card ends at the camera inside the host, where the host's outline does not
        // round it: each layer clips to the card's own rounded rect, inner ends included.
        boolean cut = sideWanted || mainLeft != 0 || mainRight != 0;
        clipBarCardLayer(main, cut);
        clipBarCardLayer(side, cut);
        // The slot (clock, pinned cards, media) stands in the main card only.
        View slot = findViewById(R.id.terminal_top_widget_area);
        if (slot != null) changed |= setBarCardMargins(slot, mainLeft, mainRight);
        if (!changed) return;
        // The cards' dress and frost follow the new rects, once, after this layout.
        host.post(() -> {
            View current = findViewById(R.id.terminal_window_bar_host);
            if (current == null || mChrome == null) return;
            dressBarSideCard(current);
            mChrome.requestSync(ChromeRenderer.SCOPE_TOP_PANE_FROST);
        });
    }

    /** The second card's glass: the main card's own dress, built for the bar as it stands now. */
    private void dressBarSideCard(@NonNull View host) {
        // A re-dress may carry a new Corners: the cards' clips take it.
        for (int id : BAR_CARD_LAYERS) {
            View layer = findViewById(id);
            if (layer != null && layer.getOutlineProvider() == mBarCardOutline)
                layer.invalidateOutline();
        }
        View side = findViewById(R.id.terminal_window_bar_background_side);
        if (side == null || side.getVisibility() != View.VISIBLE) return;
        side.setBackground(buildTerminalWindowBarBackground(host));
        applyWindowBarDeckSlab();
    }

    /** The layers that draw the split bar's two cards: each card's frost, tint and rim. */
    private static final int[] BAR_CARD_LAYERS = {R.id.terminal_window_bar_background,
        R.id.terminal_window_bar_background_side};

    /**
     * A split bar card's own shape: its rect at the bar's radius for its height, so a card that
     * grows with the expanded bar keeps the radius the host's outline has.
     */
    private final android.view.ViewOutlineProvider mBarCardOutline =
        new android.view.ViewOutlineProvider() {
            @Override
            public void getOutline(View view, android.graphics.Outline outline) {
                int width = view.getWidth();
                int height = view.getHeight();
                if (width <= 0 || height <= 0) {
                    outline.setEmpty();
                    return;
                }
                outline.setRoundRect(0, 0, width, height,
                    mStatusBar.resolveStatusBarCapsuleCornerRadiusPx(height));
            }
        };

    /** Clips one layer of a bar card to the card's rounded rect, or lets it draw as laid out. */
    private void clipBarCardLayer(@Nullable View layer, boolean cut) {
        if (layer == null) return;
        android.view.ViewOutlineProvider provider = cut ? mBarCardOutline
            : android.view.ViewOutlineProvider.BACKGROUND;
        if (layer.getOutlineProvider() != provider) layer.setOutlineProvider(provider);
        if (layer.getClipToOutline() != cut) layer.setClipToOutline(cut);
    }

    /** Puts side margins on {@code card} unless they are already there; whether it moved. */
    private static boolean setBarCardMargins(@NonNull View card, int left, int right) {
        ViewGroup.LayoutParams params = card.getLayoutParams();
        if (!(params instanceof ViewGroup.MarginLayoutParams)) return false;
        ViewGroup.MarginLayoutParams margins = (ViewGroup.MarginLayoutParams) params;
        if (margins.leftMargin == left && margins.rightMargin == right) return false;
        margins.leftMargin = left;
        margins.rightMargin = right;
        card.setLayoutParams(margins);
        return true;
    }

    /** The window's width for the camera box: the decor's, else the display's. */
    private int windowWidthForCutout() {
        int width = getWindow().getDecorView().getWidth();
        return width > 0 ? width : getResources().getDisplayMetrics().widthPixels;
    }

    /**
     * Turns the first camera gap's centre and width into the nudges on Android's shape, once
     * (guarded by a stored flag): the same box within a pixel or two, no margin as before, so a
     * Custom gap an upgrade finds stays where the user put it. The old keys stay in place and are
     * never read again. Without a mode of Custom or a stored value there is nothing to turn.
     */
    private void migrateCutoutPreferences(@Nullable Rect shape, int windowWidthPx) {
        if (mPreferences == null || windowWidthPx <= 0 || mPreferences.isStatusBarCutoutMigrated())
            return;
        Integer centreDp = mPreferences.getLegacyStatusBarCutoutCenter();
        Integer widthDp = mPreferences.getLegacyStatusBarCutoutWidth();
        boolean custom = com.termux.app.statusbar.StatusRowKeepOut.Mode.fromPreference(
            mPreferences.getStatusBarCutoutMode())
            == com.termux.app.statusbar.StatusRowKeepOut.Mode.CUSTOM;
        if (custom || centreDp != null || widthDp != null) {
            float density = getResources().getDisplayMetrics().density;
            int centrePx = Math.round((centreDp == null ? 0 : centreDp) * density);
            int widthPx = Math.round((widthDp == null ? 32 : widthDp) * density);
            int baseWidth = shape != null ? shape.width()
                : Math.round(com.termux.app.chrome.CameraHoleGeometry.CUSTOM_BASE_DP * density);
            int baseCentre = shape != null ? (shape.left + shape.right) / 2 : windowWidthPx / 2;
            mPreferences.setStatusBarCutoutMargin(0);
            mPreferences.setStatusBarCutoutOffsetY(0);
            mPreferences.setStatusBarCutoutScale(
                com.termux.app.chrome.CameraHoleGeometry.migrateScalePct(widthPx, baseWidth));
            mPreferences.setStatusBarCutoutOffsetX(
                com.termux.app.chrome.CameraHoleGeometry.migrateOffsetXDp(
                    windowWidthPx / 2 + centrePx, baseCentre, density));
        }
        mPreferences.setStatusBarCutoutMigrated(true);
    }

    private void syncStatusRowKeepOut(@NonNull WindowInsetsCompat insetsCompat) {
        View row = findViewById(R.id.terminal_status_row);
        // The top edge's camera shape, kept per cutout: the insets arrive every frame of the IME's
        // animation, the cutout never changes under them.
        androidx.core.view.DisplayCutoutCompat cutout = insetsCompat.getDisplayCutout();
        Rect hole = topCutoutShape(cutout, insetsCompat);
        float[] radii = new float[4];
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S) {
            android.view.WindowInsets platform = insetsCompat.toWindowInsets();
            if (platform != null) {
                int[] positions = {android.view.RoundedCorner.POSITION_TOP_LEFT,
                    android.view.RoundedCorner.POSITION_TOP_RIGHT,
                    android.view.RoundedCorner.POSITION_BOTTOM_LEFT,
                    android.view.RoundedCorner.POSITION_BOTTOM_RIGHT};
                for (int i = 0; i < positions.length; i++) {
                    android.view.RoundedCorner corner = platform.getRoundedCorner(positions[i]);
                    if (corner != null) radii[i] = corner.getRadius();
                }
            }
        }
        // Kept for the frames Full screen brings to the screen's edges (FullScreenCornerPolicy).
        mDisplayCornerRadiiPx = radii;
        if (!mPanesScreenTopFollowed) {
            mPanesScreenTopFollowed = true;
            getWindow().getDecorView().getViewTreeObserver()
                .addOnGlobalLayoutListener(this::syncPanesForScreenTop);
        }
        syncPanesForScreenTop();
        int topBand = insetsCompat.getInsetsIgnoringVisibility(Type.statusBars()).top;
        com.termux.app.statusbar.StatusRowKeepOut.Mode mode = mPreferences == null
            ? com.termux.app.statusbar.StatusRowKeepOut.Mode.AUTO
            : com.termux.app.statusbar.StatusRowKeepOut.Mode.fromPreference(
                mPreferences.getStatusBarCutoutMode());
        migrateCutoutPreferences(hole, windowWidthForCutout());
        int dxPx = mPreferences == null ? 0
            : Math.round(dpToPx(mPreferences.getStatusBarCutoutOffsetX()));
        int dyPx = mPreferences == null ? 0
            : Math.round(dpToPx(mPreferences.getStatusBarCutoutOffsetY()));
        int scalePct = mPreferences == null
            ? TermuxPreferenceConstants.TERMUX_APP.DEFAULT_STATUS_BAR_CUTOUT_SCALE
            : mPreferences.getStatusBarCutoutScale();
        int marginPx = Math.round(dpToPx(mPreferences == null
            ? TermuxPreferenceConstants.TERMUX_APP.DEFAULT_STATUS_BAR_CUTOUT_MARGIN
            : mPreferences.getStatusBarCutoutMargin()));
        com.termux.app.statusbar.StatusRowKeepOut.Screen screen =
            new com.termux.app.statusbar.StatusRowKeepOut.Screen(hole != null,
                hole == null ? 0 : hole.left, hole == null ? 0 : hole.top,
                hole == null ? 0 : hole.right, hole == null ? 0 : hole.bottom, topBand,
                radii[0], radii[1], radii[2], radii[3], mode, dxPx, dyPx, scalePct, marginPx,
                Math.round(dpToPx(com.termux.app.chrome.CameraHoleGeometry.CUSTOM_BASE_DP)));
        // The one box the bar's split and the panes read, in window pixels; only in Full screen.
        int windowWidth = windowWidthForCutout();
        int[] cameraBox = mProperties != null && mProperties.isUsingFullScreen()
            ? com.termux.app.statusbar.StatusRowKeepOut.keepOutBox(screen, windowWidth) : null;
        boolean boxMoved = !java.util.Arrays.equals(cameraBox, mCameraBox);
        mCameraBox = cameraBox;
        if (boxMoved) syncPanesForScreenTop();
        // The Floating bar's gap from the screen's edge follows Full screen and the screen's
        // corners (applyStatusBarStyle); restyle once when either changed under it.
        boolean fullScreen = mProperties != null && mProperties.isUsingFullScreen();
        if (fullScreen != mStatusBar.statusStyleFullScreen()
            || !java.util.Arrays.equals(radii, mStatusBar.statusStyleCornerRadii())) {
            View barHost = findViewById(R.id.terminal_window_bar_host);
            if (barHost != null) mStatusBar.applyStatusBarStyle(barHost);
        }
        // The window bar reads the same answer for where it stands, but only in Full screen: with
        // the system bar showing it never reaches the camera's band, and stays as it always was.
        View windowBar = findViewById(R.id.terminal_window_bar);
        if (windowBar instanceof com.termux.app.terminal.TerminalWindowBar)
            ((com.termux.app.terminal.TerminalWindowBar) windowBar).setScreenKeepOut(
                mProperties != null && mProperties.isUsingFullScreen() ? screen : null);
        homeFloatChipBar().setScreenKeepOut(
            mProperties != null && mProperties.isUsingFullScreen() ? screen : null);
        if (!(row instanceof com.termux.app.statusbar.StatusRowLayout)) return;
        ((com.termux.app.statusbar.StatusRowLayout) row).setScreenKeepOut(screen);
    }

    /**
     * Whether the strip behind the system status bar repeats the top pane's veil.
     *
     * <p>True (user decision 2026-09-17): the strip carries whatever veil the pane below it wears,
     * so the docked top pane is one continuous sheet of glass from the physical top edge of the
     * screen down. The strip is still not a band of its own — it asks no question and notes no
     * glass; it only repeats the pane's answer. False leaves the strip bare glass: the veil stays
     * strictly under the content that asked for it, at the price of a step at the system bar's
     * bottom edge.</p>
     */
    private static final boolean STATUS_INSET_STRIP_CONTINUES_PANE_VEIL = true;

    /**
     * Continue the top pane's glass through the system status-bar inset. This surface is a sibling
     * of the drawer, so Android cannot clip it at the drawer's top bound. The compact window row
     * remains bottom-aligned inside its expanded pane and the terminal still starts below that pane.
     *
     * <p>The strip carries no content of its own — every status widget, the lens and the chips are
     * laid out in the pane below it — so it is not a chrome band and asks for no veil. See
     * {@link #STATUS_INSET_STRIP_CONTINUES_PANE_VEIL}.</p>
     */
    /**
     * The first band showing in the top edge's stack — outermost first, so the one against the
     * system status bar — or null while that stack shows none.
     */
    @Nullable
    private View topEdgeStackLeadView() {
        View stack = findViewById(R.id.place_edge_stack_top);
        if (!(stack instanceof ViewGroup) || stack.getVisibility() != View.VISIBLE) return null;
        ViewGroup bands = (ViewGroup) stack;
        for (int index = 0; index < bands.getChildCount(); index++) {
            View band = bands.getChildAt(index);
            if (band.getVisibility() == View.VISIBLE) return band;
        }
        return null;
    }

    /**
     * What leads the top edge in the docked style: the window bar, a sheet in the dock's material
     * (the pinned-apps plank, the alphabets bar's own capsule), or nothing a strip could continue.
     * The capsule has no lead: it floats clear of the status bar. Extra keys standing along the top
     * wear no glass of their own, so they count as nothing here.
     */
    @NonNull
    private com.termux.app.chrome.ChromeEdgeRule.TopLead topEdgeStackLead() {
        if (isRoundedStyle(com.termux.app.place.SeamDress.Surface.STATUS)) return com.termux.app.chrome.ChromeEdgeRule.TopLead.NONE;
        View lead = topEdgeStackLeadView();
        if (lead == null) return com.termux.app.chrome.ChromeEdgeRule.TopLead.NONE;
        int id = lead.getId();
        if (id == R.id.terminal_window_bar_host)
            return com.termux.app.chrome.ChromeEdgeRule.TopLead.WINDOW_BAR;
        if (id == R.id.place_off_dock_plank_host || id == R.id.place_az_bar_host)
            return com.termux.app.chrome.ChromeEdgeRule.TopLead.DOCK_SHEET;
        return com.termux.app.chrome.ChromeEdgeRule.TopLead.NONE;
    }

    /** The lead the strip behind the system status bar continues, or NONE while it is not shown. */
    @NonNull
    private com.termux.app.chrome.ChromeEdgeRule.TopLead statusInsetStripLead() {
        // Under a joined Docked frame the frame's glass runs up under the system bar: no strip.
        if (frameStandsDown()) return com.termux.app.chrome.ChromeEdgeRule.TopLead.NONE;
        return com.termux.app.chrome.ChromeEdgeRule.statusInsetLead(isRoundedStyle(com.termux.app.place.SeamDress.Surface.STATUS),
            !shouldEnableSeamlessStatusBackground(), mLastStatusBarInsetTop, topEdgeStackLead());
    }

    /** The lead the status inset strip was last given; see {@link #applyTerminalWindowBarBackdropInsets}. */
    @NonNull private com.termux.app.chrome.ChromeEdgeRule.TopLead mStatusStripLead =
        com.termux.app.chrome.ChromeEdgeRule.TopLead.NONE;

    /** Whether {@code sheet} is the band the status inset strip continues. */
    private boolean continuesIntoStatusInsetStrip(@Nullable View sheet) {
        return sheet != null && statusInsetStripLead() != com.termux.app.chrome.ChromeEdgeRule.TopLead.NONE
            && topEdgeStackLeadView() == sheet;
    }

    /**
     * The strip behind the system status bar, in the docked style, for whatever leads the top
     * edge: the window bar's own glass, as it always was, or the dock's material over a sheet off
     * the dock — each at its own opacity, blur and frost, and on the upper slice of the light model
     * the surface below renders the rest of, so the two read as one card running up under the
     * system bar. Nothing leading, the capsule, or fullscreen: no strip.
     */
    private void applyTerminalWindowBarBackdropInsets() {
        View host = findViewById(R.id.terminal_window_bar_host);
        View statusGlass = findViewById(R.id.terminal_status_bar_background);
        if (host == null || statusGlass == null) return;
        com.termux.app.chrome.ChromeEdgeRule.TopLead lead = statusInsetStripLead();
        com.termux.app.chrome.ChromeEdgeRule.TopLead previous = mStatusStripLead;
        mStatusStripLead = lead;
        // The deck's band over the strip follows the lead this pass lays.
        applyDeckBands();
        if (previous != lead) {
            // The surface the strip used to continue, or now continues, renders a different slice
            // and takes a different top seam: re-glaze it, after this pass rather than inside it.
            if (previous == com.termux.app.chrome.ChromeEdgeRule.TopLead.WINDOW_BAR
                || lead == com.termux.app.chrome.ChromeEdgeRule.TopLead.WINDOW_BAR)
                host.post(this::refreshTerminalWindowBar);
            if (previous == com.termux.app.chrome.ChromeEdgeRule.TopLead.DOCK_SHEET
                || lead == com.termux.app.chrome.ChromeEdgeRule.TopLead.DOCK_SHEET)
                host.post(this::refreshOffDockGlass);
        }
        View statusSurface = findViewById(R.id.terminal_status_bar_glass_surface);
        if (lead == com.termux.app.chrome.ChromeEdgeRule.TopLead.NONE) {
            // Over the wallpaper this view is only ever the strip, so a strip that has just lost
            // its lead goes with it rather than waiting for the next appearance pass.
            if (previous != lead && shouldUseWallpaperPassthroughMode())
                statusGlass.setVisibility(View.GONE);
            statusGlass.setTranslationY(0f);
            if (statusSurface != null) statusSurface.setVisibility(View.GONE);
            mChrome.requestSync(ChromeRenderer.SCOPE_TOP_PANE_FROST);
            return;
        }
        if (lead == com.termux.app.chrome.ChromeEdgeRule.TopLead.DOCK_SHEET) {
            applyStatusInsetStripOverDockSheet(statusGlass, statusSurface);
            return;
        }
        float opacity = mPreferences != null ? mPreferences.getStatusBarOpacity(mStatusBar.statusLookPage()) / 100f : 1f;
        int glassInset = mStatusBar.resolveStatusBarHorizontalInsetPx();
        ViewGroup.LayoutParams glassParams = statusGlass.getLayoutParams();
        if (glassParams instanceof ViewGroup.MarginLayoutParams) {
            ViewGroup.MarginLayoutParams glassMargins = (ViewGroup.MarginLayoutParams) glassParams;
            if (glassMargins.leftMargin != glassInset || glassMargins.rightMargin != glassInset) {
                glassMargins.leftMargin = glassInset;
                glassMargins.rightMargin = glassInset;
                statusGlass.setLayoutParams(glassMargins);
                if (!mCrossing.seam().sliding()) mStatusBar.resetStatusMarginEase(statusGlass);
            }
        }
        statusGlass.setTranslationY(-mLastStatusBarInsetTop);
        statusGlass.setBackgroundColor(Color.TRANSPARENT);
        statusGlass.setVisibility(View.VISIBLE);
        if (statusSurface != null) {
            // Mid-crossing the fade holds the strip's glass (and the bar's): both are built once
            // in the arriving half's dress and cross with the finger (TopBandFade).
            if (!topFadeTakesRedress()) statusSurface.setBackground(buildStatusInsetStripSurface(host));
            statusSurface.setVisibility(View.VISIBLE);
        }
        // Shown, or dressed again, while the bar rides: it stands where the bar stands from this
        // pass, not at its rest until the bar's next move.
        mTopStackRenderer.requestApply();
        mChrome.requestSync(ChromeRenderer.SCOPE_TOP_PANE_FROST);
    }

    /**
     * The strip over a sheet in the dock's material leading the top edge: the dock's opacity, the
     * dock's blur radius, and the slice of the light model above the one the sheet renders
     * ({@link #statusInsetSheetSliceStart}). The frost is the painter's, at the dock's radius.
     */
    private void applyStatusInsetStripOverDockSheet(@NonNull View statusGlass,
                                                    @Nullable View statusSurface) {
        float opacity = mPreferences == null ? 1f : mPreferences.getAppBarOpacity(stackLookPage()) / 100f;
        int glassInset = mDock.appliedDockLayout().horizontalInsetPx;
        ViewGroup.LayoutParams glassParams = statusGlass.getLayoutParams();
        if (glassParams instanceof ViewGroup.MarginLayoutParams) {
            ViewGroup.MarginLayoutParams glassMargins = (ViewGroup.MarginLayoutParams) glassParams;
            if (glassMargins.leftMargin != glassInset || glassMargins.rightMargin != glassInset) {
                glassMargins.leftMargin = glassInset;
                glassMargins.rightMargin = glassInset;
                statusGlass.setLayoutParams(glassMargins);
                if (!mCrossing.seam().sliding()) mStatusBar.resetStatusMarginEase(statusGlass);
            }
        }
        statusGlass.setTranslationY(-mLastStatusBarInsetTop);
        statusGlass.setBackgroundColor(Color.TRANSPARENT);
        statusGlass.setVisibility(View.VISIBLE);
        if (statusSurface != null) {
            statusSurface.setBackground(mChrome.glass().dockSurface(opacity, 0f,
                statusInsetSheetSliceStart(topEdgeStackLeadView()), false,
                mChrome.glass().statusTintStrength()));
            statusSurface.setVisibility(View.VISIBLE);
        }
        // Shown, or dressed again, while the bar rides: it stands where the bar stands from this
        // pass, not at its rest until the bar's next move.
        mTopStackRenderer.requestApply();
        mChrome.requestSync(ChromeRenderer.SCOPE_TOP_PANE_FROST);
    }

    /**
     * Where the dock's light model splits between the status inset strip and the sheet leading the
     * top edge under it: the strip renders {@code [0, f]}, the sheet {@code [f, 1]}. 0 for a sheet
     * the strip does not continue, which then renders the whole model as it always has.
     */
    private float statusInsetSheetSliceStart(@Nullable View sheet) {
        if (!continuesIntoStatusInsetStrip(sheet)) return 0f;
        int sheetPx = sheet.getId() == R.id.place_off_dock_plank_host
            ? offDockPlankGlassHeightPx() : azBarThicknessPx();
        return com.termux.app.chrome.ChromeEdgeRule.stripFraction(mLastStatusBarInsetTop, sheetPx);
    }

    private float terminalWindowGlassStatusFraction(@NonNull View host) {
        int paneHeight = host.getLayoutParams() != null ? host.getLayoutParams().height : 0;
        if (paneHeight <= 0) {
            paneHeight = Math.round(
                dpToPx(com.termux.app.statusbar.StatusBarEdgeGeometry.ROW_EXPANDED_DOCKED_DP));
        }
        return mLastStatusBarInsetTop / (float) (mLastStatusBarInsetTop + paneHeight);
    }









    private void applyDockImeOffset(int imeLiftPx) {
        mDockImeLiftPx = imeLiftPx;
        applyAccessoryStackTranslation();
    }

    /**
     * The accessory stack's one translationY, which two things own a share of: the system IME's
     * lift, and the wall's travel sliding the dock and keyboard between two places' states. Each
     * writes its own share and the stack's renderer sums them, so neither undoes the other; it
     * also cuts the stack and the keyboard where the travel slides them past their laid-out
     * bottoms, and holds the bands under the keyboard up by the keyboard's share
     * ({@link com.termux.app.place.StackScene}).
     */
    private void applyAccessoryStackTranslation() {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q)
            Trace.setCounter("Wall.stackTranslationPx", Math.round(mDockTravelTranslationPx));
        mStackRenderer.setTravel(mDockTravelTranslationPx, mKeyboardTravelSharePx, mDockImeLiftPx);
    }

    /**
     * The bottom stack's one writer of transforms (the travel, the IME's lift, the sink, the
     * slide and the plank's slab, composed), reading the stack's views through the activity.
     */

