    /**
     * Confirms killing a session on the terminal sheet plane rather than in a dialog window, so the
     * prompt costs no focus change over the terminal it is about. The pid rides in the title: it is
     * the only thing distinguishing this prompt from the same one about another session.
     */
    private void showKillSessionDialog(TerminalSession session) {
        if (session == null)
            return;
        com.termux.app.terminal.TerminalSheetController sheet = getTerminalSheetController();
        LinearLayout body = com.termux.app.terminal.TerminalSheetViews.body(this);
        com.termux.app.terminal.TerminalSheetViews.addMessage(body,
            getString(R.string.title_confirm_kill_process));
        LinearLayout actions = com.termux.app.terminal.TerminalSheetViews.addActionRow(body);
        com.termux.app.terminal.TerminalSheetViews.addAction(actions,
            getString(android.R.string.cancel), sheet::dismiss);
        com.termux.app.terminal.TerminalSheetViews.addAction(actions,
            getString(android.R.string.ok), () -> {
                sheet.dismiss();
                session.finishIfRunning();
            });
        sheet.show(getString(R.string.action_kill_process, session.getPid()), body);
    }

    private void onResetTerminalSession(TerminalSession session) {
        if (session != null) {
            session.reset();
            showToast(getResources().getString(R.string.msg_terminal_reset), true);
            if (mTermuxTerminalSessionActivityClient != null)
                mTermuxTerminalSessionActivityClient.onResetTerminalSession();
        }
    }

    /**
     * For processes to access primary external storage (/sdcard, /storage/emulated/0, ~/storage/shared),
     * termux needs to be granted legacy WRITE_EXTERNAL_STORAGE or MANAGE_EXTERNAL_STORAGE permissions
     * if targeting targetSdkVersion 30 (android 11) and running on sdk 30 (android 11) and higher.
     */
    public void requestStoragePermission(boolean isPermissionCallback) {
        new Thread() {

            @Override
            public void run() {
                // Do not ask for permission again
                int requestCode = isPermissionCallback ? -1 : PermissionUtils.REQUEST_GRANT_STORAGE_PERMISSION;
                // If permission is granted, then also setup storage symlinks.
                if(PermissionUtils.checkAndRequestLegacyOrManageExternalStoragePermission(
                    TermuxActivity.this, requestCode, true, !isPermissionCallback)) {
                    if (isPermissionCallback)
                        Logger.logInfoAndShowToast(TermuxActivity.this, LOG_TAG, getString(com.termux.shared.R.string.msg_storage_permission_granted_on_request));
                    TermuxInstaller.setupStorageSymlinks(TermuxActivity.this);
                } else {
                    if (isPermissionCallback)
                        Logger.logInfoAndShowToast(TermuxActivity.this, LOG_TAG, getString(com.termux.shared.R.string.msg_storage_permission_not_granted_on_request));
                }
            }
        }.start();
    }

    @Override
    protected void onActivityResult(int requestCode, int resultCode, @Nullable Intent data) {
        Logger.logVerbose(LOG_TAG, "onActivityResult: requestCode: " + requestCode + ", resultCode: " + resultCode + ", data: " + IntentUtils.getIntentString(data));
        if ((requestCode == REQUEST_CODE_WIDGET_BIND || requestCode == REQUEST_CODE_WIDGET_CONFIGURE
                || requestCode == REQUEST_CODE_WIDGET_RECONFIGURE)
            && mWidgetHostController != null
            && mWidgetHostController.handleActivityResult(requestCode, resultCode, data)) {
            return;
        }
        super.onActivityResult(requestCode, resultCode, data);
        if (requestCode == PermissionUtils.REQUEST_GRANT_STORAGE_PERMISSION) {
            requestStoragePermission(true);
        } else if (requestCode == REQUEST_CODE_VOICE_TYPING) {
            TerminalSession target = mVoiceTypingTargetSession;
            mVoiceTypingTargetSession = null;
            if (resultCode != RESULT_OK || data == null || target == null) return;
            java.util.ArrayList<String> results = data.getStringArrayListExtra(
                android.speech.RecognizerIntent.EXTRA_RESULTS);
            if (results == null) return;
            for (String result : results) {
                if (result != null && !result.trim().isEmpty()) {
                    // Spoken text goes where typing goes: into the display or an overlay when
                    // one has claimed it, into the shell it was started from otherwise. Off the
                    // Terminal place (the Dictate key on Home or Display) there is no shell in
                    // front, so it goes where ✓ would, or to the clipboard.
                    if (currentWallPage() != com.termux.app.page.PageKind.TERMINAL) {
                        String text = VoiceTextSanitizer.clean(result);
                        if (!text.isEmpty() && !typeVoiceText(text) && copyVoiceText(text))
                            AppNotice.show(this, R.drawable.ic_rl_mic, getString(R.string.voice_input_no_target_copied), false);
                    } else if (!offerToInAppKeyboardInterceptor(
                            juloo.keyboard2.KeyValue.makeStringKey(result), false, false, false)) {
                        target.write(result);
                    }
                    break;
                }
            }
        }
    }

    private void launchVoiceTyping(boolean chooser) {
        TerminalSession target = getCurrentSession();
        if (target == null) return;
        Intent recognition = new Intent(android.speech.RecognizerIntent.ACTION_RECOGNIZE_SPEECH);
        recognition.putExtra(android.speech.RecognizerIntent.EXTRA_LANGUAGE_MODEL,
            android.speech.RecognizerIntent.LANGUAGE_MODEL_FREE_FORM);
        if (getPackageManager().resolveActivity(recognition,
                android.content.pm.PackageManager.MATCH_DEFAULT_ONLY) == null) {
            AppNotice.show(this, R.drawable.ic_rl_mic, getString(R.string.voice_typing_unavailable), false);
            return;
        }
        Intent launch = createVoiceTypingIntent(this, chooser);
        try {
            mVoiceTypingTargetSession = target;
            startActivityForResult(launch, REQUEST_CODE_VOICE_TYPING);
        } catch (android.content.ActivityNotFoundException e) {
            mVoiceTypingTargetSession = null;
            AppNotice.show(this, R.drawable.ic_rl_mic, getString(R.string.voice_typing_unavailable), false);
        }
    }

    // ------------------------------------------------------------------ on-device voice input

    /**
     * Starts a dictation with the on-device engine: opens the microphone for a
     * {@link VoiceInputSession} whose phrases collect in the pill's panel, never in the terminal,
     * until the panel's ✓ or Copy uses them. Every way it cannot — no speech model, no microphone
     * permission, a runtime refusal — falls back to the Android recognizer
     * ({@link #launchVoiceTyping}) with a one-line notice, so the key always does something.
     *
     * @param fromKeyboard started from the in-app keyboard's voice key, which needs that keyboard
     *     up and stops the dictation when it goes down; the Dictate key needs neither
     */
    private void startOnDeviceVoiceInput(boolean fromKeyboard) {
        if (mVoiceInput != null) return;
        if (fromKeyboard && (mInAppKeyboard == null || !mInAppKeyboard.isVisible())) return;
        com.termux.ai.TaiSettings tai = new com.termux.ai.TaiSettings(this);
        // The settings' choice, or another installed speech model when that one's files are gone.
        com.termux.ai.TaiModelSpec model = com.termux.ai.TaiSpeechModels.resolveActive(this);
        if (model == null) {
            AppNotice.show(this, R.drawable.ic_rl_mic, getString(R.string.voice_input_no_model), false);
            launchVoiceTyping(false);
            return;
        }
        String modelId = model.id;
        // Each installed graph carries its own window in its file name; the setting is only the
        // preference for the next download.
        int windowSeconds = com.termux.ai.TaiSpeechModels.windowSeconds(model);
        if (windowSeconds <= 0) windowSeconds = tai.getSttWindowSeconds();
        if (androidx.core.content.ContextCompat.checkSelfPermission(this,
                android.Manifest.permission.RECORD_AUDIO)
            != android.content.pm.PackageManager.PERMISSION_GRANTED) {
            mVoiceMicrophoneAskedFromKeyboard = fromKeyboard;
            requestVoiceInputMicrophone();
            return;
        }
        VoiceLanguage.Choice language = resolveVoiceLanguage(model);
        VoiceInputSession.Config config = new VoiceInputSession.Config(modelId, language.forced, language.hint,
            mPreferences.getInAppKeyboardVoicePauseMs(), windowSeconds,
            mPreferences.getInAppKeyboardVoiceSilenceTimeoutMs(),
            mPreferences.isInAppKeyboardVoiceSoundsEnabled(),
            mPreferences.isInAppKeyboardHapticsEnabled(),
            VoiceMicSensitivity.fromStorage(mPreferences.getInAppKeyboardVoiceMicSensitivity()));
        VoiceInputSession session = new VoiceInputSession(this, config, mVoiceInputHost);
        mVoiceSpeechWarming = true;
        if (!session.start()) {
            mVoiceSpeechWarming = false;
            AppNotice.show(this, R.drawable.ic_rl_mic, getString(R.string.voice_input_fallback,
                getString(R.string.voice_input_mic_unavailable)), false);
            launchVoiceTyping(false);
            return;
        }
        // Text still waiting in the panel is carried on from rather than lost; a pill that is
        // only saying what became of used text gives way. Waiting text that is a cleanup or an
        // edit is final and is not cleaned again; text as heard is, and a cleanup still running on
        // it hands over what it had cleaned. An edit still open is kept first, so the new
        // dictation carries on from it.
        endVoiceEdit();
        String base = mVoiceDictation.carryOver();
        boolean baseFinal = !base.trim().equals(mVoiceDictation.raw().trim());
        VoiceSessionCleanup previous = null;
        if (base.isEmpty()) {
            closeVoicePill();
        } else {
            previous = mVoiceCleanup;
            mVoiceCleanup = null;
            if (previous != null) previous.cancel();
            getWindow().getDecorView().removeCallbacks(mVoicePillAutoClose);
        }
        mVoiceInput = session;
        mVoiceTiedToKeyboard = fromKeyboard;
        mVoiceDictation.start(base);
        // Phrases collect as heard; with cleanup on, the chat model resolves on its own thread. A
        // model already resident is warmed now and cleans what was said so far at phrase pauses
        // when it is quick enough; a cold one loads only once the session ends (a cold GPU load
        // while the user spoke froze the screen). Either way the rest is cleaned at the end. With
        // no Gemma installed the passes hand the raw text back and nothing changes.
        if (mPreferences.isInAppKeyboardVoicePolishEnabled()) {
            String level = mPreferences.getInAppKeyboardVoicePolishLevel();
            VoiceSessionCleanup cleanup = new VoiceSessionCleanup(new LocalTaiVoiceTextPolisher(this, level), level);
            cleanup.carryOn(base, baseFinal, previous);
            // A language the setting forces (or an English-only model) is certain; otherwise the
            // speech model's own guess arrives later (onSpeechLanguage), and the keyboard's or the
            // phone's language is assumed only for text that reads as no language in particular.
            cleanup.setLanguageHint(language.forced != null ? language.forced
                : com.termux.ai.TaiSpeechModels.isEnglishOnly(model) ? "en" : null);
            cleanup.setLanguageFallback(VoiceLanguage.resolve(mPreferences.getInAppKeyboardVoiceLanguage(),
                mInAppKeyboard == null ? null : mInAppKeyboard.getActiveTextLayoutId(), userLocale()).code);
            mVoiceCleanup = cleanup;
            cleanup.warmIfResident(this::refreshVoiceWarmUp);
        }
    }

    /**
     * {@code voice.dictate}, the Dictate key: starts a dictation when none is listening — on any
     * place, the keyboard up or down, or no launcher keyboard at all — and stops the one that is.
     * Either way the text waits in the panel. With the Android recognizer chosen in Settings, that
     * recognizer opens instead.
     *
     * @return whether a dictation is listening now
     */
    boolean toggleVoiceDictation() {
        VoiceInputSession session = mVoiceInput;
        if (session != null) {
            // Like the voice key: once the mic has closed, the captured phrases finish on their own.
            if (!session.isStopRequested()) session.stop(VoiceInputSession.EndReason.USER);
            return false;
        }
        if (mPreferences == null) return false;
        if (!voiceUsesOnDevice()) {
            launchVoiceTyping(false);
            return false;
        }
        startOnDeviceVoiceInput(false);
        return mVoiceInput != null;
    }

    /**
     * What a dictation sends the speech model: the setting's language forced on a multilingual
     * Whisper graph, or with Auto no language and the layout's (then the locale's) as the hint
     * the graph falls back to while it is not sure what it hears; nothing for an English-only
     * graph or Parakeet, which decide alone. Both one-time notices live here: a setting Whisper
     * does not know (English is used), and a non-English choice against an {@code .en} model (the
     * choice is ignored).
     */
    @NonNull
    private VoiceLanguage.Choice resolveVoiceLanguage(@NonNull com.termux.ai.TaiModelSpec model) {
        mVoiceSpokenLanguage = null;
        String setting = mPreferences.getInAppKeyboardVoiceLanguage();
        if (com.termux.ai.TaiSpeechModels.isParakeet(model.id, model.localPath)) return VoiceLanguage.Choice.NONE;
        boolean englishOnly = com.termux.ai.TaiSpeechModels.isEnglishOnly(model);
        if (englishOnly) {
            if (!VoiceLanguage.AUTO.equals(setting) && !VoiceLanguage.FALLBACK.equals(setting)
                && !mVoiceEnglishOnlyNoticed) {
                mVoiceEnglishOnlyNoticed = true;
                AppNotice.show(this, R.drawable.ic_rl_mic, getString(R.string.voice_input_english_only_model,
                    new java.util.Locale(setting).getDisplayLanguage()), true);
            }
            return VoiceLanguage.Choice.NONE;
        }
        String layoutId = mInAppKeyboard == null ? null : mInAppKeyboard.getActiveTextLayoutId();
        VoiceLanguage.Resolution resolution = VoiceLanguage.resolve(setting, layoutId, userLocale());
        // Auto listens, so an unknown layout only means an English hint, not English forced.
        if (resolution.fallback && resolution.explicit && !mVoiceLanguageFallbackNoticed) {
            mVoiceLanguageFallbackNoticed = true;
            AppNotice.show(this, R.drawable.ic_rl_mic, getString(R.string.voice_input_language_fallback), false);
        }
        return VoiceLanguage.Choice.forWhisper(resolution);
    }

    @NonNull
    private java.util.Locale userLocale() {
        return getResources().getConfiguration().getLocales().isEmpty()
            ? java.util.Locale.getDefault() : getResources().getConfiguration().getLocales().get(0);
    }

    private void requestVoiceInputMicrophone() {
        if (mVoiceMicrophonePromptShowing) return;
        if (!androidx.core.app.ActivityCompat.shouldShowRequestPermissionRationale(this,
                android.Manifest.permission.RECORD_AUDIO)) {
            androidx.core.app.ActivityCompat.requestPermissions(this,
                new String[] {android.Manifest.permission.RECORD_AUDIO},
                REQUEST_CODE_VOICE_INPUT_MICROPHONE);
            return;
        }
        mVoiceMicrophonePromptShowing = true;
        new MaterialAlertDialogBuilder(this)
            .setTitle(R.string.voice_input_permission_title)
            .setMessage(R.string.voice_input_permission_message)
            .setPositiveButton(R.string.voice_input_permission_allow, (dialog, which) ->
                androidx.core.app.ActivityCompat.requestPermissions(this,
                    new String[] {android.Manifest.permission.RECORD_AUDIO},
                    REQUEST_CODE_VOICE_INPUT_MICROPHONE))
            .setNegativeButton(R.string.voice_input_permission_dismiss, (dialog, which) ->
                launchVoiceTyping(false))
            .setOnDismissListener(dialog -> mVoiceMicrophonePromptShowing = false)
            .show();
    }

    /** Releases the microphone; phrases already captured still arrive. No-op without a session. */
    private void endVoiceInput(@NonNull VoiceInputSession.EndReason reason) {
        VoiceInputSession session = mVoiceInput;
        if (session != null) session.stop(reason);
    }

    /** Releases the microphone and drops whatever is in flight: the activity is going away. */
    private void cancelVoiceInput() {
        VoiceInputSession session = mVoiceInput;
        mVoiceInput = null;
        mDictationMarks.end(true);
        if (session != null) session.cancel(VoiceInputSession.EndReason.DESTROYED);
        closeVoicePill();
    }

    /**
     * The speech engine in use: the one picked in Keyboard settings, or, never picked, on-device as
     * soon as a speech model is installed and Android's recognizer before that.
     */
    private boolean voiceUsesOnDevice() {
        if (mPreferences.isInAppKeyboardVoiceEngineChosen()) return mPreferences.isInAppKeyboardVoiceOnDevice();
        return com.termux.ai.TaiSpeechModels.resolveActive(this) != null;
    }

    private void showVoiceIndicator() {
        // The place viewport — the frame the pane wall slides inside — anchors the pill at its top
        // right, under the status bar and the top bars, the same on Home, Terminal and Display.
        View panes = findViewById(R.id.terminal_surface_host);
        if (panes == null) return;
        if (mVoiceIndicator == null) {
            mVoiceIndicator = new VoiceListeningIndicator(this, panes, mVoicePillPlace);
            mVoiceIndicator.setTypingKeyboardBounds(out ->
                mInAppKeyboard != null && mInAppKeyboard.getKeyboardRectOnScreen(out));
        }
        mVoiceIndicator.show(mVoicePillCallbacks, mVoiceCleanup != null, mVoiceDictation.raw());
        refreshVoiceWarmUp();
        // Talking is not touching, so the phone's screen timeout would dim and then lock mid-sentence.
        holdVoiceScreen();
    }

    /**
     * Read aloud from the selection toolbar, on the reading card ({@link ReadAloudCard}): in the
     * same place viewport and the same remembered place as the dictation pill, on an indicator of
     * its own so a dictation that is up is left alone. False without a viewport to put it in.
     */
    private boolean startReadAloudCard(@NonNull String text) {
        View panes = findViewById(R.id.terminal_surface_host);
        if (panes == null) return false;
        if (mReadAloudCard == null) mReadAloudCard = new ReadAloudCard(this, panes, mVoicePillPlace);
        mReadAloudCard.start(text);
        return true;
    }

    /**
     * Holds the screen on for as long as the pill is up ({@link VoiceScreenHold}): without a limit
     * while the dictation listens, transcribes or cleans up, and with the idle release running
     * once the text only waits. No-op with the pill down or the activity paused.
     */
    private void holdVoiceScreen() {
        if (!mVoiceScreenMayHold || mVoiceIndicator == null || !mVoiceIndicator.isShowing()) return;
        mVoiceScreenHold.hold(mVoiceInput == null && mVoiceCleanup == null);
    }

    /** The pill's "Warming up" chip: the speech side or the cleanup model is still loading. */
    private void refreshVoiceWarmUp() {
        if (mVoiceIndicator == null) return;
        VoiceSessionCleanup cleanup = mVoiceCleanup;
        boolean listening = mVoiceInput != null && !mVoiceInput.isStopRequested();
        mVoiceIndicator.setWarmingUp(listening && (mVoiceSpeechWarming || (cleanup != null && cleanup.isWarming())));
    }

    /**
     * Closes the pill however far it got, and its text goes with it: a cleanup still running is
     * dropped, the screen hold lets go. Nothing ever reached the terminal, so nothing there
     * changes. No-op when it is down.
     */
    private void closeVoicePill() {
        // The editor goes with the text, and gives the keyboard's typing back first.
        if (mVoiceCardEdit != null) mVoiceCardEdit.abandon();
        VoiceSessionCleanup cleanup = mVoiceCleanup;
        mVoiceCleanup = null;
        if (cleanup != null) cleanup.cancel();
        mVoiceDictation.clear();
        getWindow().getDecorView().removeCallbacks(mVoicePillAutoClose);
        if (mVoiceIndicator != null) mVoiceIndicator.hide();
        if (mInAppKeyboard != null) mInAppKeyboard.setVoiceTypingActive(false);
        mVoiceScreenHold.release();
    }

    private void closeVoicePillAfter(long delayMs) {
        View decor = getWindow().getDecorView();
        decor.removeCallbacks(mVoicePillAutoClose);
        decor.postDelayed(mVoicePillAutoClose, delayMs);
    }

    /**
     * How long the pill stays once ✓ or Copy has used the text: a moment to say so, and long
     * enough to see the cleanup's marks when the press was made early and ran as they landed.
     */
    private static final long VOICE_PILL_ACTION_DONE_MS = 1_500L;
    private static final long VOICE_PILL_ACTION_ON_CLEANED_MS = 2_500L;

    /**
     * The pill's pause/resume and ×, the card's swipe, and the panel's undo, Copy and ✓. Pause
     * stops listening: every phrase still transcribing arrives, the cleanup runs and the text
     * waits; resume carries on the same text. The × and the swipe only ever discard the
     * dictation and close at once. Copy and ✓ use the text once it is final, stopping first when
     * pressed while listening. None of them ever erases or retypes anything in the terminal.
     */
    private final VoiceListeningIndicator.Callbacks mVoicePillCallbacks = new VoiceListeningIndicator.Callbacks() {
        // Every button ends an edit of the text first, kept, and with it the editor's claim on
        // the keyboard's typing; the × and the swipe end it unkept with the text.

        @Override
        public void onPause() {
            endVoiceEdit();
            endVoiceInput(VoiceInputSession.EndReason.USER);
        }

        @Override
        public void onResume() {
            endVoiceEdit();
            resumeVoiceDictation();
        }

        @Override
        public void onClose() {
            if (mVoiceCardEdit != null) mVoiceCardEdit.abandon();
            discardVoiceDictation();
        }

        @Override
        public void onTextTapped(int shownOffset) {
            voiceCardEdit().onTextTapped(shownOffset);
        }

        @Override
        public void onUndo() {
            endVoiceEdit();
            if (!mVoiceDictation.toggleUndo()) return;
            if (mVoiceIndicator != null) mVoiceIndicator.setUndone(mVoiceDictation.isUndone());
        }

        @Override
        public void onCopy() {
            useVoiceDictation(VoiceDictation.Use.COPY);
        }

        @Override
        public void onInsert() {
            useVoiceDictation(VoiceDictation.Use.INSERT);
        }

        @Override
        public void onTouched() {
            // Any touch of the pill is the user still there: the idle release starts over.
            holdVoiceScreen();
        }
    };

    /**
     * The pill's resume: listening again on the text in the panel, as the voice key or the
     * Dictate key would. A dictation the voice key started stays tied to the keyboard while that
     * keyboard is up. Not while the last phrases are still transcribing (the button waits then).
     */
    private void resumeVoiceDictation() {
        if (mVoiceInput != null || mPreferences == null) return;
        boolean fromKeyboard = mVoiceTiedToKeyboard && mInAppKeyboard != null && mInAppKeyboard.isVisible();
        startOnDeviceVoiceInput(fromKeyboard);
    }

    /** The pill's ×, or a swipe: whatever is still transcribing is dropped with the text. */
    private void discardVoiceDictation() {
        mDictationMarks.end(true);
        VoiceInputSession session = mVoiceInput;
        if (session != null) session.cancel(VoiceInputSession.EndReason.USER);
        closeVoicePill();
    }

    /**
     * ✓ or Copy. With the text final it is used now; pressed early, the press waits for the text
     * to settle (the phrases still transcribing, the one cleanup pass) and listening stops so it
     * can.
     */
    private void useVoiceDictation(@NonNull VoiceDictation.Use use) {
        // Kept, and the keyboard's slot handed back, before anything is typed: ✓ must never type
        // into the card's own editor.
        endVoiceEdit();
        if (mVoiceDictation.press(use)) {
            carryOutVoiceUse(use, mVoiceDictation.result(), false);
            return;
        }
        if (mVoiceDictation.pending() != null) endVoiceInput(VoiceInputSession.EndReason.USER);
    }

    /**
     * Copies {@code text}, or for ✓ types it once where the keyboard types ({@link #typeVoiceText});
     * with nothing there to take it, ✓ copies it instead and says so.
     *
     * @param onCleaned the press was made early and runs as the cleaned text lands
     */
    private void carryOutVoiceUse(@NonNull VoiceDictation.Use use, @Nullable String text, boolean onCleaned) {
        if (text == null || text.isEmpty()) {
            closeVoicePill();
            return;
        }
        int said;
        if (use == VoiceDictation.Use.INSERT && typeVoiceText(text)) {
            said = R.string.voice_input_inserted;
        } else {
            if (!copyVoiceText(text)) {
                closeVoicePill();
                return;
            }
            if (use == VoiceDictation.Use.INSERT) AppNotice.show(this, R.drawable.ic_rl_mic, getString(R.string.voice_input_no_target_copied), false);
            said = R.string.voice_input_cleanup_copied;
        }
        if (mVoiceIndicator != null) mVoiceIndicator.onActionDone(said);
        closeVoicePillAfter(onCleaned ? VOICE_PILL_ACTION_ON_CLEANED_MS : VOICE_PILL_ACTION_DONE_MS);
    }

    private boolean copyVoiceText(@NonNull String text) {
        android.content.ClipboardManager clipboard =
            (android.content.ClipboardManager) getSystemService(Context.CLIPBOARD_SERVICE);
        if (clipboard == null) return false;
        clipboard.setPrimaryClip(android.content.ClipData.newPlainText(
            getString(R.string.voice_input_cleanup_clip_label), text));
        return true;
    }

    /**
     * Types {@code text} once where the keyboard would type right now on the place on screen, and
     * never with an Enter. The text may hold line breaks, a Polished cleanup's paragraphs and list
     * items ({@link VoiceTextSanitizer#cleanLines}): the shell in front gets them in one bracketed
     * paste when its program takes that and on one line otherwise ({@link DictationMarks#type}), a
     * multi-line text field gets them as they are, and everywhere else a line break could run
     * something, so the text goes in on one line ({@link VoiceTextSanitizer#oneLine}). In order:
     * first whatever has claimed the launcher keyboard's typing — the palette, the drawer's
     * search, a rename, a sheet, or on the Display place the display itself; then, on the Display
     * place without a launcher keyboard, the display through the same bridge; then a focused text
     * field of the launcher's own (a widget's editor, typed into by the phone's keyboard); and on
     * the Terminal place the shell in front. Home has no shell in front of it and a display with no server has
     * nobody listening, so false there, and the caller copies instead.
     */
    private boolean typeVoiceText(@NonNull String text) {
        String oneLine = VoiceTextSanitizer.oneLine(text);
        juloo.keyboard2.KeyValue value = juloo.keyboard2.KeyValue.makeStringKey(oneLine);
        if (offerToInAppKeyboardInterceptor(value, false, false, false)) return true;
        com.termux.app.page.PageKind page = currentWallPage();
        if (page == com.termux.app.page.PageKind.DISPLAY) {
            // The bridge answers false with no server connected; the terminal behind is never the
            // fallback for text meant for the display.
            return x11KeyboardBridge().interceptKeyValue(value, false, false, false);
        }
        View focus = getCurrentFocus();
        if (focus instanceof EditText) {
            EditText field = (EditText) focus;
            android.text.Editable editable = field.getText();
            if (editable != null) {
                int start = Math.max(0, Math.min(field.getSelectionStart(), field.getSelectionEnd()));
                int end = Math.max(start, Math.max(field.getSelectionStart(), field.getSelectionEnd()));
                boolean multiLine = (field.getInputType() & android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE) != 0;
                editable.replace(start, end, multiLine ? text : oneLine);
                return true;
            }
        }
        if (page != com.termux.app.page.PageKind.TERMINAL) return false;
        TerminalSession session = getCurrentSession();
        if (session == null || !session.isRunning()) return false;
        mDictationMarks.type(session, text);
        return true;
    }

    /**
     * One transcribed phrase into the panel, as heard; nothing reaches the terminal. The cleanup
     * may clean what was said so far in the background, shown only once the dictation ends.
     */
    private void appendVoicePhrase(@NonNull String transcript) {
        String piece = mVoiceDictation.append(transcript);
        if (piece.isEmpty()) return;
        VoiceSessionCleanup cleanup = mVoiceCleanup;
        VoiceInputSession session = mVoiceInput;
        if (cleanup != null) {
            cleanup.onPhrase(mVoiceDictation.raw(), session != null && session.isTranscribing(),
                mVoiceDictation.isByHand());
        }
        // While the text is open in the editor the phrase joins the draft's end instead.
        if (mVoiceCardEdit != null && mVoiceCardEdit.onPhrase(piece)) return;
        if (mVoiceIndicator != null) mVoiceIndicator.appendTranscript(piece);
    }

    /**
     * The microphone is released and every phrase delivered. Nothing heard closes the pill; a
     * dictated command is written as one ({@link VoiceCommandFormatter}, no model, cleanup on or
     * off); with cleanup on and something worth cleaning, what the passes during the dictation
     * have not cleaned is cleaned now; otherwise the text waits as heard.
     */
    private void finishVoiceSession(@NonNull VoiceInputSession.EndReason reason) {
        mVoiceDictation.onStopped();
        VoiceListeningIndicator indicator = mVoiceIndicator;
        String raw = mVoiceDictation.raw().trim();
        if (indicator == null || !indicator.isShowing() || raw.isEmpty()
            || mVoiceDictation.phase() != VoiceDictation.Phase.FINISHING) {
            closeVoicePill();
            return;
        }
        VoiceSessionCleanup cleanup = mVoiceCleanup;
        if (mVoiceDictation.isByHand()) {
            // The user has edited the text: neither the formatter nor the model may rewrite it.
            mVoiceCleanup = null;
            if (cleanup != null) cleanup.cancel();
            indicator.showAsHeard(R.string.voice_input_ready);
            settleVoiceDictation(raw, false);
            if (mVoiceCardEdit != null) mVoiceCardEdit.onSettled();
            return;
        }
        String command = VoiceCommandFormatter.format(raw);
        if (command != null) {
            // The formatter's alone: the model is never sent a command (skipReason "command").
            mVoiceCleanup = null;
            if (cleanup != null) cleanup.cancel();
            if (command.isEmpty() || command.equals(raw)) {
                indicator.showAsHeard(R.string.voice_input_ready);
                settleVoiceDictation(raw, false);
            } else {
                indicator.showCleaned(command, R.string.voice_input_cleaned_up);
                settleVoiceDictation(command, true);
            }
            return;
        }
        // A failure is often the runtime short of memory: no second model on top of it.
        boolean cleanable = reason != VoiceInputSession.EndReason.FAILED
            && VoiceSessionCleanup.skipReason(raw) == null;
        if (cleanup != null && cleanable) {
            indicator.setCleaningUp();
            cleanup.run(raw, (cleanedRaw, result) -> onVoiceCleaned(cleanup, cleanedRaw, result));
            return;
        }
        mVoiceCleanup = null;
        if (cleanup != null) cleanup.cancel();
        indicator.showAsHeard(R.string.voice_input_ready);
        settleVoiceDictation(raw, false);
    }

    /**
     * The cleanup has landed, the whole text at once. Anything but a real change keeps the text
     * as heard; a change shows with its words marked. Either way the text now waits for the panel's buttons. A pass that
     * is no longer the dictation's own — a resume or a discard replaced it, or the text moved on
     * from what it cleaned — is dropped, so an older version never comes back over the panel.
     */
    private void onVoiceCleaned(@NonNull VoiceSessionCleanup cleanup, @NonNull String raw,
                                @NonNull VoiceTextPolisher.Result result) {
        if (mVoiceCleanup != cleanup) return;
        mVoiceCleanup = null;
        VoiceListeningIndicator indicator = mVoiceIndicator;
        if (indicator == null || !indicator.isShowing()) return;
        if (mVoiceDictation.phase() != VoiceDictation.Phase.FINISHING
            || !raw.trim().equals(mVoiceDictation.raw().trim())) return;
        // A Polished pass's paragraphs and list items keep their line breaks.
        String cleaned = result.isPolished() ? VoiceTextSanitizer.cleanLines(result.text) : "";
        if (cleaned.isEmpty() || cleaned.equals(raw.trim())) {
            indicator.showAsHeard(R.string.voice_input_kept_as_heard);
            settleVoiceDictation(raw.trim(), false);
            return;
        }
        indicator.showCleaned(cleaned, R.string.voice_input_cleaned_up);
        settleVoiceDictation(cleaned, true);
    }

    /** The text is final: it waits, or an early ✓ or Copy uses it now. */
    private void settleVoiceDictation(@NonNull String text, boolean cleaned) {
        // The screen stays on while the text waits, until the idle release lets it sleep.
        holdVoiceScreen();
        VoiceDictation.Use early = cleaned ? mVoiceDictation.onCleaned(text) : mVoiceDictation.onSettled(text);
        // The dictation's result, not text: an edit kept before the text settled is what is used.
        if (early != null) carryOutVoiceUse(early, mVoiceDictation.result(), cleaned);
    }

    /** Ends an edit of the dictation card's text, keeping it. No-op when none is open. */
    private void endVoiceEdit() {
        if (mVoiceCardEdit != null) mVoiceCardEdit.end();
    }

    @NonNull
    private VoiceCardEdit voiceCardEdit() {
        if (mVoiceCardEdit == null) {
            mVoiceCardEdit = new VoiceCardEdit(mVoiceDictation, new VoiceCardEditHost(),
                ClipboardText.forContext(this), android.view.ViewConfiguration.get(this).getScaledTouchSlop());
        }
        return mVoiceCardEdit;
    }

    /** The activity's half of editing the dictation card's text: the microphone, the cleanup, the keyboards. */
    private final class VoiceCardEditHost implements VoiceCardEdit.Host {
        @Nullable
        @Override
        public VoiceCardEdit.Card card() {
            VoiceListeningIndicator indicator = mVoiceIndicator;
            return indicator != null && indicator.isShowing() ? indicator : null;
        }

        @Override
        public void stopListening() {
            VoiceInputSession session = mVoiceInput;
            if (session != null && !session.isStopRequested()) session.stop(VoiceInputSession.EndReason.USER);
        }

        @Override
        public void dropCleanup() {
            VoiceSessionCleanup cleanup = mVoiceCleanup;
            mVoiceCleanup = null;
            if (cleanup != null) cleanup.cancel();
            refreshVoiceWarmUp();
            VoiceListeningIndicator indicator = mVoiceIndicator;
            // The session had ended and only the cleanup was left: nothing else settles the text.
            if (mVoiceInput == null && mVoiceDictation.phase() == VoiceDictation.Phase.FINISHING
                && indicator != null && indicator.isShowing()) {
                indicator.showAsHeard(R.string.voice_input_ready);
                settleVoiceDictation(mVoiceDictation.raw().trim(), false);
            }
        }

        @Override
        public boolean ensureTypingKeyboard() {
            return ensureInAppTypingKeyboard();
        }

        @Override
        public void showSystemKeyboard() {
            if (!isImeVisible()) mVoiceEditRaisedIme = true;
            // Focus stays on the terminal view, which owns the input connection; committed text
            // reaches the editor through the overlay channel.
            onSystemImeRequested();
            KeyboardUtils.showSoftKeyboard(TermuxActivity.this, mTerminalView);
        }

        @Override
        public void releaseSystemKeyboard() {
            if (!mVoiceEditRaisedIme) return;
            mVoiceEditRaisedIme = false;
            if (getWindow() == null) return;
            WindowCompat.getInsetsController(getWindow(), getWindow().getDecorView()).hide(Type.ime());
        }

        @Override
        public void claimTyping(@Nullable com.termux.app.terminal.inappkeyboard.TerminalKeyEventHandler
                                    .KeyValueInterceptor interceptor) {
            if (mInAppKeyboard == null) return;
            if (interceptor != null) {
                mInAppKeyboard.setKeyValueInterceptor(interceptor);
            } else {
                restoreInAppKeyboardTypingClaim();
            }
        }

        @Override
        public boolean isOnTypingKeyboard(float rawX, float rawY) {
            // The keys, and the extra-keys row beside them: both type into the edit.
            return isPointOnInAppKeyboard(rawX, rawY)
                || viewContainsScreenPoint(findViewById(R.id.inapp_keyboard_container), rawX, rawY)
                || viewContainsScreenPoint(findViewById(R.id.terminal_toolbar_host), rawX, rawY);
        }
    }

    /**
     * Hands the in-app keyboard's interceptor slot to whoever owns it now. Every surface that
     * borrows the slot calls this on its way out, and none of them puts {@code null} back: a
     * layer closing over the display window would leave the keyboard typing into the terminal
     * hidden behind it.
     */
    private void restoreInAppKeyboardTypingClaim() {
        applyInAppKeyboardTypingClaim(mSheets.isCommandPaletteOpen(), mSheets.isTerminalSheetOpen(),
            isAppDrawerOpen());
    }

    /**
     * The one owner of the in-app keyboard's interceptor slot, in {@link
     * com.termux.app.terminal.inappkeyboard.TypingClaim}'s order. The three flags are what the
     * caller knows to be so now: a surface mid-open or mid-close is not yet what its own
     * {@code isOpen} says.
     */
    private void applyInAppKeyboardTypingClaim(boolean palette, boolean sheet, boolean drawer) {
        if (mInAppKeyboard == null) return;
        boolean folderRename = mSheets.isFolderRenameActive();
        mInAppKeyboard.setTextFieldHoldsFocus(isFrontPageFieldTyping());
        switch (com.termux.app.terminal.inappkeyboard.TypingClaim.owner(palette, sheet,
            folderRename || isTerminalRenameActive(), drawer, isDisplayWindowTyping(),
            isFrontPageFieldTyping())) {
            case COMMAND_PALETTE:
                mInAppKeyboard.setKeyValueInterceptor(getCommandPaletteController());
                break;
            case TERMINAL_SHEET:
                mInAppKeyboard.setKeyValueInterceptor(getTerminalSheetController());
                break;
            case RENAME:
                // A folder rename is stronger than the drawer search under it, and a terminal
                // rename chip installed its own interceptor, which the closing drawer's spring
                // landing hundreds of ms later must not clear: its finish path restores the claim.
                if (folderRename) mInAppKeyboard.setKeyValueInterceptor(mSheets.folderRenameController());
                break;
            case APP_DRAWER:
                mInAppKeyboard.setKeyValueInterceptor(mSheets.appDrawerControllerIfBuilt() == null
                    ? null : mSheets.appDrawerControllerIfBuilt().getSearchController());
                break;
            case DISPLAY:
                mInAppKeyboard.setKeyValueInterceptor(x11KeyboardBridge());
                break;
            case ASSISTANT: {
                com.termux.app.terminal.inappkeyboard.TypingPage page = typingFrontPage();
                mInAppKeyboard.setKeyValueInterceptor(page == null ? null : page.typingKeys());
                break;
            }
            default:
                mInAppKeyboard.setKeyValueInterceptor(null);
                break;
        }
    }

    /**
     * The wall's last settled place, which is the window the keyboard's keys belong to: a swipe
     * in flight keeps its keys with the window it started from until the wall lands. The display
     * window in front of the Terminal is the place {@link com.termux.app.page.PageKind#DISPLAY}.
     */
    @Nullable private com.termux.app.page.PageKind mSettledWallPage;

    @NonNull
    private com.termux.app.page.PageKind settledWallPage() {
        return mSettledWallPage != null ? mSettledWallPage : currentWallPage();
    }

    /** Whether the settled place is the display window, with a display attached to type into. */
    private boolean isDisplayWindowTyping() {
        return settledWallPage() == com.termux.app.page.PageKind.DISPLAY && mDisplayServer.controller() != null
            && mPaneWallController != null && mPaneWallController.displayWindow() != null;
    }

    /** The front page when it is one the launcher's keyboard types into. */
    @Nullable
    private com.termux.app.terminal.inappkeyboard.TypingPage typingFrontPage() {
        com.termux.app.page.Page front = mPages.front();
        // A Linux window in front of the Terminal's row takes the keys (#392).
        if (front != null && front.kind() == com.termux.app.page.PageKind.TERMINAL
                && mLinuxWindows != null && linuxWindowInFront() != 0L) {
            return mLinuxWindows.page();
        }
        // A focused Linux Float on Home takes the keys (#388).
        if (front != null && front.kind() == com.termux.app.page.PageKind.HOME
                && mPaneController != null) {
            com.termux.app.terminal.PaneContentFrame floated = mPaneController.activeLinuxPaneFrame();
            if (floated instanceof com.termux.app.terminal.inappkeyboard.TypingPage) {
                return (com.termux.app.terminal.inappkeyboard.TypingPage) floated;
            }
        }
        // A Linux pane in focus in the Terminal's split takes the keys as a terminal pane would.
        if (front != null && front.kind() == com.termux.app.page.PageKind.TERMINAL
                && mPaneController != null) {
            com.termux.app.terminal.PaneContentFrame pane = mPaneController.activeLinuxPaneFrame();
            if (pane instanceof com.termux.app.terminal.inappkeyboard.TypingPage) {
                return (com.termux.app.terminal.inappkeyboard.TypingPage) pane;
            }
        }
        return front instanceof com.termux.app.terminal.inappkeyboard.TypingPage
            ? (com.termux.app.terminal.inappkeyboard.TypingPage) front : null;
    }

    /** Whether the front page is one of the launcher's typing pages and one of its text fields holds focus. */
    private boolean isFrontPageFieldTyping() {
        com.termux.app.terminal.inappkeyboard.TypingPage page = typingFrontPage();
        return page != null && page.isTyping();
    }

    /**
     * A page's text field took or lost focus: it is typed into with the launcher's keyboard,
     * which comes up for it, and never the phone's.
     */
    private void onPageFieldFocus(boolean focused) {
        // With the launcher's keyboard turned off the phone's is the only one there is: the field
        // takes it as any text field does.
        boolean inApp = isInAppKeyboardEnabled();
        View field = getCurrentFocus();
        if (field instanceof EditText) ((EditText) field).setShowSoftInputOnFocus(!inApp);
        if (!inApp) {
            if (focused && field instanceof EditText) {
                onSystemImeRequested();
                KeyboardUtils.showSoftKeyboard(this, field);
            }
            return;
        }
        if (mInAppKeyboard == null) return;
        mInAppKeyboard.setTextFieldHoldsFocus(isFrontPageFieldTyping());
        if (focused) mInAppKeyboard.show(
            com.termux.app.terminal.inappkeyboard.TermuxInAppKeyboard.ShowReason.FOCUS);
        restoreInAppKeyboardTypingClaim();
    }

    private final VoiceInputSession.Host mVoiceInputHost = new VoiceInputSession.Host() {
        @Override
        public void onListening() {
            if (mInAppKeyboard != null) mInAppKeyboard.setVoiceTypingActive(true);
            showVoiceIndicator();
            // Only a shell in front can show where the words will land; the text itself goes
            // wherever ✓ finds a taker, later.
            mDictationMarks.listen(currentWallPage() == com.termux.app.page.PageKind.TERMINAL
                ? getCurrentSession() : null);
        }

        @Override
        public void onSegmentCaptured() {
            if (mVoiceIndicator != null) mVoiceIndicator.onSegmentCaptured();
        }

        @Override
        public void onSegmentSettled() {
            if (mVoiceIndicator != null) mVoiceIndicator.onSegmentSettled();
        }

        @Override
        public void onSpeechReady() {
            mVoiceSpeechWarming = false;
            refreshVoiceWarmUp();
        }

        @Override
        public void onLevel(float rms, boolean voiced, float noiseFloor) {
            // A dictation from the voice key belongs to the keyboard that started it, and the
            // keyboard can go down without telling the visibility listener (a focus hide); the
            // level tick, some 30 times a second, is where that is noticed.
            if (mVoiceTiedToKeyboard && (mInAppKeyboard == null || !mInAppKeyboard.isVisible())) {
                endVoiceInput(VoiceInputSession.EndReason.HIDDEN);
                return;
            }
            if (mVoiceIndicator != null) mVoiceIndicator.setLevel(rms, voiced, noiseFloor);
        }

        @Override
        public void onSpeechLanguage(@NonNull String iso, boolean differsFromHint) {
            mVoiceSpokenLanguage = iso;
            if (mVoiceCleanup != null) mVoiceCleanup.setLanguageHint(iso);
            // Named only when it was heard and is not the keyboard's or the phone's language, so
            // someone dictating in their own language sees nothing new.
            if (mVoiceIndicator != null) {
                mVoiceIndicator.setSpokenLanguage(differsFromHint ? VoiceLanguage.displayName(iso, userLocale()) : null);
            }
        }

        @Override
        public void onTranscript(@NonNull String text) {
            appendVoicePhrase(text);
        }

        @Override
        public void onDraining() {
            if (mVoiceIndicator != null) mVoiceIndicator.setTranscribing();
            refreshVoiceWarmUp();
        }

        @Override
        public void onFailure(@NonNull String code, @NonNull String message, boolean anyTranscriptDelivered) {
            String detail = message.isEmpty() ? code : message;
            if (anyTranscriptDelivered || !mVoiceTiedToKeyboard
                || mInAppKeyboard == null || !mInAppKeyboard.isVisible()) {
                // Text already came through, or nothing to fall back for (the recognizer types
                // where the keyboard does, which the Dictate key may not have): just say why.
                AppNotice.show(TermuxActivity.this, R.drawable.ic_rl_mic, getString(R.string.voice_input_stopped, detail), true);
                return;
            }
            AppNotice.show(TermuxActivity.this, R.drawable.ic_rl_mic, getString(R.string.voice_input_fallback, detail), true);
            launchVoiceTyping(false);
        }

        @Override
        public void onEnded(@NonNull VoiceInputSession.EndReason reason) {
            mVoiceInput = null;
            mVoiceSpeechWarming = false;
            // A discard has already said cancel; this is the microphone closing on its own terms.
            mDictationMarks.end(reason == VoiceInputSession.EndReason.FAILED
                || reason == VoiceInputSession.EndReason.DESTROYED);
            // The voice key un-presses now; the pill stays with the text.
            if (mInAppKeyboard != null) mInAppKeyboard.setVoiceTypingActive(false);
            refreshVoiceWarmUp();
            finishVoiceSession(reason);
            // After the finish, which still reads the session's language; the card's strip moves
            // on to the outcome, which never names it.
            mVoiceSpokenLanguage = null;
            if (mVoiceIndicator != null) mVoiceIndicator.setSpokenLanguage(null);
        }
    };

    static Intent createVoiceTypingIntent(@NonNull Context context, boolean chooser) {
        Intent recognition = new Intent(android.speech.RecognizerIntent.ACTION_RECOGNIZE_SPEECH);
        recognition.putExtra(android.speech.RecognizerIntent.EXTRA_LANGUAGE_MODEL,
            android.speech.RecognizerIntent.LANGUAGE_MODEL_FREE_FORM);
        return chooser ? Intent.createChooser(recognition,
            context.getString(R.string.voice_typing_chooser_title)) : recognition;
    }

    @Override
    public void onRequestPermissionsResult(int requestCode, @NonNull String[] permissions, @NonNull int[] grantResults) {
        super.onRequestPermissionsResult(requestCode, permissions, grantResults);
        Logger.logVerbose(LOG_TAG, "onRequestPermissionsResult: requestCode: " + requestCode + ", permissions: " + Arrays.toString(permissions) + ", grantResults: " + Arrays.toString(grantResults));
        if (requestCode == PermissionUtils.REQUEST_GRANT_STORAGE_PERMISSION) {
            requestStoragePermission(true);
        } else if (requestCode == REQUEST_CODE_WEATHER_LOCATION) {
            if (grantResults.length > 0
                && grantResults[0] == android.content.pm.PackageManager.PERMISSION_GRANTED) {
                ensureWeatherController().forceRefresh();
            }
        } else if (requestCode == REQUEST_CODE_SETUP_NOTIFICATIONS) {
            if (mSetupWizard != null) mSetupWizard.onNotificationPermissionResult(
                grantResults.length > 0
                    && grantResults[0] == android.content.pm.PackageManager.PERMISSION_GRANTED);
        } else if (requestCode == REQUEST_CODE_WALLPAPER_READ_PERMISSION) {
            if (grantResults.length > 0
                && grantResults[0] == android.content.pm.PackageManager.PERMISSION_GRANTED) {
                mWallpaperReadPermissionDenied = false;
                refreshWallpaperPicture();
                mChrome.onWallpaperChanged();
            }
            if (mSetupWizard != null) mSetupWizard.onWallpaperPermissionResult();
        } else if (requestCode == REQUEST_CODE_WIDGET_CALENDAR) {
            if (mWidgetPaneController != null) mWidgetPaneController.onCalendarPermissionChanged();
        } else if (requestCode == REQUEST_CODE_PALETTE_CONTACTS) {
            // The palette's contact search: its rows rebuild themselves
            // from the result, granted or not.
            boolean granted = grantResults.length > 0
                && grantResults[0] == android.content.pm.PackageManager.PERMISSION_GRANTED;
            getCommandPaletteController().onContactsAccessChanged(granted);
        } else if (requestCode == REQUEST_CODE_VOICE_INPUT_MICROPHONE) {
            if (grantResults.length > 0
                && grantResults[0] == android.content.pm.PackageManager.PERMISSION_GRANTED) {
                startOnDeviceVoiceInput(mVoiceMicrophoneAskedFromKeyboard);
            } else {
                // Refused: the system recognizer asks for the microphone itself.
                AppNotice.show(this, R.drawable.ic_rl_mic, getString(R.string.voice_input_fallback,
                    getString(R.string.voice_input_permission_denied)), false);
                launchVoiceTyping(false);
            }
        }
    }

