    /** Reset the window and every currently visible pane to the same benchmark origin. */
    void resetTerminalPerformanceMetrics() {
        mTerminalFrameMetricsMonitor.reset();
        for (TerminalView pane : getTerminalPaneViews()) pane.resetRenderMetrics();
    }

    /** The pane currently displaying {@code session}, or null if none. */
    @Nullable
    TerminalView getTerminalViewForSession(@Nullable TerminalSession session) {
        return mPaneController == null ? null : mPaneController.getViewForSession(session);
    }

    /** The pane-tree engine (source of truth for panes/tabs). */
    public com.termux.app.terminal.TerminalPaneController getPaneController() {
        return mPaneController;
    }

    /** Mark {@code view} as the focused pane (touch / programmatic). */
    public void setActivePane(TerminalView view) {
        if (view == null || mPaneController == null) return;
        TerminalSession s = view.getCurrentSession();
        if (s != null) mPaneController.focusSession(s);
    }

    public boolean isSecondaryPaneSession(@Nullable TerminalSession s) {
        // A shell is "secondary" (hidden from the drawer) unless it is the representative of some
        // session = the focused pane of that session's current window.
        if (s == null) return true;
        for (WSession ws : mWSessions)
            if (mPaneController != null
                && mPaneController.windowActiveSession(ws.currentWindow()) == s) return false;
        return true;
    }

    // ---- Window / session helpers ----

    @Nullable private WSession wsessionOwning(com.termux.app.terminal.TerminalPaneController.Window w) {
        for (WSession ws : mWSessions)
            if (ws.windows.contains(w)) return ws;
        return null;
    }

    /** Stable name of the tmux-style session containing {@code shell}. */
    @Nullable
    public String getSessionNameFor(@Nullable TerminalSession shell) {
        if (shell == null || mPaneController == null) return null;
        WSession ws = wsessionOwning(mPaneController.windowOf(shell));
        return ws == null ? TerminalNamePolicy.normalizeSession(shell.mSessionName) : ws.name;
    }

    /** 1-based number of the current tmux-style session, or -1 before any session exists. */
    int getCurrentSessionNumber() {
        int index = mCurrentWSession == null ? -1 : mWSessions.indexOf(mCurrentWSession);
        return index < 0 ? -1 : index + 1;
    }

    /** 1-based number of the tmux-style session containing {@code shell}, or -1 when unowned. */
    int getSessionNumberFor(@Nullable TerminalSession shell) {
        if (shell == null || mPaneController == null) return -1;
        WSession ws = wsessionOwning(mPaneController.windowOf(shell));
        int index = ws == null ? -1 : mWSessions.indexOf(ws);
        return index < 0 ? -1 : index + 1;
    }

    /** Ctrl+Alt+Shift+R entry point: rename the current session, not its window or focused pane. */
    boolean promptCurrentSessionRename() {
        return beginTerminalRename(com.termux.app.terminal.rename.TerminalRenameTarget.SESSION);
    }

    /** Ctrl+Alt+R entry point: rename the current window, the tab it occupies in the window bar. */
    boolean promptCurrentWindowRename() {
        if (isDisplayWindowInFront()) return false;
        return beginTerminalRename(com.termux.app.terminal.rename.TerminalRenameTarget.WINDOW);
    }

    /**
     * Renames the current session without prompting.
     *
     * <p>Seam for registry actions ({@code session.rename}) and for a naming backend: a remote
     * caller supplies the name up front, so the editor cannot be used — it has no way to return a
     * result. Returns false when there is no session to rename.
     */
    boolean renameCurrentSessionTo(@Nullable String name) {
        if (mCurrentWSession == null || !mWSessions.contains(mCurrentWSession)) return false;
        mCurrentWSession.name = TerminalNamePolicy.normalizeSession(name);
        rebuildDrawerSessions();
        return true;
    }

    /**
     * Renames the current window without prompting. Seam for {@code window.rename}.
     *
     * <p>An empty name clears the label, which puts the tab back on its derived process/directory
     * text rather than leaving it blank. Returns false when there is no window to rename.
     */
    boolean renameCurrentWindowTo(@Nullable String name) {
        // The display window is named by its display; the terminal window behind it is not the
        // one in front to rename.
        if (isDisplayWindowInFront()) return false;
        if (mPaneController == null || mCurrentWSession == null
            || mCurrentWSession.windows.isEmpty()) return false;
        mPaneController.setWindowName(mCurrentWSession.currentWindow(), name);
        refreshTerminalWindowBar();
        return true;
    }

    /** The name the current window kept, after the policy capped it. */
    @Nullable
    String getCurrentWindowName() {
        if (mPaneController == null || mCurrentWSession == null
            || mCurrentWSession.windows.isEmpty()) return null;
        return mPaneController.windowName(mCurrentWSession.currentWindow());
    }

    /** Immutable projection consumed by the searchable session browser. */
    @NonNull
    public java.util.List<com.termux.app.terminal.SessionBrowserModel.Session> getSessionBrowserSessions() {
        java.util.List<com.termux.app.terminal.SessionBrowserModel.Session> sessions =
            new java.util.ArrayList<>();
        if (mPaneController == null) return sessions;
        for (int sessionIndex = 0; sessionIndex < mWSessions.size(); sessionIndex++) {
            WSession ws = mWSessions.get(sessionIndex);
            java.util.List<com.termux.app.terminal.SessionBrowserModel.Window> windows =
                new java.util.ArrayList<>();
            for (int windowIndex = 0; windowIndex < ws.windows.size(); windowIndex++) {
                com.termux.app.terminal.TerminalPaneController.Window window = ws.windows.get(windowIndex);
                java.util.List<com.termux.app.terminal.SessionBrowserModel.Pane> panes =
                    new java.util.ArrayList<>();
                java.util.List<TerminalSession> shells = mPaneController.shellsOf(window);
                TerminalSession activeShell = mPaneController.windowActiveSession(window);
                int activePane = activeShell == null ? 0 : shells.indexOf(activeShell);
                if (activePane < 0) activePane = 0;
                for (TerminalSession shell : shells) {
                    String foreground = null;
                    com.termux.app.statusbar.WindowForegroundResolver.ForegroundInfo info =
                        mWindowForegroundResolver == null ? null
                            : mWindowForegroundResolver.get(shell.getPid());
                    if (info != null && !info.idle) {
                        foreground = info.processName;
                        if (info.openFile != null) {
                            foreground = foreground == null ? info.openFile
                                : foreground + " · " + info.openFile;
                        }
                    }
                    if (foreground == null) foreground = shell.getTitle();
                    com.termux.app.terminal.AgentStatus agentStatus =
                        mAgentStatuses.get(shell.getPid());
                    panes.add(new com.termux.app.terminal.SessionBrowserModel.Pane(
                        shell.getCwd(), foreground,
                        agentStatus == null ? null : agentStatus.state));
                }
                String named = mPaneController.windowName(window);
                String windowLabel = named != null ? named
                    : com.termux.app.terminal.TerminalWindowBar
                        .itemFor(activeShell, windowIndex).spokenLabel;
                windows.add(new com.termux.app.terminal.SessionBrowserModel.Window(window.id,
                    windowIndex, windowIndex == ws.current, activePane, panes, windowLabel));
            }
            // Home floats are windows of the session too: listed under it, marked as floats.
            if (ws == mCurrentWSession) {
                for (com.termux.app.terminal.TerminalPaneController.Window window
                        : mPaneController.homeFloats()) {
                    TerminalSession shell = mPaneController.windowActiveSession(window);
                    if (shell == null) continue;
                    java.util.List<com.termux.app.terminal.SessionBrowserModel.Pane> panes =
                        new java.util.ArrayList<>();
                    panes.add(new com.termux.app.terminal.SessionBrowserModel.Pane(
                        shell.getCwd(), shell.getTitle(), null, true));
                    String named = mPaneController.windowName(window);
                    int index = windows.size();
                    windows.add(new com.termux.app.terminal.SessionBrowserModel.Window(window.id,
                        index, false, 0, panes, named != null ? named
                            : com.termux.app.terminal.TerminalWindowBar.itemFor(shell, index)
                                .spokenLabel));
                }
            }
            sessions.add(new com.termux.app.terminal.SessionBrowserModel.Session(ws.id, sessionIndex,
                ws == mCurrentWSession, ws.name, windows));
        }
        return sessions;
    }

    /** Select a browser row's current window and focused pane. */
    public boolean activateBrowserSession(int index) {
        if (mPaneController == null || index < 0 || index >= mWSessions.size()) return false;
        WSession ws = mWSessions.get(index);
        if (ws.windows.isEmpty()) return false;
        TerminalSession shell = mPaneController.windowActiveSession(ws.currentWindow());
        if (shell == null) return false;
        if (getTermuxTerminalSessionClient() != null) {
            getTermuxTerminalSessionClient().setCurrentSession(shell);
        } else {
            activateSessionInPanes(shell);
        }
        return true;
    }

    /** Activate exactly the stable session/window pair selected by the sessions tree. */
    public boolean activateBrowserWindow(long sessionId, long windowId) {
        if (mPaneController == null) return false;
        WSession targetSession = null;
        com.termux.app.terminal.TerminalPaneController.Window targetWindow = null;
        for (WSession session : mWSessions) {
            if (session.id != sessionId) continue;
            targetSession = session;
            for (com.termux.app.terminal.TerminalPaneController.Window window : session.windows) {
                if (window.id == windowId) {
                    targetWindow = window;
                    break;
                }
            }
            break;
        }
        if (targetSession == null || targetWindow == null) return false;
        targetSession.current = targetSession.windows.indexOf(targetWindow);
        TerminalSession shell = mPaneController.windowActiveSession(targetWindow);
        if (shell == null) return false;
        if (getTermuxTerminalSessionClient() != null) {
            getTermuxTerminalSessionClient().setCurrentSession(shell);
        } else {
            activateSessionInPanes(shell);
        }
        return true;
    }

    /** The browser index of a stable session id, or -1; the drawer names sessions by id. */
    public int browserSessionIndex(long sessionId) {
        for (int i = 0; i < mWSessions.size(); i++) {
            if (mWSessions.get(i).id == sessionId) return i;
        }
        return -1;
    }

    /** Create a fresh top-level session from the currently focused pane's CWD. */
    public boolean createBrowserSession() {
        com.termux.app.terminal.TermuxTerminalSessionActivityClient client =
            getTermuxTerminalSessionClient();
        TerminalSession current = getCurrentSession();
        return client != null && client.addNewSessionAtWorkingDirectory(
            current == null ? null : current.getCwd(), false, null);
    }

    /** Clone a selected session as a fresh one-window shell at its focused pane's CWD. */
    public boolean cloneBrowserSession(int index) {
        if (mPaneController == null || index < 0 || index >= mWSessions.size()) return false;
        WSession ws = mWSessions.get(index);
        if (ws.windows.isEmpty()) return false;
        TerminalSession source = mPaneController.windowActiveSession(ws.currentWindow());
        com.termux.app.terminal.TermuxTerminalSessionActivityClient client =
            getTermuxTerminalSessionClient();
        return source != null && client != null
            && client.addNewSessionAtWorkingDirectory(source.getCwd(), false, null);
    }

    public boolean cloneCurrentBrowserSession() {
        int index = mCurrentWSession == null ? -1 : mWSessions.indexOf(mCurrentWSession);
        return cloneBrowserSession(index);
    }

    public boolean renameBrowserSession(int index, @Nullable String name) {
        if (index < 0 || index >= mWSessions.size()) return false;
        mWSessions.get(index).name = TerminalNamePolicy.normalizeSession(name);
        rebuildDrawerSessions();
        return true;
    }

    /**
     * The label a browser-indexed session actually kept. TerminalNamePolicy caps it, so what was
     * asked for and what was stored can differ; callers that report back read this.
     */
    @Nullable
    String getBrowserSessionName(int index) {
        if (index < 0 || index >= mWSessions.size()) return null;
        return mWSessions.get(index).name;
    }

    /** Close any browser-selected session, without first activating it. */
    public boolean closeBrowserSession(int index) {
        if (mPaneController == null || index < 0 || index >= mWSessions.size()) return false;
        WSession ws = mWSessions.get(index);
        boolean wasCurrent = ws == mCurrentWSession;
        if (wasCurrent) captureTerminalDeparture();
        for (com.termux.app.terminal.TerminalPaneController.Window window :
                new java.util.ArrayList<>(ws.windows)) {
            for (TerminalSession shell : mPaneController.removeWindow(window)) {
                if (mTermuxService != null) mTermuxService.killTermuxSession(shell);
            }
        }
        mWSessions.remove(ws);
        if (wasCurrent) {
            mCurrentWSession = null;
            if (!mWSessions.isEmpty()) {
                mCurrentWSession = mWSessions.get(Math.min(index, mWSessions.size() - 1));
                mPaneController.showWindow(mCurrentWSession.currentWindow());
                animateTerminalSessionLifecycleArrival(-1);
            } else {
                // The row's last window is gone: the last Home page slides in (see
                // showNextSessionAfterClose).
                if (mPaneWallController != null) mPaneWallController.goToLastHomePage(isVisible());
            }
        }
        rebuildDrawerSessions();
        return true;
    }

    private void onWindowForegroundResolved() {
        refreshTerminalWindowBar();
        syncBackgroundProcessStack();
        // What runs in a pane is part of the arrangement the autosave keeps for a kill; a poll
        // that moved only a CPU reading changes nothing it keeps.
        int programs = paneProgramsKey();
        if (programs != mPaneProgramsKey) {
            mPaneProgramsKey = programs;
            scheduleArrangementAutosave();
        }
    }

    /** Last {@link #paneProgramsKey} an autosave was scheduled for. */
    private int mPaneProgramsKey;

    /**
     * Folds every live pane's resolved foreground program (pid and argv) into one number, so the
     * poll can tell whether any pane's program changed. No allocation: it runs on every poll.
     */
    private int paneProgramsKey() {
        if (mPaneController == null || mWindowForegroundResolver == null) return 0;
        int key = 17;
        for (WSession ws : mWSessions) {
            for (com.termux.app.terminal.TerminalPaneController.Window window : ws.windows) {
                for (TerminalSession shell : mPaneController.shellsOf(window)) {
                    com.termux.app.statusbar.WindowForegroundResolver.ForegroundInfo info =
                        mWindowForegroundResolver.get(shell.getPid());
                    key = key * 31 + (info == null ? 0 : info.foregroundPid * 31 + info.command.hashCode());
                }
            }
        }
        return key;
    }

    /**
     * Seam for {@code window.select}: switch windows by row place, the display window's included.
     * False when out of range.
     */
    boolean selectWindow(int index) {
        if (mPaneController == null || index < 0 || index >= rowWindowCount()) return false;
        showRowWindow(index);
        return true;
    }

    /**
     * Moves the Terminal's window at row place {@code from} to {@code to}: a chip dropped in the
     * window bar, {@code window.move}, the palette's Move window left / right. The row holds
     * terminal windows only (ADR 0015). The window in front stays in front and its index follows
     * it. Everything that reads the row — the window bar,
     * the drawer, the wall's inner index, the Ctrl+Alt window keys, Saved sessions — reads
     * {@link WSession#windows} and the display's place, so one rebuild brings them all along.
     * False when either place is outside the row.
     */
    boolean moveWindow(int from, int to) {
        int count = rowWindowCount();
        if (from < 0 || from >= count || to < 0 || to >= count) return false;
        if (from == to) return true;
        WSession ws = mCurrentWSession;
        if (ws != null) {
            // Either kind moves among the other (#392); the terminal window in front keeps its place.
            com.termux.app.terminal.TerminalPaneController.Window front = ws.currentWindow();
            ws.row.move(ws.windows, from, to);
            if (front != null) ws.current = Math.max(0, ws.windows.indexOf(front));
        }
        syncLinuxFront();
        rebuildDrawerSessions();
        refreshTerminalWindowBar();
        return true;
    }

    /**
     * Consume ({@code pane.consume}, Niri's word; {@link com.termux.app.terminal.ColumnPolicy}):
     * the current window's neighbour in the row — on the right, or on the left when
     * {@code fromLeft} — joins it as panes beside its focused pane and leaves the row. The current
     * window stays current and on screen, its index following it when the neighbour stood before
     * it; the consumed window's focused pane takes the focus. No session closes. Home floats are
     * not in the row, so a consume never takes one. False at the row's end on that side, with one
     * window, or when the controller refuses.
     */
    boolean consumeWindow(boolean fromLeft) {
        if (mPaneController == null || mCurrentWSession == null) return false;
        // The display window has no panes to give or take: it neither consumes nor is consumed.
        // Nor has a Linux window.
        if (isDisplayWindowInFront() || linuxWindowInFront() != 0L) return false;
        WSession ws = mCurrentWSession;
        int current = ws.current;
        int source = com.termux.app.terminal.ColumnPolicy.consumeSource(current, ws.windows.size(),
            fromLeft);
        if (source == com.termux.app.terminal.ColumnPolicy.INVALID) return false;
        com.termux.app.terminal.TerminalPaneController.Window into = ws.windows.get(current);
        com.termux.app.terminal.TerminalPaneController.Window taken = ws.windows.get(source);
        // The row is settled before the controller announces the change: what hears it (the
        // drawer's rebuild) reads this row, which must no longer hold the consumed window.
        ws.windows.remove(source);
        ws.current = com.termux.app.terminal.ColumnPolicy.currentAfterRemove(current, source);
        if (!mPaneController.consumeWindow(into, taken, fromLeft)) {
            ws.windows.add(source, taken);
            ws.current = current;
            return false;
        }
        if (mPaneController.activeWindow() != into) mPaneController.showWindow(into);
        rebuildDrawerSessions();
        return true;
    }

    /**
     * Expel ({@code pane.expel}, Niri's word; {@link com.termux.app.terminal.ColumnPolicy}): the
     * current window's focused pane leaves it for a new window of its own, right after it in the
     * row, or right before it when {@code toLeft}. Focus goes with the pane, as in Niri: the new
     * window becomes current and the Terminal slides to it the way a new window arrives, from the
     * side it was placed on. No session closes. False for a window of one pane, and while a Home
     * float has the focus: a float is not in the row.
     */
    boolean expelPane(boolean toLeft) {
        if (mPaneController == null || mCurrentWSession == null) return false;
        if (mPaneController.focusedHomeFloat() != null) return false;
        // The display window has no pane to expel, nor has a Linux window.
        if (isDisplayWindowInFront() || linuxWindowInFront() != 0L) return false;
        WSession ws = mCurrentWSession;
        com.termux.app.terminal.TerminalPaneController.Window from = ws.currentWindow();
        int target = com.termux.app.terminal.ColumnPolicy.expelTarget(ws.current,
            ws.windows.size(), toLeft);
        if (from == null || target == com.termux.app.terminal.ColumnPolicy.INVALID) return false;
        // The window as it was slides off; the new one arrives in its place.
        captureTerminalDeparture();
        com.termux.app.terminal.TerminalPaneController.Window expelled =
            mPaneController.expelPane(from);
        if (expelled == null) {
            dropTerminalDepartureSnapshot();
            return false;
        }
        // Right after the window in front in the row (right before it when toLeft), so a display
        // window beside it stays on its far side.
        int at = insertRowWindowAt(expelled, ws.current + (toLeft ? 0 : 1));
        ws.current = com.termux.app.terminal.ColumnPolicy.currentAfterExpel(at);
        mPaneController.showWindow(expelled);
        animateTerminalWindowLifecycleArrival(toLeft ? -1 : 1);
        rebuildDrawerSessions();
        return true;
    }

    /** Number of windows in the current row, the display window's included. */
    int getCurrentWindowCount() {
        return rowWindowCount();
    }

    /** Row place of the window in front, the display window's included, or -1. */
    int getCurrentWindowIndex() {
        return rowWindowCount() == 0 ? -1 : rowCurrentIndex();
    }

    /** Name of the current tmux-style session, or null when unnamed. */
    @Nullable
    String getCurrentSessionName() {
        return mCurrentWSession == null ? null : mCurrentWSession.name;
    }

    /**
     * One pane of a snapshot whose program is still to be read: the view tree's part (pid, agent)
     * is taken on the main thread, {@link #resolve} does the /proc reads.
     */
    private static final class PaneProbe {
        final com.termux.app.terminal.TerminalWorkspace.Pane pane;
        final int pid;
        @Nullable final String agentName;
        @Nullable final String agentSessionId;

        PaneProbe(@NonNull com.termux.app.terminal.TerminalWorkspace.Pane pane, int pid,
                  @Nullable String agentName, @Nullable String agentSessionId) {
            this.pane = pane;
            this.pid = pid;
            this.agentName = agentName;
            this.agentSessionId = agentSessionId;
        }

        void resolve() {
            java.util.List<String> command =
                com.termux.app.statusbar.WindowForegroundResolver.captureCommand(pid);
            // The conversation id the agent in this pane reported, kept only while that agent is
            // still what runs there.
            String sessionId = com.termux.app.terminal.AgentResume.sessionToSave(
                command, agentName, agentSessionId);
            pane.completeCapture(command, sessionId == null ? null : agentName, sessionId);
        }
    }

    /** Capture the complete live session/window/pane topology into a durable JSON file. */
    @NonNull
    public com.termux.app.terminal.TerminalWorkspace saveWorkspace(
            @NonNull String requestedName, boolean overwrite)
            throws com.termux.app.terminal.TerminalWorkspace.WorkspaceException {
        String name = com.termux.app.terminal.TerminalWorkspaceStore.validateName(requestedName);
        java.util.List<PaneProbe> probes = new java.util.ArrayList<>();
        com.termux.app.terminal.TerminalWorkspace workspace = snapshotArrangement(name, probes);
        if (workspace == null) {
            throw new com.termux.app.terminal.TerminalWorkspace.WorkspaceException(
                "no_session", "There are no terminal sessions to save");
        }
        // Explicit Save answers with the workspace, so it reads what runs here, fresh.
        for (PaneProbe probe : probes) probe.resolve();
        workspace.validate();
        new com.termux.app.terminal.TerminalWorkspaceStore().save(name, workspace, overwrite);
        return workspace;
    }

    /**
     * Reads a live pane for a save: its folder and name now, and a probe to read the program
     * from /proc (and the agent's conversation id) on whichever thread the caller chooses.
     */
    @NonNull
    private com.termux.app.terminal.TerminalPaneController.WorkspacePaneCapture workspacePaneCapture(
            @NonNull java.util.List<PaneProbe> probes) {
        return shell -> {
            String cwd = shell.getCwd();
            if (cwd == null) cwd = getProperties().getDefaultWorkingDirectory();
            com.termux.app.terminal.TerminalWorkspace.Pane pane =
                new com.termux.app.terminal.TerminalWorkspace.Pane(cwd, shell.mSessionName, null);
            probes.add(new PaneProbe(pane, shell.getPid(), shell.mAgentName, shell.mAgentSessionId));
            return pane;
        };
    }

    /**
     * The live arrangement — every session's row of windows with their trees, then the Home
     * floats — in the Saved sessions model under {@code name}, or null when there is nothing
     * (no window and no float). Every pane keeps the program running in it, read from the system
     * now rather than from the window pills' cache; the autosave keeps them too. The panes come
     * back without their program: the caller resolves {@code probes} (one per pane) before it
     * uses the workspace, which reads /proc and so can run off the main thread.
     */
    @Nullable
    private com.termux.app.terminal.TerminalWorkspace snapshotArrangement(@NonNull String name,
            @NonNull java.util.List<PaneProbe> probes) {
        if (mPaneController == null) return null;
        boolean anyWindow = false;
        for (WSession ws : mWSessions) anyWindow |= !ws.windows.isEmpty();
        if (!anyWindow && mPaneController.homeFloatCount() == 0) return null;
        java.util.List<com.termux.app.terminal.TerminalWorkspace.Session> sessions =
            new java.util.ArrayList<>();
        com.termux.app.terminal.TerminalPaneController.WorkspacePaneCapture capture =
            workspacePaneCapture(probes);
        // Home floats are windows of the current session (the drawer lists them under it): they
        // are saved after its row's windows, in the order they were opened, as the chips run.
        java.util.List<com.termux.app.terminal.TerminalPaneController.Window> homeFloats =
            chipFloats();
        WSession floatsSession = mCurrentWSession != null && !mCurrentWSession.windows.isEmpty()
            ? mCurrentWSession : null;
        for (WSession ws : mWSessions) {
            if (ws.windows.isEmpty()) continue;
            if (floatsSession == null) floatsSession = ws;
            java.util.List<com.termux.app.terminal.TerminalWorkspace.Window> windows =
                new java.util.ArrayList<>();
            for (com.termux.app.terminal.TerminalPaneController.Window window : ws.windows)
                windows.add(mPaneController.snapshotWorkspaceWindow(window, capture));
            int currentWindow = Math.max(0, Math.min(ws.current, windows.size() - 1));
            if (ws == floatsSession) {
                for (com.termux.app.terminal.TerminalPaneController.Window window : homeFloats)
                    windows.add(mPaneController.snapshotWorkspaceWindow(window, capture));
            }
            sessions.add(new com.termux.app.terminal.TerminalWorkspace.Session(ws.name,
                currentWindow, windows));
        }
        // The sessions waiting behind the wall's places, each saved as a session of its own after
        // the wall: the file keeps every shell, and a load folds them onto the wall as pages
        // (#357; the saved form of a place's sessions is #359's).
        java.util.List<com.termux.app.terminal.TerminalPaneController.Window> waiting =
            new java.util.ArrayList<>();
        mPlaceSessions.allWaiting(waiting);
        WSession first = sessions.isEmpty() ? null : firstNonEmptyWSession();
        for (com.termux.app.terminal.TerminalPaneController.Window window : waiting) {
            // Which of the first session's windows holds the place this one waits in, so a cold
            // start puts it back in that place (#359); -1 when that window is in no first row.
            com.termux.app.terminal.TerminalPaneController.Window front =
                mPlaceSessions.frontOf(window);
            int behind = first == null || front == null ? -1 : first.windows.indexOf(front);
            sessions.add(new com.termux.app.terminal.TerminalWorkspace.Session(null, 0,
                java.util.Collections.singletonList(
                    mPaneController.snapshotWorkspaceWindow(window, capture)), behind));
        }
        if (floatsSession == null && !homeFloats.isEmpty()) {
            // An empty Terminal with Home floats: they are saved as a session of floats only,
            // which loads back as floats only.
            java.util.List<com.termux.app.terminal.TerminalWorkspace.Window> windows =
                new java.util.ArrayList<>();
            for (com.termux.app.terminal.TerminalPaneController.Window window : homeFloats)
                windows.add(mPaneController.snapshotWorkspaceWindow(window, capture));
            sessions.add(new com.termux.app.terminal.TerminalWorkspace.Session(null, 0, windows));
        }
        if (sessions.isEmpty()) return null;
        // The saved current session counts the sessions written, which skip any with no window.
        int current = 0;
        for (int i = 0, written = 0; i < mWSessions.size(); i++) {
            WSession ws = mWSessions.get(i);
            if (ws.windows.isEmpty()) continue;
            if (ws == mCurrentWSession) current = written;
            written++;
        }
        current = Math.max(0, Math.min(current, sessions.size() - 1));
        return new com.termux.app.terminal.TerminalWorkspace(name, System.currentTimeMillis(),
            current, sessions);
    }

    /** The first session the snapshot writes: the wall, the first with a window. */
    @Nullable
    private WSession firstNonEmptyWSession() {
        for (WSession ws : mWSessions) if (!ws.windows.isEmpty()) return ws;
        return null;
    }

    @NonNull
    public java.util.List<com.termux.app.terminal.TerminalWorkspaceStore.Entry> listWorkspaces()
            throws com.termux.app.terminal.TerminalWorkspace.WorkspaceException {
        return new com.termux.app.terminal.TerminalWorkspaceStore().list();
    }

    /** Overview, whose Saved row lists what was saved: the workspace.picker tool's front door. */
    void showWorkspacePicker() {
        overview().open();
    }

    /** Overview, whose cards' Save saves a session: the workspace.save_prompt tool's front door. */
    void promptSaveWorkspace() {
        overview().open();
    }

    public void deleteWorkspace(@NonNull String name)
            throws com.termux.app.terminal.TerminalWorkspace.WorkspaceException {
        new com.termux.app.terminal.TerminalWorkspaceStore().delete(name);
    }

    /**
     * The shell a restored pane runs its command through and then hands back to.
     *
     * <p>It has to be the user's own shell, because the command was captured from an environment
     * that shell built: {@code ~/.termux/shell} is the symlink {@code chsh} maintains and Termux's
     * own {@code login} follows, so it is the same choice a new session gets. Falling back to a
     * fixed preference order instead would hand a fish user bash, and a command living on a PATH
     * their config sets up would not be found.
     *
     * <p>Deliberately not {@link
     * com.termux.shared.shell.command.environment.UnixShellEnvironment#LOGIN_SHELL_BINARIES}, whose
     * first entry is the {@code login} wrapper script rather than a shell: right for starting a
     * session, but it has no defined {@code -c} behaviour to wrap a command with.
     */
    @Nullable
    private static String wrapperShellPath() {
        java.io.File configured = new java.io.File(
            com.termux.shared.termux.TermuxConstants.TERMUX_HOME_DIR_PATH, ".termux/shell");
        if (configured.canExecute()) {
            try {
                return configured.getCanonicalPath();
            } catch (java.io.IOException ignored) {
                return configured.getAbsolutePath();
            }
        }
        // Same fallback order as login's, so the shell picked here is the shell it would pick.
        String binPath = new com.termux.shared.termux.shell.command.environment.TermuxShellEnvironment()
            .getDefaultBinPath();
        if (binPath != null && !binPath.isEmpty()) {
            for (String shellBinary : new String[] {"bash", "sh"}) {
                java.io.File shellFile = new java.io.File(binPath, shellBinary);
                if (shellFile.canExecute()) return shellFile.getAbsolutePath();
            }
        }
        java.io.File systemShell = new java.io.File("/system/bin/sh");
        return systemShell.canExecute() ? systemShell.getAbsolutePath() : null;
    }

    /** Termux's {@code login}, which sets a session's environment up before exec'ing the shell. */
    @Nullable
    private static String loginProgramPath() {
        String binPath = new com.termux.shared.termux.shell.command.environment.TermuxShellEnvironment()
            .getDefaultBinPath();
        if (binPath == null || binPath.isEmpty()) return null;
        java.io.File login = new java.io.File(binPath, "login");
        return login.canExecute() ? login.getAbsolutePath() : null;
    }

    /** True when the shell parses single-quoted strings fish's way rather than POSIX's. */
    @androidx.annotation.VisibleForTesting
    static boolean isFishShell(@Nullable String shellPath) {
        if (shellPath == null) return false;
        return "fish".equals(new java.io.File(shellPath).getName());
    }

    /** Recreate a saved workspace: each pane opens in its folder and starts its saved program. */
    @NonNull
    public com.termux.app.terminal.TerminalWorkspace.LoadResult loadWorkspace(@NonNull String name, boolean replace)
            throws com.termux.app.terminal.TerminalWorkspace.WorkspaceException {
        requireArrangementRestorable();
        return restoreArrangement(new com.termux.app.terminal.TerminalWorkspaceStore()
            .load(name, homePagesForWorkspace()), replace);
    }

    private void requireArrangementRestorable()
            throws com.termux.app.terminal.TerminalWorkspace.WorkspaceException {
        if (!isSplitPanesEnabled()) {
            throw new com.termux.app.terminal.TerminalWorkspace.WorkspaceException(
                "splits_disabled", "Split panes are disabled while compatibility mode is on");
        }
        if (mPaneController == null || mTermuxService == null) {
            throw new com.termux.app.terminal.TerminalWorkspace.WorkspaceException(
                "unavailable", "The terminal service and pane controller must be ready");
        }
    }

    /**
     * Builds {@code workspace}'s arrangement: fresh shells in the saved working directories
     * running the saved programs, the row's windows and trees, the Home floats on their pages.
     * Saved sessions' Load and the cold start's rebuild from the autosave both come here.
     */
    @NonNull
    private com.termux.app.terminal.TerminalWorkspace.LoadResult restoreArrangement(
            @NonNull com.termux.app.terminal.TerminalWorkspace workspace, boolean replace)
            throws com.termux.app.terminal.TerminalWorkspace.WorkspaceException {
        requireArrangementRestorable();
        int paneCount = workspace.paneCount();
        int eventualCount = replace ? paneCount : mTermuxService.getTermuxSessionsSize() + paneCount;
        if (eventualCount > com.termux.app.terminal.TermuxTerminalSessionActivityClient.MAX_SESSIONS) {
            throw new com.termux.app.terminal.TerminalWorkspace.WorkspaceException(
                "too_many_panes", "Restoring this workspace would create " + eventualCount
                    + " terminals; the limit is "
                    + com.termux.app.terminal.TermuxTerminalSessionActivityClient.MAX_SESSIONS);
        }
        // Saved Home floats float again over Home's pages; with no Home pages (no widget pane)
        // there is nothing to float over, and they load as tiled windows of the row.
        int homePageCount = 0;
        if (savesHomeFloats(workspace)) {
            attachHomeFloatLayer();
            if (mPaneController.homeFloatLayer() != null && mWidgetPaneController != null)
                homePageCount = mWidgetPaneController.homePageCount();
        }

        java.util.List<TerminalSession> createdShells = new java.util.ArrayList<>();
        java.util.List<java.util.List<TerminalSession>> windowShells = new java.util.ArrayList<>();
        int windowCount = 0;
        try {
            for (com.termux.app.terminal.TerminalWorkspace.Session savedSession : workspace.sessions) {
                for (com.termux.app.terminal.TerminalWorkspace.Window savedWindow : savedSession.windows) {
                    java.util.List<com.termux.app.terminal.TerminalWorkspace.Pane> panes =
                        new java.util.ArrayList<>();
                    collectWorkspacePanes(savedWindow.root, panes);
                    // Floating panes come after the tree, matching newWorkspaceWindow's order.
                    for (com.termux.app.terminal.TerminalWorkspace.FloatingPane floating : savedWindow.floats)
                        panes.add(floating.pane);
                    java.util.List<TerminalSession> shells = new java.util.ArrayList<>();
                    for (com.termux.app.terminal.TerminalWorkspace.Pane pane : panes) {
                        TerminalSession shell = createRestoredShell(pane);
                        if (shell == null) {
                            throw new com.termux.app.terminal.TerminalWorkspace.WorkspaceException(
                                "session_create_failed", "Could not create every workspace pane");
                        }
                        shells.add(shell);
                        createdShells.add(shell);
                    }
                    windowShells.add(shells);
                    windowCount++;
                }
            }
        } catch (com.termux.app.terminal.TerminalWorkspace.WorkspaceException e) {
            for (TerminalSession shell : createdShells) mTermuxService.killTermuxSession(shell);
            throw e;
        } catch (RuntimeException e) {
            for (TerminalSession shell : createdShells) mTermuxService.killTermuxSession(shell);
            throw new com.termux.app.terminal.TerminalWorkspace.WorkspaceException(
                "session_create_failed", "Could not create workspace panes: " + e.getMessage(), e);
        }

        java.util.List<WSession> restored = new java.util.ArrayList<>();
        java.util.List<com.termux.app.terminal.TerminalPaneController.Window> restoredWindows =
            new java.util.ArrayList<>();
        java.util.Set<com.termux.app.terminal.TerminalPaneController.Window> restoredFloats =
            new java.util.HashSet<>();
        // The restored session the saved currentSession names, or null when it kept no window in
        // the row (it was saved as floats only).
        WSession savedCurrent = null;
        java.util.Map<Integer, WSession> restoredBySaved = new java.util.HashMap<>();
        int shellWindowIndex = 0;
        try {
            for (int s = 0; s < workspace.sessions.size(); s++) {
                com.termux.app.terminal.TerminalWorkspace.Session savedSession = workspace.sessions.get(s);
                WSession ws = new WSession();
                ws.name = TerminalNamePolicy.normalizeSession(savedSession.name);
                boolean[] savedAsFloat = new boolean[savedSession.windows.size()];
                for (int i = 0; i < savedAsFloat.length; i++)
                    savedAsFloat[i] = savedSession.windows.get(i).homeFloat != null;
                boolean[] asFloat = com.termux.app.terminal.HomeFloatPolicy.restoredAsFloats(
                    savedAsFloat, homePageCount > 0);
                for (int i = 0; i < asFloat.length; i++) {
                    com.termux.app.terminal.TerminalWorkspace.Window savedWindow =
                        savedSession.windows.get(i);
                    java.util.List<TerminalSession> shells = windowShells.get(shellWindowIndex++);
                    if (asFloat[i]) {
                        // A Home float: out of the row, on its page (the last one if its page is
                        // gone), minimised if it was, at its saved size and spot.
                        com.termux.app.terminal.TerminalPaneController.Window window =
                            mPaneController.newWorkspaceHomeFloat(savedWindow, shells,
                                com.termux.app.terminal.HomeFloatPolicy.restoredPage(
                                    homePagePositionOf(savedWindow.homeFloat.pageId),
                                    homePageCount));
                        restoredWindows.add(window);
                        restoredFloats.add(window);
                        continue;
                    }
                    com.termux.app.terminal.TerminalPaneController.Window window =
                        mPaneController.newWorkspaceWindow(savedWindow, shells);
                    ws.windows.add(window);
                    restoredWindows.add(window);
                }
                // The row's current window; one saved as a float leaves the row on the window
                // before it, and the wall stays where it is.
                int rowIndex = com.termux.app.terminal.HomeFloatPolicy.restoredRowIndex(
                    asFloat, savedSession.currentWindow);
                // A session is its row's windows: one saved as floats only comes back as its
                // floats alone, as after its last window closed, and is no session of the row.
                if (rowIndex < 0) continue;
                ws.current = rowIndex;
                restored.add(ws);
                restoredBySaved.put(s, ws);
                if (s == workspace.currentSession) savedCurrent = ws;
            }
        } catch (RuntimeException e) {
            for (com.termux.app.terminal.TerminalPaneController.Window window : restoredWindows)
                mPaneController.removeWindow(window);
            for (TerminalSession shell : createdShells) mTermuxService.killTermuxSession(shell);
            throw new com.termux.app.terminal.TerminalWorkspace.WorkspaceException(
                "invalid_workspace", "Could not rebuild workspace topology: " + e.getMessage(), e);
        }

        // A saved waiting session goes back behind its place (#359) instead of onto the wall as a
        // page of its own: pairs of the window in front and the one that waits.
        java.util.List<com.termux.app.terminal.TerminalPaneController.Window[]> regrouped =
            new java.util.ArrayList<>();
        WSession wallSaved = restoredBySaved.get(0);
        for (int s = 1; wallSaved != null && s < workspace.sessions.size(); s++) {
            int behind = com.termux.app.terminal.TerminalWorkspace.placeBehind(workspace.sessions, s);
            WSession waitingSession = restoredBySaved.get(s);
            if (behind < 0 || waitingSession == null || waitingSession == savedCurrent
                    || behind >= wallSaved.windows.size() || waitingSession.windows.size() != 1)
                continue;
            regrouped.add(new com.termux.app.terminal.TerminalPaneController.Window[] {
                wallSaved.windows.get(behind), waitingSession.windows.get(0)});
            restored.remove(waitingSession);
        }

        if (replace) {
            // The live Home floats are windows of the session being replaced: they go too, while
            // the old sessions still stand for what their closing announces.
            for (com.termux.app.terminal.TerminalPaneController.Window window :
                    mPaneController.homeFloats()) {
                if (restoredFloats.contains(window)) continue;
                for (TerminalSession shell : mPaneController.removeWindow(window))
                    mTermuxService.killTermuxSession(shell);
            }
            // The sessions waiting behind the old places go with them (#357).
            java.util.List<com.termux.app.terminal.TerminalPaneController.Window> waiting =
                new java.util.ArrayList<>();
            mPlaceSessions.allWaiting(waiting);
            mPlaceSessions.clear();
            for (com.termux.app.terminal.TerminalPaneController.Window window : waiting) {
                for (TerminalSession shell : mPaneController.removeWindow(window))
                    mTermuxService.killTermuxSession(shell);
            }
            java.util.List<WSession> oldSessions = new java.util.ArrayList<>(mWSessions);
            mWSessions.clear();
            mCurrentWSession = null;
            for (WSession old : oldSessions) {
                for (com.termux.app.terminal.TerminalPaneController.Window window :
                        new java.util.ArrayList<>(old.windows)) {
                    for (TerminalSession shell : mPaneController.removeWindow(window))
                        mTermuxService.killTermuxSession(shell);
                }
            }
        }
        mWSessions.addAll(restored);
        for (com.termux.app.terminal.TerminalPaneController.Window[] pair : regrouped)
            mPlaceSessions.addWaiting(pair[0], pair[1]);
        WSession selected = savedCurrent != null ? savedCurrent
            : restored.isEmpty() ? null : restored.get(0);
        if (selected != null) {
            mCurrentWSession = selected;
            // Taken the way every other shell is (activateSessionInPanes): the window shown, its
            // pane focused through focusSession, the fonts, clipboard and session list set, so
            // a rebuilt or loaded window is the launcher's like one opened by hand.
            TerminalSession focused =
                mPaneController.windowActiveSession(mCurrentWSession.currentWindow());
            if (focused == null)
                mPaneController.showWindow(mCurrentWSession.currentWindow());
            else
                activateSessionInPanes(focused);
        } else if (mWSessions.isEmpty()) {
            // Floats only, and nothing left in the row: the Terminal is empty, as after its last
            // window closed. The wall stays on Home; off Home, the last Home page slides in.
            mCurrentWSession = null;
            if (mPaneWallController != null
                && mPaneWallController.currentPage() == com.termux.app.page.PageKind.TERMINAL)
                mPaneWallController.goToLastHomePage(isVisible());
        }
        // Else floats only were added to a live Terminal: its current session stays.
        if (getTermuxTerminalSessionClient() != null)
            getTermuxTerminalSessionClient().checkForFontAndColors();
        if (!restoredFloats.isEmpty()) onHomeFloatsChangedInActivity();
        rebuildDrawerSessions();
        return new com.termux.app.terminal.TerminalWorkspace.LoadResult(restored.size(), windowCount, paneCount,
            workspace.commandCount(), replace);
    }

    /** Whether any window of {@code workspace} was saved as a Home float. */
    private static boolean savesHomeFloats(
            @NonNull com.termux.app.terminal.TerminalWorkspace workspace) {
        for (com.termux.app.terminal.TerminalWorkspace.Session session : workspace.sessions)
            for (com.termux.app.terminal.TerminalWorkspace.Window window : session.windows)
                if (window.homeFloat != null) return true;
        return false;
    }

    private static void collectWorkspacePanes(
            @NonNull com.termux.app.terminal.TerminalWorkspace.Node node,
            @NonNull java.util.List<com.termux.app.terminal.TerminalWorkspace.Pane> panes) {
        if (node instanceof com.termux.app.terminal.TerminalWorkspace.Pane) {
            panes.add((com.termux.app.terminal.TerminalWorkspace.Pane) node);
            return;
        }
        com.termux.app.terminal.TerminalWorkspace.Split split =
            (com.termux.app.terminal.TerminalWorkspace.Split) node;
        collectWorkspacePanes(split.a, panes);
        collectWorkspacePanes(split.b, panes);
    }

    /**
     * Seams for the {@code appearance.*} and {@code app.*} registry actions. Each
     * wraps a private handler that the terminal action sheet already invokes, so
     * the palette, a keybind, and a remote caller reach the same code.
     */
    // Opens the Appearance editor, the one page every door leads to: the Settings row, the
    // terminal menu, the corner tabs, a deep link, and the remote appearance.* actions. The
    // wallpaper picker is no door of its own; the Appearance card's Wallpaper row raises it.
    void openAppearanceSurface() {
        mAppearanceFromSettings = false;
        openAppearanceSurface(null, null, null);
    }

    private void openAppearanceSurface(@Nullable String section,
            @Nullable com.termux.app.page.PageKind place,
            @Nullable com.termux.app.chrome.wallpaper.WallpaperPickerPage.ReturnState restore) {
        mOverviewRestore = restore;
        // The wall has to be built before the editor can be held on a place, and a cold start
        // delivers the intent while the root view is still being laid out.
        View root = findViewById(R.id.activity_termux_root_view);
        Runnable open = () -> {
            if (isFinishing() || isDestroyed()) return;
            // The setup cards and the editor's card sheet never stand over each other.
            if (mSetupWizard != null) mSetupWizard.stepAsideForEditor();
            mAppearance.open(com.termux.app.surfaces.EditorCard.forKey(section), place);
        };
        if (root != null) root.post(open);
        else open.run();
    }

    /**
     * The editor opens on the Global card with the picker over it: for a Wallpaper door
     * ({@code restore} null), or when the picker's Photo… came back and the session it interrupted
     * could not be carried ({@code restore} as its pending choice).
     */
    private void resumeWallpaper(
            @Nullable com.termux.app.chrome.wallpaper.WallpaperPickerPage.ReturnState restore) {
        mAppearanceFromSettings = false;
        // A picker prepared for a fresh door has no pending photo to restore.
        if (restore != null)
            mAppearance.releasePrepared();
        mOverviewRestore = restore;
        View root = findViewById(R.id.activity_termux_root_view);
        Runnable open = () -> {
            if (!isFinishing() && !isDestroyed())
                mAppearance.resumeWallpaper();
        };
        if (root != null) root.post(open);
        else open.run();
    }

    /** The wallpaper picker's sides, as a relaunch carries them. */
    private static final String WALLPAPER_SIDE_PHOTO = "PHOTO";
    private static final String WALLPAPER_SIDE_LIVE = "LIVE";

    /**
     * A menu's Wallpaper row was tapped: the picker starts loading while the menu slides away,
     * so the door that follows opens the editor without a wait.
     */
    private void prepareWallpaperDoor() {
        mOverviewRestore = null;
        mAppearance.prepareWallpaper();
    }

    /**
     * A menu has gone: a picker its Wallpaper row prepared and no door took is let go. Posted on
     * the root like {@link #resumeWallpaper}'s open, so the door the row ran is served first.
     */
    private void releasePreparedWallpaper() {
        View root = findViewById(R.id.activity_termux_root_view);
        if (root != null) root.post(mAppearance::releasePrepared);
        else mAppearance.releasePrepared();
    }

    /** The activity's half of the Appearance surface's seam: its content, its backdrop, its pages. */
    private final class AppearanceSurfaceHost
            implements com.termux.app.surfaces.AppearanceSurfaceController.Host {
        @NonNull @Override public Context context() {
            return TermuxActivity.this;
        }

        @Nullable @Override public ViewGroup content() {
            return com.termux.app.window.WindowLayers.windowRoot(TermuxActivity.this);
        }

        @Override public void createOverview(
                @NonNull com.termux.app.surfaces.AppearanceSurfaceController.Navigator navigator,
                @Nullable String centredSlot,
                @NonNull java.util.function.Consumer<com.termux.app.surfaces.AppearanceSurfaceController.OverviewPage> ready) {
            final com.termux.app.chrome.wallpaper.WallpaperPickerPage.ReturnState restore = mOverviewRestore;
            mOverviewRestore = null;
            final com.termux.app.chrome.wallpaper.WallpaperPickerPage.Slots slots =
                com.termux.app.chrome.wallpaper.WallpaperPickerPage.systemSlots(TermuxActivity.this);
            final com.termux.app.chrome.wallpaper.WallpaperPickerPage.Io io =
                com.termux.app.chrome.wallpaper.WallpaperPickerPage.Io.background();
            // Everything the page opens with is read here, off the main thread: the slots (binder
            // calls) and the recent photos.
            io.run(() -> {
                // A fresh page has no pending photo: any left were from a return that never came.
                if (restore == null) {
                    com.termux.app.chrome.wallpaper.WallpaperSlots.clearPendingPhotos(TermuxActivity.this);
                }
                return com.termux.app.chrome.wallpaper.WallpaperPickerPage.load(slots);
            }, loaded -> {
                if (loaded == null || isFinishing() || isDestroyed()) {
                    io.shutdown();
                    navigator.close();
                    return;
                }
                // A photo's return state wins; else the card the surface remembers, nothing pending.
                com.termux.app.chrome.wallpaper.WallpaperPickerPage.ReturnState start = restore;
                com.termux.app.chrome.wallpaper.WallpaperSlots.Slot remembered =
                    wallpaperSlotNamed(centredSlot);
                if (start == null && remembered != null) {
                    start = com.termux.app.chrome.wallpaper.WallpaperPickerPage.ReturnState
                        .centredOn(remembered, loaded);
                }
                final com.termux.app.chrome.wallpaper.WallpaperPickerPage picker =
                    new com.termux.app.chrome.wallpaper.WallpaperPickerPage(TermuxActivity.this,
                        slots, overviewListener(), navigator::close,
                        start, new com.termux.app.chrome.wallpaper.WallpaperThumbs(), loaded, io);
                // The picker's frame over the editor: back to the editor, and the editor's Done.
                // Photo | Video | Shader above the picker where motion can run; the sheet frames the host.
                final com.termux.app.chrome.wallpaper.WallpaperLiveHost liveHost =
                    new com.termux.app.chrome.wallpaper.WallpaperLiveHost(TermuxActivity.this, picker,
                        () -> applyHomeWallpaperInPlace(true));
                liveHost.setHeldReasonSource(() -> mScene == null ? null : mScene.heldReason());
                liveHost.setVideoSource(new com.termux.app.chrome.wallpaper.WallpaperLiveHost.VideoSource() {
                    @Override
                    public com.termux.app.chrome.wallpaper.WallpaperLiveHost.VideoSource.Result importFile(android.content.Context c, android.net.Uri u) {
                        return importFile(c, u, f -> { });
                    }

                    @Override
                    public com.termux.app.chrome.wallpaper.WallpaperLiveHost.VideoSource.Result importFile(android.content.Context c, android.net.Uri u,
                            com.termux.app.chrome.wallpaper.WallpaperLiveHost.VideoSource.Progress p) {
                        com.termux.app.chrome.scene.VideoImport.Result r = com.termux.app.chrome.scene.VideoImport.importFile(c, u, p::onProgress);
                        return new com.termux.app.chrome.wallpaper.WallpaperLiveHost.VideoSource.Result(r.ok, r.name, r.hint, r.error);
                    }

                    @Override
                    public com.termux.app.chrome.scene.VideoVariants.State state(android.content.Context c) {
                        return com.termux.app.chrome.scene.VideoVariants.state(c);
                    }

                    @Override
                    public com.termux.app.chrome.wallpaper.WallpaperLiveHost.VideoSource.Result prepareRate(android.content.Context c, int hz,
                            com.termux.app.chrome.wallpaper.WallpaperLiveHost.VideoSource.Progress p,
                            java.util.concurrent.atomic.AtomicBoolean cancel) {
                        com.termux.app.chrome.scene.VideoVariants.Result r =
                            com.termux.app.chrome.scene.VideoVariants.prepare(c, hz, p::onProgress, cancel);
                        return new com.termux.app.chrome.wallpaper.WallpaperLiveHost.VideoSource.Result(r.ok, null, null, r.error);
                    }
                });
                final com.termux.app.surfaces.WallpaperSheet shell =
                    new com.termux.app.surfaces.WallpaperSheet(TermuxActivity.this, navigator,
                        liveHost.root());
                mLiveWallpaperPage = picker;
                ready.accept(new com.termux.app.surfaces.AppearanceSurfaceController.OverviewPage() {
                    @NonNull @Override public View root() { return shell.root(); }
                    @NonNull @Override public CharSequence title() { return picker.title(); }
                    @Override public void onShown() { picker.onShown(); liveHost.onShown(); }
                    @Override public void onHidden() { picker.onHidden(); }
                    @Override public void release() {
                        if (mLiveWallpaperPage == picker) mLiveWallpaperPage = null;
                        liveHost.release();
                        picker.release();
                    }
                    @Override public boolean consumeBack() { return liveHost.consumeBack(); }
                    @Override public void holdBusy(boolean held) { picker.holdBusy(held); }
                    @Nullable @Override public String centredSlotName() { return picker.centredSlot().name(); }
                    // Opened onto Live (a scene in use), the Photo picker is GONE and its centred
                    // card never sizes: waiting on it left the sheet invisible over the editor.
                    @Override public void whenReady(@NonNull Runnable ready) {
                        if (liveHost.showingLive()) ready.run();
                        else picker.whenReady(ready);
                    }
                    // Photo | Live and the scenes' scroll, carried over a recolour relaunch.
                    @Nullable @Override public String shownSide() {
                        return liveHost.showingLive() ? WALLPAPER_SIDE_LIVE : WALLPAPER_SIDE_PHOTO;
                    }
                    @Override public int sideScrollY() { return liveHost.gridScrollY(); }
                    @Override public void restoreSide(@NonNull String side, int scrollY) {
                        liveHost.restoreSide(WALLPAPER_SIDE_LIVE.equals(side), scrollY);
                    }
                    @Override public boolean hasPendingChanges() {
                        return picker.hasPendingChanges() || liveHost.hasPendingChanges();
                    }
                    // The Photo picker's choice first, then the previewed video or shader; both finish before done.
                    @Override public void commit(@NonNull Runnable done, @NonNull Runnable failed) {
                        picker.commit(() -> liveHost.commit(done, failed), failed);
                    }
                });
            });
        }

        @Override public void onClosed() {
            mOverviewRestore = null;
            resumeSetupWizardAfterPicker();
            // Always on turned on in the editor: the keyboard Home wants is up now, whatever the
            // editor did with the one it raised, and the notice the editor held back follows on
            // the arrangement after the close.
            if (mLastWallPage == com.termux.app.page.PageKind.HOME
                && restWantsKeyboard(mLastWallPage))
                applyPlaceKeyboard(mLastWallPage);
            String notice = mSheets.alwaysOnNotice().onEditorClosed();
            if (notice != null) {
                if (mTermuxActivityRootView != null)
                    mTermuxActivityRootView.post(() -> showToast(notice, false));
                else
                    showToast(notice, false);
            }
        }

        /** In the default preferences, as Settings keeps its own place, so a killed launcher keeps it. */
        @Nullable @Override public String readReturnState() {
            try {
                return appearanceReturnPreferences().getString(
                    com.termux.app.surfaces.AppearanceReturnState.PREFS_KEY, null);
            } catch (RuntimeException e) {
                return null;
            }
        }

        @Override public void writeReturnState(@NonNull String state) {
            appearanceReturnPreferences().edit()
                .putString(com.termux.app.surfaces.AppearanceReturnState.PREFS_KEY, state).apply();
        }

        @NonNull
        private android.content.SharedPreferences appearanceReturnPreferences() {
            return getApplicationContext().getSharedPreferences(
                TermuxConstants.TERMUX_DEFAULT_PREFERENCES_FILE_BASENAME_WITHOUT_EXTENSION,
                Context.MODE_PRIVATE);
        }

        @Nullable
        private com.termux.app.chrome.wallpaper.WallpaperSlots.Slot wallpaperSlotNamed(
                @Nullable String name) {
            if (name == null) return null;
            for (com.termux.app.chrome.wallpaper.WallpaperSlots.Slot slot
                    : com.termux.app.chrome.wallpaper.WallpaperSlots.Slot.values()) {
                if (slot.name().equals(name)) return slot;
            }
            return null;
        }

        @Override public void onClosedByUser() {
            if (!mAppearanceFromSettings) return;
            mAppearanceFromSettings = false;
            // Opened from Settings' Appearance page: Back returns to Settings, not the launcher (the
            // row's CLEAR_TOP launch closed Settings underneath the surface; its saved stack brings
            // the page back).
            startActivity(com.termux.app.activities.SettingsDoor.plain(TermuxActivity.this));
        }
    }

    /** The open surface came from Settings' Appearance row; a close by the person goes back there. */
    private boolean mAppearanceFromSettings;
    /** An icon pack was applied live while the Appearance surface was open: a restyle is owed at its end. */
    private boolean mIconPackAppliedLive;

    /** What the Overview asks of the activity. */
    @NonNull
    private com.termux.app.chrome.wallpaper.WallpaperPickerPage.Listener overviewListener() {
        return new com.termux.app.chrome.wallpaper.WallpaperPickerPage.Listener() {
            @Override public void onPickPhoto(
                    @NonNull com.termux.app.chrome.wallpaper.WallpaperSlots.Slot slot,
                    @NonNull com.termux.app.chrome.wallpaper.WallpaperPickerPage.ReturnState back) {
                // The surface stays up under Android's photo picker and the crop; the cropped photo
                // becomes the page's pending choice in place (returnFromWallpaperPhoto).
                mSetupPickerPhotoTrip = true;
                launchManagedWallpaperPicker(slot, back);
            }

            @Override public void onApplied(
                    @NonNull com.termux.app.chrome.wallpaper.WallpaperSlots.Slot slot,
                    @NonNull com.termux.app.chrome.wallpaper.WallpaperSlots.Choice choice) {
                // The applier's changed listener has already told the live host; the glass
                // still has to pick up the new still as its managed picture.
                // A photo chosen here ends a live scene (it would keep drawing over the photo).
                if (com.termux.app.chrome.wallpaper.LiveSceneLogic.photoEndsScene(slot))
                    com.termux.app.chrome.wallpaper.LiveWallpaperApplier.photoChosen(TermuxActivity.this);
                if (slot != com.termux.app.chrome.wallpaper.WallpaperSlots.Slot.HOME) return;
                applyHomeWallpaperInPlace(choice.photo);
            }

            @Override public void onOpenLook() {
                mAppearance.open();
            }

            @Override public void onOpenIcons() {
                mAppearance.open();
            }
        };
    }

    /**
     * A new Home wallpaper has landed: wallpaper mode on and the launcher re-dressed in place (a
     * recreate only when the mode itself switched on), the glass moved to the new picture. The
     * picker's Apply runs it directly; {@code launcherctl wallpaper set} reaches it through
     * {@link #onHomeWallpaperApplied}. Main thread.
     */
    private void applyHomeWallpaperInPlace(boolean photo) {
        if (isFinishing() || isDestroyed()) return;
        refreshWallpaperPicture();
        refreshTerlWallpaperLooks();
        if (appOnlyWallpaperOnScreen()) {
            // A picture Android never got brings no colours callback: the glass and the
            // self-drawn backdrop are moved to it here.
            mChrome.onWallpaperChanged();
            updateTerminalGlassFrost();
        }
        setWallpaperModeEnabled(TermuxActivity.this, true);
        updateWindowBackgroundForCurrentSession();
        if (photo) {
            View rootView = findViewById(R.id.activity_termux_root_view);
            if (rootView != null) rootView.post(TermuxActivity.this::applyWallpaperOffsetFixIfNeeded);
        }
        mChrome.requestSync(ChromeRenderer.SCOPE_BACKDROPS | ChromeRenderer.SCOPE_ACCESSORY_RENDER);
    }

    /** The created launcher activity, for a wallpaper applied from outside it; null when none. */
    @Nullable private static volatile java.lang.ref.WeakReference<TermuxActivity> sLiveActivity;

    /** What {@link #onHomeWallpaperApplied} runs on the launcher on screen: the picker's apply. */
    @VisibleForTesting
    public static java.util.function.BiConsumer<TermuxActivity, Boolean> sHomeWallpaperInPlace =
        TermuxActivity::applyHomeWallpaperInPlace;

    /**
     * A Home wallpaper set from outside the activity ({@code POST /v1/wallpaper}). Any thread. On
     * screen, the launcher runs exactly what the picker's Apply runs
     * ({@link #applyHomeWallpaperInPlace}); off screen, only the mode and the owed restyle are
     * recorded, and the arrival re-reads the picture on its own.
     */
    public static void onHomeWallpaperApplied(@NonNull Context context, boolean photo) {
        java.lang.ref.WeakReference<TermuxActivity> ref = sLiveActivity;
        TermuxActivity live = ref == null ? null : ref.get();
        if (live == null) {
            setWallpaperModeEnabled(context, true);
            return;
        }
        Context app = context.getApplicationContext();
        new Handler(Looper.getMainLooper()).post(() -> {
            if (live.mIsVisible && !live.isFinishing() && !live.isDestroyed())
                sHomeWallpaperInPlace.accept(live, photo);
            else
                setWallpaperModeEnabled(app, true);
        });
    }

    /** Flips wallpaper passthrough mode and reports the value it moved to. */
    boolean toggleWallpaperMode() {
        boolean enabled = !shouldUseWallpaperPassthroughMode();
        setWallpaperModeEnabled(this, enabled);
        return enabled;
    }

    @Nullable private com.termux.shared.termux.settings.preferences.TerminalContrastLevel mEvenOutLevel;
    @Nullable private int[] mEvenOutSeeds;
    /** The theme's seeds key, dropped on a configuration change (night mode, dynamic colour). */
    @Nullable private int[] mEvenOutSeedsKey;
    @Nullable private com.termux.shared.termux.settings.preferences.TerminalContrastLevel mEvenOutLevelSeen;
    @Nullable private com.termux.app.chrome.EvenOut.Ceiling[] mEvenOutCeilings;
    /** The policy last handed to the pane band, reused while nothing it carries has changed. */
    @Nullable private com.termux.app.chrome.ChromeInk.EvenOutPolicy mEvenOutPolicy;

    /**
     * Tells the pane band how to even the wallpaper out (ADR 0014): the Contrast level, and the
     * recipe ceilings for that level and the theme's seeds (kept per both, since the recipe palette
     * they come from reads the theme), at the terminal Opacity's strength. The policy object is kept and re-handed
     * while level, ceilings and the palette's current polarity are unchanged, so a veil query that
     * changes nothing costs nothing downstream.
     */
    private int evenOutStrengthNow() {
        return com.termux.app.chrome.ChromeInk.evenOutStrengthPercent(
            mPreferences != null ? mPreferences.getTerminalBackgroundOpacity() : 100);
    }

    private int mEvenOutStrengthSeen = -1;

    private void updateEvenOutPolicy() {
        if (mChrome == null) return;
        int strength = evenOutStrengthNow();
        com.termux.app.terminal.MaterialTerminalColorScheme.setGlassFloors(strength > 0);
        com.termux.shared.termux.settings.preferences.TerminalContrastLevel level =
            com.termux.app.chrome.LegibilityLevel.terminalContrast(mPreferences);
        // The theme's seeds, read once per theme: asked on every dock and nav-strip frost request.
        if (mEvenOutSeedsKey == null)
            mEvenOutSeedsKey = com.termux.app.terminal.MaterialTerminalColorScheme.seedsKey(this);
        int[] seeds = mEvenOutSeedsKey;
        if (mEvenOutCeilings == null || mEvenOutLevel != level
                || !java.util.Arrays.equals(mEvenOutSeeds, seeds)) {
            mEvenOutCeilings = com.termux.app.terminal.MaterialTerminalColorScheme
                .evenOutCeilings(this, level);
            mEvenOutLevel = level;
            mEvenOutSeeds = seeds;
        }
        int background = com.termux.terminal.TerminalColors.COLOR_SCHEME
            .mDefaultColors[com.termux.terminal.TextStyle.COLOR_INDEX_BACKGROUND];
        com.termux.app.chrome.ChromeInk.Polarity current =
            com.google.android.material.color.utilities.ColorUtils.lstarFromArgb(background) < 50d
                ? com.termux.app.chrome.ChromeInk.Polarity.PALE_INK
                : com.termux.app.chrome.ChromeInk.Polarity.DARK_INK;
        com.termux.app.chrome.ChromeInk.EvenOutPolicy kept = mEvenOutPolicy;
        if (kept == null || kept.level != level || kept.pale != mEvenOutCeilings[0]
                || kept.dark != mEvenOutCeilings[1] || kept.current != current
                || kept.strengthPercent != strength) {
            kept = new com.termux.app.chrome.ChromeInk.EvenOutPolicy(level, mEvenOutCeilings[0],
                mEvenOutCeilings[1], current, strength);
            mEvenOutPolicy = kept;
        }
        // The stage is kept at a terminal Opacity of 0 too (strength 0): the panes draw none, and
        // a band with an Opacity of its own still evens out at its own strength.
        mChrome.ink().setEvenOutPolicy(strength > 0 ? kept : null);
        mChrome.ink().setEvenOutStage(kept);
        updateBandEvenOutPolicies();
    }

    /** Index of each chrome band's slot in the per-band memo below. */
    private static final int EVEN_OUT_KEYBOARD = 0;
    private static final int EVEN_OUT_DOCK = 1;
    /** What each band's even-out was last built from, so an unchanged pass builds nothing. */
    @NonNull private final com.termux.app.chrome.ChromeInk.EvenOutPolicy[] mBandEvenOutStage =
        new com.termux.app.chrome.ChromeInk.EvenOutPolicy[2];
    @NonNull private final com.termux.app.chrome.ChromeInk.EvenOutPolicy[] mBandEvenOutKept =
        new com.termux.app.chrome.ChromeInk.EvenOutPolicy[2];
    @NonNull private final boolean[] mBandEvenOutInherits = new boolean[2];
    @NonNull private final int[] mBandEvenOutOpacity = {-1, -1};

    /**
     * Tells the chrome bands their even-out (ADR 0014, wave 2c; ChromeInk.bandEvenOutPolicy): by
     * default the terminal's stage, the same policy the panes draw with; a band whose Opacity no
     * longer follows Global evens out to its own text target at its own Opacity's strength. The
     * keyboard and the dock have a frost to compose into; the nav strip always takes the default.
     * The status strip's glass is the top pane's (WallpaperFrostPainter), which this stage does
     * not reach, so it gets none and its ink stays on today's ground. Run with the terminal's
     * stage ({@link #updateEvenOutPolicy}); a few cached preference reads when nothing moved.
     */
    private void updateBandEvenOutPolicies() {
        if (mChrome == null) return;
        com.termux.app.chrome.ChromeInk.EvenOutPolicy stage = mEvenOutPolicy;
        int half = stackLookPage();
        mChrome.ink().setBandEvenOutPolicy(com.termux.app.chrome.GlassBackdropCache.Band.KEYBOARD,
            bandEvenOut(EVEN_OUT_KEYBOARD, com.termux.app.chrome.GlassBackdropCache.Band.KEYBOARD,
                TermuxAppSharedPreferences.SurfaceSlot.KEYBOARD, mPreferences != null
                    ? mPreferences.getInAppKeyboardBackdropOpacity(half) : 100, stage, half));
        mChrome.ink().setBandEvenOutPolicy(com.termux.app.chrome.GlassBackdropCache.Band.DOCK,
            bandEvenOut(EVEN_OUT_DOCK, com.termux.app.chrome.GlassBackdropCache.Band.DOCK,
                TermuxAppSharedPreferences.SurfaceSlot.DOCK, mPreferences != null
                    ? mPreferences.getAppBarOpacity(half) : 100, stage, half));
    }

    /** {@link com.termux.app.chrome.ChromeInk#bandEvenOutPolicy}, rebuilt only when an input moved. */
    @Nullable
    private com.termux.app.chrome.ChromeInk.EvenOutPolicy bandEvenOut(int index,
            @Nullable com.termux.app.chrome.GlassBackdropCache.Band band,
            @Nullable TermuxAppSharedPreferences.SurfaceSlot slot, int opacityPercent,
            @Nullable com.termux.app.chrome.ChromeInk.EvenOutPolicy stage,
            int half) {
        boolean inherits = slot == null || mPreferences == null || mPreferences.isSurfaceInheriting(
            slot, TermuxAppSharedPreferences.SurfaceProperty.OPACITY, half);
        if (mBandEvenOutOpacity[index] >= 0 && mBandEvenOutStage[index] == stage
                && mBandEvenOutInherits[index] == inherits
                && (inherits || mBandEvenOutOpacity[index] == opacityPercent)) {
            return mBandEvenOutKept[index];
        }
        com.termux.app.chrome.ChromeInk.EvenOutPolicy policy =
            com.termux.app.chrome.ChromeInk.bandEvenOutPolicy(band, inherits, opacityPercent, stage);
        mBandEvenOutStage[index] = stage;
        mBandEvenOutInherits[index] = inherits;
        mBandEvenOutOpacity[index] = opacityPercent;
        mBandEvenOutKept[index] = policy;
        return policy;
    }

    /** Scratch for the dock's even-out rect; main thread only, as every dress pass is. */
    @NonNull private final Rect mDockEvenOutRect = new Rect();
    @NonNull private final int[] mDockEvenOutLocation = new int[2];

    /**
     * The dock backdrop's frost with the dock band's even-out composed ahead of it, measured on
     * the dock's own surface ({@code surfaceHost}) as laid out on screen. The frost alone while
     * the band has none, or the switch is off. A null host (a Glass drag's tick) measures nothing
     * and keeps the matrix last measured, so a drag samples no wallpaper per tick.
     */
    @Nullable
    private android.graphics.ColorFilter dockFrostFilter(@Nullable View surfaceHost) {
        // Across a crossing, and from its landing until the glass can be measured where it rests,
        // the frost is the plan's (beginDockGroundBlend): a pass on the way re-measures nothing,
        // and a landing's pass does not put up the held or the left page's even-out.
        if (mDockFilterNow != null && !mDockFilterPlan.measures(stackLookPage(),
                mCrossing.crossing(), mChrome != null && mChrome.isEvenOutHeld())) {
            if (mChrome != null)
                mChrome.ink().noteBandFrame(com.termux.app.chrome.GlassBackdropCache.Band.DOCK, true);
            return mDockFilterNow;
        }
        mDockFilterNow = null;
        android.graphics.ColorFilter filter = measureDockFrostFilter(surfaceHost);
        // Each page's frost as it stands at rest, for a crossing toward it to blend into.
        if (surfaceHost != null && mDockFilterPlan.keepsAtRest(mCrossing.crossing()))
            keepDockFilterAtRest(filter);
        return filter;
    }

    /** Each look's dock frost as its own rest last wore it, by look page id. */
    @NonNull private final com.termux.app.chrome.DockFilterKeep<android.graphics.ColorFilter,
        android.graphics.ColorMatrix> mDockFilterAtRest = new com.termux.app.chrome.DockFilterKeep<>();

    /** Keeps {@code filter} as the stack look's frost at rest; nothing new when it already is. */
    private void keepDockFilterAtRest(@Nullable android.graphics.ColorFilter filter) {
        // Apart, two cards share the band; each keeps its own (restFrostFilter), none a rest here.
        if (filter == null || mChrome == null || mSideCards.apart()) return;
        int look = stackLookPage();
        int ground = groundOfWallPage(stackDressPage());
        int frames = mChrome.ink().framesGeneration();
        int dress = dockFilterDress(look);
        if (mDockFilterAtRest.holds(look, filter)) {
            mDockFilterAtRest.restamp(look, ground, frames, dress);
            return;
        }
        android.graphics.ColorMatrix matrix = com.termux.app.chrome.GlassFilters.matrixOf(filter);
        if (matrix != null) mDockFilterAtRest.keep(look, filter, matrix, ground, frames, dress);
    }

    /**
     * What the dock's frost depends on beyond the ground, the wallpaper and the rest's geometry:
     * the look's Opacity and the even-out stage (one object until its inputs change).
     */
    private int dockFilterDress(int look) {
        int opacity = mPreferences != null ? mPreferences.getAppBarOpacity(look) : 100;
        return opacity * 31 + System.identityHashCode(mEvenOutPolicy);
    }

    @Nullable
    private android.graphics.ColorFilter measureDockFrostFilter(@Nullable View surfaceHost) {
        android.graphics.ColorFilter frost = com.termux.app.chrome.GlassFilters.frost(
            mPreferences != null ? mPreferences.getAppBarOpacity(stackLookPage()) : 100);
        if (mChrome == null) return frost;
        // Asked only where the dock's frame is up: it covers the page's dim, so the dock's ink and
        // even-out are measured with none under them (cleared in clearAccessoryRenderEffectBackdrop).
        mChrome.ink().noteBandFrame(com.termux.app.chrome.GlassBackdropCache.Band.DOCK, true);
        if (surfaceHost == null) {
            return com.termux.app.chrome.GlassFilters.withEvenOut(mChrome.ink().lastBandEvenOutMatrix(
                com.termux.app.chrome.GlassBackdropCache.Band.DOCK), frost);
        }
        if (!dockEvenOutRect(surfaceHost)) return frost;
        updateEvenOutPolicy();
        return com.termux.app.chrome.GlassFilters.withEvenOut(mChrome.ink().bandEvenOutMatrix(
            com.termux.app.chrome.GlassBackdropCache.Band.DOCK, mDockEvenOutRect), frost);
    }

    /** Sets {@link #mDockEvenOutRect} to {@code surfaceHost} on screen; false before it is laid out. */
    private boolean dockEvenOutRect(@NonNull View surfaceHost) {
        if (surfaceHost.getWidth() <= 0 || surfaceHost.getHeight() <= 0) return false;
        surfaceHost.getLocationOnScreen(mDockEvenOutLocation);
        mDockEvenOutRect.set(mDockEvenOutLocation[0], mDockEvenOutLocation[1],
            mDockEvenOutLocation[0] + surfaceHost.getWidth(),
            mDockEvenOutLocation[1] + surfaceHost.getHeight());
        return true;
    }

    /**
     * What terminal text on the default background stands on (TerminalHost#terminalTextSurface):
     * transparent off the wallpaper, where the palette's own background is the answer.
     */
    private int terminalTextSurface() {
        if (mPreferences == null || mChrome == null || !shouldUseWallpaperPassthroughMode()) {
            return Color.TRANSPARENT;
        }
        return mChrome.ink().terminalPaneSurface(paneSurfaceStyle().paneGlassTintColor());
    }

    /** Whether wallpaper passthrough is currently on. */
    boolean isWallpaperModeEnabled() {
        return shouldUseWallpaperPassthroughMode();
    }

    /**
     * Flip the cursor trail preference and apply it to every live pane. Returns the value it moved to,
     * which can differ from what the views do while the device is in power save mode.
     */
    boolean toggleCursorTrail() {
        boolean enabled = !mPreferences.isTerminalCursorTrailEnabled();
        mPreferences.setTerminalCursorTrailEnabled(enabled);
        applyCursorTrailEnabledToPanes();
        return enabled;
    }

    /** Re-reads the cursor trail on/off preference into every live pane view. */
    private void applyCursorTrailEnabledToPanes() {
        if (mTermuxTerminalViewClient != null) {
            if (mPaneController != null) {
                for (TerminalView view : mPaneController.allPaneViews()) {
                    mTermuxTerminalViewClient.applyCursorTrailPolicy(view);
                    mTermuxTerminalViewClient.applyUrlUnderlinePolicy(view);
                }
            }
            mTermuxTerminalViewClient.applyCursorTrailPolicy(getTerminalView());
            mTermuxTerminalViewClient.applyUrlUnderlinePolicy(getTerminalView());
        }
    }

    /** Whether the cursor trail preference is on, regardless of power save state. */
    boolean isCursorTrailEnabled() {
        return mPreferences != null && mPreferences.isTerminalCursorTrailEnabled();
    }

    /**
     * Re-read the padding-fill preference into every live pane, the way {@link #toggleCursorTrail()}
     * does for the cursor trail. Called from {@link #reloadActivityStyling}, which a Settings change
     * to the preference reaches through {@link #requestTermuxActivityStylingOnNextResume} — right
     * away if this activity is in front, otherwise on its next resume.
     */
    private void applyPaddingFillPolicyToVisiblePanes() {
        if (mTermuxTerminalViewClient == null)
            return;
        if (mPaneController != null) {
            for (TerminalView view : mPaneController.getVisiblePaneViews()) {
                mTermuxTerminalViewClient.applyPaddingFillPolicy(view);
            }
        }
        mTermuxTerminalViewClient.applyPaddingFillPolicy(getTerminalView());
    }

    /** The terminal effect on the chrome; built the first time the effect is applied. */
    @Nullable private com.termux.app.chrome.ChromeRetroEffect mChromeRetroEffect;

    /**
     * Push the cursor trail style and retro terminal effect preferences into the pane controller
     * (kitty.conf {@code custom_shaders} still wins for the trail inside it) and the effect onto
     * the chrome. The retro effect draws on terminal pane frames (never wall widget pages) and, on
     * the Terminal only, the status bar, dock, bars and keyboard around them. Called when the controller is created,
     * from the Appearance editor's live preview and from {@link #reloadActivityStyling}.
     */
    private void applyTrailStyleAndRetroEffect() {
        if (mPreferences == null)
            return;
        String retroEffect = mPreferences.getTerminalRetroEffect();
        // The Material CRT glows in the theme's primary: read before any screen is built with it.
        com.termux.app.terminal.PaneRetroStyle.setMaterialPrimary(
            com.google.android.material.color.MaterialColors.getColor(this,
                androidx.appcompat.R.attr.colorPrimary, 0xFF6750A4));
        if (mChromeRetroEffect == null) {
            View root = findViewById(R.id.activity_termux_root_view);
            if (root != null) mChromeRetroEffect = new com.termux.app.chrome.ChromeRetroEffect(root);
        }
        if (mChromeRetroEffect != null) {
            mChromeRetroEffect.setOnHome(
                settledWallPage() == com.termux.app.page.PageKind.HOME);
            mChromeRetroEffect.setStyle(com.termux.app.terminal.PaneRetroStyle.fromId(retroEffect));
        }
        applyDeckLook();
        if (mPaneController == null)
            return;
        mPaneController.setCursorTrailStylePreference(mPreferences.getTerminalCursorTrailStyle());
        mPaneController.setRetroEffectPreference(retroEffect);
    }

    /**
     * Dresses the in-app keyboard as the CRT's accessory while the chrome draws a terminal effect
     * (wave 8, the deck look): the bezel's panel colour, the effect's lights. Plain everywhere the
     * chrome is plain, Home included.
     */
    private void applyDeckLook() {
        com.termux.app.terminal.PaneRetroStyle style = mChromeRetroEffect == null
            ? com.termux.app.terminal.PaneRetroStyle.NONE : mChromeRetroEffect.drawnStyle();
        com.termux.app.terminal.DeckLook deck = com.termux.app.terminal.DeckLook.of(style,
            getTermuxThemeColor(com.termux.shared.R.attr.termuxColorSurfacePanelHigh,
                R.color.termux_surface_panel_high),
            MaterialColors.getColor(this, androidx.appcompat.R.attr.colorPrimary, 0xFF6750A4));
        if (mInAppKeyboard != null) mInAppKeyboard.setDeckLook(deck);
        boolean changed = !java.util.Objects.equals(mDeckLook, deck);
        mDeckLook = deck;
        // The window bar: its chips, the stats' display window, and the slab under them.
        com.termux.app.terminal.TerminalWindowBar bar = findViewById(R.id.terminal_window_bar);
        if (bar != null) bar.setDeckLook(deck);
        homeFloatChipBar().setDeckLook(deck);
        View sessionsIndicator = findViewById(R.id.terminal_sessions_indicator);
        if (sessionsIndicator instanceof com.termux.app.statusbar.SessionsIndicatorView)
            ((com.termux.app.statusbar.SessionsIndicatorView) sessionsIndicator).setDeckLook(deck);
        // Every item of the row stands in the display window, in whatever order the user set.
        for (com.termux.app.statusbar.StatusRowItem item
                : com.termux.app.statusbar.StatusRowItem.values()) {
            View widget = findViewById(item.widgetId);
            if (widget instanceof com.termux.app.statusbar.StatusBarWidgetView)
                ((com.termux.app.statusbar.StatusBarWidgetView) widget).setDeckLook(deck);
            View dot = findViewById(item.dotId);
            if (dot instanceof com.termux.app.statusbar.MaterialDotSeparatorView)
                ((com.termux.app.statusbar.MaterialDotSeparatorView) dot).setDeckLook(deck);
        }
        com.termux.app.statusbar.DeckDisplayWindow.apply(
            findViewById(R.id.terminal_status_stats_cluster), deck);
        // The bands behind the system bars wear the slab with the bar and the keyboard.
        applyDeckBands();
        if (!changed)
            return;
        // The extra keys row, every page of it (a page made later is dressed as it is set).
        for (int i = 0, n = extraKeysPageTotal(); i < n; i++) applyExtraKeysDeck(extraKeysPageAt(i));
        // Off the deck the glass pass puts the bar's own background and blur back; on it, the
        // same pass ends by laying the slab (applyWindowBarDeckSlab). A hidden bar gets its pass
        // when it is next shown.
        refreshTerminalWindowBarGlass();
        // The dock's sheet, the plank off it and the keyboard's host take the slab from their own
        // glass pass (deckSlabOr), which is asked for here: nothing moved, so no geometry pass
        // would book one.
        if (mChrome != null)
            mChrome.requestSync(ChromeRenderer.SCOPE_APPLY_THIS_FRAME
                | ChromeRenderer.SCOPE_ACCESSORY_RENDER);
    }

    /**
     * Under the deck look, the slab in place of {@code glass}: the dock's sheet, the plank off the
     * dock and the keyboard's host are opaque plastic in the bezel's tone, one unit with the keys
     * (wave 8). Off the deck, {@code glass} itself. The host's outline still clips the slab, so a
     * card keeps its corners and a Docked slice its square edge.
     */
    @Nullable
    private Drawable deckSlabOr(@Nullable Drawable glass) {
        com.termux.app.terminal.DeckLook deck = mDeckLook;
        return deck == null ? glass : new com.termux.app.terminal.DeckSlabDrawable(deck);
    }

    /** The deck the chrome is wearing now; null while no terminal effect is drawn (wave 8). */
    @Nullable private com.termux.app.terminal.DeckLook mDeckLook;

    /** The extra keys row wears the deck with the keyboard (wave 8c); off it, its own look. */
    private void applyExtraKeysDeck(@Nullable ExtraKeysPageView keys) {
        if (keys == null)
            return;
        com.termux.app.terminal.DeckLook deck = mDeckLook;
        if (deck == null)
            keys.setDeckLook(false, 0, 0, 0, 0, 0, 0, 0);
        else
            keys.setDeckLook(true, deck.bed, deck.bedTop, deck.key, deck.keyTop, deck.keyFoot,
                deck.lit, deck.litInk);
    }

    /**
     * Under the deck look the window bar is an opaque slab in the bezel's tone instead of glass:
     * the slab replaces the glass drawable. Runs at the end of every
     * glass pass, so a Look or ink refresh that rebuilds the glass cannot undo it; off the deck it
     * does nothing and the pass's own background and blur stand. The host's outline still clips the
     * slab, so a Docked card keeps its shape.
     */
    private void applyWindowBarDeckSlab() {
        com.termux.app.terminal.DeckLook deck = mDeckLook;
        if (deck == null)
            return;
        View background = findViewById(R.id.terminal_window_bar_background);
        if (background != null) {
            android.graphics.drawable.Drawable current = background.getBackground();
            if (!(current instanceof com.termux.app.terminal.DeckSlabDrawable)
                    || !((com.termux.app.terminal.DeckSlabDrawable) current).deck().equals(deck))
                background.setBackground(new com.termux.app.terminal.DeckSlabDrawable(deck));
        }
        View side = findViewById(R.id.terminal_window_bar_background_side);
        if (side != null && side.getVisibility() == View.VISIBLE) {
            android.graphics.drawable.Drawable current = side.getBackground();
            if (!(current instanceof com.termux.app.terminal.DeckSlabDrawable)
                    || !((com.termux.app.terminal.DeckSlabDrawable) current).deck().equals(deck))
                side.setBackground(new com.termux.app.terminal.DeckSlabDrawable(deck));
        }
    }

    /**
     * Under the deck look the bands behind the system status bar and the system navigation bar are
     * the same opaque slab as the window bar and the keyboard, laid over whatever glass is there
     * (the status strip's, the joined Docked frame's, the stack's gap above the gesture strip). The
     * status band wherever a strip or the frame reaches under the status bar; the navigation band
     * under a dock standing on the bottom edge. Off the deck both are gone and the glass under them
     * shows as it always did. Their own views, which nothing else writes.
     */
    private void applyDeckBands() {
        com.termux.app.terminal.DeckLook deck = mDeckLook;
        View status = findViewById(R.id.deck_status_band);
        if (status != null) {
            View root = findViewById(R.id.activity_termux_root_view);
            int top = Math.max(mLastStatusBarInsetTop, root == null ? 0 : root.getPaddingTop());
            boolean show = deck != null && top > 0 && (frameStandsDown()
                || statusInsetStripLead() == com.termux.app.chrome.ChromeEdgeRule.TopLead.WINDOW_BAR);
            if (show) {
                ViewGroup.LayoutParams params = status.getLayoutParams();
                if (params != null && params.height != top) {
                    params.height = top;
                    status.setLayoutParams(params);
                }
                status.setTranslationY(-top);
                setDeckSlab(status, deck);
            }
            setDeckBandShown(status, show);
        }
        View nav = findViewById(R.id.deck_nav_band);
        if (nav != null) {
            View stack = findViewById(R.id.accessory_stack_container);
            // The band hangs below the stack, so it is laid only while the stack is.
            boolean show = deck != null && stack != null && stack.getVisibility() == View.VISIBLE
                && !mDock.dockFloats();
            if (show) setDeckSlab(nav, deck);
            setDeckBandShown(nav, show);
        }
    }

    /** {@code view}'s background as the deck's slab, rebuilt only when the deck moved. */
    private static void setDeckSlab(@NonNull View view,
                                    @NonNull com.termux.app.terminal.DeckLook deck) {
        android.graphics.drawable.Drawable current = view.getBackground();
        if (!(current instanceof com.termux.app.terminal.DeckSlabDrawable)
                || !((com.termux.app.terminal.DeckSlabDrawable) current).deck().equals(deck))
            view.setBackground(new com.termux.app.terminal.DeckSlabDrawable(deck));
    }

    private static void setDeckBandShown(@NonNull View band, boolean shown) {
        int visibility = shown ? View.VISIBLE : View.GONE;
        if (band.getVisibility() != visibility) band.setVisibility(visibility);
        if (!shown && band.getBackground() != null) band.setBackground(null);
    }

    /**
     * Opens the editor through {@code door}, on the card its row of the door table names (a
     * page-led door: the page's own object), and logs the door's line.
     */
    void openSurfaceEditor(@NonNull com.termux.app.surfaces.EditorDoor door) {
        com.termux.app.surfaces.EditorCard card = door.route(currentWallPlace(), null);
        if (door.opensWallpaperPicker()) {
            // The picker over that card, as the wizard opens it; its Done closes the editor.
            resumeWallpaper(null);
            return;
        }
        openSurfaceEditor(card);
    }

