    /** Seam for {@code terminal.reset}: reset the focused shell's emulator state. */
    boolean resetCurrentSession() {
        TerminalSession session = getCurrentSession();
        if (session == null) return false;
        onResetTerminalSession(session);
        return true;
    }

    /** Drawer entry point for renaming the tmux-style session that contains {@code shell}. */
    public void promptSessionRenameFor(@Nullable TerminalSession shell) {
        if (shell == null || mPaneController == null) return;
        promptSessionRename(wsessionOwning(mPaneController.windowOf(shell)));
    }

    private void promptSessionRename(@Nullable WSession session) {
        if (session == null) return;
        TextInputDialogUtils.textInput(this, R.string.title_rename_session, session.name,
            R.string.action_rename_session_confirm, text -> {
                if (!mWSessions.contains(session)) return;
                session.name = TerminalNamePolicy.normalizeSession(text);
                rebuildDrawerSessions();
            }, -1, null, -1, null, null);
    }

    @Nullable
    private com.termux.shared.termux.shell.command.runner.terminal.TermuxSession findTermuxSession(TerminalSession shell) {
        if (mTermuxService == null || shell == null) return null;
        for (com.termux.shared.termux.shell.command.runner.terminal.TermuxSession ts : mTermuxService.getTermuxSessions())
            if (ts.getTerminalSession() == shell) return ts;
        return null;
    }

    /** Ensure every genuinely new service shell that isn't in the restored pane tree gets a window. */
    public void ensureWindowsForServiceSessions() {
        if (mTermuxService == null || mPaneController == null) return;
        for (com.termux.shared.termux.shell.command.runner.terminal.TermuxSession ts : mTermuxService.getTermuxSessions()) {
            TerminalSession shell = ts.getTerminalSession();
            if (!com.termux.app.terminal.TerminalPaneController
                .shouldAdoptAsWindowSession(shell == null ? null : shell.mSessionName)) continue;
            // A Terminal widget's shell is its widget's, shown there when the widget is.
            if (mTerminalWidgets.isWidgetShell(shell)) continue;
            if (mPaneController.windowOf(shell) == null) {
                com.termux.app.terminal.TerminalPaneController.Window w = mPaneController.newWindow(shell);
                WSession ws = new WSession();
                ws.windows.add(w);
                ws.current = 0;
                ws.name = TerminalNamePolicy.normalizeSession(shell.mSessionName);
                mWSessions.add(ws);
            }
        }
    }

    /**
     * Keeps the arrangement for an activity that comes back in this process without instance
     * state ({@link #sProcessPaneLayout}). Only a connected activity knows it; one that never
     * connected leaves what an earlier one kept.
     */
    private void rememberProcessPaneLayout() {
        if (mTermuxService == null || mPaneController == null) return;
        sProcessPaneLayout = savePaneLayoutState();
    }

    /**
     * The row's windows and their trees, the current window, and the Home floats (page,
     * minimised, shape), every pane keyed by its shell's handle, so a recreated activity puts
     * them back around the same running shells.
     */
    @Nullable
    private Bundle savePaneLayoutState() {
        if (mPaneController == null
            || (mWSessions.isEmpty() && mPaneController.homeFloatCount() == 0
                && mMinimise.windows().size() == 0)) return null;
        Bundle root = new Bundle();
        java.util.ArrayList<Bundle> sessionStates = new java.util.ArrayList<>();
        for (WSession ws : mWSessions) {
            if (ws.windows.isEmpty()) continue;
            Bundle sessionState = new Bundle();
            java.util.ArrayList<Bundle> windowStates = new java.util.ArrayList<>();
            for (com.termux.app.terminal.TerminalPaneController.Window window : ws.windows)
                windowStates.add(mPaneController.saveWindow(window));
            sessionState.putParcelableArrayList(PANE_STATE_WINDOWS, windowStates);
            sessionState.putInt(PANE_STATE_CURRENT_WINDOW,
                Math.max(0, Math.min(ws.current, windowStates.size() - 1)));
            if (ws.name != null) sessionState.putString(PANE_STATE_SESSION_NAME, ws.name);
            savePlaceSessions(ws, sessionState);
            sessionStates.add(sessionState);
        }
        root.putParcelableArrayList(PANE_STATE_SESSIONS, sessionStates);
        mMinimise.save(root);
        root.putInt(PANE_STATE_CURRENT_SESSION,
            Math.max(0, mCurrentWSession == null ? 0 : mWSessions.indexOf(mCurrentWSession)));
        java.util.ArrayList<Bundle> floatStates = new java.util.ArrayList<>();
        for (com.termux.app.terminal.TerminalPaneController.Window window :
                mPaneController.homeFloats())
            floatStates.add(mPaneController.saveHomeFloat(window));
        if (!floatStates.isEmpty()) root.putParcelableArrayList(PANE_STATE_HOME_FLOATS, floatStates);
        mPaneController.saveScratchpadState(root);
        return root;
    }

    private void restorePaneLayoutState() {
        Bundle root = mPendingPaneLayoutState;
        mPendingPaneLayoutState = null;
        if (root == null || mTermuxService == null || mPaneController == null) return;
        mPaneController.restoreScratchpadState(root);
        java.util.Map<String, TerminalSession> sessionsByHandle = new java.util.HashMap<>();
        for (com.termux.shared.termux.shell.command.runner.terminal.TermuxSession termuxSession
                : mTermuxService.getTermuxSessions()) {
            TerminalSession terminal = termuxSession.getTerminalSession();
            if (terminal != null) sessionsByHandle.put(terminal.mHandle, terminal);
        }
        restoreRowWindowsState(root, sessionsByHandle);
        mMinimise.restoreState(root, state -> mPaneController.restoreWindow(state, sessionsByHandle));
        // After the row's windows: a float's arrival refreshes the status bar, which re-reads the
        // wall's row. Read with the service bound and no window back yet, the row had no
        // Terminal, and a relaunch on a window page (a new wallpaper's colours) landed on Home.
        restoreHomeFloatsState(root.getParcelableArrayList(PANE_STATE_HOME_FLOATS), sessionsByHandle);
    }

    /** The sessions waiting behind {@code ws}'s places and the numbers in front, into {@code out}. */
    private void savePlaceSessions(@NonNull WSession ws, @NonNull Bundle out) {
        if (mPaneController == null || mPlaceSessions.isEmpty()) return;
        java.util.ArrayList<Bundle> waiting = new java.util.ArrayList<>();
        int[] fronts = new int[ws.windows.size()];
        for (int i = 0; i < ws.windows.size(); i++) {
            com.termux.app.terminal.TerminalPaneController.Window front = ws.windows.get(i);
            fronts[i] = mPlaceSessions.numberOf(front);
            java.util.List<com.termux.app.terminal.TerminalPaneController.Window> behind =
                mPlaceSessions.waiting(front);
            for (int slot = 0; slot < behind.size(); slot++) {
                Bundle state = new Bundle();
                state.putInt(PANE_STATE_WAITING_PLACE, i);
                state.putInt(PANE_STATE_WAITING_NUMBER, mPlaceSessions.waitingNumber(front, slot));
                state.putBundle(PANE_STATE_WAITING_WINDOW, mPaneController.saveWindow(behind.get(slot)));
                waiting.add(state);
            }
        }
        if (waiting.isEmpty()) return;
        out.putParcelableArrayList(PANE_STATE_WAITING, waiting);
        out.putIntArray(PANE_STATE_FRONT_NUMBERS, fronts);
    }

    /**
     * The sessions that waited behind {@code ws}'s places, back behind them around their running
     * shells. {@code saved} is each saved place's window, null where it did not come back; a
     * session whose place is gone comes onto the row as a place of its own, so none is hidden.
     */
    private void restorePlaceSessions(@NonNull WSession ws, @NonNull Bundle state,
            @NonNull java.util.List<com.termux.app.terminal.TerminalPaneController.Window> saved,
            @NonNull java.util.Map<String, TerminalSession> sessionsByHandle) {
        java.util.ArrayList<Bundle> waiting = state.getParcelableArrayList(PANE_STATE_WAITING);
        if (waiting == null || mPaneController == null) return;
        for (Bundle entry : waiting) {
            Bundle windowState = entry == null ? null : entry.getBundle(PANE_STATE_WAITING_WINDOW);
            if (windowState == null) continue;
            com.termux.app.terminal.TerminalPaneController.Window window =
                mPaneController.restoreWindow(windowState, sessionsByHandle);
            if (window == null) continue;
            int place = entry.getInt(PANE_STATE_WAITING_PLACE, -1);
            com.termux.app.terminal.TerminalPaneController.Window front =
                place >= 0 && place < saved.size() ? saved.get(place) : null;
            if (front == null) ws.windows.add(window);
            else mPlaceSessions.addWaiting(front, window, entry.getInt(PANE_STATE_WAITING_NUMBER, 0));
        }
        int[] fronts = state.getIntArray(PANE_STATE_FRONT_NUMBERS);
        if (fronts == null) return;
        for (int i = 0; i < fronts.length && i < saved.size(); i++) {
            if (saved.get(i) != null) mPlaceSessions.restoreFrontNumber(saved.get(i), fronts[i]);
        }
    }

    /** The saved sessions' windows, back in the row around their running shells. */
    private void restoreRowWindowsState(@NonNull Bundle root,
                                        @NonNull java.util.Map<String, TerminalSession> sessionsByHandle) {
        java.util.ArrayList<Bundle> sessionStates =
            root.getParcelableArrayList(PANE_STATE_SESSIONS);
        if (sessionStates == null) return;
        mWSessions.clear();
        mPlaceSessions.clear();
        for (Bundle sessionState : sessionStates) {
            if (sessionState == null) continue;
            java.util.ArrayList<Bundle> windowStates =
                sessionState.getParcelableArrayList(PANE_STATE_WINDOWS);
            if (windowStates == null) continue;
            WSession ws = new WSession();
            // The saved place of each window, null where its shells are gone.
            java.util.List<com.termux.app.terminal.TerminalPaneController.Window> saved =
                new java.util.ArrayList<>(windowStates.size());
            for (Bundle windowState : windowStates) {
                com.termux.app.terminal.TerminalPaneController.Window window =
                    mPaneController.restoreWindow(windowState, sessionsByHandle);
                saved.add(window);
                if (window != null) ws.windows.add(window);
            }
            restorePlaceSessions(ws, sessionState, saved, sessionsByHandle);
            if (ws.windows.isEmpty()) continue;
            ws.current = Math.max(0, Math.min(
                sessionState.getInt(PANE_STATE_CURRENT_WINDOW, 0), ws.windows.size() - 1));
            ws.name = TerminalNamePolicy.normalizeSession(sessionState.getString(PANE_STATE_SESSION_NAME));
            mWSessions.add(ws);
        }
        if (!mWSessions.isEmpty()) {
            int current = Math.max(0, Math.min(root.getInt(PANE_STATE_CURRENT_SESSION, 0),
                mWSessions.size() - 1));
            mCurrentWSession = mWSessions.get(current);
            mPaneController.showWindow(mCurrentWSession.currentWindow());
        }
    }

    /**
     * The Home floats of a saved pane layout, back on their pages around their running shells,
     * minimised as they were, neither focused nor animated in. A float whose shell is gone stays
     * gone; with no Home page to float over its shell is adopted as a window of the row instead
     * ({@link #ensureWindowsForServiceSessions}).
     */
    private void restoreHomeFloatsState(@Nullable java.util.ArrayList<Bundle> floatStates,
                                        @NonNull java.util.Map<String, TerminalSession> sessionsByHandle) {
        if (floatStates == null || floatStates.isEmpty() || mPaneController == null) return;
        attachHomeFloatLayer();
        int homeCount = mPaneController.homeFloatLayer() == null || mWidgetPaneController == null
            ? 0 : mWidgetPaneController.homePageCount();
        boolean restored = false;
        for (Bundle floatState : floatStates)
            restored |= mPaneController.restoreHomeFloat(floatState, sessionsByHandle, homeCount) != null;
        if (restored) onHomeFloatsChangedInActivity();
    }

    /** Rebuild the visible session list: one entry per session (its current window's focused shell). */
    void rebuildDrawerSessions() {
        // One wall (#357): sessions a restore or an adopted shell added fold into it first.
        foldSessionsIntoWall();
        mDrawerSessions.clear();
        if (mTermuxService != null && mPaneController != null) {
            for (WSession ws : mWSessions) {
                if (ws.windows.isEmpty()) continue;
                TerminalSession rep = mPaneController.windowActiveSession(ws.currentWindow());
                com.termux.shared.termux.shell.command.runner.terminal.TermuxSession ts = findTermuxSession(rep);
                if (ts != null) mDrawerSessions.add(ts);
            }
        }
        if (mTermuxService != null)
            mTermuxService.setVisibleSessionCount(mDrawerSessions.size());
        if (!mDrawerSessions.isEmpty()) sFirstShellStarted = true;
        // The wall's row follows the windows: the Terminal is on it while there is one, and its
        // page shows the display window while that is the row's window in front.
        if (mPaneWallController != null) {
            mPaneWallController.refreshPages();
        }
        // So does the wallpaper's pan: a window opened or closed, or another session's windows,
        // re-spread the picture over the row (a snap; an arrival that follows pans from there).
        syncWallpaperParallax();
        mDrawerShape.beginRecord();
        feedDrawerShape();
        mDrawerShape.endRecord();
        refreshTerminalWindowBar();
        // The page switcher key's number follows the current window.
        refreshPageSwitcherKey();
        // The same funnel is where the autosave hears that the windows or their trees moved.
        scheduleArrangementAutosave();
    }

    /**
     * The keyboard follows the wall. Home has nothing to type into, so it always comes back
     * closed; the terminal and the display each remember whether they were left with the keyboard
     * up and come back that way; a minimal place comes back with it down. The layout and the look
     * are the same on every place (ADR 0003), so this is the one piece of chrome a place change
     * moves: it travels with the slide as a transform (syncChromeTravel) and is committed here, at
     * settle. A widget's own text field asks for the system IME through onWidgetEditorFocused
     * instead.
     */
    private void syncWallKeyboard(@NonNull com.termux.app.page.PageKind page,
                                  boolean leavingKeyboardUp, boolean remember) {
        if (page != mLastWallPage && remember) rememberPlaceKeyboard(mLastWallPage, leavingKeyboardUp);
        // Home's keyboard is the page in front's from this landing on.
        mHomeKeyboardPageId = page == com.termux.app.page.PageKind.HOME ? mHomeSeam.pageInFront() : -1;
        // A first settle on the seeded page commits nothing new; the arrangement is still checked
        // (it only acts on a change), as the settle from the Terminal's window always did.
        if (!commitWallPage(page) && !remember) syncChromeArrangement();
        Trace.beginSection("Settle.placeKeyboard");
        applyPlaceKeyboard(page);
        Trace.endSection();
        // Wherever the wall came to rest, a restored float's landing has been had.
        mKeyboardForRestoredFloat = false;
    }

    /**
     * The chrome is committed to {@code page}: arranged by its layout variant and dressed in its
     * half's Style, Corners and Margin. Nothing happens where it already is; whether it moved.
     */
    private boolean commitWallPage(@NonNull com.termux.app.page.PageKind page) {
        if (page == mLastWallPage) return false;
        // A re-dress the last landing left for after its frame runs first, while the wall still
        // stands where it landed: a commit that follows it reads from there.
        flushLandingRestyle();
        com.termux.app.page.PageKind left = mLastWallPage;
        mLastWallPage = page;
        // A touch on the marks always ends with the page it was pressed on.
        mStatusRow.endMarksTouch();
        mMaximise.checkLater(); // Maximised is the window's: a page change away ends it.
        // The dock is dressed once in the commit: a dress the place pass makes is noted, and the
        // Dock design step below finds it worn (CommitDockDress).
        mDock.commitDockDress().begin();
        try {
            // The arrangement before the keyboard, so the keyboard's geometry pass sees the
            // chrome it will stand in.
            Trace.beginSection("Settle.arrangement");
            syncChromeArrangement();
            Trace.endSection();
            // The status host follows the committed page: the row on a page with a pane, the
            // strip on Home (StatusPresentation); a compare under the strip.
            mStatusRow.syncStatusPresentation();
            // Home wears its own Style, Corners and Margin: a crossing between halves that differ
            // dresses the chrome for the arriving one, as the variant above re-arranged it. A slide
            // whose stack already changed into that dress on the way leaves the landed frame
            // nothing to show from it, so the whole re-dress (58-88 ms on pong) follows that frame
            // instead.
            Trace.beginSection("Settle.halfDress");
            if (mLandingStackDressed) deferHalfRestyle(left, page);
            else restyleChromeForHalfIfChanged(left, page);
            Trace.endSection();
            // The dock wears the arriving page's Dock design; one design on both changes nothing.
            Trace.beginSection("Settle.dockDesign");
            mDock.restyleDockSurfaceForPageIfChanged(left, page);
            Trace.endSection();
        } finally {
            mDock.commitDockDress().end();
        }
        // The bar's readings are the same on both halves (#91); whether the bar shows decides
        // whether the sampler runs.
        Trace.beginSection("Settle.stats");
        syncStatsConsumer();
        Trace.endSection();
        return true;
    }

    /** Puts the keyboard where the place on screen remembers it, without recording anything. */
    private void applyPlaceKeyboard(@NonNull com.termux.app.page.PageKind page) {
        if (page == com.termux.app.page.PageKind.DISPLAY) {
            // The terminal's keybind hints have no meaning over the display; nothing here is
            // a launcher chord.
            mKeybindHintPresenter.hideNow(false);
        }
        // The phone's keyboard belongs to the terminal's text; anywhere else it is put away, and a
        // place that wants one raises it again through its own focus.
        if (page != com.termux.app.page.PageKind.TERMINAL) {
            KeyboardUtils.hideSoftKeyboard(TermuxActivity.this, getCurrentFocus());
        }
        if (mInAppKeyboard == null) return;
        boolean wanted = restWantsKeyboard(page);
        if (mInAppKeyboard.isVisible() == wanted) return;
        if (wanted) {
            mInAppKeyboard.show(page == com.termux.app.page.PageKind.TERMINAL
                ? com.termux.app.terminal.inappkeyboard.TermuxInAppKeyboard.ShowReason.TERMINAL_TAP
                : com.termux.app.terminal.inappkeyboard.TermuxInAppKeyboard.ShowReason
                    .KEYBOARD_ACTION);
        } else {
            mInAppKeyboard.hide(com.termux.app.terminal.inappkeyboard
                .TermuxInAppKeyboard.HideReason.WALL_PAGE);
        }
    }

    /**
     * What differs between places once the wall rests on one: the keyboard each remembers, the
     * display's touchpad, which place owns the phone's keyboard, and which extra keys have
     * anything to act on. Nothing is re-laid or re-styled, because the layout and the look are the
     * same everywhere. A settle back onto the page the wall was already on changes nothing, so a
     * drag that springs back leaves the keyboard alone.
     */
    private void syncPlaceState(@NonNull com.termux.app.page.PageKind page,
                                boolean leavingKeyboardUp) {
        // The first settle is measured from the Terminal's window, the page every first settle
        // left before the opening page was seeded, so a cold start lands exactly as it did; the
        // chrome is already dressed for the seed, and a seed the wall did not land on is
        // corrected here. No keyboard is recorded for a page that was never left.
        boolean first = !mWallSettledOnce;
        mWallSettledOnce = true;
        com.termux.app.page.PageKind from =
            first ? com.termux.app.page.PageKind.TERMINAL : mLastWallPage;
        if (page == from) {
            if (first && commitWallPage(page))
                mChrome.requestSync(ChromeRenderer.SCOPE_APPLY_THIS_FRAME);
            return;
        }
        boolean overlayChanged = KeyboardOverlayPolicy.changesBetween(from, page,
            arrangement().layout());
        Trace.beginSection("Settle.wallKeyboard");
        syncWallKeyboard(page, leavingKeyboardUp, !first);
        Trace.endSection();
        Trace.beginSection("Settle.placeOwners");
        mTouchpad.syncDisplayTouchpad();
        applyPlaceSystemImeOwner();
        applyExtraKeysPlaceEligibility();
        Trace.endSection();
        // One chrome pass at rest, for the two pieces of geometry that are the place's by design:
        // the terminal alone pads the dock down to a whole text row, and Home and the display can
        // float an open keyboard over their content where the terminal gives it room. An
        // overlaying keyboard also paints an opaque fill rather than glass
        // (KeyboardMaterialPolicy), so a keyboard that stayed up across that change is repainted.
        // The content's room changes with it: a slide's settle lays the content out again anyway,
        // but a window switch to or from the display window has no slide behind it, and without
        // this pass the terminal would keep the display's floating keyboard over its rows.
        int scopes = ChromeRenderer.SCOPE_APPLY_THIS_FRAME;
        if (overlayChanged) {
            scopes |= ChromeRenderer.SCOPE_ACCESSORY_RENDER | ChromeRenderer.SCOPE_KEYBOARD_BACKDROP;
            mGeometry.requestNow(GeometryScheduler.Reason.PLACE_SETTLE,
                GeometryScheduler.ResizePolicy.NOW);
        }
        mChrome.requestSync(scopes);
    }

    /**
     * The stack dressed again for the half it now stands in, mid-slide: the dock's rows and its
     * glass, the suggestion bar over the keyboard, and the chrome's crops and sheets. The status
     * bar and the frame read their own dress (SeamDress) and come out as they were. The sizes, the
     * keyboard's included, follow through the seam's layout pass that runs next, and the keyboard
     * is dressed by the geometry pass that measures it. Only while the halves dress the stack
     * differently, and only where none of it shows.
     */
    private void restyleStackForDress(boolean shapeDiffers) {
        if (mPreferences == null || mChrome == null) return;
        Trace.beginSection("Wall.seamDress");
        try {
            updateAppLauncherBarHeight();
            applySuggestionBarSurfaceStyling();
            if (shapeDiffers) {
                mChrome.redressFromState();
            } else {
                mChrome.requestSync(ChromeRenderer.SCOPE_APPLY_THIS_FRAME
                    | ChromeRenderer.SCOPE_ACCESSORY_RENDER);
            }
        } finally {
            Trace.endSection();
        }
    }

    /** The bar host's plain glass layers: what a Margin ease stretches, and nothing else. */
    private static final int[] BAR_GLASS_LAYERS = {R.id.terminal_window_bar_background,
        R.id.terminal_window_bar_background_side, R.id.terminal_status_lens};

    /**
     * The bar drawn {@code insetPx} from each side while laid out at the committed page's Margin
     * (com.termux.app.place.BarMarginEase): its glass layers stretch about the host's centre, its
     * outline (which clips them on a card) grows or shrinks with them, and its content keeps its
     * size, each end's cluster drawn moved with its edge. The host itself is never scaled. Writes
     * only what moved; no layout.
     */
    private void applyBarMarginEase(@Nullable View host, float insetPx) {
        if (host == null || host.getWidth() <= 0 || !(host.getParent() instanceof View)) return;
        View parent = (View) host.getParent();
        float room = parent.getWidth() - parent.getPaddingLeft() - parent.getPaddingRight();
        // The inset it is laid out at, read from where it stands: its margins are even.
        float grow = com.termux.app.place.BarMarginEase.growPx((room - host.getWidth()) / 2f,
            insetPx);
        if (host.getScaleX() != 1f) host.setScaleX(1f);
        float centre = host.getWidth() / 2f;
        for (int id : BAR_GLASS_LAYERS) easeBarGlassLayer(hotView(id), centre, grow, host.getWidth());
        if (host.getOutlineProvider() == mStatusBar.statusBarSurfaceOutline()
            && mStatusBar.statusBarSurfaceOutline().setHorizontalGrow(Math.round(grow)))
            host.invalidateOutline();
        com.termux.app.statusbar.StatusRowLayout row = hotView(R.id.terminal_status_row);
        if (row != null) row.setEdgeGrow(grow);
        com.termux.app.statusbar.TopPaneWidgetSlot slot = hotView(R.id.terminal_top_widget_area);
        if (slot != null) slot.setEdgeGrow(grow);
    }

    /**
     * One glass layer of the bar, stretched about the host's centre by {@code grow} a side. A
     * card of a bar split round the camera stands against one host edge only: it stretches from
     * its inner edge, so the edge at the hole stays where the camera is and the outer one moves.
     */
    private static void easeBarGlassLayer(@Nullable View layer, float hostCentre, float grow,
                                          int hostWidth) {
        if (layer == null || layer.getWidth() <= 0) return;
        boolean atLeft = layer.getLeft() <= 0;
        boolean atRight = layer.getRight() >= hostWidth;
        float pivot;
        float scale;
        if (atLeft == atRight) {
            pivot = hostCentre - layer.getLeft();
            scale = com.termux.app.place.BarMarginEase.layerScale(pivot, grow);
        } else {
            float width = layer.getWidth();
            scale = Math.max(0.01f, (width + grow) / width);
            pivot = atLeft ? width : 0f;
        }
        if (layer.getPivotX() != pivot) layer.setPivotX(pivot);
        if (layer.getScaleX() != scale) layer.setScaleX(scale);
    }

    /** The bar's glass layers, outline and content drawn as laid out again. */
    private void resetBarMarginEase(@NonNull View host) {
        if (host.getScaleX() != 1f) host.setScaleX(1f);
        for (int id : BAR_GLASS_LAYERS) {
            View layer = findViewById(id);
            if (layer != null && layer.getScaleX() != 1f) layer.setScaleX(1f);
        }
        if (mStatusBar.statusBarSurfaceOutline().setHorizontalGrow(0)
            && host.getOutlineProvider() == mStatusBar.statusBarSurfaceOutline())
            host.invalidateOutline();
        com.termux.app.statusbar.StatusRowLayout row = findViewById(R.id.terminal_status_row);
        if (row != null) row.setEdgeGrow(0f);
        com.termux.app.statusbar.TopPaneWidgetSlot slot = findViewById(R.id.terminal_top_widget_area);
        if (slot != null) slot.setEdgeGrow(0f);
    }

    /**
     * What a place's chrome looks like at rest, for the travel: the place the chrome is committed
     * to answers from what is on screen, every other place from its memory.
     *
     * <p>No place is a travel {@code minimal} one any more: minimal mode has a layout of its own,
     * shared by every place, so whatever dock rows and keyboard it keeps are laid out and travel
     * like any layout's. Answering the mode here read as a dock with nothing showing on both sides
     * of every slide, and slid the whole stack off the screen until the wall settled.
     */
    @NonNull
    private com.termux.app.place.PlaceChromeTravel.Rest chromeRestOf(
            @NonNull com.termux.app.page.PageKind place) {
        boolean keyboardUp = sideRestKeyboardUp(place);
        // A Home page wears the bar too (#90); only one whose layout puts it away has none, and
        // the window's then fades on the way there.
        if (place == com.termux.app.page.PageKind.HOME && !homeWearsBarAtRest())
            return keyboardUp ? REST_HOME_KEYBOARD_UP : REST_HOME_KEYBOARD_DOWN;
        return keyboardUp ? REST_KEYBOARD_UP : REST_KEYBOARD_DOWN;
    }

    /**
     * Whether {@code place}'s own rest has its keyboard up ({@code SideCards#restKeyboardUp}):
     * what a crossing's end toward it reads and what the two cards lay the parked side out with.
     */
    private boolean sideRestKeyboardUp(@NonNull com.termux.app.page.PageKind place) {
        boolean front = place == mLastWallPage;
        return com.termux.app.place.SideCards.restKeyboardUp(front,
            front && committedKeyboardVisible(), !front && restWantsKeyboard(place));
    }

    /**
     * Whether Home's layout shows the status bar, from what is already resolved and held (asked
     * per frame, so it reads no store): the committed layout while the chrome is on Home, else
     * the other half's as the seam read it once for this gesture; shown until either says.
     */
    private boolean homeWearsBarAtRest() {
        PlaceLayout home = null;
        if (mLastWallPage == com.termux.app.page.PageKind.HOME) {
            if (mHomeArrangement != null) home = mHomeArrangement.layout();
        } else if (mCrossing.seam().other() == com.termux.app.page.PageKind.HOME) {
            home = mCrossing.seam().otherLayout();
        }
        return home == null || !home.slot(Element.STATUS).hidden;
    }

    /** The rests a page can have (the Rest is immutable), so a slide frame allocates none. */
    private static final com.termux.app.place.PlaceChromeTravel.Rest REST_KEYBOARD_UP =
        new com.termux.app.place.PlaceChromeTravel.Rest(true, false);
    private static final com.termux.app.place.PlaceChromeTravel.Rest REST_KEYBOARD_DOWN =
        new com.termux.app.place.PlaceChromeTravel.Rest(false, false);
    private static final com.termux.app.place.PlaceChromeTravel.Rest REST_HOME_KEYBOARD_UP =
        new com.termux.app.place.PlaceChromeTravel.Rest(true, false, false);
    private static final com.termux.app.place.PlaceChromeTravel.Rest REST_HOME_KEYBOARD_DOWN =
        new com.termux.app.place.PlaceChromeTravel.Rest(false, false, false);
    /** {@link #chromeRestOf} as the travel asks it, bound once rather than per frame. */
    private final com.termux.app.place.PlaceChromeTravel.States mChromeRestStates = this::chromeRestOf;

    /**
     * Whether the keyboard can be brought up below the screen for a slide. A floating keyboard is
     * a frame of its own over the place rather than a band of the stack, so it has nothing to
     * travel with and keeps its settle-time show; so does a keyboard the system IME stands in for.
     */
    private boolean canPreRollTravelKeyboard() {
        return mInAppKeyboard != null && mInAppKeyboard.isEnabled() && !isKeyboardFloating()
            && arrangement().layout().keyboardForm != PlaceLayout.KeyboardForm.FLOATING
            && !isImeVisible();
    }

    /** From here to settle, the content keeps the room it was committed with. */
    private void beginTravelHold() {
        mCrossing.hold(appliedContentReservationPx());
    }

    /**
     * The same, for the keyboard of {@code target}: the place a slide is travelling toward, or the
     * place on screen for a keyboard swipe that raises it under the finger.
     */
    private void preRollTravelKeyboard(@NonNull com.termux.app.page.PageKind target) {
        if (mInAppKeyboard == null) return;
        if (MotionLog.enabled) {
            MotionLog.log("keyboard-preroll", "target=" + target + " can=" + canPreRollTravelKeyboard());
        }
        Trace.beginSection("Wall.preRollKeyboard");
        try {
            // Under the hold, which the keyboard's room starts if nothing has yet; the crossing's
            // keyboard adapter shows it (CrossingViews#preRoll).
            mCrossing.preRollKeyboard(target, appliedContentReservationPx());
        } finally {
            Trace.endSection();
        }
    }

    /**
     * The extra-keys row's height for the device's key rows and scale, whether or not the place on
     * screen stands the row: the height the geometry pass gives it on a place that does
     * (StackLayout#extraKeysRowPx). Before the pager's XML height is read, the applied one.
     */
    private int measuredExtraKeysRowPx() {
        if (mTerminalToolbarDefaultHeight <= 0 || mProperties == null)
            return appliedToolbarHeightPx();
        // The bar's committed page owns the number: the rows of the page that has landed, the
        // text input counting as one. Page 1's rows only while the bar has no pages yet.
        int matrix = 0;
        ExtraKeysBarView bar = getTerminalToolbarViewPager();
        if (bar != null && bar.pageCount() > 0) {
            matrix = bar.committedRows();
        } else {
            matrix = extraKeysPageOneRows();
        }
        float scale = bar != null && bar.pageCount() > 0 ? bar.committedScale() : extraKeysScale();
        return AccessoryStackLayoutPolicy.computeTerminalToolbarHeightPx(
            Math.round(mTerminalToolbarDefaultHeight), matrix, scale);
    }

    /** The extra-keys row's height as the last pass set it, 0 while the row is off. */
    private int appliedToolbarHeightPx() {
        ExtraKeysBarView pager = getTerminalToolbarViewPager();
        ViewGroup.LayoutParams params = pager == null ? null : pager.getLayoutParams();
        return params == null ? 0 : Math.max(0, params.height);
    }

    /** The room the stack last took from the content root; -1 until the first pass. */
    private int appliedContentReservationPx() {
        return mAppliedStack == null ? -1 : mAppliedStack.contentReservationPx;
    }

    /**
     * Gives the content the arriving place's roomier room for the rest of the slide, in the frame
     * the slide starts: the hold's reservation drops by the room given back, and the geometry pass
     * lets the content reach under the chrome by exactly that. The terminal's grid is paused
     * under the change so the PTY hears one size, at settle; the other pages take their room now,
     * which for the display is the slide's whole length for the X server to repaint in.
     */
    private void preRollTravelContent(int roomGivenBackPx) {
        Trace.beginSection("Wall.preRollContent");
        try {
            if (mCrossing.giveRoomBack(roomGivenBackPx, appliedContentReservationPx())) {
                mCrossing.gridHold(mGeometry.begin(GeometryScheduler.Reason.PLACE_TRAVEL,
                    false, false));
            }
            // In this frame: the slide's first frame is drawn with the content's new room.
            mGeometry.requestNow(GeometryScheduler.Reason.PLACE_TRAVEL,
                GeometryScheduler.ResizePolicy.AT_SETTLE);
        } finally {
            Trace.endSection();
        }
    }

    /**
     * The settle's counterpart: after the settle's layout the paused panes each send the PTY
     * their one size, anchored at the bottom the way the status bar's fold does. The scheduler
     * resumes them behind the traversal that applies the settle's geometry.
     */
    private void finishTravelContentResizeAfterLayout(
            @Nullable GeometryScheduler.Transition hold) {
        mGeometry.settle(hold, false);
    }

    /**
     * The slide landed: every pane's travel ends on the resize it was drawn toward, or now. The
     * reflow is frosted only where it can be seen, on the terminal, and not under lazy mode or
     * reduced motion, which stop every animation.
     */
    private void settleTerminalTravelDisplacement() {
        if (mPaneController == null) return;
        boolean frost = isTerminalTravelFrostAllowed();
        for (com.termux.view.TerminalView view : mPaneController.getVisiblePaneViews()) {
            view.settleTravelDisplacement(frost);
        }
    }

    /** Whether a travel's frost can be seen and is wanted: on the terminal, with motion allowed. */
    private boolean isTerminalTravelFrostAllowed() {
        return !isReducedMotionEnabled() && !isLazyModeEnabled()
            && mPaneWallController != null && mPaneWallController.isTerminalShowing();
    }

    /**
     * The stack's translation at keyboard reveal {@code shown} (0 down, 1 up): the keyboard's laid
     * out height less what has come up. The one formula for the swipe's frame and for the Home
     * pill riding it.
     */
    private float keyboardTravelTranslationPx(float shown) {
        return travelKeyboardLaidOutPx() * (1f - shown);
    }

    /**
     * The keyboard's keys' height as the stack lays it out; 0 while it is down or floating. What
     * the travel slides: the foot below the keys is the keyboard's own and goes with the cut.
     */
    private int travelKeyboardLaidOutPx() {
        if (!isInAppKeyboardShown() || isKeyboardFloating()) return 0;
        return inAppKeyboardKeysPx(Math.max(0, mKeyboardGeometry.desiredHeightPx()));
    }

