    /**
     * The wall came to rest on {@code page}: the travel's transforms are put back, and what the
     * slide showed becomes the layout — the keyboard the place wants, the arrangement minimal mode
     * asks for, and the content's room, with one terminal resize for all of it. A slide that came
     * back to where it started undoes its pre-rolls instead, and the content, held all along,
     * never moved.
     */
    private void settlePlaceChrome(@NonNull com.termux.app.page.PageKind page) {
        settlePlaceChrome(page, null);
    }

    /**
     * The same, with the page the crossing lands on named ({@code landed}): a crossing between two
     * Home pages lands on the Home page Home's pager settled on, by its id, while the wall stays on
     * Home throughout. Null lands on {@code page} as the store shows it.
     */
    private void settlePlaceChrome(@NonNull com.termux.app.page.PageKind page,
                                   @Nullable com.termux.app.wall.PageRef landed) {
        // A landing still waiting for its post lands first, so this settle reads it done.
        flushLandedFrameSettle();
        Trace.beginSection("Wall.settleChrome");
        try {
            doSettlePlaceChrome(page, landed);
            // The terminal effect is the Terminal's: Home's chrome lands plain (ChromeRetroEffect).
            Trace.beginSection("Settle.deckLook");
            if (mChromeRetroEffect != null)
                mChromeRetroEffect.setOnHome(page == com.termux.app.page.PageKind.HOME);
            applyDeckLook();
            Trace.endSection();
        } finally {
            mPlacePassGate.end();
            Trace.endSection();
        }
        // The keyboard put away is measured once the landed frame is out, so the next swipe's
        // first frame shows it without laying it out from scratch.
        getWindow().getDecorView().removeCallbacks(mKeyboardPrewarmRunnable);
        getWindow().getDecorView().post(mKeyboardPrewarmRunnable);
        // A keyboard the travel brought up hands the phone's keyboard over once the landed frame
        // is out: the hand-over relayouts the whole window (4-5 ms of a drag frame on pong).
        getWindow().getDecorView().removeCallbacks(mLandTravelKeyboardRunnable);
        getWindow().getDecorView().post(mLandTravelKeyboardRunnable);
    }

    private final Runnable mLandTravelKeyboardRunnable = () -> {
        // A crossing under way again keeps the hold; its own landing posts this again.
        if (isDestroyed() || mInAppKeyboard == null || mCrossing.crossing()) return;
        mInAppKeyboard.landTravelShow();
    };

    private final Runnable mKeyboardPrewarmRunnable = () -> {
        if (isDestroyed() || mInAppKeyboard == null || mCrossing.crossing()) return;
        mInAppKeyboard.prewarm();
    };

    private void doSettlePlaceChrome(@NonNull com.termux.app.page.PageKind page,
                                     @Nullable com.termux.app.wall.PageRef landed) {
        // Everything the settle shows, hides and lays out asks for its geometry inside one batch:
        // a keyboard going away, the place's own keyboard coming up and the content's room are
        // one pass, run in this frame at the batch's end.
        boolean held = false;
        boolean contentPreRolled = false;
        boolean moved = false;
        boolean storeMoved = false;
        GeometryScheduler.Transition gridHold = null;
        mPlacePassGate.begin();
        mGeometry.beginBatch();
        try {
            // A keyboard swipe still landing lands first: it owns the same travel state.
            settleKeyboardSwipeTravelNow();
            boolean leavingKeyboardUp = committedKeyboardVisible();
            moved = mChromeTravelMoved;
            com.termux.app.page.PageKind left = mLastWallPage;
            // The half whose look the status bar wore through the slide: the Terminal's while
            // the wall slid across the seam (SeamDress), its own half's otherwise.
            int statusHalfTravelled = mStatusBar.statusLookPage();
            mChromeTravelMoved = false;
            // The material blend, if one ran, has landed on the arriving place's material; the
            // pass below paints that material plainly, and the blend's layers go with it.
            mKeyboardTravelSolidness = KeyboardMaterialPolicy.NO_TRAVEL;
            mKeyboardTravelSolidFill = null;
            // The crossing lands (Crossing#land), clearing in one step everything it held: the
            // content's hold and the cover the pane controller kept on the window in front (the
            // geometry pass below lays the panes out at the size the cover stood in for, in the
            // same traversal), the keyboard's and the content's pre-rolls, the stack's
            // translation, sink and alphas, the bar's ride, and a fold's and a melt's shares. From
            // here the chrome reads the store's arrangements again.
            Trace.beginSection("Settle.land");
            com.termux.app.place.Crossing.Landing crossingLanding =
                mCrossing.land(landed != null ? landed : shownEndpointPageOf(page),
                    arrangementRevision());
            storeMoved = crossingLanding.storeMoved();
            // The stack's next frame is the landing's: it should write nothing new.
            mStackRenderer.onLanding();
            mTopStackRenderer.onLanding();
            // And the next chrome commit is its landing's: within a side it may move rows to the
            // arriving page's edges; between Home and the Terminal it writes none.
            mRowsGuard.onLanding(
                com.termux.app.page.Side.of(left == com.termux.app.page.PageKind.HOME),
                com.termux.app.page.Side.of(page == com.termux.app.page.PageKind.HOME),
                true);
            Trace.endSection();
            boolean keyboardPreRolled = crossingLanding.keyboardPreRolled();
            contentPreRolled = crossingLanding.contentPreRolled();
            held = crossingLanding.held();
            gridHold = crossingLanding.gridHold();
            // The seam's crossing lands with it (SeamCrossing.land): a half's own bands land as the page
            // did, the commit below laying them out for the page it lands on and a slide that came
            // back laying them out whole again just after; the seam's arrangement gives way to
            // the committed one (landed on the other half, commitWallPage arranges it by that
            // half's layout, which stands the same rows; back where it started, the pass below
            // puts the committed rows back, already off screen); and the bar is dressed for its
            // own page again. The stack keeps the dress it travelled in through the page's commit
            // below, which dresses everything for the page it lands on: landed, that is the dress
            // the stack already wears (SeamCrossing.end). The status bar is at rest from here
            // (SeamCrossing.sliding), so the commit dresses it, its glass and the strip behind the
            // system status bar together, in the landed half's look.
            com.termux.app.place.SeamCrossing.Landing seamLanding = crossingLanding.seam();
            // Melting beads land as the page did: their own size on the beaded half, the slab
            // on the other.
            boolean beadsMelted = crossingLanding.beadsMelted();
            // A keyboard pre-rolled for a place the wall did not stay on goes away quietly, as it
            // came: the place under it never had it up. One the arriving place wants is already
            // where it belongs, and the place's own sync below finds nothing to do.
            if (keyboardPreRolled && mInAppKeyboard != null && mInAppKeyboard.isVisible()
                && (page == left || !restWantsKeyboard(page))) {
                mQuietKeyboardChange = true;
                try {
                    mInAppKeyboard.hide(com.termux.app.terminal.inappkeyboard.TermuxInAppKeyboard
                        .HideReason.WALL_PAGE);
                } finally {
                    mQuietKeyboardChange = false;
                }
            } else if (keyboardPreRolled && page != left
                && page == com.termux.app.page.PageKind.DISPLAY && mDisplayServer.controller() != null
                && mInAppKeyboard != null && mInAppKeyboard.isVisible()) {
                // The display hears the keyboard come up as the place's own, which is what the
                // settle-time show the pre-roll stood in for would have told it.
                mDisplayServer.controller().onUserKeyboardIntent(true);
            }
            // The strip's crossing has landed on one end's dress: the commit below dresses it
            // plainly, as that end wears it.
            Trace.beginSection("Settle.fades");
            endTopBandFade();
            // The dock's frost lands on the page the wall did, whatever share the blend last saw.
            landDockGroundBlend(page != left);
            mCrossingController.endEndBlend();
            Trace.endSection();
            // A stack dressed for the landed half on the way: the landed frame already shows what
            // the half's re-dress would, which follows it.
            mLandingStackDressed = seamLanding.stackDressedFor(page);
            // A keyboard laid out down that the arriving place wants is shown where the travel
            // already stood it (reveal 1, translation 0): quietly, with no reveal and no second
            // movement. One the place does not want stays laid out down.
            boolean quietShow = !keyboardPreRolled && !leavingKeyboardUp && page != left
                && mKeyboardDownLaidOutPx > 0 && mInAppKeyboard != null
                && !mInAppKeyboard.isVisible() && restWantsKeyboard(page);
            Trace.beginSection("Settle.placeState");
            if (quietShow) {
                mQuietKeyboardChange = true;
                mKeyboardOpensBelowScreen = true;
            }
            try {
                syncPlaceState(page, leavingKeyboardUp);
            } finally {
                mQuietKeyboardChange = false;
                mKeyboardOpensBelowScreen = false;
                mLandingStackDressed = false;
                Trace.endSection();
            }
            // The display hears the keyboard come up as the place's own, as it heard the shown
            // keyboard's own listener before the show went quiet.
            if (quietShow && page == com.termux.app.page.PageKind.DISPLAY
                && mDisplayServer.controller() != null && mInAppKeyboard.isVisible()) {
                mDisplayServer.controller().onUserKeyboardIntent(true);
            }
            Trace.beginSection("Settle.away");
            if (beadsMelted) mDock.applyDockBeadMelt(true);
            if (seamLanding.bandsMoved() && page == left && setTerminalToolbarHeight(false))
                mChrome.requestSync(ChromeRenderer.SCOPE_APPLY_THIS_FRAME
                    | ChromeRenderer.SCOPE_ACCESSORY_RENDER);
            Trace.endSection();
            Trace.beginSection("Settle.tail");
            mCrossing.end();
            // The top stack rests on the page the wall landed on.
            restTopStack(page);
            syncLegibilityCrossing();
            // What waits for the landed frame (the half's re-dress, the even-out's settle) runs
            // just after it.
            postLandingSettle();
            // A slide that came back to Home committed nothing, so no commit dressed the status
            // bar back out of the Terminal's look it slid in. Its glass and the strip behind the
            // system status bar are glazed again here, together, in Home's, or the strip alone
            // takes Home's at the next insets pass and parts from the pane below it.
            if (page == left && mStatusBar.statusLookPage() != statusHalfTravelled
                && mStatusBar.statusDressDiffersAcrossHalves())
                refreshTerminalWindowBar();
            // A slide that came back past the swap without a frame there to undo it (the drawer
            // or reduced motion took the last frames) leaves the stack dressed for the half it did
            // not land on: it is dressed back now, in the frame that puts the stack back on screen.
            if (seamLanding.redressesBack(mLastWallPage)) {
                restyleStackForDress(seamLanding.shapeDiffered());
                syncPlaceLayout();
                // And its rows carry their own half's Drawer tile again.
                syncDrawerTile();
            }
            // A slide in that came back takes its slab's design back too, in the frame the
            // stack is put back on screen; one that landed had it worn by the commit.
            if (mDockDesignTravelledTo != null && mDockDesignTravelledTo != mLastWallPage)
                mDock.restyleDockSurface();
            mDockDesignTravelledTo = null;
            // Resting on the Terminal, the canvas comes back down below the bar, its pages out of
            // the band with it, so nothing on screen moves (PageTopInsets).
            syncCanvasTopReach();
            mStatusRow.logRow("landing");
            // A pass that finds the arrangement already applied changes nothing.
            // The landing's commit has laid the place out already; a second pass on the same
            // inputs finds nothing to do (15 ms of the landed frame on pong, run twice).
            if ((seamLanding.laidOut() || storeMoved) && !placeLayoutPassRedundant())
                syncPlaceLayout();
            // A store that moved under the slide (its readers read the held arrangements till
            // now) is applied here, whole: the chrome dressed and the geometry laid out again.
            if (storeMoved) {
                mChrome.requestSync(ChromeRenderer.SCOPE_APPLY_THIS_FRAME
                    | ChromeRenderer.SCOPE_ACCESSORY_RENDER);
                mGeometry.requestNow(GeometryScheduler.Reason.PLACE_SETTLE,
                    GeometryScheduler.ResizePolicy.NOW);
            }
            if (seamLanding.barTravelled()) syncPlaceBar();
            // Every landing, a jump with the house key included: the selected chip is a window to
            // close only where that window is on screen.
            com.termux.app.terminal.TerminalWindowBar landedBar = findViewById(R.id.terminal_window_bar);
            if (landedBar != null) landedBar.setSelectedChipOffersClose(
                com.termux.app.terminal.TerminalWindowBar.selectedChipOnScreen(page));
            Trace.endSection();
            // The hold is over: one geometry pass gives the content the room the place it landed
            // on leaves it, which is the terminal's one resize for the whole slide. A slide that
            // gave the room back in its first frame finds it already right, and only the grid's
            // resize is left; the rows are drawn where it lands until it does.
            if (held) mGeometry.requestNow(GeometryScheduler.Reason.PLACE_SETTLE,
                GeometryScheduler.ResizePolicy.NOW);
        } finally {
            Trace.beginSection("Settle.geometry");
            mGeometry.endBatch();
            Trace.endSection();
        }
        Trace.beginSection("Settle.contentResize");
        if (contentPreRolled) finishTravelContentResizeAfterLayout(gridHold);
        if (held) settleTerminalTravelDisplacement();
        Trace.endSection();
        // The crops were cut where the stack was laid out; one pass re-cuts any a frame of the
        // slide drew somewhere else.
        if (moved || held) mChrome.requestSync(ChromeRenderer.SCOPE_ACCESSORY_RENDER);
    }

    /**
     * Applies the minimal or the normal layout, and the status strip, when minimal mode has
     * changed since it was last applied.
     */
    private void syncChromeArrangement() {
        com.termux.app.place.LayoutVariant variant = chromeVariant();
        // On the one shared layout a crossing keeps the variant: what Home leaves out is the
        // change, so the half is compared too.
        boolean home = mLastWallPage == com.termux.app.page.PageKind.HOME;
        if (variant == mAppliedChromeVariant && Boolean.valueOf(home).equals(mAppliedChromeHome))
            return;
        mAppliedChromeVariant = variant;
        mAppliedChromeHome = home;
        syncPlaceLayout();
        Trace.beginSection("Place.statusChrome");
        mStatusBar.applyMinimalStatusChrome();
        Trace.endSection();
    }

    // ---- Minimal mode ------------------------------------------------------------------------

    /**
     * Turns minimal mode (CONTEXT.md) on or off for the whole launcher, from the corner tab of
     * whichever place is on screen: the only door in or out, so the mode never ends on its own.
     * Minimal mode is a second saved layout and nothing more: on, the place's keyboard memory is
     * kept as it was, the keyboard goes away and the chrome is arranged by the minimal layout;
     * off, the normal layout comes back, keyboard included. Everything else, the panes included,
     * works as it does in the normal layout.
     */
    /** The minimal mode the window was last dressed for; null until a change is applied. */
    @Nullable private Boolean mMinimalApplied;

    void setMinimalMode(boolean minimal) {
        PlaceLayoutStore store = placeLayoutStore();
        if (store == null) return;
        // The mode the window shows can differ from the stored one while the Appearance editor's
        // draft is dropped under it: Discard puts the stored value back, and the window follows.
        Boolean applied = mMinimalApplied;
        if (store.isMinimal() == minimal && (applied == null || applied == minimal)) return;
        mMinimalApplied = minimal;
        com.termux.app.page.PageKind place = mLastWallPage;
        // Home ignores minimal mode (it is the windows' alone), so from Home only the flag moves:
        // Home's keyboard is its own, and the window's memory stays as it was left.
        boolean onHome = place == com.termux.app.page.PageKind.HOME;
        // Recorded before the mode is on, since minimal mode records nothing.
        if (minimal && !onHome) rememberPlaceKeyboard(place);
        store.setMinimal(minimal);
        if (minimal && !onHome && mInAppKeyboard != null && mInAppKeyboard.isVisible()) {
            mInAppKeyboard.hide(com.termux.app.terminal.inappkeyboard.TermuxInAppKeyboard
                .HideReason.KEYBOARD_ACTION);
        }
        syncChromeArrangement();
        if (!minimal && !onHome) applyPlaceKeyboard(place);
        invalidateMinimalModeGlyphs();
    }

    /** The corner tabs draw the glyph from the state, so a change only has to redraw them. */
    private void invalidateMinimalModeGlyphs() {
        if (mPaneWallController != null && mPaneWallController.displayWindow() != null)
            mPaneWallController.displayWindow().invalidateControls();
        if (mPaneWallController != null && mPaneWallController.widgetsPage() != null)
            mPaneWallController.widgetsPage().invalidateControls();
        if (mPaneController != null) mPaneController.invalidateControls();
    }

    /**
     * Writes a keyboard type for the orientation on screen and re-runs the arrangement, which is
     * what tells the keyboard the type moved. The type is every place's, like the rest of the
     * layout. False before there are preferences to write it to.
     */
    private boolean setKeyboardFormForCurrentPlace(@NonNull PlaceLayout.KeyboardForm form) {
        PlaceLayoutStore store = placeLayoutStore();
        if (store == null) return false;
        store.setKeyboardForm(currentPlaceOrientation(), form);
        syncPlaceLayout();
        return true;
    }

    /** Records how a place is being left, so it has something to come back to. */
    private void rememberPlaceKeyboard(@NonNull com.termux.app.page.PageKind place) {
        rememberPlaceKeyboard(place, committedKeyboardVisible());
    }

    private void rememberPlaceKeyboard(@NonNull com.termux.app.page.PageKind place,
                                       boolean keyboardUp) {
        PlaceLayoutStore store = placeLayoutStore();
        // Before the keyboard exists there is nothing to record: a cold start restoring the wall
        // onto another place would otherwise write the terminal's memory down as closed.
        if (store == null || mInAppKeyboard == null) return;
        // Minimal mode put the keyboard away itself; recording that would lose the keyboard the
        // place had before, which is what leaving minimal mode is meant to bring back.
        if (store.isMinimal()) return;
        // On Home the keyboard is kept per page (the crossing rule's Q1): the page that owns it.
        if (place == com.termux.app.page.PageKind.HOME) {
            rememberHomePageKeyboard(homeKeyboardPageId(), keyboardUp);
            return;
        }
        // Up on the drawer search's behalf (raised by it, not claimed since) it is not the place's.
        store.setKeyboardOpen(place, com.termux.app.place.PlaceKeyboard.keyboardToRemember(keyboardUp,
            mSheets.drawerRaisedKeyboard() && !mSheets.drawerRaisedKeyboardClaimed(),
            store.wasKeyboardOpen(place)));
    }

    // ---- The keyboard per Home page (the crossing rule's Q1) ----------------------------------

    /**
     * The Home page that owns the keyboard on screen: the one the wall or Home's pager last came
     * to rest on, -1 off Home. A pager step names its pages by id; this one's keyboard is the
     * keyboard as it is now, every other page's is its memory.
     */
    private int mHomeKeyboardPageId = -1;
    /** One page's answer to {@link #homePageHoldsTerminal}, read once per pager step or rest. */
    private int mHomeTerminalPageId = -1;
    private boolean mHomeTerminalPageHolds;

    private int homeKeyboardPageId() {
        return mHomeKeyboardPageId >= 0 ? mHomeKeyboardPageId : mHomeSeam.pageInFront();
    }

    /**
     * Home's page turned with no slide for the pager's rest to follow: the page in front takes
     * its own keyboard now. A slide under way lands through the pager's rest instead.
     */
    private final Runnable mHomeTurnWithoutSlide = () -> {
        if (mWidgetPaneController == null || mWidgetPaneController.isHomePageSettling()
            || mWidgetPaneController.homePageShiftFraction() != 0f) return;
        onHomePageAtRest();
    };

    /** Whether Home page {@code pageId} holds a floating or widget terminal to type into. */
    private boolean homePageHoldsTerminal(int pageId) {
        if (pageId == mHomeTerminalPageId) return mHomeTerminalPageHolds;
        int index = wallPages().homePageIdsForRepository().indexOf(pageId);
        boolean holds = index >= 0 && mPaneController != null
            && mPaneController.homeFloatCountOn(index) > 0;
        if (!holds && index >= 0 && mWidgetHostController != null) {
            for (com.termux.app.launcher.widget.LauncherWidgetRecord record
                    : mWidgetHostController.repository().records()) {
                if (record.page == index && com.termux.app.launcher.widget.builtin.BuiltinWidgetKind
                        .TERMINAL.id.equals(record.builtinKind)) {
                    holds = true;
                    break;
                }
            }
        }
        mHomeTerminalPageId = pageId;
        mHomeTerminalPageHolds = holds;
        return holds;
    }

    /** Whether the Home page in front was left with its keyboard up and keeps it. */
    private boolean homePageKeyboardRemembered(@NonNull PlaceLayoutStore store) {
        int front = mHomeSeam.pageInFront();
        return front >= 0 && com.termux.app.place.PlaceKeyboard.homePageKeyboardUp(false,
            store.wasHomePageKeyboardOpen(front), homePageHoldsTerminal(front));
    }

    /**
     * Home page {@code pageId}'s keyboard as a crossing end carries it: the keyboard on screen for
     * the page that owns it, every other page's memory, up only where it holds a terminal (or
     * always on).
     */
    private int homePageKeyboard(int pageId) {
        PlaceLayoutStore store = placeLayoutStore();
        if (store == null || mInAppKeyboard == null || pageId < 0)
            return com.termux.app.place.StackEnd.PAGE_KEYBOARD_REST;
        // The page that owns the keyboard is fixed for the whole step: read after the pager's
        // commit, the page in front is already the arriving one.
        if (mHomeKeyboardPageId < 0 && mLastWallPage == com.termux.app.page.PageKind.HOME)
            mHomeKeyboardPageId = mHomeSeam.pageInFront();
        if (pageId == homeKeyboardPageId())
            return com.termux.app.place.PlaceKeyboard.pageKeyboard(committedKeyboardVisible());
        return com.termux.app.place.PlaceKeyboard.pageKeyboard(
            com.termux.app.place.PlaceKeyboard.homePageKeyboardUp(store.isHomeKeyboardAlwaysOn(),
                store.wasHomePageKeyboardOpen(pageId), homePageHoldsTerminal(pageId)));
    }

    /** Records Home page {@code pageId} as left with {@code keyboardUp}, kept only with a terminal. */
    private void rememberHomePageKeyboard(int pageId, boolean keyboardUp) {
        PlaceLayoutStore store = placeLayoutStore();
        if (store == null || mInAppKeyboard == null || pageId < 0) return;
        if (store.isMinimal()) return;
        mHomeTerminalPageId = -1;
        boolean up = com.termux.app.place.PlaceKeyboard.keyboardToRemember(keyboardUp,
            mSheets.drawerRaisedKeyboard() && !mSheets.drawerRaisedKeyboardClaimed(),
            store.wasHomePageKeyboardOpen(pageId));
        store.setHomePageKeyboardOpen(pageId, com.termux.app.place.PlaceKeyboard
            .homePageKeyboardToRemember(up, homePageHoldsTerminal(pageId)));
    }

    /**
     * Home's pager came to rest on the page in front. Landed on another page, the page left
     * records its keyboard and the one in front takes its own: the stack draws it as the page has
     * it from this frame (StackRenderer#landHomePage), then it is shown or hidden.
     */
    private void onHomePageAtRest() {
        if (mControlBar != null) mControlBar.onFrontChanged();
        if (mTilingDesktop != null) mTilingDesktop.onHomePagesChanged();
        if (mLastWallPage != com.termux.app.page.PageKind.HOME) {
            mHomeKeyboardPageId = -1;
            return;
        }
        int front = mHomeSeam.pageInFront();
        if (front < 0 || front == mHomeKeyboardPageId) return;
        int left = mHomeKeyboardPageId;
        mHomeKeyboardPageId = front;
        if (left < 0) return;
        rememberHomePageKeyboard(left, committedKeyboardVisible());
        boolean wanted = restWantsKeyboard(com.termux.app.page.PageKind.HOME);
        mStackRenderer.landHomePage(com.termux.app.place.PlaceKeyboard.pageKeyboard(wanted));
        applyPlaceKeyboard(com.termux.app.page.PageKind.HOME);
    }

    /**
     * Whether the keyboard is up as the place on screen has it: a keyboard the wall's slide has
     * pre-rolled below the screen is the arriving place's, not this one's.
     */
    private boolean committedKeyboardVisible() {
        return mInAppKeyboard != null && mInAppKeyboard.isVisible() && !mCrossing.keyboardPreRolled();
    }

    /**
     * A float's chip sent the wall to Home to bring the float back focused, with the keyboard up
     * (showHomeFloat): Home wants its keyboard on this one landing. Cleared when the wall rests.
     */
    private boolean mKeyboardForRestoredFloat;

    /**
     * Whether Home keeps its keyboard up whatever a float does with it: always on, or a float
     * restored with its keyboard. Home's memory of a visit is not this: a float's keyboard still
     * goes with the float.
     */
    private boolean homeHoldsKeyboardUp() {
        if (mKeyboardForRestoredFloat) return true;
        PlaceLayoutStore store = placeLayoutStore();
        return store != null && store.isHomeKeyboardAlwaysOn();
    }

    /**
     * Tell the session client the terminal place can be seen again. While another place rests in
     * front of it the client stops repainting panes whose shells keep printing; this is the signal
     * that draws each of them once, and it is free when nothing was held back.
     */
    private void noteTerminalPlaceMayBeVisible() {
        if (mPaneController != null) mPaneController.onTerminalPlaceShown();
        if (mTermuxTerminalSessionActivityClient != null)
            mTermuxTerminalSessionActivityClient.onTerminalPlaceMayBeVisible();
    }

    /**
     * {@link #noteTerminalPlaceMayBeVisible} for one frame of a slide: the focused pane's request
     * is acknowledged as the full pass would (a pane that changes repaints its border through the
     * attention listener), without re-dressing every pane's border per frame.
     */
    private void noteTerminalPlaceMayBeVisibleWhileMoving() {
        if (mPaneController != null) mPaneController.acknowledgeActivePaneAttention();
        if (mTermuxTerminalSessionActivityClient != null)
            mTermuxTerminalSessionActivityClient.onTerminalPlaceMayBeVisible();
    }

    /**
     * The swipe off the pane's bottom border: the keyboard up ({@code open}) or down, on whichever
     * place is showing and in every mode. It is a person asking by hand, so it takes the path
     * {@code keyboard.show} and {@code keyboard.hide} take — the Display place's own routes (the
     * phone's keyboard, mouse mode's frame) included — and opening turns a keyboard that was
     * switched off back on, as the keyboard key does: this is the way back that is always there.
     * With Android's keyboard chosen in Settings it is the keyboard key's own toggle, pressed only
     * when that goes the way the swipe asked.
     */
    private void applyBorderKeyboardSwipe(boolean open) {
        applyBorderKeyboardSwipe(open, committedKeyboardVisible());
    }

    /** As above, told whether the keyboard was up as the swipe began. */
    private void applyBorderKeyboardSwipe(boolean open, boolean keyboardWasUp) {
        if (mPages.isCommitted(com.termux.app.page.PageKind.HOME) && applyHomeKeyboardSwipe(open, keyboardWasUp)) return;
        com.termux.app.terminal.TerminalHost host = terminalHost();
        if (open ? host.showInAppKeyboard(false) : host.hideInAppKeyboard(false)) return;
        TermuxTerminalViewClient client = mTermuxTerminalViewClient;
        if (client == null) return;
        boolean up = isImeVisible();
        if (open ? (client.isKeyboardTurnedOff() || !up) : up) client.onToggleSoftKeyboardRequest();
    }

    /**
     * The keyboard swipe on a Home page (spec §5.1). Up is the palette gesture: the Home palette
     * opens with the keyboard as one overlay, and the palette's close takes the keyboard it raised
     * down again ({@code TerminalCommandPaletteController.showHomeOverlay}). Down closes an open
     * palette, and with it its keyboard; always on keeps the keyboard up.
     *
     * @return whether the swipe was spent here; false leaves it to the plain keyboard swipe
     */
    private boolean applyHomeKeyboardSwipe(boolean open, boolean keyboardWasUp) {
        com.termux.app.terminal.TerminalCommandPaletteController palette =
            getCommandPaletteController();
        if (!open) {
            if (palette.isOpen()) {
                palette.collapse();
                return true;
            }
            return isHomeKeyboardAlwaysOn();
        }
        if (palette.isOpen() || !mSheets.isHomePaletteGestureEnabled()) return true;
        mSheets.openHomePalette(keyboardWasUp);
        return true;
    }

    /**
     * A vertical swipe on a Home page's free area, by Settings › Home › Gestures. Swipe up set to
     * the palette, or to nothing, and a swipe down that has a palette or a keyboard to put away,
     * take the keyboard swipe's path exactly as before; anything else runs its action.
     */
    private void runHomeSwipe(boolean up) {
        com.termux.app.launcher.home.HomeGestures.Gesture gesture = up
            ? com.termux.app.launcher.home.HomeGestures.Gesture.SWIPE_UP
            : com.termux.app.launcher.home.HomeGestures.Gesture.SWIPE_DOWN;
        com.termux.app.launcher.home.HomeGestures.Action action =
            com.termux.app.launcher.home.HomeSettings.gestureAction(this, gesture);
        if (isHomeKeyboardSwipe(up, action)) {
            applyBorderKeyboardSwipe(up);
            return;
        }
        runHomeGesture(gesture);
    }

    /** Whether a vertical Home swipe set to {@code action} takes the keyboard swipe's path. */
    private boolean isHomeKeyboardSwipe(boolean up,
            @NonNull com.termux.app.launcher.home.HomeGestures.Action action) {
        return up
            ? action == com.termux.app.launcher.home.HomeGestures.Action.PALETTE
                || action == com.termux.app.launcher.home.HomeGestures.Action.NONE
            : action == com.termux.app.launcher.home.HomeGestures.Action.NONE
                || mSheets.isCommandPaletteOpen()
                || (committedKeyboardVisible() && !isHomeKeyboardAlwaysOn());
    }

    /**
     * Swipe down on Home set to the notifications, claimed past the slop: the shade follows the
     * finger through the privileged lane when {@link
     * com.termux.app.launcher.home.ShadePullPolicy#pullsLive} allows; false leaves the swipe to
     * open the shade when let go.
     */
    private boolean beginHomeShadePull(float rawX, float rawY, long time) {
        if (!mPages.isCommitted(com.termux.app.page.PageKind.HOME)) return false;
        if (Build.VERSION.SDK_INT < com.termux.app.launcher.home.ShadePullPolicy.MIN_SDK) return false;
        com.termux.app.launcher.home.HomeGestures.Action action =
            com.termux.app.launcher.home.HomeSettings.gestureAction(this,
                com.termux.app.launcher.home.HomeGestures.Gesture.SWIPE_DOWN);
        com.termux.privileged.lane.IPrivilegedLane lane =
            com.termux.privileged.lane.PrivilegedLaneBinding.getInstance().boundLane();
        int statusBarPx = visibleStatusBarPx();
        if (!com.termux.app.launcher.home.ShadePullPolicy.pullsLive(Build.VERSION.SDK_INT, action,
                isHomeKeyboardSwipe(false, action), lane != null, statusBarPx)) {
            return false;
        }
        if (mShadePull == null) {
            mShadePull = new com.termux.app.launcher.home.ShadePullInjector(() -> {
                if (mPages.isCommitted(com.termux.app.page.PageKind.HOME)) {
                    runHomeGesture(com.termux.app.launcher.home.HomeGestures.Gesture.SWIPE_DOWN);
                }
            });
        }
        android.view.Display display = getDisplay();
        mShadePull.begin(lane, rawX, rawY, time,
            display == null ? android.view.Display.DEFAULT_DISPLAY : display.getDisplayId(),
            statusBarPx);
        return true;
    }

    /** The system status bar's height while it shows on this window; 0 while it is hidden. */
    @androidx.annotation.RequiresApi(api = Build.VERSION_CODES.R)
    private int visibleStatusBarPx() {
        android.view.WindowInsets insets = getWindow().getDecorView().getRootWindowInsets();
        if (insets == null || !insets.isVisible(android.view.WindowInsets.Type.statusBars())) return 0;
        return insets.getInsets(android.view.WindowInsets.Type.statusBars()).top;
    }

    /** Runs what {@code gesture} on a Home page is set to. */
    private void runHomeGesture(@NonNull com.termux.app.launcher.home.HomeGestures.Gesture gesture) {
        if (mTilingDesktop != null) {
            com.termux.app.launcher.home.HomeGestures.Action action =
                com.termux.app.launcher.home.HomeSettings.gestureAction(this, gesture);
            if (com.termux.app.tiling.TilingInput.homeGestureGoesDown(
                    gesture == com.termux.app.launcher.home.HomeGestures.Gesture.TWO_FINGER_UP,
                    action == com.termux.app.launcher.home.HomeGestures.Action.NONE,
                    action == com.termux.app.launcher.home.HomeGestures.Action.TERMINAL)) {
                mTilingDesktop.run(com.termux.app.tiling.TilingInput.Command.DOWN);
                return;
            }
        }
        com.termux.app.launcher.home.HomeGestureActions.run(this,
            com.termux.app.launcher.home.HomeSettings.gestureAction(this, gesture),
            com.termux.app.launcher.home.HomeSettings.gestureApp(this, gesture),
            new com.termux.app.launcher.home.HomeGestureActions.Host() {
                @Override public void openPalette() { mSheets.openHomePalette(committedKeyboardVisible()); }
                @Override public void openDrawer() { mSheets.openAppDrawerFromHome(); }
                @Override public void goToTerminal() {
                    if (mPaneWallController != null) mPaneWallController.returnToTerminal(true);
                }
                @Override public void lockScreen() { lockScreenFromHomeGesture(); }
                @Override public void explainHelperNeeded() {
                    AppNotice.show(TermuxActivity.this, R.string.home_gesture_needs_helper, false);
                }
                @Override public void explainNoApp() {
                    AppNotice.show(TermuxActivity.this, R.string.home_gesture_no_app, false);
                }
                @Override public void explainShadeFailed() {
                    AppNotice.show(TermuxActivity.this, R.string.home_gesture_shade_failed, false);
                }
            });
    }

    /**
     * A Home gesture's lock: the accessibility service when it is on, else Shizuku, else the
     * prompt that says how to turn the service on.
     */
    private void lockScreenFromHomeGesture() {
        if (LauncherLockAccessibilityAccess.isEnabled(this) && LockAccessibilityService.lockScreen()) {
            return;
        }
        if (PrivilegedBackendManager.getInstance().isPrivilegedAvailable()) {
            lockScreenWithShizuku();
            return;
        }
        showEnableAccessibilityLockDialog();
    }

    /** Whether the Home layout keeps the keyboard up on Home (always on). */
    private boolean isHomeKeyboardAlwaysOn() {
        PlaceLayoutStore store = placeLayoutStore();
        return store != null && store.isHomeKeyboardAlwaysOn();
    }

    // ---- The keyboard swipe under the finger (wall/KeyboardReveal) --------------------------
    // The same reveal the wall's slide draws the keyboard through between two places
    // (PlaceChromeTravel): the keyboard pre-rolled below the screen, the content held at its room,
    // the stack slid by the part not yet shown, the pane clipped where the chrome's live edge
    // stands and its rows drawn toward the size they will land at. Here one place's two keyboard
    // states are the two ends, and the finger, then its settle, says how far between them.

    /** A keyboard swipe owns the chrome's travel: from its claim until its settle lands. */
    private boolean mKeyboardSwipeTravel;
    /** Whether the keyboard was up when that swipe began. */
    private boolean mKeyboardSwipeFromOpen;
    /** How much more room the content has with the keyboard where the swipe is taking it. */
    private int mKeyboardSwipeRoomChangePx;
    /**
     * The dock padding a swipe closing the keyboard lands with ({@link
     * #keyboardDownFlushPaddingPx}): the settle's pass gives it to the dock and takes it from the
     * terminal, so the rows are drawn toward the height left after it. 0 for a swipe opening it.
     */
    private int mKeyboardSwipeLandingPaddingPx;

    /**
     * A keyboard swipe was claimed, going up ({@code opening}) or down: take the keyboard for the
     * finger, and answer the height it travels over. 0 leaves the swipe to its release
     * ({@link #applyBorderKeyboardSwipe}) wherever the keyboard is not one band of the stack that
     * can be slid: a floating keyboard, the phone's own keyboard, the Display place's own routes
     * (the phone's keyboard there, mouse mode's frame), a keyboard switched off (the release turns
     * it back on), one already where the swipe points, the editors and the drawer owning the
     * stack, and reduced motion.
     */
    private int beginKeyboardSwipeTravel(boolean opening) {
        if (mKeyboardSwipeTravel || mPaneWallController == null || mInAppKeyboard == null) return 0;
        com.termux.app.wall.PaneWallLayout wall = mPaneWallController.wall();
        if (wall.isMoving() || wall.offsetPx() != 0f || mCrossing.holdsContent()
            || mCrossing.keyboardPreRolled() || mChromeTravelMoved) return 0;
        if (isReducedMotionEnabled() || mSheets.isAppDrawerEngaged() || mSurfaceEditor.isActive()
            || appliedContentReservationPx() < 0) return 0;
        if (!canPreRollTravelKeyboard() || mInAppKeyboard.isTurnedOff()
            || mDisplayKeys.displayTakesSystemKeyboard() || mTouchpad.isDisplayTouchpadFrame()) return 0;
        boolean up = committedKeyboardVisible();
        if (opening == up) return 0;
        // On Home the finger raises the palette gesture's keyboard only; a down swipe that closes
        // the palette, or meets always on, is decided on release (applyHomeKeyboardSwipe).
        if (mPages.isCommitted(com.termux.app.page.PageKind.HOME) && (opening ? !mSheets.isHomePaletteGestureEnabled()
            : mSheets.isCommandPaletteOpen() || isHomeKeyboardAlwaysOn())) return 0;
        mKeyboardSwipeTravel = true;
        mKeyboardSwipeFromOpen = up;
        endHomePillFlight();
        // The room the content has now, read before anything moves; the other end is read once
        // the keyboard it depends on has been measured.
        int fromReservationPx = keyboardSwipeReservationPx(up);
        mKeyboardSwipeLandingPaddingPx = 0;
        if (opening) {
            preRollTravelKeyboard(mLastWallPage);
            mKeyboardSwipeRoomChangePx = fromReservationPx - keyboardSwipeReservationPx(true);
        } else {
            // Down: the content is given the room the keyboard gives back now, under a paused
            // grid, and the stack slides away from over it.
            mKeyboardSwipeRoomChangePx = fromReservationPx - keyboardSwipeReservationPx(false);
            mKeyboardSwipeLandingPaddingPx = keyboardDownFlushPaddingPx();
            beginTravelHold();
            if (mKeyboardSwipeRoomChangePx > 0) preRollTravelContent(mKeyboardSwipeRoomChangePx);
        }
        int travelPx = travelKeyboardLaidOutPx();
        if (travelPx <= 0 || !isInAppKeyboardShown()) {
            // Nothing laid out to slide: back as it was, and the release asks instead.
            finishKeyboardSwipeTravel(up);
            return 0;
        }
        setKeyboardSwipeTravel(up ? 1f : 0f);
        holdKeyboardSwipeFrostIfUnplaceable();
        return travelPx;
    }

    /**
     * A swipe over rows the travel cannot draw ahead — a full-screen program's, which it repaints
     * itself once the resize lands — is frosted from its claim until it lands or springs back,
     * instead of sliding a frame the program is about to replace. Rows the travel can place are
     * drawn sharp and keep only the settle's brief frost. Gated as that frost is.
     */
    private void holdKeyboardSwipeFrostIfUnplaceable() {
        if (!mCrossing.holdsContent() || mPaneController == null || !isTerminalTravelFrostAllowed())
            return;
        com.termux.view.TerminalView view = mPaneController.soleTiledPaneView();
        if (view != null && !view.canPlaceTravelRows()) view.holdTravelFrost();
    }

    /** The room a place's chrome leaves the content with the keyboard up or down, at rest. */
    private int keyboardSwipeReservationPx(boolean keyboardUp) {
        return mCrossingController.travelRestReservationPx(mLastWallPage, keyboardUp);
    }

    /**
     * The terminal's flush dock padding once the keyboard is down, worked out while it is still
     * up: the geometry pass stands the padding down while the keyboard shows, so the reservation
     * a closing swipe reads has none, yet the settle's pass lays it (up to a line) under the dock
     * and takes it from the terminal. The same conditions and arithmetic as that pass, for a
     * stack of the dock's rows alone; the window positions it measures do not move with the
     * keyboard.
     */
    private int keyboardDownFlushPaddingPx() {
        boolean toolbarShown = buildChromeSpec().toolbarShown;
        if (!toolbarShown || visiblePaneCount() > 1 || isImeVisible()
            || mLastWallPage != com.termux.app.page.PageKind.TERMINAL
            || (mPaneController != null && mPaneController.isActivePaneFloating()))
            return 0;
        return Math.max(0, resolveTerminalFlushDockPaddingPx(
            computeAccessoryStackHeight(
                mAppliedStack == null ? 0 : mAppliedStack.dockContentHeightPx, 0, 0),
            resolveAccessoryStackBottomMarginPx(toolbarShown, false)));
    }

    /**
     * One frame of the keyboard swipe: {@code reveal} of the keyboard shows, 0 to 1. Transforms
     * only, as for the wall's travel: the stack's translation, the pane's clip under it and the
     * rows' displacement.
     */
    private void setKeyboardSwipeTravel(float reveal) {
        if (!mKeyboardSwipeTravel) return;
        float shown = Math.max(0f, Math.min(1f, reveal));
        float translation = keyboardTravelTranslationPx(shown);
        mChromeTravelMoved = true;
        if (mCrossing.holdsContent()) {
            com.termux.view.TerminalView view = mPaneController == null ? null
                : mPaneController.soleTiledPaneView();
            if (view != null) {
                // Toward the height the terminal settles at: the room given back less the dock
                // padding the settle lays, so the rows land where the resize puts them.
                view.setTravelDisplacement(
                    mKeyboardSwipeRoomChangePx - mKeyboardSwipeLandingPaddingPx,
                    mKeyboardSwipeFromOpen ? 1f - shown : shown);
            }
        }
        // The stack's translation, all of it the keyboard's, and the cover under the hold, through
        // the crossing's adapter (Crossing#keyboardSwipe).
        mCrossing.keyboardSwipe(translation);
    }

    /**
     * The keyboard swipe's settle landed, up ({@code open}) or down. The travel's transforms come
     * off, as the wall's settle takes them off; a swipe that went through is then the person's own
     * show or hide — the keyboard key's path, heard by everything that listens for one — and one
     * that came back undoes its pre-roll quietly. One geometry pass gives the content the room it
     * landed on.
     */
    private void finishKeyboardSwipeTravel(boolean open) {
        if (!mKeyboardSwipeTravel) return;
        mKeyboardSwipeTravel = false;
        mKeyboardSwipeLandingPaddingPx = 0;
        mChromeTravelMoved = false;
        // The hold lets go in one step (Crossing#releaseHold): the content's room, the pre-rolls,
        // the stack's translation and the cover on the window in front.
        com.termux.app.place.Crossing.Landing released = mCrossing.releaseHold();
        boolean keyboardPreRolled = released.keyboardPreRolled();
        boolean contentPreRolled = released.contentPreRolled();
        boolean held = released.held();
        GeometryScheduler.Transition gridHold = released.gridHold();
        // The keyboard's own show or hide and the content's room are one pass, at the batch's end.
        mGeometry.beginBatch();
        try {
            if (open != mKeyboardSwipeFromOpen) {
                // The pre-rolled keyboard, up already, becomes the one the person asked for; the
                // display's policy hears it here, since the keyboard itself saw no change to
                // report.
                applyBorderKeyboardSwipe(open, mKeyboardSwipeFromOpen);
                if (open && mDisplayServer.controller() != null && !mTouchpad.isRaisingDisplayFrameKeyboard())
                    mDisplayServer.controller().onUserKeyboardIntent(true);
            } else if (keyboardPreRolled && mInAppKeyboard != null && mInAppKeyboard.isVisible()) {
                mQuietKeyboardChange = true;
                try {
                    mInAppKeyboard.hide(com.termux.app.terminal.inappkeyboard.TermuxInAppKeyboard
                        .HideReason.WALL_PAGE);
                } finally {
                    mQuietKeyboardChange = false;
                }
            }
            if (held) mGeometry.requestNow(GeometryScheduler.Reason.PLACE_SETTLE,
                GeometryScheduler.ResizePolicy.NOW);
        } finally {
            mGeometry.endBatch();
        }
        if (contentPreRolled) finishTravelContentResizeAfterLayout(gridHold);
        if (held) settleTerminalTravelDisplacement();
        mChrome.requestSync(ChromeRenderer.SCOPE_ACCESSORY_RENDER);
        // The Home pill takes the pose of the keyboard's end, whatever progress last reached it.
        com.termux.app.terminal.extrakeys.HomePillLayer pillLayer = mHomePillLayer;
        if (pillLayer != null) pillLayer.keyboardDock().onKeyboardSettled();
    }

    /** Lands a keyboard swipe still under way, before something else moves the chrome. */
    private void settleKeyboardSwipeTravelNow() {
        if (!mKeyboardSwipeTravel) return;
        if (mPaneWallController != null) mPaneWallController.wall().settleKeyboardRevealNow();
        // The wall hands the keyboard back through onKeyboardRevealEnd; if it had nothing
        // engaged, the travel goes back to where it began.
        finishKeyboardSwipeTravel(mKeyboardSwipeFromOpen);
    }

    /** The wall moved ({@link com.termux.app.wall.WallPose#OFFSET}): the chrome travels with it. */
    private void onWallOffsetChanged(float offsetPx) {
        // The wall moving again reads the settled state: a landing still waiting
        // for its post lands first. The offset coming back to rest on the frame the
        // wall settled is not that: its landed frame draws the chrome at the end of
        // its travel (progress 1, written by the travel below), and the landing
        // follows its post (LandedFrameSettle), outside this layout pass.
        // Called while the wall controller is still being built: null until then.
        com.termux.app.wall.PaneWallLayout movingWall =
            mPaneWallController != null ? mPaneWallController.wall() : null;
        if (offsetPx != 0f || (movingWall != null && movingWall.isMoving())) {
            flushLandedFrameSettle();
        }
        Trace.beginSection("Wall.offsetChanged");
        try {
            onWallOffsetChangedTraced(offsetPx);
        } finally {
            Trace.endSection();
        }
    }

    private void onWallOffsetChangedTraced(float offsetPx) {
        // A perfetto counter beside the stack's (applyAccessoryStackTranslation), so
        // a trace shows whether the chrome lands with the wall or after it.
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q)
            Trace.setCounter("Wall.offsetPx", Math.round(offsetPx));
        Trace.beginSection("Wall.barOffset");
        syncPlaceBarOffset(offsetPx);
        syncGroundStrip(offsetPx);
        Trace.endSection();
        // Off its rest on the Terminal, the canvas reaches up under the bar so Home's
        // page stands at its own top from this frame on (PageTopInsets).
        syncCanvasTopReach();
        // The terminal's own frame line stays put while its page leaves: it fades.
        syncTerminalFrameLineTravel();
        // The dock, the keyboard and the status bar's content travel with the wall
        // between the two places' states, as transforms only.
        mCrossingController.syncChromeTravel(offsetPx);
        // The wallpaper pans with the wall, and every glass surface follows it. The
        // slabs, on the terminal's page or any other, re-aim in the frame the wall
        // moved in whether or not the wallpaper panned: the glass service asks each
        // of them at the commit (SlabAim), so nothing is pushed to them here.
        Trace.beginSection("Wall.parallax");
        syncWallpaperParallax(true);
        Trace.endSection();
        // The wall moved at all, so the terminal may be sliding back into the frame:
        // any pane whose screen changed while it was away is drawn now, before the
        // first frame of the slide, rather than one stale frame later. The panes'
        // borders are re-dressed when the page comes on screen
        // (onTerminalOffScreenChanged), not per frame; per frame only the
        // acknowledgement is taken, which repaints them itself when it lands.
        Trace.beginSection("Wall.terminalVisible");
        noteTerminalPlaceMayBeVisibleWhileMoving();
        Trace.endSection();
    }

    /** The Terminal page sank or rose under a held border ({@link com.termux.app.wall.WallPose#SINK}). */
    private void onTerminalSinkChanged(float scale) {
        // The terminal's frame line is laid over the wall, not carried by the page
        // (syncTerminalFrameLineTravel): it sinks with the page by hand. Its margins
        // are the pane host's less the stroke's air on every side, so the two share
        // a centre and one scale about it keeps the line where it frames the page.
        // The slabs' wallpaper stays on the screen while their page sinks under it:
        // the glass service re-aims them in the frame the sink draws in.
        View borderView = hotView(R.id.terminal_border_overlay);
        if (borderView == null) return;
        borderView.setPivotX(borderView.getWidth() / 2f);
        borderView.setPivotY(borderView.getHeight() / 2f);
        borderView.setScaleX(scale);
        borderView.setScaleY(scale);
    }

    /**
     * Wire the pane wall around the terminal's pane host. The terminal is its middle page and is
     * handed over untouched; the other places register themselves as the install gains them.
     */
    private void createPaneWallController(@Nullable View paneHost) {
        View wall = findViewById(R.id.terminal_pane_wall);
        if (!(wall instanceof com.termux.app.wall.PaneWallLayout) || paneHost == null) return;
        // The display frame's still may be drawing a picture the wall lets go: it forgets it first.
        ((com.termux.app.wall.PaneWallLayout) wall).setOnPictureDropped(picture -> {
            com.termux.app.x11.X11PaneFrame frame = mPaneWallController == null
                ? null : mPaneWallController.displayWindow();
            if (frame != null) frame.forgetPagePicture(picture);
        });
        com.termux.app.wall.WallFacts wallFacts = new com.termux.app.wall.WallFacts() {
            @Override public boolean reducedMotion() { return isReducedMotionEnabled(); }
            // Home is always on the row; the Terminal while there is a window to show.
            @Override public boolean hasWindow() { return isTerminalOnRow(); }
            @Override public boolean terminalWindowOpen() {
                return mTermuxService != null && terminalWindowTotal() > 0;
            }
            @NonNull @Override public com.termux.app.wall.UseAs useAs() {
                return TermuxActivity.this.useAs();
            }
            // Under Terl the wall is Home's pages alone; the rest are windows of the stack.
            @Override public boolean homePagesOnly() { return mTilingDesktop != null; }
            // The wall lays out in the pages' order (ADR 0015, A2a).
            @Override public com.termux.app.wall.WallPages wallPages() {
                return TermuxActivity.this.wallPages();
            }
            // The plank (PlankTilt) is a Fancier Glass motion: the look as the last apply
            // resolved it, with nothing telling the phone to hold still.
            @Override public boolean isPlankTiltEnabled() {
                return mFancierGlassLook != null
                    && !isReducedMotionEnabled() && !isLazyModeEnabled();
            }
            // Settings › Terminal › Windows & panes, then the pane under the finger.
            @Override public boolean bodySwipePagesWall(float rawX, float rawY) {
                return mPreferences != null && mPreferences.isTerminalBodySwipeEnabled()
                    && mPaneController != null
                    && mPaneController.bodySwipePagesWall(rawX, rawY);
            }
            // The seam band's last row is the bottom border's, so only the pane is asked.
            @Override public boolean seamSwipePagesWall(float rawX, float rawY) {
                return mPaneController != null
                    && mPaneController.bodySwipePagesWall(rawX, rawY);
            }
        };
        mPaneWallController = new com.termux.app.wall.PaneWallController(
            (com.termux.app.wall.PaneWallLayout) wall, wallFacts);
        mPaneWallController.setStatusRowPx(mStatusRowRoomPx);
        mPaneWallController.setTerminal(new com.termux.app.wall.WallTerminal() {
            @Override public boolean restore() {
                com.termux.app.wall.WallPages.Result back = wallPagesStore().edit(
                    com.termux.app.wall.TerminalPageReturn::restore);
                if (!back.ok() || back.page == null) return false;
                noteTerminalPageId(back.page.id);
                return true;
            }
            // Home's swipe past its last page into an empty Terminal (ADR 0008): the same fresh shell the Terminal entry starts there.
            @Override public boolean canStartShell() {
                return isSplitPanesEnabled() && mPaneController != null
                    && getTermuxTerminalSessionClient() != null;
            }
            @Override public boolean startShell() {
                if (!canStartShell()) return false;
                getTermuxTerminalSessionClient().addNewSession(false, null);
                return true;
            }
            @Override public int count() {
                return wallInnerCount(com.termux.app.page.PageKind.TERMINAL);
            }
            @Override public int index() {
                return wallInnerIndex(com.termux.app.page.PageKind.TERMINAL);
            }
            @Override public void show(int index) {
                showWallInnerPage(com.termux.app.page.PageKind.TERMINAL, index);
            }
            @Override public void stepBegin(int steps) {
                if (MotionLog.enabled) MotionLog.log("inner-step-begin", "page=TERMINAL steps=" + steps);
                mStatusCardHost.dismiss();
                // A terminal window leaving for another is pictured, unless the one arriving
                // stands live beside it: then the leaving one stays live too and carries on.
                if (isLiveWindowStep(steps)) dropTerminalDepartureSnapshot();
                else captureTerminalDeparture();
            }
            @Override public void step(int steps, float fromPx) {
                if (MotionLog.enabled) {
                    MotionLog.log("inner-step", "page=TERMINAL steps=" + steps + " fromPx=" + fromPx);
                }
                Trace.beginSection("Term.stepWindow");
                try {
                    stepWindowFromWall(steps, fromPx);
                } finally {
                    Trace.endSection();
                }
            }
            @Override public void dropDeparture() {
                dropTerminalDepartureSnapshot();
            }
        });
        // The constructor's own pass ran before the Terminal seam was there: its restore is asked now.
        mPaneWallController.refreshPages();
        attachLinuxWindows();
        mPaneWallController.setLanding(new com.termux.app.wall.WallLanding() {
            @Override public void landed(
                    @NonNull com.termux.app.page.PageKind page) {
                if (MotionLog.enabled) {
                    MotionLog.log("wall-page-settled", "page=" + page);
                    mMotionInvariantHandler.removeCallbacks(mMotionInvariantTick);
                    mMotionInvariantHandler.postDelayed(mMotionInvariantTick,
                        com.termux.app.chrome.MotionInvariants.WINDOW_MS + 50);
                }
                // The landed frame draws the page at rest with the chrome at the end of its
                // travel; making that the layout waits for just after it (LandedFrameSettle).
                com.termux.app.wall.PaneWallLayout wall = mPaneWallController.wall();
                View decor = getWindow() != null ? getWindow().getDecorView() : null;
                boolean windowDraws = !isDestroyed() && decor != null
                    && decor.isAttachedToWindow();
                if (com.termux.app.wall.LandedFrameSettle.defers(
                        wall != null && wall.settleEndsSlide(), windowDraws, page)) {
                    Trace.beginSection("Wall.landed");
                    Trace.endSection();
                    // The wall already answers the arriving page as current: the glyphs
                    // change in the frame the motion lands, not in the settle after it.
                    refreshPageGlyphs();
                    com.termux.app.page.PageKind earlier = mLandedFrameSettle.hold(page);
                    if (earlier != null) runWallPageSettle(earlier);
                    mFrames.requestNextFrame(com.termux.app.window.FrameStep.PAGE_SETTLE);
                    return;
                }
                flushLandedFrameSettle();
                runWallPageSettle(page);
            }
            @Override public void committed(
                    @NonNull com.termux.app.page.PageKind page) {
                // A page change by any other means puts the key's page bar away.
                if (mPageBar != null) mPageBar.close();
                // A landing still waiting for its post lands before the page changes again.
                flushLandedFrameSettle();
                // One window-bar refresh for the whole change, however many syncs ask.
                batchWindowBarRefresh(() -> {
                    noteTerminalPlaceMayBeVisible();
                    if (mPaneWallController.displayWindow() != null) {
                        mPaneWallController.displayWindow().dismissControls();
                    }
                    // Only the bar is re-dressed at release, beside the cheap put-aways above:
                    // it is the pager, and it names the place the wall has committed to. The
                    // rest waits for the settle (syncPlaceState).
                    syncPlaceBar();
                    // The window chips belong to the Terminal: its row's windows, the
                    // display window's among them, and none on Home.
                    com.termux.app.terminal.TerminalWindowBar chips =
                        findViewById(R.id.terminal_window_bar);
                    if (chips != null && isSplitPanesEnabled()) syncWindowBarItems(chips);
                    // A change the wall makes at rest — a page taken away while it was
                    // showing hands the wall to Home without a slide — is followed by no
                    // settle, so the place's state is applied here instead.
                    com.termux.app.wall.PaneWallLayout wall = mPaneWallController.wall();
                    if (wall != null && !wall.isMoving() && wall.offsetPx() == 0f)
                        settlePlaceChrome(page);
                    // At rest with no settle to follow: clipboard reads waiting for the
                    // terminal may be due.
                    if (wall != null && !wall.isMoving()
                        && mTermuxTerminalSessionActivityClient != null)
                        mTermuxTerminalSessionActivityClient.onFrontPaneMaybeChanged();
                });
            }
        });
        mPaneWallController.setKeyboardSwipe(new com.termux.app.wall.WallKeyboardSwipe() {
            @Override public void onSwipe(boolean open) {
                applyBorderKeyboardSwipe(open);
            }
            // On Home the swipe is the palette gesture: off in Settings, it is armed only
            // to put away a keyboard that is up.
            @Override public boolean isEnabled() {
                return !mPages.isCommitted(com.termux.app.page.PageKind.HOME) || mSheets.isHomePaletteGestureEnabled()
                    || committedKeyboardVisible();
            }
            // The keyboard swipe tied to the finger: the reveal the wall's slide already
            // draws the keyboard through, driven by the finger instead of the wall.
            @Override public int onRevealBegin(boolean opening) {
                return beginKeyboardSwipeTravel(opening);
            }
            @Override public void onRevealProgress(float reveal) {
                setKeyboardSwipeTravel(reveal);
                // The Home pill rides the same reveal (draw-only, allocation-free).
                com.termux.app.terminal.extrakeys.HomePillLayer pillLayer = mHomePillLayer;
                if (pillLayer != null && mKeyboardSwipeTravel) {
                    pillLayer.keyboardDock().onProgress(reveal);
                }
            }
            @Override public void onRevealEnd(boolean open) {
                finishKeyboardSwipeTravel(open);
            }
        });
        mPaneWallController.setStatusFold(mStatusBar.wallStatusFold());
        // The wall's pose: the travel reads the offset and the sink, the terminal's panes the
        // rims and whether their page is off screen.
        mPaneWallController.addPoseReader((pose, changed) -> {
            if ((changed & com.termux.app.wall.WallPose.OFFSET) != 0) {
                onWallOffsetChanged(pose.offsetPx());
            }
            if ((changed & com.termux.app.wall.WallPose.SINK) != 0) {
                onTerminalSinkChanged(pose.terminalSinkScale());
            }
            if ((changed & (com.termux.app.wall.WallPose.RIMS
                | com.termux.app.wall.WallPose.OFF_SCREEN)) != 0 && mPaneController != null) {
                mPaneController.onWallPose(pose, changed);
                // Back on screen the panes take focus again: a window whose step panned it in
                // gets the keys its front could not hand it while it was off screen.
                if ((changed & com.termux.app.wall.WallPose.OFF_SCREEN) != 0
                    && !pose.terminalOffScreen()) mTerminalPages.onPanesBackOnScreen();
            }
        });
        // The chips rest a wall's width off on Home: a wall laid out at another width stands the
        // top stack's rest again (an offset change alone is not told of it).
        mPaneWallController.wall().addOnLayoutChangeListener((v, l, t, r, b, ol, ot, or, ob) -> {
            if (r - l != or - ol) restTopStack(mLastWallPage);
        });
        // Before anything lands the wall: Home's pages, run and press page come from the seam.
        mPaneWallController.setHome(mHomeSeam);
        // Overview stands before the first page: the swipe past it brings Overview in (#356).
        mPaneWallController.wall().setOverviewEdge(overview().wallEdge());
        // The display view stands on one Display page at a time (ADR 0015, A3b).
        mDisplayPageBinding.setLanding(mDisplayLanding::landedAt);
        mPaneWallController.setDisplay(mDisplayPageBinding);
        mPaneWallController.attachTerminalPage(paneHost, (x, out) ->
            mPaneController != null && mPaneController.bottomPaneEdgeAt(x, out));
        // The Widgets page is built before the widget controller looks its grid up, so the
        // controller finds it already on the wall.
        if (isWidgetsPageWanted()) {
            attachWidgetsPage();
        }
        // The display window opens on demand (ADR 0008); a display already up — announced to the
        // activity this one replaces — is taken at once.
        if (com.termux.app.x11.X11DisplayReceiver.hasKeptAnnouncement()) buildDisplayWindow();
        installLinuxAppRunner();
        installLauncherEntryRunner();
        mAppliedPaneStyleKey = null;
        mPaneWallController.applyStyle(paneSurfaceStyle());
        // Where the wall starts is decided in landWall(), once the widget grid can be turned.
        // Minimal mode is remembered across launches. The arrangement reads it on its own
        // (arrangementOf); the bar is told once here, and every change after this
        // goes through syncChromeArrangement.
        boolean home = mLastWallPage == com.termux.app.page.PageKind.HOME;
        if (chromeVariant() != mAppliedChromeVariant
            || !Boolean.valueOf(home).equals(mAppliedChromeHome)) {
            mAppliedChromeVariant = chromeVariant();
            mAppliedChromeHome = home;
            mStatusBar.applyMinimalStatusChrome();
        }
    }

    /** The place settle a slide's landed frame left for just after it (LandedFrameSettle). */
    private final com.termux.app.wall.LandedFrameSettle mLandedFrameSettle =
        new com.termux.app.wall.LandedFrameSettle();

    /**
     * Runs the settle a landed frame left waiting, now; nothing when none waits. The next frame's step runs it
     * just after that frame, and anything that reads the settled state first runs it here.
     */
    private void flushLandedFrameSettle() {
        com.termux.app.page.PageKind page = mLandedFrameSettle.take();
        if (page == null) return;
        if (isDestroyed() || mPaneWallController == null) return;
        runWallPageSettle(page);
    }

    /** What a wall at rest on {@code page} makes the layout, traced as the page's settle. */
    private void runWallPageSettle(@NonNull com.termux.app.page.PageKind page) {
        Trace.beginSection("Wall.pageSettled");
        try {
            doRunWallPageSettle(page);
        } finally {
            Trace.endSection();
            // The landing's settle has run, or a crossing came back: the crossing window shuts.
            com.termux.app.window.CrossingWindow.shared().close();
        }
        // The wall is at rest here: clipboard reads that waited for the terminal may be due.
        if (mTermuxTerminalSessionActivityClient != null)
            mTermuxTerminalSessionActivityClient.onFrontPaneMaybeChanged();
    }

    private void doRunWallPageSettle(
            @NonNull com.termux.app.page.PageKind wallPage) {
        refreshPageGlyphs();
        // The place the Terminal's page shows: the display's while the display
        // window is in front of it.
        com.termux.app.page.PageKind page = wallPage;
        refreshGroundStrip();
        // Everything a place change moves apart from the bar runs here, once the wall
        // has stopped: the layout and the look are every place's, so the slide never
        // has anything to re-lay, and what is left — the keyboard, the touchpad, who
        // owns the phone's keyboard, which keys can act — lands in one pass at rest
        // rather than in the release frame (ADR 0003). The dock and the keyboard have
        // already travelled there with the slide; this is where what they showed
        // becomes the layout.
        // The Home pill's flight, read before the settle re-dresses the chrome: where the docked
        // bar stands now, and whether the pill is on screen to fly. A flight still running lands
        // first.
        com.termux.app.page.PageKind placeBefore = settledWallPage();
        com.termux.app.terminal.extrakeys.HomePillLayer pillLayer = homePillLayer();
        com.termux.app.terminal.extrakeys.HomePillFlightPlayer flights =
            pillLayer == null ? null : pillLayer.flights();
        boolean pillFree = false;
        boolean barBefore = false;
        if (flights != null) {
            flights.finish();
            pillFree = mHomePill.isShown() && !pillLayer.ownsPose();
            barBefore = flights.captureDockedBar(getTerminalToolbarViewPager());
        }
        mSettledWallPage = page;
        settlePlaceChrome(page);
        restoreInAppKeyboardTypingClaim();
        com.termux.app.terminal.extrakeys.HomePillFlightPlan.Flight flight = flights == null
            ? com.termux.app.terminal.extrakeys.HomePillFlightPlan.Flight.NONE
            : com.termux.app.terminal.extrakeys.HomePillFlightPlan.decide(placeBefore, page,
                pillFree, barBefore, buildChromeSpec().extraKeysRowEnabled,
                mHomePillHost.switchOn(), !isReducedMotionEnabled(),
                mExtraKeySetController.targetNow());
        if (flight == com.termux.app.terminal.extrakeys.HomePillFlightPlan.Flight.TO_DOCK) {
            // The pill stays on screen for the flight, with Home's keys.
            mHomePill.holdForFlight(true);
        } else if (flight == com.termux.app.terminal.extrakeys.HomePillFlightPlan.Flight.TO_PILL) {
            flights.armToPill();
        }
        // The flight is the motion of a page change that starts or ends on Home with the bar on,
        // so the key set swaps under it instead of morphing.
        refreshExtraKeySet(flight == com.termux.app.terminal.extrakeys.HomePillFlightPlan.Flight.NONE);
        if (flight == com.termux.app.terminal.extrakeys.HomePillFlightPlan.Flight.TO_DOCK) {
            flights.flyToDock(getTerminalToolbarViewPager());
        }
        noteTerminalPlaceMayBeVisible();
        Trace.beginSection("Wall.displayAttachment");
        try {
            syncDisplayAttachment(page);
        } finally {
            Trace.endSection();
        }
        // A display window left before its display came up goes, once the wall has
        // finished settling rather than inside it.
        if (page != com.termux.app.page.PageKind.DISPLAY) {
            dropUnstartedDisplayWhenSettled(0L);
        }
        dismissHelpOverlay();
        // The "Go to …" read-out lands with the page (showTerminalActionHint).
        if (mWallReadoutShowing) {
            mWallReadoutShowing = false;
            com.termux.app.notice.AppNotice.clearReadout(TermuxActivity.this);
        }
    }

    /** The share of the terminal's frame line last drawn; 1 at rest on the terminal. */
    private float mTerminalFrameLineAlpha = 1f;
    /** Whether the frame line was last drawn where the fading page is posed. */
    private boolean mTerminalFrameLineRides;

    /**
     * The terminal's own frame line ({@code terminal_border_overlay}, the plain border around a
     * lone pane, or the glass edge) is chrome laid over the wall rather than a rim the page
     * carries. While the page only moves, the line stays put and fades as the page leaves its
     * rest, over the same stretch the pages' rims fade, and stays away while another place rests
     * in the frame — the Widgets and display windows wear a line of their own
     * ({@code PaneWallPolicy.pageOutlineAlpha}). While the page transition fades the page instead
     * (Stack, Depth, Fade), the line is drawn where the page is posed — its translation and its
     * scale, about the centre the two share (onPageSinkChanged) — at the page's own alpha, so the
     * glass edge and the text it frames come and go together
     * ({@code PaneWallPolicy.terminalFrameLineAlpha}). Per frame of a slide, so nothing here but
     * comparisons and view properties.
     */
    private void syncTerminalFrameLineTravel() {
        if (mPaneWallController == null) return;
        View borderView = hotView(R.id.terminal_border_overlay);
        View paneHost = hotView(R.id.terminal_pane_host);
        if (borderView == null || paneHost == null) return;
        com.termux.app.wall.PaneWallLayout wall = mPaneWallController.wall();
        float pageAlpha = paneHost.getAlpha();
        boolean rides = com.termux.app.wall.PaneWallPolicy.fadesWithPage(pageAlpha);
        // A page parked at 0 shows nothing to follow; one fading on screen is followed, and the
        // line is put back on the frame the ride ends.
        if ((rides && pageAlpha > 0f) || (!rides && mTerminalFrameLineRides)) {
            float x = rides ? paneHost.getTranslationX() : 0f;
            if (borderView.getTranslationX() != x) borderView.setTranslationX(x);
            float scale = paneHost.getScaleX();
            if (borderView.getScaleX() != scale || borderView.getScaleY() != scale) {
                borderView.setPivotX(borderView.getWidth() / 2f);
                borderView.setPivotY(borderView.getHeight() / 2f);
                borderView.setScaleX(scale);
                borderView.setScaleY(scale);
            }
        }
        mTerminalFrameLineRides = rides;
        // Where the page's slide puts it: an effect may pose it elsewhere, but a line that does
        // not ride fades on the page's way out, as the rims do.
        float alpha = com.termux.app.wall.PaneWallPolicy.terminalFrameLineAlpha(
            com.termux.app.wall.PaneWallPolicy.pageOutlineAlpha(wall.slidePx(paneHost),
                wall.getWidth()), pageAlpha);
        if (alpha == mTerminalFrameLineAlpha) return;
        mTerminalFrameLineAlpha = alpha;
        borderView.setAlpha(alpha);
    }

    /**
     * The bar is the pager. Its place content — the badge and chips of the status row, the summary
     * beside the clock, the glyphs in the lens edges and the tint of the glass — belongs to the
     * place on screen and follows the wall. This re-reads which places the wall has and dresses
     * the bar for the one showing; {@link #syncPlaceBarOffset} moves it with the finger.
     */
    private void refreshPlaceBar() {
        View slotView = findViewById(R.id.terminal_top_widget_area);
        if (mPaneWallController != null) {
            // A preference sync can have taken a place away or given one back.
            mPaneWallController.refreshPages();
        }
        if (slotView instanceof com.termux.app.statusbar.TopPaneWidgetSlot) {
            ((com.termux.app.statusbar.TopPaneWidgetSlot) slotView).setClockAlignment(
                mPreferences == null ? null : mPreferences.getTopPaneClockAlignment());
        }
        syncPlaceBar();
    }

    /** The place on screen, as {@link #currentWallPlace} answers it. */
    @NonNull
    private com.termux.app.page.PageKind currentWallPage() {
        return currentWallPlace();
    }

    /** Where the wall stands relative to its rest, as its last offset callback said. */
    private float mWallOffsetPx;

    /** Dress the bar for the place on screen: row content, accents, summary, icons and tint. */
    private void syncPlaceBar() {
        // One bar across the wall (#90): the same badge and chips on Home as on every window, in
        // the Terminal's accent, so nothing in the row changes colour on the swipe.
        int accent = com.termux.app.statusbar.StatusBarLensView.accentFor(this,
            com.termux.app.page.PageKind.TERMINAL);
        Integer placeAccent = accent;
        // The row's badge is the Terminal session's and the chips are its windows, the display
        // window's and the Home floats' with them, on both halves alike.
        boolean terminal = true;
        com.termux.app.statusbar.SessionsIndicatorView sessions =
            findViewById(R.id.terminal_sessions_indicator);
        if (sessions != null) {
            sessions.setAccent(placeAccent);
            sessions.setVisibility(mStatusRow.sessionsIndicatorVisibility(terminal,
                mMarksLine.marksLookShown()));
        }
        boolean windowsShown = terminal
            && com.termux.app.wall.PaneWallPolicy.showsWindowChips(currentWallPage());
        com.termux.app.terminal.TerminalWindowBar bar = findViewById(R.id.terminal_window_bar);
        if (bar != null) {
            // The chips are drawn on glass, so they ask the chrome what they are standing on
            // rather than trusting a role colour authored against an opaque card.
            bar.setChromeInk(mChrome.ink());
            bar.setPlaceAccent(placeAccent);
            bar.setVisibility(windowsShown && !mStatusRow.chipsKeptAway(mMarksLine.marksLookShown())
                && !mStatusBar.isStatusBarVertical()
                ? View.VISIBLE : View.GONE);
            // The font toggle's pill follows the page the bar is dressed for.
            syncFontToggle();
            // The plus opens a terminal window right after the window in front, whichever it is;
            // without split panes there are no windows to open, on either half.
            bar.setCreateButtonShown(terminal && isSplitPanesEnabled());
            // Seen from Home the selected chip is a window to go to, not one to close.
            bar.setSelectedChipOffersClose(
                com.termux.app.terminal.TerminalWindowBar.selectedChipOnScreen(currentWallPage()));
        }
        com.termux.app.statusbar.StatusBarWindowColumn windowColumn =
            findViewById(R.id.terminal_status_window_column);
        if (windowColumn != null) {
            windowColumn.setChromeInk(mChrome.ink());
            windowColumn.setPlaceAccent(placeAccent);
            windowColumn.setVisibility(windowsShown && !mMarksLine.marksLookShown()
                && mStatusBar.isStatusBarVertical() ? View.VISIBLE : View.GONE);
        }
        // Under the Marks look the line stands where the chips were, so the chips are put away.
        mMarksLine.syncMarksLine();
        // Home's float chips, in Home's accent: they are Home's content, not the Terminal's.
        homeFloatChipBar().dress(mChrome.ink(), com.termux.app.statusbar.StatusBarLensView
            .accentFor(this, com.termux.app.page.PageKind.HOME), mStatusBar.isStatusBarVertical());
        bindPlaceBadge(sessions);
        com.termux.app.statusbar.StatusBarLensView lens = findViewById(R.id.terminal_status_lens);
        if (lens != null) {
            // The row may have said what colour each place is before this view existed.
            lens.setPlaceAccents(mPlaceAccents);
            // The icons are chips of the same kit as the badge beside them: same corner.
            lens.setChipRadiusPx(mStatusBar.resolveStatusIndicatorCornerRadiusPx(Math.round(dpToPx(20)),
                isRoundedStyle(com.termux.app.place.SeamDress.Surface.STATUS)));
            // Nothing to keep clear of: a column stands in the canvas band, which already starts
            // below the system status bar and ends above the navigation bar.
            lens.setAlongInsets(0, 0);
            if (!mStatusBar.isStatusBarFoldInteractive()) {
                lens.setExpansion(mStatusBar.isStatusBarCompact()
                    ? 0f : 1f);
            }
        }
        applyPlaceStripInset(mStatusBar.isStatusBarCompact()
            ? 0f : 1f);
        syncPlaceBarOffset(mWallOffsetPx);
        // A column's weather is the bare number; it reads the bar's form, so it follows it.
        if (mWeatherController != null && mWeatherController.cache().valid) {
            onWeatherUpdated(mWeatherController.cache());
        }
    }

    /**
     * The row's place content starts after the lens, in both forms: the place icons live behind
     * the content and past the edges, and take no room from the row.
     */
    private void applyPlaceStripInset(float expansion) {
        applyPlaceStripInset(findViewById(R.id.terminal_status_place_content));
        applyPlaceStripInset(findViewById(R.id.terminal_status_home_chips));
    }

    /** {@link #applyPlaceStripInset(float)} for one side's strip. */
    private void applyPlaceStripInset(@Nullable View strip) {
        if (strip == null) return;
        int lens = Math.round(dpToPx(com.termux.app.statusbar.PlaceContentStrip.LENS_WIDTH_DP));
        // The lens runs along the bar, so what it keeps clear is the bar's leading end: the row's
        // start on a row, the column's top on a column.
        // Each is put back to nothing on the other axis: a column's top padding carried over into
        // a row once, and pushed the row's chips down out of their 24dp.
        boolean vertical = mStatusBar.isStatusBarVertical();
        // A column keeps a foot under its chips. A row keeps nothing at its end: the window bar
        // owns the gap before the readings there (StatusRowLayout), and a strip padding on top of
        // it was dead space between the chips and the CPU figure. Neither is carried across: a
        // trailing padding left standing across a column is width the chips do not have — a 26dp
        // chip in a 34dp column — so they slide off the bar's centre line and the curve clips them.
        int start = vertical ? 0 : lens;
        int top = vertical ? lens : 0;
        int end = 0;
        int bottom = vertical
            ? Math.round(dpToPx(com.termux.app.statusbar.PlaceContentStrip.COLUMN_FOOT_DP)) : 0;
        if (strip.getPaddingStart() != start || strip.getPaddingTop() != top
            || strip.getPaddingEnd() != end || strip.getPaddingBottom() != bottom) {
            strip.setPaddingRelative(start, top, end, bottom);
        }
    }

    /**
     * The wall moved: the place's row content and summary go with it, the lens glyphs travel
     * along their legs, and the glass drifts towards the colour of the place coming in.
     */
    private void syncPlaceBarOffset(float offsetPx) {
        mWallOffsetPx = offsetPx;
        int width = mPaneWallController == null ? 0 : mPaneWallController.wall().getWidth();
        // The readings stand still while the wall moves under them, so the row never fades
        // or clips with the wall. The badge and the window chips are the Terminal's (ADR 0030
        // section 2): they rest a wall to the right on Home and slide in with the Terminal's
        // rows, which the top stack's renderer writes (TopStackRenderer), the bar carrying them
        // when it rides.
        View strip = hotView(R.id.terminal_status_place_content);
        if (strip != null) {
            if (strip.getTranslationY() != 0f) strip.setTranslationY(0f);
            if (strip.getAlpha() != 1f) strip.setAlpha(1f);
        }
        // At rest the top stack stands the front page's side; the wall moving or laid out again
        // (its width) and the place bar's sync are the one place every rest change passes.
        restTopStack(mLastWallPage);
        if (mPaneWallController == null) return;
        // The marks are the wall's cells, read around the current one (ADR 0016).
        com.termux.app.statusbar.StatusBarLensView lens = hotView(R.id.terminal_status_lens);
        if (lens != null) {
            lens.setWallState(mPaneWallController.cellKinds(),
                mPaneWallController.currentCellIndex(), offsetPx, width);
        }
    }

    /** The badge at the start of the status row is the terminal session's, on both halves. */
    private void bindPlaceBadge(@Nullable com.termux.app.statusbar.SessionsIndicatorView badge) {
        if (badge == null) return;
        int sessionIndex = mCurrentWSession == null ? -1 : mWSessions.indexOf(mCurrentWSession);
        badge.setSession(currentStatusSessionName(), mWSessions.size(), sessionIndex);
    }

    /** The bridge that types the in-app keyboard's values into X. Built once. */
    @NonNull
    private com.termux.app.x11.X11KeyboardBridge x11KeyboardBridge() {
        if (mX11KeyboardBridge == null) {
            mX11KeyboardBridge = new com.termux.app.x11.X11KeyboardBridge(() -> {
                com.termux.app.x11.X11PaneFrame frame = mPaneWallController == null
                    ? null : mPaneWallController.displayWindow();
                return frame == null ? null : frame.display();
            }, () -> mDisplayServer.controller() != null && mDisplayServer.controller().pasteWithShift());
        }
        return mX11KeyboardBridge;
    }

    /** The Paste shortcut of Linux windows by class, for the Wayland key path. Built once. */
    @NonNull
    private com.termux.app.wayland.LinuxPasteShortcuts linuxPasteShortcuts() {
        if (mLinuxPasteShortcuts == null) {
            final com.termux.app.x11.X11AppSettingsStore store =
                new com.termux.app.x11.X11AppSettingsStore(this);
            com.termux.app.wayland.LinuxPasteShortcuts shortcuts =
                com.termux.app.wayland.LinuxPasteShortcuts.over(store);
            // Held by the field: the preferences keep a listener only weakly.
            mLinuxPasteShortcutsListener = (prefs, key) -> shortcuts.invalidate();
            getSharedPreferences(
                TermuxConstants.TERMUX_DEFAULT_PREFERENCES_FILE_BASENAME_WITHOUT_EXTENSION,
                MODE_PRIVATE).registerOnSharedPreferenceChangeListener(mLinuxPasteShortcutsListener);
            mLinuxPasteShortcuts = shortcuts;
        }
        return mLinuxPasteShortcuts;
    }

    /** Stopping a display closes everything on it, so it is asked once. */
    private void confirmStopEmbeddedDisplay() {
        if (!mDisplayServer.isRunning()) return;
        new com.google.android.material.dialog.MaterialAlertDialogBuilder(this)
            .setTitle(R.string.termux_wall_display_stop_title)
            .setMessage(R.string.termux_wall_display_stop_message)
            .setNegativeButton(android.R.string.cancel, null)
            .setPositiveButton(R.string.termux_wall_display_stop_confirm,
                (dialog, which) -> mDisplayServer.stop())
            .show();
    }

    /**
     * Put the Widgets place on the wall: the app-widget grid, and the border tab that carries its
     * settings and the pencil that starts editing it.
     */
    private void attachWidgetsPage() {
        if (mPaneWallController == null) return;
        com.termux.app.wall.WidgetPaneFrame page =
            mPaneWallController.attachWidgetsPage(getLayoutInflater());
        if (page == null) return;
        // The Home pages register only now that their one view exists.
        mPaneWallController.setHomePageFactory(
            id -> new com.termux.app.launcher.home.HomePage(id, mHomePageHost, mHomeGlass));
        page.setGlass(mHomeGlass);
        mPaneWallController.setDisplayPageFactory(mDisplayPages::page);
        mPaneWallController.setTerminalStops(mTerminalPages);
        page.setHost(new com.termux.app.wall.WidgetPaneFrame.Host() {
            @Override public void showHelpOverlay() { TermuxActivity.this.showHelpOverlay(); }
            // Widgets take what the dock and the floats leave of Live blur's budget.
            @Override public boolean liveBlur() { return mLiveBlur; }
            @Override public void openSurfaceEditor() {
                TermuxActivity.this.openSurfaceEditor(com.termux.app.surfaces.EditorDoor.PANE_CONTROLS);
            }
            @Override public boolean isMinimalMode() {
                return TermuxActivity.this.isMinimalMode();
            }
            @Override public void toggleMinimalMode() {
                setMinimalMode(!TermuxActivity.this.isMinimalMode());
            }
            @Override public boolean editWidgets() {
                return mWidgetPaneController != null && mWidgetPaneController.editWidgets();
            }
            @Override public int widgetGridColumns() {
                return widgetGridCaps().clampColumns(
                    arrangement().layout().widgetColumns);
            }
            @Override public int widgetGridRows() {
                return widgetGridCaps().clampRows(
                    arrangement().layout().widgetRows);
            }
            @Override @NonNull public com.termux.app.launcher.widget.WidgetGridCaps widgetGridCaps() {
                return mWidgetPaneController != null ? mWidgetPaneController.gridCaps()
                    : com.termux.app.launcher.widget.WidgetGridCaps.unbounded();
            }
            @Override public void setWidgetGrid(int columns, int rows) {
                PlaceLayoutStore store = placeLayoutStore();
                if (store == null) return;
                PlaceOrientation orientation = currentPlaceOrientation();
                store.setWidgetColumns(orientation, columns);
                store.setWidgetRows(orientation, rows);
                // The grid is drawn from the layout, so the same re-read the Layout
                // page's sliders trigger is what reflows it here - no second path to applyGrid.
                syncPlaceLayout();
            }
        });
        mPaneWallController.setPages(mPages);
    }

    /**
     * The build carries the embedded Linux display. Nothing switches it on (ADR 0008): a display
     * comes up on demand and its window is on the row while it is ({@link #isDisplayUp}).
     */
    public boolean isX11DisplayEnabled() {
        return com.termux.app.x11.X11ServerSupport.isAvailable(TermuxActivity.this) && mPreferences != null;
    }

    /**
     * A display is up, so its window is in a row: one runs, or one was asked for and is starting
     * ({@link com.termux.app.x11.DisplayServer#isRequested()}).
     */
    private boolean isDisplayUp() {
        return isX11DisplayEnabled() && mPaneWallController != null
            && mPaneWallController.displayWindow() != null
            && (mDisplayServer.isRequested() || mDisplayServer.isRunning());
    }

    // ---- The display window in the Terminal's row (ADR 0008, amended 2026-10-19) -----------

    /** The current session's terminal windows; none while no session is current. */
    @NonNull
    private java.util.List<com.termux.app.terminal.TerminalPaneController.Window> rowWindows() {
        return mCurrentWSession == null ? java.util.Collections.emptyList()
            : mCurrentWSession.windows;
    }

    /** How many windows the current row has: its terminal windows and its Linux windows (#392). */
    private int rowWindowCount() {
        return mCurrentWSession == null ? 0 : mCurrentWSession.row.count(mCurrentWSession.windows);
    }

    /** How many terminal windows the current row has (ADR 0015). */
    private int terminalWindowCount() {
        return rowWindows().size();
    }

    /** The row place of the current row's terminal window {@code terminal}; -1 when out of range. */
    private int placeOfTerminal(int terminal) {
        return mCurrentWSession == null ? -1
            : mCurrentWSession.row.indexOfTerminal(mCurrentWSession.windows, terminal);
    }

    /** The terminal window index at row place {@code place}; -1 for a Linux window or out of range. */
    private int terminalAtPlace(int place) {
        return mCurrentWSession == null ? -1
            : mCurrentWSession.row.terminalAt(mCurrentWSession.windows, place);
    }

    /** The Linux window in front of the current row (#392); 0 while a terminal window is. */
    private long linuxWindowInFront() {
        WSession ws = mCurrentWSession;
        if (ws == null || mLinuxWindows == null || !ws.row.hasLinux()) return 0L;
        // Reading the place in front drops a front that left the row.
        ws.row.frontIndex(ws.windows, ws.current);
        return ws.row.front();
    }

    /**
     * Whether the wall is on a Display page (ADR 0015, A3b): what the keyboard's form, the keys
     * and help read as "the display is in front". Mid-slide, the page the wall committed to.
     */
    private boolean isDisplayWindowInFront() {
        return mPaneWallController != null
            && mPaneWallController.currentPage() == com.termux.app.page.PageKind.DISPLAY;
    }

    /** The row place of the window in front, a Linux window's included (#392). */
    private int rowCurrentIndex() {
        WSession ws = mCurrentWSession;
        if (ws == null) return 0;
        return Math.max(0, ws.row.frontIndex(ws.windows, ws.current));
    }

    /**
     * The display window comes in front of the row ({@code front}) or the terminal window behind
     * it takes its place, carried in from {@code direction}'s side (+1 the right, -1 the left, 0
     * at once) over the rest of a page from {@code fromPx}, as a window switch travels. A terminal
     * window chosen in its place is shown by the caller first.
     *
     * @param fromPx where the arriving window stands, or 0 for a whole page away
     * @param fromRow the row place the arrival left, for the wallpaper's pan
     */
    private void setDisplayInFront(boolean front, int direction, float fromPx, int fromRow) {
        if (mPaneWallController == null || front == isDisplayWindowInFront()) return;
        // A Display page is a page of the wall (A3b): in front is the wall going there, and
        // back is the wall going to the Terminal page.
        boolean animate = direction != 0 && isVisible() && !isReducedMotionEnabled();
        if (front) mPaneWallController.goToDisplayPage(-1, animate);
        else mPaneWallController.goTo(com.termux.app.page.PageKind.TERMINAL, animate);
    }

    /**
     * The window in front of the Terminal changed kind without the wall moving — the display
     * window came in front, or a terminal window took its place — so the place changed: what a
     * settle does for a place is done here. Mid-slide, the settle that ends the slide does it.
     */
    private void onDisplayFrontChanged() {
        if (mPaneWallController == null) return;
        mStatusCardHost.dismiss();
        com.termux.app.x11.X11PaneFrame display = mPaneWallController.displayWindow();
        if (display != null) display.dismissControls();
        if (mPaneWallController.currentPage() != com.termux.app.page.PageKind.TERMINAL) return;
        syncPlaceBar();
        refreshTerminalWindowBar();
        com.termux.app.wall.PaneWallLayout wall = mPaneWallController.wall();
        if (wall.isMoving() || wall.offsetPx() != 0f) return;
        com.termux.app.page.PageKind place = currentWallPlace();
        settlePlaceChrome(place);
        syncDisplayAttachment(place);
        // No landing follows a change of window under a wall at rest: the view goes with it now.
        if (place == com.termux.app.page.PageKind.DISPLAY) mDisplayPages.attach();
        else mDisplayPages.leave();
        if (place == com.termux.app.page.PageKind.TERMINAL) noteTerminalPlaceMayBeVisible();
        // A display window left before its display came up goes, once the window that took its
        // place has arrived.
        if (place != com.termux.app.page.PageKind.DISPLAY) {
            dropUnstartedDisplayWhenSettled(windowSwitchMs(
                com.termux.app.terminal.TerminalWindowBar.WINDOW_SWITCH_ANIMATION_DURATION_MS));
        }
    }

    /**
     * Bring the row's window at {@code row} in front, the display window's included, as the
     * window chips and {@code window.select} do: a terminal window by the window switch's travel,
     * the display window by the same travel with its frame.
     */
    private void showRowWindow(int row) {
        if (mPaneController == null) return;
        mMaximise.checkLater();
        int count = rowWindowCount();
        if (row < 0 || row >= count) return;
        int previous = rowCurrentIndex();
        if (row == previous) return;
        int direction = row > previous ? 1 : -1;
        int window = terminalAtPlace(row);
        if (isDisplayWindowInFront() && window < 0) {
            // A Linux window: it comes in front of the row, and the wall goes back to the Terminal.
            showRowPlaceAcrossLinux(row, 0, 0f, previous);
            setDisplayInFront(false, direction, 0f, previous);
            return;
        }
        if (!isDisplayWindowInFront() && showRowPlaceAcrossLinux(row, direction, 0f, previous)) return;
        if (isDisplayWindowInFront()) {
            // The display goes off as the window comes in: no picture of a terminal is leaving.
            if (mCurrentWSession != null) mCurrentWSession.row.clearFront();
            if (mCurrentWSession != null && window != mCurrentWSession.current) {
                mCurrentWSession.current = window;
                mPaneController.showWindow(mCurrentWSession.currentWindow());
            }
            syncLinuxFront();
            setDisplayInFront(false, direction, 0f, previous);
            rebuildDrawerSessions();
            return;
        }
        showWindowFromBar(window);
    }

    /**
     * With the display window in front of the row, the terminal window behind it comes in front
     * (the one that was in front before it), travelling as a window switch; a row with no terminal
     * window gets a fresh shell, whose window then takes the front. Nothing otherwise.
     */
    private void bringTerminalWindowInFront() {
        if (mPaneWallController == null) return;
        if (linuxWindowInFront() != 0L) {
            // A Linux window's page is the Terminal page's place (#392): Go to Terminal there
            // brings the nearest terminal window in front, as it does from the display.
            int places = rowWindowCount();
            boolean[] linux = new boolean[places];
            for (int i = 0; i < places; i++) linux[i] = terminalAtPlace(i) < 0;
            int place = com.termux.app.wayland.LinuxWindowRow.nearestTerminalPlace(
                rowCurrentIndex(), linux);
            if (place >= 0) showRowWindow(place);
            return;
        }
        if (!isDisplayWindowInFront()) return;
        // The Terminal page beside it, its first shell started when it has none.
        mPaneWallController.goToTerminal(isVisible() && !isReducedMotionEnabled());
    }

    // ---- A window's controls on its mark (status-row-and-marks, Window controls) -------------

    /** Where a held mark's or window chip's controls go (WindowControlRouter); made at first use. */
    @Nullable private com.termux.app.statusbar.WindowControlRouter mWindowControlRouter;
    private final int[] mControlLoc = new int[2];

    @NonNull
    private com.termux.app.statusbar.WindowControlRouter windowControlRouter() {
        if (mWindowControlRouter == null) mWindowControlRouter = new com.termux.app.statusbar.WindowControlRouter(
            new com.termux.app.statusbar.WindowControlRouter.Actions() {
                @Override public void closeRowWindow(int place) { TermuxActivity.this.closeRowWindow(place); }
                @Override public void closeDisplay(int pageId) { closeDisplayWindowFromRow(); }
                @Override public void minimiseRowWindow(int place) { if (mMinimise.minimise(place)) mMaximise.check(); }
                @Override public void toggleMaximise(@NonNull com.termux.app.wall.pageswitch.PageBarModel.Target target) { mMaximise.toggle(target); }
                @Override public void moveLinuxWindow(int place, float x, float y, int pointerId) {
                    long id = mMinimiseHost.linuxAt(place);
                    if (id == 0L || mLinuxWindows == null || mTermuxActivityRootView == null) return;
                    mTermuxActivityRootView.getRootView().getLocationOnScreen(mControlLoc);
                    mLinuxWindows.beginCarryById(id, x - mControlLoc[0], y - mControlLoc[1], pointerId);
                }
                @Override public void scaleLinuxWindow(int place) {
                    long id = mMinimiseHost.linuxAt(place);
                    if (id == 0L || mLinuxWindows == null) return;
                    // In front first: the rail stands on the window's own page.
                    goToLinuxWindow(id);
                    mLinuxWindows.showScaleRail(id);
                }
                @Override public boolean linuxWindowScales(int place) {
                    long id = mMinimiseHost.linuxAt(place);
                    return id == 0L || mLinuxWindows == null || mLinuxWindows.windowTakesScale(id);
                }
                @Override public boolean linuxWindowIsDesktop(int place) {
                    long id = mMinimiseHost.linuxAt(place);
                    return id != 0L && mLinuxWindows != null && mLinuxWindows.windowIsDesktop(id);
                }
                @Override public void fullScreenLinuxWindow(int place) {
                    long id = mMinimiseHost.linuxAt(place);
                    if (id == 0L || mLinuxWindows == null) return;
                    // In front first: a row window takes the screen from the Linux page.
                    goToLinuxWindow(id);
                    mLinuxWindows.fullScreenWindow(id);
                }
            });
        return mWindowControlRouter;
    }

    /**
     * The app of Linux window {@code id} asked for its window menu: its controls open as if its
     * mark were held: on the row (the marks, or the chips under Glyphs) for a row window, on the
     * pane's corner tab for a pane of a split. No finger is down: a press on a control acts.
     */
    private void showLinuxWindowControls(long id) {
        if (mPaneController != null && mPaneController.hasLinuxPane(id)) {
            mPaneController.showLinuxPaneControls(id);
            return;
        }
        WSession ws = mCurrentWSession;
        int place = ws == null ? -1 : ws.row.indexOfLinux(ws.windows, id);
        if (place < 0) return;
        com.termux.app.wall.pageswitch.PageBarModel.Entry entry = pageBarModel().rowWindow(place);
        if (entry == null) return;
        if (mMarksLine.marksLookShown()) {
            mMarksLine.openWindowControls(com.termux.app.page.PageKind.LINUX, place);
        } else if (mChipControlsHold != null) {
            mChipControlsHold.open(entry);
        }
    }

    /** The Glyphs look's hold on the window bar, kept to open its controls for a window's app. */
    @Nullable private com.termux.app.statusbar.ChipControlsHold mChipControlsHold;

    /** The Glyphs look: a still hold on a window chip opens the window's controls over the bar. */
    @NonNull
    private com.termux.app.statusbar.ChipControlsHold chipControlsHold(@NonNull com.termux.app.terminal.TerminalWindowBar bar) {
        return new com.termux.app.statusbar.ChipControlsHold(bar, new com.termux.app.statusbar.ChipControlsHold.Host() {
            // On a Display page the bar's chips are the display's apps, not windows.
            @Nullable @Override public com.termux.app.wall.pageswitch.PageBarModel.Entry heldWindow(int i) { return isDisplayWindowInFront() ? null : pageBarModel().rowWindow(i); }
            @Override public int accent() { return resolveAzGestureAccentColor(); }
            @Nullable @Override public com.termux.app.statusbar.MarksLineView.TitleGlass glass() { return mMarksLine.titleGlass(); }
            @NonNull @Override public com.termux.app.statusbar.MarksLineView.WindowControls controls() { return windowControlRouter(); }
        });
    }

    /** What Minimise reads and does of the row (MinimiseController). */
    @NonNull private final com.termux.app.terminal.MinimiseController.Host<com.termux.app.terminal.TerminalPaneController.Window> mMinimiseHost =
        new com.termux.app.terminal.MinimiseController.Host<com.termux.app.terminal.TerminalPaneController.Window>() {
            @Override public long linuxAt(int place) { return mCurrentWSession == null ? 0L : mCurrentWSession.row.linuxAt(mCurrentWSession.windows, place); }
            @Override public void minimiseLinux(long id) { if (mLinuxWindows != null) mLinuxWindows.minimiseRowWindow(id); refreshTerminalWindowBar(); }
            @Override public void restoreLinux(long id) {
                if (mPaneWallController != null && currentWallPlace() != com.termux.app.page.PageKind.TERMINAL) mPaneWallController.goTo(com.termux.app.page.PageKind.TERMINAL, switcherAnimates());
                if (mLinuxWindows != null) mLinuxWindows.tapChip(id);
            }
            @Override public void minimisedLinuxIds(@NonNull java.util.List<Long> out) { if (mLinuxWindows != null) mLinuxWindows.minimisedIds(out); else out.clear(); }
            @Override public int terminalAtPlace(int place) { return TermuxActivity.this.terminalAtPlace(place); }
            @Override public int terminalCount() { return terminalWindowCount(); }
            @Nullable @Override public com.termux.app.terminal.TerminalPaneController.Window removeFromRow(int index) { return takeOutOfRow(index); }
            @Override public void returnToRow(@NonNull com.termux.app.terminal.TerminalPaneController.Window window, int index) { putBackInRow(window, index); }
            @Override public boolean hasShells(@NonNull com.termux.app.terminal.TerminalPaneController.Window w) { return mPaneController != null && !mPaneController.shellsOf(w).isEmpty(); }
            @Nullable @Override public String name(@NonNull com.termux.app.terminal.TerminalPaneController.Window w) { return mPaneController == null ? null : mPaneController.windowName(w); }
            @Nullable @Override public String linuxName(long id) { return linuxWindowName(id); }
            @Nullable @Override public String linuxIconKey(long id) { return linuxWindowIconKey(id); }
            @Nullable @Override public Bundle save(@NonNull com.termux.app.terminal.TerminalPaneController.Window w) { return mPaneController == null ? null : mPaneController.saveWindow(w); }
        };
    @NonNull private final com.termux.app.terminal.MinimiseController<com.termux.app.terminal.TerminalPaneController.Window> mMinimise =
        new com.termux.app.terminal.MinimiseController<>(mMinimiseHost);

    /** Takes terminal window {@code index} out of the row (Minimise): its shells keep running. */
    @Nullable
    private com.termux.app.terminal.TerminalPaneController.Window takeOutOfRow(int index) {
        WSession ws = mCurrentWSession;
        if (ws == null || mPaneController == null || index < 0 || index >= ws.windows.size()) return null;
        int oldIndex = ws.current;
        boolean visible = index == oldIndex && !isDisplayWindowInFront();
        if (visible) captureTerminalDeparture();
        com.termux.app.terminal.TerminalPaneController.Window window = ws.windows.remove(index);
        settleRowAfterLeaving(index, oldIndex, visible);
        rebuildDrawerSessions();
        return window;
    }

    /** Puts a minimised window back into the row at terminal index {@code at}, in front. */
    private void putBackInRow(@NonNull com.termux.app.terminal.TerminalPaneController.Window window, int at) {
        WSession ws = mCurrentWSession;
        if (ws == null) mWSessions.add(ws = mCurrentWSession = new WSession());
        if (at <= ws.current && !ws.windows.isEmpty()) ws.current++;
        ws.windows.add(at, window);
        ws.row.terminalAdded(ws.windows, window);
        refreshTerminalWindowBar();
        rebuildDrawerSessions();
        pageSwitchNavigator().showTerminalWindow(placeOfTerminal(at));
    }

    /** A window's Maximise: which window fills the screen, and the arrangement it stands. */
    @NonNull private final com.termux.app.chrome.MaximiseController mMaximise =
        new com.termux.app.chrome.MaximiseController(new com.termux.app.chrome.MaximiseController.Host() {
            @Override public void applyMaximise() { applyFullscreenMode(); syncPlaceLayout(); mChrome.requestSync(ChromeRenderer.SCOPE_APPLY_THIS_FRAME); }
            @Override public void navigateTo(@NonNull com.termux.app.wall.pageswitch.PageBarModel.Target t) { com.termux.app.wall.pageswitch.PageSwitchTargets.carryOut(t, pageSwitchNavigator()); }
            @NonNull @Override public String frontKey() { return com.termux.app.chrome.MaximiseController.frontKeyOf(pageBarModel()); }
            @Override public boolean keyboardShown() { return isInAppKeyboardShown(); }
            @Override public void post(@NonNull Runnable r) { if (mTermuxActivityRootView != null) mTermuxActivityRootView.post(r); }
            @Override public void postDelayed(@NonNull Runnable r, long ms) { if (mTermuxActivityRootView != null) mTermuxActivityRootView.postDelayed(r, ms); }
            @Override public void removeCallbacks(@NonNull Runnable r) { if (mTermuxActivityRootView != null) mTermuxActivityRootView.removeCallbacks(r); }
        });

    /**
     * Seam for the window bar's ×, {@code window.close} by place: the row's window at {@code row}
     * closes, the display window's included ({@link #closeDisplayWindowFromRow}).
     */
    private void closeRowWindow(int row) {
        long linux = mCurrentWSession == null ? 0L
            : mCurrentWSession.row.linuxAt(mCurrentWSession.windows, row);
        if (linux != 0L) {
            // A Linux window's close asks its app to close, as its rim tab's Close does.
            if (mLinuxWindows != null) mLinuxWindows.closeChip(linux);
            return;
        }
        int window = terminalAtPlace(row);
        if (window < 0 || window >= rowWindows().size()) return;
        if (windowHasForegroundJob(window)) confirmCloseWindow(window);
        else closeWindow(window);
    }

    /**
     * The display window's close: it is the display, so closing it stops it — every app on it is
     * asked to close first (Stop's sequence), asked first when an app is open, since closing them
     * may lose their work. A display still starting, or waiting for its keyboard layouts, simply
     * goes. The window leaves the row when the display does ({@link com.termux.app.x11.DisplayServer#tearDown}).
     */
    private void closeDisplayWindowFromRow() {
        if (!isDisplayUp()) return;
        if (!mDisplayServer.isRunning()) {
            mDisplayServer.tearDown();
            return;
        }
        if (mDisplayServer.windows().isEmpty()) mDisplayServer.stop();
        else confirmStopEmbeddedDisplay();
    }

    /**
     * The display window comes in front of the current row: joined at the row's end if another
     * session's row held it, and the wall brought to the Terminal.
     */
    private void bringDisplayWindowInFront(boolean animateWall) {
        bringDisplayWindowInFront(animateWall, -1);
    }

    /** {@code pageId}: the Display page to show it on (A3c, a routed Linux app); -1 the bound one. */
    private void bringDisplayWindowInFront(boolean animateWall, int pageId) {
        if (mPaneWallController == null || !isDisplayUp()) return;
        mPaneWallController.refreshPages();
        // The wall goes to the bound Display page (A3b); a wall with none has nowhere to show it.
        if (!mPaneWallController.goToDisplayPage(pageId, animateWall)) {
            Logger.logWarn(LOG_TAG, "No Display page on the wall to show the display on");
        }
        onWallPlacesChanged();
        refreshTerminalWindowBar();
    }

    /**
     * Build the display window: the page that inflates the X view, whose native side loads the
     * server library and allocates a context, and the server connection behind it. Built only when
     * a display is wanted or one announced itself, so an install that never runs one never builds
     * any of it; the page goes again when the display does ({@link com.termux.app.x11.DisplayServer#tearDown}).
     * Whether it is on the row is {@link #isDisplayUp}'s to say.
     */
    private void buildDisplayWindow() {
        if (buildDisplayFrame()) createX11DisplayController();
    }

    /**
     * The display's frame alone, as the Display page's view: its X view and its host, without the
     * server connection ({@link #buildDisplayWindow} adds that). Answers whether there is one.
     */
    private boolean buildDisplayFrame() {
        if (mPaneWallController == null || !isX11DisplayEnabled()) return false;
        com.termux.app.x11.X11PaneFrame page =
            mPaneWallController.attachDisplayWindow(getLayoutInflater());
        if (page == null) return false;
        page.setFramePipeline(mFrames);
        page.setHost(new com.termux.app.x11.X11PaneFrame.Host() {
            @Override public void showHelpOverlay() { TermuxActivity.this.showHelpOverlay(); }
            @Override public void openSurfaceEditor() {
                TermuxActivity.this.openSurfaceEditor(com.termux.app.surfaces.EditorDoor.PANE_CONTROLS);
            }
            @Override public boolean isMinimalMode() {
                return TermuxActivity.this.isMinimalMode();
            }
            @Override public void toggleMinimalMode() {
                setMinimalMode(!TermuxActivity.this.isMinimalMode());
            }
            @Override public void startDisplay() { mDisplayServer.start(); }
            @Override public void turnOnDisplay() { mDisplayServer.start(); }
            @Override public void installKeyboardData(@NonNull java.util.List<String> command) {
                runKeyboardDataInstall(command);
            }
            @Override public void toggleDisplayPower() {
                if (mDisplayServer.isRunning()) confirmStopEmbeddedDisplay();
                else mDisplayServer.start();
            }
            @Override public void openDisplaySettings() {
                ActivityUtils.startActivity(TermuxActivity.this,
                    com.termux.app.activities.SettingsActivity.createFragmentIntent(TermuxActivity.this,
                        com.termux.app.fragments.settings.termux.X11DisplayPreferencesFragment.class,
                        R.string.settings_terminal_sub_linux_apps_title));
            }
            @Override public boolean consumeLauncherKey(@NonNull KeyEvent event) {
                return consumeDisplayWindowKey(event);
            }
        });
        page.applyEnabled(true);
        // The phone defaults (text size, touch mode) go in the first time a display is used.
        com.termux.app.x11.X11Defaults.applyOnce(this);
        return true;
    }

    /**
     * Brings the wall and the chrome that reads it up to date after a place came or went at
     * rest: the bar's marks and gesture, the key row's place switches, and the shipped key row
     * itself, which carries a switch only for the places the wall has.
     */
    private void onWallPlacesChanged() {
        refreshPlaceBar();
        reloadExtraKeysFromProperties();
        mAppliedExtraKeysPlace = null;
        applyExtraKeysPlaceEligibility();
    }

    /** The display window is wanted: its page and the server connection built, if they are not. */
    private void attachEmbeddedDisplay() {
        if (mPaneWallController == null || !isX11DisplayEnabled()) return;
        if (mPaneWallController.displayWindow() == null) buildDisplayWindow();
        else createX11DisplayController();
    }

    /** Whether the display was up the last time the row was re-read for it. */
    private boolean mDisplayUpOnRow;

    /**
     * The row re-read after the display came up or went down, and the chrome that names the
     * row's windows with it: the chips, and the key row's display switch when the display came
     * or went.
     */
    private void syncDisplayOnRow() {
        if (mPaneWallController == null) return;
        mPaneWallController.refreshPages();
        boolean up = isDisplayUp();
        if (up != mDisplayUpOnRow) {
            mDisplayUpOnRow = up;
            onWallPlacesChanged();
        }
        // The display's chip comes and goes with its window.
        refreshTerminalWindowBar();
    }

    /**
     * Open the display window and bring it in front: the Display entry, {@code wall.display} and
     * Go to Display, and every Linux app tapped in the drawer come here. With no display running
     * one is asked for, so the window joins the row while it starts and says what it is waiting
     * for; {@code start} starts it here (a Linux app's runner starts it itself, with the app queued
     * behind it). A display missing its keyboard layouts is not started: the window offers to
     * install them instead. A display window already in another session's row moves to this one.
     */
    private void openDisplayWindow(boolean start) {
        openDisplayWindow(start, -1);
    }

    /** {@code pageId}: the Display page to show the display on (A3c); -1 the bound one. */
    private boolean openDisplayWindow(boolean start, int pageId) {
        if (mPaneWallController == null || !isX11DisplayEnabled()) return false;
        attachEmbeddedDisplay();
        if (mPaneWallController.displayWindow() == null) return false;
        if (!mDisplayServer.isRunning()) {
            mDisplayServer.setRequested(true);
            if (start && com.termux.app.x11.X11CliInstaller.hasKeyboardData()) {
                mDisplayServer.start();
            }
        }
        closeAppDrawerForLinuxLaunch();
        if (mTilingDesktop != null) {
            // Every kind is a tile (#419): the display opens as a window, not a wall page.
            mTilingDesktop.openDisplay();
            return true;
        }
        // A Linux app can be launched (via launcherctl) while this Activity is stopped. Animating
        // a wall transition nobody can see would just spend real frames on an invisible window
        // (the same reasoning as TerminalWindowBar's animateSelectionSlide); animate only when
        // visible, otherwise land on the window directly so it is simply where the user finds it.
        bringDisplayWindowInFront(isVisible(), pageId);
        if (isDisplayUp() != mDisplayUpOnRow) {
            mDisplayUpOnRow = isDisplayUp();
            onWallPlacesChanged();
        }
        return true;
    }

    /**
     * A Linux launch gave up before a display came up (#192): the Display page it added goes
     * again, committed so it leaves the store. Only the page that launch added, and never one a
     * display is up on.
     */
    private void dropAddedLinuxPage() {
        int id = mAddedLinuxPage;
        mAddedLinuxPage = -1;
        if (id < 0 || (isDisplayUp() && mDisplayPageBinding.boundPage() == id)) return;
        // A page made lasting since ("Add display") is the user's now.
        com.termux.app.wall.WallPages.Page page = wallPages().page(id);
        if (page == null || !page.temporary) return;
        editWallPages(pages -> pages.remove(id));
        wallPagesStore().commitRemoval(id);
    }

    /**
     * The temporary Display page a drawer launch put up goes with its display (ADR 0015's
     * 2026-11-04 amendment): removed for good the way Edit pages removes a Display page, so a
     * wall on it lands on its neighbour. Runs when the display stops or its app is gone.
     */
    private void removeTemporaryDisplayPage() {
        mAddedLinuxPage = -1;
        mTemporaryDisplaySawApp = false;
        mTemporaryDisplayStartedByLaunch = false;
        com.termux.app.wall.WallPages.Page page = wallPages().temporaryDisplay();
        if (page == null) return;
        final int id = page.id;
        editWallPages(pages -> pages.remove(id));
        wallPagesStore().commitRemoval(id);
    }

    /**
     * The display's app list changed: once an app has stood on the temporary page's display and
     * none is left for {@link #TEMPORARY_DISPLAY_APP_GONE_MS}, the page goes, and the display
     * with it when that launch started it.
     */
    private void noteTemporaryDisplayWindows(int count) {
        if (wallPages().temporaryDisplay() == null) {
            mTemporaryDisplaySawApp = false;
            return;
        }
        if (count > 0) {
            mTemporaryDisplaySawApp = true;
            return;
        }
        if (!mTemporaryDisplaySawApp || mPaneWallController == null) return;
        mTemporaryDisplayEmptyAtMs = android.os.SystemClock.uptimeMillis();
        mPaneWallController.wall().postDelayed(this::closeTemporaryDisplayIfAppGone,
            TEMPORARY_DISPLAY_APP_GONE_MS);
    }

    private void closeTemporaryDisplayIfAppGone() {
        if (isFinishing() || isDestroyed()) return;
        if (!mTemporaryDisplaySawApp || !mDisplayServer.windows().isEmpty()
            || wallPages().temporaryDisplay() == null) return;
        // Emptied again since this check was posted: that later one decides.
        if (android.os.SystemClock.uptimeMillis() - mTemporaryDisplayEmptyAtMs
            < TEMPORARY_DISPLAY_APP_GONE_MS) return;
        // The display stopping takes the page with it (tearDownEmbeddedDisplay).
        if (mTemporaryDisplayStartedByLaunch && mDisplayServer.isRunning()) {
            mDisplayServer.stop();
            return;
        }
        removeTemporaryDisplayPage();
    }

    /**
     * Start-up sweep: a temporary Display page left in the store (the process died with it up)
     * goes when no display runs or is kept to be claimed; a live one is left to its display.
     */
    private void sweepTemporaryDisplayPages() {
        if (wallPages().temporaryDisplay() == null) return;
        if (mDisplayServer.isRunning()
            || com.termux.app.x11.X11DisplayReceiver.hasKeptAnnouncement()) return;
        wallPagesStore().transform(com.termux.app.wall.WallPages::withoutTemporaryPages);
    }

    /**
     * A display announced itself with no window open — started from a shell, by Start with the
     * launcher, or before this activity existed: build the window, and the controller takes the
     * kept announcement and reports the display running, which puts the window on the row.
     */
    private void claimKeptDisplay() {
        if (mPaneWallController == null || !isX11DisplayEnabled()) return;
        // A Display page's frame alone has no server connection yet: the announcement is its.
        if (mPaneWallController.displayWindow() != null && mDisplayServer.controller() != null) return;
        if (!com.termux.app.x11.X11DisplayReceiver.hasKeptAnnouncement()) return;
        attachEmbeddedDisplay();
    }

    /**
     * The row came to rest away from a display window whose display never came up (it would not
     * start, or it waits for its keyboard layouts): the ask lapses and the window goes, so a
     * window with nothing on it does not stay in the row. {@code place} is where it rests.
     */
    private void dropUnstartedDisplay(@NonNull com.termux.app.page.PageKind place) {
        if (place == com.termux.app.page.PageKind.DISPLAY || !mDisplayServer.isRequested()
            || mDisplayServer.isRunning()) return;
        mDisplayServer.setRequested(false);
        mDisplayServer.tearDown();
    }

    /** {@link #dropUnstartedDisplay} once the wall and the window it brought in are at rest. */
    private void dropUnstartedDisplayWhenSettled(long delayMs) {
        if (mPaneWallController == null || !mDisplayServer.isRequested()) return;
        mPaneWallController.wall().postDelayed(() -> {
            if (mPaneWallController == null || mPaneWallController.wall().isMoving()) return;
            dropUnstartedDisplay(currentWallPlace());
        }, delayMs);
    }

    /**
     * The activity's half of the display window's teardown (the server's half is
     * {@link com.termux.app.x11.DisplayServer#tearDown}): the window's frame and the X view behind
     * it are removed — which frees the view's native context — and the chrome that read the row is
     * brought up to date. A display window in front hands the row to the window on its left.
     */
    private void tearDownEmbeddedDisplayWindow(boolean wasInFront) {
        // Whoever owns typing now — an open palette or sheet keeps its claim — not nobody.
        restoreInAppKeyboardTypingClaim();
        mDisplayKeys.hideDisplaySystemKeyboard();
        mDisplayPages.releaseFocus();
        mPaneWallController.detachDisplayWindow();
        // A Display window (#419) builds its frame again, showing the display's landing.
        if (mTilingDesktop != null) mTilingDesktop.onContentChanged();
        syncDisplayEnvironment();
        mDisplayKeys.syncDisplayKeyboardRoute();
        mDisplayUpOnRow = false;
        onWallPlacesChanged();
        // The window on its left took its place in front without the wall moving: the place
        // changed under the chrome, as a window switch onto a terminal changes it.
        if (wasInFront) onDisplayFrontChanged();
        rebuildDrawerSessions();
        // Taking the page away hands the wall to a window with no settle after it, and may move
        // the panes under the hand-back above: the keys are checked once more where they ended.
        if (!(getCurrentFocus() instanceof TerminalView)) returnKeysToTerminal();
        // A temporary page goes with its display.
        removeTemporaryDisplayPage();
        // The Display pages stay on the wall: a fresh frame stands on the bound one, its card. It
        // goes up in this same pass, not a posted one: with the old frame off and nothing on the
        // page, a frame between would draw the bare wallpaper.
        mDisplayPageBinding.ensureFrame();
    }

    @Nullable private String mDiagDisplayKb; // DIAG(display-kb)
    @Nullable private String mDiagDockFilter; // DIAG(dock-filter)

    /** Whether a layer — the drawer, the palette, a sheet, help — is open over the page. */
    private boolean isLayerOpen() {
        return mOverlays.anyOpen();
    }

    /** The Back press whose release the layer that took it is owed, so X never sees half a Back. */
    private boolean mLayerClaimedBackDown;

    /**
     * Every key aimed at the display window. An open layer takes keys first, through the same
     * registry calls the terminal path makes, and only what it leaves reaches X. With none open
     * the display's keyboard is a PC keyboard: every key, chords included, is X's. The wall is
     * left by touch, by the place icons, or by Home. Back is the one exception, because the
     * phone has nothing else that means "back".
     */
    private boolean consumeDisplayWindowKey(@NonNull KeyEvent event) {
        int keyCode = event.getKeyCode();
        if (event.getAction() == KeyEvent.ACTION_UP) {
            // Asked even with every layer gone: the press a layer took ended it, and its
            // release must not become a Back for the app.
            if (keyCode == KeyEvent.KEYCODE_BACK && mLayerClaimedBackDown) {
                mLayerClaimedBackDown = false;
                return true;
            }
            if (mOverlays.consumeKeyUp(keyCode)) return true;
        } else if (event.getAction() == KeyEvent.ACTION_DOWN && isLayerOpen()
                && mOverlays.consumeKeyDown(keyCode, event)) {
            if (keyCode == KeyEvent.KEYCODE_BACK) mLayerClaimedBackDown = true;
            return true;
        }
        if (keyCode != KeyEvent.KEYCODE_BACK) return false;
        return mDisplayPages.consumeBack(event);
    }

    /**
     * Text the phone's keyboard committed into the display: what an open layer takes is its own,
     * and what is left is for X.
     */
    @NonNull
    private String textLeftAfterOpenLayer(@NonNull String text) {
        if (!isLayerOpen()) return text;
        StringBuilder left = new StringBuilder(text.length());
        for (int i = 0; i < text.length(); ) {
            int codePoint = text.codePointAt(i);
            i += Character.charCount(codePoint);
            if (!mOverlays.consumeCodePoint(codePoint, false)) left.appendCodePoint(codePoint);
        }
        return left.toString();
    }

    /**
     * Whether the display's view may take the focus back for itself, as it does whenever the
     * window regains focus: not over an open layer, and not from a launcher text field.
     */
    private boolean displayViewMayTakeFocus() {
        return !isLayerOpen() && !(getCurrentFocus() instanceof EditText);
    }

    /**
     * Gives the focus back to the display's view when the display window is the one showing;
     * true when it did, so a caller that would hand it to a terminal pane leaves it be.
     */
    private boolean returnFocusToDisplayWindow() {
        if (settledWallPage() != com.termux.app.page.PageKind.DISPLAY) return false;
        com.termux.x11.LorieView display = mDisplayKeys.displayView();
        if (display == null) return false;
        display.requestFocus();
        return true;
    }

    /**
     * Put the Display place's keyboard down by the same route the keyboard key takes, so the
     * text-focus policy hears the user asking for it away: the frame swaps back to mouse mode's
     * touchpad, or the keyboard itself goes.
     */
    private void lowerDisplayKeyboard() {
        if (mTouchpad.applyDisplayFrameKeyboard(false)) return;
        if (mInAppKeyboard != null) mInAppKeyboard.hide(com.termux.app.terminal.inappkeyboard
            .TermuxInAppKeyboard.HideReason.KEYBOARD_ACTION);
    }

    /**
     * Re-read the keyboard-data probe and refresh the display window's empty state from it. Only a
     * running-state change reaches {@link com.termux.app.x11.X11PaneFrame#applyRunning} on its
     * own, so a package installed in a shell while the user was elsewhere — on another place, or
     * with the app backgrounded — left the message stale until the display was next started or
     * stopped. Called on {@link #onResume} and whenever the wall settles on the place.
     */
    private void refreshDisplayEmptyStateReadiness() {
        com.termux.app.x11.X11PaneFrame display = mPaneWallController == null
            ? null : mPaneWallController.displayWindow();
        if (display != null) display.refreshEmptyStateReadiness();
    }

    /** The shell the display window's install button started, until it ends. */
    @Nullable private TerminalSession mKeyboardDataInstallShell;

    /**
     * The display window's install button: {@code command} in a new window of the current session,
     * with the wall turned to the terminal to show it, the route a widget's "open in terminal"
     * takes. Compatibility mode has no windows, so there it is a plain session made current.
     */
    private void runKeyboardDataInstall(@NonNull java.util.List<String> command) {
        String title = getString(R.string.termux_x11_install_keyboard_data);
        TerminalSession shell = openCommandWindow(command, null, title, true);
        if (shell == null && !isSplitPanesEnabled()) {
            shell = createCommandShell(command, null, title, false);
            if (shell != null) getTermuxTerminalSessionClient().setCurrentSession(shell);
        }
        if (shell == null) {
            // The one refusal the user can act on; the others pass once the service is up.
            if (mTermuxService != null && mTermuxService.getTermuxSessionsSize()
                    >= com.termux.app.terminal.TermuxTerminalSessionActivityClient.MAX_SESSIONS) {
                mSheets.showTerminalNotice(getString(R.string.title_max_terminals_reached) + " — "
                    + getString(R.string.msg_max_terminals_reached), AppNoticeItem.Hold.REFUSAL);
            }
            return;
        }
        mKeyboardDataInstallShell = shell;
        if (mPaneWallController != null) {
            mPaneWallController.goTo(com.termux.app.page.PageKind.TERMINAL, isVisible());
        }
    }

    /**
     * The install's shell ended. The user never left the activity, so nothing else re-reads the
     * keyboard-data probe: the display window's empty state is refreshed here. When the install
     * worked and its window is the one on screen, the wall goes back to the display window, which
     * now offers Start. A failed install does not end on its own (its script keeps the window
     * open in the user's shell), so this runs for it only once they exit that shell.
     */
    private void onKeyboardDataInstallFinished(@NonNull TerminalSession session) {
        if (session != mKeyboardDataInstallShell) return;
        mKeyboardDataInstallShell = null;
        refreshDisplayEmptyStateReadiness();
        if (session.getExitStatus() != 0 || session != getCurrentSession()) return;
        if (mPaneWallController == null || !com.termux.app.x11.X11CliInstaller.hasKeyboardData()
            || currentWallPlace() != com.termux.app.page.PageKind.TERMINAL) {
            return;
        }
        // The window went when the wall left it for the install; it comes back offering Start.
        openDisplayWindow(false);
    }

    /**
     * The settle's part of the Display: the keys' row follows the place, and a display view kept
     * attached through a slide off the Display pages lets go now. Attaching and letting go
     * otherwise belong to the Display pages' front and leave ({@link com.termux.app.x11.DisplayPages}).
     */
    private void syncDisplayAttachment(@NonNull com.termux.app.page.PageKind page) {
        mSettledWallPage = page;
        refreshExtraKeySet(true);
        if (page != com.termux.app.page.PageKind.DISPLAY) mDisplayPages.detachIfOwed();
    }

    /**
     * The keys go back to the active terminal pane, quietly, once: no retry. A key that then
     * finds nothing holding the keys is delivered by the per-key safety net, which asks again.
     * Nothing to do while an external text field takes input. True when the pane holds them.
     */
    private boolean returnKeysToTerminal() {
        if (mInAppKeyboard != null && mInAppKeyboard.isExternalTextInputActive()) return false;
        return handKeysToActivePane();
    }

    /** One quiet focus request on the active pane; true when the pane really holds the keys. */
    private boolean handKeysToActivePane() {
        return com.termux.app.terminal.PaneKeys.handTo(getTerminalView(), true);
    }

    /** The display's view holds the keys on its own window at rest, where they are X's. */
    private boolean isDisplayKeyHolderShowing() {
        View focus = getCurrentFocus();
        return focus instanceof com.termux.x11.LorieView && isDisplayWindowInFront() && focus.isShown();
    }

    /**
     * The safety net under the display's focus hand-back: a key that arrives while no view holds
     * the keys, or while a display view whose window has gone does, is delivered to what is in
     * front — the active terminal's key handler, which offers it to the palette and the other
     * overlays first, or those overlays alone — and the keys are handed back for the next one.
     * Typing never dies with the focus. See {@link com.termux.app.x11.DisplayViewFocus#routeFor}.
     */
    @Override
    public boolean dispatchKeyEvent(KeyEvent event) {
        // A bare Super opens the bar's search, a second one puts it away (#435). The press and the
        // release go together: both are taken here, or (a Linux window or the Display, which may
        // see Super itself) both are forwarded, never one of them alone.
        if (mTilingDesktop != null && mControlBar != null) {
            int code = event.getKeyCode();
            boolean tap = mSuperTap.onKey(code, event.getAction(), event.getRepeatCount());
            boolean meta = code == KeyEvent.KEYCODE_META_LEFT || code == KeyEvent.KEYCODE_META_RIGHT;
            if (tap) mSuperTapHandler.post(() -> barSearch().toggle());
            if (meta) {
                com.termux.app.tiling.WindowKind front = mTilingDesktop.frontKind();
                boolean toGuest = front == com.termux.app.tiling.WindowKind.LINUX_APP
                    || front == com.termux.app.tiling.WindowKind.DISPLAY;
                if (!toGuest) return true;
            }
        }
        if (offerLeaderGate(event)) return true;
        // Navigation mode (#433): no window takes a key; Back and a layer over the page go on.
        if (mTilingDesktop != null && com.termux.app.tiling.navigation.NavigationKeys.swallows(
            mTilingDesktop.isNavigating(), event.isSystem(), mOverlays.anyOpen())) return true;
        if (routeKeyNobodyHolds(event)) {
            // DIAG(back-path): revert before merge.
            if (MotionLog.enabled && event.getKeyCode() == KeyEvent.KEYCODE_BACK)
                MotionLog.log("back-key", "action=" + event.getAction() + " took=router");
            return true;
        }
        boolean took = super.dispatchKeyEvent(event);
        // DIAG(back-path): who held the focus and whether the view tree spent Back; revert before merge.
        if (MotionLog.enabled && event.getKeyCode() == KeyEvent.KEYCODE_BACK) {
            View focus = getCurrentFocus();
            MotionLog.log("back-key", "action=" + event.getAction() + " took=" + took
                + " focus=" + (focus == null ? "none" : focus.getClass().getSimpleName()
                + (focus.isShown() ? "" : "(hidden)")) + " front=" + (mPages == null ? "?"
                : String.valueOf(mPages.committedKind())));
        }
        return took;
    }

    private final com.termux.app.leader.LeaderGate mLeaderGate = new com.termux.app.leader.LeaderGate();

    /**
     * The leader gate for a hardware key, the one owner of the leader's chords under Terl (the table, so a user's unmap or remap counts): every screen
     * asks the binding table first, so a bound leader chord runs wherever the keys are going (a
     * terminal, Home, a Linux window, the Display, a text field) and an unbound one goes on to
     * them unchanged. Off with the Terl switch: v1's per-screen handling stays as it is.
     */
    private boolean offerLeaderGate(@NonNull KeyEvent event) {
        if (com.termux.app.terminal.TerminalKeyBindingResolver.swallowsUnboundLeaderChords()
            || mTermuxTerminalViewClient == null) return false;
        mTermuxTerminalViewClient.trackLeaderHold(event);
        boolean down = event.getAction() == KeyEvent.ACTION_DOWN;
        if (mLeaderGate.swallows(down, event.getKeyCode(), event.getRepeatCount())) return true;
        if (!down || event.getRepeatCount() > 0) return false;
        boolean bound = mTermuxTerminalViewClient.consumeLauncherChord(event);
        if (com.termux.app.leader.LeaderGate.decide(true, false, bound)
            != com.termux.app.leader.LeaderGate.Verdict.RUN) return false;
        mLeaderGate.ran(event.getKeyCode());
        return true;
    }

    private boolean routeKeyNobodyHolds(@NonNull KeyEvent event) {
        View focus = getCurrentFocus();
        TerminalView terminal = getTerminalView();
        boolean terminalShown = terminal != null && terminal.isShown();
        com.termux.app.x11.DisplayViewFocus.Holder holder = focus == null
            ? com.termux.app.x11.DisplayViewFocus.Holder.NONE
            : focus instanceof TerminalView
                && (!focus.isShown() || ((TerminalView) focus).mEmulator == null)
            ? com.termux.app.x11.DisplayViewFocus.Holder.TERMINAL_HIDDEN
            : !(focus instanceof com.termux.x11.LorieView)
            ? com.termux.app.x11.DisplayViewFocus.Holder.OTHER
            : isDisplayKeyHolderShowing()
            ? com.termux.app.x11.DisplayViewFocus.Holder.DISPLAY_SHOWING
            : com.termux.app.x11.DisplayViewFocus.Holder.DISPLAY_AWAY;
        com.termux.app.x11.DisplayViewFocus.Route route =
            com.termux.app.x11.DisplayViewFocus.routeFor(holder, event.getKeyCode(),
                terminal != null && terminal.mEmulator != null, terminalShown,
                isAppDrawerOpen() || mSheets.isCommandPaletteOpen());
        if (route == com.termux.app.x11.DisplayViewFocus.Route.PASS) return false;
        if (event.getAction() == KeyEvent.ACTION_DOWN && event.getRepeatCount() == 0) {
            returnKeysToTerminal();
            // Landed: the ordinary path delivers this key too.
            if (route == com.termux.app.x11.DisplayViewFocus.Route.TERMINAL
                && com.termux.app.x11.DisplayViewFocus.holdsKeys(terminal)) return false;
        }
        if (route == com.termux.app.x11.DisplayViewFocus.Route.TERMINAL)
            return terminal.dispatchKeyEvent(event);
        // No terminal to type into: the overlays, in the order a terminal would offer them.
        int keyCode = event.getKeyCode();
        if (event.getAction() == KeyEvent.ACTION_UP) return mOverlays.consumeKeyUp(keyCode);
        if (event.getAction() != KeyEvent.ACTION_DOWN) return false;
        if (mOverlays.consumeKeyDown(keyCode, event)) return true;
        int codePoint = event.getUnicodeChar(event.getMetaState());
        return codePoint > 0 && mOverlays.consumeCodePoint(codePoint, event.isCtrlPressed());
    }

    /**
     * {@code DISPLAY} for shells started from now on: set while a display server runs and the
     * setting is on (the default), cleared otherwise. Nothing already running is touched, and
     * nothing is written to disk. Whether a server runs is
     * the process's ({@link com.termux.app.x11.X11DisplayServerState}), not this activity's
     * controller's: a relaunched activity, before or without its controller on the server, must
     * not read as the display having stopped. Only the setting is this activity's to say.
     */
    private void syncDisplayEnvironment() {
        com.termux.app.x11.X11DisplayServerState.setDisplayEnvWanted(
            mPreferences != null && mPreferences.isX11SetDisplayEnvEnabled());
        // Wayland Display listens on its socket while it is the chosen display.
        com.termux.app.wayland.WaylandAppRunner.shared(this).setWaylandChosen(
            com.termux.app.wayland.LinuxDisplayBackend.current(this)
                == com.termux.app.wayland.LinuxDisplayBackend.WAYLAND);
    }

    /**
     * Re-list the Linux apps — the prefix's and every container's — in the drawer when their
     * desktop files changed or a distro was installed or removed; forced, whatever the files say.
     */
    private void refreshLinuxApps(boolean force) {
        if (!com.termux.app.x11.X11ServerSupport.isAvailable(TermuxActivity.this)) return;
        long signature = com.termux.app.x11.LinuxAppCatalog.signature(
            com.termux.app.x11.LinuxAppCatalog.roots());
        if (!force && signature == mLinuxAppsSignature) return;
        mLinuxAppsSignature = signature;
        // Apps came or went, so a class that resolved to nothing may resolve now.
        if (mDisplayWindowIcons != null) mDisplayWindowIcons.clear();
        // The Display pages' cards are read again with the catalog (W2).
        mDisplayPageBinding.onCatalogChanged();
        // The same two steps, in the same order, as a package change takes through
        // refreshSuggestionBarFromPackageState: kick the provider's background rebuild first, then
        // tell the drawer. The provider parks warm-up callbacks while a rebuild is in flight, so
        // the drawer's re-registration fires once against the finished snapshot.
        //
        // Telling it is the whole point. refreshAsync hands its result to the callback it was
        // given and to nothing else — there is no listener list — so kicking it with a null
        // callback, as this did, left a newly installed app sitting in the provider with nothing
        // to put it on screen: the drawer had already read the old catalogue in bind() on the way
        // open. It turned up on the next open, or when `termux-reload-settings` came through the
        // package path, which is what made this look like a reload was required.
        if (isLauncherCatalogEnabled() && mSuggestionBarView != null) {
            mSuggestionBarView.refreshAllApps(null);
        } else {
            // The drawer's catalogue is not the dock's: it refreshes even with the suggestion bar
            // switched off or its view not built yet.
            com.termux.app.launcher.data.LauncherAppDataProvider.getInstance(this).refreshAsync(null, null);
        }
        if (mSheets.appDrawerControllerIfBuilt() != null) {
            mSheets.appDrawerControllerIfBuilt().onAppCatalogChanged();
        }
    }

    /** Runs Linux app {@code entry}; {@code newWindow} starts another copy rather than going to an open window. */
    private boolean runLinuxEntry(@NonNull com.termux.app.launcher.model.LauncherAppEntry entry,
                                  boolean newWindow) {
        if (mLinuxApps == null) return false;
        com.termux.app.x11.LinuxAppCatalog.LinuxApp app = resolveLinuxAppForLaunch(entry);
        if (app == null) {
            showToast(getString(R.string.termux_x11_app_gone), true);
            refreshLinuxApps(true);
            return false;
        }
        // Wayland Display, when Settings chooses it: the app opens in its own window on the
        // Linux windows screen, so no Display page is routed or added.
        if (mLinuxApps.runUnderWayland(app, newWindow)) {
            closeAppDrawerForLinuxLaunch();
            return true;
        }
        if (mTilingDesktop != null) {
            // The tiling desktop (#419) has no Display pages: the app opens on the display,
            // whose window the runner's show-display step opens.
            mLinuxApps.run(app, newWindow);
            return true;
        }
        // A3c: the app opens on its Display page: the one bound to it, else the first unbound
        // one, else a new temporary page after the current one, which goes with its display.
        // The runner's show-display step shows that page; the landing there leaves the app to
        // the runner.
        com.termux.app.wall.WallPages.Route route =
            wallPages().routeLinuxApp(app.id, linuxRouteFromPageId());
        int routedPage = route.pageId;
        if (route.needsNewPage()) {
            com.termux.app.wall.WallPages.Result added =
                wallPagesStore().edit(route::addTo);
            routedPage = added.ok() && added.page != null ? added.page.id : -1;
            mTemporaryDisplaySawApp = false;
            mTemporaryDisplayStartedByLaunch = !mDisplayServer.isRunning();
        }
        mDisplayLanding.routeTo(routedPage);
        mAddedLinuxPage = route.needsNewPage() ? routedPage : -1;
        mLinuxApps.run(app, newWindow);
        return true;
    }

    private void closeAppDrawerForLinuxLaunch() { mSheets.closeAppDrawerForLinuxLaunch(); }

    /**
     * The launcher's own drawer entries (ADR 0008): Terminal goes to the Terminal, Display opens
     * the bare display. Terminal is pinned to the dock the first time a build with it runs.
     */
    private void installLauncherEntryRunner() {
        mEntryRunnerHook = new com.termux.app.launcher.LauncherAppLauncher.EntryRunner() {
            @Override public boolean open(@NonNull String entryId) {
                if (com.termux.app.launcher.LauncherEntries.DISPLAY.equals(entryId)) {
                    if (!isX11DisplayEnabled()) return false;
                    openDisplayWindow(true);
                    return true;
                }
                if (com.termux.app.launcher.LauncherEntries.ASSISTANT.equals(entryId)) {
                    openAssistant();
                    return true;
                }
                if (!com.termux.app.launcher.LauncherEntries.TERMINAL.equals(entryId)) return false;
                // Under Terl the entry opens a terminal window in the stack, wherever it is tapped.
                if (openTerlTerminal()) return true;
                // Into an empty Terminal from Home, the tap launches a terminal: a Home float.
                if (launchesAsHomeFloat(com.termux.app.terminal.HomeFloatPolicy.Launch.ENTRY_TAP))
                    return openHomeFloatHere();
                return openTerminalEntry(false);
            }
            @Override public boolean openAlternate(@NonNull String entryId) {
                return com.termux.app.launcher.LauncherEntries.TERMINAL.equals(entryId)
                    && openTerminalEntry(true);
            }
            @Override public boolean openHomeFloat(@NonNull String entryId) {
                return com.termux.app.launcher.LauncherEntries.TERMINAL.equals(entryId)
                    && openHomeFloatHere();
            }
        };
        com.termux.app.launcher.LauncherAppLauncher.setEntryRunner(mEntryRunnerHook);
        if (mPreferences != null) {
            com.termux.app.launcher.data.TerminalEntryPin.pinOnce(
                mPreferences.getSharedPreferences(),
                com.termux.app.launcher.data.LauncherConfigRepository.getInstance(this));
        }
    }

    /**
     * Under Terl every door to a terminal (the Terminal entry wherever it is pinned or listed, a
     * new window, the New session shortcut) opens a terminal window in the stack and goes there:
     * from Home in the waiting Workspace, on a Workspace after the focused window. False with
     * the switch off, for v1's own door.
     */
    private boolean openTerlTerminal() {
        if (mTilingDesktop == null) return false;
        closeAppDrawerForLinuxLaunch();
        mTilingDesktop.newTerminalHere();
        return true;
    }

    /**
     * The Terminal entry: the Terminal at the window last shown, or a new window when there is
     * none or one was asked for ({@code newWindow}, the long press). A new window lands right
     * after the current one.
     */
    private boolean openTerminalEntry(boolean newWindow) {
        if (openTerlTerminal()) return true;
        if (mPaneWallController == null) return false;
        closeAppDrawerForLinuxLaunch();
        if (!isTerminalOnRow()) {
            // An empty Terminal: one fresh shell, its session's only window (any mode).
            if (getTermuxTerminalSessionClient() != null)
                getTermuxTerminalSessionClient().addNewSession(false, null);
        } else if (newWindow) {
            createRowWindow();
        } else {
            // The Terminal entry shows a terminal, not the display window in front of one.
            bringTerminalWindowInFront();
        }
        mPaneWallController.refreshPages();
        mPaneWallController.goTo(com.termux.app.page.PageKind.TERMINAL, isVisible());
        return true;
    }

    /**
     * The float layer Home floats are drawn in, pinned to the Home pages; built once the pane
     * controller and the Home view both exist.
     */
    private void attachHomeFloatLayer() {
        if (mPaneController == null || mPaneController.homeFloatLayer() != null) return;
        View view = findViewById(R.id.widget_pane);
        if (!(view instanceof com.termux.app.launcher.widget.WidgetPaneView)) return;
        com.termux.app.terminal.HomeFloatLayer layer =
            new com.termux.app.terminal.HomeFloatLayer(this);
        // A minimised float folds into its chip in the bar (#91), on both halves: no row of
        // chips of its own above the dock.
        ((com.termux.app.launcher.widget.WidgetPaneView) view).setPagePinnedLayer(layer);
        mPaneController.setHomeFloatLayer(layer);
        syncHomeFloatObstructions();
    }

    /**
     * Terminal on Home (its long-press menu, the Terminal entry's New float here and its tap into
     * an empty Terminal, the palette's Open terminal here, and any new terminal or window a
     * keybind or the local API asks for while Home is in front): a Home float on the Home page in
     * view, born a window inside the room between the status bar and the dock, focused, with the
     * keyboard overlay up and the float ending above it. It is a window of the current
     * session but not of the row: the Terminal neither gains it nor is needed for it.
     */
    boolean openHomeFloatHere() {
        return openHomeFloatHere(null);
    }

    /** {@link #openHomeFloatHere()} with its shell named {@code sessionName} (null: unnamed). */
    boolean openHomeFloatHere(@Nullable String sessionName) {
        // Under Terl it is a Float of the stack's place in front (#421), never a v1 pane.
        if (mTilingDesktop != null) {
            closeAppDrawerForLinuxLaunch();
            mTilingDesktop.newFloatHere();
            return true;
        }
        if (!canOpenHomeFloat()) return false;
        closeAppDrawerForLinuxLaunch();
        TerminalSession current = getCurrentSession();
        TerminalSession shell = createShellForCwd(current != null ? current.getCwd() : null,
            sessionName);
        if (shell == null) return false;
        int page = mWidgetPaneController == null ? 0 : mWidgetPaneController.homePageIndex();
        if (mPaneWallController.currentPage() != com.termux.app.page.PageKind.HOME)
            mPaneWallController.goTo(com.termux.app.page.PageKind.HOME, isVisible());
        syncHomeFloatObstructions();
        mSheets.runWithoutNotices(() -> mPaneController.openHomeFloat(shell, page));
        if (mInAppKeyboard != null && !mInAppKeyboard.isVisible()) {
            mInAppKeyboard.show(com.termux.app.terminal.inappkeyboard.TermuxInAppKeyboard
                .ShowReason.TEXT_ENTRY);
        }
        return true;
    }

    /** Whether Home can carry a Home float now: split panes on, the wall and its float layer up. */
    private boolean canOpenHomeFloat() {
        if (mPaneController == null || mPaneWallController == null || !isSplitPanesEnabled())
            return false;
        attachHomeFloatLayer();
        return mPaneController.homeFloatLayer() != null;
    }

    /**
     * Whether a terminal asked for by {@code launch} opens as a Home float on the page in view
     * rather than in the Terminal's row ({@link com.termux.app.terminal.HomeFloatPolicy#launchesAsFloat}).
     */
    private boolean launchesAsHomeFloat(@NonNull com.termux.app.terminal.HomeFloatPolicy.Launch launch) {
        return com.termux.app.terminal.HomeFloatPolicy.launchesAsFloat(launch,
            currentWallPage() == com.termux.app.page.PageKind.HOME, isTerminalOnRow(),
            canOpenHomeFloat());
    }

    /** Home's long-press sheet, built on the first long press and laid over everything. */
    /** Where the long press that opened the sheet rested, on screen; Edit pages' wheels hang there. */
    private float mHomeActionsRawX, mHomeActionsRawY;

    /**
     * Puts an app on Home as an icon, from the app menu's Add to Home or the sheet's Add an app:
     * the page in front when it has room, else the first that has, else a new page. A toast names
     * the page, since it may not be the one on screen.
     */
    private void addAppToHome(@NonNull com.termux.app.launcher.model.LauncherAppEntry entry) {
        if (mWidgetPaneController == null) return;
        int page = mWidgetPaneController.addApp(entry);
        if (page < 0) {
            Logger.logWarn(LOG_TAG, "Add to Home failed for " + entry.appRef.stableId());
            return;
        }
        com.termux.app.notice.AppNotice.confirm(this, R.drawable.ic_rl_home,
            getString(R.string.home_app_added, page + 1));
    }

    /**
     * Settings › Home's rows that shape the Home pages ({@link
     * com.termux.app.launcher.home.HomeSettings}), pushed into the pane as the launcher comes to
     * the front: Settings is another activity, so a change there is always followed by this.
     */
    private void applyHomeSettings() {
        // The dock's badge look is Settings › Notifications', pushed here for the same reason.
        if (mSuggestionBarView != null) {
            // Terl has dots only; v1 keeps the style Settings chose.
            mSuggestionBarView.setNotificationBadgeStyle(
                com.termux.app.launcher.notifications.NotificationDots.styleFor(isTerlDesktopOn(),
                    com.termux.app.launcher.home.HomeSettings.badgeStyle(this)));
        }
        // Page transition turns the wall's pages too: the seam, and the Terminal's windows.
        if (mPaneWallController != null && mPaneWallController.wall() != null) {
            mPaneWallController.wall().setPageTransition(
                com.termux.app.launcher.home.HomeSettings.pageTransition(this));
        }
        if (mWidgetPaneController == null) return;
        mWidgetPaneController.setPageMotion(
            com.termux.app.launcher.home.HomeSettings.pageTransition(this),
            com.termux.app.AnimationSpeed.multiplier(this));
        mWidgetPaneController.setIconStyle(com.termux.app.launcher.home.HomeSettings.iconStyle(this));
        // Under Terl the glyph row is Terl's own home.page_dots (off by default), not v1's choice.
        mWidgetPaneController.setPageIndicator(com.termux.app.wall.TerlWall.indicator(
            com.termux.app.launcher.home.HomeSettings.pageIndicator(this), mTilingDesktop != null,
            mPreferences != null && mPreferences.isTerlHomePageDotsShown()));
        syncHomeBandLook();
        mWidgetPaneController.setLayoutLocked(
            com.termux.app.launcher.home.HomeSettings.isLayoutLocked(this));
        mWidgetPaneController.setFolderStyle(
            com.termux.app.launcher.home.HomeSettings.folderDensity(this));
        mWidgetPaneController.setSwipeUpAction(com.termux.app.launcher.home.HomeSettings
            .gestureAction(this, com.termux.app.launcher.home.HomeGestures.Gesture.SWIPE_UP));
        mWidgetPaneController.setExtraGestures(
            com.termux.app.launcher.home.HomeGestures.watched(
                com.termux.app.launcher.home.HomeSettings.gestureAction(this,
                    com.termux.app.launcher.home.HomeGestures.Gesture.DOUBLE_TAP)),
            com.termux.app.launcher.home.HomeGestures.watched(
                com.termux.app.launcher.home.HomeSettings.gestureAction(this,
                    com.termux.app.launcher.home.HomeGestures.Gesture.TWO_FINGER_UP))
                // The tiling desktop's way down from Home (#418).
                || mTilingDesktop != null
                || com.termux.app.launcher.home.HomeGestures.watched(
                com.termux.app.launcher.home.HomeSettings.gestureAction(this,
                    com.termux.app.launcher.home.HomeGestures.Gesture.TWO_FINGER_DOWN)));
    }

    // ---- Start in: which page is Home (StartInPolicy) ------------------------------------------

    /**
     * A cold start landed for Start in = Display: the display window comes in front once its
     * display is up, which Start with the launcher brings about after the wall has landed.
     */
    private boolean mStartOnDisplayPending;
    /**
     * Start in follows the display's start: switched off in Settings while Display is Start in,
     * Start in falls back at once, so Settings and Edit pages never show a Display that will not
     * start. Held here, as the store keeps its listeners weakly.
     */
    @Nullable private android.content.SharedPreferences.OnSharedPreferenceChangeListener
        mStartInListener;

    /** The wall's pages and its home (ADR 0015): the one source of Start in and the Home page. */
    private com.termux.app.wall.WallPagesStore mWallPagesStore;
    /** The wall's way into Home; it also keeps the Home run the wall last bound (ADR 0015, A2a). */
    private final com.termux.app.launcher.home.HomeWallSeam mHomeSeam =
        new com.termux.app.launcher.home.HomeWallSeam(() -> mWidgetPaneController,
            () -> TermuxActivity.this.wallPages(),
            () -> { refreshShownPageIds(); return mShownHomePageIds; });
    @Nullable private com.termux.app.wall.WallPagesStore.Listener mWallPagesListener;
    /** Prunes and drops page looks; no other work (readers build their own PageLook). */
    @Nullable private com.termux.app.look.PageLook mPageLookPruner;

    @NonNull
    private com.termux.app.wall.WallPages wallPages() {
        return wallPagesStore().current();
    }

    /** The store, opened on first use when something asks before onCreate built it. */
    @NonNull
    private com.termux.app.wall.WallPagesStore wallPagesStore() {
        if (mWallPagesStore == null) {
            mWallPagesStore = com.termux.app.wall.WallPagesStore.open(this);
        }
        return mWallPagesStore;
    }

    /**
     * The widget repository's Home pages are the wall's Home pages: it keys what stands on a page
     * by the page's id and asks this owner to add, remove or reorder them. The store tells it
     * back when the pages change by another route ({@link #mWallPagesListener}).
     */
    @NonNull
    private com.termux.app.launcher.widget.LauncherWidgetRepository.HomePageOwner widgetPageOwner() {
        return new com.termux.app.launcher.widget.LauncherWidgetRepository.HomePageOwner() {
            @NonNull @Override public java.util.List<Integer> homePageIds() {
                return wallPages().homePageIdsForRepository();
            }
            @NonNull @Override public java.util.List<Integer> addHomePages(int count) {
                java.util.List<Integer> before = homePageIds();
                wallPagesStore().transform(pages -> pages.withHomeCount(before.size() + count));
                java.util.List<Integer> added = homePageIds();
                added.removeAll(before);
                return added;
            }
            @Override public void removeHomePages(@NonNull java.util.Collection<Integer> ids) {
                java.util.List<Integer> held = homePageIds();
                int[] mapping = new int[held.size()];
                int next = 0;
                for (int i = 0; i < mapping.length; i++) {
                    mapping[i] = ids.contains(held.get(i)) ? -1 : next++;
                }
                wallPagesStore().transform(pages -> pages.withHomeMapping(mapping));
            }
            @Override public void reorderHomePages(@NonNull java.util.List<Integer> order) {
                java.util.List<Integer> held = homePageIds();
                if (held.size() != order.size() || !held.containsAll(order)) return;
                int[] mapping = new int[held.size()];
                for (int i = 0; i < mapping.length; i++) mapping[i] = order.indexOf(held.get(i));
                wallPagesStore().transform(pages -> pages.withHomeMapping(mapping));
            }
        };
    }

    /** Runs an edit of the wall's pages through the store (saved, announced). */
    private void editWallPages(@NonNull com.termux.app.wall.WallPagesStore.Edit edit) {
        wallPagesStore().edit(edit);
    }

    /** Whether the display starts with the launcher here: switched on, on a build that has one. */
    private boolean displayStartsWithLauncher() {
        return isX11DisplayEnabled() && mPreferences.isX11DisplayAutostartEnabled();
    }

    /** Start in as it stands, the one value the Home marker and the start-up read. */
    @NonNull
    private String effectiveStartIn() {
        return com.termux.app.wall.StartInPolicy.effective(wallPages().startIn(),
            displayStartsWithLauncher(), !rowWindows().isEmpty());
    }

    /** Makes home what Start in {@code startIn} names, in the wall's pages. */
    private void chooseWallStartIn(@NonNull String startIn) {
        editWallPages(pages -> pages.chooseStartIn(startIn));
    }

    /** Stores Start in as it stands when the stored value no longer holds: an unstartable Display. */
    private void settleStartIn() {
        if (mPreferences == null) return;
        String now = effectiveStartIn();
        if (!now.equals(wallPages().startIn())) chooseWallStartIn(now);
    }

    /** Listens for the display's start and Start in, for {@link #settleStartIn} and the marker. */
    private void watchStartIn() {
        android.content.SharedPreferences store =
            mPreferences == null ? null : mPreferences.getSharedPreferences();
        if (store == null || mStartInListener != null) return;
        mStartInListener = (changed, key) -> {
            if (TermuxPreferenceConstants.TERMUX_APP.KEY_USE_AS.equals(key)) {
                applyUseAs();
                return;
            }
            if (TermuxPreferenceConstants.TERMUX_APP.KEY_X11_DISPLAY_AUTOSTART.equals(key)) {
                settleStartIn();
            } else if (!TermuxPreferenceConstants.TERMUX_APP.KEY_LAUNCHER_START_IN.equals(key)) {
                return;
            }
        };
        com.termux.shared.settings.preferences.PreferenceDraft.listen(store, mStartInListener);
        // Home moved (Settings, Overview, another holder of the store): the marker follows.
        mWallPagesListener = new com.termux.app.wall.WallPagesStore.Listener() {
            /** The page kinds of the last page list this listener saw: the wall keys it put on the row. */
            private java.util.List<com.termux.app.page.PageKind> mKeyKinds = availableWallPages();

            @Override public void onChanged(@NonNull com.termux.app.wall.WallPages pages) {
                // The widget repository lines its pages up with the Home pages by id.
                if (mWidgetHostController != null) mWidgetHostController.repository().onHomePagesChanged();
                if (mPaneController != null) mPaneController.onHomePagesChanged();
                // The wall lays out in the pages' order: a moved page moves on the wall.
                if (mPaneWallController != null) mPaneWallController.refreshPages();
                // A Display or Home page added or removed puts its key on the row or takes it off.
                java.util.List<com.termux.app.page.PageKind> kinds =
                    com.termux.app.wall.WallKeys.kinds(pages, useAs());
                if (!kinds.equals(mKeyKinds)) {
                    mKeyKinds = kinds;
                    onWallPlacesChanged();
                }
                // A removed Display page's picture went with refreshPages (A3c2).
                mDisplayPageBinding.applyStill();
            }
            @Override public void onRemoved(@NonNull com.termux.app.wall.WallPages.Page page) {
                // The removal is final: the page's own look goes with it, and what stood on it.
                if (mPageLookPruner != null) mPageLookPruner.dropPage(page.id);
                if (mPaneController != null && page.kind == com.termux.app.page.PageKind.HOME) {
                    mPaneController.homePageRemoved(page.id);
                }
                if (mWidgetHostController != null && page.kind == com.termux.app.page.PageKind.HOME) {
                    mWidgetHostController.repository().pageRemoved(page.id);
                }
            }
        };
        sweepTemporaryDisplayPages();
        wallPagesStore().addListener(mWallPagesListener);
        // Once at start: page looks whose page is not on the wall or kept aside are dead keys.
        mPageLookPruner = new com.termux.app.look.PageLook(
            new com.termux.app.look.PrefsLookStore(store));
        java.util.Set<Integer> liveIds = new java.util.HashSet<>();
        com.termux.app.wall.WallPages held = wallPages();
        for (com.termux.app.wall.WallPages.Page p : held.allPages()) liveIds.add(p.id);
        for (com.termux.app.wall.WallPages.Page p : held.detached()) liveIds.add(p.id);
        mPageLookPruner.pruneUnknown(liveIds);
    }

    /**
     * Use as changed (Settings, or the welcome sheet's first page): the wall's row is read again,
     * so choosing Terminal only while on the Home page moves the wall to the Terminal, and Edit
     * pages, which is Home's, goes down.
     */
    private void applyUseAs() {
        if (mTilingDesktop != null) mTilingDesktop.setHasHome(useAs().showsHomePage());
        if (mPaneWallController == null) return;
        com.termux.app.wall.UseAs useAs = useAs();
        boolean leaves = useAs.leaves(mPaneWallController.currentPage());
        mPaneWallController.refreshPages();
        if (leaves) mPaneWallController.goToTerminal(false);
        // Terl's Workspaces stand over the wall: with Home back, the wall under them is on Home,
        // not on the Terminal page it was left on, so no Home controls show over that page.
        else if (mTilingDesktop != null && useAs.showsHomePage()) mPaneWallController.goToHomePageOne(false);
    }

    private void unwatchStartIn() {
        android.content.SharedPreferences store =
            mPreferences == null ? null : mPreferences.getSharedPreferences();
        if (store != null && mStartInListener != null) {
            com.termux.shared.settings.preferences.PreferenceDraft.unlisten(store, mStartInListener);
        }
        mStartInListener = null;
        if (mWallPagesListener != null && mWallPagesStore != null) {
            mWallPagesStore.removeListener(mWallPagesListener);
        }
        mWallPagesListener = null;
        if (mPageLookPruner != null) mPageLookPruner.close();
        mPageLookPruner = null;
        if (mGroundLook != null) mGroundLook.close();
        mGroundLook = null;
    }

    /**
     * Edit pages' Rename: a name field with the keyboard up and the field focused, the system
     * IME announced first so its insets are taken.
     */
    private void promptPageRename(@Nullable String current,
                                  @NonNull java.util.function.Consumer<String> done) {
        float density = getResources().getDisplayMetrics().density;
        android.widget.EditText input = new android.widget.EditText(this);
        input.setSingleLine();
        input.setImeOptions(android.view.inputmethod.EditorInfo.IME_ACTION_DONE);
        if (current != null) {
            input.setText(current);
            input.setSelection(current.length());
        }
        android.widget.FrameLayout box = new android.widget.FrameLayout(this);
        int side = Math.round(24 * density);
        box.setPadding(side, Math.round(8 * density), side, Math.round(16 * density));
        box.addView(input);
        androidx.appcompat.app.AlertDialog dialog =
            new com.google.android.material.dialog.MaterialAlertDialogBuilder(this)
                .setTitle(R.string.page_overview_rename_title)
                .setView(box)
                .setPositiveButton(R.string.page_overview_rename_confirm,
                    (d, which) -> done.accept(input.getText().toString()))
                .setNegativeButton(android.R.string.cancel, null)
                .create();
        input.setOnEditorActionListener((v, action, event) -> {
            done.accept(input.getText().toString());
            dialog.dismiss();
            return true;
        });
        if (dialog.getWindow() != null) {
            dialog.getWindow().setSoftInputMode(
                android.view.WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_VISIBLE);
        }
        onSystemImeRequested();
        dialog.show();
        input.requestFocus();
    }

    /** Every terminal window open, across sessions: what removing the Terminal page closes. */
    private int terminalWindowTotal() {
        int n = 0;
        for (WSession ws : mWSessions) n += ws.windows.size();
        return n;
    }

    /** The Terminal page's id as the look's per-page values know it (set at start, and here). */
    private void noteTerminalPageId(int id) {
        if (mPreferences != null) {
            mPreferences.getSharedPreferences().edit().putInt(
                com.termux.shared.termux.settings.preferences.PageLookKeys.KEY_TERMINAL_PAGE_ID,
                id).apply();
        }
        TermuxAppSharedPreferences.setTerminalPageId(id);
    }

    /**
     * The doors Edit pages had (a pinch on Home, Home's sheet, Settings) open Overview (#354);
     * Settings' Back returns to Settings › Home. Refused, as Edit pages was, while the layout is
     * locked. They edit the Home pages, so they open the wall's Overview also under the Terl
     * switch, whose own Overview (the stack's, #430) has no page controls.
     */
    private void openOverviewDoor(boolean fromSettings) {
        if (mWidgetPaneController == null || mPaneWallController == null) return;
        if (mWidgetPaneController.refusedWhileLocked(
                com.termux.app.launcher.home.HomeLayoutLock.Edit.EDIT_PAGES)) return;
        com.termux.app.overview.OverviewController overview = overview();
        if (fromSettings) {
            overview.setBackReturn(() -> startActivity(
                com.termux.app.activities.SettingsActivity.createFragmentIntent(
                    TermuxActivity.this,
                    com.termux.app.fragments.settings.termux.HomePreferencesFragment.class,
                    R.string.settings_section_home)));
        }
        overview.openWall();
    }

    /** The Home pages as the workspace file's v4 float positions are read against them. */
    @NonNull
    private com.termux.app.terminal.TerminalWorkspace.HomePages homePagesForWorkspace() {
        com.termux.app.wall.WallPages pages = wallPages();
        return new com.termux.app.terminal.TerminalWorkspace.HomePages(
            pages.homePageIdsForRepository(), pages.homeId());
    }

    /** Where Home page {@code id} stands in the pager; past the last when it is not one. */
    private int homePagePositionOf(int id) {
        int at = wallPages().homePageIdsForRepository().indexOf(id);
        return at >= 0 ? at : Integer.MAX_VALUE;
    }

    /** Each row runs what the corner tab, the palette and Settings already run for it. */
    private void runHomeAction(@NonNull com.termux.app.launcher.home.HomeActionsSheetPolicy.Item item) {
        switch (item) {
            case TERMINAL: openHomeFloatHere(); break;
            case ADD_WIDGET:
                if (mWidgetPaneController != null) mWidgetPaneController.openPicker();
                break;
            case ADD_APP:
                if (mWidgetPaneController != null) {
                    com.termux.app.launcher.home.HomeAppPicker.show(this, this::addAppToHome);
                }
                break;
            case ADD_PAGE: {
                View pane = findViewById(R.id.widget_pane);
                if (pane instanceof com.termux.app.launcher.widget.WidgetPaneView)
                    ((com.termux.app.launcher.widget.WidgetPaneView) pane).addWidgetPage();
                break;
            }
            case EDIT_PAGES: openOverviewDoor(false); break;
            case EDIT_WIDGETS: {
                com.termux.app.wall.WidgetPaneFrame page = mPaneWallController == null ? null
                    : mPaneWallController.widgetsPage();
                if (page == null) break;
                int[] onScreen = new int[2];
                page.getLocationOnScreen(onScreen);
                float x = mHomeActionsRawX - onScreen[0];
                float y = mHomeActionsRawY - onScreen[1];
                page.runPencil(new android.graphics.RectF(x, y, x, y));
                break;
            }
            case REMOVE_PAGE:
                if (mWidgetPaneController != null) mWidgetPaneController.removeCurrentPage();
                break;
            case LOCK_LAYOUT: break; // a switch on the card; see onLayoutLockChanged
            case WALLPAPER:
                // The wallpaper picker: no editor card has a Change row.
                openSurfaceEditor(com.termux.app.surfaces.EditorDoor.HOME_SHEET_WALLPAPER);
                break;
            case APPEARANCE:
                openSurfaceEditor(com.termux.app.surfaces.EditorDoor.HOME_SHEET_APPEARANCE);
                break;
            case LAUNCHER_SETTINGS: openSettings(); break;
            case SET_DEFAULT_HOME: HomeAppChooser.open(this); break;
            case HELP: showHelpOverlay(); break;
        }
    }

    /** The dock's, the stack's and the margin's heights as the last geometry pass laid them. */
    private int mHomeFloatDockPx, mHomeFloatStackPx;
    private boolean mHomeFloatKeyboardShown;
    /** How far the system keyboard pushes the stack up, as the last geometry pass laid it. */
    private int mHomeFloatImePushPx;

    /**
     * Whether Home's rows stand at their keyboard-down rect under a raised keyboard: a Home whose
     * keyboard is raised on demand (#309). A property of Home's rest, whatever page is in front.
     */
    private boolean homeRowsCovered() {
        return !com.termux.app.place.HomeKeyboardCover.liftsRows(
            com.termux.app.page.PageKind.HOME, isHomeKeyboardAlwaysOn());
    }

    /**
     * The top of what covers Home from below, on screen, or -1 with no keyboard up; floats and the
     * pill both meet it. While covered ({@link #homeRowsCovered}) it is the keyboard's true top: for
     * the in-app keyboard the stack's bottom less the keyboard column's laid-out height and its
     * bottom margin ({@code accessory_keyboard_column}, 0 while it is not laid out); for the system
     * keyboard {@link #systemImeTopOnScreenPx}. Always-on Home keeps the dock riding the keyboard,
     * so it is the stack's top, as before.
     */
    private int homeKeyboardTopOnScreenPx(int stackBottomPx) {
        if (!homeRowsCovered()) {
            return KeyboardOverlayPolicy.homeKeyboardTopPx(mHomeFloatKeyboardShown,
                mHomeFloatImePushPx, stackBottomPx, mHomeFloatStackPx,
                Math.max(0, stackBottomPx - mHomeFloatStackPx));
        }
        int columnPx = 0;
        View column = findViewById(R.id.accessory_keyboard_column);
        if (column != null) {
            columnPx = column.getHeight();
            if (column.getLayoutParams() instanceof ViewGroup.MarginLayoutParams) {
                columnPx += ((ViewGroup.MarginLayoutParams) column.getLayoutParams()).bottomMargin;
            }
        }
        return KeyboardOverlayPolicy.homeKeyboardTopPx(mHomeFloatKeyboardShown,
            mHomeFloatImePushPx, stackBottomPx, columnPx, systemImeTopOnScreenPx());
    }

    /**
     * The system keyboard's top on screen. The root fits the system windows: a keyboard the
     * window resizes for is the root's bottom padding ({@code mRootFitBottomPx}, which stands in
     * for the bars' with the keyboard down), so its top is the root's bottom less that padding;
     * a keyboard the insets miss is the root's own bottom margin, which already put the root's
     * bottom on the keyboard's top.
     */
    private int systemImeTopOnScreenPx() {
        View root = mTermuxActivityRootView;
        if (root == null) return 0;
        int[] at = mHomeImeTopScratch;
        root.getLocationOnScreen(at);
        int bottom = at[1] + root.getHeight();
        return mRootFitBottomPx > mRootRestFitBottomPx ? bottom - mRootFitBottomPx : bottom;
    }

    private final int[] mHomeImeTopScratch = new int[2];

    /**
     * Tells the float layer what covers it, in screen pixels: the status bar (or the system bar)
     * above, the dock below, and the keyboard with the dock riding on it while it is up. The
     * stack's bottom edge is where it stands on screen; its rows are this pass's heights.
     */
    private void syncHomeFloatObstructions() {
        if (mPaneController == null || mPaneController.homeFloatLayer() == null) return;
        // A slide across the seam stands the other half's rows or bar for its length: the floats
        // keep the room they had, and the settle's pass gives them the new one.
        if (!com.termux.app.terminal.HomeFloatPolicy.obstructionsMayMove(mCrossing.crossing(),
            mCrossing.seam().layout() != null,
            mLastWallPage == com.termux.app.page.PageKind.HOME)) return;
        View stack = findViewById(R.id.accessory_stack_container);
        View root = findViewById(R.id.activity_termux_root_view);
        if (stack == null || root == null) return;
        int[] at = new int[2];
        stack.getLocationOnScreen(at);
        // A root margin written since the last layout moves the stack by as much on the next one,
        // and so does its own (the system keyboard's lift with the bars hidden): it stands on its
        // parent's bottom, less the margin.
        int unlaidStackShift = 0;
        if (mTermuxActivityRootView != null)
            unlaidStackShift += mTermuxActivityRootView.unlaidBottomMarginGivebackPx();
        if (stack.getParent() instanceof ViewGroup
            && stack.getLayoutParams() instanceof ViewGroup.MarginLayoutParams) {
            ViewGroup parent = (ViewGroup) stack.getParent();
            int laidMargin = parent.getHeight() - parent.getPaddingBottom() - stack.getBottom();
            if (parent.getHeight() > 0 && stack.getHeight() > 0)
                unlaidStackShift += laidMargin
                    - ((ViewGroup.MarginLayoutParams) stack.getLayoutParams()).bottomMargin;
        }
        int stackBottom = Math.round(at[1] - stack.getTranslationY()) + stack.getHeight()
            + unlaidStackShift;
        // The dock's top at rest, wherever a system keyboard has pushed it: the floats' room is
        // the same with either keyboard up, and they meet the keyboard's top instead.
        int dockTop = KeyboardOverlayPolicy.homeDockRestTopPx(stackBottom, mHomeFloatDockPx,
            mHomeFloatImePushPx);
        int keyboardTop = homeKeyboardTopOnScreenPx(stackBottom);
        // The in-app keyboard's height is laid out whether or not it is up: where its top will
        // stand is known before it shows. Covered rows stay under it, so its top is the stack's
        // bottom less the keys; rows that ride it (always-on Home) add their own height.
        int predictedKeyboardTop = keyboardTop >= 0 || mKeyboardDownLaidOutPx <= 0 ? -1
            : Math.max(0, stackBottom - (homeRowsCovered() ? 0 : mHomeFloatStackPx)
                - mKeyboardDownLaidOutPx);
        root.getLocationOnScreen(at);
        int roomTop = at[1];
        androidx.core.view.WindowInsetsCompat insets =
            androidx.core.view.ViewCompat.getRootWindowInsets(root);
        if (insets != null) {
            roomTop += insets.getInsets(
                androidx.core.view.WindowInsetsCompat.Type.statusBars()).top;
        }
        // The room starts under the top edge's whole stack, read off the layout. Home wears no
        // status bar, so on Home that is the system bar's inset and whatever dock rows stand on
        // the top edge.
        View column = findViewById(R.id.terminal_content_column);
        if (column != null) {
            column.getLocationOnScreen(at);
            int columnTop = Math.round(at[1] - column.getTranslationY());
            roomTop = Math.max(roomTop, columnTop + EdgeStackPolicy.stackThicknessPx(
                arrangement().layout(), PlaceLayout.Edge.TOP, buildEdgeStackMetrics()));
        }
        // Minimised floats fold into their chips in the bar (#91): nothing stands above the dock
        // for them, and the floats' room keeps no band clear.
        // The floats breathe Home's Margin inside all that, the same air as the widget grid's
        // rim: Home's own, read explicitly, since floats are laid out while a window is in front.
        mPaneController.setHomeFloatObstructions(roomTop, dockTop, keyboardTop,
            Math.round(dpToPx(homeMarginDp())), predictedKeyboardTop);
    }

    /** Linux apps tapped in the drawer run on the display; this is what runs them. */
    private void installLinuxAppRunner() {
        if (!com.termux.app.x11.X11ServerSupport.isAvailable(TermuxActivity.this)) return;
        // A display that announces itself with no window open opens one (ADR 0008).
        mUnclaimedDisplayListener = this::claimKeptDisplay;
        com.termux.app.x11.X11DisplayReceiver.setUnclaimedListener(mUnclaimedDisplayListener);
        // The display's commands go in the prefix on every start, so a display can be started
        // from any shell; off the main thread, because it is disk I/O on the home screen's way up.
        com.termux.app.x11.X11CliInstaller.installAsync(this, result -> {
            if (isFinishing() || isDestroyed()) return;
            if (result == com.termux.app.x11.X11CliInstaller.Result.FOREIGN_COMMAND) {
                showToast(getString(R.string.termux_x11_command_taken), true);
            }
        });
        mLinuxAppsHost = new com.termux.app.x11.X11LinuxAppRunner.Host() {
                @Override public boolean isDisplayRunning() { return mDisplayServer.isRunning(); }
                @Override public void startDisplay() { mDisplayServer.start(); }
                @Override public boolean runScript(@NonNull String script,
                        @NonNull com.termux.app.x11.X11LinuxAppRunner.ScriptExitListener onExit) {
                    return runScript(script, onExit, null);
                }
                @Override public boolean runScript(@NonNull String script,
                        @NonNull com.termux.app.x11.X11LinuxAppRunner.ScriptExitListener onExit,
                        @Nullable java.util.function.IntConsumer onPid) {
                    if (mTermuxService == null) return false;
                    // bash everywhere but the nix edition, which has none and whose own sh is a
                    // store link Android cannot exec; there this is Android's shell, and the line
                    // it runs hands the work to $PREFIX/bin/login.
                    com.termux.shared.shell.command.runner.app.AppShell shell =
                        mTermuxService.createTermuxTask(com.termux.app.x11.NixProfile.hostShellPath(),
                            new String[]{"-c", script}, null, TermuxConstants.TERMUX_HOME_DIR_PATH);
                    if (shell == null) return false;
                    if (onPid != null) {
                        int pid = com.termux.shared.shell.ShellUtils.getPid(shell.getProcess());
                        if (pid > 0) onPid.accept(pid);
                    }
                    // TermuxService already reads the exit code safely inside the onAppShellExited
                    // callback it posts to its own main-thread handler once AppShell's worker thread
                    // is done with it; this rides that same happens-before edge instead of polling
                    // the raw field from an unrelated timer.
                    mTermuxService.notifyOnAppShellExit(shell, onExit::onExit);
                    return true;
                }
                @Override public void showDisplayWindow() {
                    // The runner starts the display itself, with the app queued behind it. The
                    // page a drawer tap was routed to is shown; a landing that runs its page's
                    // app is already there (A3c).
                    if (mDisplayLanding.landingRunsApp()) return;
                    if (!openDisplayWindow(false, mDisplayLanding.freshRoutedPage()))
                        dropAddedLinuxPage();
                }
                @Override public void launchGaveUp() {
                    dropAddedLinuxPage();
                }
                @Override public boolean raiseWindowFor(@NonNull com.termux.app.x11.LinuxAppCatalog.LinuxApp app) {
                    if (!mDisplayServer.hasWindowList()) return false;
                    int id = linuxWindowIdFor(app);
                    if (id < 0) return false;
                    mDisplayServer.activateWindow(id);
                    return true;
                }
                @Override public void showNotice(@NonNull String message) { showToast(message, true); }
                @Override public void askBeforeReplacingSession(@NonNull String message,
                        @NonNull Runnable onYes) {
                    new com.google.android.material.dialog.MaterialAlertDialogBuilder(
                            TermuxActivity.this)
                        .setMessage(message)
                        .setNegativeButton(android.R.string.cancel, null)
                        .setPositiveButton(R.string.termux_x11_session_replace_confirm,
                            (dialog, which) -> onYes.run())
                        .show();
                }
            };
        // The process's runner, not a new one: one this activity's predecessor started things
        // with keeps them, and this activity only takes over lending it a shell and a screen.
        mLinuxApps = com.termux.app.x11.X11LinuxAppRunner.shared(this);
        mLinuxApps.attach(mLinuxAppsHost);
        mLinuxAppRunnerHook = new com.termux.app.launcher.LauncherAppLauncher.LinuxAppRunner() {
            @Override public boolean run(@NonNull com.termux.app.launcher.model.LauncherAppEntry entry) {
                return runLinuxEntry(entry, false);
            }
            @Override public boolean runNewWindow(@NonNull com.termux.app.launcher.model.LauncherAppEntry entry) {
                return runLinuxEntry(entry, true);
            }
        };
        com.termux.app.launcher.LauncherAppLauncher.setLinuxAppRunner(mLinuxAppRunnerHook);
        mTerminalAppRunnerHook = new com.termux.app.launcher.LauncherAppLauncher.TerminalAppRunner() {
            @Override public boolean handles(@NonNull com.termux.app.launcher.model.LauncherAppEntry entry) {
                com.termux.app.x11.LinuxAppCatalog.LinuxApp app = resolveLinuxApp(entry.appRef);
                // Held for the run that follows in this same launch, whichever runner takes it.
                rememberLinuxAppResolution(entry, app);
                return app != null && app.terminal;
            }
            @Override public boolean run(@NonNull com.termux.app.launcher.model.LauncherAppEntry entry) {
                com.termux.app.x11.LinuxAppCatalog.LinuxApp app = resolveLinuxAppForLaunch(entry);
                if (app == null) {
                    showToast(getString(R.string.termux_x11_app_gone), true);
                    refreshLinuxApps(true);
                    return false;
                }
                // A terminal app is a terminal window, not the display: no display window, no
                // X11LinuxAppRunner. It opens right after the current window (ADR 0008), and the
                // wall follows it to the Terminal — after the run, since with no window yet
                // there is no Terminal on the row to go to before it.
                closeAppDrawerForLinuxLaunch();
                if (mTilingDesktop != null) {
                    // Terl: a window after the focused one in the Workspace in front, running the app.
                    mTilingDesktop.newTerminalRunning(java.util.Arrays.asList("sh", "-c", app.command()), app.name);
                    return true;
                }
                // No WindowForegroundResolver here: it needs the privileged backend only because
                // it scans every process on the system, not because reading this app's own pane
                // shell needs one, and it is async/cache-only besides. LinuxTerminalAppRunner
                // reads /proc/<pid>/stat for this exact pid directly instead — see its class doc.
                boolean ran = com.termux.app.x11.LinuxTerminalAppRunner.run(app);
                if (ran && mPaneWallController != null) {
                    mPaneWallController.refreshPages();
                    mPaneWallController.goTo(com.termux.app.page.PageKind.TERMINAL, isVisible());
                }
                return ran;
            }
        };
        com.termux.app.launcher.LauncherAppLauncher.setTerminalAppRunner(mTerminalAppRunnerHook);
    }

    /**
     * The Linux app an entry's id names, re-read from the live catalogue (nothing is cached or
     * watched, so an app installed a moment ago is simply there). Null once the app is gone.
     */
    /**
     * The answer {@code LauncherAppLauncher}'s {@code handles} just read for this launch, so the
     * runner it hands the entry to does not scan every root again a moment later: one scan per
     * tap instead of two. Valid only for the same entry, on the same thread, within
     * {@link #LINUX_APP_RESOLUTION_REUSE_MS}, and used once.
     */
    @Nullable private com.termux.app.launcher.model.LauncherAppEntry mResolvedLinuxEntry;
    /**
     * The page a Linux app's new Display page goes after: on Home the Home page in front (the
     * wall's current slot is the first page of the Home run), else the page the wall is on.
     */
    private int linuxRouteFromPageId() {
        if (mPaneWallController == null) return -1;
        if (mPaneWallController.currentPage() == com.termux.app.page.PageKind.HOME) {
            int home = mHomeSeam.pageInFront();
            if (home >= 0) return home;
        }
        return mPaneWallController.currentPageId();
    }

    @Nullable private com.termux.app.x11.LinuxAppCatalog.LinuxApp mResolvedLinuxApp;
    @Nullable private Thread mResolvedLinuxThread;
    private long mResolvedLinuxAtMs;
    private static final long LINUX_APP_RESOLUTION_REUSE_MS = 1000L;
    /** launcherctl launches from its own thread, so the memo is guarded. */
    private final Object mResolvedLinuxLock = new Object();

    private void rememberLinuxAppResolution(@NonNull com.termux.app.launcher.model.LauncherAppEntry entry,
                                            @Nullable com.termux.app.x11.LinuxAppCatalog.LinuxApp app) {
        synchronized (mResolvedLinuxLock) {
            mResolvedLinuxEntry = entry;
            mResolvedLinuxApp = app;
            mResolvedLinuxThread = Thread.currentThread();
            mResolvedLinuxAtMs = android.os.SystemClock.uptimeMillis();
        }
    }

    /** The Linux app for a launch: the resolution {@code handles} just made for it, else a scan. */
    @Nullable
    private com.termux.app.x11.LinuxAppCatalog.LinuxApp resolveLinuxAppForLaunch(
            @NonNull com.termux.app.launcher.model.LauncherAppEntry entry) {
        synchronized (mResolvedLinuxLock) {
            boolean reusable = mResolvedLinuxEntry == entry
                && mResolvedLinuxThread == Thread.currentThread()
                && android.os.SystemClock.uptimeMillis() - mResolvedLinuxAtMs
                    <= LINUX_APP_RESOLUTION_REUSE_MS;
            com.termux.app.x11.LinuxAppCatalog.LinuxApp app = mResolvedLinuxApp;
            mResolvedLinuxEntry = null;
            mResolvedLinuxApp = null;
            mResolvedLinuxThread = null;
            if (reusable) return app;
        }
        return resolveLinuxApp(entry.appRef);
    }

    /** The display window of {@code app} on the running display, or -1. */
    private int linuxWindowIdFor(@NonNull com.termux.app.x11.LinuxAppCatalog.LinuxApp app) {
        return com.termux.app.x11.DisplayWindowMatch.windowFor(
            mDisplayServer.windows(), app.startupWmClass, app.exec, app.id);
    }

    @Nullable
    private com.termux.app.x11.LinuxAppCatalog.LinuxApp resolveLinuxApp(
            @NonNull com.termux.app.launcher.model.AppRef ref) {
        java.util.List<com.termux.app.x11.LinuxAppCatalog.LinuxApp> apps =
            com.termux.app.x11.LinuxAppCatalog.scan(com.termux.app.x11.LinuxAppCatalog.roots());
        return com.termux.app.x11.LinuxAppCatalog.find(apps, com.termux.app.x11.X11Apps.desktopId(ref));
    }

    /**
     * Wire the connection to a display server. Nothing here starts one: a display exists because
     * something asked for it ({@link #openDisplayWindow}) or someone typed {@code termux-x11 :0}.
     */
    private void createX11DisplayController() {
        if (mPaneWallController == null || mDisplayServer.controller() != null) return;
        com.termux.app.x11.X11PaneFrame page = mPaneWallController.displayWindow();
        if (page == null) return;
        mDisplayServer.setController(new com.termux.app.x11.X11DisplayHostController(this,
            new com.termux.x11.LorieHost.Callbacks() {
                @Override public void toggleKeyboardVisibility() {
                    if (toggleDisplayFrameKeyboard()) return;
                    if (mInAppKeyboard == null) return;
                    // The keyboard key is the way back from "off", here as on the terminal.
                    if (mInAppKeyboard.isTurnedOff()) {
                        mInAppKeyboard.setTurnedOff(false);
                        return;
                    }
                    if (mInAppKeyboard.isVisible()) {
                        mInAppKeyboard.hide(com.termux.app.terminal.inappkeyboard
                            .TermuxInAppKeyboard.HideReason.KEYBOARD_ACTION);
                    } else {
                        mInAppKeyboard.show(com.termux.app.terminal.inappkeyboard
                            .TermuxInAppKeyboard.ShowReason.KEYBOARD_ACTION);
                    }
                }
                // Hardware keys reach the view before the page sees them when the server's scancode
                // workaround is off; the same answer either way.
                @Override public boolean handleKey(@NonNull KeyEvent event) {
                    return consumeDisplayWindowKey(event);
                }
                @NonNull
                @Override public String textLeftAfterLayer(@NonNull String text) {
                    return textLeftAfterOpenLayer(text);
                }
                @Override public boolean mayTakeFocus() {
                    return displayViewMayTakeFocus();
                }
                @Override public void onDisplayStopped() {
                    com.termux.app.x11.X11PaneFrame frame = mPaneWallController == null
                        ? null : mPaneWallController.displayWindow();
                    if (frame != null) frame.applyRunning(false);
                    syncPlaceBar();
                    // A temporary page goes with its display.
                    removeTemporaryDisplayPage();
                }
            }));
        mDisplayServer.controller().setTextFocusKeyboard(new com.termux.app.x11.DisplayTextFocusPolicy.Keyboard() {
            @Override public void showKeyboardForTextFocus() {
                // While mouse mode owns the keyboard frame the keyboard is already up in it: the
                // text field brings it in front of the touchpad instead of raising anything.
                if (mTouchpad.applyDisplayFrameTextFocus(true)) return;
                if (mInAppKeyboard != null) mInAppKeyboard.show(com.termux.app.terminal
                    .inappkeyboard.TermuxInAppKeyboard.ShowReason.FOCUS);
            }
            @Override public void hideKeyboardForTextFocus() {
                if (mTouchpad.applyDisplayFrameTextFocus(false)) return;
                if (mInAppKeyboard != null) mInAppKeyboard.hide(com.termux.app.terminal
                    .inappkeyboard.TermuxInAppKeyboard.HideReason.FOCUS);
            }
            @Override public boolean isKeyboardUp() {
                // The phone's keyboard, where this place takes one, is up exactly while the IME is.
                if (mDisplayKeys.displayTakesSystemKeyboard()) return isImeVisible();
                // In mouse mode the keyboard view is up either way, as the pad's frame; what the
                // policy is asking is whether a keyboard is the thing on screen.
                if (mTouchpad.isDisplayTouchpadFrame()) return mFrameContent.isKeyboardContent();
                return mInAppKeyboard != null && mInAppKeyboard.isVisible();
            }
        });
        page.setTapListener(new com.termux.app.x11.X11PaneFrame.TapListener() {
            @Override public void onDisplayTap() {
                if (mDisplayServer.controller() != null) mDisplayServer.controller().onDisplayTap();
            }

            @Override public void onDisplayDrag() {
                if (mDisplayServer.controller() != null) mDisplayServer.controller().onDisplayDrag();
            }
        });
        mDisplayServer.controller().host().setLorieView(page.display());
        mDisplayServer.listen(mPaneWallController.wall());
        syncDisplayEnvironment();
        // The tool store CLI goes in the same way the display's commands do, on every start.
        com.termux.app.store.TlstoreInstaller.installAsync(this, result -> {
            Logger.logDebug(LOG_TAG, "tlstore install: " + result);
            if (result.kind == com.termux.app.store.TlstoreInstaller.Result.Kind.FOREIGN_COMMAND) {
                Logger.logWarn(LOG_TAG, "Leaving a foreign " + result.foreignCommand
                    + " in place; tlstore not installed");
            }
        });
        // Built while the display window is already in front at rest (its own "Turn on") — there
        // is no settle coming to attach the surface, so do it now.
        if (isDisplayWindowInFront() && !mPaneWallController.wall().isMoving()) {
            mDisplayPages.attach();
        }
    }

    /**
     * The icon resolver, built the first time the display's chip needs it. It outlives a display
     * stopping and starting, since what an app's icon looks like does not depend on the server.
     */
    @Nullable
    private com.termux.app.x11.X11WindowIconResolver displayWindowIcons() {
        if (!com.termux.app.x11.X11ServerSupport.isAvailable(this)) return null;
        if (mDisplayWindowIcons == null) {
            mDisplayWindowIcons = new com.termux.app.x11.X11WindowIconResolver(getResources(),
                (wmClass, icon, name) -> {
                    // A Linux window's chip dresses as its icon or name resolves, not at the next refresh.
                    boolean linuxChips = mLinuxWindows != null && !mLinuxWindows.chips().isEmpty();
                    if (icon != null) mLinuxIconsResolved++;
                    if ((icon == null && name == null) || !(isDisplayUp() || linuxChips)
                        || !isSplitPanesEnabled()) return;
                    com.termux.app.terminal.TerminalWindowBar bar =
                        findViewById(R.id.terminal_window_bar);
                    if (bar != null) syncWindowBarItems(bar);
                });
            // A Linux app's colour icon (the page marks') is the drawer's, from its bounded store.
            mDisplayWindowIcons.setColourIcons(ref ->
                LauncherAppDataProvider.getInstance(this).icons().artwork(ref));
        }
        return mDisplayWindowIcons;
    }

    /**
     * The display window's chip: named after the app in front, the way a terminal window's chip
     * names what runs in it, and wearing that app's icon once one resolves; Display, with the
     * chip's generic glyph, while no app is open (DisplayWindowName).
     */
    @NonNull
    private com.termux.app.chrome.DisplayAppChips displayAppChips() {
        java.util.List<Integer> ids = new java.util.ArrayList<>();
        for (com.termux.app.x11.X11WindowList.Window w : mDisplayServer.windows()) ids.add(w.id);
        return new com.termux.app.chrome.DisplayAppChips(ids,
            com.termux.app.x11.DisplayWindowName.frontIndex(mDisplayServer.windows().size(),
                mDisplayServer.activeWindow()));
    }

    /** One chip per app open on the display, named and iconed like the old single chip. */
    @NonNull
    private java.util.List<com.termux.app.terminal.TerminalWindowBar.WindowItem>
            displayAppItems() {
        String display = getString(R.string.launcher_entry_display);
        com.termux.app.x11.X11WindowIconResolver apps = displayWindowIcons();
        java.util.List<com.termux.app.terminal.TerminalWindowBar.WindowItem> items =
            new java.util.ArrayList<>();
        for (com.termux.app.x11.X11WindowList.Window window : mDisplayServer.windows()) {
            String name = com.termux.app.x11.DisplayWindowName.of(
                apps == null ? null : apps.nameFor(window.wmClass), window.label, display);
            String spoken = name.equals(display) ? display
                : getString(R.string.display_window_spoken_label, name, display);
            items.add(new com.termux.app.terminal.TerminalWindowBar.WindowItem(name, spoken)
                .withIcon(apps == null ? null : apps.iconFor(window.wmClass)));
        }
        return items;
    }

    @NonNull
    private com.termux.app.terminal.TerminalWindowBar.WindowItem displayWindowItem() {
        String display = getString(R.string.launcher_entry_display);
        int front = com.termux.app.x11.DisplayWindowName.frontIndex(mDisplayServer.windows().size(),
            mDisplayServer.activeWindow());
        if (front < 0) {
            return new com.termux.app.terminal.TerminalWindowBar.WindowItem(display, display);
        }
        com.termux.app.x11.X11WindowList.Window window = mDisplayServer.windows().get(front);
        com.termux.app.x11.X11WindowIconResolver apps = displayWindowIcons();
        String name = com.termux.app.x11.DisplayWindowName.of(
            apps == null ? null : apps.nameFor(window.wmClass), window.label, display);
        String spoken = name.equals(display) ? display
            : getString(R.string.display_window_spoken_label, name, display);
        return new com.termux.app.terminal.TerminalWindowBar.WindowItem(name, spoken)
            .withIcon(apps == null ? null : apps.iconFor(window.wmClass));
    }

    private void onDisplayWindowsChanged(
            @NonNull java.util.List<com.termux.app.x11.X11WindowList.Window> windows, int active) {
        noteTemporaryDisplayWindows(windows.size());
        // The display's chip wears its front app's name and icon, so a new front app re-dresses it.
        if (!isDisplayUp() || !isSplitPanesEnabled()) return;
        com.termux.app.terminal.TerminalWindowBar bar = findViewById(R.id.terminal_window_bar);
        if (bar != null) syncWindowBarItems(bar);
    }

    /** What the display server's lifecycle needs from the activity. */
    private final class DisplayServerHost implements com.termux.app.x11.DisplayServer.Host {
        @Override public void refreshPageGlyphs() { TermuxActivity.this.refreshPageGlyphs(); }

        @Override public void setStartFailure(@Nullable String reason) {
            setDisplayStartFailure(reason);
        }

        @Override public boolean hasDisplayWindow() {
            return mPaneWallController != null && mPaneWallController.displayWindow() != null;
        }

        @Override public boolean isDisplayWindowInFront() {
            return TermuxActivity.this.isDisplayWindowInFront();
        }

        @Override public void onDisplayTornDown(boolean wasInFront) {
            tearDownEmbeddedDisplayWindow(wasInFront);
        }

        @Override public void onLinuxAppsRunningChanged(boolean running) {
            if (mLinuxApps != null) mLinuxApps.onDisplayRunningChanged(running);
        }

        @Override public void syncRunningChrome(boolean running) {
            com.termux.app.x11.X11PaneFrame frame = mPaneWallController == null
                ? null : mPaneWallController.displayWindow();
            if (frame != null) frame.applyRunning(running);
            if (mPaneWallController != null) mPaneWallController.onDisplayRunningChanged();
            mDisplayPageBinding.applyStill();
            TermuxActivity.this.syncPlaceBar();
            mTouchpad.syncDisplayTouchpad();
            syncDisplayEnvironment();
        }

        @Override public void afterRunningChanged(boolean running) {
            // A display that stopped has nothing left to type into.
            if (!running) mDisplayKeys.hideDisplaySystemKeyboard();
            mDisplayKeys.syncDisplayKeyboardRoute();
            syncDisplayOnRow();
        }

        @Override public void bringInFrontIfStartOnDisplayPending() {
            // Start in = Display: the cold start's landing finishes on the display window.
            if (mStartOnDisplayPending) {
                mStartOnDisplayPending = false;
                bringDisplayWindowInFront(false);
            }
        }

        @Override public void onDisplayGone() {
            if (mPaneWallController != null) mPaneWallController.onDisplayRunningChanged();
            TermuxActivity.this.syncPlaceBar();
        }

        @Override public void onWindowsChanged(
                @NonNull java.util.List<com.termux.app.x11.X11WindowList.Window> windows,
                int active) {
            onDisplayWindowsChanged(windows, active);
        }

        @Override public void syncPlaceBar() { TermuxActivity.this.syncPlaceBar(); }

        @Nullable @Override public TermuxService service() { return mTermuxService; }

        @Nullable @Override public com.termux.shared.termux.settings.preferences
                .TermuxAppSharedPreferences preferences() {
            return mPreferences;
        }

        @Override public boolean isActivityGone() { return isFinishing() || isDestroyed(); }
    }

    /** Hand the Display window the reason the last Start died, or clear it with null. */
    private void setDisplayStartFailure(@Nullable String reason) {
        if (mPaneWallController == null) return;
        com.termux.app.x11.X11PaneFrame frame = mPaneWallController.displayWindow();
        if (frame != null) frame.setStartFailure(reason);
    }

    /** The Display place's menu while it is up. */

    /**
     * Mouse mode, flipped by the Mouse mode action. In the terminal every touch is the mouse; on
     * the Display place a touchpad takes the keyboard's place. It is a session choice, not a
     * setting: the app starts with it off.
     *
     * <p>On the Display place the pad and the keyboard share one frame, so what mouse mode is
     * doing is also what that frame holds — the pad, or the keyboard parked in front of it. The
     * decision table is {@link com.termux.app.x11.DisplayFrameContentPolicy}; mouse mode is on
     * for as long as its content is not {@code NONE}.
     */
    @NonNull private final com.termux.app.x11.DisplayFrameContentPolicy mFrameContent =
        new com.termux.app.x11.DisplayFrameContentPolicy();
    /** The keyboard's clipboard panel, over the keys the way the touchpad is; built on first use. */
    @Nullable private ClipboardPanelController mClipboardPanel;

    @NonNull
    private ClipboardPanelController clipboardPanel() {
        if (mClipboardPanel != null) return mClipboardPanel;
        mClipboardPanel = new ClipboardPanelController(new ClipboardPanelController.Host() {
            @Override @Nullable public FrameLayout keyboardViewHost() {
                return findViewById(R.id.inapp_keyboard_view_host);
            }

            @Override @Nullable public View keyboardView() {
                return mAttachedInAppKeyboardView;
            }

            @Override public boolean isCard() {
                return isInAppKeyboardCapsule();
            }

            @Override public boolean isReducedMotionEnabled() {
                return TermuxActivity.this.isReducedMotionEnabled();
            }

            @Override @NonNull public ClipboardPanelView.Palette palette() {
                // The touchpad's roles: the overlay surface the drawer and the popups use, its
                // on-surface pair, and the terminal place's accent for the pill and the pins.
                return new ClipboardPanelView.Palette(
                    getTermuxThemeColor(com.termux.shared.R.attr.termuxColorSurfacePanelHigh,
                        R.color.termux_surface_panel_high),
                    getTermuxThemeColor(com.termux.shared.R.attr.termuxColorOnSurface,
                        R.color.termux_on_surface),
                    getTermuxThemeColor(com.termux.shared.R.attr.termuxColorOnSurfaceVariant,
                        R.color.termux_on_surface_variant),
                    com.termux.app.statusbar.StatusBarLensView.accentFor(TermuxActivity.this,
                        com.termux.app.page.PageKind.TERMINAL));
            }

            @Override public void pasteFromHistory(@NonNull String text) {
                // Onto the Android clipboard first — the one clipboard every paste reads — and
                // then through the keyboard's own paste route, so the Display place or an
                // overlay takes it exactly as it takes the paste key. Pasting is not copying:
                // the history is left as it stands.
                ShareUtils.copyTextToClipboard(TermuxActivity.this, text);
                if (mInAppKeyboard != null && mInAppKeyboard.pasteThroughKeyboard()) return;
                if (mTermuxTerminalSessionActivityClient != null)
                    mTermuxTerminalSessionActivityClient.onPasteTextFromClipboard(getCurrentSession());
            }
        }, ClipboardHistory.get(this));
        return mClipboardPanel;
    }

    // ---- The page bar ----------------------------------------------------------------------------

    /** Whether something covers the wall (an editor, the drawer, a sheet, first-run setup): the page bar takes no touch. */
    private boolean pageSwitchSuppressed() {
        return mSurfaceEditor.isActive() || mLayoutEditor.isActive()
            || mSheets.isAppDrawerEngaged() || mSheets.isCommandPaletteOpen()
            || isLayerOpen()
            || setupWizardComesFirst()
            || (mSetupWizard != null && mSetupWizard.isCardSheetShowing());
    }

    /** The page bar's owner, Home's and the key's popup: answers the bar's questions and claims its touch. */
    @Nullable private com.termux.app.wall.pageswitch.PageBarController mPageBar;

    /**
     * The raised glass the key's page bar wears (ElevatedGlass over the sheets' glass), worn only
     * while that bar is shown: it reads the shared blur cache's frame at the raised radius, holds
     * no pixels of its own and takes no Live glass slot.
     */
    @Nullable private com.termux.app.chrome.LookGlassStyle mRaisedGlass;

    @NonNull
    private com.termux.app.chrome.LookGlassStyle raisedGlassStyle() {
        if (mRaisedGlass == null) {
            mRaisedGlass = new com.termux.app.chrome.LookGlassStyle(this, mChrome,
                new com.termux.app.chrome.LookGlassStyle.Host() {
                    @Override public TermuxAppSharedPreferences preferences() { return mPreferences; }
                    @Override public View wallpaperFrame() {
                        return findViewById(R.id.activity_termux_root_view);
                    }
                    @Override public boolean wallpaperBlurs() { return wallpaperSampleable(); }
                    @Override public int glassBaseColor() { return resolveAccessoryGlassBaseColor(); }
                    // The Fancier Glass look the extra-keys card under it wears, so the pop-up is
                    // the same material with the cards' lit edge; null (plain frost) when it is off.
                    @Override public com.termux.app.chrome.GlassRefraction.Look refraction() {
                        return mFancierGlassLook;
                    }
                    @Override public com.termux.app.chrome.WallpaperParallax parallax() {
                        return mWallpaperParallax;
                    }
                    @Override public com.termux.app.chrome.LookGlassSpec spec() {
                        return com.termux.app.chrome.ElevatedGlass.lookSpec(
                            mPreferences != null && mPreferences.isUseSystemWallpaperEnabled(),
                            com.termux.app.chrome.ElevatedGlass.of(mPreferences));
                    }
                });
        }
        return mRaisedGlass;
    }

    private void attachPageBar() {
        if (mPageBar != null) return;
        final com.termux.app.wall.pageswitch.PageSwitchTargets.Navigator nav = pageSwitchNavigator();
        mPageBar = new com.termux.app.wall.pageswitch.PageBarController(this,
            new com.termux.app.wall.pageswitch.PageBarController.Host() {
                @Override public void goToPage(int pageId) { nav.goToPage(pageId); }
                @Override public void showTerminalWindow(int index) { nav.showTerminalWindow(index); }
                @Override public void goToTerminal() { nav.goToTerminal(); }
                @Override public void openOverview() { nav.openOverview(); }

                @Override public boolean hapticsEnabled() {
                    return mPreferences != null && mPreferences.isAppHapticsEnabled();
                }

                @Override public boolean isReducedMotionEnabled() {
                    return TermuxActivity.this.isReducedMotionEnabled();
                }

                @Override public boolean isSuppressed() {
                    return pageSwitchSuppressed();
                }

                @Override public int accent() {
                    // The A-Z bar's accent: the scheme's primary.
                    return resolveAzGestureAccentColor();
                }

                @NonNull @Override public com.termux.app.wall.pageswitch.PageBarModel pageBarModel() {
                    return TermuxActivity.this.pageBarModel();
                }

                @Override public int ink() {
                    return getTermuxThemeColor(com.termux.shared.R.attr.termuxColorOnSurface,
                        R.color.termux_on_surface);
                }

                @Override public com.termux.app.chrome.LookGlassStyle raisedGlass() {
                    return raisedGlassStyle();
                }

                @Override public boolean keysCardOnScreen(@NonNull android.graphics.Rect out) {
                    View card = findViewById(R.id.extra_keys_card);
                    if (card == null || !card.isShown() || card.getWidth() <= 0) return false;
                    int[] at = new int[2];
                    card.getLocationOnScreen(at);
                    out.set(at[0], at[1], at[0] + card.getWidth(), at[1] + card.getHeight());
                    return true;
                }

                // The gap the stack keeps between the extra-keys card and the keyboard's card:
                // Floating's air, Docked's none (ChromePolicy, UnderKeyboardBand).
                @Override public int stackRowGapPx() {
                    return com.termux.app.chrome.ChromePolicy.keyboardHostTopMarginPx(
                        isRoundedStyle(com.termux.app.place.SeamDress.Surface.STACK), false,
                        getResources().getDisplayMetrics().density);
                }

                // The card's own rule (KeysCardDress dresses it with exactly this call, whatever
                // the style): the resolved Corners, "follow the style" included, capped at half.
                @Override public float keysCardRadiusPx(int heightPx) {
                    return mDock.resolveDockCapsuleCornerRadiusPx(heightPx);
                }
            }, (FrameLayout) findViewById(R.id.page_switch_layer));
        // The dock's capsules dim while the bar slides (the dock strip's slice listens here).
        mPageBar.setSlidingListener(sliding -> mPageTicks.setDimmed(sliding));
        mPageSwitchKey = new com.termux.app.wall.pageswitch.PageSwitchKeyOwner(mPageBar,
            this::extraKeysPageTotal, this::extraKeysPageAt);
        // Rows built before the switcher existed take the key's owner and glyph now.
        for (int i = 0, n = extraKeysPageTotal(); i < n; i++) {
            ExtraKeysPageView page = extraKeysPageAt(i);
            if (page != null) page.setKeyTouchOwner(mPageSwitchKey);
        }
        refreshPageSwitcherKey();
    }

    /** The extra-keys bar's page switcher key: its touch, its hit area and its plain click. */
    @Nullable private com.termux.app.wall.pageswitch.PageSwitchKeyOwner mPageSwitchKey;

    /**
     * Tells every key row that stands a page switcher key which page the wall is on, for the cap's
     * glyph and number. Each page compares before it repaints; with no such key nothing is built.
     */
    private void refreshPageSwitcherKey() {
        com.termux.app.wall.pageswitch.PageGlyphSource.Glyph glyph = null;
        for (int i = 0, n = extraKeysPageTotal(); i < n; i++) {
            ExtraKeysPageView page = extraKeysPageAt(i);
            if (page == null || !page.hasPageSwitcherKey()) continue;
            if (glyph == null) glyph = currentPageGlyph();
            page.setPageSwitcherGlyph(glyph.kind, glyph.number);
        }
    }

    /**
     * The key's cap is built with this: the glyph of the page the wall is on, with that kind's
     * number. Installed from onCreate, so a bar built at any time starts right.
     */
    private final com.termux.app.wall.pageswitch.PageGlyphSource.Provider mPageGlyphProvider =
        this::currentPageGlyph;

    @NonNull
    private com.termux.app.wall.pageswitch.PageGlyphSource.Glyph currentPageGlyph() {
        com.termux.app.wall.pageswitch.PageBarModel model = pageBarModel();
        return new com.termux.app.wall.pageswitch.PageGlyphSource.Glyph(model.capKind(),
            model.capNumber());
    }

    /** Gives Home's glyph row the pages the wall has now; called when a page settles or the list changes. */
    private void refreshPageGlyphs() {
        if (mWidgetPaneController != null) {
            mWidgetPaneController.setPageBarEntry(mPageBar);
            mWidgetPaneController.setPageBar(pageBarModel());
        }
        refreshPageSwitcherKey();
        mMarksLine.syncMarksLine();
    }

    /**
     * Tells Home's pane the status bar's page bar look: Marks fits the pill to its marks. Called when the look can have changed (settings return, the editor's row), never per
     * page change; the pane compares before it resizes.
     */
    private void syncHomeBandLook() {
        if (mWidgetPaneController == null || mPreferences == null) return;
        mWidgetPaneController.setPageBarLook(com.termux.app.wall.pageswitch.PageBarLook
            .fromValue(mPreferences.getPageBarLook()));
        // Home's pill under Marks holds a line of its own; it is fed with the status bar's.
        mMarksLine.syncMarksLine();
    }

    /** The window count and current window the glyphs were last given. */
    private int mGlyphWindowCount = -1;
    private int mGlyphWindowCurrent = -1;

    /**
     * Terminal's glyph holds the window you would return to, so the glyphs follow the window list
     * wherever the window bar's items are rebuilt. Compares before it refreshes.
     */
    private void refreshPageGlyphsIfWindowsMoved() {
        int count = rowWindowCount();
        int current = count == 0 ? -1 : rowCurrentIndex();
        // A Linux window's mark key changes with its icon: an icon set, or an entry icon that
        // resolved, redresses the marks through this same refresh.
        int icons = (mLinuxWindows == null ? 0 : mLinuxWindows.iconVersion()) + mLinuxIconsResolved;
        if (count == mGlyphWindowCount && current == mGlyphWindowCurrent && icons == mGlyphIconVersion) return;
        mGlyphWindowCount = count;
        mGlyphWindowCurrent = current;
        mGlyphIconVersion = icons;
        refreshPageGlyphs();
    }

    /** The Linux icon version the glyphs were last given, and how many entry icons have resolved. */
    private int mGlyphIconVersion = -1;
    private int mLinuxIconsResolved;

    private boolean switcherAnimates() {
        return isVisible() && !isReducedMotionEnabled();
    }

    /**
     * The wall's pages as the page bar shows them, right now: in wall order, with the Terminal's
     * windows and their own names (null while unnamed).
     */
    @NonNull
    private com.termux.app.wall.pageswitch.PageBarModel pageBarModel() {
        com.termux.app.wall.pageswitch.PageBarModel.Input in =
            new com.termux.app.wall.pageswitch.PageBarModel.Input();
        java.util.List<com.termux.app.wall.pageswitch.PageBarModel.Page> pages =
            new java.util.ArrayList<>();
        // Under Terl Home's page dots name Home's pages alone: the rest are windows of the stack.
        boolean terl = mTilingDesktop != null;
        for (com.termux.app.wall.WallPages.Page page : wallPages().pages()) {
            if (!com.termux.app.wall.TerlWall.laysOut(page.kind, terl)) continue;
            pages.add(new com.termux.app.wall.pageswitch.PageBarModel.Page(page.id, page.kind,
                page.name == null || page.name.isEmpty() ? null : page.name, page.binding));
        }
        in.pages = pages;
        java.util.List<String> windowNames = new java.util.ArrayList<>();
        java.util.List<String> windowAppIds = new java.util.ArrayList<>();
        java.util.List<String> windowGlyphs = new java.util.ArrayList<>();
        if (mPaneController != null && !terl) {
            java.util.List<com.termux.app.terminal.TerminalPaneController.Window> windows =
                rowWindows();
            // In row order, a Linux window's name among the terminal windows' (#392).
            int places = rowWindowCount();
            boolean[] linux = new boolean[places];
            for (int i = 0; i < places; i++) {
                int terminal = terminalAtPlace(i);
                linux[i] = terminal < 0;
                windowNames.add(terminal >= 0 ? mPaneController.windowName(windows.get(terminal))
                    : linuxWindowName(mCurrentWSession.row.linuxAt(windows, i)));
                windowAppIds.add(terminal >= 0 ? null
                    : linuxWindowIconKey(mCurrentWSession.row.linuxAt(windows, i)));
                windowGlyphs.add(terminal < 0 ? null : windowProgramGlyph(windows.get(terminal)));
            }
            in.linuxWindows = linux;
        }
        in.windowNames = windowNames;
        in.windowAppIds = windowAppIds;
        mMinimise.fill(in);
        in.windowGlyphs = windowGlyphs;
        in.currentWindow = windowNames.isEmpty() ? -1 : rowCurrentIndex();
        in.currentPageId = mPaneWallController == null ? -1 : mPaneWallController.currentPageId();
        in.displayRunning = mDisplayServer.isRunning();
        in.homeOffered = useAs().showsHomePage();
        in.kindNames = new String[] {getString(R.string.page_switch_home),
            getString(R.string.page_switch_terminal), getString(R.string.page_switch_display),
            getString(R.string.page_switch_assistant)};
        return com.termux.app.wall.pageswitch.PageBarModel.build(in);
    }

    /**
     * The page mark key of Linux window {@code id}: it names the window and changes with its icon;
     * null when it is gone or has no icon to show. {@link #pageMarkIcons} answers it.
     */
    @Nullable
    private String linuxWindowIconKey(long id) {
        return mLinuxWindows == null ? null : mLinuxWindows.iconKey(id);
    }

    /**
     * The glyph a terminal window's mark wears while its focused pane runs a full-screen program
     * the glyph table knows; null otherwise. The program is the one the window bar's chip uses
     * ({@link #buildWindowItem}), read from the resolver's last answer, not resolved again.
     */
    @Nullable
    private String windowProgramGlyph(
            @NonNull com.termux.app.terminal.TerminalPaneController.Window window) {
        TerminalSession session = mPaneController == null ? null
            : mPaneController.windowActiveSession(window);
        if (session == null || !isFullScreenApplication(session)) return null;
        com.termux.app.statusbar.WindowForegroundResolver.ForegroundInfo info =
            mWindowForegroundResolver == null ? null : mWindowForegroundResolver.get(session.getPid());
        String process = info != null && !info.idle ? glyphProcessFor(info)
            : com.termux.app.terminal.TerminalWindowBar.processName(session.getTitle());
        return com.termux.app.wall.pageswitch.PageMarkGlyph.forProgram(true, process);
    }

    @Nullable private com.termux.app.wall.pageswitch.PageMarkIcons mPageMarkIcons;
    /** The Linux windows' icon fallback: the Display's desktop-entry icons, in the form asked. */
    @NonNull private final com.termux.app.wayland.LinuxWindowIcons.Lookup mLinuxIconLookup =
        new com.termux.app.wayland.LinuxWindowIcons.Lookup() {
            @Nullable @Override public android.graphics.Bitmap forAppId(@NonNull String appId,
                    @NonNull com.termux.app.wayland.LinuxWindowIcons.Form form) {
                com.termux.app.x11.X11WindowIconResolver apps = displayWindowIcons();
                if (apps == null) return null;
                return form == com.termux.app.wayland.LinuxWindowIcons.Form.COLOUR
                    ? apps.colourFor(appId) : apps.iconFor(appId);
            }

            @Nullable @Override public android.graphics.Bitmap named(@NonNull String name,
                    @NonNull com.termux.app.wayland.LinuxWindowIcons.Form form) {
                com.termux.app.x11.X11WindowIconResolver apps = displayWindowIcons();
                if (apps == null) return null;
                return form == com.termux.app.wayland.LinuxWindowIcons.Form.COLOUR
                    ? apps.colourNamed(name) : apps.iconNamed(name);
            }
        };

    /**
     * Where the page bar's views get a Linux app's icon and the program glyphs' face: the window
     * chips' icon resolver and the bundled symbols font. Not wired into a view yet.
     */
    @NonNull
    com.termux.app.wall.pageswitch.PageMarkIcons pageMarkIcons() {
        if (mPageMarkIcons == null) {
            mPageMarkIcons = new com.termux.app.x11.ResolverPageMarkIcons(
                getResources(), this::displayWindowIcons,
                () -> com.termux.shared.termux.font.NerdFontSpans.typeface(this),
                id -> mLinuxWindows == null ? null : mLinuxWindows.windowIcon(id,
                    com.termux.app.wayland.LinuxWindowIcons.Form.COLOUR));
        }
        return mPageMarkIcons;
    }

    /** What a chosen cell does on the wall. */
    @NonNull
    private com.termux.app.wall.pageswitch.PageSwitchTargets.Navigator pageSwitchNavigator() {
        return new com.termux.app.wall.pageswitch.PageSwitchTargets.Navigator() {
            @Override public void goToPage(int pageId) {
                goToSwitcherPage(pageId, switcherAnimates());
            }

            @Override public void showTerminalWindow(int index) {
                if (mPaneWallController == null) return;
                // As a window chip tapped from elsewhere: the wall travels to the Terminal page,
                // then the window comes in front.
                if (currentWallPlace() != com.termux.app.page.PageKind.TERMINAL)
                    mPaneWallController.goTo(com.termux.app.page.PageKind.TERMINAL,
                        switcherAnimates());
                showRowWindow(index);
            }

            @Override public void goToTerminal() {
                if (mPaneWallController == null) return;
                bringTerminalWindowInFront();
                mPaneWallController.goTo("terminal");
            }

            @Override public void openOverview() {
                toggleOverview();
            }

            @Override public void restoreMinimised(int index) { mMinimise.restore(index); }
        };
    }

    /** Go to the wall page {@code pageId}, by the way its kind is gone to. */
    private void goToSwitcherPage(int pageId, boolean animate) {
        if (mPaneWallController == null) return;
        com.termux.app.wall.WallPages.Page page = wallPages().page(pageId);
        if (page == null) return;
        switch (page.kind) {
            case HOME:
                mPaneWallController.goToHomePageAt(wallPages().homePages().indexOf(page), animate);
                break;
            case DISPLAY:
                mPaneWallController.goToDisplayPage(pageId, animate);
                break;
            case ASSISTANT:
                mPaneWallController.goToAssistantPage(animate);
                break;
            default:
                bringTerminalWindowInFront();
                mPaneWallController.goToPageId(pageId, animate);
                break;
        }
    }

    /** Flip mouse mode; returns the new state. The mark at the end of the stats is the announcement. */
    boolean toggleMouseMode() {
        // The mouse key also brings the pad back from behind a keyboard that took the frame for
        // a text field: there it is not mouse mode the user is turning off.
        mTouchpad.applyDisplayFrameDecision(mFrameContent.onMouseKey());
        return mFrameContent.isMouseMode();
    }

    void setMouseMode(boolean enabled) {
        if (mFrameContent.isMouseMode() == enabled) return;
        mTouchpad.applyDisplayFrameDecision(enabled
            ? mFrameContent.onMouseModeOn() : mFrameContent.onMouseModeOff());
    }

    // ---- The Display place's keyboard ---------------------------------------------------------

    /**
     * The keyboard key, on the Display place with mouse mode on: the keyboard comes to the front
     * of the frame, or goes back behind the pad. True when it was taken, and the caller should
     * leave the keyboard itself alone.
     */
    boolean toggleDisplayFrameKeyboard() {
        // With the phone's keyboard chosen for this place, the key is that keyboard's: the pad
        // keeps the frame it stands in and nothing is swapped.
        if (mDisplayKeys.toggleDisplaySystemKeyboard()) return true;
        if (!mTouchpad.isDisplayTouchpadFrame()) return false;
        mTouchpad.applyDisplayFrameDecision(mFrameContent.onKeyboardKey());
        return true;
    }

    /** A small mouse in the status row while mouse mode is on; gone the moment it is off. */
    private void syncMouseModeMark() {
        com.termux.app.statusbar.StatusBarWidgetView mark = findViewById(R.id.terminal_status_widget_mouse);
        if (mark == null) return;
        if (mFrameContent.isMouseMode() && mark.getTag() == null) {
            mark.setTag("wired");
            mark.setColorRole(com.termux.app.statusbar.StatusBarWidgetView.ColorRole.PRIMARY);
            mark.setIconResource(R.drawable.ic_rl_mouse);
            mark.setValue("");
            mark.setOnClickListener(v -> toggleMouseMode());
        }
        mark.setVisibility(mFrameContent.isMouseMode() ? View.VISIBLE : View.GONE);
        mStatusBar.syncRowDots();
        mStatusBar.syncStatusBarInk();
    }

    public boolean isMouseMode() {
        return mFrameContent.isMouseMode();
    }

    /** The parting of a split keyboard in the keyboard view's pixels; null when it has none. */
    @Nullable
    /**
     * Dresses the touchpad for where it stands and answers its layout: in a split keyboard's
     * parting it takes the seat a key would take there, with the caps' radius and fill, so it
     * reads as one more key on the keyboard's background; anywhere else it is the panel over the
     * whole frame.
     */
    @NonNull
    private final int[] mDropTargetBandAt = new int[2];

    /**
     * Where the Remove and Uninstall targets sit while an icon is dragged, on screen: the status
     * bar, while it runs along the top of the screen. False otherwise; they then sit just under
     * the system bar.
     */
    private boolean dropTargetBand(@NonNull android.graphics.Rect out) {
        View bar = findViewById(R.id.terminal_window_bar_host);
        if (bar == null || !bar.isShown() || bar.getHeight() <= 0) return false;
        bar.getLocationOnScreen(mDropTargetBandAt);
        View root = bar.getRootView();
        if (mDropTargetBandAt[1] + bar.getHeight() / 2 > root.getHeight() / 2) return false;
        out.set(mDropTargetBandAt[0], mDropTargetBandAt[1],
            mDropTargetBandAt[0] + bar.getWidth(), mDropTargetBandAt[1] + bar.getHeight());
        return true;
    }

    private void createWidgetPaneController() {
        View view = findViewById(R.id.widget_pane);
        // Terminal-only installs keep the status pane (clock, status) but not the widget grid.
        if (view != null && !isWidgetsPageWanted()) {
            view.setVisibility(View.GONE);
            return;
        }
        if (!(view instanceof com.termux.app.launcher.widget.WidgetPaneView)
            || mWidgetHostController == null) return;
        mWidgetPaneController = new com.termux.app.launcher.widget.WidgetPaneController(
            (com.termux.app.launcher.widget.WidgetPaneView) view, mWidgetHostController,
            new com.termux.app.launcher.widget.WidgetPaneController.Host() {
                @Override public boolean reducedMotion() { return isReducedMotionEnabled(); }
                // Over the dock the page offers no cell: an app from the drawer let go there is
                // pinned by the dock's row (dockDrop), never put on the page.
                private final int[] dockAt = new int[2];
                @Override public boolean isOverDock(float rawX, float rawY) {
                    View dock = mSuggestionBarView;
                    if (dock == null || !dock.isShown()) return false;
                    int[] at = dockAt;
                    dock.getLocationOnScreen(at);
                    return rawX >= at[0] && rawX < at[0] + dock.getWidth()
                        && rawY >= at[1] && rawY < at[1] + dock.getHeight();
                }
                // The widget grid lives on the wall's Widgets page, and nowhere else.
                @Override public boolean isWidgetSurfaceShowing() {
                    return mPages.isCommitted(com.termux.app.page.PageKind.HOME);
                }
                @Override public void captureWidgetSurfaceOrigin() {
                    // The page is where it was and where it will be; there is nothing to keep.
                }
                @Override public void restoreWidgetSurfaceOrigin() {
                    if (mPaneWallController != null) {
                        mPaneWallController.goTo(com.termux.app.page.PageKind.HOME, false);
                    }
                }
                @Override public void onWidgetEditSessionChanged(boolean editing) {
                    // The page's border tab belongs to the mode: the grid's size while a widget
                    // is being edited, the settings and the pencil otherwise.
                    if (mPaneWallController != null && mPaneWallController.widgetsPage() != null) {
                        mPaneWallController.widgetsPage().applyWidgetEditing(editing);
                    }
                    mTerminalWidgets.onWidgetEditing(editing);
                }
                // A Terminal widget whose shell is busy asks before it goes, as a window does.
                @Override public void confirmWidgetRemoval(int appWidgetId, @NonNull Runnable remove) {
                    mTerminalWidgets.confirmRemoval(TermuxActivity.this, appWidgetId, remove);
                }
                // Home's swipe between Home pages pans the wallpaper over the row, per frame; a
                // Home page added or removed lands here too as the page re-renders at rest.
                @Override public void onHomePageShifted() {
                    syncWallpaperParallax();
                    // Between two Home pages that dress the chrome apart, it morphs with the
                    // slide (#173 slice E).
                    mCrossingController.syncHomePagesTravel();
                }
                // The user's swipe inside the Home run: the wall steps onto that page's cell.
                @Override public void onHomePageTurnedByUser() {
                    if (mPaneWallController != null) mPaneWallController.onHomePageTurned();
                }
                @Override public void onWidgetPageRendered() {
                    // A Home page added or removed changes the bar's dots, and the pages' Floats.
                    if (mControlBar != null) mControlBar.onFrontChanged();
                    if (mTilingDesktop != null) mTilingDesktop.onHomePagesChanged();
                    refreshPageGlyphs();
                    // A widget added or removed may change which Home page holds a terminal.
                    mHomeTerminalPageId = -1;
                    // A Terminal widget gone from Home takes its shell with it, however it went.
                    mTerminalWidgets.reconcile();
                    // Another Home page in front may wear another ground, on screen or beside it.
                    refreshGroundStrip();
                    // The badge, the chips and the summary read the page: a new page or a new
                    // widget changes all three.
                    if (!mPages.isCommitted(com.termux.app.page.PageKind.HOME)) return;
                    // The Home page in front may wear a page layout of its own (ADR 0015 §3):
                    // landing on another one re-arranges the chrome. The morph is slice E.
                    // Re-arranging costs a frame of 70-160 ms, which would eat a page settle
                    // under way (#173): it waits for the settle to land, once however many
                    // renders ask in the meantime.
                    if (mWidgetPaneController != null
                            && mWidgetPaneController.isHomePageSettling()) {
                        if (!mChromeArrangementAfterSettle) {
                            mChromeArrangementAfterSettle = true;
                            mWidgetPaneController.runWhenHomePageSettles(() -> {
                                mChromeArrangementAfterSettle = false;
                                // A crossing between the two Home pages lands first, so the
                                // landed layout is what is applied (slice E).
                                mCrossingController.landHomePagesCrossing();
                                syncChromeArrangement();
                            });
                        }
                    } else {
                        syncChromeArrangement();
                    }
                    syncPlaceBar();
                    com.termux.app.terminal.TerminalWindowBar chips =
                        findViewById(R.id.terminal_window_bar);
                    if (chips != null && isSplitPanesEnabled()) syncWindowBarItems(chips);
                }
                // A provider text input inside a widget follows the toolbar text-input seam: the
                // in-app keyboard yields (clearing its disable-IME window flags), then the editor
                // takes focus and the system IME. Closing restores the prior arrangement.
                @Override public void onWidgetEditorFocused(@NonNull View editor) {
                    if (mInAppKeyboard != null && mInAppKeyboard.isEnabled()) {
                        mInAppKeyboard.beginExternalTextInput();
                    }
                    onSystemImeRequested();
                    editor.post(() -> {
                        if (!editor.hasFocus()) editor.requestFocus();
                        KeyboardUtils.showSoftKeyboard(TermuxActivity.this, editor);
                    });
                }
                @Override public void onWidgetEditorClosed() {
                    if (mInAppKeyboard != null) mInAppKeyboard.endExternalTextInput();
                }
                @Override @NonNull
                public com.termux.app.launcher.widget.builtin.BuiltinWidgetStyle.Numerals builtinWidgetNumerals() {
                    return com.termux.app.launcher.widget.builtin.BuiltinWidgetStyle.Numerals.fromKey(
                        mPreferences == null ? null : mPreferences.getAppLauncherBuiltinWidgetStyle());
                }
                @Override public void onHomeLongPressed(float rawX, float rawY) {
                    // Under the Terl desktop, holding empty Home opens edit mode (ADR 0040).
                    if (isTerlDesktopOn()) {
                        mEditMode.open(null);
                        if (mFirstRunTips != null) mFirstRunTips.onGesture(com.termux.app.tips.Tip.HOME_HOLD);
                        return;
                    }
                    mSheets.showHomeActionsSheet(rawX, rawY);
                }
                // A folder on Home opens the dock's popup, in the dock's look, and renames through the
                // dock's own focusless intake.
                @Override @Nullable
                public com.termux.app.launcher.popup.AnchoredMenuTheme homeMenuTheme() {
                    return mSuggestionBarView == null ? null : mSuggestionBarView.menuTheme();
                }
                // A hold on a Home icon opens the dock's App menu; the finger travelling on closes it.
                @Override public boolean showHomeAppMenu(
                        @NonNull com.termux.app.launcher.model.LauncherAppEntry entry,
                        @NonNull View anchor, @NonNull Runnable removeFromHome) {
                    if (mSuggestionBarView == null) return false;
                    mSuggestionBarView.showHomeAppContextPopup(anchor, entry, removeFromHome);
                    return true;
                }
                @Override public void dismissHomeAppMenu() {
                    if (mSuggestionBarView != null) mSuggestionBarView.dismissContextPopups();
                }
                @Override public boolean homeDropTargetBand(@NonNull android.graphics.Rect out) {
                    return dropTargetBand(out);
                }
                @Override @Nullable public TerminalDress.Source homeDropTargetDress() {
                    return terminalDressSource();
                }
                // A Home icon dragged onto the dock goes into its pinned row.
                @Override @Nullable public com.termux.app.dock.DockDrop dockDrop() {
                    return mSuggestionBarView == null ? null : mSuggestionBarView.dockDrop();
                }
                @Override public void beginHomeFolderRename(@NonNull String name,
                        @NonNull FolderRenameTitleView title,
                        @NonNull com.termux.app.launcher.widget.WidgetPaneController.HomeFolderRenameTarget target) {
                    mSheets.beginHomeFolderRename(name, title, target);
                }
                @Override public void cancelHomeFolderRename() { mSheets.cancelFolderRename(); }
                @Override public boolean isFolderRenameTypingTouch(float rawX, float rawY) {
                    return mSheets.isFolderRenameTypingTouch(rawX, rawY);
                }
                // The palette gesture starts on the page's free area: Home has no bottom border.
                @Override public void onHomePaletteSwipe(boolean up) {
                    if (mPages.isCommitted(com.termux.app.page.PageKind.HOME)) runHomeSwipe(up);
                }
                // Swipe up set to the drawer: the plane follows the finger like the dock's pull.
                // The drag runs on a mirrored axis (the pull is measured downward), so up is
                // positive travel and the release velocity flips with it.
                @Override public void onHomeDrawerPressed() {
                    if (mPages.isCommitted(com.termux.app.page.PageKind.HOME) && mSheets.canWarmAppDrawer()) {
                        getAppDrawerController().warmUp();
                    }
                }
                @Override public boolean onHomeDrawerDragBegin(float claimRawY) {
                    if (!mPages.isCommitted(com.termux.app.page.PageKind.HOME) || mSheets.isAppDrawerEngaged()) return false;
                    PlaceLayout.Edge edge = arrangement().appsEdge();
                    com.termux.app.launcher.drawer.AppDrawerController drawer = getAppDrawerController();
                    drawer.beginFollowDrag(-claimRawY, AppDrawerPullGeometry.pullFor(edge),
                        AppDrawerPullGeometry.seedFor(edge));
                    return drawer.isDragging();
                }
                @Override public void onHomeDrawerDrag(float rawY) {
                    getAppDrawerController().updateDrag(-rawY);
                }
                @Override public void onHomeDrawerDragEnd(float velocityYPxPerSec) {
                    getAppDrawerController().endDrag(-velocityYPxPerSec);
                }
                @Override public void onHomeDrawerDragCancel() {
                    getAppDrawerController().cancelDrag();
                }
                // Swipe down set to the notifications: the shade follows the finger when it can.
                @Override public boolean onHomePullDownBegin(float rawX, float rawY, long time) {
                    return beginHomeShadePull(rawX, rawY, time);
                }
                @Override public void onHomePullDown(float rawX, float rawY, long time) {
                    if (mShadePull != null) mShadePull.move(rawX, rawY, time);
                }
                @Override public void onHomePullDownEnd(float rawX, float rawY, long time,
                                                        int releaseWay) {
                    if (mShadePull != null) mShadePull.end(rawX, rawY, time, releaseWay);
                }
                @Override public void onHomePullDownCancel() {
                    if (mShadePull != null) mShadePull.cancel();
                }
                @Override public void onHomeDoubleTap() {
                    if (mPages.isCommitted(com.termux.app.page.PageKind.HOME)) runHomeGesture(
                        com.termux.app.launcher.home.HomeGestures.Gesture.DOUBLE_TAP);
                }
                @Override public void onHomePinchIn() {
                    if (mPages.isCommitted(com.termux.app.page.PageKind.HOME)) openOverviewDoor(false);
                }
                @Override public void onHomeTwoFingerSwipe(boolean up) {
                    if (mPages.isCommitted(com.termux.app.page.PageKind.HOME)) runHomeGesture(up
                        ? com.termux.app.launcher.home.HomeGestures.Gesture.TWO_FINGER_UP
                        : com.termux.app.launcher.home.HomeGestures.Gesture.TWO_FINGER_DOWN);
                }
                @Override @NonNull
                public com.termux.app.launcher.widget.builtin.BuiltinWidgetServices.Host builtinWidgetHost() {
                    return new com.termux.app.launcher.widget.builtin.BuiltinWidgetServices.Host() {
                        @Override public void requestCalendarPermission() {
                            String permission = android.Manifest.permission.READ_CALENDAR;
                            // Asked before and refused for good: the system shows nothing for a
                            // second request, so the app's own settings page is the way in.
                            if (mWidgetCalendarAsked
                                && !androidx.core.app.ActivityCompat
                                    .shouldShowRequestPermissionRationale(TermuxActivity.this, permission)) {
                                openAppSettingsPage();
                                return;
                            }
                            mWidgetCalendarAsked = true;
                            androidx.core.app.ActivityCompat.requestPermissions(TermuxActivity.this,
                                new String[] {permission}, REQUEST_CODE_WIDGET_CALENDAR);
                        }
                        @Override public void onSystemImeRequested() {
                            if (mInAppKeyboard != null && mInAppKeyboard.isEnabled()) {
                                mInAppKeyboard.beginExternalTextInput();
                            }
                            TermuxActivity.this.onSystemImeRequested();
                        }
                        @Override public void onSystemImeReleased() {
                            View focus = getCurrentFocus();
                            KeyboardUtils.hideSoftKeyboard(TermuxActivity.this,
                                focus != null ? focus : getWindow().getDecorView());
                            if (mInAppKeyboard != null) mInAppKeyboard.endExternalTextInput();
                        }
                        @Override public boolean openCommandWindow(@NonNull java.util.List<String> command,
                                                                   @Nullable String title) {
                            if (TermuxActivity.this.openCommandWindow(command, null, title, true) == null) {
                                return false;
                            }
                            // The window is the point: the wall turns to the terminal to show it.
                            if (mPaneWallController != null) {
                                mPaneWallController.goTo(com.termux.app.page.PageKind.TERMINAL,
                                    isVisible());
                            }
                            return true;
                        }
                        @Override @Nullable public android.graphics.Typeface monoTypeface() {
                            TerminalView view = getTerminalView();
                            return view == null ? null : view.getTerminalTypeface();
                        }
                        @Override public void attachTerminalWidget(int widgetId,
                                @NonNull com.termux.app.launcher.widget.builtin.TerminalWidgetView widget) {
                            mTerminalWidgets.attach(widgetId, widget);
                        }
                        @Override public void detachTerminalWidget(int widgetId,
                                @NonNull com.termux.app.launcher.widget.builtin.TerminalWidgetView widget) {
                            mTerminalWidgets.detach(widgetId, widget);
                        }
                        @Override public void restartTerminalWidget(int widgetId) {
                            mTerminalWidgets.restart(widgetId);
                        }
                    };
                }
            });
        // The grid preference was applied in onCreate, before this controller existed, straight
        // to the host; now the pane can hold it to what the wall fits, and re-cap on layout.
        applyWidgetGridPreference();
        applyHomeSettings();
    }

    /**
     * A tap, or a close ({@code close}, the × on a chip), on the window chip at {@code index} of
     * {@code surface}: the bar's row or its column, or a Wall strip tile. The
     * window chips say what it means ({@link
     * com.termux.app.chrome.WindowChips#tap}, {@link com.termux.app.chrome.WindowChips#close}),
     * each surface counting its own index, and this carries it out: a window is brought in front
     * (the display window's as any other's, at its place in the row), the Terminal sliding in
     * first from Home's dock or the bar seen from Home; a float comes back on its Home page, the
     * wall travelling Home first from the Terminal's bar; a window closes, a terminal
     * window taking its panes with it and the display window stopping its display ({@link
     * #closeDisplayWindowFromRow}); a float's shell ends.
     */
    private void onWindowChip(@NonNull com.termux.app.chrome.WindowChips.Surface surface,
                              int index, boolean close) {
        if (surface == com.termux.app.chrome.WindowChips.Surface.BAR && !isSplitPanesEnabled())
            return;
        // A Wall strip tile of a Linux window carries its row place (#392).
        if (surface == com.termux.app.chrome.WindowChips.Surface.WALL_STRIP
                && com.termux.app.dock.WallStripModel.isLinuxChip(index)) {
            onLinuxWindowChip(com.termux.app.dock.WallStripModel.placeOfLinuxChip(index), close);
            return;
        }
        if (surface == com.termux.app.chrome.WindowChips.Surface.BAR && !isDisplayWindowInFront()) {
            // The bar's chips are row places, Linux windows' among them, then minimised Linux
            // windows (#392); the terminal windows' meaning is read by their own index.
            if (onLinuxWindowChip(index, close)) return;
            int terminal = terminalAtPlace(index);
            if (terminal < 0) return;
            index = terminal;
        }
        if (surface == com.termux.app.chrome.WindowChips.Surface.BAR && isDisplayWindowInFront()) {
            // #192: on a Display page the bar's chips are the display's apps.
            if (!mDisplayServer.hasWindowList()) return;
            com.termux.app.chrome.DisplayAppChips apps = displayAppChips();
            int id = close ? apps.closeWindowId(index) : apps.tapWindowId(index);
            if (id < 0) return;
            if (close) mDisplayServer.closeWindowById(id); else mDisplayServer.activateWindow(id);
            return;
        }
        if (mPaneController == null) return;
        com.termux.app.chrome.WindowChips<com.termux.app.terminal.TerminalPaneController.Window>
            chips = windowChips();
        com.termux.app.chrome.WindowChips.Meaning<
            com.termux.app.terminal.TerminalPaneController.Window> meaning =
                close ? chips.close(surface, index) : chips.tap(surface, index);
        switch (meaning.action) {
            case SHOW_WINDOW:
                if (meaning.travel) {
                    if (mPaneWallController == null) return;
                    mPaneWallController.goTo(com.termux.app.page.PageKind.TERMINAL,
                        isVisible());
                }
                showRowWindow(placeOfTerminal(meaning.row));
                return;
            case RESTORE_FLOAT:
                // showHomeFloat travels Home itself when the wall is elsewhere (meaning.travel).
                if (meaning.window != null) showHomeFloat(meaning.window);
                return;
            case CLOSE_WINDOW:
                closeRowWindow(placeOfTerminal(meaning.row));
                return;
            case CLOSE_FLOAT: {
                // A float's × closes it as its titlebar's Close does: its shell ends.
                TerminalSession shell = meaning.window == null ? null
                    : mPaneController.windowActiveSession(meaning.window);
                if (shell != null) shell.finishIfRunning();
                return;
            }
            default:
        }
    }

    // ---- Linux windows (spec #384): the seam is LinuxWindowsController; this only lends it the wall.

    /** Builds the Linux windows' controller and hands its view to the wall: Wayland builds only. */
    private void attachLinuxWindows() {
        if (!com.termux.BuildConfig.WAYLAND_DISPLAY || mPaneWallController == null || mLinuxWindows != null) return;
        // Linux windows stand in the session's row since #392: a page a launcher before it left goes.
        wallPagesStore().transform(com.termux.app.wall.WallPages::withoutLinuxWindows);
        mLinuxWindows = new com.termux.app.wayland.LinuxWindowsController(this,
            new com.termux.app.wayland.LinuxWindowsController.Host() {
                @Override public void addWindow(long id, boolean goTo) {
                    if (mTilingDesktop != null) {
                        // Every kind is a tile (#419): the app's window opens in the tiling desktop.
                        com.termux.app.wayland.LinuxWindowsController.Chip chip =
                            mLinuxWindows == null ? null : mLinuxWindows.chip(id);
                        mTilingDesktop.linuxWindowOpened(id, chip == null ? null : chip.appId,
                            chip == null ? null : chip.label, !goTo);
                        return;
                    }
                    // No current session: the one shown next takes it; with no session at all it
                    // waits for the first (syncLinuxFront places it).
                    int at = com.termux.app.terminal.LinuxWindowHoming.sessionForNew(
                        mWSessions.indexOf(mCurrentWSession), mWSessions.size());
                    if (at < 0) {
                        mUnplacedLinuxWindows.add(id);
                        return;
                    }
                    WSession ws = mWSessions.get(at);
                    ws.row.add(ws.windows, ws.current, id);
                    if (goTo && ws == mCurrentWSession) goToLinuxWindow(id);
                    else onLinuxRowChanged();
                }
                @Override public void removeWindow(long id) {
                    if (mTilingDesktop != null) {
                        // Leaving the row for its tiling window is not going away.
                        if (mLinuxWindows == null || !mLinuxWindows.knows(id)) mTilingDesktop.linuxWindowGone(id);
                        return;
                    }
                    removeLinuxWindow(id);
                }
                @Override public void removeAllWindows() {
                    if (mTilingDesktop != null) {
                        mTilingDesktop.linuxWindowsGone();
                        return;
                    }
                    mUnplacedLinuxWindows.clear();
                    for (WSession ws : mWSessions) ws.row.clearLinux();
                    if (mCurrentWSession != null) mCurrentWSession.row.clearLinux();
                    onLinuxRowChanged();
                }
                @Nullable @Override public Object placeOf(long id) {
                    if (mTilingDesktop != null) return null;
                    // The place carries its session: the window goes back to that row.
                    WSession ws = sessionWithLinuxWindow(id);
                    if (ws == null) return null;
                    return new com.termux.app.terminal.LinuxWindowHoming.Minimised<>(ws,
                        ws.row.placeOf(ws.windows, id));
                }
                @SuppressWarnings("unchecked")
                @Override public void restoreWindow(long id, @Nullable Object place) {
                    if (mTilingDesktop != null) {
                        if (!mTilingDesktop.showLinuxWindow(id)) addWindow(id, true);
                        return;
                    }
                    com.termux.app.terminal.LinuxWindowHoming.Minimised<WSession,
                        com.termux.app.terminal.TerminalPaneController.Window> from =
                        place instanceof com.termux.app.terminal.LinuxWindowHoming.Minimised
                            ? (com.termux.app.terminal.LinuxWindowHoming.Minimised<WSession,
                                com.termux.app.terminal.TerminalPaneController.Window>) place
                            : null;
                    WSession origin = from == null ? null : from.session;
                    WSession target = com.termux.app.terminal.LinuxWindowHoming.sessionForRestore(
                        origin, mWSessions, mCurrentWSession);
                    if (target == null) {
                        mUnplacedLinuxWindows.add(id);
                        return;
                    }
                    if (from != null && com.termux.app.terminal.LinuxWindowHoming.atOldPlace(
                            origin, target)) {
                        target.row.restore(target.windows, target.current, id, from.place);
                    } else {
                        target.row.addAtEnd(target.windows, id);
                    }
                    // A restore is asked for by a tap, so the window is shown: its session comes
                    // in front first when another one is.
                    if (target != mCurrentWSession) {
                        activateBrowserSession(mWSessions.indexOf(target));
                    }
                    if (target == mCurrentWSession) goToLinuxWindow(id);
                    else onLinuxRowChanged();
                }
                @Override public void goToWindow(long id) {
                    if (mTilingDesktop != null) mTilingDesktop.showLinuxWindow(id);
                    else goToLinuxWindow(id);
                }
                @Override public void notice(@NonNull String text) { showToast(text, true); }
                @Override public void chipsChanged() {
                    if (mTilingDesktop != null && mLinuxWindows != null) {
                        // An app id or name learnt late is kept by its tiling window (#419).
                        for (long id : mTilingDesktop.linuxWindowIds()) {
                            com.termux.app.wayland.LinuxWindowsController.Chip chip = mLinuxWindows.chip(id);
                            if (chip != null) mTilingDesktop.linuxWindowChanged(id, chip.appId, chip.label);
                        }
                    }
                    refreshTerminalWindowBarChips();
                }
                @Override public void attentionChanged() {
                    if (mPaneController != null) mPaneController.repaintLinuxPaneBorders();
                }
                @Override public void offerForceClose(@NonNull String appName, @NonNull Runnable forceClose) {
                    com.termux.app.notice.AppNotice.undoable(TermuxActivity.this,
                        getString(R.string.linux_window_force_close_title, appName),
                        getString(R.string.linux_window_force_close_hint), forceClose,
                        com.termux.app.notice.AppNoticeHostView.HOLD_LONG_MS, R.drawable.ic_rl_close);
                }
                @Nullable @Override public String appName(@NonNull String appId) {
                    com.termux.app.x11.X11WindowIconResolver apps = displayWindowIcons();
                    return apps == null ? null : apps.nameFor(appId);
                }
                @NonNull @Override public com.termux.app.wayland.LinuxWindowIcons.Lookup iconLookup() {
                    return mLinuxIconLookup;
                }
                @Nullable @Override public com.termux.app.wayland.LinuxCarry.Host carryHost() {
                    return linuxCarryHost();
                }
                @NonNull @Override public com.termux.app.page.PageHost pageHost() { return mPageHost; }
                @Override public void keepScreenOn(boolean on) {
                    mScreenOnReasons.set(com.termux.app.window.ScreenOnReasons.LINUX_WINDOW, on);
                }
            });
        mLinuxWindows.setWindowMenuListener(this::showLinuxWindowControls);
        mLinuxWindows.setReplayEndedListener(() -> {
            if (mTilingDesktop != null) mTilingDesktop.linuxReplayEnded();
        });
        mLinuxWindows.setPasteShortcuts(appId -> linuxPasteShortcuts().withShift(appId));
        if (mPaneController != null) {
            mPaneController.setLinuxPanes(new com.termux.app.terminal.TerminalPaneController.LinuxPanes() {
                @Nullable @Override public com.termux.app.terminal.PaneContentFrame frameOf(long windowId) {
                    return mLinuxWindows == null ? null : mLinuxWindows.paneFrame(windowId);
                }
                @Override public void focused(long windowId) {
                    if (mLinuxWindows == null) return;
                    mLinuxWindows.setPaneFocus(windowId);
                    // The launcher's keyboard types into the focused pane, whatever its kind.
                    restoreInAppKeyboardTypingClaim();
                }
                @Override public void orphaned(long windowId) {
                    if (mLinuxWindows != null) mLinuxWindows.releasePane(windowId, true);
                }
                @Override public void close(long windowId) {
                    if (mLinuxWindows != null) mLinuxWindows.closeChip(windowId);
                }
                @Override public boolean asking(long windowId) {
                    return mLinuxWindows != null && mLinuxWindows.asksForUser(windowId);
                }
                @Override public boolean scales(long windowId) {
                    return mLinuxWindows != null && mLinuxWindows.windowTakesScale(windowId);
                }
                @Override public void minimise(long windowId) {
                    if (mLinuxWindows != null) mLinuxWindows.minimisePaneWindow(windowId);
                }
                @Override public void showScale(long windowId) {
                    if (mLinuxWindows != null) mLinuxWindows.showScaleRail(windowId);
                }
                @Override public boolean isDesktop(long windowId) {
                    return mLinuxWindows != null && mLinuxWindows.windowIsDesktop(windowId);
                }
                @Override public void fullScreen(long windowId) {
                    if (mLinuxWindows != null) mLinuxWindows.fullScreenWindow(windowId);
                }
                @Override public void floatDocked(long windowId) {
                    // Dock: the Float's window stands in the row after the current one, and the wall goes there.
                    if (mLinuxWindows == null) return;
                    mLinuxWindows.releasePane(windowId, true);
                    goToLinuxWindow(windowId);
                }
            });
        }
        mLinuxWindows.setPaneHost(new com.termux.app.wayland.LinuxPaneHost() {
                @Override public void removePane(long id) {
                    if (mTilingDesktop != null) {
                        // A tiling window's frame (#419): its window closes once the app's is gone.
                        if (mLinuxWindows == null || !mLinuxWindows.knows(id)) mTilingDesktop.linuxWindowGone(id);
                        return;
                    }
                    if (mPaneController != null) mPaneController.removeLinuxPane(id);
                }
                @Override public void paneTouched(long id) {
                    // A tiling window's frame takes its own presses (#419).
                    if (mTilingDesktop != null) return;
                    if (mPaneController != null) mPaneController.focusLinuxPane(id);
                }
        });
        mLinuxWindows.page().setTopInsetPx(mStatusRowRoomPx);
        mPaneWallController.setLinuxWindows(mLinuxWindows.page(), mLinuxWindows, this::syncLinuxFront);
        com.termux.app.wayland.WaylandAppRunner.shared(this).setWindowsSurface(mLinuxWindows::showWindow);
        mLinuxWindows.start();
    }

    /** Scratch for the carry's wall span: a move reads it, so it allocates nothing. */
    private final int[] mCarryWallAt = new int[2];
    private final float[] mCarryFloatRoom = new float[4];

    /** What a carried Linux window asks of the wall and the row (#386). */
    @NonNull
    private com.termux.app.wayland.LinuxCarryFloatHost linuxCarryFloatHost() {
        return new com.termux.app.wayland.LinuxCarryFloatHost() {
            @Override public boolean floatRoom(@NonNull float[] out) {
                // Only the Home page in front takes a Float; the layer is made on the first ask.
                return mPaneWallController != null
                    && mPaneWallController.currentPage() == com.termux.app.page.PageKind.HOME
                    && canOpenHomeFloat() && mPaneController.linuxFloatBounds(0f, 0f, out, null);
            }
            @Override public void floatBoundsAt(float x, float y, @NonNull float[] out) {
                if (mPaneController != null) mPaneController.linuxFloatBounds(x, y, mCarryFloatRoom, out);
            }
        };
    }

    private com.termux.app.wayland.LinuxCarry.Host linuxCarryHost() {
        return new com.termux.app.wayland.LinuxCarry.Host() {
            @NonNull @Override public android.view.ViewGroup overlay() {
                return com.termux.app.window.WindowLayers.host(TermuxActivity.this,
                    com.termux.app.window.WindowLayer.NOTICES);
            }
            @Override public int frontPlace() {
                return mPaneWallController != null
                    && mPaneWallController.currentPage() == com.termux.app.page.PageKind.TERMINAL
                    ? rowCurrentIndex() : -1;
            }
            @Override public int placeCount() { return rowWindowCount(); }
            @Override public int placeOf(long id) {
                WSession ws = mCurrentWSession;
                return ws == null ? -1 : ws.row.indexOfLinux(ws.windows, id);
            }
            @Override public void wallSpan(@NonNull float[] out) {
                if (mPaneWallController == null) {
                    out[0] = 0f;
                    out[1] = 0f;
                    return;
                }
                com.termux.app.wall.PaneWallLayout wall = mPaneWallController.wall();
                wall.getLocationInWindow(mCarryWallAt);
                out[0] = mCarryWallAt[0];
                out[1] = mCarryWallAt[0] + wall.getWidth();
            }
            @Override public boolean canPage(int steps) {
                return mPaneWallController != null && mPaneWallController.wall().canPage(steps);
            }
            @Override public void page(int steps) {
                if (mPaneWallController != null) mPaneWallController.wall().pageOnce(steps);
            }
            @Override public void drop(long id, int from, int to) {
                moveWindow(from, to);
                goToLinuxWindow(id);
            }
            @Override public void putBack(long id) {
                // A pane never left its split: nothing to bring back.
                if (mPaneController != null && mPaneController.hasLinuxPane(id)) return;
                goToLinuxWindow(id);
            }
            @Override public boolean inPane(long id) {
                return mPaneController != null && mPaneController.hasLinuxPane(id);
            }
            @Override public boolean paneAt(long id, float x, float y, @NonNull float[] out) {
                // Only the Terminal's own window in front has panes to split; a Linux window's page does not.
                return mPaneController != null && mLinuxWindows != null && linuxWindowInFront() == 0L
                    && mPaneWallController != null
                    && mPaneWallController.currentPage() == com.termux.app.page.PageKind.TERMINAL
                    && mPaneController.paneBoundsAt(id, x, y, out);
            }
            @Override public void dropSplit(long id, float x, float y, int side) {
                if (mPaneController == null || mLinuxWindows == null
                    || mLinuxWindows.takeIntoPane(id) == null) {
                    return;
                }
                if (!mPaneController.dropLinuxPane(id, x, y, side)
                    && !mPaneController.hasLinuxPane(id)) {
                    mLinuxWindows.releasePane(id, true);
                }
            }
            @Nullable @Override public com.termux.app.wayland.LinuxCarryFloatHost floatHost() {
                return linuxCarryFloatHost();
            }
            @Override public void dropFloat(long id, float x, float y) {
                if (mPaneController == null || mLinuxWindows == null || !canOpenHomeFloat()) {
                    putBack(id);
                    return;
                }
                // From a split first: its pane leaves the tree, the window's page stays.
                if (mPaneController.hasLinuxPane(id)) mPaneController.removeLinuxPane(id);
                if (mLinuxWindows.takeIntoPane(id, true) == null) {
                    putBack(id);
                    return;
                }
                int page = mWidgetPaneController == null ? 0 : mWidgetPaneController.homePageIndex();
                if (mPaneController.openLinuxHomeFloat(id, page, x, y) == null) {
                    mLinuxWindows.releasePane(id, true);
                    goToLinuxWindow(id);
                }
            }
            @Override public void dropFromPane(long id, int to) {
                if (mPaneController == null || mLinuxWindows == null) return;
                mPaneController.removeLinuxPane(id);
                mLinuxWindows.releasePane(id, true);
                WSession ws = mCurrentWSession;
                int from = ws == null ? -1 : ws.row.indexOfLinux(ws.windows, id);
                if (from >= 0) moveWindow(from, to);
                goToLinuxWindow(id);
            }
        };
    }

    /** The room the Terminal's top pane holds for the status row; a Linux window's page holds the same. */
    private int mStatusRowRoomPx;

    /** The Linux window {@link #syncLinuxFront} last stood in front; 0 for none. */
    private long mLinuxFrontSynced;

    /** Linux windows that opened while no session existed: they join the first session that appears. */
    private final java.util.ArrayList<Long> mUnplacedLinuxWindows = new java.util.ArrayList<>();

    /**
     * Stands the Linux window in front of the current row, if any, in the Terminal page's place,
     * and tells the Linux windows which one the view shows and whether it holds its surface: the
     * one in front, else one beside it, within a row place of the front ({@code
     * LinuxWindowRow.holdsSurface} over row places, #392). Run on every landing and row change.
     */
    private void syncLinuxFront() {
        if (mLinuxWindows == null || mPaneWallController == null) return;
        WSession ws = mCurrentWSession;
        if (ws != null && !mUnplacedLinuxWindows.isEmpty()) {
            for (long id : mUnplacedLinuxWindows) ws.row.add(ws.windows, ws.current, id);
            mUnplacedLinuxWindows.clear();
        }
        long front = linuxWindowInFront();
        int frontPlace = rowCurrentIndex();
        long bound = front;
        if (bound == 0L && ws != null && ws.row.hasLinux()) {
            long after = ws.row.linuxAt(ws.windows, frontPlace + 1);
            bound = after != 0L ? after : ws.row.linuxAt(ws.windows, frontPlace - 1);
        }
        int boundPlace = bound == 0L || ws == null ? -1 : ws.row.indexOfLinux(ws.windows, bound);
        boolean terminalPage = mPaneWallController.currentPage() == com.termux.app.page.PageKind.TERMINAL;
        mPaneWallController.setLinuxInFront(front != 0L);
        mLinuxWindows.bind(bound);
        mLinuxWindows.setTerminalShown(terminalPage);
        mLinuxWindows.setNearFront(terminalPage
            && com.termux.app.wayland.LinuxWindowRow.holdsSurface(bound != 0L, boundPlace, frontPlace));
        mLinuxWindows.setInFront(terminalPage && front != 0L);
        if (front == mLinuxFrontSynced) return;
        mLinuxFrontSynced = front;
        // The keys go to the Linux window in front, or back to the terminal.
        restoreInAppKeyboardTypingClaim();
    }

    /** A Linux window joined or left the row without paging: the wall, chips and drawer follow. */
    private void onLinuxRowChanged() {
        syncLinuxFront();
        refreshTerminalWindowBar();
        rebuildDrawerSessions();
    }

    /** The session whose row holds Linux window {@code id}; null for none. */
    @Nullable
    private WSession sessionWithLinuxWindow(long id) {
        if (mCurrentWSession != null && mCurrentWSession.row.contains(id)) return mCurrentWSession;
        for (WSession ws : mWSessions) if (ws.row.contains(id)) return ws;
        return null;
    }

    /**
     * Linux window {@code id} leaves its row: in front, its neighbour comes in front as when a
     * terminal window closes ({@code SessionRow#remove}).
     */
    private void removeLinuxWindow(long id) {
        mUnplacedLinuxWindows.remove(Long.valueOf(id));
        WSession ws = sessionWithLinuxWindow(id);
        if (ws == null) return;
        boolean wasFront = ws == mCurrentWSession && linuxWindowInFront() == id;
        int next = ws.row.remove(ws.windows, ws.current, id);
        if (wasFront && next >= 0 && mPaneController != null) {
            int terminal = ws.row.terminalAt(ws.windows, next);
            if (terminal >= 0 && terminal != ws.current) {
                ws.current = terminal;
                mPaneController.showWindow(ws.currentWindow());
            }
        }
        onLinuxRowChanged();
    }

    /** The wall pages to Linux window {@code id} in the current row: on the Terminal by a window switch, else there. */
    private void goToLinuxWindow(long id) {
        WSession ws = mCurrentWSession;
        if (ws == null || mPaneWallController == null) return;
        int place = ws.row.indexOfLinux(ws.windows, id);
        if (place < 0) return;
        if (mPaneWallController.currentPage() == com.termux.app.page.PageKind.TERMINAL) {
            showRowWindow(place);
            return;
        }
        showRowPlaceAcrossLinux(place, 0, 0f, com.termux.app.wall.WallParallax.ADJACENT);
        mPaneWallController.goTo(com.termux.app.page.PageKind.TERMINAL, isVisible());
    }

    /**
     * Brings row place {@code row} in front when a Linux window stands there or is in front now
     * (#392): the cover comes or goes in the Terminal page's place, the terminal window at
     * {@code row} shown behind it, travelling as a window switch from {@code direction}'s side
     * over {@code fromPx} (0: a whole page), at once for direction 0. A Linux window leaving is
     * pictured from its own pixels. False when neither end is a Linux window: the caller's
     * terminal path runs.
     */
    private boolean showRowPlaceAcrossLinux(int row, int direction, float fromPx, int fromWindow) {
        WSession ws = mCurrentWSession;
        if (ws == null || mPaneController == null || mLinuxWindows == null || !ws.row.hasLinux()) return false;
        if (row < 0 || row >= ws.row.count(ws.windows)) return false;
        long leaving = linuxWindowInFront();
        long arriving = ws.row.linuxAt(ws.windows, row);
        if (leaving == 0L && arriving == 0L) return false;
        boolean travels = direction != 0 && isVisible() && !isReducedMotionEnabled()
            && mPaneWallController != null
            && mPaneWallController.currentPage() == com.termux.app.page.PageKind.TERMINAL;
        if (!travels) {
            dropTerminalDepartureSnapshot();
        } else if (leaving != 0L) {
            // A software draw of the wall cannot read the Linux window's TextureView.
            dropTerminalDepartureSnapshot();
            mTerminalDepartureSnapshot = mLinuxWindows.departurePicture();
            mTerminalDepartureTranslucent = true;
            mTerminalDepartureSlidePx = 0f;
            mTerminalDepartureShiftPx = 0f;
        } else if (mTerminalDepartureSnapshot == null) {
            captureTerminalDeparture();
        }
        mStatusCardHost.dismiss();
        int terminal = ws.row.select(ws.windows, row);
        if (terminal >= 0) {
            ws.current = terminal;
            if (mPaneController.activeWindow() != ws.currentWindow()) {
                mPaneController.showWindow(ws.currentWindow());
            }
        }
        syncLinuxFront();
        refreshTerminalWindowBar();
        if (!travels) {
            rebuildDrawerSessions();
            return true;
        }
        View host = findViewById(R.id.terminal_surface_host);
        int width = host == null ? 0 : host.getWidth();
        float remaining = Math.abs(fromPx);
        long duration = com.termux.app.terminal.TerminalWindowBar.WINDOW_SWITCH_ANIMATION_DURATION_MS;
        if (width > 0 && remaining > 0f) {
            duration = Math.max(160L, Math.round(duration * Math.min(1f, remaining / width)));
        }
        duration = windowSwitchMs(duration);
        // A Linux window arriving draws from its own surface: no pane host draw to wait for.
        animateTerminalArrival(direction, true, duration, remaining, fromWindow, arriving == 0L,
            this::rebuildDrawerSessions);
        return true;
    }

    /** A Linux window's name on the bar and the page bar: its app's name, else a plain word. */
    @NonNull
    private String linuxWindowName(long id) {
        com.termux.app.wayland.LinuxWindowsController.Chip chip =
            mLinuxWindows == null ? null : mLinuxWindows.chip(id);
        return chip != null ? chip.label : getString(R.string.linux_window_app);
    }

    /**
     * The bar's chips in row order, Linux windows' among the terminal windows' (#392), then the
     * minimised Linux windows: the app's name and icon. Answers the chip selected: the row place
     * in front ({@code selected} is the terminal window's index).
     */
    private int addLinuxWindowItems(
            @NonNull java.util.List<com.termux.app.terminal.TerminalWindowBar.WindowItem> items,
            int selected) {
        WSession ws = mCurrentWSession;
        if (mLinuxWindows == null || ws == null) return selected;
        if (!ws.row.hasLinux() && mLinuxWindows.chips().isEmpty()) return selected;
        java.util.List<com.termux.app.terminal.TerminalWindowBar.WindowItem> terminals =
            new java.util.ArrayList<>(items);
        items.clear();
        int places = ws.row.count(ws.windows);
        for (int i = 0; i < places; i++) {
            int terminal = ws.row.terminalAt(ws.windows, i);
            if (terminal >= 0) {
                if (terminal < terminals.size()) items.add(terminals.get(terminal));
                continue;
            }
            items.add(linuxWindowItem(ws.row.linuxAt(ws.windows, i)));
        }
        for (com.termux.app.wayland.LinuxWindowsController.Chip chip : mLinuxWindows.chips()) {
            if (chip.minimised) items.add(linuxWindowItem(chip.id));
        }
        return selected < 0 ? selected : rowCurrentIndex();
    }

    @NonNull
    private com.termux.app.terminal.TerminalWindowBar.WindowItem linuxWindowItem(long id) {
        com.termux.app.wayland.LinuxWindowsController.Chip chip =
            mLinuxWindows == null ? null : mLinuxWindows.chip(id);
        String label = chip != null ? chip.label : getString(R.string.linux_window_app);
        String appId = chip != null ? chip.appId : "";
        boolean asking = chip != null && chip.attention;
        // The chip and the page mark ask the same owner for the icon; the app catalogue's icon
        // stands in while the window has none.
        android.graphics.Bitmap icon = mLinuxWindows == null ? null : mLinuxWindows.windowIcon(id,
            com.termux.app.wayland.LinuxWindowIcons.Form.SILHOUETTE);
        if (icon == null && !appId.isEmpty()) {
            com.termux.app.x11.X11WindowIconResolver apps = displayWindowIcons();
            if (apps != null) icon = apps.iconFor(appId);
        }
        return new com.termux.app.terminal.TerminalWindowBar.WindowItem(label, label, false, asking)
            .withIcon(icon);
    }

    /**
     * A tap or × on a bar chip that is a Linux window's: at its row place, or past the row a
     * minimised one's. False for a terminal window's chip.
     */
    private boolean onLinuxWindowChip(int index, boolean close) {
        WSession ws = mCurrentWSession;
        if (mLinuxWindows == null || mPaneController == null || ws == null) return false;
        int places = ws.row.count(ws.windows);
        long id = 0L;
        if (index >= 0 && index < places) {
            id = ws.row.linuxAt(ws.windows, index);
        } else if (index >= places) {
            int at = index - places;
            for (com.termux.app.wayland.LinuxWindowsController.Chip chip : mLinuxWindows.chips()) {
                if (!chip.minimised) continue;
                if (at-- == 0) {
                    id = chip.id;
                    break;
                }
            }
        }
        if (id == 0L) return false;
        if (close) mLinuxWindows.closeChip(id); else mLinuxWindows.tapChip(id);
        return true;
    }

    /** True when any pane of the current session's window at {@code index} is running something. */
    private boolean windowHasForegroundJob(int index) {
        if (mCurrentWSession == null || index < 0 || index >= mCurrentWSession.windows.size())
            return false;
        return windowHasForegroundJob(mCurrentWSession.windows.get(index));
    }

    /** True when any pane of {@code window} is running something. */
    private boolean windowHasForegroundJob(
            @NonNull com.termux.app.terminal.TerminalPaneController.Window window) {
        if (mPaneController == null || mWindowForegroundResolver == null) return false;
        java.util.List<TerminalSession> shells = mPaneController.shellsOf(window);
        Boolean[] idle = new Boolean[shells.size()];
        for (int i = 0; i < idle.length; i++) {
            com.termux.app.statusbar.WindowForegroundResolver.ForegroundInfo info =
                mWindowForegroundResolver.get(shells.get(i).getPid());
            idle[i] = info == null ? null : info.idle;
        }
        return com.termux.app.statusbar.WindowControlRouter.asksBeforeClose(idle);
    }

    /** Closing a window that is still working asks first; mirrors the sessions panel's wording. */
    private void confirmCloseWindow(int index) {
        if (mCurrentWSession == null || index < 0 || index >= mCurrentWSession.windows.size()) return;
        String name = mPaneController == null ? null
            : mPaneController.windowName(mCurrentWSession.windows.get(index));
        String title = name == null || name.isEmpty()
            ? getString(R.string.session_browser_window, index + 1) : name;
        new com.google.android.material.dialog.MaterialAlertDialogBuilder(this)
            .setTitle(getString(R.string.session_browser_close_title, title))
            .setMessage(R.string.termux_window_close_running_message)
            .setNegativeButton(android.R.string.cancel, null)
            .setPositiveButton(R.string.session_browser_close, (dialog, which) -> closeWindow(index))
            .show();
    }

    /** Which description the font toggle's pill carries: 0 none yet, 1 normal size, 2 Compact. */
    private int mFontToggleDescribed;

    /**
     * The status bar's font toggle pill: a tap switches the focused pane between its size and
     * Compact, a long press opens the settings holding the Compact size. It shows while its
     * switch is on and a pane is focused on Home or the Terminal, and its mark follows that
     * pane's state ({@link com.termux.app.statusbar.StatusStatsClusterPolicy#fontToggleShown}).
     */
    private void syncFontToggle() {
        com.termux.app.statusbar.StatusBarWidgetView pill =
            findViewById(R.id.terminal_status_widget_font_toggle);
        if (pill == null) return;
        if (pill.getTag() == null) {
            pill.setTag("wired");
            pill.setOnClickListener(v -> {
                TermuxTerminalViewClient client = mTermuxTerminalViewClient;
                if (client != null) client.toggleCompactFontSize();
            });
            pill.setOnLongClickListener(v -> {
                startActivity(com.termux.app.activities.SettingsActivity.createFragmentIntent(this,
                    com.termux.app.fragments.settings.termux.TermuxFontsPreferencesFragment.class,
                    R.string.termux_fonts_preferences_title, null,
                    com.termux.app.fragments.settings.termux.TermuxFontsPreferencesFragment
                        .KEY_COMPACT_SIZE));
                return true;
            });
        }
        boolean toggleable = mPaneController != null && mPaneController.canToggleActivePaneCompact();
        boolean shown = com.termux.app.statusbar.StatusStatsClusterPolicy.fontToggleShown(
            mPreferences != null && mPreferences.isStatusWidgetFontToggleEnabled(),
            currentWallPage(), toggleable);
        boolean compact = toggleable && mPaneController.isActivePaneCompact();
        int described = compact ? 2 : 1;
        if (mFontToggleDescribed != described) {
            mFontToggleDescribed = described;
            pill.setContentDescription(getString(compact
                ? R.string.font_toggle_restore_content_description
                : R.string.font_toggle_content_description));
        }
        // The row's dots follow the pill there (StatusBarWidgets.syncRowDots).
        mStatusBar.syncFontToggle(shown, compact);
    }

    private void setTerminalWindowBar() {
        com.termux.app.terminal.TerminalWindowBar bar = findViewById(R.id.terminal_window_bar);
        if (bar == null) return;
        // The column's chips stand for the same windows as the row's pills and answer the same
        // way, so one selection rule serves both.
        com.termux.app.statusbar.StatusBarWindowColumn windowColumn =
            findViewById(R.id.terminal_status_window_column);
        if (windowColumn != null) windowColumn.setListener(index ->
            onWindowChip(com.termux.app.chrome.WindowChips.Surface.BAR, index, false));
        bar.setOnWindowSelectedListener(index ->
            onWindowChip(com.termux.app.chrome.WindowChips.Surface.BAR, index, false));
        // Every chip tap, not only the ones that change which window is current: the tap that
        // asks the selected chip for its close button is spent on that reveal and never reaches
        // the selection listener, and it is exactly the tap the run's window card asks for.
        bar.setOnWindowCloseRequestedListener(index ->
            onWindowChip(com.termux.app.chrome.WindowChips.Surface.BAR, index, true));
        // A chip dragged along the row and dropped: the window moves there, and stays current if
        // it was. Only the row's windows' chips lift, the display window's among them
        // (setMovableChipCount below).
        bar.setOnWindowChipMovedListener(this::moveWindow);
        mChipControlsHold = chipControlsHold(bar);
        bar.setOnWindowChipHeldListener(mChipControlsHold);
        // On the display window too: the new window goes right after it, as after any window.
        bar.setOnCreateWindowListener(this::onBarNewWindow);
        applyLazyMode();

        com.termux.app.statusbar.SessionsIndicatorView sessionsIndicator =
            findViewById(R.id.terminal_sessions_indicator);
        if (sessionsIndicator != null) {
            // The chip opens Overview (the wall as one strip of cards). The sessions panel stays
            // behind session.panel and the sessions key; the native drawer by its edge swipe.
            sessionsIndicator.setOnClickListener(v -> toggleOverview());
        }
        View statusBarHost = findViewById(R.id.terminal_window_bar_host);
        if (statusBarHost instanceof com.termux.app.statusbar.StatusBarSwipeLayout) {
            com.termux.app.statusbar.StatusBarSwipeLayout swipeHost =
                (com.termux.app.statusbar.StatusBarSwipeLayout) statusBarHost;
            swipeHost.setCollapsed(mStatusBar.isStatusBarCompact());
            swipeHost.setExpansionAllowed(
                com.termux.app.statusbar.StatusBarGesturePolicy.expansionAllowed(mStatusBar.statusBarEdge()));
            swipeHost.setListener(new com.termux.app.statusbar.StatusBarSwipeLayout.Listener() {
                @Override public void onCollapsedStateRequested(boolean collapsed) {
                    mStatusBar.setTopStatusBarCollapsed(collapsed, true);
                }
                @Override public void onCollapsedStateRequested(boolean collapsed,
                                                                float towardOpenVelocityPxPerSec) {
                    // The fold lands from wherever the finger left the bar, at the speed it let go.
                    mStatusBar.setTopStatusBarCollapsed(collapsed, true, towardOpenVelocityPxPerSec);
                }
                @Override public void onFoldDrag(float towardOpenPx) {
                    mStatusBar.dragTopStatusBar(towardOpenPx);
                }
                @Override public void onFoldDragCancelled() {
                    // Back to the form the bar had, from wherever the finger left it.
                    if (mStatusBar.isStatusBarFoldDragging()) mStatusBar.setTopStatusBarCollapsed(mStatusBar.isStatusBarCompact(), true, 0f);
                }
                @Override public boolean isStatusGestureBlocked() {
                    // A live COMPACT/EXPANDED animator is deliberately eligible for takeover.
                    return mSheets.isCommandPaletteOpen() || mSheets.isAppDrawerEngaged() || mSurfaceEditor.isActive();
                }
            });
        }
        com.termux.app.statusbar.StatusBarLensView lens = findViewById(R.id.terminal_status_lens);
        if (lens != null) {
            // A tap on a peeking place icon slides the wall to the place it stands for.
            lens.setListener(page -> {
                if (mPaneWallController == null) return;
                mPaneWallController.goTo(page, true);
            });
            View slotView = findViewById(R.id.terminal_top_widget_area);
            if (slotView instanceof com.termux.app.statusbar.TopPaneWidgetSlot) {
                // The home icon sits on the clock's time line at the band's height; the slot
                // says where that is after every layout, relative to itself. The lens spans the
                // whole bar, and the slot stands at its foot on a bottom bar, so the line is
                // carried into the bar's own coordinates here.
                ((com.termux.app.statusbar.TopPaneWidgetSlot) slotView).setHomeAnchorListener(
                    (centerYPx, sizePx) -> lens.setHomeAnchor(slotView.getTop() + centerYPx,
                        sizePx));
            }
        }
        refreshTerminalWindowBar();
    }

    /**
     * Grows the accessory stack's explicit height by a band's change, without the pass that
     * computes it: one height write for a frame of a bottom bar's fold. The stack is the sum of its
     * bands ({@link #computeAccessoryStackHeight}), so this is exact until the stack meets its
     * ceiling, where the settle's pass sheds the dock's rows as it always has.
     */
    private void growAccessoryStackBy(int deltaPx) {
        if (deltaPx == 0) return;
        View stack = findViewById(R.id.accessory_stack_container);
        ViewGroup.LayoutParams params = stack == null ? null : stack.getLayoutParams();
        if (params == null || params.height < 0) return;
        params.height = Math.max(0, params.height + deltaPx);
        stack.setLayoutParams(params);
    }

    /** Refresh visibility, labels, selection and the shared dock/keyboard glass treatment. */
    public void refreshTerminalWindowBar() {
        if (mWindowBarRefreshBatchDepth > 0) {
            mWindowBarRefreshPending = true;
            return;
        }
        Trace.beginSection("Bar.refresh");
        try {
            doRefreshTerminalWindowBar();
        } finally {
            Trace.endSection();
        }
    }

    /**
     * Whether the window bar's frost is on screen drawn through the program, as the last top-pane
     * frost pass reported it ({@code onWindowBarFrostEdge}); the bar's stroke stands down while
     * it is.
     */
    private boolean mWindowBarFrostDrawsEdge;

    /** Depth of {@link #batchWindowBarRefresh}; while above zero a refresh is only noted. */
    private int mWindowBarRefreshBatchDepth;
    private boolean mWindowBarRefreshPending;

    /**
     * Runs {@code action} with the window bar's refresh held to one pass at its end. The bar
     * re-reads everything it shows on every refresh, so a page change whose several syncs each
     * ask for one — the status bar's height, the place's row, its look — pays for it once.
     */
    private void batchWindowBarRefresh(@NonNull Runnable action) {
        mWindowBarRefreshBatchDepth++;
        try {
            action.run();
        } finally {
            if (--mWindowBarRefreshBatchDepth == 0 && mWindowBarRefreshPending) {
                mWindowBarRefreshPending = false;
                refreshTerminalWindowBar();
            }
        }
    }

    private void doRefreshTerminalWindowBar() {
        View host = findViewById(R.id.terminal_window_bar_host);
        com.termux.app.terminal.TerminalWindowBar bar = findViewById(R.id.terminal_window_bar);
        if (host == null || bar == null) return;
        syncHomeBandLook();
        // Status bar › Place changed (the editor's row, a settings return): the reach, the
        // Terminal's top and the top pane's row are re-read on the one arrangement pass.
        if (mStatusRow.placeChanged()) {
            applyEdgeStacksAndInvalidate(arrangement().layout());
        }
        // Re-applied here, not only at setup, so a lazy-mode toggle takes effect on the
        // settings-return refresh instead of waiting for the activity to be recreated.
        applyLazyMode();
        // The Wall strip's clock is the bar's, in the face just picked, whether or not the bar
        // is shown.
        applyWallStripClockFace(mWallStripRow);
        boolean visible = isSplitPanesEnabled()
            && !arrangement().layout().slot(Element.STATUS).hidden;
        host.setVisibility(visible ? View.VISIBLE : View.GONE);
        int chips = com.termux.app.wall.PaneWallPolicy.showsWindowChips(mLastWallPage)
            && !mStatusRow.chipsKeptAway(mMarksLine.marksLookShown()) ? View.VISIBLE : View.GONE;
        if (bar.getVisibility() != chips) bar.setVisibility(chips);
        mStatusBar.syncBorderStatusSwipe(visible);
        if (!visible) {
            // With the bar put away the Wall strip's tiles still read
            // the same windows, on Home as on a window.
            if (mPages.isCommitted(com.termux.app.page.PageKind.HOME) ? homeWallStrip()
                : wallStripOn(mLastWallPage))
                syncWindowBarItems(bar);
            applyTerminalSurfaceAppearance();
            // Idempotence: the widgets live inside the GONE host here, so nothing is shown either
            // way — but updateStatusWidgets also owns starting and stopping the sampler, and
            // skipping it would make that depend on which mode the user happens to be in.
            mStatusBar.updateStatusWidgets();
            return;
        }

        com.termux.app.terminal.TerminalClockWidget clock = findViewById(R.id.terminal_clock_widget);
        if (clock != null) {
            if (mPreferences != null) {
                clock.setStyle(mPreferences.getTopPaneClockStyle());
                clock.setAlignment(mPreferences.getTopPaneClockAlignment());
                clock.setUseAmPm(mPreferences.isTopPaneClockAmPmEnabled());
                clock.setSeconds(mPreferences.isStatusClockSecondsEnabled());
            }
        }
        // The slot places the clock's cell by the same alignment the widget draws with, so the
        // two move together whether the change came from settings or the surface editor.
        View slotView = findViewById(R.id.terminal_top_widget_area);
        if (slotView instanceof com.termux.app.statusbar.TopPaneWidgetSlot) {
            ((com.termux.app.statusbar.TopPaneWidgetSlot) slotView).setClockAlignment(
                mPreferences == null ? null : mPreferences.getTopPaneClockAlignment());
            // The Status bar card's Clock toggle; the collapsed bar hides the whole slot anyway.
            ((com.termux.app.statusbar.TopPaneWidgetSlot) slotView).setClockShown(
                mStatusBar.isStatusClockShown());
        }
        com.termux.app.statusbar.StatusBarStackedClockView stackedClock =
            findViewById(R.id.terminal_status_column_clock);
        if (stackedClock != null && mPreferences != null) {
            stackedClock.setUseAmPm(mPreferences.isTopPaneClockAmPmEnabled());
            // Only reachable while the panel is expanded: the widget slot the clock lives in is GONE
            // in the collapsed bar, so this needs no state check of its own.
            if (clock.getTag() == null) {
                clock.setTag("wired");
                clock.setOnClickListener(v -> openSystemClockApp());
            }
        }
        Trace.beginSection("Bar.placeBar");
        try {
            refreshPlaceBar();
        } finally {
            Trace.endSection();
        }

        Trace.beginSection("Bar.glass");
        try {
            applyTerminalWindowBarGlass(host);
        } finally {
            Trace.endSection();
        }

        bindPlaceBadge(findViewById(R.id.terminal_sessions_indicator));

        Trace.beginSection("Bar.chips");
        java.util.List<Integer> foregroundPids;
        try {
            foregroundPids = syncWindowBarItems(bar);
            scheduleWindowLabelPoll(foregroundPids);
        } finally {
            Trace.endSection();
        }
        Trace.beginSection("Bar.widgets");
        try {
            mStatusBar.updateStatusWidgets();
        } finally {
            Trace.endSection();
        }
        // The tab a chip hangs from can move when the row re-lays out (a window opened, a label
        // widened), so a live chip follows it instead of drifting off its anchor.
        if (mRenameCoordinator != null && mRenameCoordinator.isActive())
            mRenameCoordinator.reposition();
    }

    /**
     * The window bar's glass, blur and style: the part of {@link #doRefreshTerminalWindowBar} a
     * glass value moves, and all a Look editor drag's tick refreshes
     * ({@link #refreshTerminalWindowBarGlass}).
     */
    private void applyTerminalWindowBarGlass(@NonNull View host) {
        View background = findViewById(R.id.terminal_window_bar_background);
        if (background != null && !topFadeTakesRedress()) {
            background.setBackground(buildTerminalWindowBarBackground(host));
            dressBarSideCard(host);
        }
        applyWindowBarDeckSlab();
        mStatusBar.applyStatusBarStyle(host);
        applyTerminalWindowBarBackdropInsets();
    }

    /** The strip's glass behind the system bar, continuing the bar's, in the dress worn now. */
    @NonNull
    private Drawable buildStatusInsetStripSurface(@NonNull View host) {
        float opacity = mPreferences != null
            ? mPreferences.getStatusBarOpacity(mStatusBar.statusLookPage()) / 100f : 1f;
        return mChrome.glass().statusBarExtensionSurface(opacity, 0f,
            terminalWindowGlassStatusFraction(host),
            STATUS_INSET_STRIP_CONTINUES_PANE_VEIL
                ? com.termux.app.chrome.GlassBackdropCache.Band.WINDOW_BAR
                : null);
    }

    /** The bar's own glass in the dress worn now; null where it wears none (on the plank). */
    @Nullable
    private Drawable buildTerminalWindowBarBackground(@NonNull View host) {
        boolean joinsDock = mStatusBar.statusBarEdge() == PlaceLayout.Edge.BOTTOM;
        boolean onPlank = (joinsDock && mStatusBarOnDockPlank) || frameStandsDown();
        float opacity = mPreferences == null ? 1f
            : (joinsDock ? mPreferences.getAppBarOpacity(stackLookPage()) : mPreferences.getStatusBarOpacity(mStatusBar.statusLookPage()))
                / 100f;
        boolean capsuleStatusBar = isRoundedStyle(com.termux.app.place.SeamDress.Surface.STATUS);
        // The capsule floats below the status bar as its own slab, so its glass spans the full
        // pane height. The default pane merges with the behind-status glass, so it renders only
        // the lower slice and the extension draws the rest.
        // The edge rule is the model's: Docked, only the edge facing the opening keeps the
        // line; the bar's screen edges and joins take none, and the strip behind the system
        // status bar continues it where it leads. The capsule keeps it all round.
        boolean stripContinues = statusInsetStripLead()
            == com.termux.app.chrome.ChromeEdgeRule.TopLead.WINDOW_BAR;
        int barStroke = capsuleStatusBar ? com.termux.app.chrome.ChromeEdgeRule.ALL
            : chromeRimEdges(com.termux.app.place.ChromeShape.PieceId.STATUS);
        return onPlank ? null
            : joinsDock
                ? mChrome.glass().dockSurface(opacity, 0f, 1f, false,
                    mChrome.glass().statusTintStrength())
                : mChrome.glass().statusBarSurface(opacity,
                    capsuleStatusBar || mStatusBar.isStatusBarVertical() || !stripContinues
                        ? 0f : terminalWindowGlassStatusFraction(host), 1f, barStroke,
                    com.termux.app.chrome.GlassBackdropCache.Band.WINDOW_BAR,
                    // While the bar's frost draws the gathered light along the same outline,
                    // as the last frost pass found it, the bar lays no stroke beside it.
                    mWindowBarFrostDrawsEdge);
    }

    /**
     * {@link #refreshTerminalWindowBar} for a Frost, Opacity or Tint drag's tick: the bar's glass
     * only. The rest of the refresh (the window chips, the clock, the place bar, the label poll)
     * reads nothing a glass value moves; the release's full pass runs it once.
     */
    private void refreshTerminalWindowBarGlass() {
        View host = findViewById(R.id.terminal_window_bar_host);
        if (host == null || host.getVisibility() != View.VISIBLE) return;
        applyTerminalWindowBarGlass(host);
    }

    /**
     * {@link #refreshTerminalWindowBar} for focus moved to another pane of the window on screen
     * ({@code PaneFocusNotice.Kind.PANE}): the window chips and their label poll only. A bar put
     * away takes the full pass, which also feeds the Wall strip's tiles.
     */
    private void refreshTerminalWindowBarChips() {
        if (mWindowBarRefreshBatchDepth > 0) {
            mWindowBarRefreshPending = true;
            return;
        }
        View host = findViewById(R.id.terminal_window_bar_host);
        com.termux.app.terminal.TerminalWindowBar bar = findViewById(R.id.terminal_window_bar);
        if (host == null || bar == null) return;
        if (host.getVisibility() != View.VISIBLE) {
            refreshTerminalWindowBar();
            return;
        }
        Trace.beginSection("Bar.chipsOnly");
        try {
            scheduleWindowLabelPoll(syncWindowBarItems(bar));
            if (mRenameCoordinator != null && mRenameCoordinator.isActive())
                mRenameCoordinator.reposition();
        } finally {
            Trace.endSection();
        }
    }

    /**
     * Push the current window list — labels, selection and working state — into {@code bar}, and
     * return the pane pids for the foreground resolver. Split out of
     * {@link #refreshTerminalWindowBar()} so the shell-activity refresh can update the pills without
     * redoing the bar's glass, blur and palette work several times a second.
     */
    @NonNull
    private java.util.List<Integer> syncWindowBarItems(
            @NonNull com.termux.app.terminal.TerminalWindowBar bar) {
        java.util.List<Integer> foregroundPids = new java.util.ArrayList<>();
        // The window chips (the display window's at its place among the terminal windows', ADR
        // 0008 amended 2026-10-19, then the Home floats), built once and dressed once: every
        // window's shells, the floats' included, are observed once for this refresh's marks, and
        // the bar and the Wall strip both show the chips as they come out of that.
        com.termux.app.chrome.WindowChips<com.termux.app.terminal.TerminalPaneController.Window>
            chips = windowChips();
        // The Terminal's windows on the bar; the Wall strip's tiles also carry the Home floats.
        java.util.Map<com.termux.app.terminal.TerminalPaneController.Window,
            com.termux.app.terminal.TerminalWindowBar.WindowItem> floatItems =
                new java.util.HashMap<>();
        java.util.List<com.termux.app.terminal.TerminalWindowBar.WindowItem> items =
            windowChipItems(chips, foregroundPids, floatItems);
        // Home's own chips: the floats of the Home page shown, dressed from the same observation.
        syncHomeFloatChips(floatItems);
        // Home's dock may show the same chips as the Wall strip's tiles, and so may a window whose
        // dock wears the Wall strip over its apps (#93).
        if (mPages.isCommitted(com.termux.app.page.PageKind.HOME) || wallStripFed() && wallStripOn(mLastWallPage))
            syncWallStrip(chips, items);
        int selected = chips.selected(com.termux.app.chrome.WindowChips.Surface.BAR);
        mMarksLine.setWindowAttention(chips, items);
        // The bar lists the Terminal's own windows; the floats are Home's chips (#295).
        items = new java.util.ArrayList<>(
            items.subList(0, chips.count(com.termux.app.chrome.WindowChips.Surface.BAR)));
        // On a Display page the bar shows no terminal window chips (A3c2): the status widgets
        // beside them stay; the terminal chips come back with the wall's return to the Terminal page.
        // #192: the Display page's chips are the display's apps, one each; none when empty.
        if (isDisplayWindowInFront()) {
            items = displayAppItems();
            selected = displayAppChips().selected();
        } else {
            selected = addLinuxWindowItems(items, selected);
        }
        // The row's own windows can be dragged to reorder, Linux windows' chips among them: not
        // the Home floats' or minimised Linux windows' after them. The same on both halves.
        bar.setMovableChipCount(items.isEmpty() || isDisplayWindowInFront() ? 0
            : Math.min(items.size(), rowWindowCount()));
        bar.setWindows(items, selected);
        syncFontToggle();
        refreshPageGlyphsIfWindowsMoved();
        mMarksLine.syncMarksLine();
        if (mScene != null && selected >= 0 && selected < items.size())
            mScene.onFocusedWindow(items.get(selected).label);
        com.termux.app.statusbar.StatusBarWindowColumn windowColumn =
            findViewById(R.id.terminal_status_window_column);
        if (windowColumn != null) windowColumn.setWindows(items, selected);
        syncBackgroundProcessStack();
        scheduleShellPhaseJudgement();
        java.util.List<Integer> pids = collectAllPanePids();
        // The Home floats' shells are the session's windows too, and their chips carry the same
        // marks as the row's: the trackers keep them, and the resolver reads their foreground.
        if (mPaneController != null) {
            for (com.termux.app.terminal.TerminalPaneController.Window window : chipFloats()) {
                for (TerminalSession shell : mPaneController.shellsOf(window)) {
                    if (shell.getPid() > 0 && !pids.contains(shell.getPid()))
                        pids.add(shell.getPid());
                }
            }
        }
        java.util.HashSet<Integer> live = new java.util.HashSet<>(pids);
        mShellPhases.retain(live);
        mAgentStatuses.retain(live);
        if (mPaneController != null) mPaneController.retainPaneAttention(live);
        return pids;
    }

    /**
     * The chip for the terminal window {@code window} at {@code index} — a row's window or a Home
     * float — its marks read from this refresh's observation of its shells; {@code seen} when the
     * user is looking at it.
     */
    @NonNull
    private com.termux.app.terminal.TerminalWindowBar.WindowItem windowItem(
            @NonNull com.termux.app.terminal.TerminalPaneController.Window window, int index,
            @NonNull java.util.List<Integer> foregroundPids, boolean seen, long now) {
        TerminalSession session = mPaneController.windowActiveSession(window);
        com.termux.terminal.TerminalEmulator progress = windowProgressReporter(window, now);
        // Agents first: observeWindowPhases reads back what this refresh's agent pass wrote,
        // so a title that has just turned the ring on must not be a refresh behind.
        com.termux.app.terminal.AgentStatus.State agentState = observeWindowAgents(window, now);
        for (TerminalSession shell : mPaneController.shellsOf(window)) syncPaneAttention(shell);
        int phases = observeWindowPhases(window, seen, now);
        com.termux.app.terminal.TerminalWindowBar.WindowItem built =
            buildWindowItem(session, index, foregroundPids, mPaneController.windowName(window));
        return built
            .withBusy(progress != null || (phases & PHASE_WORKING) != 0)
            .withAttention(isWindowAwaitingUser(window) || (phases & PHASE_ATTENTION) != 0)
            .withDone((phases & PHASE_DONE) != 0,
                (phases & PHASE_DONE) != 0 && windowCommandFailed(window))
            .withProgress(progress == null || progress.getProgressState()
                    == com.termux.terminal.TerminalEmulator.PROGRESS_STATE_INDETERMINATE
                    ? com.termux.app.terminal.TerminalWindowBar.WindowItem.NO_PERCENTAGE
                    : progress.getProgressValue(),
                progress != null && progress.getProgressState()
                    == com.termux.terminal.TerminalEmulator.PROGRESS_STATE_ERROR)
            .withAgentState(agentState)
            .withStatus(windowProgramStatus(window, built.label));
    }

    /** What a program in {@code window} reports about itself; null when none has anything but idle. */
    @Nullable
    private com.termux.app.terminal.TerminalWindowBar.WindowItem.Status windowProgramStatus(
            @NonNull com.termux.app.terminal.TerminalPaneController.Window window,
            @NonNull String windowLabel) {
        java.util.List<TerminalSession> shells = mPaneController.shellsOf(window);
        java.util.ArrayList<com.termux.terminal.ProgramStatusStore> stores =
            new java.util.ArrayList<>(shells.size());
        for (TerminalSession shell : shells) {
            TerminalEmulator emulator = shell.getEmulator();
            stores.add(emulator == null ? null : emulator.getProgramStatus());
        }
        return com.termux.app.terminal.ProgramStatusLabel.forWindow(stores, windowLabel);
    }

    private static final int PHASE_WORKING = 1;
    private static final int PHASE_ATTENTION = 2;
    private static final int PHASE_DONE = 4;

    /**
     * Feeds this refresh's observation of every shell in {@code window} to the phase tracker and
     * folds the answers into one set of marks: the ring while any shell works (including the short
     * grace after it goes quiet), the bell when one went quiet on a question, the tick when one
     * finished — the last two only for a window the user is not looking at.
     */
    private int observeWindowPhases(
            @NonNull com.termux.app.terminal.TerminalPaneController.Window window, boolean seen,
            long nowMs) {
        if (mPaneController == null) return 0;
        int marks = 0;
        for (TerminalSession shell : mPaneController.shellsOf(window)) {
            int pid = shell.getPid();
            if (pid <= 0) continue;
            com.termux.app.statusbar.WindowForegroundResolver.ForegroundInfo info =
                mWindowForegroundResolver == null ? null : mWindowForegroundResolver.get(pid);
            com.termux.app.statusbar.ShellPhaseTracker.Phase phase = mShellPhases.observe(pid, nowMs,
                isPaneWorking(shell, pid, nowMs), info != null, info != null && info.idle,
                () -> screenLooksLikeQuestion(shell), seen);
            switch (phase) {
                case WORKING: marks |= PHASE_WORKING; break;
                case ATTENTION: marks |= PHASE_ATTENTION; break;
                case DONE: marks |= PHASE_DONE; break;
                default: break;
            }
        }
        return marks;
    }

    /**
     * Whether this pane counts as working for the phase tracker: an agent that said so itself, by
     * hook or by title, answers for its own pane, because output on the screen is a poor proxy for
     * a turn — a Claude at rest with a background shell still writes, and one thinking quietly does
     * not. Every other pane is judged by its output, exactly as before.
     */
    private boolean isPaneWorking(@NonNull TerminalSession shell, int pid, long nowMs) {
        com.termux.app.terminal.AgentStatus status = mAgentStatuses.get(pid);
        if (status != null && (status.source == com.termux.app.terminal.AgentStatus.Source.TITLE
            || status.source == com.termux.app.terminal.AgentStatus.Source.HOOK)) {
            return status.state == com.termux.app.terminal.AgentStatus.State.WORKING;
        }
        return isShellWorking(shell, nowMs);
    }

    /**
     * Feeds the pane's data-driven attention causes from what is already tracked: an agent that is
     * blocked, and a progress report in the error state. The bell rides noteShellAttention.
     */
    private void syncPaneAttention(@NonNull TerminalSession shell) {
        if (mPaneController == null) return;
        com.termux.app.terminal.AgentStatus status = mAgentStatuses.get(shell.getPid());
        mPaneController.setPaneAttention(shell, com.termux.app.terminal.PaneAttention.Cause.BLOCKED,
            status != null && status.state == com.termux.app.terminal.AgentStatus.State.BLOCKED);
        com.termux.terminal.TerminalEmulator emulator = shell.getEmulator();
        mPaneController.setPaneAttention(shell,
            com.termux.app.terminal.PaneAttention.Cause.PROGRESS_ERROR, emulator != null
                && emulator.getProgressState()
                == com.termux.terminal.TerminalEmulator.PROGRESS_STATE_ERROR);
    }

    /**
     * An agent's own report about its pane, from {@code launcherctl agent}. Authoritative, so the
     * chips and the browser are repainted straight away rather than at the next poll.
     */
    void reportAgentStatus(@NonNull TerminalSession pane, @Nullable String agent,
                           @Nullable com.termux.app.terminal.AgentStatus.State state) {
        int pid = pane.getPid();
        if (pid <= 0) return;
        if (!mAgentStatuses.report(pid, agent, state, android.os.SystemClock.uptimeMillis())) return;
        syncPaneAttention(pane);
        com.termux.app.terminal.TerminalWindowBar bar = findViewById(R.id.terminal_window_bar);
        if (bar != null) syncWindowBarItems(bar);
    }

    /**
     * The agents running in a live pane that have no resume hook set up yet, for the Save
     * dialog's offer. The panes' pids are taken here; their programs (/proc) and the hook files
     * are read on the writer thread, and {@code onResult} runs back on the main thread.
     */
    public void requestAgentsNeedingResumeSetup(
            @NonNull java.util.function.Consumer<java.util.List<String>> onResult) {
        requestAgentsNeedingResumeSetup(null, onResult);
    }

    /** As above for the panes of {@code only} alone (a saved session); null for every pane. */
    public void requestAgentsNeedingResumeSetup(
            @Nullable com.termux.app.terminal.TerminalPaneController.Window only,
            @NonNull java.util.function.Consumer<java.util.List<String>> onResult) {
        final java.util.List<Integer> pids = new java.util.ArrayList<>();
        if (mPaneController != null) {
            java.util.List<com.termux.app.terminal.TerminalPaneController.Window> windows =
                new java.util.ArrayList<>();
            if (only != null) {
                windows.add(only);
            } else {
                windows.addAll(chipFloats());
                for (WSession ws : mWSessions) windows.addAll(ws.windows);
            }
            for (com.termux.app.terminal.TerminalPaneController.Window window : windows) {
                for (TerminalSession shell : mPaneController.shellsOf(window)) {
                    pids.add(shell.getPid());
                }
            }
        }
        ARRANGEMENT_AUTOSAVE_WRITER.execute(() -> {
            java.util.List<java.util.List<String>> commands = new java.util.ArrayList<>();
            for (int pid : pids) {
                commands.add(com.termux.app.statusbar.WindowForegroundResolver.captureCommand(pid));
            }
            final java.io.File home = new java.io.File(
                com.termux.shared.termux.TermuxConstants.TERMUX_HOME_DIR_PATH);
            final String launcherctl = com.termux.shared.termux.TermuxConstants
                .TERMUX_BIN_PREFIX_DIR_PATH + "/launcherctl";
            final java.util.List<String> agents = com.termux.app.terminal.AgentResume
                .agentsNeedingSetup(commands, agent -> com.termux.launcherctl.ClaudeHooksInstaller
                    .isInstalled(agent, home, launcherctl));
            mArrangementAutosaveHandler.post(() -> onResult.accept(agents));
        });
    }

    /**
     * Set up resume for {@code agents} (the Save dialog's button): their hook or plugin files
     * are written under the home folder on the writer thread, and {@code onDone} runs on the main
     * thread with whether every file was written.
     */
    public void installAgentResume(@NonNull java.util.List<String> agents,
                                   @NonNull java.util.function.Consumer<Boolean> onDone) {
        final java.io.File home = new java.io.File(
            com.termux.shared.termux.TermuxConstants.TERMUX_HOME_DIR_PATH);
        final String launcherctl =
            com.termux.shared.termux.TermuxConstants.TERMUX_BIN_PREFIX_DIR_PATH + "/launcherctl";
        final java.util.List<String> asked = new java.util.ArrayList<>(agents);
        ARRANGEMENT_AUTOSAVE_WRITER.execute(() -> {
            boolean ok = true;
            for (String agent : asked) {
                try {
                    ok &= com.termux.launcherctl.ClaudeHooksInstaller
                        .installAll(home, launcherctl, agent).optBoolean("ok", false);
                } catch (org.json.JSONException e) {
                    ok = false;
                }
            }
            final boolean result = ok;
            mArrangementAutosaveHandler.post(() -> onDone.accept(result));
        });
    }

    /**
     * An agent's session hook named the conversation this pane is in: it is kept on the pane, and
     * the autosave follows so a kill right after still resumes it.
     */
    void reportAgentSession(@NonNull TerminalSession pane, @NonNull String agent,
                            @NonNull String sessionId) {
        if (agent.equals(pane.mAgentName) && sessionId.equals(pane.mAgentSessionId)) return;
        pane.mAgentName = agent;
        pane.mAgentSessionId = sessionId;
        scheduleArrangementAutosave();
    }

    /**
     * The rolled-up agent reading for one window: what each of its panes says, folded blocked over
     * working over idle. Null when no pane in it is running an agent, which is the ordinary case and
     * costs one map lookup per pane.
     *
     * <p>The screen half only runs for a pane whose foreground procfs reading names an agent, and
     * only the bottom rows are ever read — the tracker throttles and hashes the rest.
     */
    @Nullable
    private com.termux.app.terminal.AgentStatus.State observeWindowAgents(
            @NonNull com.termux.app.terminal.TerminalPaneController.Window window, long nowMs) {
        if (mPaneController == null) return null;
        com.termux.app.terminal.AgentStatus.State folded = null;
        for (TerminalSession shell : mPaneController.shellsOf(window)) {
            folded = com.termux.app.terminal.AgentStatus.rollUp(folded, observePaneAgent(shell, nowMs));
        }
        return folded;
    }

    /** One pane's agent reading, refreshed from procfs and (when due) from its screen. */
    @Nullable
    private com.termux.app.terminal.AgentStatus.State observePaneAgent(
            @NonNull TerminalSession shell, long nowMs) {
        int pid = shell.getPid();
        if (pid <= 0) return null;
        com.termux.app.statusbar.WindowForegroundResolver.ForegroundInfo info =
            mWindowForegroundResolver == null ? null : mWindowForegroundResolver.get(pid);
        String agent = info == null || info.idle ? null
            : com.termux.app.terminal.AgentStatus.kindFor(info.processName, info.command);
        // A pane whose foreground cannot be read at all keeps whatever it had: a missing procfs
        // reading is not evidence the agent exited, and dropping it would flicker the dot.
        if (agent == null && info == null && mAgentStatuses.isHooked(pid)) {
            com.termux.app.terminal.AgentStatus held = mAgentStatuses.get(pid);
            return held == null ? null : held.state;
        }
        // isWorkingAsOf, not the raw flag: a reading that stopped being refreshed must not go on
        // asserting that an agent with no rules of its own is still working.
        mAgentStatuses.observe(pid, agent, shell.getTitle(),
            info != null && info.isWorkingAsOf(nowMs, shell.getLastWriteUptimeMs()),
            () -> agentScreenTail(shell), nowMs);
        com.termux.app.terminal.AgentStatus status = mAgentStatuses.get(pid);
        return status == null ? null : status.state;
    }

    /** The bottom rows of a pane, which is all a screen rule ever looks at. */
    @Nullable
    private static String agentScreenTail(@NonNull TerminalSession shell) {
        com.termux.terminal.TerminalEmulator emulator = shell.getEmulator();
        if (emulator == null) return null;
        int top = Math.max(0, emulator.mRows - com.termux.app.terminal.AgentScreenRules.TAIL_ROWS);
        return emulator.getContent().text(0, top, emulator.mColumns,
            emulator.mRows - 1, true, false);
    }

    /**
     * Whether the last command to finish in {@code window} said it failed.
     *
     * <p>The status comes from the shell's own OSC 133;D report, so it is only ever available where
     * shell integration is in use; without it every finished command gets the plain tick, which is
     * the honest answer. Read at badge time rather than remembered, since the emulator holds the
     * status until the next command replaces it.
     */
    private boolean windowCommandFailed(
            @NonNull com.termux.app.terminal.TerminalPaneController.Window window) {
        if (mPaneController == null) return false;
        for (TerminalSession shell : mPaneController.shellsOf(window)) {
            com.termux.terminal.TerminalEmulator emulator = shell.getEmulator();
            if (emulator != null && emulator.getLastCommandExitCode() > 0) return true;
        }
        return false;
    }

    /** Read once per quiet spell, when the tracker has to tell asking from finished. */
    private static boolean screenLooksLikeQuestion(@NonNull TerminalSession shell) {
        com.termux.terminal.TerminalEmulator emulator = shell.getEmulator();
        if (emulator == null) return false;
        String screen = emulator.getContent().text(0, 0, emulator.mColumns,
            emulator.mRows - 1, true, false);
        return com.termux.app.statusbar.ShellAttentionCues.looksLikeQuestion(screen);
    }

    /**
     * One refresh at the moment the soonest quiet command has to be judged waiting or finished,
     * rather than polling while nothing changes.
     */
    private void scheduleShellPhaseJudgement() {
        mShellActivityHandler.removeCallbacks(mShellPhaseJudgement);
        long now = android.os.SystemClock.uptimeMillis();
        long due = mShellPhases.nextJudgementMs(now);
        if (due < 0L) return;
        mShellActivityHandler.postDelayed(mShellPhaseJudgement, Math.max(50L, due - now) + 20L);
    }

    @NonNull
    private java.util.List<Integer> collectAllPanePids() {
        java.util.LinkedHashSet<Integer> unique = new java.util.LinkedHashSet<>();
        if (mPaneController != null) {
            for (WSession session : mWSessions) {
                for (com.termux.app.terminal.TerminalPaneController.Window window : session.windows) {
                    for (TerminalSession shell : mPaneController.shellsOf(window)) {
                        if (shell.getPid() > 0) unique.add(shell.getPid());
                    }
                }
            }
        }
        return new java.util.ArrayList<>(unique);
    }

    void syncBackgroundProcessStack() {
        java.util.List<com.termux.app.statusbar.BackgroundProcessModel.Snapshot> snapshots =
            new java.util.ArrayList<>();
        if (mPaneController != null && mWindowForegroundResolver != null) {
            java.util.HashSet<Integer> seenShells = new java.util.HashSet<>();
            for (WSession session : mWSessions) {
                for (com.termux.app.terminal.TerminalPaneController.Window window : session.windows) {
                    for (TerminalSession shell : mPaneController.shellsOf(window)) {
                        int shellPid = shell.getPid();
                        if (shellPid < 1 || !seenShells.add(shellPid)) continue;
                        // Only shells that rang the bell earn a standing row: a long-lived remote
                        // session or watcher is "running" forever, and a permanent corner row for it
                        // is noise. The bell is the same signal the attention notice and the window
                        // pill accent key off, and visiting the window clears it.
                        if (!mAttentionShellPids.contains(shellPid)) continue;
                        com.termux.app.statusbar.WindowForegroundResolver.ForegroundInfo info =
                            mWindowForegroundResolver.get(shellPid);
                        if (info == null || info.idle || info.foregroundPid < 1) continue;
                        com.termux.terminal.TerminalEmulator emulator = shell.getEmulator();
                        boolean running = emulator == null || !emulator.hasShellIntegration()
                            || emulator.isShellIntegrationCommandRunning();
                        snapshots.add(new com.termux.app.statusbar.BackgroundProcessModel.Snapshot(
                            session.id, shellPid, info.foregroundPid, info.processName,
                            shell.getTitle(), running));
                    }
                }
            }
        }
        long now = android.os.SystemClock.elapsedRealtime();
        mBackgroundProcessModel.update(snapshots, now);
        // Session, not pane: moving between the windows of one session leaves their pills on screen,
        // and the pills already carry the working and waiting states. Only leaving the session hides
        // them, which is the case this corner covers.
        long focusedSessionId = mCurrentWSession == null ? -1L : mCurrentWSession.id;
        java.util.List<com.termux.app.statusbar.BackgroundProcessModel.Entry> visible =
            mBackgroundProcessModel.visibleEntries(focusedSessionId, now);
        long untilNext = mBackgroundProcessModel.msUntilNextVisible(focusedSessionId, now);
        mBackgroundProcessHandler.removeCallbacks(mBackgroundProcessResync);
        if (untilNext >= 0L)
            mBackgroundProcessHandler.postDelayed(mBackgroundProcessResync, untilNext);
        if (mBackgroundProcessStack == null && visible.isEmpty()) return;
        com.termux.app.statusbar.BackgroundProcessStackView stack = obtainBackgroundProcessStack();
        if (stack != null) stack.bind(visible);
    }

    /**
     * Record that {@code session} asked for the user. The terminal bell is the signal: it is what
     * shells, editors, and agent CLIs already ring when a command finishes or a prompt needs an
     * answer, so no cooperation from the program is required.
     *
     * <p>A bell from the window the user is already in is not news: its pill shows the bell for a
     * couple of seconds and drops it on its own, instead of holding it until acknowledged.
     */
    void noteShellAttention(@NonNull TerminalSession session) {
        int pid = session.getPid();
        if (pid < 1 || mPaneController == null) return;
        if (mScene != null) mScene.onBell(mPaneController.getViewForSession(session));
        // The pane's own border glows until the user focuses it; every bell, OSC 9/777/99 message
        // and launcherctl notify lands here.
        mPaneController.setPaneAttention(session,
            com.termux.app.terminal.PaneAttention.Cause.BELL, true);
        if (mCurrentWSession != null
            && mPaneController.shellsOf(mCurrentWSession.currentWindow()).contains(session)) {
            if (mTimedAttentionShellPids.add(pid)) refreshTerminalWindowBar();
            mShellActivityHandler.postDelayed(() -> {
                if (mTimedAttentionShellPids.remove(pid)) refreshTerminalWindowBar();
            }, FOCUSED_BELL_MS);
            return;
        }
        if (!mAttentionShellPids.add(pid)) return;
        refreshTerminalWindowBar();
    }

    /**
     * The emulator in {@code window} that is reporting progress (OSC 9;4), or null when none is.
     * The first reporting shell wins: a window's pill has one ring.
     */
    @Nullable
    private com.termux.terminal.TerminalEmulator windowProgressReporter(
            @NonNull com.termux.app.terminal.TerminalPaneController.Window window, long nowMs) {
        if (mPaneController == null) return null;
        for (TerminalSession shell : mPaneController.shellsOf(window)) {
            com.termux.terminal.TerminalEmulator emulator = shell.getEmulator();
            if (emulator == null || emulator.getProgressState()
                == com.termux.terminal.TerminalEmulator.PROGRESS_STATE_NONE) continue;
            // A report belongs to the command that made it. A program killed part-way through never
            // sends the closing "OSC 9;4;0", and its ring would then turn for the rest of the
            // session; once the shell itself has the terminal back there is nothing left to report
            // on. Only a reading fresh enough to still mean something may retire a report.
            com.termux.app.statusbar.WindowForegroundResolver.ForegroundInfo info =
                mWindowForegroundResolver == null ? null : mWindowForegroundResolver.get(shell.getPid());
            if (info != null && info.idle && nowMs - info.atMs
                <= com.termux.app.statusbar.WindowForegroundResolver.WORKING_TTL_MS) continue;
            return emulator;
        }
        return null;
    }

    void clearShellAttention(int shellPid) {
        if (mAttentionShellPids.remove(shellPid)) refreshTerminalWindowBar();
    }

    private void clearWindowAttention(
            @NonNull com.termux.app.terminal.TerminalPaneController.Window window) {
        if (mPaneController == null) return;
        for (TerminalSession shell : mPaneController.shellsOf(window)) {
            mAttentionShellPids.remove(shell.getPid());
            mShellPhases.markSeen(shell.getPid());
        }
    }

    private boolean isWindowAwaitingUser(
            @NonNull com.termux.app.terminal.TerminalPaneController.Window window) {
        if (mPaneController == null) return false;
        if (mAttentionShellPids.isEmpty() && mTimedAttentionShellPids.isEmpty()) return false;
        for (TerminalSession shell : mPaneController.shellsOf(window)) {
            int pid = shell.getPid();
            if (mAttentionShellPids.contains(pid) || mTimedAttentionShellPids.contains(pid))
                return true;
        }
        return false;
    }

    /**
     * Whether {@code shell} has a command actively working in it this instant. The rules, and why a
     * full-screen program only counts on measured CPU, live in
     * {@link com.termux.app.statusbar.ShellWorkingPolicy}.
     */
    private boolean isShellWorking(@NonNull TerminalSession shell, long nowMs) {
        int pid = shell.getPid();
        if (pid <= 0) return false;
        com.termux.app.statusbar.WindowForegroundResolver.ForegroundInfo info =
            mWindowForegroundResolver == null ? null : mWindowForegroundResolver.get(pid);
        return com.termux.app.statusbar.ShellWorkingPolicy.isWorking(nowMs, shell.getLastWriteUptimeMs(),
            SHELL_INPUT_GRACE_MS, info, isFullScreenApplication(shell),
            mShellActivityTracker.isWorking(pid, nowMs));
    }

    /** Whether {@code shell} has a full-screen application on the alternate screen buffer. */
    private static boolean isFullScreenApplication(@NonNull TerminalSession shell) {
        com.termux.terminal.TerminalEmulator emulator = shell.getEmulator();
        return emulator != null && emulator.isAlternateBufferActive();
    }

    /**
     * Record output from {@code session} and schedule one coalesced refresh of the working
     * indication.
     *
     * <p>This is tmux's monitor-activity: {@code onTextChanged} already fires on every screen
     * update, so no privileged backend and no procfs polling is involved.
     *
     * <p>Deliberately not on mWindowLabelHandler despite being the same kind of work:
     * scheduleWindowLabelPoll calls removeCallbacksAndMessages(null) on that handler, which would
     * drop a pending refresh and leave the coalescing flag stuck.
     */
    void noteShellActivity(@Nullable TerminalSession session) {
        if (session == null || !isSplitPanesEnabled()) return;
        int pid = session.getPid();
        if (pid <= 0) return;
        long now = android.os.SystemClock.uptimeMillis();
        mShellActivityTracker.noteActivity(pid, now, session.getLastWriteUptimeMs());
        mShellActivityTracker.pruneBefore(now - 4 * com.termux.app.statusbar.ShellActivityTracker.DECAY_MS);
        scheduleWindowBarRefresh();
    }

    /**
     * One coalesced window-bar refresh, for news that changes what a chip shows without being output
     * of its own — an agent retitling its pane. Deliberately not routed through
     * {@link #noteShellActivity}: a title is not activity, and counting it as such would ring a
     * plain shell that only renamed its window.
     */
    void scheduleWindowBarRefresh() {
        if (mShellActivityRefreshPending) return;
        mShellActivityRefreshPending = true;
        mShellActivityHandler.postDelayed(mShellActivityRefresh, SHELL_ACTIVITY_REFRESH_MS);
    }

    private void refreshShellActivityIndication() {
        mShellActivityRefreshPending = false;
        boolean labelPollOwed = mWindowLabelPollOwed;
        mWindowLabelPollOwed = false;
        com.termux.app.terminal.TerminalWindowBar bar = findViewById(R.id.terminal_window_bar);
        if (bar != null && isSplitPanesEnabled()) {
            java.util.List<Integer> foregroundPids = syncWindowBarItems(bar);
            if (labelPollOwed) scheduleWindowLabelPoll(foregroundPids);
        }
        scheduleShellActivityDecay();
    }

    /**
     * One refresh at the moment the soonest still-active shell stops counting as working, instead of
     * polling for the whole time nothing is happening.
     */
    private void scheduleShellActivityDecay() {
        mShellActivityHandler.removeCallbacks(mShellActivityDecay);
        long now = android.os.SystemClock.uptimeMillis();
        long expiry = mShellActivityTracker.nextExpiryMs(now);
        if (expiry < 0L) return;
        mShellActivityHandler.postDelayed(mShellActivityDecay, Math.max(50L, expiry - now) + 20L);
    }

    @Nullable
    private CharSequence currentStatusSessionName() {
        return mCurrentWSession == null ? null : mCurrentWSession.name;
    }

    /**
     * Build a window pill label following the priority: open file basename (editors) &gt; foreground
     * process name &gt; directory basename (idle). Falls back to the title/cwd label when foreground
     * detection has no data yet. Collects the pane pid into {@code foregroundPids} for the next
     * resolver poll.
     */
    @NonNull
    private com.termux.app.terminal.TerminalWindowBar.WindowItem buildWindowItem(
            @Nullable TerminalSession session, int index, @NonNull java.util.List<Integer> foregroundPids,
            @Nullable String windowName) {
        if (session == null) {
            return windowName == null
                ? com.termux.app.terminal.TerminalWindowBar.itemFor(null, index)
                : com.termux.app.terminal.TerminalWindowBar.itemForNamed(windowName, null);
        }
        int pid = session.getPid();
        if (pid > 0) foregroundPids.add(pid);
        com.termux.app.statusbar.WindowForegroundResolver.ForegroundInfo info =
            mWindowForegroundResolver == null ? null : mWindowForegroundResolver.get(pid);
        // A user-given name outranks every derived label: the whole point of naming a window is that
        // its tab stops changing under you as the foreground process comes and goes.
        if (windowName != null) {
            String process = info != null && !info.idle ? glyphProcessFor(info)
                : com.termux.app.terminal.TerminalWindowBar.processName(session.getTitle());
            return com.termux.app.terminal.TerminalWindowBar.itemForNamed(windowName, process);
        }
        if (info != null && !info.idle && info.processName != null) {
            return com.termux.app.terminal.TerminalWindowBar.itemForForegroundProcess(
                glyphProcessFor(info), info.openFile);
        }
        // Idle or not yet resolved: directory basename via the existing title/cwd derivation.
        return com.termux.app.terminal.TerminalWindowBar.itemFor(session, index);
    }

    /**
     * The name the chip should wear for a resolved foreground: the agent the argv identifies when
     * procfs only saw its runtime ({@code node} hosting Claude Code, {@code npx} hosting Codex),
     * otherwise the process name itself. An agent's own name is the one the glyph table knows.
     */
    @Nullable
    private static String glyphProcessFor(
            @NonNull com.termux.app.statusbar.WindowForegroundResolver.ForegroundInfo info) {
        String agent = com.termux.app.terminal.AgentStatus.kindFor(info.processName, info.command);
        return agent != null ? agent : info.processName;
    }

    /** Kick the throttled foreground resolver and keep it polling while the window bar is shown. */
    private void scheduleWindowLabelPoll(@NonNull java.util.List<Integer> pids) {
        mWindowLabelHandler.removeCallbacksAndMessages(null);
        if (pids.isEmpty()) return;
        if (mWindowForegroundResolver == null) {
            mWindowForegroundResolver = new com.termux.app.statusbar.WindowForegroundResolver(
                this::onWindowForegroundResolved);
        }
        mWindowForegroundResolver.refresh(pids, android.os.SystemClock.uptimeMillis());
        mWindowLabelHandler.postDelayed(() -> {
            if (mWindowForegroundResolver != null && isSplitPanesEnabled()) {
                mWindowForegroundResolver.refresh(pids, android.os.SystemClock.uptimeMillis());
                scheduleWindowLabelPoll(pids);
            }
        }, WINDOW_LABEL_POLL_MS);
    }


    /**
     * Whether anything showing the CPU and RAM readings is on screen, for the sampler's pause
     * (StatsPollCadence): the open stats card or the status bar, on Home as on a window (#91).
     */
    private boolean statsConsumerVisible() {
        boolean cardShowing = mStatusCardHost.isShowing() && mStatsCardView != null;
        View barHost = findViewById(R.id.terminal_window_bar_host);
        // The Terl bar's reading slot is a reading on screen of its own (#428).
        return cardShowing || (mControlBar != null && mControlBar.readingWantsSampler())
            || (barHost != null && barHost.getVisibility() == View.VISIBLE);
    }

    /** The sampler follows whether anything shows its readings ({@link #statsConsumerVisible}). */
    private void syncStatsConsumer() {
        if (mStatsController != null) mStatsController.setConsumerVisible(statsConsumerVisible());
    }

    /**
     * The AI glyph has no preference behind it. It is a live state, not a choice: it appears while a
     * model is resident and greys out on its way back off screen, so it is wired once and left to
     * its own visibility rule.
     */
    private void ensureAiIndicatorController() {
        com.termux.app.statusbar.StatusBarWidgetView ai = findViewById(R.id.terminal_status_widget_ai);
        if (ai == null) return;
        if (mAiIndicatorController == null) {
            mAiIndicatorController = new com.termux.app.statusbar.AiIndicatorController(ai,
                () -> mStatusBar.syncRowDots());
            ai.setOnClickListener(view -> {
                Intent intent = com.termux.app.activities.SettingsDoor.plain(this);
                intent.putExtra(com.termux.app.activities.SettingsActivity.EXTRA_OPEN_TAI_SETTINGS, true);
                startActivity(intent);
            });
        }
        mAiIndicatorController.start();
        mAiIndicatorController.refresh();
    }

    /** The sampling cadence, stretched in lazy mode. */
    private long statsInterval(long normalMs) {
        return isLazyModeEnabled() ? normalMs * STATS_LAZY_MULTIPLIER : normalMs;
    }

    private boolean isLazyModeEnabled() {
        return mPreferences != null && mPreferences.isLazyModeEnabled();
    }

    /**
     * Pushes the lazy-mode toggle to every consumer that caches it — the window bar and the clock;
     * the stats sampler reads {@link #isLazyModeEnabled()} on each cadence instead.
     */
    private void applyLazyMode() {
        boolean lazy = isLazyModeEnabled();
        com.termux.app.terminal.TerminalWindowBar bar = findViewById(R.id.terminal_window_bar);
        if (bar != null) bar.setLazyMode(lazy);
        homeFloatChipBar().setLazyMode(lazy);
        com.termux.app.terminal.TerminalClockWidget clock = findViewById(R.id.terminal_clock_widget);
        if (clock != null) clock.setLazyMode(lazy);
    }

    private int mSeenDirectCpu;
    @Nullable private com.termux.privileged.PrivilegedChoice.Status mSeenBackendStatus;
    private com.termux.app.statusbar.StatusStatNeedsPolicy.Access mSeenGpuAccess =
        com.termux.app.statusbar.StatusStatNeedsPolicy.Access.UNKNOWN;

    private com.termux.app.statusbar.SystemStatsController ensureStatsController() {
        if (mStatsController == null) {
            mStatsController = new com.termux.app.statusbar.SystemStatsController(this, this::onStatsUpdated);
        }
        return mStatsController;
    }

    /**
     * The one callback behind two surfaces with opposite needs. The card is a monitor and gets the raw
     * snapshot at whatever cadence it asked for; the bar is a glance and goes through the smoothers,
     * which repaint it on their own calm rhythm and, in the common case, say "nothing changed" so no
     * view is touched at all.
     */
    private void onStatsUpdated(@NonNull com.termux.app.statusbar.SystemStatsController.Stats stats) {
        long nowMs = android.os.SystemClock.uptimeMillis();
        // What the phone lets the app read decides whether CPU and GPU stand greyed or show; the
        // bar is redrawn once when that is learned, not per sample.
        com.termux.privileged.PrivilegedChoice.Status backendStatus =
            com.termux.privileged.PrivilegedBackendManager.getInstance().currentStatus();
        if (stats.directCpu != mSeenDirectCpu || stats.gpuAccess != mSeenGpuAccess
            || backendStatus != mSeenBackendStatus) {
            mSeenDirectCpu = stats.directCpu;
            mSeenGpuAccess = stats.gpuAccess;
            mSeenBackendStatus = backendStatus;
            mStatusBar.updateStatusWidgets();
        }
        com.termux.app.statusbar.StatusBarWidgetView cpu = findViewById(R.id.terminal_status_widget_cpu);
        com.termux.app.statusbar.StatusBarWidgetView ram = findViewById(R.id.terminal_status_widget_ram);
        // The GPU smoother is fed while the switch is on, shown or not: a hidden widget learns it
        // can show from the first sample that reads a load, and the bar is redrawn once on that
        // change (and when the reading goes away), not per sample.
        if (mPreferences != null && mPreferences.isStatusWidgetGpuEnabled()) {
            com.termux.app.statusbar.StatusBarWidgetView gpu = findViewById(R.id.terminal_status_widget_gpu);
            boolean gpuKnownBefore = mBarGpuSmoother.publishedPercent()
                != com.termux.app.statusbar.StatusBarStatSmoother.UNKNOWN;
            int gpuLoad = stats.hardware != null
                ? stats.hardware.gpuBusyPercent : com.termux.app.statusbar.StatusBarStatSmoother.UNKNOWN;
            boolean gpuChanged = mBarGpuSmoother.offer(gpuLoad, nowMs);
            boolean gpuKnown = mBarGpuSmoother.publishedPercent()
                != com.termux.app.statusbar.StatusBarStatSmoother.UNKNOWN;
            if (gpuKnown != gpuKnownBefore) {
                mStatusBar.updateStatusWidgets();
            } else if (gpuChanged && gpu != null && gpu.getVisibility() == View.VISIBLE) {
                gpu.setValue(mBarGpuSmoother.text());
            }
        }
        // The smoothers feed the bar's widgets, on Home as on a window (#91).
        if (cpu != null && cpu.getVisibility() == View.VISIBLE
            && mBarCpuSmoother.offer(stats.cpuPercent, nowMs)) {
            cpu.setValue(mBarCpuSmoother.text());
        }
        if (ram != null && ram.getVisibility() == View.VISIBLE) {
            int memPct = stats.memTotalKb > 0
                ? (int) Math.round(100.0 * stats.memUsedKb / stats.memTotalKb) : -1;
            if (mBarMemorySmoother.offer(memPct, nowMs)) ram.setValue(mBarMemorySmoother.text());
        }
        if (mStatsCardView != null && mStatusCardHost.isShowing()) {
            mStatsCardView.bind(stats);
        }
        if (mControlBar != null) mControlBar.onStats(stats, nowMs);
    }

    private void toggleStatsCard(@NonNull View anchor) {
        if (mStatusCardHost.isShowing()) {
            // Keyed on the card, not the tapped widget: CPU and RAM both open this one card.
            boolean same = mStatusCardHost.isShowingContent(mStatsCardView);
            mStatusCardHost.dismiss();
            if (same) return;
        }
        if (mStatsCardView == null) {
            mStatsCardView = new com.termux.app.statusbar.SystemStatsCardView(this);
        }
        detachFromParent(mStatsCardView);
        mStatsCardView.bind(ensureStatsController().latest());
        ensureStatsController().start(statsInterval(STATS_CARD_INTERVAL_MS), true, true);
        setWidgetAccent(anchor, true);
        mStatusCardHost.setDropEdge(findViewById(R.id.terminal_window_bar_host));
        mStatusCardHost.setEdge(mStatusBar.statusBarEdge());
        mStatusCardHost.show(anchor, mStatsCardView, mStatusBar.statusCardStyleProvider(), () -> {
            setWidgetAccent(anchor, false);
            if (mStatsController != null
                && mPreferences != null
                && (mPreferences.isStatusWidgetCpuEnabled() || mPreferences.isStatusWidgetRamEnabled()
                    || mPreferences.isStatusWidgetGpuEnabled())) {
                mStatsController.start(statsInterval(STATS_BAR_INTERVAL_MS), false,
                    mPreferences.isStatusWidgetGpuEnabled());
            }
        });
    }

